pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the smallest
    // plausible item are pure waste — penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal
        score -= 200.0;
    } else {
        // Penalize large leftover gaps less than tiny unusable ones,
        // scaled by how "dead" the gap is (gap that nothing fits into).
        let dead = (post_residual < 20) as f64 * 60.0
            + (post_residual < 35) as f64 * 25.0;
        score += dead;
    }

    // Lookahead: if the next item fits into the post_residual, reward this bin;
    // if it nearly fits, mildly penalize for wasting the chance.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
        } else if next_item_size <= bin_residual {
            // next item would fit this bin but not after this placement
            score += 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, prefer tightening existing bins
    // rather than spreading; with few bins, mild preference to fill.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 8.0;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderate score.
        score = 50.0 + pressure * 8.0;
        if post_residual < 15 {
            // small item into a fresh bin wastes the bin — penalize
            score += 100.0;
        }
        if fitting_bins_count == 1 {
            score -= 60.0; // still prefer reusing the last fitting bin
        }
    }

    // Stream progression: early on, be more conservative with new bins;
    // late in the stream, allow tighter packing aggression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (post_residual == 0 as u32 as bool) as u8 as f64;

    // Mean-residual coupling: if open bins are already loose on average,
    // prefer filling them (lower score for bins below mean residual usage).
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot fit even the smallest plausible item (<= ~10)
    // is pure waste; scale penalty by how "stuck" the gap is.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0; // hard penalty for near-dead space
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 6.0; // soft penalty for tight gaps
    }

    // Nonlinear dead-space penalty: gaps that cannot fit the lookahead item
    // are likely dead; penalize proportionally to the shortfall.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (favor small post_residual relatively more).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make the empty bin moderately attractive only when
    // the current fit is bad (large post_residual) or no bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        score += 60.0 - 120.0 * bad_fit; // low score only if item is small in empty bin
        if post_residual > 40 {
            score -= 70.0; // poor fit elsewhere: opening a new bin is fine
        }
    }

    // Mild lookahead synergy: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any future item
    // (items are 1..100, so treat very small gaps as near-wasted, but keep a
    // gradient so the tightest fit still wins).
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr <= 10.0 {
            // Unusable sliver: strong penalty on top of the base value.
            score += (11.0 - pr) * 8.0;
        } else if pr <= 25.0 {
            // Likely unusable for most items: moderate penalty.
            score += (25.0 - pr) * 2.5;
        }
    }

    // Reward exact / near-exact fits (post_residual == 0 is a perfect close).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: mildly discourage spreading across many open bins
    // so we consolidate into existing bins rather than fragmenting.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has no dead-space risk yet.
    // Make it attractive only when no open bin offers a good fit, i.e. when
    // the item would leave a large awkward gap in the best existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales slightly with stream position
        // (late in the stream, consolidation matters a bit more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 20.0 * progress;
        // If lookahead item could use the leftover of a fresh bin placement,
        // opening a new bin is slightly more attractive.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
        // With very few open bins, prefer opening a new one less harshly.
        if open_bins_count <= 2 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if placing here leaves exactly the space the next
    // item needs, reward it (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible
    // follow-up item are pure waste — penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Squared dead-space term: moderate gaps are also increasingly costly.
    score += (post_residual as f64).powi(2) / 100.0;

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when the fit
    // into open bins is bad (large post_residual or dead space).
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score = 30.0 + fit_quality * 50.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory
        }
    }

    // Mild stream-progression damping.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically relative to capacity.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 8.0 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Post-residual fits next item: reward.
            score -= 4.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += crowd * (post_residual as f64) * 0.05;

    // New-bin candidate: only attractive when mean residual is low (existing bins nearly full)
    // or the item leaves a very usable residual in a fresh bin.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - (post_residual as f64);
        let new_bin_bonus = 30.0 * (1.0 - mean_residual / cap) - 10.0 * progress;
        score -= new_bin_bonus;
        // Opening a new bin for a large item is fine; for small items it wastes space.
        score += (item_size as f64) * 0.1;
        let _ = mean_gap;
    }

    // Prefer bins whose residual is close to the item (waste minimization).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * fit_gap * fit_gap;

    // Late in stream, tighten packing: punish large residuals more.
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10, the minimum item size) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Slightly-larger-but-still-awkward gaps are partially wasted too.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placing item so that the next item can still fit in the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if next item almost fits but not quite (near-dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer existing bins when bin count is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below mean (filling emptier-of-space bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for tight fits overall.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // New-bin candidate: make it attractive only when item is large (little waste)
    // and existing bins are crowded; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0;
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        score += open_bins_count as f64 * -0.3;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0; // new bin would create awkward gap for next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual tightly matches the item (best-fit sharpening).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Slight preference for keeping mean residual high (avoid fragmenting full bins).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.8 + mean_residual * 0.05;
        score -= pressure;
        if post_residual < 25 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Larger leftover space is mildly rewarded (still usable).
        score -= 0.3 * (post_residual as f64);
    }

    // Pressure from number of open bins: prefer filling existing bins
    // when many are open; prefer new bins when few are open.
    score += 4.0 * (open_bins_count as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when
    // mean residual across open bins is small (they are nearly full).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if mean_r < 15.0 {
            score -= 50.0; // open bins nearly full -> prefer new bin
        } else {
            score += 40.0 + mean_r; // discourage wasting fresh bins
        }
    }

    // Lookahead: if the next item would fit the post-residual exactly-ish,
    // reward leaving that gap; if post-residual is too small for the next
    // item but nonzero, penalize (dead space for the near future).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= n && pr - n < 10.0 {
            score -= 30.0; // next item nearly fills this bin perfectly
        } else if pr > 0.0 && pr < n {
            score += 15.0; // leftover can't fit next item
        }
    }

    // Late in the stream, tighten up: avoid opening bins near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress > 0.9 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals in "usable" classes.
    // Class A: post_residual divisible by 10 (clean slots) -> strong reward.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 5 -> mild reward.
    else if post_residual % 5 == 0 {
        score -= 2.5;
    }
    // Small unusable dead space (post_residual < 10) -> penalize unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division threshold: residual "quanta" of size 10.
    let quanta = post_residual / 10;
    score -= quanta as f64 * 1.5;

    // Perfect fit is best.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: strong reward, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.05 * slack;
            // Harmonic bonus: next item exactly fills a class boundary.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here: penalize more if we waste a lot.
            score += 2.0;
            if post_residual < 10 {
                score += 4.0; // bin becomes dead anyway
            }
        }
    } else {
        // Last item: prefer exact fill.
        if post_residual == 0 { score -= 10.0; }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: make it attractive only when item is large relative to
    // mean residual or open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 20.0 + item_size as f64 * 0.15 - congestion * 2.0 - progress * 3.0;
        // Harmonic: large items starting fresh bins is good.
        if item_size % 10 == 0 { score -= 2.0; }
        if item_size >= 50 { score -= 3.0; }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a plausible
    // item are heavily penalized (items are >= 1, but small gaps < 12 are nearly
    // unusable in practice; gaps below next_item_size are dead for the lookahead).
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 4.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward tight relative fit (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * (0.5 + progress);

    // New-bin candidate: only attractive when this item is huge relative to
    // typical residuals or no good fits exist.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 0.0 && fitting_bins_count > 1 {
            score += 12.0 + mean_gap * 0.3;
        } else {
            score += 3.0;
        }
        // Late in the stream, keep consolidating into open bins.
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure loss; penalize gaps that can never be filled by any plausible item.
    let dead_threshold = 10.0f64; // below this, gap is likely unusable
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize mid-range dead space that only fits tiny items: quadratic blowup
    // on gaps in (10..=20] which are awkward for future items.
    if post_residual > 0 && post_residual <= 20 {
        score += 8.0 * (21.0 - post_residual as f64);
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item is large and residual barely
    // covers it, keep the bin attractive; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 4.0 * (next_item_size - post_residual) as f64;
        } else {
            score += 1.5 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins) to keep a pool of large residuals for big items.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Slight preference to fill bins as the stream progresses (avoid leftover sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // New-bin candidate: make empty bins mildly attractive only when it is a
    // genuinely bad fit elsewhere; penalize default new-bin choice.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits (post_residual == next_item_size)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward leaving room for the next item with some slack
            score -= 8.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Penalize dead space smaller than the next item
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare post_residual relative to mean residual: prefer bins that tighten the spread
    score -= 2.0 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer fuller bins as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the minimum plausible item size is wasted.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 30.0;

    // Penalize leaving residuals that no typical item can use efficiently
    // (very small residuals are dead space unless nearly zero).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // creates stranded space relative to lookahead
        }
        // Perfect chain: this + next item exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 12.0;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer bins already below mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Time horizon: late in the stream, discourage opening new bins
    // (fewer chances to fill them), encourage using existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive early or when open bins are crowded.
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 5.0 + progress * 20.0 - crowding * 2.0;
        if item_size >= 70 {
            score -= 6.0; // huge items fit fine in a fresh bin
        }
    } else {
        score -= progress * 4.0;
    }

    // Mild penalty on too many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (nonlinear).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits.
    score -= 8.0 * (item_size as f64 / bin_residual as f64);

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: penalize leaving large slack.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in stream, prefer consolidating (favor existing bins);
    // late in stream, slack matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.3 * progress;

    // Many open bins: discourage spreading; few bins: cheaper to open new ones.
    score += 0.5 * open_bins_count as f64;
    score += 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it attractive only when current bin's post-fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; offset by how badly existing bins would fit.
        score = 55.0 + 0.3 * mean_residual - 0.4 * item_size as f64;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity - 1) {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: small unusable gaps are the worst outcome ---
    if post_residual > 0 {
        if post_residual <= 10 {
            // tiny gap: nearly always dead space -> heavy penalty
            score += (11.0 - post_residual as f64) * 60.0;
        } else if post_residual <= 20 {
            // small gap: likely dead unless a tiny item arrives
            score += (21.0 - post_residual as f64) * 12.0;
        } else if post_residual >= 30 && post_residual <= 60 {
            // mid gap: reusable by the broadest item range -> mild reward
            score -= 15.0;
        } else if post_residual >= 61 {
            // large residual: flexible, but wasteful if item was small
            score -= 5.0;
        }
    } else {
        // perfect fit: maximal reward
        score -= 200.0;
    }

    // --- Tightness reward: fraction of bin consumed by this placement ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // --- Last-chance pressure: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // base cost of opening a bin; acceptable only if fits elsewhere are bad
        score += 40.0;
        // opening a fresh bin is attractive early (many future items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 55.0;
        // many open bins -> discourage opening even more
        score += (open_bins_count as f64).min(20.0) * 4.0;
    }

    // --- Open-bins pressure: prefer reusing bins when many are open ---
    score += (open_bins_count as f64).min(15.0) * 1.5;

    // --- Lookahead (k=2): reward bins whose post_residual matches next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 90.0; // next item fits almost perfectly
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the known next item
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // --- Mean-residual coupling: avoid leaving this bin far from the pack average ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can no longer fit the
    // minimum item (1) are pure waste, but residuals that are small enough
    // to be "hard to fill" (below typical item scale) are the real killers.
    // Penalize tiny-but-nonzero residuals super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 20.0 {
            // small gap: likely dead space, punish quadratically
            score += (20.0 - pr) * (20.0 - pr) * 0.35;
        } else if pr <= 50.0 {
            // mid gap: mildly awkward
            score += (50.0 - pr) * 0.4;
        } else {
            // large residual is reusable; reward keeping big usable space
            score -= 12.0;
        }
    } else {
        // perfect fill
        score -= 30.0;
    }

    // Reward exact-ish fits relative to bin residual (tight packing signal).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourages closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress) * 0.6;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the average (keeps the fleet homogeneous and predictable).
    score += (bin_residual as f64 - mean_residual).abs() * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item would be blocked by this placement, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how snugly the next item fits the leftover
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + snug * 15.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when no open bin offers a decent fit, by anchoring
    // its score near a moderate value.
    if bin_residual == bin_capacity {
        // base anchor: slightly worse than a good fit, better than a bad one
        score = 55.0 + (open_bins_count as f64) * 0.3;
        // if nothing else fits, new bin must win
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // late in the stream, be more willing to open fresh bins
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item size (1) are worthless; the smaller the gap, the worse.
    if post_residual > 0 {
        // Non-linear dead-space penalty: quadratic in unusable fraction.
        let dead = 1.0 - (post_residual as f64 / bin_capacity as f64).max(0.0);
        score += 40.0 * dead * dead;

        // Hard penalty for gaps below the smallest plausible item (1..=3):
        // treat them as fully dead.
        if post_residual <= 3 {
            score += 60.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward residuals that exactly fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual cannot fit the next item (dead for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via its large post_residual,
    // but add explicit pressure scaled by open bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (0.5 + progress);

    // Prefer bins tighter than the mean residual (best-fit coupling).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (small gaps that few items can ever fill) are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (post residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is highly desirable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Partially usable residual is fine; penalize only mild waste.
            score -= 5.0;
        } else {
            // Next item cannot use the residual: it becomes dead space.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins
    // are crowded and the current fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        score += 20.0 - pressure * 5.0;
        if (item_size as f64) > mean_residual * 0.9 && open_bins_count > 2 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // (higher utilization) rather than spreading items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    // Slight preference for bins with residual close to the item (tight fit).
    score += (bin_residual - item_size) as f64 * 0.1;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already well packed; reward finishing it off.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny leftover gaps are almost unusable
    // (items are 1..100, but small gaps < 20 rarely help).
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 - (post_residual as f64) * 2.0; // smaller gap => worse
    }

    // Reward tight fits (post_residual near zero but not in dead zone).
    if post_residual <= bin_residual / 4 {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer consolidating into
    // existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // this placement is perfect.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover space can't host next item: mild penalty if gap is small
        if post_residual < next_item_size && post_residual < 35 {
            score += 10.0;
        }
    }

    // New-bin candidate (empty bin): make it attractive only when the
    // item is large relative to capacity or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = if item_size >= 50 { 25.0 } else { 0.0 };
        score -= 30.0 + large_item_bonus + progress * 20.0;
        // But if an existing bin fits well, this should lose:
        // add back a term proportional to item size (new bin wastes space).
        score += item_size as f64 * 0.3;
    }

    // Slight nudge using mean residual: bins deviating far below mean
    // residual are "hole" bins; filling them is good.
    let deviation = mean_residual - bin_residual as f64;
    if deviation > 0.0 {
        score -= deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful
    // (below the smallest plausible item size ~10, or below next item).
    let min_useful = if next_item_size > 0 { next_item_size.min(30) } else { 10 } as f64;
    if (post_residual as f64) < min_useful {
        score += 25.0 * (min_useful - post_residual as f64);
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.35 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize blocking the next item slightly, scaled by how close we are.
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (1.0 - (gap / (bin_capacity as f64)).min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: make empty bins moderately attractive so
    // we don't force awful fits, but not so attractive that we never reuse.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = (open_bins_count as f64).ln().max(0.0);
        // Opening new bins is cheaper early and when many bins are already open
        // relative to mean residual (fragmentation pressure).
        let frag = (mean_residual - post_residual as f64) / (bin_capacity as f64);
        score += 55.0 - 25.0 * progress - 8.0 * crowd + 30.0 * frag.max(0.0);
        // Large items prefer fresh bins (avoid splitting awkwardly).
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate fragmented space into predictable buckets).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Slight time-dependent aggression: late in the stream, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 6.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
    score += 0.05 * crowding * (1.0 - progress);

    // Penalize bins far from the mean residual (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight bias toward fuller bins (smaller residual).
    score += 0.1 * bin_residual as f64 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > (bin_capacity as f64 - item_size as f64);
        score += if bad_fit { 5.0 } else { 20.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into the post-residual: strong reward, scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack.min(50.0);
    }
    // Next item does NOT fit: penalize proportionally to wasted lookahead space.
    else if next_item_size > 0 {
        let overflow = (next_item_size - post_residual) as f64;
        score += overflow * 2.0;
    }

    // Reward tight fits relative to bin capacity (small dead space fraction).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize creating residual far below the mean residual (fragmenting space).
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += (-dev) * 0.5;
    } else {
        score -= dev * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Early in the stream, be more willing to open fresh bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        // Mild penalty per open bin to discourage bin proliferation.
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    }
    // Next item fits into post_residual: mild reward proportional to tightness.
    if next_item_size > 0 && next_item_size < post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit in the leftover: penalize small dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 40.0 * (1.0 - dead / bin_capacity as f64) * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is already below average (tighter bins first).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Early in the stream, keep bins consolidated; late, avoid tiny leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize very small unusable leftovers (dead space) generally.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    // -> both items pack perfectly, strongly reward.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item fits with leftover; penalize proportionally to leftover
            let leftover = (post_residual - next_item_size) as f64;
            score += leftover * 0.4;
        } else {
            // next item won't fit here after this placement; mild penalty scaled
            // by how much of the next item overflows
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.15;
        }
    } else {
        // Last item: prefer tightest fit only
        score -= 10.0;
    }

    // Reward bins whose residual is small relative to the mean (tight bins get used,
    // large-residual bins stay flexible).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (post_residual very small is good).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (item_size as f64 / bin_capacity as f64) * 8.0;
    }

    // Strong penalty for creating dead space (small unusable leftover, e.g. 1..=3)
    if post_residual >= 1 && post_residual <= 3 {
        score += 20.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * 20.0 / (mean_residual + 1.0);
        // Prefer reusing bins early; allow new bins when mean residual is low or many bins
        score += 30.0 - crowded * 0.5 - progress * 10.0;
        // If next item is large and current item leaves big gap, new bin is fine
        if next_item_size >= 60 && item_size >= 60 {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins with high fill ratio
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Pull toward the mean residual: prefer bins whose residual is near average
    // (balanced packing), penalize outliers.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item would fit in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual is dead space for the next item: penalize proportionally.
        score += 0.2 * post_residual as f64;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., current item is large relative to mean residual and spread is wide).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 }
            else if item_size as f64 > mean_residual + 20.0 { 0.6 }
            else { 0.0 };
        score = bin_capacity as f64 - 80.0 * desperation + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits (small but usable-ish residuals) mildly.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 30.0;

    // Penalize leaving a gap that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: only attractive when residuals are large/wasted.
    if bin_residual == bin_capacity {
        let avg_dead = mean_residual - post_residual as f64;
        score = bin_capacity as f64 * 0.55 - avg_dead * 0.2;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is already good; amplify non-linearity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (next_item_size - post_residual) as f64;
    }

    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage unless current fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Penalize new bins; relax penalty late in stream or when no bin fits.
        score += 40.0 * (1.0 - poor_fits) * (1.0 - 0.5 * progress);
        // If mean residual is high, open bins are fragmented; new bin is fine.
        score -= 0.2 * mean_residual;
    }

    // Mild penalty for large post-residuals that are awkward (small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference for filling bins with more residual than the mean
    // (balance load across open bins, keep some bins tight for big items).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, huge reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tight the fit is
            score -= 150.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving large unusable gaps
            score += 40.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Penalize small post_residuals that are likely dead space relative to item range
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: prefer bins whose residual deviates favorably
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize so we only open when fits are truly bad
    if bin_residual == bin_capacity {
        score += 200.0;
        // But if nothing fits well elsewhere, opening may still win via lookahead
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 50.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how poor current fits are.
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        let mut new_bin_score = 55.0 + open_bins_count as f64 * 2.0;
        // If existing bins would leave large dead space, opening a fresh bin is better.
        new_bin_score -= mean_gap * 0.8;
        // Lookahead: if next item matches the post-residual of this bin, avoid new bin.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 20.0;
            new_bin_score += 15.0;
        }
        // If next item would fit the new bin's full capacity nicely, mild bonus.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score);
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // (packing into below-average-residual bins keeps large gaps available).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 4.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize leaving residual that cannot fit the next item if next item exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward residual that can accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Slightly favor bins tighter than the mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * (-0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (<= 10, or < next item) are wasted space.
    let min_item = 10u32;
    if post_residual < min_item {
        score -= 60.0; // perfect-ish fill, dead space unusable anyway
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual can't host the lookahead item: dead space for the horizon
        score += (post_residual as f64) * 1.5;
    } else {
        // usable residual: reward proportionally
        score -= (post_residual as f64) * 0.4;
    }

    // Tight-fit reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Open-bin pressure: prefer spreading when many bins are open,
    // prefer consolidation (new bin) when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (4.0 + 6.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty so among multiple candidates the best-fit wins via post_residual
        score += 2.0;
    }

    // New-bin candidate adjustment: an empty bin has huge residual; make it
    // attractive only when mean residual of open bins is very low or the
    // item is large and would leave a bad gap elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let gap_penalty = (mean_residual - post_residual as f64).max(0.0);
        score -= gap_penalty * 0.8;
        if item_size >= 60 {
            score -= 10.0; // large items fit anywhere; prefer fresh bin to keep small gaps
        }
    }

    // Mean-residual coupling: if this bin is far below the mean residual,
    // it is the "driest" bin; prefer filling driest bins first.
    let dryness = mean_residual - bin_residual as f64;
    score += dryness * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the residual left behind.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Next item fits exactly or nearly: reward tight coupling.
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 300.0;
            } else {
                score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize leaving residual that is
            // too small to be useful (dead space trap).
            score += 40.0 * (1.0 - pr / nxt);
        }
    }

    // Penalize small unusable residuals relative to mean residual.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.5 {
        score += 30.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residuals
    // of open bins are all poor (large post_residual penalty above handles it).
    if bin_residual == bin_capacity {
        score += 50.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * pr / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = (next_item_size as f64).min(cap);
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let open = open_bins_count as f64;
    let fits = fitting_bins_count as f64;
    let fill = (item_size as f64 / cap).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Convex waste term: strongly prefer tight placements.
    let mut score = post + 0.30 * post * post / cap;

    // Closing a bin completely is highly desirable.
    if post_residual == 0 {
        score -= 8.0 + 4.0 * progress + 0.10 * open + 2.0 * fill;
    }

    // Penalize residuals too small for the lookahead item; the penalty is
    // larger when the next item is large, because the replacement bin would
    // otherwise have little leftover room.
    if post_residual > 0 && next > 0.0 && post < next {
        let missing = next - post;
        let next_ratio = next / cap;

        score += missing * (2.0 + 3.0 * progress) * (1.0 + 0.02 * open)
            + next_ratio * (30.0 + 20.0 * progress)
            + 0.03 * missing * missing;
    } else if post_residual > 0 && next > 0.0 && post >= next {
        // Reward leaving a residual that can still absorb the next item.
        score -= 2.0 + 2.0 * progress + 2.0 * (next / cap);
    }

    if !is_new_bin {
        // General pressure toward using already-open bins.
        score -= 0.8 + 0.08 * open;

        // Last fitting bin: avoid opening a new bin unless the fit is terrible.
        if fitting_bins_count <= 1 {
            score -= 3.0 + 2.0 * progress + 0.08 * open;
        }
    } else {
        let fitting_pressure = if fitting_bins_count > 0 {
            4.0 + 1.2 * fits.sqrt()
        } else {
            0.0
        };

        score += 8.0
            + fitting_pressure
            + (1.0 - fill) * 6.0
            + open * (0.45 + 0.55 * progress)
            + 0.04 * mean_residual.max(0.0);

        // If any open bin fits, a new bin is dominated when it cannot absorb
        // the lookahead item, or when there is no lookahead item left.
        if fitting_bins_count > 0 && (next_item_size == 0 || post < next) {
            score += 1.0e9;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual in (0, 10) is wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that cannot fit the smallest plausible item (1..=100 range).
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward residual that exactly fits the next item (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.3;
    }

    // Mild progression scaling: tighten packing as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (tighter bins first keeps loose bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Near-match: next item fits with small slack -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 60.0 - (post_residual - next_item_size) as f64 * 3.0;
    }

    // Penalize leaving a residual that is too small for typical items (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Small dead space (< 10) is nearly unusable: strong penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Last-chance bin: if only one bin fits, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when existing bins fit poorly
    // (large post_residual relative to mean) or many bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual + 15.0;
        if poor_fit || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 35.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Slight preference for tighter bins relative to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress
    let progress_w = 8.0 * t * (1.0 - t) + 2.0 * t * t;
    score += progress_w * 20.0 * pr_norm * pr_norm;

    // Penalize residuals too small for the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (next_norm - pr_norm).max(0.0);
        score += 15.0 * gap * gap * cap;
        // Reward residuals that still fit the next item
        let fit_bonus = (1.0 - (pr_norm - next_norm)).max(0.0);
        score -= 10.0 * fit_bonus * pr_norm * (1.0 - t);
    }

    // Reward tight fits (small post_residual relative to item)
    score -= 12.0 * item_norm * (1.0 - pr_norm);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // New-bin candidate: prefer it only when post_residual is large and bins are many
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 18.0 * openness * (1.0 - item_norm) * (1.0 + t);
        score -= 5.0 * (1.0 - openness);
    }

    // Mild attraction toward bins whose residual is close to the mean (balance)
    let dev = (pr_norm - mean_norm).abs();
    score += 6.0 * dev * dev * cap * (0.5 + 0.5 * t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Exact chain: item fills residual now, next item fills the remainder.
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        }
    }

    // Reward tight fits now (small dead space relative to capacity).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize creating unusable slivers (post residual small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (consolidate space).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: keep it expensive, but cheaper late in the stream
    // or when many bins are open (accepting poor fits becomes costly).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress - 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_gain = norm_pr * (1.0 + 2.0 * t * (1.0 - t) * 4.0);
    score -= progress_gain * cap * 0.35;

    // Penalize unusable dead space (residual too small for typical future items)
    let dead = (1.0 - norm_pr).powi(3);
    score += dead * cap * 0.5 * (0.5 + 0.5 * t);

    // Reward tight fits: low post_residual relative to item
    score -= (norm_item - norm_pr).abs() * cap * 0.2;

    // Lookahead coupling: reward residual that can fit the next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fits_next * norm_next * cap * 0.4;
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= cap * 0.3 * (1.0 - t * 0.5);
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 10.0 * t;

    // Pull toward mean residual: prefer bins with residual near the average
    score += ((mean_residual - pr) / cap).abs() * cap * 0.1;

    score
}

