    score += 5.0 * (mean_residual - pr) / cap;

    // Crowding: many open bins -> discourage spreading, favor filling existing ones.
    score += 2.0 * (open_bins_count as f64).sqrt() * norm_pr;

    // New-bin candidate penalty: opening a fresh bin is only attractive when the item
    // is large relative to capacity and stream is early.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 20.0 - 25.0 * item_frac * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class are rewarded, dead-space classes penalized. ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: post_residual divisible by common item granularities (10, 20, 25)
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 12.0; // leftover likely reusable by future items
    }

    // Class 2: tiny dead space (1..=5) is nearly unusable -> penalize
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    // Class 3: awkward middle leftovers via integer division thresholds
    let q = post_residual / 10; // decade class of the leftover
    match q {
        0 => {
            if post_residual > 0 { score += 8.0; } // 1..9: dead space
        }
        1 | 2 => { score += 4.0; }   // 10..29: mediocre
        3 | 4 => { score -= 6.0; }   // 30..49: good (fits mid-size items)
        _ => { score -= 3.0; }       // 50+: large leftover, fine but not tight
    }

    // Tight fit reward: leftover is a small fraction of capacity
    let frac = post / cap;
    if post_residual > 0 && frac < 0.15 {
        score -= 10.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host the next item: harmonic match reward
            score -= 14.0;
            // extra reward if leftover is exactly/nearly the next item size
            let gap = post_residual - next_item_size;
            if gap <= 5 { score -= 8.0; }
        } else {
            // leftover cannot host next item: mild penalty scaled by how close
            let miss = (next_item_size - post_residual) as f64;
            score += (miss / 20.0).min(10.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 30.0;
        // but if existing bins are fragmented (high mean residual spread),
        // opening fresh is less bad
        let fragmentation = (mean_residual - post).abs();
        if mean_residual < 25.0 {
            score -= 10.0; // open bins are nearly full anyway
        }
        let _ = fragmentation;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Prefer bins whose residual is far below the mean (concentrate waste)
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.1;
    }

    // Slight preference for bins among many fitting options to reduce bin count
    if fitting_bins_count > 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are dead weight. Penalize the "unusable band".
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal zone: mildly discouraged unless next item fits it.
        score += 3.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Reward bins whose residual accommodates the lookahead item (k=2).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Lookahead won't fit here: this placement may strand space.
        score += 2.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than spreading out.
    let open_pressure = open_bins_count as f64;
    if bin_residual < bin_capacity {
        score -= 0.05 * open_pressure;
    } else {
        // New-bin candidate: penalize proportionally to how many bins are
        // already open, so we only open when the fit elsewhere is truly bad.
        score += 0.08 * open_pressure;
    }

    // Relative waste vs. mean residual: placing into a bin with large
    // residual when the mean is low suggests a poor match.
    let rel_waste = post_residual as f64 - mean_residual;
    score += 0.3 * rel_w.max(0.0) * 0.0; // placeholder zeroed
    score += 0.15 * rel_waste.max(0.0);

    // Tightness bonus: reward small positive residuals relative to item size.
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 2.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 0.5;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 100.0; // perfect chain: next item fills this bin exactly
        } else {
            score += gap * 0.6; // penalize mismatch between leftover and next item
        }
        // bonus if next item still fits into post_residual
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: minimize leftover hard
        score += post_residual as f64 * 0.2;
    }

    // Compare against mean residual: avoid dumping items into already-tight bins
    // unless the fit is very good; encourage using bins with large residuals
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in stream or when
    // current item is huge and no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 40.0;
        if progress < 0.15 || (poor_fit && next_item_size > post_residual) {
            score -= 20.0;
        } else {
            score += 15.0; // prefer existing bins mid/late stream
        }
    }

    // Slight preference for bins with more residual among similar fits
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: leftover space that cannot hold a typical item.
    if post_residual < 10 {
        score -= 25.0; // perfect closure
    } else if post_residual < 30 {
        score += 0.35 * (30.0 - post_residual as f64); // awkward leftover
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 0.15 * next_item_size as f64;
        } else {
            score += 0.10 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let late_game = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 100.0
            + 0.5 * pressure
            - 20.0 * fragmentation / (bin_capacity as f64)
            - 10.0 * late_game
            - (if next_item_size > 0 && next_item_size <= bin_capacity { next_item_size as f64 * 0.1 } else { 0.0 });
        // Never beat a decent existing fit.
        if fitting_bins_count > 0 && fit_ratio > 0.5 {
            score += 60.0;
        }
    }

    // Mild global balance: prefer bins below mean residual (consolidating emptier bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time horizon: early on, be conservative with tight fits (keep flexibility);
    // late, close bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling: post_residual shaped by stream progress
    let shape = 1.0 + 2.0 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 30.0 * x * x * shape;

    // Penalize residuals that neither fit the lookahead item nor stay useful
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 8.0 * (gap / cap) * (gap / cap) * 100.0 * (0.5 + 0.5 * progress);
        // Reward exact-ish fit for the next item
        score -= 12.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    }

    // Last-chance bonus: strongly favor using a scarce fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - x);
    }

    // Penalize opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 25.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 5.0 * (1.0 - x) * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes are rewarded (waste minimization).
    let pr = post_residual;
    let residue_class = pr % 10; // fine-grained harmonic class
    let coarse_class = pr / 10;  // decade class (0..=9)

    // Penalize residues in awkward classes (too small to fit min item =1,
    // but awkward for typical sizes). Reward exact harmonics of capacity fractions.
    if pr == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if pr <= 5 {
        score -= 15.0; // near-perfect, tiny dead space
    } else {
        // dead-space penalty grows for residues that can't hold common items
        if pr < 10 {
            score += 20.0; // unusable sliver
        } else if residue_class == 0 {
            score -= 6.0; // decade-aligned residual is reusable
        }
    }

    // Coupling with next item: lookahead harmonic matching
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) >= nxt {
            // can the residue also host the next item exactly (harmonic)?
            let slack = pr as f64 - nxt;
            if slack == 0.0 {
                score -= 30.0; // chain of perfect fits
            } else if (slack as u32) % 10 == 0 {
                score -= 10.0; // harmonic slack
            } else {
                score -= 5.0 * (1.0 - slack / cap);
            }
        } else {
            // next item won't fit here; penalize less if residue tiny
            score += 8.0 * (1.0 - pr as f64 / cap);
        }
    } else {
        // last item: just prefer tight fits
        score -= 10.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Fraction-of-capacity coupling: prefer bins whose fill ratio is high
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= 12.0 * fill_ratio;

    // Mean-residual divergence: avoid bins far from the fleet mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make opening a new bin costly unless current bins are poor
    if bin_residual == bin_capacity {
        score += 55.0;
        // but late in the stream with many open bins, fresh bins are fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) > cap * 0.5 {
            score -= 10.0; // big next item: fresh bin is strategic
        }
    }

    // Coarse class micro-adjustment: mid-range residues (20-40) are versatile
    if (10..=40).contains(&pr) {
        score -= 3.0 * coarse_class as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future
    // items are the worst outcome. Penalize small non-zero post_residual hard.
    let min_useful = 10u32; // smallest possible item footprint
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // nearly dead space
    } else if post_residual < 35 {
        score += 8.0; // tight fit, mildly risky
    } else {
        // Larger usable residual is fine; slightly reward roominess.
        score -= 5.0;
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fitting the next item exactly into the created gap (lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap can still host the lookahead item: keep this bin attractive.
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap cannot host lookahead: it is likely to become dead space.
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> encourage consolidation into
    // existing bins rather than spreading.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: an empty bin has full residual. Only make
    // it attractive when the current item is large and fits poorly elsewhere;
    // otherwise keep it suppressed so existing bins get used first.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress and
        // number of already open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 30.0 * progress + (open_bins_count as f64) * 2.0;
        // Large items (>= 60) justify a fresh bin more readily.
        if item_size >= 60 {
            score -= 35.0;
        }
        // If the item leaves a big residual, the new bin stays useful.
        if post_residual >= 40 {
            score -= 10.0;
        }
    }

    // Mild tie-breaker: prefer bins whose residual deviates favorably from
    // the mean (filling the emptiest bins first reduces fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: strongly reward bins where the NEXT item also fits
    // into the resulting residual (perfect chain match).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: reward proportionally to how well next item fills remainder.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.25 * chain_waste;
            // Extra bonus for an exact two-item completion of the bin.
            if chain_waste == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize dead space that is too small
            // to be useful for typical future items, scaled by stream progress.
            let progress = step_index as f64 / total_items.max(1) as f64;
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += (10.0 - dead) * (1.0 + progress);
            }
        }
    } else {
        // Last item: just minimize waste (already base term).
    }

    // Relative-to-mean coupling: bins with residual near/below mean are
    // "aged" bins; filling them is good, leaving them is bad.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 5.0 * (mean_residual - resid_f) / (bin_capacity as f64);
    } else {
        score += 2.0 * (resid_f - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin mildly so tight fits
    // in open bins win, but let it win when open-bin post_residual is huge.
    if bin_residual == bin_capacity {
        // Fresh bin: score = its post_residual (capacity - item) plus a
        // fixed opening cost; opening cost shrinks late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 10.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 8.0;
        }
    } else {
        // Existing bin with a big leftover after placement is unattractive
        // relative to a fresh bin unless it chains with the next item.
        if post_residual > 60 && !(next_item_size > 0 && next_item_size <= post_residual) {
            score += 10.0;
        }
    }

    // Mild penalty for creating many open bins early (bin proliferation).
    if open_bins_count > 4 && post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let size = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight packing).
    let mut score = post;

    // Strong reward for near-perfect fits (waste < 10).
    if post_residual < 10 {
        score -= 60.0 * (1.0 - post / 10.0);
    }

    // Penalize dead space relative to mean residual: leaving more than the
    // average slack is worse than average; leaving very little is good.
    score += 0.35 * (post - mean_residual);

    // Penalize creating residuals too small for typical future items
    // (unusable sliver). Scale penalty by how close post is to the floor.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - post / 20.0);
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            // Penalize blocking the next item's best fit.
            score += 8.0 * (1.0 - post / (next_item_size as f64));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is justified only when
    // existing residuals are large relative to the item (poor fits elsewhere)
    // or many bins are already open (fragmentation).
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - size).max(0.0);
        let fragmentation = (open_bins_count as f64).ln().max(0.0);
        let justify = 20.0 + 0.5 * avg_fit_gap + 4.0 * fragmentation;
        // Early in the stream, prefer filling existing bins; later, allow more opening.
        let horizon = 15.0 * t;
        score += justify - horizon;
        // Never open a new bin when a perfect fit exists elsewhere is handled
        // by that bin's low score; add mild floor penalty.
        score += 5.0;
    }

    // Mild preference for filling bins with larger residuals early on
    // (best-fit-with-lookahead hybrid), fading over time.
    score -= (1.0 - t) * 0.1 * (resid - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty on wasted space.
    let mut score = pr as f64;

    // Non-linear waste penalty: dead space grows quadratically for small residuals.
    score += 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_pr;

    // Smooth coupling with stream progress: later in stream, prefer tighter fills more strongly.
    let t = progress * progress;
    score -= 25.0 * t * norm_pr * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor the only fitting bin, scaled smoothly by progress.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Mild penalty when many bins are open (discourage spreading).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let room = norm_pr - n / cap;
        if room < 0.0 {
            score += 12.0 * (-room) * (1.0 + progress);
        } else {
            score -= 6.0 * room * (1.0 - room) * (1.0 + progress);
        }
    }

    // Mean-residual deviation coupling: prefer bins near mean residual (smooth Gaussian-like).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but weight by bin fullness fraction.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score = score * (1.0 + 0.5 * fill_frac) - 5.0 * fill_frac;

    // Harmonic class logic: classify post_residual via integer division thresholds (capacity / k).
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fit
    } else if pr < bin_capacity / 10 {
        score -= 20.0; // nearly perfect
    } else if pr < bin_capacity / 5 {
        score += 10.0; // awkward small dead space
    } else if pr < bin_capacity / 2 {
        score += 15.0;
    } else {
        score += 5.0; // large residual still useful
    }

    // Modulo arithmetic: dead space divisible by common item classes (multiples of 10) is reusable.
    let dead = pr % 10;
    if dead == 0 {
        score -= 4.0;
    } else if dead <= 2 {
        score -= 1.0;
    } else if dead >= 8 {
        score -= 2.0;
    } else {
        score += 2.0; // mid-remainder waste is hard to reuse
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            score += 8.0; // next item won't fit here; residual likely dead
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is fine early, penalized when many bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_frac;

    // Prefer bins with residual near mean (balance), slight reward.
    score -= 2.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the
    // smallest possible item (1..100 range => treat < 10 as unusable gap)
    // are heavily penalized, scaled by how "wasted" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Mid-range dead space (fits only tiny items) gets a moderate penalty.
    else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // using it avoids opening a new bin — reward it, but only if the
    // resulting dead space is acceptable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 || post_residual == 0 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into new bins; prefer consolidating into existing residual space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has huge residual; make it
    // unattractive unless existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening bins is even less attractive.
        score += 20.0 * progress;
        // But if many open bins exist with low mean residual, a fresh bin
        // is relatively fine (they are nearly full anyway).
        score -= (open_bins_count as f64 * 0.3).min(10.0);
    }

    // Lookahead: if the next item would fit into this bin's post_residual,
    // reward this placement (keeps bins complementary).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item cannot fit the post residual but post residual is large,
    // slight penalty (bin may become stranded).
    if next_item_size > post_residual && post_residual >= 20 {
        score += 5.0;
    }

    // Slight preference for filling bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits too: mild reward proportional to slack left after next placement.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit in leftover: penalize dead space.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize new-bin candidate (bin_residual == bin_capacity) unless current bins are hopeless.
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    // Early in stream, slightly favor reusing bins to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: perfect or near-perfect fits get strong bonus.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tight) * (1.0 - tight);

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is large.
    score += 0.15 * open_bins_count as f64;
    score -= 0.10 * mean_residual;

    // Time horizon: early on, be conservative (favor filling existing bins);
    // late in the stream, minimize leftover waste aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - tight);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, reduced when existing fits are poor.
        let poor_fit_penalty = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += 60.0 + poor_fit_penalty - 0.5 * mean_residual;
        // Late in stream, avoid opening bins for small items.
        if item_size < 40 && progress > 0.7 {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;
    let tightness = 1.0 - fit_ratio;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * pr_norm);

    // Reward tight fits, smoothly scaled by progress
    score -= 18.0 * tightness * tightness * (1.0 - pr_norm * pr_norm) * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (pr - ns).max(0.0);
        score += 0.35 * waste * (1.0 - progress);
        // Reward bins whose post-residual accommodates the next item
        let next_fits = (ns <= pr) as i32 as f64;
        score -= 6.0 * next_fits * (1.0 - pr_norm) * (0.5 + progress);
    }

    // Last-chance bonus: smooth reward when few fitting bins exist
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 8.0 * scarcity * (1.0 - pr_norm);

    // Mild penalty for spreading across many open bins
    score += 0.4 * open_bins_count as f64 * pr_norm * (1.0 - progress);

    // Deviation from mean residual, smooth quadratic
    score += 0.25 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: modulo-10 buckets (capacity fractions) ---
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space classes: small remainders (1..=9) are hard to fill -> penalize
    match class {
        0 => score -= 8.0,            // perfect fit class
        1 | 2 | 3 | 4 => score += 6.0, // awkward slivers
        5 | 6 | 7 => score += 3.0,    // medium slivers
        8 | 9 => score += 1.0,        // nearly full, mild penalty
        _ => {}
    }

    // Integer-division threshold on post_residual: halves of capacity
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half { score -= 4.0; }
    else if pr >= quarter { score += 1.0; }
    else if pr > 0 { score += 5.0; }

    // --- Coupling with next item (lookahead k=2) ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits exactly into this residual -> strong reward
            score -= 10.0;
            // harmonic check: does next item leave a perfect class too?
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 6.0; }
            if pr2 < 10 && pr2 > 0 { score += 4.0; }
        } else {
            // next item cannot use this residual: dead space risk
            score += (next_item_size as f64) * 0.15;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 {
        // only this bin fits; avoid opening a new bin unless residual is tiny
        if pr >= 10 { score -= 7.0; }
    } else if fitting_bins_count > 1 {
        // competition exists: prefer bins with tight fit
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // fresh bin: attractive if current item is large (leaves structured residual)
        let frac = item_size as f64 / cap;
        if item_size >= half {
            score -= 3.0; // large item into empty bin is fine
        }
        if frac.fract() == 0.0 && (cap / item_size as f64).fract() == 0.0 {
            score -= 5.0; // item divides capacity harmonically
        }
        // discourage new bins when plenty of open bins have room
        score += (open_bins_count as f64) * 0.8;
        // discourage late in the stream if mean residual is large
        score += mean_residual * 0.05;
    }

    // --- Stream progression: tighten packing as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mild preference for bins tighter than the mean residual
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin before opening a new bin: favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }
    // If next item is large, prefer bins with big residual for the future.
    if next_item_size >= 60 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // New-bin candidate: only attractive when open bins would leave tiny dead space
    // or pressure is low early in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 3.0;
        if post_residual >= 10 || item_size > 90 {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (consolidate small gaps).
    score += ((mean_residual - bin_residual as f64) / 10.0).clamp(-5.0, 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: next item fits in the post residual with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.8;
    }
    // Next item cannot use the remaining space: penalize dead space creation,
    // scaled by how much usable space is wasted relative to mean residual.
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        score += dead * 0.5 + (dead - mean_residual).abs() * 0.3;
    }

    // Reward tight fills (low post residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.01;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Spread load: mildly prefer bins with more alternatives.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate: only attractive if the item is large relative to
    // capacity or no good existing fit exists (post residual of a fresh bin
    // is large, so it needs a discount to compete when fits are poor).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let poor_fit = fitting_bins_count <= 1
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 20);
        if large_item || poor_fit {
            score -= 25.0;
        } else {
            // Prefer filling existing bins when fits are decent.
            score += 40.0;
        }
    }

    // Late in the stream: consolidate harder, avoid leaving scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * progress;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).powi(2) * 0.005;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Strong reward for near-perfect fits (post_residual small).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size as u32) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward small residual
            let tiny = post_residual as f64;
            if tiny < next_item_size as f64 && tiny < 10.0 {
                score += 10.0;
            }
        }
    }

    // Global state coupling: penalize creating residual far below the mean residual
    // (fragmentation relative to the fleet average), scaled by fleet size.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (open_bins_count as f64).sqrt().min(4.0);

    // Time horizon: early in the stream, be more willing to open new bins (higher score
    // for poor fits is tolerated later); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - waste_frac);

    // Brand-new empty bin candidate: make it attractive only when the fit is bad
    // elsewhere — i.e., neutral baseline slightly above well-fitting open bins.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.10 * mean_residual;
        if fitting_bins_count <= 1 {
            score = 5.0; // no real alternative -> new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.3 + 0.7 * progress);

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize dead space relative to the next item's needs
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.15 * gap * gap / cap;
        if next_item_size as f64 <= pr && next_item_size as f64 > 0.0 {
            score -= 6.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Mild penalty for fragmentation relative to mean residual
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly so open bins are preferred unless fit is poor
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create dead-space classes.
    let r = post_residual % 10;
    // Residues 1..9 (non-multiples of 10) are "awkward" dead space; multiples of 10 are reusable.
    let awkward = match r {
        0 => 0.0,
        1 | 2 | 3 | 4 | 6 | 7 | 8 => 6.0,
        5 | 9 => 3.0,
        _ => 4.0,
    };
    score += awkward;

    // Integer-division thresholds: post_residual in low third = tight fit (good).
    let third = bin_capacity / 3;
    if post_residual <= third {
        score -= 8.0; // near-full bin, reward strongly
    } else if post_residual <= 2 * third {
        score -= 2.0; // moderately full
    } else {
        score += 4.0; // mostly empty bin used wastefully
    }

    // Perfect fit: post_residual is a multiple of small harmonic units (10, 20, 25).
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 20 == 0 {
        score -= 3.0;
    }
    if post_residual == 0 {
        score -= 15.0; // exact fill
    }

    // Lookahead coupling: if next item can exactly fill the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; residual becomes true dead space
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless necessary.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 18.0;
        // but if no open bin fits well (many bins can't help), relax penalty
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // early in stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // if next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good squeeze.
    let dev = mean_residual - post_residual as f64;
    score -= 0.1 * dev;

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Pull toward the mean residual: prefer bins whose residual is near average
    // (balanced packing), penalize outliers.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item would fit in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual is dead space for the next item: penalize proportionally.
        score += 0.2 * post_residual as f64;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., current item is large relative to mean residual and spread is wide).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 }
            else if item_size as f64 > mean_residual + 20.0 { 0.6 }
            else { 0.0 };
        score = bin_capacity as f64 - 80.0 * desperation + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space left).
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize small-but-nonzero leftovers: they are likely dead space.
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
    }

    // 2-step lookahead: reward if the leftover exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // leftover can host the next item: mild reward, scaled by snugness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize proportionally to wasted fraction
            let waste = (next_item_size - post_residual) as f64 / next_item_size as f64;
            score += 50.0 * waste;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are preferred targets.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: score it by "wasted capacity" if opened for this item,
    // plus a mild exploration bonus early in the stream.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 20.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress); // opening new bins is cheaper early on
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 0.6 * nxt;
        } else {
            // penalize leftovers that nearly-but-don't fit the next item (dead space risk)
            score += 0.25 * (nxt - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Slight preference for bins tighter than the current mean residual.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Penalize tiny unusable slivers.
    if post_residual < 10 {
        score += 3.0;
    }

    // Late-stream consolidation: prefer reusing existing bins as the stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (open_bins_count as f64).sqrt();

    // New-bin candidate: only attractive when every open bin would leave a large hole.
    if bin_residual == bin_capacity {
        let mut nb = 0.9 * bin_capacity as f64;
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 - item_size as f64 {
            nb -= 0.6 * next_item_size as f64;
        }
        if fitting_bins_count == 0 {
            nb -= 20.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex in normalized residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth non-linear coupling of residual with stream progress:
    // early on, tolerate large residuals; later, penalize them quadratically.
    let progress_weight = progress * progress;
    score += 40.0 * progress_weight * norm_pr;

    // Tight-fit reward (small post residual), stronger later in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening bins unless residual would be very small
    // or many bins are open and mean residual is high (consolidation pressure).
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 45.0 - 30.0 * progress - 20.0 * mean_norm * mean_norm;
    }

    // Lookahead: reward if next item fits snugly into the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 10.0 * ((nx - pr) / cap);
        }
    }

    // Crowd penalty: many open bins with low mean residual -> prefer consolidation.
    let crowd = (open_bins_count as f64).ln1p();
    score += 5.0 * crowd * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (integer division into capacity fractions) ---
    // Class 0: post_residual is a "clean" harmonic slot (divides capacity nicely)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual / 10) % 10; // decade class 0..9

    // Reward clean residuals: multiples of 10 are reusable by typical item sizes
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Harmonic-friendly small residuals that pair with common item sizes
    match class {
        0 => score -= 4.0,                      // residual 0..9 (or exact multiples of 100)
        1 | 2 => score -= 2.5,                  // 10..29: fits small items
        3 | 4 => score -= 1.0,                  // 30..49: mid slots
        5 | 6 => score += 1.5,                  // 50..69: awkward mid gap
        7 | 8 => score += 3.0,                  // 70..89: large dead zone
        _ => score += 5.0,                      // 90..99: nearly full, almost dead
    }

    // --- Dead-space penalty: residual too small for the smallest possible item ---
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable dead space
    }

    // --- Lookahead coupling: can next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: reward proportionally to how tightly next item fits
            let slack = post_residual - next_item_size as u32;
            score -= 8.0 - (slack as f64) * 0.15;
            // Perfect harmonic pair: next item exactly fills residual
            if slack == 0 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here: penalize more if residual is large (waste)
            score += (post_residual as f64) * 0.10;
        }
    }

    // --- Last-chance logic: this is the only bin that fits the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0; // strongly prefer placing here over opening a new bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; discourage unless current placement is terrible
        score += 55.0;
        // Early in the stream, opening bins is cheaper (build diversity of residuals)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If many bins are open and residuals are fragmented, prefer new bin slightly less
        score -= (open_bins_count as f64).min(20.0) * 0.3;
        // If next item is huge, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // --- Waste-ratio coupling with mean residual ---
    // Penalize bins whose post residual deviates badly from the mean open residual
    let dev = (post - mean_residual).abs();
    score += dev * 0.05;

    // --- Exact-fill reward ---
    if post_residual == 0 {
        score -= 30.0;
    }

    // --- Modulo harmonic bonus: residual that is a divisor-friendly fraction of capacity ---
    if bin_capacity % post_residual.max(1) == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the smallest
    // plausible item are pure waste — penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal
        score -= 200.0;
    } else {
        // Penalize large leftover gaps less than tiny unusable ones,
        // scaled by how "dead" the gap is (gap that nothing fits into).
        let dead = (post_residual < 20) as f64 * 60.0
            + (post_residual < 35) as f64 * 25.0;
        score += dead;
    }

    // Lookahead: if the next item fits into the post_residual, reward this bin;
    // if it nearly fits, mildly penalize for wasting the chance.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
        } else if next_item_size <= bin_residual {
            // next item would fit this bin but not after this placement
            score += 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, prefer tightening existing bins
    // rather than spreading; with few bins, mild preference to fill.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 8.0;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderate score.
        score = 50.0 + pressure * 8.0;
        if post_residual < 15 {
            // small item into a fresh bin wastes the bin — penalize
            score += 100.0;
        }
        if fitting_bins_count == 1 {
            score -= 60.0; // still prefer reusing the last fitting bin
        }
    }

    // Stream progression: early on, be more conservative with new bins;
    // late in the stream, allow tighter packing aggression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (post_residual == 0 as u32 as bool) as u8 as f64;

    // Mean-residual coupling: if open bins are already loose on average,
    // prefer filling them (lower score for bins below mean residual usage).
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already favored).

    // 2-step lookahead: reward if the next item exactly fills the post_residual,
    // reward if it fits, penalize if it doesn't (dead space for the next item).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step match
        } else if next_item_size <= post_residual {
            // partial match: closer to exact fill is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted residual
            score += 0.5 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Penalize leaving residual that is too small for typical items (dead space),
    // but only when the lookahead doesn't rescue it.
    if next_item_size == 0 || next_item_size > post_residual {
        if post_residual < 10 {
            score -= 20.0; // tiny residual is effectively a closed bin: fine
        } else if post_residual < item_size {
            score += 10.0; // awkward gap: too big to ignore, too small to reuse soon
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so we only open a new bin when open bins look bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        // but if no open bin fits well, opening is acceptable (score stays competitive)
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for spreading across bins early vs. late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of the bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits (low post residual relative to capacity)
    score -= 40.0 * fill * fill;

    // Penalize small dead space that nothing can use later (dead zone 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it, especially early/mid stream
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; penalize leaving moderately-sized leftovers
            score += 8.0 * post_frac;
        }
    }

    // Prefer bins with residual below the mean (consolidate fuller bins)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage filling existing ones rather than spreading
    score += 2.0 * open_bins_count as f64 * post_frac;

    // New empty bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying late in the stream
        let new_bin_cost = 60.0 - 25.0 * progress;
        // If few fitting bins or the item is huge, a new bin is more acceptable
        let relief = if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        let big_item = if item_size > bin_capacity / 2 { 15.0 } else { 0.0 };
        score += new_bin_cost + relief + big_item - 20.0 * (1.0 - fill);
    }

    // Mild non-linear coupling: squared deviation of post residual from mean
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Base: post-residual, mildly non-linearly compressed
    let mut score = pr * (1.0 + 0.35 * (pr / cap) * (1.0 - pr / cap));

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, prefer bins that leave very small residuals (tight packing)
    let t = progress * std::f64::consts::PI;
    let phase = 0.5 - 0.5 * t.cos(); // smooth 0->1 ramp
    score -= phase * (pr * pr) / cap * 0.9;
    score += phase * pr * 0.15;

    // Reward filling bins nearly exactly, scaled by progress
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * fill * (1.0 + phase) * 8.0;

    // Penalize dead space relative to mean residual
    score += 0.25 * (pr - mean_residual).abs();

    // Lookahead: if next item fits exactly in post-residual, strong reward
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 3.0 * phase;
    }

    // Last-chance bin: favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: keep it attractive early, less so late
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * phase) + (open_bins_count as f64) * 2.0 - fill * 0.0;
        score -= 10.0 * (1.0 - phase);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Partition residual space into harmonic classes mod 10: small leftovers
    // (<10) are dead space for items >=10, so penalize them extra.
    let class = post_residual % 10;
    if post_residual < 10 {
        // Perfectly dead residual: strongly penalize (waste is total)
        score += 25.0;
    } else if class == 0 {
        // Residual is an exact multiple of 10: ideal harmonic class, reward
        score -= 12.0;
    } else if class <= 3 {
        // Nearly aligned: mild reward
        score -= 4.0;
    } else if class >= 8 {
        // Nearly a full dead slot: mild penalty
        score += 4.0;
    }

    // --- Integer-division thresholds on post_residual ---
    // How many "typical" items (size ~ half of post_residual) still fit?
    let fit_depth = post_residual / 20; // coarse utility measure
    score -= 2.0 * fit_depth as f64;

    // --- Lookahead coupling: does the next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: this placement enables the next item too
            score -= 8.0;
            // Extra reward if next item harmonizes with post_residual class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else if next_item_size <= post_residual + 10 {
            // Near-miss: next item almost chains; slight penalty
            score += 3.0;
        } else {
            // Next item definitely won't use this bin's leftover
            score += 5.0;
        }
    }

    // --- Last-chance bonus: only bin that fits -> avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current open bins are
        // fragmented (low mean residual) or crowded.
        if mean_residual < 20.0 || open_bins_count == 0 {
            score -= 10.0;
        } else {
            // Prefer existing bins when they still hold useful space
            score += 5.0 + mean_residual * 0.05;
        }
    }

    // --- Mild tight-fit reward: filling a bin almost exactly ---
    if post_residual <= 5 {
        score -= 10.0;
    }

    // --- Stream progression: early on, be conservative with new bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            // reward closeness of next item to post residual
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit in this bin after placement: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Penalize small post residuals that are useless (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // neutral-ish baseline; make it slightly worse than a decent fit
        score += 80.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Slight preference for filling fuller bins when many bins are open
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fits are gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fit_ratio * fit_ratio;

        // Reward leaving residuals that small items can still use.
        if post_residual <= 10 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // this placement is doubly valuable; if it creates a residual just
    // barely too small for the next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size <= post_residual + 5 {
            score += 15.0; // near-miss dead space
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when fits are poor or many
    // open bins have low residuals (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let poor_fit = post_residual as f64 > 25.0;
        // Prefer new bin early or when existing fits waste a lot.
        let openness = 40.0 * (1.0 - progress) + fragmentation * 0.5;
        if poor_fit && openness > 45.0 {
            score -= 30.0;
        } else {
            score += 50.0; // discourage needless bin opening
        }
    }

    // Global state: with many open bins, favor consolidation into
    // emptier bins to close them out.
    if open_bins_count > 4 {
        let emptiness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * emptiness;
    }

    // Mild penalty proportional to wasted residual vs mean.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Smoothly shrink effective dead space as stream progresses (favor tight fits late).
    score += prn * prn * 12.0 * (0.5 + 0.5 * progress);
    score -= prn * 8.0 * (1.0 - p3);

    // Reward near-perfect fits with smooth polynomial term.
    let fit_quality = 1.0 - prn;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Penalize residuals that cannot fit the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0) / cap;
        score += 20.0 * gap * gap * (0.3 + 0.7 * progress);
        // Reward residual that nicely accommodates the next item.
        let slack = (pr - ns).max(0.0) / cap;
        score -= 6.0 * (1.0 - slack) * (1.0 - slack) * progress;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize mildly unless open-bin fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    let mrn = (mean_residual / cap).clamp(0.0, 1.0);
    score += 5.0 * (prn - mrn) * (prn - mrn) - 3.0 * prn * (1.0 - mrn);

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * fit_quality;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residue mod capacity quarters ---
    let q = bin_capacity / 4; // 25
    let residue = post_residual % q;
    // Residuals near quarter boundaries are "harmonic" (likely reusable by small items)
    let harmonic_bonus = if residue <= 3 || residue >= q - 3 { 6.0 } else { 0.0 };
    score -= harmonic_bonus;

    // Dead-space class: residuals in awkward mid-range bands are penalized
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny sliver, nearly unusable
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Integer-division threshold: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: lookahead exactly fills leftover
            if next_item_size == post_residual {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Lookahead cannot use this bin's leftover: dead space likely
            score += 6.0 + (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default neutral, penalize opening unless current fit is bad
    if bin_residual == bin_capacity {
        score += 10.0;
        // Opening a new bin is fine early or when few bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count < 4 || progress < 0.1 {
            score -= 8.0;
        }
        // If lookahead is large and mean residual is small, new bin is attractive
        if next_item_size > 50 && mean_residual < 20.0 {
            score -= 12.0;
        }
    }

    // Slight preference for tighter packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.05 * (0.5 + progress);

    // Coupling with mean residual: prefer bins below mean (use loose space first)
    if (post_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    } else if post_residual == 0 {
        // Perfect fill is the best possible outcome.
        score -= 100.0;
    } else {
        // Larger usable residuals are mildly attractive.
        score -= (post_residual as f64) * 0.05;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0 + 0.5 * (post_residual as f64);
    }
    // Reward when the next item exactly or nearly fills the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones;
    // with few open bins, prefer packing into existing bins anyway but soften.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, but less when many bins are open and
        // this bin's residual would leave a bad gap anyway.
        score += 40.0 + pressure;
        if post_residual > 0 && post_residual < 10 {
            score += 30.0; // opening a fresh bin for a bad-fit item is pointless
        }
    } else {
        // Existing bins get a discount that grows with open-bin pressure.
        score -= pressure.min(25.0);
        // Prefer bins tighter than the current mean residual (good fits).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Mild preference for large items going into tight bins.
    if item_size >= 60 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: small post_residual is already favored by base term,
    // but add extra quadratic discount for very tight fits.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 1.0 {
            score -= 40.0; // perfect chaining: next item closes this bin
        } else if next <= post_residual as f64 {
            // next item fits: discount proportional to how well it is consumed
            let chain_eff = 1.0 - ((post_residual as f64 - next) / bin_capacity as f64);
            score -= 15.0 * chain_eff;
        } else {
            // next item will NOT fit here: penalize leaving a residual that is
            // likely dead space relative to the mean residual of open bins.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: leaving residual far below the
    // mean means we consumed valuable slack; leaving far above means this bin stays useful.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit and residuals
    // are still healthy (fragmentation avoidance).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let healthy = fitting_bins_count as f64;
        score += 20.0 + 10.0 * (1.0 - progress) + 3.0 * healthy.min(10.0);
        // But if all open bins would leave huge dead space, allow opening a new bin.
        if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > (post_residual as f64 + mean_residual) {
            score -= 45.0;
        }
    }

    // Mild preference for bins tighter than average when many bins are open.
    if open_bins_count > 3 {
        score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(4) * 40.0;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if post-residual matches next item snugly.
            let snug = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= (1.0 - snug).powi(3) * 10.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good open fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 45.0;
        // If open bins are crowded (few fitting), new bin becomes more attractive.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Large items deserve fresh bins when residuals are fragmented.
        if item_size > mean_residual {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out open bins rather than growing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins with residual above the mean (keep mean residual balanced low).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) penalty
    let mut score = pr + 25.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: tight fits (small norm_pr) are increasingly valuable as stream progresses
    let tightness = (-norm_pr * 4.0).exp(); // ~1 when post_residual near 0, decays as residual grows
    score -= 30.0 * tightness * (0.3 + 0.7 * progress);

    // Cubic interaction between post_residual and progress: late in stream, waste matters more
    score += 12.0 * norm_pr.powi(3) * (1.0 + 3.0 * progress);

    // If next item fits in post_residual, reward this bin (chaining placements)
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 15.0 * chain_quality * (0.5 + 0.5 * progress);
    }

    // Penalize if next item is slightly larger than post_residual (near-miss creates dead space temptation)
    if next_item_size > post_residual && next_item_size > 0 {
        let miss = (next_item_size - post_residual) as f64 / cap;
        score += 20.0 * (-miss * 10.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_item);
    }

    // Slight preference for bins with residuals below mean (consolidate waste)
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 5.0 * dev.tanh();

    // Mild penalty for opening many bins relative to stream progress
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate: smooth gate — favor new bin early or when fit is poor
    if bin_residual == bin_capacity {
        let poor_fit_bonus = norm_pr * norm_pr * 40.0 * (1.0 + progress);
        score += 10.0 - 20.0 * (1.0 - progress) + poor_fit_bonus;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: exact division of capacity into item-sized chunks
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Reward residuals that divide capacity cleanly (harmonic classes: 0, cap/2, cap/3, ...)
    let frac = pr / cap;
    let harmonics = [0.0f64, 1.0/4.0, 1.0/3.0, 1.0/2.0, 2.0/3.0, 3.0/4.0, 1.0];
    let mut best_h = f64::INFINITY;
    for &h in &harmonics {
        let d = (frac - h).abs();
        if d < best_h { best_h = d; }
    }
    score += 6.0 * best_h; // prefer residuals near harmonic fractions of capacity

    // Reward small residuals strongly (tight packing)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residual too small for likely future items (sizes 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let new_pr = post_residual - next_item_size;
            score -= 8.0 * (1.0 - new_pr as f64 / cap);
        } else {
            // next item won't fit here; penalize leaving large loose residuals
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if is_new_bin {
        let crowding = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalty for opening new bins early / when few bins open
        let mut nb = 15.0 + 2.0 * open_bins_count as f64;
        nb -= 10.0 * progress;
        // if this bin's post-residual fit is poor (large leftover), new bin gains appeal
        if mean_residual < it { nb -= 12.0; }
        if crowding > 4.0 { nb -= 6.0; }
        // never open a new bin when the item fits snugly somewhere
        if post_residual <= 10 && !is_new_bin { nb += 50.0; }
        score += nb;
    }

    // Mild preference for balancing mean residual
    score += 0.03 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals too small for the smallest item (1..=9)
    // are unusable dead space; punish them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 12.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to capacity (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_frac) * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones; penalize the fresh-bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in post residual but could fit a larger residual,
    // mildly penalize leaving a residual just below next_item_size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Early in the stream, be slightly more willing to keep residuals flexible
    // (favor bins with larger residuals); late, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * waste_frac * 10.0;

    // Prefer bins below the mean residual (consolidate waste into few bins).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    // -> both items pack perfectly, strongly reward.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // next item fits with leftover; penalize proportionally to leftover
            let leftover = (post_residual - next_item_size) as f64;
            score += leftover * 0.4;
        } else {
            // next item won't fit here after this placement; mild penalty scaled
            // by how much of the next item overflows
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.15;
        }
    } else {
        // Last item: prefer tightest fit only
        score -= 10.0;
    }

    // Reward bins whose residual is small relative to the mean (tight bins get used,
    // large-residual bins stay flexible).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (post_residual very small is good).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (item_size as f64 / bin_capacity as f64) * 8.0;
    }

    // Strong penalty for creating dead space (small unusable leftover, e.g. 1..=3)
    if post_residual >= 1 && post_residual <= 3 {
        score += 20.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * 20.0 / (mean_residual + 1.0);
        // Prefer reusing bins early; allow new bins when mean residual is low or many bins
        score += 30.0 - crowded * 0.5 - progress * 10.0;
        // If next item is large and current item leaves big gap, new bin is fine
        if next_item_size >= 60 && item_size >= 60 {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins with high fill ratio
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + progress * pr_norm + progress * progress * pr_norm * pr_norm);

    let mut score = poly * cap;

    // Penalize dead space more strongly as stream progresses
    score += progress * pr_norm * pr_norm * 20.0;

    // Reward tight fits via cubic damping of post-residual
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * 15.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let gap = (pr_norm - next_norm).abs();
        score += gap * gap * 10.0;
    }

    // Slight preference for consolidating into fewer bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * pr_norm;

    // Mean residual interaction
    score -= (mean_residual / cap - pr_norm).abs() * 3.0;

    // New-bin candidate: prefer it only when item is large relative to residual elsewhere
    if bin_residual == bin_capacity {
        score += 5.0 - item_norm * 4.0 + progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into coarse "harmonics" of the capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class index: 0 = tiny leftover (great fit), higher = wasteful.
    let harmonic = (post_residual / 10).min(10) as f64;
    score += harmonic * 2.0;

    // Exact modular structure: leftovers that are multiples of common item
    // sizes (10, 20, 25, 50) are reusable; penalize "ugly" remainders.
    let rem10 = post_residual % 10;
    if rem10 != 0 {
        score += rem10 as f64 * 0.8;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is nearly unusable.
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Lookahead coupling: does the next item's harmonic class match the
    // leftover? Reward leftovers that can host next_item_size exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Next item fits, but check how harmonically the then-leftover behaves.
            let post2 = post_residual - next_item_size;
            score -= 8.0;
            if post2 % 10 == 0 {
                score -= 6.0;
            }
            if post2 < 10 && post2 > 0 {
                score += post2 as f64 * 2.0;
            }
        } else {
            // Next item cannot use this bin's leftover: leftover is stranded
            // unless another item later matches. Penalize proportional to waste.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a neutral-to-mild score;
    // only prefer it when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many items remain
        // and open bins are fragmented (high mean residual spread).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.85 - progress * 10.0;
        // If existing bins would leave ugly remainders, new bin is fine.
        let ugly = (post_residual % 10 != 0) as f64 * 5.0;
        score -= ugly;
        // Prefer new bin if mean residual of open bins is small (they are full-ish).
        score += (mean_residual / cap) * 20.0;
    }

    // Mild pressure to consolidate: fewer open bins is better when fits exist.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals that are too small to ever be useful
    // (below the minimum conceivable item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small but usable post residual).
    if post_residual > 0 && post_residual <= 15 {
        score -= 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // elsewhere or open-bin pressure is high; otherwise keep it slightly
    // worse than a good existing fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - item_size as f64;
        score += 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: open new bin
        }
        if post_residual < 10 {
            score += 0.0; // empty bin never creates dead space
        }
    }

    // Lookahead: if next item fits into this bin's post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would leave this bin wasted anyway, slight penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean
    // (filling the fullest bins first keeps many medium residuals alive).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late-stream tightening: as the stream progresses, be greedier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a post_residual that
    // matches the next item size exactly or nearly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match for the next item => big bonus.
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64));
        // Extra spike for an exact match.
        if gap < 0.5 {
            score -= 25.0;
        }
        // Also reward post_residual that can still hold the next item
        // with some slack (keeps chains of placements alive).
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space: cannot host the next item.
            score += 0.15 * (post_residual as f64);
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.05 * (post_residual as f64);
    }

    // Penalize post_residual below the minimum plausible item size (unusable sliver),
    // unless it exactly matches the next item (handled above).
    if next_item_size == 0 || post_residual < next_item_size {
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // Compare against mean residual: prefer bins whose residual is above average
    // (they have room to spare), lightly penalize near-empty bins.
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= 3.0;
    } else if res_f < mean_residual {
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        score -= 4.0 * progress;
    }

    // Discard the brand-new-bin option unless existing fits are truly bad:
    // a new bin starts with score == bin_capacity; keep it slightly unattractive
    // but allow it when post_residual would be a tiny dead sliver.
    if bin_residual == bin_capacity {
        score += 8.0;
        if item_size >= 10 && next_item_size > 0 && post_residual < 10 && post_residual != next_item_size {
            score -= 30.0; // opening fresh is better than making a sliver
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but usable.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let tight_bonus = if post_residual == 0 {
        -30.0 // perfect fill
    } else if post_residual <= 10 {
        -18.0
    } else if post_residual <= 20 {
        -8.0
    } else {
        0.0
    };
    score += tight_bonus;

    // Lookahead coupling: if next item fits in the post-residual, this is a great bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // penalize leaving dead space the next item cannot use
        let waste = post_residual as f64 - 0.0;
        score += 0.15 * waste * (0.5 + t);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many options, prefer tighter fits more aggressively
        score += 0.1 * (fitting_bins_count as f64).min(5.0);
    }

    // Prefer bins below mean residual (filling emptier bins evens out residual distribution)?
    // Actually prefer bins ABOVE mean residual (larger residual = more room = better fit chance),
    // while penalizing very low residuals relative to mean (fragmented bins).
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.08 * (res - mean_residual);
    } else {
        score += 0.12 * (mean_residual - res);
    }

    // Discourage opening new bins when open bins already have plenty of room.
    if bin_residual == bin_capacity {
        let avg_free = mean_residual.max(0.0);
        score += 10.0 + 0.5 * open_bins_count as f64 + 0.3 * avg_free;
        // Early in the stream new bins are cheap; late in the stream avoid them.
        score += 20.0 * (1.0 - t);
    }

    // Mild time pressure: as stream ends, consolidate into existing bins.
    score -= 10.0 * t * (if bin_residual < bin_capacity { 1.0 } else { 0.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, penalize waste more strongly
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += 0.3 * progress_coupling;

    // Dead-space penalty: post-residual that cannot fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let gap = (ns - pr) / cap;
            score += 15.0 * gap * gap * (1.0 + progress);
        } else {
            // reward bins whose leftover fits the lookahead item, smoothly
            let slack = 1.0 - (pr - ns) / cap;
            score -= 2.0 * slack * slack * (0.5 + progress);
        }
    } else {
        // last item: minimize residual directly
        score += 0.5 * pr;
    }

    // Last-chance bonus: unique fitting bin should be strongly favored
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fit > 1.0 {
        score += 0.4 * (fit - 1.0) * (1.0 - progress * 0.5);
    }

    // Mean-residual coupling: prefer bins deviating below mean residual
    // (tighter bins) when mean residual is high; smooth interaction
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * (0.5 + 0.5 * progress);

    // Mild penalty for proliferating open bins early in the stream
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: only attractive when item is large or stream is late
    let is_new = (bin_residual == bin_capacity) && (item_size as f64) <= bin_residual as f64;
    if is_new {
        let large_item = item_size as f64 / cap;
        score += 3.0 + 10.0 * (1.0 - large_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: classify post_residual into residue classes of
    // common small item sizes (integer division thresholds).
    let cls = post_residual / 10; // coarse class 0..10
    let class_penalty = match cls {
        0 => -20.0,                 // nearly perfect
        1 => 5.0,                   // 10-19: awkward sliver
        2 | 3 => 12.0,              // 20-39: dead zone for mid items
        4 | 5 => -8.0,              // 40-59: useful
        6 | 7 => 0.0,
        _ => 15.0,                  // large residual: wasteful but flexible
    };
    score += class_penalty;

    // Lookahead: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // bonus if it fits snugly afterwards
            let chain = post_residual - next_item_size;
            if chain < 10 {
                score -= 10.0;
            }
        } else {
            score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost so we
    // only open when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // but open a fresh bin if the item is large and current bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
        let _ = progress;
    }

    // Penalize bins far above mean residual (fragmentation imbalance).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Modulo harmonic: residual congruent to small sizes is more reusable.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 10 == 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are useless, punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can still host the next item (usable space).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item.
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor (large post_residual).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 55.0 - 70.0 * waste;
        // Late in stream, prefer consolidating into existing bins.
        score += 25.0 * progress;
    }

    // Mild tie-break toward bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild superlinear penalty
    // on wasted space relative to capacity.
    let frac_waste = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * frac_waste * frac_waste;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly or
    // nearly matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let perfect = if gap == 0.0 { 1.0 } else { 0.0 };
        score -= 18.0 * perfect;
        score += 0.35 * gap;

        // If the next item fits EXACTLY into the post_residual, this is a
        // two-item perfect closure: strongly favor it.
        if next_item_size == post_residual {
            score -= 30.0;
        }
        // If next item cannot fit in post_residual but this bin's residual
        // leaves a large unusable chunk, penalize proportionally.
        if next_item_size > post_residual {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a post_residual well below the mean means this bin becomes
    // hard to fill later -> mild penalty; leaving it near/above mean is fine.
    if open_bins_count > 1 {
        let diff = post_residual as f64 - mean_residual;
        score += 0.10 * diff;
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item fits poorly everywhere. Penalize the fresh empty bin
    // unless the fit into existing bins is really bad (large post_residual).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its residual equals capacity.
        // Offset so that a new bin only wins when existing placements
        // would waste more than ~ (capacity - typical item) space.
        score -= 0.5 * (item_size as f64);
        // Early in the stream, opening bins is cheaper; later, prefer packing.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for keeping fewer open bins (consolidation pressure).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer minimal post residual (best fit core).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Penalize dead space that no future item (min size 1, typical small) can fill;
    // dead space in (0..10) is nearly unusable for classic streams.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 150.0;
        } else if post_residual < next_item_size {
            // next item won't fit here; slight penalty for stranding space
            score += 30.0;
        }
        // Reward leaving room for the next item at all.
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large and fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: moderately high so only genuinely bad fits beat it.
        let pressure = (item_size as f64 / bin_capacity as f64) * 60.0;
        let many_open = (open_bins_count as f64).ln().max(0.0) * 10.0;
        // Late in stream, prefer closing out open bins rather than growing.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 120.0 - pressure + many_open + progress * 40.0;
        // If no other bin fits at all, new bin must win.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        return score;
    }

    // Prefer filling bins that are already relatively full (tight packing).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 50.0;

    // Prefer bins whose residual deviates favorably from the mean residual:
    // choosing a below-mean-residual bin concentrates packing.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Mild penalty for spreading across many open bins early on.
    if open_bins_count > 1 {
        score += ((open_bins_count as f64).ln() - 1.0).max(0.0) * 5.0;
    }

    // Time-horizon coupling: as the stream progresses, be greedier (minimize waste now).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Smooth non-linear polynomial coupling with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier)
    let progress_coupling = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + progress * 60.0);
    score += 40.0 * progress_coupling;

    // Early stream: favor keeping residuals flexible (mild quadratic reward for mid-range residual)
    let flexibility = 4.0 * norm_pr * (1.0 - norm_pr);
    score -= flexibility * (1.0 - progress) * 30.0;

    // Penalize post residual that can't fit the next item (smooth sigmoid-like gate)
    if next_item_size > 0 {
        let fits_next = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let unusable = 1.0 - (fits_next / 20.0).tanh().abs();
        score += 25.0 * unusable * (0.5 + progress);
    }

    // Last chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 30.0 * progress;
    }

    // Many open bins: discourage spreading; few bins: encourage consolidation
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * 10.0 * norm_pr;

    // Bin far from mean residual: slight penalty (outlier dead space)
    score += 0.3 * (pr - mean_residual).abs() * progress;

    // New empty bin candidate: default mild penalty unless item is large
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 20.0 - 25.0 * large * large;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod 10 and integer division bands.
    let cls = post_residual % 10;
    let band = post_residual / 10; // 0..=10

    // Reward residuals that are "harmonically useful": multiples of common item sizes.
    // post_residual in {0,10,20,...,90} is reusable by typical items.
    if cls == 0 {
        score -= 12.0;
    } else if cls == 5 {
        score -= 4.0;
    } else {
        // odd/unusable classes penalized more when residual is small (dead space)
        score += (10 - cls) as f64 * 0.35;
    }

    // Small dead-space bands are bad unless residual is 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Reward filling bins nearly full (band 0 means residual < 10 handled above).
    if band >= 1 && band <= 3 {
        score -= 3.0; // tight fit is good
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot class
            let over = (next_item_size - post_residual) % 10;
            score += over as f64 * 0.2;
        }
    } else {
        // last item: just minimize waste
        score += 5.0;
    }

    // New-bin candidate: prefer it when current bin would leave large awkward residual
    // and the stream is early (many items remain to fill fresh bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is attractive early; penalize it later.
        score += 18.0 * (1.0 - progress) - 6.0 * progress;
        // But if only one bin fits and residual class is bad, new bin becomes viable.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            score -= 10.0;
        }
    }

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it's already tight — reward using it (best-fit tendency).
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.15;
    }

    // Mild penalty for spreading across many open bins when a tight option exists.
    if open_bins_count > 4 && post_residual > 40 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 5.0; // gap in the "small item" range, still reusable
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 && (post_residual as u32) < next_item_size {
        score += 6.0; // dead space relative to the known next item
    }

    // New-bin candidate: neutral-ish baseline, slightly above good fits.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Stream progression: early on, be a bit more conservative about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's post-residual exactly fits the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item fits with small slack left (tight chain)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0);
    }

    // Penalize creating dead space smaller than the smallest plausible item (1..=100 range)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Reward bins tighter than the current mean residual (good packing state)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight preference for using existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more later in the stream
        score += 20.0 + 40.0 * progress;
    } else {
        score -= 10.0 + 20.0 * progress;
    }

    // Discard tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (nonlinear).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits.
    score -= 8.0 * (item_size as f64 / bin_residual as f64);

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: penalize leaving large slack.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in stream, prefer consolidating (favor existing bins);
    // late in stream, slack matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.3 * progress;

    // Many open bins: discourage spreading; few bins: cheaper to open new ones.
    score += 0.5 * open_bins_count as f64;
    score += 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it attractive only when current bin's post-fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; offset by how badly existing bins would fit.
        score = 55.0 + 0.3 * mean_residual - 0.4 * item_size as f64;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity - 1) {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core: penalize wasted residual with a smooth convex (quadratic) term.
    let mut score = post * post / cap;

    // Linear waste term scaled by stream progress: later in stream, waste matters more.
    score += post * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) with a saturating non-linear bonus.
    let tightness = 1.0 - (post / cap);
    score -= cap * tightness * tightness * tightness * 0.6;

    // Coupling with mean residual: prefer bins whose residual deviates smoothly
    // from the fleet mean, penalizing outliers that fragment the packing.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 20.0 * dev * dev;

    // Lookahead: if the next item fits perfectly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 30.0 * (1.0 - gap / cap);
        } else {
            // Next item can't follow here: penalize proportional to dead space.
            score += 10.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 + 25.0 * progress;
    }

    // New-bin candidate (empty bin): make it unattractive unless residual waste
    // elsewhere is severe; smooth interaction with progress and open bins.
    if bin_residual == bin_capacity {
        let pressure = post.max(0.0); // post == cap for empty bin
        score = cap * (1.2 + 0.8 * progress) + 0.05 * open_bins_count as f64;
        let _ = pressure;
    } else if post == 0 {
        // Perfect fill: dominant reward.
        score -= 100.0;
    }

    // Mild bonus for consolidating into few bins early, more later.
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity fractions.
    // Post-residuals in "dead zones" (very small) are penalized; exact-fit zones rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead space penalty: quadratic growth for tiny post residuals.
    if post_residual <= 5 {
        score += 40.0 - (post_residual as f64) * 4.0; // 40..20 penalty, encourages tight fits
    } else if post_residual <= 15 {
        score += 6.0;
    }

    // Perfect fit reward (harmonic class 0)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo-class logic: residuals that are multiples of common item granularity
    // (items are 1..=100, but many streams cluster on multiples of 5/10) stay usable.
    let mod10 = post_residual % 10;
    if mod10 == 0 && post_residual > 0 {
        score -= 8.0; // round residual is more likely reusable
    } else {
        score += (mod10 as f64) * 0.4; // ragged residuals slightly penalized
    }

    // Integer-division thresholds: classify residual into capacity quarters.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    score -= (quarter as f64) * 2.0; // prefer bins retaining larger usable chunks

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only prefer it
    // when the current item is large and would leave an awkward residual in any bin,
    // or when the lookahead item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        // Base handicap: opening new bins is costly, must be justified.
        score += 30.0;
        // Large items leaving awkward residuals justify a new bin.
        let awkward = (bin_residual - item_size) < 10 && item_size < bin_capacity;
        if awkward {
            score -= 45.0;
        }
        // Lookahead synergy: if next item nearly fills a fresh bin with this one,
        // a new bin enables a near-perfect pairing.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 35.0;
        }
        // Early in stream, fresh bins are cheaper; late, conserve.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Lookahead fit: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 20.0; // near-perfect lookahead pair
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: mild penalty, this residual may strand.
            score += 4.0;
            if post_residual < 10 {
                score += 10.0; // stranded tiny residual
            }
        }
    }

    // Mean-residual coupling: placing into a bin far from the mean reduces
    // fragmentation of the bin population (keeps residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Many open bins: prefer tightening existing bins to allow bin closure.
    if open_bins_count > 8 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest conceivable item are pure waste — punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose post-residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual becomes dead space relative to the known next item.
        score += 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins when residual
    // capacity elsewhere is still healthy.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are crowded.
        score += 35.0 + 8.0 * (open_bins_count as f64).ln().max(0.0)
            - (mean_residual / 10.0);
    } else {
        score += 0.05 * open_bins_count as f64;
    }

    // Slight preference for tighter fits measured against mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Early-stream exploration: keep bins flexible when little is known.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fit (small post residual), but keep some usable slack.
    let mut score = post;

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next > 0.0 {
        if next == post {
            score -= 60.0; // perfect chain
        } else if next < post {
            let slack = post - next;
            // Reward proportional to how well next item fills the remainder.
            score -= 40.0 * (1.0 - slack / cap);
            // Penalize tiny unusable leftover after the chain.
            if slack < 10.0 && slack > 0.0 {
                score += 15.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize dead space creation.
            score += 10.0 + 20.0 * (post / cap);
        }
    } else {
        // Last item: pure tight fit.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Compare post residual against mean residual: leaving more slack than
    // average is bad for future flexibility.
    score += 0.3 * (post - mean_residual).max(0.0);

    // Avoid fragmenting when many bins are already open.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Never prefer a brand-new bin over a decent existing fit.
    if bin_residual == bin_capacity {
        score += 30.0 + post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, normalized by capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead * dead;

    // Reward tight fits (small post residual) especially when this is the
    // only fitting bin — last-chance placements are precious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count >= 2 {
        // Slight penalty when many alternatives exist: prefer exploring others.
        score += 2.0 * (fitting_bins_count as f64).min(6.0);
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this bin strongly (chaining placements).
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * snug;
        } else {
            // Next item cannot follow here: penalize proportionally to waste.
            score += 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be more selective (favor new bins
    // for large residual anchors); late in the stream, fill aggressively.
    let t = step_index as f64 / total_items.max(1) as f64;
    let urgency = t * t;
    score -= 20.0 * urgency * (1.0 - dead);

    // Global state: many open bins with high mean residual -> encourage
    // consolidation into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are plentiful and roomy.
        let crowd = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 15.0 + 8.0 * crowd;
        // But allow new bins early when stream is long and bins are scarce.
        score -= 12.0 * (1.0 - t) * (1.0 - (open_bins_count as f64 / 20.0).min(1.0));
    } else {
        // Existing bin: reward when mean residual is high (bins are loose),
        // encouraging using the emptiest-feeling capacity.
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Item-size awareness: large items deserve priority placement in the
    // bin that wastes least relative to their size.
    let size_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * size_frac * (1.0 - dead);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: quadratic penalty on post_residual (dead space grows quadratically bad)
    let mut score = post * post / cap;

    // Smooth reward for tight fits: coupling between fill ratio and progress
    let fill = (cap - post) / cap;
    score -= 6.0 * fill * fill * (0.5 + progress);

    // Perfect/near-perfect fit bonus (smooth, non-piecewise)
    let perfect = (-post / cap).exp();
    score -= 4.0 * perfect * (1.0 + progress);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 5.0 * (-gap / cap).exp() * (1.0 - progress * 0.5);
        } else {
            score += 1.5 * (nxt / cap) * (post / cap);
        }
    }

    // Penalize creating residual below typical small-item size as stream progresses
    let small = 10.0_f64.min(cap * 0.1);
    if post < small && post > 0.0 {
        score += (small - post) * (0.5 + progress);
    }

    // Last-chance bin: strongly prefer to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // New-bin candidate: attractive early (fresh capacity), less attractive later
    if bin_residual == bin_capacity {
        score = 2.0 + 10.0 * progress + 0.02 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 >= cap * 0.5 && item <= cap - next_item_size as f64 {
            score -= 3.0; // pairing big items in fresh bin
        }
    }

    // Mild penalty if this bin is far above mean residual (keep bins balanced)
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // classes (likely dead space) get a bonus for being filled.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction leftover

    // Integer-division thresholds on post_residual (harmonic bands)
    let band = post_residual / 10; // 0..10 bands
    match band {
        0 => score -= 12.0,        // post_residual < 10: near-perfect fit
        1 => score -= 8.0,         // 10..19
        2 => score -= 5.0,         // 20..29
        3 => score -= 2.0,         // 30..39
        4 | 5 => score += 1.5,     // 40..59: awkward mid residual
        6 | 7 => score += 3.0,     // 60..79: large dead space risk
        _ => score += 1.0,         // 80..100: essentially empty bin
    }

    // Modulo-arithmetic coupling: leftover that is a multiple of small
    // harmonic units (10, 20, 25, 50) is reusable -> reward.
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 25 == 0 { score -= 2.0; }
    if post_residual % 50 == 0 { score -= 1.5; }

    // Next-item lookahead: reward if next item fits the post residual
    // (exact or close), penalize if next item would waste this bin anyway.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 - slack * 0.08; // next item fits: strong reward
            if post_residual == next_item_size { score -= 4.0; } // perfect chain
        } else {
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
        // Harmonic class of next item size vs post residual band
        let nclass = next_item_size / 20; // 0..4
        let pclass = band.min(9);
        if nclass as i32 - pclass as i32 == 0 { score -= 2.0; }
        let _ = n;
    }

    // Last-chance bin: strongly favor using it rather than opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Many open bins: encourage consolidation into existing bins
    score += (open_bins_count as f64) * 0.15;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - pr) * 0.10;

    // Slight preference for new empty bin early in stream, penalty later
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + progress * 20.0; // opening new bin gets progressively worse
    }

    // Small tie-breaker on capacity fraction
    score += frac * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest possible
    // future item are worthless. Penalize heavily in the "dead zone".
    if post_residual < 10 {
        score += 40.0; // tiny unusable gap
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap cannot hold the known next item: dead space unless a tiny item comes.
        score += 18.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect setup for the lookahead item: strong reward.
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Reward leaving exactly-zero residual (perfect closure).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, but only if the fit is not terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins
    // (raise new-bin score relative to open bins).
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: cost of opening a bin grows with open count.
        score += 10.0 + 2.5 * open_bins_count as f64;
        // Opening a new bin is more acceptable early in the stream or when
        // existing residuals are large (poor fits elsewhere).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 12.0; // nothing fits well; new bin reasonable
        }
    } else {
        // Slight bonus for placing into bins with residual close to the mean
        // (keeps residual distribution balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Mild global preference for using existing capacity as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 50.0;
        } else {
            // Dead space penalty: post_residual smaller than next item is wasted
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size - post_residual) as f64 * 0.8;
            } else {
                // leftover larger than next item: mild reward scaled by closeness
                score -= (post_residual - next_item_size).min(20) as f64 * 0.3;
            }
            // closeness bonus overall
            score -= (40.0 / (1.0 + diff as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer tighter bins relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Never open a new bin when an open bin fits well (post_residual small)
    if bin_residual == bin_capacity {
        score += 15.0 + post_residual as f64 * 0.1;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0; // fresh bin perfect for next item is still fine
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    score -= 12.0 * tightness;

    // Penalize post_residual that is too small to be useful for any item (dead space).
    // Dead space: post_residual > 0 but < minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize mid-range useless residuals less than a large item would need.
    if post_residual >= 10 && post_residual < 40 {
        score += 0.15 * (40 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 {
            // Next item cannot use the leftover; penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 55.0;
        // But if no open bin fits well (tightness low), opening new bin becomes attractive.
        if tightness < 0.5 {
            score -= (0.5 - tightness) * 80.0;
        }
        // Late in the stream, fewer new bins preferred.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= 0.05 * open_bins_count as f64;
    }
    if mean_residual > item_size as f64 {
        score -= 3.0;
    }

    // Slight preference to place large items early into emptier bins.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score += 5.0 * fill_ratio * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 30.0 * norm_pr * norm_pr
        - 20.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling with stream progress: later in stream, penalize large residuals more
    score += 25.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize waste that cannot fit the lookahead item (smooth sigmoid-like gate)
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gate = 1.0 / (1.0 + (-8.0 * (pr - next_item_size as f64) / cap)).recip();
        let _ = fits_next;
        score -= 15.0 * gate * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Reward tight fits relative to mean residual state (smooth quadratic coupling)
    let mean_n = mean_residual / cap;
    score += 10.0 * (norm_pr - mean_n) * (norm_pr - mean_n);

    // Mild penalty when many bins are open (prefer consolidation early)
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - progress) * norm_pr;

    // New-bin candidate: make it unattractive unless residual is essentially perfect
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: coarse-grained via integer division.
    // Classes of 10 units: 0..10 (near-perfect), 10..20, etc.
    let gap_class = post_residual / 10;
    match gap_class {
        0 => score -= 12.0,               // near-perfect fit: strongly reward
        1 => score -= 6.0,                // small gap: good
        2 => score -= 2.0,                // medium gap
        3 => score -= 0.5,                // mediocre
        _ => {}                           // large gap: no reward (dead space)
    }

    // Penalize gaps in the "unusable harmonic band": residual in 1..10 is hard
    // to fill for items >= 10; but if next item fits exactly, reward instead.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Harmonic compatibility: does the NEXT item divide/match the post_residual class?
    if next_item_size > 0 {
        let fits_next = next_item_size <= post_residual;
        if fits_next {
            let next_class = next_item_size / 10;
            let gap_class_f = gap_class as f64;
            // reward if next item lands in same or adjacent harmonic class
            let next_g = next_item_size / 10;
            if next_g == gap_class { score -= 5.0; }
            else if next_g + 1 == gap_class as u32 { score -= 2.5; }
            // exact-fill lookahead
            if next_item_size == post_residual { score -= 15.0; }
            // ratio-based bonus: item consumes >= 75% of remaining space
            if (next_item_size as f64) >= 0.75 * post_residual as f64 { score -= 4.0; }
        } else {
            // next item can't use this residual: penalize proportional to wasted class
            let waste_class = (next_item_size - post_residual) / 10;
            score += waste_class as f64 * 1.5;
        }
    }

    // Item size harmonic classes: large items should go into tight bins.
    let item_class = item_size / 20; // 0..4
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= item_class as f64 * (1.0 - post_residual as f64 / bin_capacity as f64) * 4.0;
    let _ = fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin early in the stream or when
    // this bin's post-residual would be an awkward class.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of a fresh bin
        score = bin_capacity as f64 * 0.6;
        // early stream: fresh bins are cheap (future items unknown)
        score -= (1.0 - progress) * 15.0;
        // if no open bin fits at all, the new bin must win: make it very cheap
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late stream: prefer filling existing bins, penalize new bins
        score += progress * 25.0;
        // many open bins with high mean residual: avoid adding another
        if open_bins_count > 3 && mean_residual > 20.0 {
            score += mean_residual * 0.3;
        }
    }

    // Mild penalty when this bin's residual is far from mean residual
    // (keep residuals harmonized across bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Tie-break: prefer bins with less residual overall when many bins fit.
    if fitting_bins_count > 2 {
        score += post_residual as f64 * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for ANY future item (min size 1..100,
    // but small gaps below ~20 are hard to fill) are heavily penalized.
    if post_residual < 20 && post_residual > 0 {
        score += (20.0 - post_residual as f64) * 8.0; // dead space penalty
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer reusing open bins unless the fit is terrible.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bin would leave big dead space
        // or open-bin pressure is low.
        let dead_here = if post_residual < 20 && post_residual > 0 { 160.0 } else { 0.0 };
        score += 25.0 - dead_here + open_bins_count as f64 * 2.0;
        // If lookahead item fits in the new residual, make new bin slightly more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Open-bins pressure: many open bins -> favor filling existing ones (already default),
    // few open bins -> allow spreading.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to the item (tight fit relative to mean).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead coupling: penalize leaving a residual that neither fits next item nor is 0.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Early stream: be slightly greedy with new bins; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or tightly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // tight fit for next item: penalize wasted gap
            let gap = post_residual - next_item_size;
            score -= 300.0 - gap as f64 * 4.0;
            if gap <= 10 {
                score -= 150.0;
            }
        } else {
            // next item cannot fit: dead space penalty scaled by how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable fit
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count > 0 {
            score += 80.0;
        }
        // early in stream, be less afraid of new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 60.0;
    }

    // small waste penalty for large leftover chunks that few items can use
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny residual is nearly a perfect fit
    }
    if post_residual > 50 {
        score += 20.0; // big leftover is flexible but keep pressure on tight fits
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving residuals that are awkwardly small (dead space nobody can use).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // extra reward if it would then be a tight fit for the next item too.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            let post2 = post_residual - next_item_size;
            score -= 5.0 * (1.0 - (post2 as f64) / (bin_capacity as f64));
        } else {
            score += 3.0; // this placement kills the bin for the next item
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state coupling: many open bins with large mean residual → prefer
    // consolidating into existing bins rather than fragmenting.
    let consolidation_pressure = (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);
    score -= 4.0 * consolidation_pressure * (1.0 - tightness);

    // Time horizon: early in the stream keep bins flexible (penalize very tight fits
    // slightly less late, since endgame packing is more valuable).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    // New-bin candidate handling: an empty bin is only attractive when no decent
    // fit exists (post_residual would be huge) or state suggests saturation.
    if bin_residual == bin_capacity {
        let desperation = (post_residual as f64) / (bin_capacity as f64);
        score += 25.0;
        score -= 20.0 * desperation; // partially rebates when item is large
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening a new bin is clearly right
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: penalize large post_residual quadratically,
    // but relax the penalty as the stream progresses (endgame consolidation).
    let pr_norm = pr / cap;
    let quad = pr_norm * pr_norm;
    let relax = 1.0 - 0.6 * progress * progress;
    score += 60.0 * quad * relax;

    // Reward tight fits with a cubic bonus term.
    let tight = 1.0 - pr_norm;
    score -= 25.0 * tight * tight * tight;

    // Dead-space hazard: residuals too small for typical items are wasted.
    let dead = ((30.0 - pr) / 30.0).max(0.0);
    score += 40.0 * dead * dead;

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: bonus if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: keep it competitive only when open bins are quite full.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 8.0 + 30.0 * crowding * (mean_residual / cap);
    }

    // Mild tie-break toward bins with residuals below the mean (use the fullest).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // --- Harmonic class logic on post_residual ---
    // Residuals divisible by 10 are "harmonic" with the item-size grid: mildly reward.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 2.5;
    }
    // Dead space: residual too small for the smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    // Very tight fit (near-perfect packing) gets a strong reward.
    if post_residual <= 3 {
        score -= 9.0;
    } else if post_residual <= 8 {
        score -= 4.0;
    }

    // --- Integer-division threshold coupling with lookahead ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also land here: chain reward scaled by leftover class.
            let slack_class = (post_residual - next_item_size) / 10; // integer division
            score -= 4.0 + (3.0 - slack_class.min(3) as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // --- Last-chance bonus: this is the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin should only win when existing fits are poor.
        // Base penalty grows with how much usable space is already lying around.
        score += 9.0 + 0.2 * mean_residual;
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= 0.06 * (item_size as f64);
    }

    // --- Mild pressure toward consolidating open bins ---
    if open_bins_count > 4 {
        score -= 0.05 * (open_bins_count as f64);
    }

    // Tiny tie-breaker: prefer bins whose residual is closest to a harmonic fraction of capacity.
    let frac = pr / cap;
    score += (frac - (frac * 2.0).round() / 2.0).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

