    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // new bin candidate: base cost grows with number of open bins
        score += 30.0 + 5.0 * pressure.sqrt();
    } else {
        score -= 3.0 * pressure.sqrt();
    }

    // Slight preference for tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

