    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits into post_residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
