    }

    // New-bin candidate handling: empty bin gets a baseline score near capacity,
    // penalized more when decent open bins exist; favored when residuals are fragmented.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is more attractive early and when mean residual is small.
        score -= 25.0 * (1.0 - progress) * (1.0 - mean_residual / bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if fitting_bins_count <= 1 {
