        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (consolidation).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * dev;
    }

    // Slight time pressure: later in the stream, favor tighter packing overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: penalize leftover space, with a non-linear (quadratic) dead-space penalty
    let mut score = norm_post * (1.0 + 2.0 * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tighten bins more aggressively (waste matters more)
    let late_bias = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += late_bias * norm_post * norm_post * cap * 0.05;

    // Reward tight fits: cubic decay of penalty as post_residual -> 0
    score -= (1.0 - norm_post).powi(3) * 2.0;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else {
        // mild dispersion penalty when many bins could fit
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.1;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if pr >= next_item_size as f64 {
            score -= (1.0 - gap / cap).max(0.0) * 1.5;
        } else {
            score += (next_item_size as f64 - pr) / cap * 0.5;
        }
    }

    // Alignment with mean residual state: prefer bins near the mean to keep balance,
    // with a smooth quadratic coupling scaled by progress
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * (0.5 + late_bias);

    // Mild preference for consolidating into fewer bins as stream progresses
    score -= late_bias * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (mod 10) are "dead space" bins -> penalize.
    let post_class = post_residual % 10;
    if post_residual > 0 {
        // Dead-space penalty: leftovers that no typical item can use.
        if post_class > 0 && post_residual < 10 {
            score += 25.0 * (10 - post_class) as f64;
        }
        // Perfect fit reward: post_residual exactly a multiple of 10
        // (aligns with the classic 10..80 granularity grid).
        if post_class == 0 {
            score -= 12.0;
        }
    }

    // Integer-division thresholds on post_residual: classify leftover size.
    if post_residual <= 20 && post_residual > 0 {
        score += 8.0; // tiny leftover, likely waste
    } else if post_residual > 40 {
        score -= 6.0; // large leftover remains reusable
    }

    // Capacity-fraction coupling: how full the bin becomes.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // Lookahead harmonic class: if next item fits exactly in post_residual,
    // strongly reward; if next item is larger than post_residual but would
    // fit a fresh bin, penalize less.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
        // Modulo affinity: next_item and post_residual share a residue class
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only
    // when no open bin offers a good fit (post_residual would be huge waste).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + 10.0 * fill_frac;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a bin
        } else if next_item_size > 0 && next_item_size <= bin_capacity - item_size && post_residual >= next_item_size {
            // opening a fresh bin enables a perfect next fit
            score -= 20.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer bins below mean residual (balancing across open bins).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
