    if post_residual > half {
        score -= 8.0;
    } else if post_residual > quarter {
        score -= 2.0;
    } else if post_residual < quarter {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the waste is severe.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual <= 10 {
            score += 25.0; // unless it creates dead space
        }
    }

    // New-bin candidate handling: prefer it only when open bins are crowded
    // or this would be a very tight fill.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = (bin_capacity - item_size.min(bin_capacity)) as f64 + 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
            score -= 12.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 30.0;
        }
    } else {
        // Mild diversity pressure: spread load when many bins are open.
        score += open_bins_count as f64 * 0.05;
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Small modulo-based tie-breaking jitter (deterministic).
    score -= ((mod8 * 3 + mod16) % 7) as f64 * 0.05;
    let _ = (mod4, step_index, total_items);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item size (1) are worthless; the smaller the gap, the worse.
    if post_residual > 0 {
        // Non-linear dead-space penalty: quadratic in unusable fraction.
        let dead = 1.0 - (post_residual as f64 / bin_capacity as f64).max(0.0);
        score += 40.0 * dead * dead;

        // Hard penalty for gaps below the smallest plausible item (1..=3):
        // treat them as fully dead.
        if post_residual <= 3 {
            score += 60.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward residuals that exactly fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual cannot fit the next item (dead for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via its large post_residual,
    // but add explicit pressure scaled by open bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (0.5 + progress);

    // Prefer bins tighter than the mean residual (best-fit coupling).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Strong reward when the next item also fits in the post residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward if next item is a near-perfect follow-up fit.
        let next_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 10.0 * next_tightness;
    } else if next_item_size > 0 {
        // Penalize creating dead space that the lookahead item cannot use.
        let waste = post_residual.min(next_item_size.saturating_sub(1).max(post_residual)) as f64;
        score += 0.15 * waste;
    }

    // Penalize leaving residuals that are too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded or this bin would leave bad fragmentation.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 55.0;
        // Cheaper to open when many items remain ahead (amortization).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If open bins are already quite full on average, a new bin is fine.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score -= 30.0 * mean_fill;
        // If no open bin fits, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Prefer new bin if the item is huge relative to typical residual space.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else {
        // Slight preference to consolidate into fewer bins.
        score += 0.5 * open_bins_count as f64;
    }

    // Global pressure: when mean residual is high, prefer using the emptiest bins
    // (large residuals) to consolidate; when mean residual is low, prefer tight fits.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.1 * diff;

    // Mild time-horizon modulation: early in the stream, be greedy about tight fits;
    // late in the stream, avoid opening bins at all costs.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on wasted post-residual
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Cubic dead-space term, damped by stream progress (dead space matters less late)
    let dead_norm = pr / cap;
    score += 30.0 * dead_norm * dead_norm * dead_norm * (1.0 - 0.5 * progress);

    // Reward tight fits: smooth interaction of fill ratio with progress
    let fill = (item_size as f64) / cap;
    score -= 20.0 * fill * fill * (1.0 + progress);

    // Lookahead coupling: prefer residuals that can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            // post-residual cannot host next item: penalize with smooth ramp
            let miss = (nx - pr) / cap;
            score += 15.0 * miss * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        // among many fitting bins, mild preference for tighter residual via base term already
        score += 2.0 * ((fitting_bins_count as f64).ln());
    }

    // Mean-residual coupling: bins far from mean residual get smooth penalty
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate handling: make empty bin attractive only when current fit is bad
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && (pr as u32) < next_item_size { 1.0 } else { 0.0 };
        let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
        // empty bin score: neutral baseline, slightly high so it only wins when open bins are bad
        score = 0.75 * cap + 10.0 * progress - 30.0 * last_chance - 20.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod-8 buckets, capacity-fraction thresholds) ---
    let cap = bin_capacity as f64;
    let post = post_residual as u32;
    let class = post % 8;

    // Dead-space classes: tiny residuals that nothing (>=10) can ever use are pure waste.
    if post > 0 && post < 10 {
        score += 40.0; // absolute dead space penalty
    }
    // Harmonic sweet spots: residuals that are exact divisors / multiples of common item sizes
    match class {
        0 => score -= 18.0,  // divisible by 8: highly reusable
        4 => score -= 12.0,  // divisible by 4
        2 | 6 => score -= 6.0,
        _ => score += 3.0,   // odd residuals: slightly worse reuse
    }

    // Integer-division thresholds: how many "average" items still fit?
    let avg_next = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
    let fits_k = (post as f64 / avg_next).floor();
    score -= 8.0 * fits_k; // reward bins that can absorb the lookahead item k times

    // Lookahead compatibility: does next item fit exactly or snugly?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0; // perfect harmonic match with lookahead
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            if slack < 10.0 { score -= 15.0; } // snug fit leaves near-zero waste
            else { score -= 10.0 * (1.0 - slack / cap); }
        } else {
            // next item does NOT fit here: penalize proportionally to wasted potential
            score += 6.0 + 10.0 * (next_item_size - post) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation into fullest bins.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate handling: only attractive when no good harmonic option exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base new-bin score: slightly worse than a decent-fit open bin
        score = cap * 0.55 - 20.0 * desperation - 10.0 * progress;
        // Open a new bin if open bins are nearly full on average (little reusable space)
        if mean_residual < 15.0 { score -= 15.0; }
        if open_bins_count == 0 { score -= 50.0; }
        return score;
    }

    // Fullness reward: tighter packing preferred; non-linear coupling with mean residual.
    let fullness = 1.0 - (post as f64) / cap;
    score -= 12.0 * fullness * fullness;
    if (post as f64) < mean_residual {
        score += 4.0; // below-mean residual = this bin is tighter than average: good
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space below min item size
        } else if post_residual <= 20 {
            score += 25.0; // narrow gap, few items can use it
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the lookahead item
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if this bin is the only fitting one, strongly avoid a new bin.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // If residual of existing bins is mostly dead space, new bin is acceptable.
        if mean_residual < 12.0 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: if the next item exactly fills the post residual,
    // this is an ideal two-item packing.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }
    // Next item fits snugly into the post residual (tight coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Post residual is dead space: too small for the next item (or anything typical).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 150.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // tiny unusable sliver
    }

    // Prefer bins with residuals below the mean (fill the emptiest-relative bins first),
    // penalize dipping far below mean creating fragmentation.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: baseline score so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 50.0;
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        }
    }

    // Late in the stream: consolidate aggressively, discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual by capacity.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leaving awkward mid-size gaps
            let gap = (post_residual - next_item_size) as f64;
            score += 0.3 * gap;
        } else {
            // next item won't fit here anyway; small residual is fine (dead space low)
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and open bins are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let pressure = 1.0 - mean_r / (bin_capacity as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        let late = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 20.0 * pressure - 10.0 * big_item - 5.0 * late;
        // never open a new bin when an existing bin fits perfectly
        if post_residual == 0 {
            score += 100.0;
        }
    }

    // Mild preference for fuller bins when many bins are open (consolidation).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Encourage exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / capacity;
    let norm_item = item_size as f64 / capacity;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large residuals early (waste), reward tight fits via cubic term
    score += 12.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Reward high fill ratio with smooth quadratic coupling
    let fill = norm_item;
    score -= 20.0 * fill * fill * (1.0 + progress);

    // Dead-space avoidance: residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt) * (1.0 + 0.5 * progress);
        } else {
            score -= 4.0 * (nxt / (pr + 1.0));
        }
    }

    // Last-chance bin bonus (smooth penalty for missing it)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins near the mean (smooth deviation term)
    let dev = (pr - mean_residual) / capacity;
    score += 10.0 * dev * dev;

    // Mild penalty for opening new bins when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction classes
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward placements whose post_residual falls into a "harmonic" class
    // that other items can still fill (e.g. small, reusable residuals).
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else {
        // Modulo arithmetic on post_residual: residuals divisible by common
        // item-size classes (multiples of 10 in classic streams) are reusable.
        if post_residual % 10 == 0 {
            score -= 30.0;
        }
        if post_residual % 25 == 0 {
            score -= 20.0;
        }
        if post_residual % 5 == 0 {
            score -= 8.0;
        }

        // Small residuals (dead space) get penalized quadratically.
        if frac < 0.10 {
            score += (0.10 - frac) * 200.0;
        }

        // Harmonic coupling with next item: reward if next item exactly
        // consumes the post residual (perfect lookahead fit).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 120.0;
            } else if next_item_size < post_residual {
                // next item fits: residual class after next placement
                let r2 = post_residual - next_item_size;
                if r2 % 10 == 0 {
                    score -= 25.0;
                }
                if r2 == 0 {
                    score -= 80.0;
                }
                // reward leaving room for next item reasonably tightly
                score -= 15.0 * (r2 as f64 / cap);
            } else {
                // next item cannot use this residual: mild penalty scaled
                score += (next_item_size - post_residual) as f64 * 0.05;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins
    // would leave very tight unusable residuals.
    if bin_residual == bin_capacity {
        // neutral base; open bins with good fits should beat this
        score = cap * 0.75 - (post_residual as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Penalize bins far below mean residual (fragmenting spread)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Late in stream: consolidate, prefer tighter fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, heavily reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: residuals too small for any item (1..100)
    // are unusable unless zero -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gap: only usable by tiny items; moderate penalty.
        score += 25.0;
    }

    // Reward leaving room for the lookahead item if it fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64) * 0.3;
    }
    // Penalize if post_residual is nonzero but smaller than next item AND
    // below the minimum possible item size (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 40.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 50.0;

    // Open-bin pressure: with many open bins, prefer packing into existing bins
    // over spreading; penalize lightly so new bins are avoided when crowded.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): make it attractive only when existing
    // residuals are large/fragmented; otherwise it should lose to reusing bins.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.4 + (open_bins_count as f64) * 2.0;
        // If next item is huge, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: when average residual is low, bins are nearly
    // full; slightly prefer bins whose residual is below mean (closer to full).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer future items to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward when the leftover space exactly hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit in leftover: penalize small dead space.
            let dead = post_residual as f64;
            score += 150.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins whose leftover is near the average
    // (balanced packing), penalize outliers.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make opening a new bin attractive only when the current
    // fit is poor (large post_residual) or no real alternative exists.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        if poor_fit || fitting_bins_count == 0 {
            score -= 250.0;
        } else {
            score += 200.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Slight preference to fill already-open bins as stream progresses.
    score -= 0.05 * (step_index as f64 / total_items.max(1) as f64) * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post-residual), with a mild convexity penalty
    // so that very small residuals are favored super-linearly.
    let post = post_residual as f64;
    score += 0.35 * (post * post) / bin_capacity as f64;

    // Lookahead: if the next item fits into this bin's post-residual, reward it;
    // otherwise penalize leaving a residual that is almost-but-not-quite useful.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - nxt / bin_capacity as f64);
        } else {
            // dead-space risk: residual can't host the next item
            score += 3.0 * (post / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits,
    // avoiding a needless new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing residuals are badly
    // fragmented (item barely fits anywhere) or many bins are already open.
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64 / bin_capacity as f64
        } else {
            1.0
        };
        // reward opening a new bin when the best existing fit would be very tight
        // or when open-bin count is low relative to progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 25.0 * tightness + 10.0 * (1.0 - progress) - open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: opening is mandatory
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // fresh bin can host the next item too
        }
    }

    // Global fragmentation pressure: if mean residual is small, hoard space;
    // penalize placements that leave residuals near mean (waste-like).
    if bin_residual != bin_capacity {
        let diff = post - mean_residual;
        score += 0.15 * diff.abs();
        // reward bins whose residual is above mean (use the roomy ones first)
        if post > mean_residual {
            score -= 1.5;
        }
    }

    // Time-horizon modulation: early in the stream, be conservative with
    // tight fills (keep flexibility); late, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (1.0 - post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth non-linear shaping
    let post_norm = post / cap;
    let base = post * (1.0 + 0.8 * post_norm * post_norm);

    // Stream-progress coupling: as the stream advances, tighten tolerance for wasted space
    let progress_coupling = post * (0.15 + 0.55 * progress) * (1.0 - post_norm);

    // Dead-space penalty: residuals that no plausible item can use are worse
    let dead_penalty = if post > 0.0 && post < 10.0 { 12.0 * (1.0 - post / 10.0) } else { 0.0 };

    // Lookahead: reward residuals that can host the next item (smooth, not hard cutoff)
    let lookahead = if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 { -6.0 * (1.0 - gap / cap) } else { 4.0 * (-gap / cap) }
    } else { 0.0 };

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a bin
    let last_chance = if fitting_bins_count == 1 { -18.0 } else { 0.0 };

    // Crowding: many open bins with low mean residual -> prefer filling existing bins
    let crowding = -0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap).max(0.0);

    // New-bin candidate: empty bin gets a moderate opening cost so it's chosen
    // only when no open bin offers a decent fit.
    let new_bin_cost = if bin_residual == bin_capacity {
        8.0 + 20.0 * progress
    } else {
        0.0
    };

    let mut score = base + progress_coupling + dead_penalty + lookahead + last_chance + crowding + new_bin_cost;

    // Smooth saturation of extreme scores to keep comparisons stable
    score = score.tanh() * 50.0 + score * 0.01;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by modulo classes of capacity.
    let r = post_residual;
    let class = r % 10; // fine-grained harmonic class
    let harmonic_bonus = match class {
        0 => -12.0, // perfectly aligned residual (e.g., 50, 60, ...) -> very reusable
        5 => -8.0,  // half-class residuals still highly reusable
        2 | 8 => -4.0,
        _ => 0.0,
    };
    score += harmonic_bonus as f64;

    // Integer-division thresholds on post_residual: reward small residuals strongly.
    if r == 0 {
        score -= 30.0; // perfect fit
    } else if r <= 10 {
        score -= 10.0; // nearly full, dead space unusable anyway
    } else if r <= 20 {
        score -= 4.0;
    } else if r > bin_capacity / 2 {
        score += 6.0; // leaving more than half empty is wasteful
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size < r {
            let slack = r - next_item_size;
            if slack <= 10 {
                score -= 8.0;
            } else if slack > 40 {
                score += 3.0; // next item leaves huge slack again -> chain of waste
            }
        } else {
            // next item won't fit here; penalize proportionally to how far off
            let gap = (next_item_size - r) as f64;
            score += (gap / 20.0).min(6.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (high mean residual mismatch) or few bins fit item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_cost = 20.0 + 10.0 * progress; // late in stream, prefer reusing bins
        let fit_pressure = if fitting_bins_count == 0 { -25.0 } else { 0.0 };
        let mean_gap = (mean_residual - item_size as f64).abs();
        let mismatch = if mean_gap < 10.0 { -10.0 } else { 0.0 };
        score += open_cost + fit_pressure + mismatch;
    }

    // Slight preference for bins whose residual is close to item (best-fit sharpening).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 2.0;

    // Mild penalty for proliferating bins when this bin is already sparse.
    if open_bins_count > 4 && bin_residual as f64 > mean_residual + 20.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: residuals too small to hold any item (min size 1,
    // but practically tiny gaps) are wasted. Penalize unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderate gaps that could still fit a typical small item are mildly bad.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + next_item_size as f64 * 0.4;
    }
    // If next item is slightly larger than the gap, this creates near-dead space.
    if next_item_size > post_residual && post_residual > 0 && (next_item_size - post_residual) < 15 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate opening new bins for better fits.
    let pressure = open_bins_count as f64 * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure; attractive only when
        // existing fits are poor (their dead-space penalties dominate).
        score += 30.0 + pressure;
        // Opening early in the stream is cheaper (more items to fill it with).
        if total_items > 0 {
            score -= 40.0 * (1.0 - step_index as f64 / total_items as f64);
        }
    } else {
        // Favor the fullest-remaining bin (best fit) among open bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
        // Bonus for placing into bins already below mean residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
        score += pressure * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match bonus (subtract heavily); graded penalty for near misses.
        if diff == 0.0 {
            score -= 40.0 + 0.5 * item_size as f64;
        } else if diff <= 5.0 {
            score -= 20.0 - 3.0 * diff;
        } else {
            score += 0.3 * diff;
        }
        // Penalize residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight preference to keep bins tightly packed early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Discard tiny unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 15.0;
    } else if post_residual < 12 {
        score -= 6.0;
    }

    // Dead-space penalty: small unusable leftovers are bad, scaled by how many
    // future items could still use them (early in stream => worse to waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (1.0 - progress) * 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; mildly penalize leaving a mid-gap that
            // neither the next item nor typical small items can use.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins among many open bins (mild consolidation pressure).
    score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean residual (i.e., fuller than average).
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate pricing: opening a new bin is acceptable when the item
    // is large (little waste) or few bins are open; expensive when item is small
    // and many bins exist with usable space.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste
            + 10.0 * (open_bins_count as f64).sqrt()
            - 15.0 * (item_size as f64 / bin_capacity as f64)
            - (1.0 - progress) * 5.0;
        // If no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight noise-free tie-break toward earlier-created (fuller) bins via residual.
    score += 0.01 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer bins left with small residual (tight packing).
    let mut score = post;

    // Non-linear tightness reward: quadratic coupling of fit ratio with progress.
    let fit_ratio = 1.0 - (post / cap);
    let tightness = fit_ratio * fit_ratio * (1.0 + progress);
    score -= 18.0 * tightness * cap * 0.01;

    // Penalize large dead space with a smooth cubic term (worse later in stream).
    let dead = post / cap;
    score += 25.0 * dead * dead * dead * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: score proportional to item size plus mild progress penalty,
    // so it only wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = item + 0.15 * cap * (0.3 + progress) + 0.1 * mean_residual;
    } else {
        // Favor bins whose residual is close to item (smooth kernel), avoiding waste.
        let gap = (bin_residual as f64 - item).abs();
        score += 0.08 * gap;
        // Lookahead: reward bins whose post-residual can host the next item.
        if next_item_size > 0 {
            if post >= next_item_size as f64 {
                score -= 6.0 * (1.0 - (post - next_item_size as f64) / cap);
            } else {
                score += 4.0 * (1.0 - post / (next_item_size as f64 + 1.0));
            }
        }
        // Mild penalty for spreading across many open bins.
        score += 0.05 * open_bins_count as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well the leftover decomposes
    // into capacity fractions (quarters). Small, "clean" leftovers are good.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Residue classes mod 10 and mod 25 on the residual
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;

    // Penalize awkward leftovers that don't align with common size classes
    if post_residual > 0 {
        if mod10 == 0 {
            score -= 4.0; // perfectly divisible by 10: likely reusable
        } else if mod25 == 0 {
            score -= 3.0;
        } else if post_residual < 10 {
            score += 15.0; // dead space: nothing can fit (min size 1..10)
        } else if post_residual < 20 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the leftover,
    // reward strongly (perfect harmonic match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            // leftover after the hypothetical next placement
            let post2 = post_residual - next_item_size;
            if post2 < 10 && post2 > 0 {
                score += 8.0;
            }
        } else {
            // next item won't fit here: slight penalty proportional to gap
            score += 2.0 + (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Fractional fill reward: prefer bins that become fuller
    let fill = 1.0 - frac;
    score -= 10.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins
    // are nearly full or the fit is terrible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score = bin_capacity as f64 - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        if item_size >= 50 {
            score -= 10.0; // big items start fresh bins happily
        }
    } else if fitting_bins_count == 1 && post_residual < 10 {
        // Forced but wasteful placement; still better than a new bin
        score += 5.0;
    }

    // Mild preference to keep many open bins balanced early on
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Tie-break toward mean residual consistency
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the less leftover, the better (non-linearly).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Strict dead-space penalty: residuals too small for typical future items
    // (1..=10) are waste. Penalize the 1..9 dead zone heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Mid dead zone: residual 10..30 is hard to fill unless a small item comes;
    // scale penalty by how far below mean_residual it sits.
    else if post_residual >= 10 && post_residual < 30 {
        let gap = mean_residual - post_residual as f64;
        if gap > 0.0 {
            score += 8.0 + gap * 0.5;
        } else {
            score += 4.0;
        }
    }

    // Reward residuals that can still host the lookahead item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Bonus if lookahead would leave another usable residual.
            let post2 = post_residual - next_item_size;
            if post2 == 0 {
                score -= 10.0; // perfect two-item packing
            } else if post2 >= 10 {
                score -= 3.0;
            } else {
                score += 10.0; // lookahead would create dead space here
            }
        } else {
            // This bin becomes dead after placement; strong penalty unless
            // post_residual is exactly 0 (perfect fit now).
            if post_residual == 0 {
                score -= 15.0;
            } else {
                score += 12.0;
            }
        }
    } else if post_residual == 0 {
        // Last item: perfect closure.
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // Open-bin pressure: discourage scattering across many bins; but a
    // brand-new empty bin candidate should only win when the fit is poor.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 5.0 + (open_bins_count as f64) * 0.8;
        // If the item would leave a large usable residual in a fresh bin,
        // that's fine; if item is small, opening a bin is wasteful.
        if item_size < 40 {
            score += 25.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    } else {
        // Existing bin: mild preference for bins with below-mean residual
        // (consolidate fullness).
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += dev * 6.0;
        score -= (open_bins_count as f64) * 0.3;
    }

    // Late-stream consolidation: as the stream ends, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits snugly into post residual (small slack)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot fit here, penalize proportionally
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }

    // Penalize leaving residuals that are hard to fill (very small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins with residual close to item size (tight fit overall)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discard the empty new-bin candidate unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
    }

    // Slightly prefer filling bins with smaller mean residual (consolidate)
    score += 0.1 * mean_residual;

    // Early in stream: be more open to new bins; late: consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual is the primary waste term.
    // Squared penalty for larger dead space (non-linear waste aversion).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: if the next item exactly fits the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward residual that remains usable for the next item,
            // scaled by how well it matches (prefer exact-ish fits).
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: mild penalty, worse for big leftovers.
            score += 0.15 * (post_residual as f64 - (post_residual as f64 % next_item_size as f64));
        }
    } else {
        // Last item: only the immediate waste matters; push toward tightest fit.
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // since rejecting it forces a new bin and strands this residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals clean for the long future); late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize normally, but the penalty shrinks
        // when existing fits are poor (large post_residual elsewhere) or
        // early in the stream when preserving flexibility pays off.
        let poor_fit_pressure = (mean_residual / bin_capacity as f64) * 20.0;
        score += 45.0 - 25.0 * (1.0 - progress) - poor_fit_pressure;
        // Never open a new bin if an open bin achieves a near-perfect fit.
        if post_residual <= 5 && fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Existing bin: reward keeping bin count low.
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
        // Bonus for matching the global mean residual (balanced packing).
        score -= 0.05 * (post_residual as f64 - mean_residual).abs().recip().min(5.0);
        // Late stream: extra reward for filling bins completely.
        if progress > 0.8 && post_residual <= 10 {
            score -= 20.0;
        }
    }

    // Discourage leaving residuals in the awkward 30..60 band that few items fit.
    if post_residual >= 30 && post_residual <= 60 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / cap;

    // Base: quadratic penalty on wasted residual, smoothed by progress
    let mut score = pr_n * pr_n * (1.0 + 2.0 * progress) * cap;

    // Non-linear coupling: large post-residual is worse late in the stream
    score += 4.0 * pr_n.powi(3) * cap * progress;

    // Reward tight fits: small post-residual relative to item size
    let item_n = item_size as f64 / cap;
    score -= 6.0 * item_n * (1.0 - pr_n).powi(2) * cap;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * cap * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 3.0 * cap * (1.0 - slack * slack) * (0.5 + progress);
        } else {
            // next item won't fit; penalize proportionally to the gap
            score += 2.0 * ((nx - pr) / cap) * cap * progress;
        }
    }

    // Prefer bins with residuals below the mean (consolidate large gaps elsewhere)
    score += 1.5 * (r - mean_residual).max(0.0);

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += cap * (0.5 + 0.3 * (open_bins_count as f64).ln().max(0.0)) * (1.0 - 0.5 * progress);
        // But allow new bin if it would be near-perfectly filled
        if item_n > 0.9 {
            score -= cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over small moduli.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Dead-space penalty: residuals in awkward classes (1..=9 mod 10, tiny nonzero)
    if pr > 0 && pr < 10 {
        score += 18.0; // unusable sliver
    }
    if pr % 10 != 0 && pr % 10 < 5 && pr >= 10 {
        score += 3.0; // awkward fractional class
    }

    // Perfect-fit harmonic classes: post_residual divisible by common item granules
    if pr == 0 {
        score -= 60.0;
    } else if pr % 25 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: how many "typical" items still fit
    let fits = pr / 10; // min item size granule
    if fits == 0 && pr > 0 {
        score += 10.0;
    }

    // Lookahead coupling: can next item fit exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nxt_post = pr - next_item_size;
            if nxt_post == 0 {
                score -= 25.0; // enables perfect second fit
            } else if nxt_post % 10 == 0 {
                score -= 10.0;
            } else if nxt_post < 10 {
                score += 6.0; // creates sliver after next item
            }
        } else {
            // next item won't fit here; residual becomes dead unless reusable later
            score += 5.0;
        }
        // Harmonic pairing: next_item_size divides residual nicely
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 6.0;
        }
    }

    // Capacity fraction anchoring: prefer residuals near capacity fractions
    let frac = pr as f64 / cap;
    if (frac - 0.5).abs() < 0.05 {
        score -= 5.0; // half-full residual is versatile
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: open fresh bin only if current fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > cap * 0.6
            || (pr > 0 && pr < 10)
            || (next_item_size > 0 && next_item_size > pr && pr < 20);
        if bad_fit {
            score -= 45.0;
        } else {
            score += 30.0;
        }
    }

    // Stream progression: early on, be greedy-tight; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;

    // Tie-break toward bins below mean residual (tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight penalty per open bin to discourage bin sprawl
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals too small for typical items (1..=10) are wasted.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose residual was already small (best-fit flavor beyond raw post_residual).
    score += 0.3 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., this empty-bin call has post_residual == capacity - item_size).
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral residual, but add opening cost.
        score += 25.0;
        // If the item would leave a large usable residual, opening a new bin is fine.
        if post_residual >= 20 {
            score -= 20.0;
        }
        // If many bins are open, prefer consolidating instead of a new one.
        score += 3.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 30.0;
    }
    // Penalize placements that leave residual just below next item size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Slight drift over stream: early on, be conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // Nudge toward bins below mean residual (tighter bins get used first).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: residuals too small to be useful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // exact match for the next item is excellent
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: leftover likely becomes dead space
        score += 8.0;
    }

    // Compare fit tightness relative to mean residual across open bins
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    if mean_residual > 0.0 {
        // prefer bins that are tighter (smaller residual) than average
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when no decent fit exists,
    // but allow it when existing bins would create large dead space
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin is fine for the next item
        }
    }

    // Late in the stream, consolidate: discourage opening new bins
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead); // unusable slivers
        } else {
            // Dead space is only useful if a future item could fit it; scale by
            // how close it is to typical item sizes (mid-range ~50).
            let usefulness = 1.0 - ((dead - 50.0).abs() / 50.0).min(1.0);
            score += 8.0 * (1.0 - usefulness);
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting this bin's fit.
        score += 5.0;
    }

    // Scarcity: if this is the only bin that can fit the item, favor using it.
    if fitting_bins_count <= 1 {
        score -= 15.0;
    } else {
        // Many alternatives: be picky, demand a really good fit.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: prefer filling bins when many are open (bin-count pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / 20.0).min(1.0);
    score -= 10.0 * pressure * (0.5 + 0.5 * progress);

    // Compare bin residual to mean residual: prefer using below-average-residual
    // bins (compact them) when pressure is high, prefer above-average when low.
    let rel = bin_residual as f64 - mean_residual;
    score += (if pressure > 0.5 { -0.05 } else { 0.05 }) * rel;

    // New-bin candidate: opening a new bin wastes the residual of all open bins.
    // Only allow it if the item fits poorly everywhere; make empty bin costly.
    if bin_residual == bin_capacity {
        let escape_threshold = 20.0 + 40.0 * pressure;
        // Attractive only when post_residual is small (item nearly fills a bin)
        // or when open bins are few and stream is early.
        let fresh_bonus = if post_residual as f64 <= escape_threshold {
            -12.0 * (1.0 - post_residual as f64 / bin_capacity as f64)
        } else {
            6.0 + 10.0 * pressure
        };
        score += fresh_bonus - 4.0 * progress;
    }

    // Small deterministic tie-breaker based on residual parity structure.
    score += 0.01 * ((bin_residual % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: penalize leftover space, with a super-linear waste cost.
    let mut score = pr * (1.0 + 0.9 * (pr / cap).powi(2));

    // Smooth interaction: leftover hurts more as the stream progresses.
    score += 6.0 * pr * progress / cap;

    // Reward tight fits (high fit_ratio), smoothly saturating.
    score -= 12.0 * fit_ratio * (1.0 - fit_ratio);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize more early, allow opening later when
    // open bins are crowded (mean residual low relative to item).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 - 14.0 * progress;
        score += 0.05 * open_bins_count as f64 * (1.0 - progress);
        if next_item_size > 0 {
            let gap = (next_item_size as f64 - pr).max(0.0) / cap;
            score += 8.0 * gap * (1.0 - progress);
        }
    } else {
        // Lookahead: bonus if next item fits the post-residual smoothly.
        if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
            score -= 4.0 * (next_item_size as f64 / cap);
        }
        // Penalize bins deviating from mean residual (keeps balance).
        score += (mean_residual - pr).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: exact-fill is perfect; small dead space (<10) is dead weight.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Residual classes by quarter-capacity (harmonic fractions).
    let q = (post_residual as f64 / cap * 4.0).floor() as i32;
    score += match q { 0 => 12.0, 1 => 0.0, 2 => -6.0, _ => -10.0 };

    // Coupling with lookahead: reward leaving room for next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Tight fit bonus.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= tight * tight * 20.0;

    // Late-stream consolidation pressure.
    let prog = step_index as f64 / total_items.max(1) as f64;
    score -= prog * mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // Next item would leave another dead gap: mildly discourage.
        score += 5.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 20 {
        // Next item leaves a still-usable residual: reward the chain.
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is cheap early (many items
    // remain to fill it) but expensive late. Also discourage opening new bins
    // when many bins are already open (open-bin pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 30.0 * progress + 1.5 * open_bins_count as f64;
        // But if the current item is large relative to mean residual, a fresh
        // bin may still be the cleanest choice.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond the
    // raw post_residual ordering.
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let pre = bin_residual.max(1) as f64;
    let post_u = post_residual;
    let post = post_u as f64;
    let item = item_size as f64;
    let next_u = next_item_size;
    let next = next_u as f64;
    let mean = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        pre
    };
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let remaining = 1.0 - progress;
    let is_new_bin = bin_residual == bin_capacity;
    let fits = fitting_bins_count as f64;
    let fill_ratio = (item / pre).clamp(0.0, 1.0);

    let mut score;

    if next_u > 0 {
        let pressure = 1.0 - (mean / next).clamp(0.0, 1.0);

        if post_u == next_u {
            score = 0.0;
            score -= 4.0 + 5.0 * remaining + 3.0 * pressure;
        } else if post_u > next_u {
            score = post - next;
            score -= 2.0 + 6.0 * (next / post) + 4.0 * pressure * (next / cap);
            score += 0.04 * (post - next).min(cap);
        } else {
            let gap = next - post;
            score = post + gap * (0.30 + 0.35 * pressure);
        }

        let d = ((post - next).abs() / cap).clamp(0.0, 1.0);
        score -= 4.0 * (1.0 - d) * (1.0 - d);
    } else {
        score = post;
        if post_u == 0 {
            score -= 10.0;
        }
    }

    score -= 4.0 * fill_ratio;
    score += 0.05 * (post - mean).clamp(-cap, cap);

    if is_new_bin {
        let mut open_cost = 32.0
            + 8.0 * progress
            + 0.6 * open_bins_count as f64
            + 0.9 * fits
            + 4.0 * (mean / cap);

        if next_u > 0 && post_u == next_u {
            open_cost *= 0.40;
        } else if next_u > 0 && post_u > next_u {
            open_cost *= 0.75;
        }

        if fitting_bins_count == 0 {
            open_cost = -cap;
        }

        score += open_cost;
    } else if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * fill_ratio;
        if next_u > 0 && post_u >= next_u {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fill ratio of the bin before placement
    let fill = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    // Perfect fit: strongly reward zero residual
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item exactly fills the post-residual, huge bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    }
    // Next item fits comfortably in the leftover space
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 * (next_item_size as f64 / post_residual as f64);
    }
    // Next item would NOT fit here: penalize leaving awkward gaps
    else if next_item_size > post_residual && post_residual > 0 {
        score += 20.0 + 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins (waste-aware): reward high fill ratio
    score -= 40.0 * fill * fill;

    // Penalize small dead space (unusable slivers) more than large usable space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Global state coupling: when many bins are open, discourage opening new ones
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty, softened late in the stream
        score += 60.0 - 30.0 * progress;
        // If mean residual across open bins is small, opening a new bin is justified
        if mean_residual < item_size as f64 {
            score -= 70.0;
        }
        // If many bins can fit, definitely avoid a new bin
        if fitting_bins_count > 2 {
            score += 50.0;
        }
    } else {
        // Reward placing into bins whose residual matches mean residual (balance)
        score -= 10.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));
    }

    // Mild time-horizon term: early on, be conservative; late, pack aggressively
    score -= 15.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0, 1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0, 1]

    // Smooth polynomial coupling: waste penalty grows super-linearly with
    // post-residual, and even more so late in the stream (compaction phase).
    let coupling = norm_pr * norm_pr * (1.0 + progress * 2.0);
    score += 30.0 * coupling;

    // Cubic interaction: heavily penalize mid-range dead space late in stream
    score += 15.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward bins whose post_residual can accommodate the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 12.0 * (1.0 - slack) * progress.min(1.0);
        } else {
            // Post-residual too small for next item: penalize proportionally
            let gap = (n - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps the pool of open bins homogeneous and reusable)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Many open bins: slight pressure to fill existing bins rather than spread
    let ob = open_bins_count as f64;
    score += 0.5 * ob * norm_pr * progress;

    // New-bin candidate: make it mildly unattractive unless post_residual is
    // exactly full capacity (it is) and existing fits are poor; the coupling
    // terms above make poor existing fits compete with it.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable" classes
    // (residuals that common small items can fill) are favored.
    let pr = post_residual;
    // Class A: post_residual divisible by small harmonics (10,20,25,50) -> highly reusable
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fill
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -7.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        3.0 // awkward residual, penalize
    };
    score += harmonic_bonus;

    // Coupling with next item: if next item exactly fits post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr && (pr % next_item_size == 0) {
            score -= 10.0; // next item divides residual: future perfect packing
        } else if next_item_size > pr {
            score += 6.0; // next item won't fit here; residual likely dead space
        }
        // integer-division threshold: residual bucket vs next item size
        let bucket = pr / 10; // residual in deciles
        let n_bucket = next_item_size / 10;
        if bucket >= n_bucket && bucket - n_bucket <= 1 {
            score -= 4.0; // near-fit next item
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open fits are terrible.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap - item_size as f64; // post_residual of fresh bin = cap - item
        // penalize opening when decent fits exist
        if fitting_bins_count > 0 {
            score += 20.0 + mean_residual * 0.1;
        }
        // late in stream, avoid opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // tightness reward: small positive post_residual means tight fit
        if pr > 0 && pr <= 10 {
            score -= 6.0;
        }
        // many open bins: prefer consolidating into fuller bins
        score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap) * 2.0;
        // prefer bins below mean residual (fuller bins) mildly
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..)
    // can use are wasted. Penalize tiny unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead gap below smallest plausible item
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    }
    // Penalize blocking the next item while it still fits elsewhere poorly.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when few exist,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // New-bin candidate: only attractive when current bin fits are bad.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual > 0 && post_residual < 10 { 60.0 } else { 0.0 };
        score = 70.0 + 2.0 * open_bins_count as f64 - bad_fit_penalty;
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0;
        }
    }

    // Mild tie-break: prefer bins with residual near mean (balanced packing).
    score -= 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: exact match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 0.9;
        // Perfect chain: place next item exactly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Small gap that next item can still leave a tight residual.
        if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 12.0;
            } else if gap > 40 {
                score += 6.0; // leaves a big awkward hole
            }
        }
        // Next item does NOT fit here: this bin becomes dead space after placement.
        if next_item_size > post_residual && post_residual > 0 {
            score += 10.0 + post_residual as f64 * 0.15;
        }
    } else {
        // Last item: prefer minimal residual.
        score += 0.0;
    }

    // Tightness reward: leaving tiny residual is excellent (near-perfect packing).
    if post_residual <= 3 {
        score -= 18.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist and item is small.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin is fine if next item is large too
        }
        if fitting_bins_count > 0 && item_size <= 50 {
            score += 15.0; // discourage new bin for small items
        }
        score += open_bins_count as f64 * 0.5;
    }

    // Late-stream consolidation: fewer open bins preferred as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space after placement (wasted capacity).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead * dead;

    // Lookahead: reward if next item can fit into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let pair_fit = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * pair_fit;
        } else {
            score += 5.0;
        }
        // Bonus if post residual exactly matches next item (perfect chaining).
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more willing to open bins (favor tight fits
    // less aggressively so future items have room); late in stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 * dead;
    score -= progress * 10.0 * fill_ratio;

    // Global state coupling: if mean residual is low (bins nearly full), prefer
    // consolidating into existing bins; if mean residual is high, allow spreading.
    let mr = mean_residual / bin_capacity as f64;
    score += mr * 6.0 * (1.0 - fill_ratio);

    // Penalize opening a brand-new bin when existing bins fit decently.
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost, discounted when item is large or few bins fit.
        let size_frac = item_size as f64 / bin_capacity as f64;
        let discount = if fitting_bins_count == 0 { 50.0 } else { fitting_bins_count as f64 };
        score += 12.0 - 10.0 * size_frac + 4.0 / discount;
        // Opening a new bin early is fine (many future items); late, avoid it.
        score += progress * 15.0;
    }

    // Mild penalty for too many open bins (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Core waste term: non-linearly penalize leftover space (super-linear).
    let pr = post_residual as f64;
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth progress coupling: waste becomes more costly later in the stream.
    score += 1.5 * progress * (pr * pr) / (cap * cap);

    // Tight-fit reward: small post_residual relative to capacity is heavily favored.
    let tightness = 1.0 - (pr / cap);
    score -= 4.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 3.0 * (1.0 - slack) * (1.0 - slack);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): post_residual is large, so core waste already penalizes it;
    // add a mild extra penalty that decays as open bins become scarce/poor.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 2.0 + 6.0 * scarcity * (1.0 - progress);
    }

    // Mild preference to balance residuals across open bins.
    score += 0.3 * ((mean_residual - pr).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: bins whose leftover falls into "usable"
    // residue classes (small leftovers that future small items can absorb).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Dead-space penalty: leftover too small for the minimum item (1..10),
    // but not tiny enough to be harmless -> wasted capacity.
    if post_residual > 10 && post_residual < 20 {
        score += 45.0;
    }

    // Harmonic division thresholds: leftover that exactly admits half/quarter
    // capacity slabs is attractive (modular alignment with capacity fractions).
    if bin_capacity % post_residual.max(1) == 0 && post_residual > 0 {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits exactly in the post-residual;
    // penalize if next item is just slightly too big (near-miss is worst).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual + 10 {
            score += 35.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: opening a new bin is only good when no open bin
    // offers a decent fit; make the empty bin mildly unattractive by default
    // but competitive when all open residuals are small relative to item.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * mean_residual - 10.0 * (fitting_bins_count == 0) as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // pairing large items in fresh bins
        }
    }

    // Mild stream-pressure coupling: later in stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since items are >= 1 and typical streams leave such gaps unrecoverable.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual <= 19 {
        score += 25.0;
    } else if post_residual <= 34 {
        score += 8.0;
    }

    // Reward tight fits: the smaller the post_residual relative to bin capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across too many bins.
    score += 2.5 * open_bins_count as f64;

    // Penalize bins whose residual is far above the mean residual (they are poor candidates
    // to consolidate into), but reward bins close to the mean (balanced packing).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 9 {
            score += 20.0; // next item would create dead space here anyway
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    }

    // Mild progression bias: later in the stream, prefer using existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack -> reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space: next item does NOT fit the leftover -> penalize proportionally.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 12.0 + 0.35 * post_residual as f64;
    }

    // Tight fit reward: how full the bin becomes relative to capacity.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Penalize residuals far below mean (wasting space in already-loose bins)
    score -= 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Early stream: be slightly greedy to consolidate; late stream: keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress) * fill;

    // New empty bin candidate: make it attractive only when its post_residual
    // is large (i.e., item is small) and few bins fit the item poorly.
    if bin_residual == bin_capacity {
        score += 5.0; // mild default penalty; tight fits above overcome it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still serves the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize large dead space relative to typical item size
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 120.0;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(2.0);
        } else {
            // residual too small for next item: penalize proportionally to waste
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Favor bins tighter than average (best-fit style)
    score += (mean_residual - bin_residual as f64) * 1.5;

    // New-bin candidate: discourage unless current bin would leave tiny unusable space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = (bin_residual - item_size) as f64;
        // open a new bin if placing here would strand a lot of space relative to progress
        score += 150.0 - dead * (0.5 + 2.0 * progress);
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 60.0; // new bin keeps flexibility for next item
        }
    }

    // Early stream: prefer consolidation into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Core: penalize leftover space, quadratically (dead space is worse than linear).
    let mut score = post + 0.9 * (post / cap) * post;

    // Tight-fit reward: small post_residual relative to item size is great.
    let tightness = 1.0 - post / (item + 1.0);
    score -= 6.0 * tightness * tightness.max(0.0);

    // Non-linear coupling with stream progress: early on, prefer filling bins
    // aggressively (leave little waste); later, prefer preserving flexibility.
    let flex = (post / cap) * (0.5 + 0.5 * progress);
    score -= 4.0 * flex * (1.0 - progress) * (1.0 - progress);

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size as f64 <= post {
        let gap = (post - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - gap) * (1.0 - progress);
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when good open bins exist; allow it when
    // residuals are nearly exhausted or many bins already open (spread load).
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.5);
        score += 3.0 + 2.0 * open_pressure * (1.0 - progress);
        // But if mean residual is small (bins nearly full), new bin is fine.
        score -= (mean_residual / cap).min(1.0) * 4.0;
    }

    // Mild preference for bins already below mean residual (balance waste).
    score += 0.5 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // (multiples of common item-size classes) and penalize awkward dead space.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals divisible by 10 are harmonically ideal (align with 10..80 grid).
        score -= if class == 0 { 12.0 } else if class <= 2 { 4.0 } else { -2.0 * (class as f64) / 10.0 };
    } else {
        // Perfect fill is the best outcome.
        score -= 25.0;
    }

    // Integer-division thresholds: how many more "average" items fit?
    let avg_next = if next_item_size > 0 { next_item_size as f64 } else { 45.0 };
    let fits_next = if pr >= next_item_size && next_item_size > 0 { 1.0 } else { 0.0 };
    score -= 10.0 * fits_next;

    // Coupling: post_residual close to next_item_size is a great pairing.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leaving a residual that no plausible item can use (dead space).
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is costly unless the item is
    // large relative to capacity (would leave a bad residual in any open bin).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 0.15 * open_bins_count as f64;
        // Reward opening a new bin for big items that would fragment open bins.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 25.0 * (frac - 0.5) * 2.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 8.0 * fitting_bins_count as f64;
        }
    } else {
        // Prefer fuller bins (tight fit reward).
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 8.0 * fill;
    }

    // Prefer bins whose residual is near the mean residual (balanced packing),
    // with a harmonic twist: only when mean residual is in a "good" class.
    let mr_class = (mean_residual as u32) % 10;
    let mean_weight = if mr_class == 0 { 0.3 } else { 0.1 };
    score += mean_weight * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for older bins (close them out over time).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Harmonic bonus: post_residual sharing a divisor class with next item.
    if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the minimum
    // future item (1..=10) are pure waste. Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // "Awkward gap" zone: too big to ignore, too small for typical items.
    else if post_residual < 25 {
        score += 12.0 + (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into post_residual,
    // strongly prefer this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use the leftover gap -> mild penalty
            score += (post_residual as f64) * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // fit is mediocre; encourage reusing bins when many are open.
    let pressure = open_bins_count as f64 * 0.6;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, heavily favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to consolidate load.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: keep it neutral-to-slightly-costly so it only wins
    // when all open bins have bad fits (their dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + pressure;
    }

    // Mild stream-progression tilt: later in the stream, waste matters more
    // (fewer chances to amortize it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit lookahead: strongly reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch scaled by how far next item is from fitting.
            score += diff * 0.35;
        }
        // Penalize leaving residual that cannot hold next item at all (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
        // Reward residual large enough to still be useful later.
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual) — already base term.
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps the fleet balanced.
    let pr = post_residual as f64;
    let mean_gap = (pr - mean_residual).abs();
    score += mean_gap * 0.08;

    // Penalize very small post_residual (fragmentation / unusable slivers),
    // unless it is an exact fit already rewarded above.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (new empty bin has post_residual = capacity - item).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when a reasonable fit exists in an open bin:
    // new-bin candidate has bin_residual == bin_capacity; penalize it mildly
    // unless the fit into open bins would be terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item would perfectly fill a fresh bin after this item, allow it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear squash.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the resulting residual, big reward;
    // if the residual is a dead zone (too small for next item but nonzero), penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 && post_residual < 10 {
            score += 12.0 * (1.0 - post_residual as f64 / 10.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when a tighter option exists:
    // prefer bins whose residual deviates from the mean (consolidate large residuals).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Time horizon: early in the stream be conservative (keep flexibility),
    // later in the stream be aggressive (fill bins tightly).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * fit_ratio;
    score -= 6.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // last chance exists: prefer existing bin
        } else {
            // Attractiveness of a fresh bin grows with how loose the best fits are.
            score += 5.0 + 0.1 * open_bins_count as f64 - 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: post_residual scaled by capacity, shaped by progress.
    let x = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth interaction: waste penalty grows with progress for mid-range residuals
    score += 18.0 * x * (1.0 - x) * (0.5 + p) * cap * 0.1;
    // Penalize very large leftover less early, more late (smooth quartic term)
    score += 10.0 * x.powi(4) * (0.3 + 0.7 * p);
    // Reward tight fits (small post_residual) increasingly over time
    score -= 12.0 * (1.0 - x).powi(3) * (0.4 + 0.6 * p);

    // Lookahead coupling: if next item fits the post residual, reward smoothly
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as i32 as f64;
        let nx = next_item_size as f64 / cap;
        score -= 14.0 * fits * (1.0 - (nx - x).abs()) * (0.5 + 0.5 * p);
        // Penalize post residual that blocks next item
        score += 8.0 * (1.0 - fits) * nx * (0.4 + 0.6 * p);
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * p);
    }

    // New-bin candidate: make empty bins mildly attractive early, less late
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - p) - 4.0 * p;
    }

    // Mean residual deviation: prefer bins whose residual is near mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * (0.5 + 0.5 * p);

    // Mild penalty for many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot class" does the leftover fall into?
    // Classes of 10 units (classic harmonic bin packing granularity).
    let class = post_residual / 10;
    let frac = (post_residual as f64) / cap;

    // Reward large post_residual classes (usable leftovers), but only up to a point:
    // residuals that exactly match common item sizes are gold.
    let harmonic_reward = match class {
        0 => -8.0,              // near-perfect fit: dead space < 10 is excellent
        1 => -3.0,              // leftover 10..19: fits smallest items
        2 => 1.5,               // leftover 20..29: moderately useful
        3 => 0.5,               // leftover 30..39
        4 => 2.0,               // leftover 40..49: awkward class
        5 => 1.0,
        6 => 2.5,               // 60..69: awkward
        7 => 1.5,
        8 => 2.0,
        9 => 0.0,
        _ => 0.0,
    };
    score += harmonic_reward;

    // Exact-harmonic bonus: post_residual is a multiple of common sizes (10/20/25/50).
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0) {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how snugly
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 2.0 + 6.0 * snug;
        } else {
            // next item cannot use this leftover: penalize awkward leftovers
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap).min(1.0) * 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.25 * (post_residual as f64);
    }

    // New-bin candidate handling: opening a bin is only attractive when the item is
    // large relative to capacity (it would dominate a fresh bin anyway).
    if bin_residual == bin_capacity {
        let item_frac = (item_size as f64) / cap;
        score = cap - (item_size as f64); // baseline: leftover of a fresh bin
        score -= 3.0 * item_frac;         // large items prefer fresh bins
        if fitting_bins_count == 0 {
            score -= 20.0;                // no alternative: must open
        }
    }

    // Progress-based tightening: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (frac * 4.0);

    // Slight preference for bins with below-mean residual (consolidate emptier bins).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible
    // follow-up item are pure waste — penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Squared dead-space term: moderate gaps are also increasingly costly.
    score += (post_residual as f64).powi(2) / 100.0;

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when the fit
    // into open bins is bad (large post_residual or dead space).
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score = 30.0 + fit_quality * 50.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory
        }
    }

    // Mild stream-progression damping.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
