pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer leaving small post-residual, but with diminishing returns
    // (wasting a large bin on a tiny leftover is worse than the raw number suggests)
    let mut score = post * (1.0 + 0.35 * (post / cap).powi(2));

    // Tight-fit reward: item filling most of the residual
    let fill_ratio = item / bin_residual as f64;
    score -= 18.0 * fill_ratio.powi(3);

    // Perfect-fit style bonus when post residual is very small
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead-space penalty: leftover that is smaller than the smallest plausible item (1)
    // Here: leftover below 10 is nearly unusable for typical streams; penalize mildly
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10.0 - post) / 10.0;
    }

    // Lookahead coupling: if the next item can fit exactly into the post residual,
    // strongly favor this bin (chain fit)
    if next > 0.0 {
        if (post - next).abs() < 0.5 {
            score -= 30.0;
        } else if next <= post {
            // next item fits: reward proportionally to how well it fills the leftover
            score -= 10.0 * (next / post);
        } else {
            // next item will NOT fit here: this bin becomes dead weight for the chain
            score += 6.0 * (next - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity):
    // opening a new bin is attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        let mut new_bin_score = cap - item; // same base as others
        new_bin_score += 20.0; // inherent opening cost
        // if the item leaves a large hole in an existing bin, opening new bin is better
        if fill_ratio < 0.35 {
            new_bin_score -= 10.0;
        }
        // early in the stream, keep options open; late, consolidate
        new_bin_score -= 12.0 * (1.0 - progress);
        // many open bins with high mean residual: prefer reusing
        if open_bins_count > 0 && mean_residual > item {
            new_bin_score += 8.0;
        }
        return new_bin_score;
    }

    // Global state: many open bins -> encourage consolidating into fuller bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Mean residual coupling: if this bin is much emptier than average, slightly
    // deprioritize it (save roomy bins for big future items)
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res - mean_residual) / cap;
        score += 6.0 * dev;
    }

    // Late-stream tightening: as stream ends, strongly prefer minimal post residual
    score += 10.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual
    let dead = (pr as f64 - mean_residual).abs();
    score += 5.0 * (dead / cap) * (dead / cap) * 100.0;

    // Lookahead: reward if next item fits post_residual
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0 * (1.0 - (next_item_size as f64 / cap));
        } else {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    // Discard opening new bins when a decent fit exists
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (harmonic classes of capacity)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else {
        // Harmonic class penalty: residual in "awkward" classes (11..=30) is dead space
        let pr = post_residual;
        if pr >= 11 && pr <= 30 {
            score += 40.0 + (30 - pr) as f64 * 2.0;
        } else if pr >= 31 && pr <= 60 {
            score += 10.0;
        }
        // Fractional capacity coupling: penalize residuals that are neither tiny nor reusable
        let frac = pr as f64 / cap;
        score += 50.0 * frac * frac;
    }

    // Lookahead: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= 80.0 - nxt_post as f64 * 0.5;
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted fraction
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score = 120.0 + 200.0 * (1.0 - crowded);
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: new bin is necessary
        }
        if next_item_size > 0 && next_item_size >= post_residual && next_item_size <= bin_capacity {
            score -= 30.0;
        }
        // Early in stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * (1.0 - progress);
    }

    // Mild preference to fill bins with many occupants (low mean residual context)
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Favor bins whose residual was already small (tight packing).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Pressure from number of open bins: discourage opening/keeping too many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else if gap < 10 {
            score += 20.0; // would create a dead gap for the next item
        } else {
            score -= 5.0;
        }
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced packing),
    // but only mildly, so dead-space logic dominates.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: only attractive when existing bins would waste a lot
    // or when the stream is early and spreading items is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 + 50.0 * progress + 3.0 * open_bins_count as f64;
        if item_size == bin_capacity {
            score = -1000.0; // must open a bin for a full-size item
        }
        if fitting_bins_count == 1 && post_residual >= 0 {
            // competing with a last-chance bin: make new bin slightly worse
            score += 10.0;
        }
    }

    score
}

