    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: slight penalty to encourage diversity of choice.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large relative to capacity or few bins fit it.
    if bin_residual == bin_capacity {
        let tightness = item / cap;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Early on, opening bins is cheap; later, prefer filling existing ones.
        let time_cost = 40.0 * progress;
        score = 60.0 - 30.0 * tightness - 25.0 * scarcity + time_cost + 2.0 * open_bins_count as f64;
    }

    // Global state: high mean residual means bins are roomy; penalize
    // placements that fragment space disproportionately vs. the average.
    let frag = (post - mean_residual) / cap;
