    // early on, large residuals are acceptable; late in the stream,
    // penalize them super-linearly to squeeze bins tight.
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth saturating bonus.
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness;

    // Dead-space penalty: residuals too small for the smallest plausible
    // future item are wasted; penalize smoothly around the threshold.
    let dead = ((30.0 - pr).max(0.0)) / 30.0;
    score += 10.0 * dead * dead;

    // Lookahead: favor bins whose post-residual still accommodates the next item.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (next_item_size as f64 / cap);
