        let balance = 1.0 - ((pr - mean_residual).abs() / cap).min(1.0);
        score -= 3.0 * balance;
    }

    // Smooth pressure term: many open bins -> encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress) * pr_norm;

