    // Harmonic class of post_residual (decile buckets): small leftovers are good
    let cls = pr / 10;
    score += match cls {
        0 => -6.0,
        1 => -4.0,
        2 => -2.5,
        3 => -0.5,
        4 => 1.0,
        5 => 2.5,
        _ => 4.0,
    };

    // Reward bins whose leftover can host the lookahead item
    if next_item_size > 0 && pr >= next_item_size {
        score -= 3.0;
        let rem = pr - next_item_size;
        // Perfect harmonic chain: leftover after lookahead is a clean decile
        if rem % 10 == 0 {
            score -= 2.0;
        }
        if rem <= 10 {
            score -= 1.5;
        }
    } else if next_item_size > 0 {
        // Dead space for the next item
        score += 2.5;
        // Penalize if next item is close to fitting (wasted opportunity)
        if next_item_size - pr <= 10 {
            score += 1.5;
        }
    }

    // Exact modulo alignment of current leftover
    if pr % 10 == 0 && pr > 0 {
        score -= 1.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.5;
    }

    // New-bin candidate: penalize so we only open when no decent fit exists,
    // but relax the penalty late in the stream or when open bins are congested
    if bin_residual == bin_capacity {
        score += 9.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress;
        if mean_residual < cap * 0.25 && open_bins_count > 0 {
            score -= 2.0;
        }
    }

    // Mild congestion bonus: spreading load across many open bins
    score -= 0.15 * open_bins_count as f64;

    // Favor bins whose residual is close to mean (keeps balance of classes)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the smallest possible item (1) can't occur, but gaps that no
