            }
        } else {
            // Dead space for the next item: penalize proportionally to gap.
            score += 0.8 * gap;
        }
    } else {
        // Last item: only tightness matters.
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual below the mean wastes space in a fragmented bin.
    if (post_residual as f64) < mean_residual {
        score += 0.6 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 {
            let gap = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() as f64;
            30.0 * (1.0 - gap / bin_capacity as f64)
        } else {
            0.0
        };
