    // Mildly prefer filling bins with more open bins already active
    score -= 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Core: prefer small post-residual, with non-linear shrink for tight fits
    let mut score = pr * (1.0 + 0.8 * (1.0 - fit_ratio).powi(3));

    // Reward tight fits more strongly as stream progresses
    score -= 30.0 * fit_ratio.powi(2) * (0.5 + progress);

    // Penalize leaving dead space that no plausible item can use
    let dead = (pr / cap).powi(2) * (1.0 + 2.0 * progress);
    score += 25.0 * dead;

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 35.0 * waste * (1.0 + 0.5 * pressure) - 10.0 * progress;
    }

    // Lookahead: if next item could reuse post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let reuse = next_item_size as f64 / pr.max(1.0);
        score -= 12.0 * reuse * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "usable" class (small or divisible into common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are exact multiples of common item denominations
        let harmonics: [u32; 6] = [10, 20, 25, 50, 33, 100];
        let mut harmonic_bonus = 0.0;
        for h in harmonics.iter() {
            if pr % h == 0 {
                harmonic_bonus += 8.0;
            }
        }
        score -= harmonic_bonus;

        // Classify post_residual into integer-division bands (harmonic classes)
        let class = pr / 10; // 0..=10
        match class {
            0 => score -= 25.0,                 // near-perfect fit
            1 => score -= 15.0,                 // small dead space
            2 | 3 => score -= 5.0,              // medium: often fillable
            4 | 5 => score += 10.0,             // awkward half-full zone
            6 | 7 => score += 5.0,              // large residual: decent
            _ => score -= 12.0,                 // nearly empty bin: keep flexible
        }

        // Dead-space penalty if next item cannot fit the leftover
        if next_item_size > 0 {
            if next_item_size > pr {
                score += 12.0 + 0.15 * (next_item_size - pr) as f64;
            } else {
                // reward when leftover exactly harmonizes with next item
                if pr == next_item_size {
                    score -= 20.0;
                } else if (pr - next_item_size) <= 5 {
                    score -= 10.0;
                }
                // modulo coupling: leftover splits evenly around next item
                if pr % next_item_size.max(1) == 0 {
                    score -= 6.0;
                }
            }
        }
    } else {
        // Perfect fill: strongly favored
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 45.0 - 20.0 * progress;
        // If many open bins fit the item, opening new is wasteful
        if fitting_bins_count > 0 {
            nb += 25.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If mean residual is large, prefer existing bins
        nb += (mean_residual - 30.0).max(0.0) * 0.3;
        score += nb;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Prefer tighter fits overall
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: residuals too small for any item (1..=10)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Moderate dead space: penalty scaled by how far it is from being
    // reusable by the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }
    // Reward if the next item fits exactly into the resulting gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Open-bins pressure: discourage spreading across many bins when the
    // item fits comfortably (post_residual still generous).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.5 + progress);
    if post_residual >= 40 {
        score += pressure;
    } else {
        score += pressure * 0.25;
    }

    // Last-resort bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mean residual alignment: prefer bins whose leftover stays near the
    // fleet mean (keeps gaps usable across bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Slight preference for filling fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (no dead space created).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0; // chain fit: this bin will be perfectly completed next step
        } else if next_item_size <= post_residual {
            // next item fits inside the leftover space: mild reward scaled by tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 100.0 * tightness;
        } else {
            // next item cannot use the leftover space: penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(60.0) * 2.0;
        }
    }

    // Penalize creating small unusable residuals relative to mean residual.
    if post_residual > 0 {
        let small = (mean_residual - post_residual as f64).abs();
        if post_residual < 10 {
            score += 150.0; // tiny dead space is nearly worthless
        }
        score += small * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when it beats poor fits,
    // i.e. an empty bin has full residual but we discourage premature opening
    // when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in the stream, avoid spawning bins with tiny expected leftovers.
        if next_item_size > 0 && next_item_size > bin_capacity - 10 {
            score -= 50.0; // next big item will need a fresh bin anyway
        }
    }

    // Slight preference for tighter bins overall (low residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Stream progression: as we near the end, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 40.0 * (open_bins_count.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.9;

    // Penalize leaving dead space that no typical item (>= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward if next item fits the post residual, punish if not.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= next_item_size as f64 * 0.6;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin, less so early or
    // when many bins are open and mean residual is high (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 15.0 + 35.0 * progress - 20.0 * fragmentation;
        // If current item is huge relative to capacity, new bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with residual close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // Slight preference for fuller bins (smaller residual) among open bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post_residual, non-linearly scaled by stream progress.
    // Late in the stream, residual space becomes more costly (less chance to fill it).
    let poly = 1.0 + 0.8 * progress + 0.6 * progress * progress;
    let mut score = pr * poly;

    // Penalize very small dead space quadratically (unusable slivers).
    let dead = pr / cap;
    score += 6.0 * dead * dead * cap;

    // Reward tight fits: small post_residual relative to item size.
    let item = item_size as f64;
    let tightness = 1.0 - (pr / (item + 1.0)).min(1.0);
    score -= 4.0 * tightness * tightness * item / cap;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * gap / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins vs. mean residual alignment.
    score += 0.05 * open_bins_count as f64 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: only attractive when existing bins would leave large waste.
    if bin_residual == bin_capacity {
        // Neutral baseline; slightly discourage early, encourage late if mean residual is poor.
        score = pr * poly + 3.0 - 5.0 * progress + 0.5 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are "harmonic" with common
    // item sizes (multiples of 10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        40.0 // perfect fit is ideal
    } else if pr % 50 == 0 || pr % 25 == 0 {
        18.0
    } else if pr % 10 == 0 {
        12.0
    } else if pr % 20 == 0 {
        14.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: small unusable residuals (< 10, min item size).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Coupling with next item: if next item exactly matches post_residual,
    // this bin is a perfect two-item chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if pr < next_item_size && pr > 0 {
            // residual can't serve next item: mild penalty scaled by how far off
            let gap = (next_item_size - pr) as f64;
            score += (gap / 20.0).min(8.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin, more so late in the stream
    // and when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let consolidation = (open_bins_count as f64).ln().max(0.0);
        score += 45.0 + 25.0 * progress + 5.0 * consolidation;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (fill the fullest bins first, keep slack concentrated).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= (dev * 0.3).min(12.0);
    } else {
        score += (-dev * 0.15).min(8.0);
    }

    // Integer-division threshold on post_residual: residuals in [10, 30) are
    // "one small item" zones; encourage compacting them.
    if (pr / 10) >= 1 && (pr / 10) <= 2 && pr % 10 != 0 {
        score += 4.0; // awkward non-harmonic mid zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized dead space.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tightness relative to bin capacity (tight fill = good).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly; reward it. If next item cannot fit,
    // slight penalty for fragmenting this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well
        // or the stream is early and few bins are open.
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 + pressure * 3.0
            - desperation * 30.0
            - (1.0 - progress) * 10.0;
        // If a last-chance bin exists, strongly discourage a new bin.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    } else {
        // Existing bin: reward being the last chance (avoid opening new bins).
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer bins whose residual is near the mean (balanced packing).
        score -= 5.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));
        // Mild preference for fuller bins as stream progresses.
        score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score -= 0.35 * item_size as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item could chain into this bin: reward exact/near matches
            score -= 0.6 * (post_residual as f64 - gap * 0.8);
        } else {
            // dead space relative to next item: penalize
            score += 0.25 * gap;
        }
    }

    // Compare residual against mean residual across open bins
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize the new-bin candidate unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 12.0;
        // allow new bin when lookahead suggests a perfect future chain is unlikely
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Mild pressure to consolidate early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.5 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly penalize large post-residuals that are unusable dead space
    // (smaller than the minimum conceivable item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 3.0;
    }

    // Reward tight fits: exponential reward for small post_residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly into the post-residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 18.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            let miss = next_item_size - post_residual;
            score += 6.0 * (miss as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer fullest packing, tie-break irrelevant
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
        if post_residual < 15 {
            score -= 15.0;
        }
    }

    // New-bin candidate (empty bin): make it attractive only when the current item
    // is large or open bins are crowded; otherwise discourage spreading load.
    if bin_residual == bin_capacity && bin_capacity >= item_size {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 30.0;
        score -= large_item_bonus;
        // Early in stream, opening fresh bins is fine; late, prefer consolidation.
        score += (1.0 - progress) * 10.0 + 0.5 * open_bins_count as f64;
        // If many bins fit the item, discourage opening another
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // If next item is huge, a fresh bin may serve it better
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
        let _ = crowding;
    }

    // Mild preference for bins with residual close to item (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Global pressure: when mean residual is low, avoid wasting scarce space
    score += (mean_residual / bin_capacity as f64) * 5.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress * (1.0 - progress) * 4.0);
    score += 20.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - norm_pr) * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item, penalize wasted potential
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack_fit = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack_fit) * (1.0 - slack_fit);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Penalize bins whose residual deviates far from the mean residual (balance pressure)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64) * 0.05 * progress;

    // Prefer filling bins with larger residual when few fitting bins remain
    score += (fitting_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues mod small integers
    // capture "nice" leftover sizes that future items can fill.
    let pr = post_residual;
    let c = bin_capacity;

    // Reward residuals that are harmonically aligned with capacity fractions.
    let fractions: [u32; 8] = [0, 5, 10, 20, 25, 50, 75, 100];
    for f in fractions.iter() {
        if pr == *f {
            score -= 18.0;
        }
    }

    // Modulo classes: residuals divisible by 10 are "usable" classes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 5 == 0 && pr % 10 != 0 {
        score -= 2.0;
    }
    // Odd/awkward residuals are dead space.
    if pr % 2 == 1 {
        score += 3.0;
    }

    // Integer-division thresholds on post_residual.
    let class = pr / 10; // 0..=9 coarse class
    score -= match class {
        0 => 12.0,          // near-perfect fill
        1 => 7.0,
        2 => 4.0,
        3 => 1.0,
        4 => 0.0,
        5 => -1.0,
        _ => -2.0,
    };

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain bonus scaled by how snugly the next item would fit.
            let snug = (pr - next_item_size) as f64;
            score -= 8.0 + 6.0 * (1.0 - snug / c as f64);
            if pr % next_item_size.max(1) == 0 {
                score -= 4.0; // exact harmonic subdivision
            }
        } else {
            // Next item cannot follow into this residual: penalize
            // proportionally to wasted capacity.
            score += 4.0 + 3.0 * (next_item_size as f64 / c as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer tighter fits, mild penalty.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Pull toward mean residual: bins far below mean waste capacity.
    let diff = mean_residual - post_residual as f64;
    score += 0.15 * diff;

    // Early in the stream, be more willing to spread items (keep options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 2.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // Discourage opening a new bin when alternatives exist.
            score += 10.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps of 1..=9 are essentially unusable
    // (min item size ~1..10); penalize them heavily.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness reward: fraction of the bin's useful space consumed.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: prefer consolidating into
    // already-open bins rather than spreading out.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: default cost of opening a new bin;
    // only attractive when existing bins would leave large dead space
    // or none fit well.
    if bin_residual == bin_capacity {
        score = 55.0 + 2.0 * open_bins_count as f64;
        if post_residual > 0 && post_residual <= 9 {
            // never open a fresh bin for an item that itself creates dead space
            score += 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit post residual but fits elsewhere, mild penalty
    // for fragmenting.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference to fill bins below mean residual (balance).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
