pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor small post_residual (best-fit core).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item uses leftover space.
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * use_ratio * use_ratio;
        } else {
            // Next item won't fit here; penalize leaving awkward medium gaps.
            let gap = post_residual as f64;
            if gap >= next_item_size as f64 * 0.5 && gap < next_item_size as f64 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is expensive early, cheaper late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Penalize opening new bins, more so when many bins are open or progress is low.
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + 8.0 * open_pressure * (1.0 - 0.5 * progress);
        // But if no open bin fits well, opening is less bad (handled via fitting count).
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 15.0 * progress;
    }

    // Global residual pressure: if mean residual across open bins is high, encourage
    // filling bins rather than spreading items.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // Penalize leaving residuals that are small-but-unusable (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild penalty for very full bins early (keep flexibility), reward late.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += 10.0 * fill * (0.5 - progress);

    // Slight noise-free tie-breaker: prefer bins with lower index-like pressure via
    // open bin count (favor packing into fewer bins).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
