pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes via integer division.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual < 10 (nearly dead, small) -> good.
    // Larger classes: residual divisible into big chunks is reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0;
    } else {
        let class = pr / 10; // harmonic class of leftover
        // small leftovers (class 0..2) are near-dead space: penalize extra
        if class <= 1 {
            score += 8.0 * (2.0 - class as f64);
        } else if pr % 10 == 0 {
            // leftover is a harmonic multiple of 10 -> likely reusable by future items
            score -= 6.0;
        }
        // leftover that exactly matches next item is gold
        if next_item_size > 0 && next_item_size <= pr {
            if pr == next_item_size {
                score -= 25.0;
            } else if pr - next_item_size <= 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else if next_item_size > 0 {
            // next item cannot fit here: mild penalty scaled by how much it misses
            let miss = (next_item_size - pr) as f64;
            score += (miss / cap) * 10.0;
        }
    }

    // Tightness of current fit: reward filling a large fraction of the bin now
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so new bins are only chosen when open bins score poorly.
        score += 40.0;
        // More open bins with high mean residual -> prefer reusing them, penalize new bin more.
        score += open_bins_count as f64 * 2.0;
        // Late in the stream, consolidation matters more.
        score += progress * 10.0;
        // If mean residual is small, open bins are nearly full; new bin less bad.
        score -= (mean_residual / cap).max(0.0) * 20.0;
        // If next item is large, a fresh bin gives it room.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual was already small (tight packing pressure).
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless the item truly doesn't fit well anywhere.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 2.0;
        // If no other bin fits, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
    }

    // Lookahead coupling: if the next item fits the resulting gap, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for next item: mild penalty scaled by gap uselessness.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Mean-residual alignment: prefer bins close to the mean residual (balanced packing).
    score -= 2.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / (bin_capacity as f64 + 1.0)));

    // Slight late-stream conservatism: near the end, tighten bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
