    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // slack left after hypothetically placing next item too
            let two_step_slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - two_step_slack as f64 / bin_capacity as f64);
        } else {
            // dead space relative to the next item
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: penalize making bin much tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-poor unless nothing fits well
    if bin_residual == bin_capacity {
        score += 120.0;
        // open a new bin if the item leaves awkward residue in any existing bin
        if post_residual > 0 && post_residual < 20 {
            score -= 150.0;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * item_size as f64;

    // Penalize creating dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers are wasted capacity
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 4.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a residual that blocks the next item.
        score += 2.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
    }

    // New-bin candidate logic: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // Cheaper to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // More expensive when many bins are already open (consolidation pressure).
        score += 1.5 * (open_bins_count as f64).ln().max(0.0);
        // If many bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 6.0;
        }
        // If mean residual is large, prefer using existing bins.
        score += 0.08 * mean_residual;
        // If next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 5.0;
        }
    }

    // Mild preference for bins with residual close to the item (best-fit flavor).
    score += 0.02 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / capacity;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: tighten packing as stream advances
    score *= 1.0 + 0.5 * progress * norm_post;

    // Dead-space quadratic penalty relative to mean residual
    let dead = (post - mean_residual).abs();
    score += 0.3 * dead * dead / capacity;

    // Reward bins that also fit the next item (smooth lookahead coupling)
    if next_item_size > 0 {
        let fits_next = (post >= next_item_size as f64) as f64;
        let gap = (post - next_item_size as f64) / capacity;
        score -= 6.0 * fits_next * (1.0 - gap * gap).max(0.0);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild pressure to reuse existing bins when many are open
    score -= (open_bins_count as f64).ln() * 0.4;

    // Penalize opening a new bin slightly, scaled by progress
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: how it partitions the capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals that are "dead zones" — small but nonzero leftovers
    // that few typical items can exploit. Harmonic classes: multiples of 10
    // are the most reusable; residuals in (0,10) are dead.
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,                       // perfectly reusable class
        1..=5 => score += 18.0,                   // near-dead sliver
        6..=9 => score += 8.0,                    // awkward class
        _ => {}
    }

    // Exact-fill bonus: harmonic class zero with tiny residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo thresholds on post_residual: reward residuals that can host
    // mid-range items (>= 20) — integer division test.
    if post_residual / 20 >= 1 {
        score -= 6.0;
    }

    // Lookahead coupling: does next_item_size fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: reward, stronger when the chain is tight.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mild penalty scaled by how close we were.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + 10.0 * (1.0 - miss / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor. Penalize the fresh bin, but relax the penalty late in the
    // stream or when the mean residual across open bins is already large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        let relax = (mean_r / cap).clamp(0.0, 1.0);
        score += 30.0 - 20.0 * relax - 10.0 * progress;
        // If the item is huge relative to capacity, opening fresh is natural.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 15.0;
        }
    }

    // Fractional capacity coupling: prefer bins whose fill ratio after placement
    // crosses harmonic thresholds (1/2, 3/4).
    let fill = (cap - frac * cap) / cap; // 1 - residual fraction = fill fraction
    if fill >= 0.75 {
        score -= 9.0;
    } else if fill >= 0.5 {
        score -= 5.0;
    }

    // Slight diversity pressure: too many open bins with high mean residual
    // suggests over-fragmentation; favor compacting into existing bins.
    if open_bins_count > 4 && mean_residual > 0.5 * cap && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
