    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover space can't host next item: mild penalty if gap is small
        if post_residual < next_item_size && post_residual < 35 {
            score += 10.0;
        }
    }

    // New-bin candidate (empty bin): make it attractive only when the
    // item is large relative to capacity or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item_bonus = if item_size >= 50 { 25.0 } else { 0.0 };
        score -= 30.0 + large_item_bonus + progress * 20.0;
        // But if an existing bin fits well, this should lose:
        // add back a term proportional to item size (new bin wastes space).
        score += item_size as f64 * 0.3;
    }

    // Slight nudge using mean residual: bins deviating far below mean
    // residual are "hole" bins; filling them is good.
    let deviation = mean_residual - bin_residual as f64;
    if deviation > 0.0 {
        score -= deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            // penalize leaving a residual that is awkwardly small for the next item
            if slack_after_next > 0 && slack_after_next < 10 {
                score += 30.0;
            }
        } else {
            // next item won't fit here after placement; penalize mildly, worse late in stream
            score += 40.0 * (0.5 + 0.5 * progress);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose residual after placement is close to zero relative to mean.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 0.5 {
            score -= 50.0 * (1.0 - ratio);
        } else if ratio > 1.5 {
            score += 25.0 * (ratio - 1.5);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless the item is large and open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else { 0.0 };
        let last_chance_exists = fitting_bins_count == 0;
        if last_chance_exists {
            // no open bin can fit: opening is forced
            score -= 200.0;
        } else {
            // opening a new bin is only attractive when item is big and residuals are tight
            let big_item = item_size as f64 / bin_capacity as f64;
            score += 150.0 - 200.0 * big_item - 100.0 * (1.0 - crowded);
            if next_item_size > 0 && next_item_size >= post_residual.max(item_size) {
                score -= 30.0;
            }
        }
    }

    // Mild late-stream tightening: waste matters more as stream ends.
    score += 0.5 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.85;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear penalty on wasted residual, modulated by stream progress
    score += 8.0 * x * x * (0.5 + progress) * cap * 0.01;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 20.0 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a new bin, more so early on,
    // unless the fit into existing bins would be very poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 {
            let gap = (next_item_size as f64 - pr).abs();
            score += 0.1 * gap * (1.0 - progress);
        }
    }

    // Lookahead coupling: reward residual matching next item size
    if next_item_size > 0 {
        let nd = (pr - next_item_size as f64).abs() / cap;
        score += 6.0 * nd * nd * cap * 0.05 * (1.0 - progress);
    }

    // Mean-residual deviation term: prefer bins whose post-residual
    // stays near the mean to keep flexibility
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * 0.05;

    // Slight penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward: post_residual falls in a "harmonic" class (0, or exact fractions of capacity)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // residue class modulo small integers: residuals divisible by common item sizes are reusable
        let mut harmonic_bonus = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                harmonic_bonus += 15.0;
            }
        }
        score -= harmonic_bonus;

        // Fraction-of-capacity classes: tiny leftover (<10) is dead space -> penalize;
        // large leftover (> half capacity) is flexible -> reward.
        if pr < 10.0 {
            score += 60.0 * (1.0 - pr / 10.0);
        } else if pr > cap * 0.5 {
            score -= 40.0;
        } else if pr > cap * 0.25 {
            score -= 15.0;
        }

        // Lookahead coupling: if next item fits into post_residual, big reward
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 80.0;
            // extra reward for near-exact pairing
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 40.0;
            }
        } else if next_item_size > 0 {
            // next item won't fit here: penalize proportionally to how "wasted" the space is
            score += 10.0 * (next_item_size as f64 - pr).min(60.0) / 60.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if all open bins fit badly.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; scales with how many bins already fit the item
        let mut new_bin_score = cap * 0.55 + 50.0;
        if fitting_bins_count > 0 {
            new_bin_score += 30.0 * fitting_bins_count as f64;
        }
        // early in stream, opening bins is cheaper (keeps options open)
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 40.0 * (1.0 - progress);
        score = score.max(new_bin_score);
        return score;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 25.0 * fill * (open_bins_count as f64).sqrt().min(5.0);

    // Slight preference toward bins tighter than the mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    let post = post_residual as f64;
    score += post;

    // Strict dead-space penalty: residuals too small for the smallest
    // possible future item are pure waste. Penalize them quadratically.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * (dead_threshold - post) * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual exactly matches the next item (lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post_residual cannot hold the next item but is close.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open bins pressure: with many open bins, prefer packing into existing
    // bins rather than spreading; make new bins less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.3 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin should only win when the fit
    // elsewhere is bad. Penalize the fresh bin, scaled by how many bins fit.
    if bin_residual == bin_capacity {
        score += 25.0 + fitting_bins_count as f64 * 5.0;
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly favor it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Prefer bins with residual below mean (denser bins first).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // Mild reward for using a large fraction of the bin's residual.
    score -= (item_size as f64 / bin_residual as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: bin becomes exactly sized for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post-residual that cannot host the next item is dead space: penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Partial lookahead: next item still fits with slack left over.
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable to preserve.
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    }

    // New-bin candidate: only attractive when it promises a large usable residual.
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 {
            score -= (bin_capacity as f64 - next_item_size as f64).abs() * 0.1;
        }
    }

    // Late in the stream, prefer closing bins tightly (waste minimization).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward placements that leave room for the next item (lookahead coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item fits here afterwards: strong reward, deeper if snug
            let snug = 1.0 - ((post_residual as f64) - nxt) / cap;
            score -= 8.0 + 6.0 * snug;
        } else {
            // next item won't fit after placement: penalize proportionally
            let gap = nxt - post_residual as f64;
            score += 4.0 * (gap / cap);
        }
    } else {
        // last item: just minimize residual
        score -= 5.0;
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        // small unusable dead space penalty
        score += 6.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Time horizon: early in stream, prefer tight packing (low residual);
    // late in stream, prefer closing bins out (favor fuller bins even more)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);

    // Global state: many open bins with high mean residual -> discourage
    // leaving this bin sparse; encourage consolidating into fuller bins
    if open_bins_count > 0 {
        let rel_mean = mean_residual / cap;
        score += 3.0 * rel_mean * (post_residual as f64 / cap);
        if open_bins_count > 8 {
            score -= 2.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // New-bin candidate: empty bin should only win if it offers great
    // flexibility (large post_residual that still fits the next item)
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, mild preference for leaving medium space; late, strong tightness pressure.
    let coupling = x * x * (1.0 - x) * (1.0 + 3.0 * progress);
    score += 40.0 * coupling;

    // Penalize very large dead space quadratically, stronger as stream progresses
    score += (x * x) * cap * (0.5 + 1.5 * progress);

    // Reward using nearly-full bins (small residual) with smooth decay
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: penalize if post residual can't fit the next item but could have
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt && bin_residual as f64 >= nxt {
            score += 10.0 + 15.0 * progress;
        }
        // Reward leaving space exactly usable by the next item (smooth soft match)
        let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
        if fit_quality > 0.0 {
            score -= 12.0 * fit_quality * fit_quality;
        }
    }

    // Mean residual context: penalize bins far from the mean residual (outliers)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for proliferating bins relative to progress
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with slight early preference to open bins
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls
    // into "awkward" residue classes that few typical items can fill.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfectly tight fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class B: residual small enough to be nearly unusable (<= 10)
        if post_residual <= 10 {
            score -= 50.0; // small dead space is fine, bin is "closed"
        } else {
            // Class C: harmonic slots — residuals that are multiples of
            // common item sizes (10, 20, 25, 50) are easy to fill later.
            let harmonic = (post_residual % 10 == 0) as f64
                + (post_residual % 25 == 0) as f64
                + (post_residual % 50 == 0) as f64;
            score -= 8.0 * harmonic;

            // Class D: awkward residues (prime-ish, off-grid) get penalized.
            if post_residual % 10 != 0 && post_residual % 5 != 0 {
                score += 6.0;
            }
        }
    }

    // Fractional capacity logic: how much of the bin is consumed.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * fill; // prefer fuller bins (best-fit core)

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot follow here; penalize leftover that is
            // too small for the next item but too big to ignore.
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current fit is bad. Base cost for opening a new bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is better when many bins are open and mean
        // residual is low (fragmented state) — reduce the penalty.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        if mean_residual < 15.0 {
            score -= 10.0;
        }
        // Never open a new bin for a tiny item if a decent fit exists.
        if item_size <= 30 && fitting_bins_count > 1 {
            score += 40.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (given minimum item size 1..100 unknown, treat very small gaps
    // as dead) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // If next item cannot fit and post residual is small, mild penalty
    // (dead end for the chain).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; opening new bins becomes more costly.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, scaled by stream
        // progression (later in the stream, harder to amortize a new bin).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 60.0 + open_pressure * (1.0 + progress) - 20.0 * progress;
    } else {
        // Existing bin: slight reward for choosing bins with low mean
        // residual spread (tighter packing targets).
        score -= open_pressure * 0.1;
        if (post_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 120.0 * (1.0 - diff as f64 / 100.0).max(0.0);

        // Penalize dead space: post residual too small for next item.
        if post_residual < next_item_size {
            score += 25.0 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving space usable for next item.
        else {
            score -= 15.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins deviating below mean (tight packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item is huge and post_residual is huge, new bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 6.0 + 0.35 * waste;
    } else if next_item_size > 0 {
        // Reward bins that can also host the next item after this placement.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when existing bins fit well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with usable open-bin space.
        score += 25.0 + 0.15 * mean_residual * (open_bins_count as f64).sqrt();
        // If nothing else fits tightly, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Global load balancing: penalize bins far from mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Time horizon: early in stream, keep residuals flexible; late, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly;

    // Penalize small dead space more strongly late in the stream (smooth cubic)
    let dead = (1.0 - norm_pr).powi(3);
    score += 8.0 * dead * (0.5 + progress);

    // Reward tight fits: post_residual close to zero
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < item_size / 2 {
        score -= 6.0 * (1.0 - post_residual as f64 / (item_size as f64 / 2.0));
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / cap;
        score -= 10.0 * chain_fit * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: open only when existing bins would waste a lot of space
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + mean_residual * 0.05;
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.02 * open_bins_count as f64 * mean_residual / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as "compatibility classes"
    let post = post_residual;
    let residue = (post % 10) as f64;
    // Dead-space penalty: residuals that are too small to host any typical item
    if post > 0 && post < 10 {
        score += 60.0; // unusable sliver
    } else if post < 20 {
        score += 12.0;
    } else if post == 0 {
        score -= 40.0; // perfect closure
    } else {
        // reward residuals that are multiples of common item sizes (harmonic fit)
        if post % 10 == 0 { score -= 10.0; }
        if post % 20 == 0 { score -= 6.0; }
        if post % 25 == 0 { score -= 5.0; }
        if post % 50 == 0 { score -= 8.0; }
    }

    // Lookahead coupling: does post_residual exactly host the next item?
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 25.0;
        } else if post >= next_item_size {
            let nres = post - next_item_size;
            if nres < 10 { score -= 5.0; } else if nres % 10 == 0 { score -= 8.0; }
        } else {
            score += 8.0; // next item cannot follow here
        }
        // small next item makes leftover residue more valuable
        if next_item_size <= 20 && post >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fractional capacity pressure: prefer bins whose fill fraction is high
    let fill_frac = 1.0 - (post as f64) / cap;
    score -= fill_frac * 15.0;

    // Compare against mean residual: bins below mean residual are tighter, favor them
    score += ((post as f64) - mean_residual) * 0.15;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && post >= next_item_size { 0.0 } else { 10.0 };
        let tight_open = if open_bins_count > 0 { (open_bins_count as f64).ln() * 3.0 } else { 0.0 };
        score = 55.0 + desperation + tight_open
            - (fitting_bins_count as f64) * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 5.0;
        // opening a fresh bin wastes nothing if item itself is large
        if item_size >= 70 { score -= 10.0; }
        if item_size <= 15 { score += 15.0; }
    }

    // Mild tie-break on residue class: prefer leaving residues in {0, 10, 20, 25, 50}
    let harmonic_bonus = match post {
        0 => 12.0,
        10 | 20 | 25 | 50 => 6.0,
        30 | 40 | 75 => 3.0,
        _ => residue * 0.2,
    };
    score -= harmonic_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space is worthless
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // next item cannot use the leftover
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but a brand-new empty bin gets a mild bonus only when few bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (tighter bins) to consolidate filling.
    if bin_residual < bin_capacity {
        let diff = mean_residual - (bin_residual as f64);
        score += diff * 0.5;
    }

    // Mild pressure to close bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            // Next item fills this bin exactly afterwards: chain of perfect fits.
            score -= 500.0;
        } else if gap > 0 {
            // Next item fits with leftover; penalize proportionally to dead space.
            score += gap as f64 * 0.5;
            // But if next item leaves near-zero, still slightly favorable.
            if gap <= 5 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: post_residual becomes dead space risk.
            // Penalize small unusable residuals more strongly.
            let pr = post_residual as f64;
            if pr < 10.0 {
                score += 40.0;
            } else {
                score += (10.0 - pr / 10.0).max(0.0) * 2.0;
            }
        }
    }

    // Compare post_residual against mean residual of open bins.
    // Favor bins whose residual is brought closer to the mean (balance), or below it.
    if open_bins_count > 0 {
        let dev = post_residual as f64 - mean_residual;
        score += dev * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is bad
    // (large post_residual) or few fitting bins.
    if bin_residual == bin_capacity {
        // Base new-bin cost: keep it high unless placement elsewhere is terrible.
        score += 60.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
        // If many open bins, discourage another one.
        score += open_bins_count as f64 * 3.0;
    }

    // Slight preference for bins with tighter residual (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (best-fit core).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward exact next-item fit even more than current tightness.
            if slack < 10 {
                score -= 25.0;
            } else {
                score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // This bin becomes dead after placement if next item can't use leftover.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 35.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 40.0 * progress;
        // More open bins with high mean residual => prefer consolidation into existing bins.
        new_bin_score += open_bins_count as f64 * 2.0;
        new_bin_score += (mean_residual - bin_capacity as f64 / 2.0).max(0.0) * 0.5;
        // If item is large, a fresh bin is more attractive (large items pair well).
        new_bin_score -= (item_size as f64 / 100.0) * 20.0;
        // If no other bin fits well, new bin becomes viable.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score = new_bin_score;
    }

    // Mild penalty for spreading across too many bins when mean residual is low.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling: residual weight grows with progress
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);
    score += 6.0 * norm_pr * (1.0 - progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Lookahead: penalize post_residual that cannot fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 15.0 * gap * gap;
        score -= 8.0 * fits_next * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bin, less so early or when bin nearly full
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 18.0 - 14.0 * fill * fill - 10.0 * progress;
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space buckets (mod 10) —
    // residuals in "awkward" classes (1..9 mod 10) are harder to fill later.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        match class {
            0 => { score -= 6.0; }          // perfectly decadal leftover: reusable
            1..=3 => { score += 4.0 + class as f64; } // tiny dead space: nearly unusable
            4..=6 => { score += 1.5; }      // mid class: mildly awkward
            _ => { score -= 1.0; }          // 7..9: fits small items (10..80 range scaled)
        }
    }

    // Integer-division threshold: post_residual relative to item-size floor
    let q = if item_size > 0 { pr / item_size.max(1) } else { 0 };
    if q == 0 && pr > 0 {
        // no same-size item can ever fit again: penalize proportionally
        score += 8.0 * (pr as f64) / (bin_capacity as f64);
    } else if q >= 1 {
        score -= 3.0 + q as f64;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect chaining
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic class of the double-residual
            if (pr - next_item_size) % 10 == 0 { score -= 4.0; }
        } else {
            // next item won't fit here: this residual becomes a class trap
            score += 3.0 + (next_item_size - pr).min(20) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 20.0 } else {
            8.0 * (1.0 - (open_bins_count.min(12) as f64) / 12.0)
        };
        score = bin_capacity as f64 - pressure + (mean_residual / bin_capacity as f64) * 4.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 3.0; // fresh bin pairs well with mid-size next item
        }
    }

    // Late-stream consolidation: tighten bin selection as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Pressure from many open bins: discourage spreading into new bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the item (best fit among open bins).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;

    // Mean residual coupling: if mean residual is large, avoid leaving small gaps.
    if post_residual as f64 > mean_residual {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 2.0;
    }

    // Lookahead: if next item would fit the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leaves a gap the next item cannot use: penalize.
        score += (post_residual as f64) * 0.5;
    }

    // New-bin candidate handling: neutral-ish score; opening new bin only when
    // no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progression.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 - progress * 10.0 + open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > item_size {
            score -= 5.0;
        }
        // Strongly discourage new bin if a last-chance open bin exists.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
