    // Global state: if mean residual across open bins is high, prefer filling existing bins
    let mean_res = mean_residual;
    if mean_res > 30.0 {
        score -= 3.0 * ((mean_res - 30.0) / 70.0).min(1.0);
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying late in the stream
        let mut open_cost = 20.0 - 8.0 * progress;
        // If very few bins fit, opening fresh is more acceptable
        if fitting_bins_count == 0 {
            open_cost -= 15.0;
        } else if fitting_bins_count == 1 {
            open_cost += 5.0; // last chance bin exists -> prefer it
        } else {
            open_cost += 10.0;
        }
        // If next item is large, a fresh bin with full room is valuable
        if next_item_size > 0 && next_item_size as f64 > mean_res {
            open_cost -= 6.0;
        }
        score += open_cost.max(0.0);
        // Empty bin leaves post_residual == capacity; neutralize the base residual term
        score -= post_residual as f64;
    }

    // Late-stream consolidation: favor compacting into few bins
    if open_bins_count > 3 {
        score += 0.3 * (open_bins_count as f64).min(10.0) * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: residual value decays with progress (later, less room to save)
    let decay = 1.0 - 0.6 * progress * progress;
    score *= decay;

    // Penalize large dead space quadratically relative to capacity
    let dead_frac = post / cap;
    score += 18.0 * dead_frac * dead_frac * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) with smooth inverse term
    score -= 12.0 * (1.0 - dead_frac).powi(3);

    // New-bin candidate: penalize opening fresh bins, more so mid-stream
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 25.0 + 35.0 * (1.0 - progress);
        // but if no open bin fits, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && !is_new {
        score -= 22.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Diverge from mean residual: prefer bins unlike the average to preserve diversity
    score += 0.15 * (post - mean_residual).abs() * (1.0 - progress);

    // Mild pressure to use existing bins when many are open
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: tightest fit preferred (best-fit core).
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify leftover space into
    // capacity-fraction buckets (0-25, 25-50, 50-75, 75-100).
    // Small residuals are "dead space" -> penalize quadratically.
    let quarter = bin_capacity as f64 / 4.0;
    let res = post_residual as f64;
    let class = (res / quarter).min(3.999) as u32;
    score += match class {
        0 => 12.0 + (quarter - res) * 0.15, // tiny leftover: near-perfect fill, slight bonus
        1 => 8.0,                            // half-ish leftover: still usable
        2 => 2.0,                            // roomy
        _ => -6.0,                           // large leftover: this bin was underfilled
    };

    // Integer-division threshold: exact multiples of common item sizes (10,20,25,50)
    // make the residual maximally reusable. Reward residuals divisible by 10 or 25.
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }

    // Lookahead harmonic coupling: if next item fits exactly into the post
    // residual, this is a perfect chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item leaves a residue; penalize by how far from exact
            let nres = post_residual - next_item_size;
            score -= 6.0 - (nres as f64) * 0.08;
        } else {
            // next item won't fit here: mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists (post_residual near capacity
    // minus item means item is small relative to bin). Penalize mildly so
    // tight fits in open bins win, but allow it when open bins are all bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If open bins are crowded (low mean residual), opening a new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
    }

    // Global pressure: many open bins with high mean residual -> reward
    // using existing bins harder (consolidation).
    if open_bins_count > 2 {
        score -= (mean_residual - res) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small to fit the smallest item (1..100 range, min item 1)
    // Treat residuals below a "useful threshold" as dead space with escalating penalty.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small residual that still fits next item: reward (good chaining)
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 8.0;
    }

    // Penalize leaving residual that cannot fit next item (creates stranded space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open bins pressure: discourage spreading across many bins when residuals are plentiful
    score += (open_bins_count as f64) * 0.8;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
    }

    // Mild bonus for bins tighter than average (compact packing)
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Post-residual large enough to fit the next item: good chain potential.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space: post_residual too small for the next item.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste;
    }

    // Penalize post_residual far from mean residual (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Tight fit reward: small post residual is good (waste minimization).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Late in the stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    } else {
        // New-bin candidate: penalize unless residuals are all hopeless.
        score += 10.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near zero is excellent.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to ever fit a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 0.25 * next_item_size as f64;
        } else {
            // Next item cannot fit here; penalize proportionally to wasted potential.
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: only bin that fits the item — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let bad_fit = 1.0 - fit_ratio;
        score = bin_capacity as f64 * 0.55
            - 25.0 * crowd * progress
            - 30.0 * bad_fit * bad_fit
            + 10.0 * (mean_residual / bin_capacity as f64);
        // Late in the stream, prefer consolidating into existing bins.
        score += 20.0 * progress * (1.0 - bad_fit);
    }

    // Mild preference for fuller bins relative to the fleet average.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Small time-decay: as stream ends, favor using nearly-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;

    // Base: prefer small post-residual, with non-linear emphasis on tight fits
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress: late in the stream,
    // tight fits matter more (dead space is harder to recover)
    let progress_coupling = 1.0 + 1.2 * progress * (1.0 - norm_pr);
    score *= progress_coupling;

    // Polynomial interaction between item size and progress: large items late
    // deserve priority placement (avoid opening bins for them)
    score -= 8.0 * norm_item * norm_item * progress * (1.0 - progress + 0.5);

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // Penalize opening a brand-new bin smoothly: new bin has post_residual = cap - item
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // New-bin penalty grows with how many open bins could fit and with progress
        score += 10.0 + 15.0 * progress + 2.0 * (fitting_bins_count as f64);
        // But relax penalty when item is very large (poor fit anywhere)
        score -= 14.0 * norm_item * norm_item;
    }

    // Lookahead: if next item fits into post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 - norm_pr);
    }

    // Mild preference for bins with residuals near the item (good fit among open bins)
    let fit_gap = (bin_residual as f64 - item) / cap;
    score += 3.0 * fit_gap * fit_gap;

    // Slight diversity pressure: avoid concentrating on few bins when many are open
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // Mean-residual coupling: when mean residual is high, tolerate looser fits
    score -= 0.05 * mean_residual * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space below smallest item (1) is pure waste,
    // but with sizes >=10 effectively any post_residual < 10 is a "dead" class.
    let dead_threshold = 9u32;
    if post_residual < dead_threshold {
        score += 50.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else {
        // Harmonic bucket: how many equal-size items of the dominant class still fit?
        let class_fit = post_residual / 10; // integer division threshold classes
        score -= (class_fit as f64) * 6.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < dead_threshold {
                score -= 15.0; // next item nearly closes bin
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.3;
            }
        } else {
            // next item won't fit here: leftover should still be reusable
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer filling bins that are already relatively full (tight fit preference)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Slight preference for keeping the number of open bins low late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    // New-bin candidate: make it moderately attractive only when current bins are crowded
    if bin_residual == bin_capacity {
        score += 30.0 - mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible future item are nearly worthless.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64; // tiny unusable gap => heavy penalty
    } else if pr >= 10 && pr < 20 {
        score += 6.0; // marginal gap
    }

    // Perfect fit is highly desirable.
    if pr == 0 {
        score -= 40.0;
    }

    // Exact match with lookahead: this bin can serve the next item too.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0;
        if pr == next_item_size {
            score -= 12.0; // next item closes this bin perfectly
        }
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 5.0; // gap blocks the known next item
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a fresh bin moderately expensive so it
    // is only chosen when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64;
        // But if the current item would leave a perfect slot for the next item,
        // a new bin is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Early in the stream, allow spreading items a bit (cheap bins now,
    // better packing later); late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight reward for bins tighter than the mean residual (good fits).
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit in the leftover: penalize dead space creation,
        // worse when the leftover is small (unusable).
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 35.0;
        } else {
            score += 12.0 * (1.0 - dead / 50.0).max(0.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins below mean residual (tighter bins) to keep large residuals flexible.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let urgency = if next_item_size > 0 && next_item_size >= item_size { 1.0 } else { 0.0 };
        score += 20.0 - 15.0 * urgency;
        // Discourage new bins when decent fitting bins exist.
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Late in stream: consolidate, avoid spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full packing (small post_residual already does this,
    // but amplify with a quadratic term so tiny leftovers are strongly preferred).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Dead-space penalty: leftovers too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item uses leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
        } else {
            // Next item cannot use this bin's leftover; mild penalty for stranding space.
            score += 4.0;
        }
    } else {
        // Last item: filling bins as tightly as possible is all that matters.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item fits poorly everywhere
        // (few fitting bins) or when many bins are already open and fragmented.
        let scarcity_bonus = if fitting_bins_count <= 2 { 18.0 } else { 0.0 };
        let fragmentation = (open_bins_count as f64).ln().max(0.0);
        score -= scarcity_bonus + 3.0 * fragmentation;

        // Early in the stream, prefer consolidating into open bins; later, allow spreading.
        score += 10.0 * (1.0 - progress);
    }

    // Global residual pressure: if mean residual is high, prefer bins with residual
    // far from the mean (to consolidate outliers); if low, just pack tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.0 * dev / (mean_residual + 1.0);

    // Mild preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post_residual, with non-linear shrinkage of large dead space.
    let mut score = pr * (1.0 + 0.8 * fit_norm * fit_norm);

    // Smooth progress coupling: later in the stream, penalize waste more strongly.
    let prog_coupling = 0.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += pr * (0.3 + 0.7 * prog_coupling) * fit_norm;

    // Reward tight fits (small post residual) with a smooth quadratic bonus.
    score -= 20.0 * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward; else mild penalty
    // scaled smoothly by how much of post_residual the next item would consume.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let use_ratio = nx / pr.max(1.0);
            score -= 12.0 * use_ratio * use_ratio;
        } else {
            let over = (nx - pr) / cap;
            score += 8.0 * over * over;
        }
    }

    // Mild preference for bins whose residual is near the mean (keeps balance),
    // smooth quadratic penalty on deviation.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight penalty when many bins are open: encourage consolidation early.
    score += 0.15 * open_bins_count as f64 * fit_norm;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as i64;
    let eighth = (bin_capacity / 8) as i64;

    // Reward exact harmonic fits: post_residual in {0, C/4, C/2, 3C/4}
    let pr_i = post_residual as i64;
    if pr_i == 0 {
        score -= 40.0; // perfect fit
    } else if pr_i == quarter {
        score -= 18.0;
    } else if pr_i == quarter * 2 {
        score -= 14.0;
    } else if pr_i == quarter * 3 {
        score -= 10.0;
    }

    // Penalize tiny dead space (unusable residue) unless zero
    if pr_i > 0 && pr_i <= eighth {
        score += 25.0 - 2.0 * pr as f64;
    }

    // Modulo-class pairing: can next_item_size exactly fill the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // next item closes this bin perfectly
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as i64;
            if gap % quarter == 0 {
                score -= 8.0; // gap stays in harmonic class
            }
            score += gap as f64 * 0.4;
        } else {
            // next item cannot use this bin's residue
            score += 6.0;
        }
    }

    // Integer-division threshold on post_residual vs item size
    let fits_div = post_residual / item_size.max(1);
    if fits_div >= 2 {
        score -= 6.0; // residue can host multiple small items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when current bin would leave bad residue
    if bin_residual == bin_capacity {
        // opening fresh is neutral-ish; penalize slightly so real bins win on good fits
        score += 12.0;
        if item_size > (bin_capacity * 2 / 3) {
            score -= 20.0; // big items are fine in a fresh bin
        }
    }

    // Stream progression: early on, be pickier about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Mean-residual coupling: if this bin is far below mean residual, it's already fragmented
    if (mean_residual - pr) > cap * 0.25 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual is "dead" if it is too small to fit even the smallest plausible item.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving a gap that cannot fit the known next item (wasted capacity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving a gap that exactly or comfortably fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual as f64 - next_item_size as f64).min(10.0);
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmenting into more bins;
    // favor filling existing bins instead of opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (0.5 + 0.5 * progress);
    score += pressure * 0.5;

    // New-bin candidate: only attractive when existing residuals are poor fits.
    // Penalize the empty bin mildly so it wins only when dead-space penalties dominate.
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 0.8;
        // If the item is large relative to mean residual, opening fresh is less bad.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, easier to close out).
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item fits tightly into post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize proportionally
        score += 50.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Tight fit reward: small post residual is good dead-space avoidance
    if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 100.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_penalty = 150.0 + mean_residual * 0.3;
        let last_chance_bonus = if fitting_bins_count == 1 { 0.0 } else { 400.0 };
        score += poor_fit_penalty * (1.0 - 0.2 * progress) + last_chance_bonus;
    }

    // Prefer bins with residual close to mean (avoid fragmenting outlier bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared post-residual penalty amplifies dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so we prefer reuse, but relax as stream
    // progresses and open-bin residuals are fragmented (high mean residual).
    if is_new_bin {
        let fragmentation = ((mean_residual - post_residual as f64) / bin_capacity as f64).max(0.0);
        score += 15.0 + 20.0 * (1.0 - progress) - 25.0 * fragmentation.min(1.0);
        // If no existing bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate emptier bins).
    if !is_new_bin {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * diff;
    }

    // Mild pressure to reduce open-bin count early in the stream.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with smooth non-linear penalty on residual.
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, moderate residuals are more tolerable; late, dead space hurts more.
    let coupling = norm_pr * norm_pr * (1.0 + progress * 3.0);
    score += 40.0 * coupling;

    // Smooth interaction: residual vs mean residual deviation, scaled by progress.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dev * (0.5 + progress);

    // Perfect fit bonus (smooth, non-linear).
    let perfect = (norm_pr - 0.02).abs();
    score -= 25.0 * (-perfect * perfect * 50.0).exp();

    // Lookahead: reward residual that can fit next item (quadratic coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - slack * slack) * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strong smooth bonus to use it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty proportional to number of open bins, smoothed by progress.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly (dead space eliminated).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space below 10 is unusable for
    // any item, so treat small post residuals as nearly perfect fits.
    if post_residual < 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Modulo-class coupling: does the leftover pair naturally with the
    // lookahead item? Reward residuals that are multiples of common
    // harmonics of the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // lookahead chains perfectly
        } else if next_item_size <= post_residual {
            // next item fits here: keep this bin attractive
            score -= 40.0;
            // harmonic bonus when post_residual is a multiple of next_item_size
            if post_residual % next_item_size == 0 {
                score -= 80.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large
            // stranded residuals
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Integer-division threshold on post_residual: classify leftover into
    // harmonic bands of the capacity.
    let band = post_residual / 25; // 0,1,2,3
    score += band as f64 * 15.0;

    // Penalize wasting a nearly-empty bin's large residual on a small item
    // when the item creates a mid-range dead zone.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.35 && frac < 0.6 {
        score += 30.0; // awkward mid-band leftover
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new-bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins are tight or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 1.2;
        // base cost of a fresh bin, softened for big items or tight state
        score += 90.0
            - item_size as f64 * 0.4
            - progress * 20.0
            - if tight { 70.0 } else { 0.0 }
            - if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 0.0 };
        // never let a new bin beat a perfect fit
        if post_residual == 0 { score += 1000.0; }
        if bin_residual - item_size < 10 && item_size >= 60 { score -= 50.0; }
    }

    // Mild pressure against proliferating bins when mean residual is high.
    score += open_bins_count as f64 * 0.05 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest item threshold
    // (items >= 10 by spec, but be safe with 1..100 range => use 10) are pure waste.
    let min_item = 10u32;
    if post_residual < min_item && post_residual > 0 {
        // Unusable sliver: strong penalty proportional to how "almost useful" it is.
        score += 60.0 + (min_item - post_residual) as f64 * 8.0;
    }

    // Penalize residuals that cannot fit the lookahead item (k=2) if they could
    // otherwise have been useful for it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward a residual that exactly accommodates the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Reward perfect fit / zero post residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many open bins,
    // but relax near end of stream where closing bins out is valuable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).powf(1.3) * (1.0 - 0.5 * progress);
    score += pressure * 0.35;

    // Deviation from mean residual: prefer bins whose fill keeps residuals balanced,
    // unless it's a last-chance bin.
    if fitting_bins_count > 1 {
        score += (post_residual as f64 - mean_residual).abs() * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it moderately attractive only when the current item is large or
    // no good fit exists; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items: new bin is fine; small items into fresh bin waste capacity.
        score += 25.0 - 30.0 * fill_ratio;
        // If few fitting bins, opening fresh is more acceptable.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Mild preference for tighter existing fits (small post_residual already base term).
    score += (post_residual as f64).powf(1.2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize mismatch between post_residual and the lookahead item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.5;
    }

    // Penalize leaving dead space below the minimum plausible item size,
    // scaled by how far along the stream we are.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (better packing).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Default penalty for opening a new bin.
        score += 25.0;
        // But if the current item plus next item nearly fill a fresh bin,
        // opening is worthwhile (aggressive 2-step lookahead).
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity * 9 / 10 {
            score -= 45.0;
        }
        // Reduce penalty when many bins are already open (spread load).
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mild preference for filling existing bins tightly relative to capacity.
    score += (1.0 - (item_size as f64 / bin_capacity as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (post_residual as f64);

    // Penalize dead space that cannot fit the smallest plausible item (1..100, assume ~10 typical)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < item_size {
        score += 8.0;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residuals deviating below the mean (consolidate small leftovers)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time horizon: early on, be selective (penalize loose fits); late, accept anything
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.4;
    score -= progress * 5.0;

    // Many open bins: encourage closing them out (favor bins with small residual)
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty on tiny dead space
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more; early on, keep bins flexible
    let coupling = (progress - 0.5) * (norm_pr - 0.5);
    score += 30.0 * coupling * norm_pr;
    score -= 20.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Reward bins whose post-residual can host the next item (smooth kernel)
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - fit_quality * fit_quality);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: only one bin fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild pressure toward consolidating bins as stream progresses
    score += 0.8 * open_bins_count as f64 * (0.3 + progress);

    // Deviation from mean residual: prefer bins near mean to keep balance
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Penalize brand-new empty bin candidate unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap) < 0.5;
        score += if poor_fit { 15.0 + 20.0 * progress } else { 60.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residues divisible by 10 are
    // "usable" since item sizes are multiples of 10 in the canonical stream.
    let r = post_residual as i64;
    let dead = (r % 10) as f64;          // dead space beyond a 10-multiple
    let usable = ((r / 10).min(8)) as f64; // usable 10-blocks, capped

    // Reward leaving a residual that is itself a plausible item size class.
    let harmonic_bonus = match post_residual {
        0 => 40.0,                 // perfect fit: strongly reward
        10 | 20 | 30 | 40 => 18.0, // highly reusable classes
        50 | 60 => 8.0,
        _ => -2.0,
    };
    score -= harmonic_bonus;
    score -= 1.5 * usable;

    // Penalize dead space non-linearly (small residues below 10 are wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64;
    }
    score += 0.8 * dead * dead / 10.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / 80.0);
        } else {
            // next item cannot use this bin's remainder; mild penalty if we waste space
            score += 4.0;
        }
        // Harmonic coupling: next item divisible-by-10 class vs post residual class
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: it's only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for fragmenting; relaxed late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut pen = 55.0 - 15.0 * progress;
        // If many bins can fit, opening a new one is wasteful.
        pen += 8.0 * (fitting_bins_count.min(6) as f64);
        // If the item is huge and would leave a tiny unusable residue anywhere,
        // a fresh bin is fine: reduce penalty when item is large.
        pen -= 0.3 * (item_size.saturating_sub(50)) as f64;
        // If next item is large, a fresh bin with room for it is valuable.
        if next_item_size >= 60 {
            pen -= 10.0;
        }
        score += pen.max(0.0);
    } else {
        // Prefer tighter existing bins: compare residual to mean residual.
        score += 0.15 * (bin_residual as f64 - mean_residual);
        // Slight preference for bins that keep open-bin count stable.
        score -= 0.5 * (open_bins_count.min(20) as f64).ln().max(0.0);
    }

    // Phase coupling: early stream -> be frugal with new space (already covered);
    // late stream -> consolidate, reward near-full bins more.
    if total_items > 0 {
        let prog = step_index as f64 / total_items as f64;
        score -= 6.0 * prog * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small-but-not-dead gaps: moderate penalty, scaled by how close
        // to dead-space they are.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins. With few bins, opening a new one is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (avoid bin fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when the item would leave a
    // large usable gap elsewhere or when mean residual is bloated. An empty
    // bin gives post_residual == bin_capacity; penalize it unless the fit in
    // existing bins would be terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by open-bin pressure.
        score += 35.0 + open_bins_count as f64 * 1.2;
        // If mean residual across open bins is large, existing bins are
        // roomy; opening yet another bin is wasteful.
        score += mean_residual * 0.3;
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 20.0;
        // But if next item is large and this item leaves a big gap, a fresh
        // bin can be fine — slight relief.
        if next_item_size as f64 > post_residual as f64 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: place item so the next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near matches: the next item could still fit with little waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 / (1.0 + slack);
    }

    // Penalize dead space that cannot hold the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Favor tight fits relative to the mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly reward using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening a new bin when many bins are already open, unless it's early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 100.0 * progress + open_bins_count as f64 * 2.0;
    }

    // Small absolute waste bonus: prefer bins that end with tiny leftovers.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving residual that the lookahead item could use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to lookahead item.
        score += 0.35 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins exist with slack.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But allow new bin early in stream or when mean residual is tiny.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Prefer using bins whose residual deviates below the mean (consolidate emptier bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize post residual, non-linearly (dead space grows in cost).
    let mut score = norm_pr * norm_pr * cap * (1.0 + 0.5 * progress);

    // Smooth coupling: prefer tight fits, reward grows with stream progress.
    score -= (1.0 - norm_pr) * (1.0 + progress) * 10.0;

    // Interaction: post residual vs mean residual — avoid creating outliers.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Lookahead: reward if next item fits in post residual, smooth decay.
    if next_item_size > 0 {
        let fits = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let slack = 1.0 - ((next_item_size as f64 - pr).max(0.0) / cap);
        score -= 3.0 * (fits / cap) * slack;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for bin proliferation relative to stream length.
    score += 0.5 * open_bins_count as f64 / (total_items as f64).max(1.0) * 100.0;

    // Smooth penalty for very small item into large residual (waste of big space).
    score += 4.0 * norm_item * (1.0 - norm_item) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space smaller than the minimum
    // item (1) is worthless; small residues in low integer-division classes
    // are near-worthless too.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let post_frac = post / cap;

    // Class A: tiny dead space (< 10) is a win -> strong reward.
    if post_residual < 10 {
        score -= 60.0;
    }
    // Class B: residue in (10..=20] is a poor harmonic class (hard to fill
    // with items of size >= 1 but typical items rarely match) -> penalize.
    else if post_residual <= 20 {
        score += 15.0;
    }
    // Class C: residues that are "half" multiples of capacity are decent
    // targets for mid-size items -> mild reward.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands of C/4).
    let band = post_residual / 25; // 0..4
    score += match band {
        0 => 10.0,  // 0..24: awkward leftover unless tiny
        1 => 2.0,   // 25..49: mediocre
        2 => -3.0,  // 50..74: good
        _ => -6.0,  // 75..100: excellent
    } * (1.0 - post_frac);

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if next item is close but doesn't fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot follow into this bin: dead-end risk grows
            // when post_residual is small-but-nonzero.
            if post_residual < next_item_size && post_residual > 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless post_residual would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when the item is large
    // relative to capacity (first-fit into a fresh bin preserves harmonic
    // structure) or all existing fits are bad.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        // Big items start fresh bins well; small items should use leftovers.
        score -= size_frac * 70.0;
        // If many bins are open with slack, discourage a new bin.
        score += (open_bins_count as f64) * (mean_residual / cap) * 12.0;
    }

    // Stream progression: late in the stream, consolidation matters more;
    // slightly penalize opening extra bins then.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for tiny unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space is worse if the next item cannot use it
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }
    // Reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 6.0;
    }

    // Tightness bonus: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.3;
        if post_residual < 20 {
            score += 30.0; // opening a bin for a poor fit is bad
        }
    }

    // Mean residual coupling: penalize bins far below mean residual (fragmented bins)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.2;
    }

    // Late-stream consolidation
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
    }
    // Penalize post-residuals that are dead space (too small for typical items).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 8.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if crowded || big_item {
            score -= 10.0 + 10.0 * (1.0 - progress);
        } else {
            score += 20.0; // discourage wasting a fresh bin
        }
    } else {
        // Prefer bins with residual close to item (best-fit flavor) among open bins.
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += tightness * 8.0;
        // Slight preference for bins below mean residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Late in stream, consolidate: favor existing bins more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = pr
        - 18.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * fit_frac
        + 30.0 * fit_frac * fit_frac * fit_frac;

    // Stream-progress coupling: tighten packing as stream advances
    score -= 25.0 * progress * (1.0 - fit_frac) * (1.0 - fit_frac);

    // Perfect/near-perfect fit bonus (smooth gaussian-like)
    let x = fit_frac;
    score -= 20.0 * (-x * x * 40.0).exp();

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 12.0 * (1.0 - ns / cap);
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins deviating from mean residual (fragmentation)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Mild penalty for many open bins to discourage spreading
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fill is strongly rewarded.
        score -= 100.0;
    }

    // Reward bins whose residual can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u64 as u32 {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into fresh bins and encourage tightening existing ones.
    score += open_bins_count as f64 * 1.5;

    // Favor bins tighter than the mean residual (good fits).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.25;
    }

    // Early in the stream, allow slightly more freedom to open bins;
    // later, be strict.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 5.0;
    }

    // Mild preference for larger fills (less waste per placement).
    score -= item_size as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize dead space super-linearly, stronger as stream advances.
    let dead = post_residual as f64;
    score += 0.9 * dead * dead / bin_capacity as f64 * (0.5 + progress);

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: this bin's post_residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 45.0 + 20.0 * progress;
        } else if post_residual >= next_item_size {
            // Next item fits: reward tightness of that follow-up fit.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item does NOT fit here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer the tightest possible fit.
        score -= 10.0;
    }

    // Relative-to-mean residual: bins tighter than average are precious,
    // avoid dumping small items into them; loose bins absorb scraps.
    if (bin_residual as f64) < mean_residual {
        score += 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 30.0 * (item_size as f64 / bin_residual as f64);
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin for small items when alternatives exist.
        score += 40.0 * (1.0 - fill_ratio) * (1.0 - fill_ratio);
        if fitting_bins_count > 0 {
            score += 12.0; // open bins exist; discourage wasteful new bin
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            // Room for the next item too: make new bin more attractive.
            score -= 15.0 + 10.0 * (item_size as f64 / bin_capacity as f64);
        }
    }

    // Slight bonus for high occupancy of the chosen bin.
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear)
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    } else if post_residual >= 10 && post_residual < 50 {
        score += 8.0;  // moderately awkward leftover
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // extra reward for near-exact chain packing
            let chain_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (chain_waste as f64) / 100.0).max(0.0);
        } else {
            score += 6.0; // chain broken
        }
    } else {
        // last item: close bins as fully as possible
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize opening new bins unless current bin is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let big_item = (item_size as f64) / (bin_capacity as f64);
        // open new bin if item is large and would leave a bad residual elsewhere,
        // or early in the stream when open bins are scarce
        let open_penalty = 20.0 + 15.0 * progress + 2.0 * (open_bins_count as f64);
        score += open_penalty;
        if big_item > 0.6 {
            score -= 30.0; // big items are fine in a fresh bin
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 12.0; // room for the next item too
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins that reduce spread of residuals
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for bins below mean residual (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Time horizon: late in stream, be greedy about exact fits
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // normalized post residual
    let x = pr / cap;
    // smooth polynomial coupling with progress
    let poly = x * x * (1.0 - progress) + x * progress * progress;
    score += 8.0 * poly;
    // penalize small dead space more as stream progresses (wasted capacity matters)
    score += 6.0 * progress * (1.0 - x) * (1.0 - x);
    // reward tight fits
    score -= 4.0 * (item_size as f64 / cap) * (1.0 - x);
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - x);
    }
    // lookahead: prefer bins leaving room for next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && pr > 0 && (next_item_size as f64) > pr {
        score += 2.0 * (1.0 - pr / (next_item_size as f64));
    }
    // new bin candidate: prefer it early or when current bins are fragmented
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
        score += 4.0 * progress * (mean_residual / cap).min(1.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "usable" classes
    let residue = post_residual % 10;
    // Penalize dead-space classes (1..9 residue = unusable sliver)
    if residue != 0 {
        score += (10 - residue) as f64 * 1.5;
    }

    // Reward very tight fits (small post residual) extra
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect fit
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic divisibility: post_residual divisible by 20 is a good harbor for medium items
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item can exactly fill this bin's post residual, strongly favor
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item fits comfortably in post residual (integer division harmonic)
    if next_item_size > 0 && next_item_size <= post_residual / 2 {
        score -= 8.0;
    }
    // Penalize leaving post_residual that next item cannot use at all
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate handling
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base bonus for opening a fresh bin when few alternatives exist
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // If current item would leave a bad residue in any open bin, prefer fresh bin
        if item_size % 10 != 0 && post_residual % 10 != 0 {
            score -= 12.0;
        }
        // Early stream: opening bins is cheap, keep flexibility
        let progress = step_index as f64 / total_items as f64;
        if progress < 0.5 {
            score -= 8.0 * (1.0 - progress);
        }
        // Late stream: consolidate into open bins instead
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Mild preference to drain bins when many are open
    score -= 0.3 * open_bins_count as f64;

    // Tie-break: prefer bins below mean residual (consolidation)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1)
    // or for the lookahead item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, zero waste
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap cannot host the next item: penalize proportionally to unusability
        let unusable = (next_item_size - post_residual) as f64;
        score += unusable * 2.0;
    }

    // Penalize leaving gaps below the minimum item size range but above 0
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 15.0;

    // Open-bin pressure: discourage opening new bins when alternatives exist
    if bin_residual == bin_capacity {
        // brand-new bin candidate
        if fitting_bins_count > 0 {
            score += 60.0 + 5.0 * open_bins_count as f64;
        } else {
            score += 10.0; // forced to open anyway, mild penalty
        }
    } else {
        // using an existing bin reduces open-bin growth pressure
        score -= 5.0;
        if fitting_bins_count == 1 {
            // last-chance bin: strongly favor using it
            score -= 40.0;
        }
    }

    // Slight preference for bins with residuals near the mean (balanced packing)
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    // Late in stream: be more greedy about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= tightness * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain fit: next item fills this bin exactly
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            // penalize mismatch, scaled by how "wasteful" the leftover would be
            score += gap * 0.35;
        }
    } else {
        // last item: prefer tightest fit only
        score -= 10.0;
    }

    // Reward bins tighter than the mean residual (well-filled bins first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize large dead space that no item (min size 1..10) can plausibly use.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill, very desirable
    } else if post_residual > 50 {
        score += 15.0; // large leftover risks fragmentation unless chain fit
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but allow opening a new bin late in the stream when few bins fit
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Slight progression bias: early on, consolidate; late, prioritize tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1) can use well:
    // small post_residual values are fine; large ones waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly perfect fill
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement (creates a perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; slight penalty for leaving
            // residual smaller than next item (dead space for lookahead).
            score += 4.0;
        }
    } else {
        // Last item: absolutely minimize post residual.
        score += 2.0 * post_residual as f64;
    }

    // Scarcity: if this is the only bin that fits, strongly favor using it
    // (avoid opening a new bin when the item would otherwise fit nowhere).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make an empty bin mildly attractive only
    // when existing bins would leave large unusable residuals or the fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; late, prefer filling existing ones.
        let openness = 1.0 - progress;
        score -= 5.0 * openness;
        // If no open bin fits well (best alternative residual large), open new bin.
        if post_residual == 0 {
            score -= 15.0; // item exactly fills a fresh bin
        }
        if (mean_residual - item_size as f64) < 5.0 && fitting_bins_count > 0 {
            score -= 6.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate,
    // penalize spreading into new space, reward filling fragmented bins.
    if open_bins_count > 2 {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 10.0 * fragmentation * (open_bins_count as f64).ln();
        // Bins below mean residual are the "crumbs" — filling them is good.
        if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
            score -= 6.0;
        }
    }

    // Time horizon: as the stream ends, weight absolute waste more heavily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    // Mild penalty for very large items going into nearly-full bins when a
    // better spread exists (keep big-item flexibility).
    if item_size > 60 && bin_residual < bin_capacity {
        score += 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress
    let mut score = pr
        + 30.0 * norm_pr * norm_pr
        - 20.0 * norm_pr * norm_pr * progress
        + 10.0 * norm_pr * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits (small post_residual), smoothly
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr > 0.0 && pr < ns {
            score += 25.0 * (1.0 - pr / ns) * (0.5 + 0.5 * progress);
        } else if pr >= ns {
            score -= 8.0 * (ns / cap) * (1.0 - norm_pr);
        }
    }

    // Last-chance bin bonus: avoid opening new bins when only one bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual early (keep big spaces open), above later
    score += 5.0 * ((pr - mean_residual) / cap) * (2.0 * progress - 1.0);

    // Mild penalty for opening a new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small dead space are prized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 8.0;
    } else if pr <= 30 {
        score += 5.0;
    } else {
        score += 12.0; // large dead space
    }

    // Integer division thresholds: post_residual bucketed by deciles of capacity.
    let dec = (pr * 10) / bin_capacity; // 0..10
    score += dec as f64 * 1.5;

    // Modulo arithmetic: residuals congruent to common item sizes are reusable.
    let m = pr % 10;
    if m == 0 {
        score -= 6.0;
    } else if m <= 2 {
        score -= 3.0;
    }

    // Lookahead coupling: reward residuals that can host next item exactly.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > pr {
        // next item cannot fit here; residual becomes dead space
        score += (next_item_size - pr) as f64 * 0.4;
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer crowded bins when many bins are open (consolidation pressure).
    score -= (bin_residual as f64 / cap) * open_bins_count as f64 * 0.8;

    // Early stream: slightly favor opening bins to build diversity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    // Mean-residual coupling: penalize bins far below mean residual (already tight).
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus: zero waste is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: residual barely larger than item means good packing.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 8.0 / (1.0 + tightness);

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 30.0 + pressure;
    } else {
        score -= 0.5 * pressure;
    }

    // Mean-residual coupling: prefer bins whose residual is above average
    // (consume slack where it is abundant), avoid creating outliers.
    if bin_residual != bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if the next item would fit in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // next item cannot use the leftover: dead space likely
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: strongly reward.
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snug the chain is.
            let snug = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.25 * snug;
        } else {
            // Next item does not fit: penalize wasting space the next item needed.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: only attractive when item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if big_item || (fitting_bins_count <= 1 && post_residual as f64 > 0.5 * bin_capacity as f64) {
            score -= 8.0 + 10.0 * progress;
        } else {
            score += 25.0;
        }
    }

    // Mild preference for tighter fits overall.
    score += 0.05 * (bin_residual - item_size) as f64;

    // Late in stream: prioritize closing bins (small post_residual) more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.1 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is already good; amplify non-linearity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (next_item_size - post_residual) as f64;
    }

    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage unless current fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Penalize new bins; relax penalty late in stream or when no bin fits.
        score += 40.0 * (1.0 - poor_fits) * (1.0 - 0.5 * progress);
        // If mean residual is high, open bins are fragmented; new bin is fine.
        score -= 0.2 * mean_residual;
    }

    // Mild penalty for large post-residuals that are awkward (small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference for filling bins with more residual than the mean
    // (balance load across open bins, keep some bins tight for big items).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), non-linearly shaped by progress
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth interaction: as stream progresses, tighten tolerance for waste
    score += norm_pr * norm_pr * (1.0 - progress) * 4.0;

    // Reward large fill fraction with a saturating polynomial
    let fill = 1.0 - norm_pr;
    score -= fill * fill * (3.0 - 2.0 * fill) * 6.0;

    // Penalize bins whose post-residual can't fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 3.0 + (nxt - pr) / cap * 8.0;
        } else {
            // smooth reward when lookahead also fits
            let slack = (pr - nxt) / cap;
            score -= 2.0 * (-slack * 5.0).exp();
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mild pressure toward consolidating into fewer bins
    score += (open_bins_count as f64) * 0.05 * norm_pr;

    // Encourage deviation from mean residual toward fuller bins (smooth quadratic)
    let dev = norm_pr - mean_residual / cap;
    score += dev * dev * 2.0;

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - fill) + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space under
    // the smallest plausible item (~10) is pure waste — penalize harshly
    // via a harmonic-class style threshold on post_residual.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual <= 25 {
        score -= 2.0;
    }

    // Harmonic class of the fill level: integer division thresholds.
    let fill_class = (item_size * 4) / bin_capacity; // 0..=3 quarters
    match fill_class {
        3 => score -= 6.0,  // big item: prefer dumping into existing space
        2 => score -= 2.0,
        _ => {}
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let waste = post_residual as f64;
            if waste > 0.0 && waste < next_item_size as f64 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are poor. Give the empty bin a baseline that keeps it
    // competitive for large items but loses for good fits elsewhere.
    if bin_residual == bin_capacity {
        // baseline: like post_residual = capacity - item_size, plus a
        // mild preference when few bins are open or stream is early.
        let mut nb = (bin_capacity - item_size) as f64 + 18.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count <= 1 {
            nb -= 30.0;
        }
        if progress < 0.1 {
            nb -= 5.0;
        }
        // If mean residual across open bins is small, a new bin is cheap.
        if mean_residual < 20.0 {
            nb -= 6.0;
        }
        score = nb;
    }

    // Mild tie-breaking: prefer bins with residuals far from the mean
    // (consolidate similar residual classes via modulo buckets).
    let bucket = (post_residual / 10) as f64;
    let mean_bucket = (mean_residual / 10.0).floor();
    if bucket == mean_bucket {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small but potentially usable gaps: moderate penalty scaled by gap.
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new bins; prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 * 0.6;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, softened when the
        // item is large and existing residuals are small (poor fits elsewhere).
        score += 12.0 + pressure;
        let mean_r = mean_residual;
        if (mean_r - item_size as f64) < 5.0 {
            score -= 10.0; // existing bins would leave bad fits anyway
        }
        // Lookahead: if next item is small, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 8.0;
        }
    } else {
        // Fitting into an existing bin reduces pressure slightly.
        score -= pressure * 0.15;
        // Lookahead synergy: if next item fits exactly into the post residual,
        // reward this placement.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 18.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (build
    // diversity of residuals); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 6.0;
    } else {
        score += progress * 3.0;
    }

    // Mild penalty when this bin's residual deviates far above the mean
    // (keeps residual distribution tight and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: next item fills this bin completely
        } else if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving moderately-sized holes
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0).min(1.0);
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are better targets
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Penalize creating dead space that nothing (size >= 10) can use
    if post_residual < 10 {
        score -= 25.0; // zero-waste completion is great
    } else if post_residual < 20 {
        score += 5.0; // small awkward hole
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when open bins would be badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 35.0 - 10.0 * fragmentation.min(3.0);
        // Open a fresh bin if the current item is large and lookahead is large too
        if item_size >= 60 && next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Early in stream: be slightly more willing to spread across bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing (min item 1..100 unknown) can use,
    // but only mildly since distribution is unknown.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, this is a great chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let chain_quality = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_quality;
        } else {
            // Next item cannot use the leftover: penalize proportionally to waste.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would leave bad residual. Penalize opening a new bin generally,
    // scaled by how many bins are already open and stream progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if mean residual across open bins is very low (all nearly full),
        // opening fresh is reasonable: reduce the penalty.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Time-horizon coupling: early in the stream, be conservative (keep bins
    // flexible); late in the stream, accept tighter fits aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Deviation from mean residual: bins far below mean residual are the
    // "ragged" ones; using them reduces fragmentation.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_density = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post-residual, with smooth non-linear sharpening.
    let mut score = pr * (1.0 + 0.6 * pr / cap) - 18.0 * fit_density * fit_density;

    // Dead-space penalty: residuals too small for typical future items.
    let dead = (1.0 - pr / cap).powi(2);
    score += 10.0 * dead * (1.0 - progress);

    // Smooth stream-progress coupling: tighten packing as stream advances.
    score += 6.0 * progress * (pr / cap).powi(2);

    // Lookahead: reward residuals that still fit the next item, penalize near-misses.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 5.0 * (nx - pr) / nx;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly when existing bins fit well,
    // reward opening a new bin when fragmentation is high.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let frag = (mean_residual - pr).abs() / cap;
        score += 30.0 - 20.0 * (1.0 - fit_density.min(1.0)) - 15.0 * (1.0 - progress);
        score += 12.0 * (1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)).min(1.0));
    } else {
        score += 4.0 * (mean_residual / cap - pr / cap).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity quartiles.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 40.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 15.0;
    }

    // Penalize dead space that cannot fit typical small items (harmonic classes of 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo coupling: residual divisible by common item sizes is reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits in post_residual, reward keeping this bin usable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // next item would have fit if we hadn't placed here — mild penalty.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        // If item is large and no bin fits well, opening a new bin can be OK.
        if item_size > bin_capacity * 3 / 4 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Progression: late in stream, tighten packing (prefer tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.05 * progress;

    // Penalize bins far from mean residual (fragmentation spread).
    score += ((pr - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest item (1..=10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0;
    }
    // Reward residual that can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }
    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Pressure from many open bins: discourage opening new bins
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }
    // Early stream: mild preference to keep bins balanced
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact / tight fits (low post_residual).
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 25.0;
        } else if post_residual as f64 >= next {
            // next item fits too: pair placement bonus proportional to tightness
            score -= 12.0 * (next / (post_residual as f64));
        } else {
            // next item won't fit here: penalize wasted residual that is too small
            // for the next item (dead space risk), scaled by how far it falls short.
            let gap = next - post_residual as f64;
            score += 6.0 * (gap / 100.0).min(1.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are preferred targets.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_residual - item_size {
        score -= 8.0;
    }

    // Penalize leaving residual below the smallest plausible item (dead space),
    // but only mildly for very small leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Mild preference against opening new bins when many bins are already open.
    score += 0.05 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + 0.15 * (open_bins_count as f64);
        // Late in the stream, prefer consolidating into open bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        return score;
    }

    // Reward tight fits: smaller post_residual already helps; amplify non-linearly.
    score -= 0.6 * ((bin_capacity - post_residual) as f64).powi(2) / bin_capacity as f64;

    // Dead-space penalty: very small leftover space is wasted unless it's zero.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that are already committed (low residual).
        score -= 0.3 * (bin_capacity - bin_residual) as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, keep this bin
    // for the next item; penalize consuming it now unless this is a perfect fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score += 15.0; // save this bin for the next item
        } else if next_item_size < post_residual && next_item_size >= post_residual.saturating_sub(10) {
            score += 6.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> encourage
    // filling existing bins rather than spreading items.
    if mean_residual > 30.0 && open_bins_count > 2 {
        score -= 0.1 * mean_residual;
    }

    // Time horizon: early on, keep bins balanced; late, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: reward small post-residual (tight fit), non-linearly
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = x * x;
    let cube = quad * x;
    score += (0.5 * quad + 0.3 * cube) * cap * (0.5 + progress);

    // Penalize dead space that no small item can use later
    if x > 0.0 && x < 0.1 {
        score += 8.0 * (0.1 - x) * cap;
    }

    // Reward using nearly-full bins, stronger late in the stream
    let tightness = 1.0 - x;
    score -= tightness * tightness * 5.0 * (1.0 + 2.0 * progress);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 3.0 + 2.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        score += 1.5;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins below mean residual early on (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: overwhelmingly preferred.
    if post_residual == 0 {
        return -10000.0;
    }

    // Harmonic class of the leftover: multiples of 10 are "reusable" classes
    // (typical item sizes align to decade grids), odd/prime-ish remainders are dead space.
    let class = post_residual % 10;
    score += match class {
        0 => -15.0,
        1 | 3 | 7 | 9 => 12.0,
        2 | 4 | 6 | 8 => 6.0,
        5 => 3.0,
        _ => 0.0,
    };

    // Lookahead coupling: reward leaving room for the next item,
    // penalize stranding a remainder that cannot host it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // bonus scaled by how well the next item nests in the remainder
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.3;
        } else {
            score += 25.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate evaluation: base cost is the wasted space this item
    // leaves in a fresh bin; only attractive if no (or one poor) alternative exists.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced opening
        } else if fitting_bins_count == 1 {
            score += 40.0; // an existing bin is a last chance; keep it
        }
        // large items fragment future space less in a fresh bin
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer consolidating into bins with fat mean residual.
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score -= prog * 10.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (<= 10, or < next item) are wasted space.
    let min_item = 10u32;
    if post_residual < min_item {
        score -= 60.0; // perfect-ish fill, dead space unusable anyway
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual can't host the lookahead item: dead space for the horizon
        score += (post_residual as f64) * 1.5;
    } else {
        // usable residual: reward proportionally
        score -= (post_residual as f64) * 0.4;
    }

    // Tight-fit reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Open-bin pressure: prefer spreading when many bins are open,
    // prefer consolidation (new bin) when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (4.0 + 6.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty so among multiple candidates the best-fit wins via post_residual
        score += 2.0;
    }

    // New-bin candidate adjustment: an empty bin has huge residual; make it
    // attractive only when mean residual of open bins is very low or the
    // item is large and would leave a bad gap elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let gap_penalty = (mean_residual - post_residual as f64).max(0.0);
        score -= gap_penalty * 0.8;
        if item_size >= 60 {
            score -= 10.0; // large items fit anywhere; prefer fresh bin to keep small gaps
        }
    }

    // Mean-residual coupling: if this bin is far below the mean residual,
    // it is the "driest" bin; prefer filling driest bins first.
    let dryness = mean_residual - bin_residual as f64;
    score += dryness * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item perfectly fills the remaining space.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            // Next item fits exactly-ish: reward closeness, penalize slack left after that.
            let post2 = post_residual as f64 - next_item_size as f64;
            score -= 30.0 * (1.0 - post2 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to how much dead space remains.
            score += 10.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Reward bins whose residual is below mean (tight bins pack better with big items).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when it creates a perfect future fit or fits are scarce.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 15.0;
        } else {
            score += 25.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Penalize leaving tiny unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for filling bins tighter as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Strongly reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that no realistic item can use (min item 1, but
    // typical items are larger): residual below 10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.3;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty, worse if slack is small.
        score += 8.0;
    }

    // Penalize wasting a nearly-empty bin's flexibility: prefer placing into
    // bins with low residual when the fit is loose.
    let residual_gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score += residual_gap * 0.15;

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate scoring.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 80.0;
        // If no bin fits at all (this is the only candidate), it must be chosen.
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        new_bin_score -= (1.0 - progress) * 25.0;
        // If mean residual is high, opening a new bin wastes existing capacity.
        new_bin_score += mean_residual * 0.4;
        // Many open bins: discourage another one.
        new_bin_score += open_bins_count as f64 * 2.0;
        // If the lookahead item is large, a fresh bin gives flexibility.
        if next_item_size > 50 {
            new_bin_score -= 15.0;
        }
        return new_bin_score;
    }

    // Mild preference for bins whose residual is close to item_size (best-fit bias).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Time-horizon modulation: late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual < 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core: quadratic waste penalty, scaled by stream progress
    let mut score = pr + (pr / cap) * (pr / cap) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - (item_size as f64) / (bin_residual.max(1) as f64);
    score -= (1.0 - tightness) * item_size as f64 * 0.3;

    // Smooth coupling of post_residual with mean residual: penalize making bin
    // residual deviate far from the fleet mean (keeps residual diversity useful)
    let dev = pr - mean_residual;
    score += 0.1 * dev * dev / cap;

    // Lookahead: bonus if next item fits into post_residual exactly-ish
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap);
    } else if next_item_size > post_residual {
        // penalize stranding next item
        score += 5.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: opening a new bin wastes capacity; penalize unless
    // item is large relative to residual (poor fits elsewhere) or late stream
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64) / (1.0 + progress * 10.0);
        score = cap as f64 * (0.8 + 0.02 * openness) - 10.0 * (item_size as f64 / cap);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin can host the growing stream
        }
    }

    // Mild penalty for many open bins to encourage consolidation early
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that pair well
    // with common item size classes (multiples of 10 / small divisors).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Dead-space penalty: residuals that are "orphaned" (too small for the
    // smallest plausible item) get a strong penalty.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Modulo-class reward: residual divisible by common class widths (e.g. 10, 20, 25)
    // is more likely to be exactly filled by future items.
    let mut harmony = 0.0f64;
    for m in [5u32, 10, 20, 25, 50].iter() {
        if post_residual % m == 0 {
            harmony += 4.0;
        }
    }
    score -= harmony;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // reward proportional closeness of fit
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            // next item cannot use this residual at all: mild penalty scaled by orphan size
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Tight fit reward: quadratic bonus for small post_residual.
    score -= 6.0 * (1.0 - frac) * (1.0 - frac);

    // Penalize leaving residuals in the "awkward band" (e.g. 1..10) that few items fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Early in stream: slight preference to consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: penalize opening a new bin unless current bin would be
    // left with a very awkward residual or this is a poor fit overall.
    if bin_residual == bin_capacity {
        // A fresh bin is fine early (progress small) or when item is large relative to capacity.
        let item_frac = item_size as f64 / cap;
        score += 6.0 * progress;                     // later => discourage new bins
        score -= 10.0 * item_frac;                   // large items justify new bins
        if next_item_size > 0 && (next_item_size as f64) <= (cap - item_size as f64) {
            score -= 3.0; // next item can share the fresh bin
        }
    }

    // Slight nudge toward bins whose residual is close to the mean residual
    // (keeps bin population homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fill is perfect, but flag overflow safety
    }
    // Penalize unusable small gaps (<10) harshly, scaled by how unusable they are.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Penalize medium gaps (<25) moderately: unlikely to fit typical items.
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 2.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5 + 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer using existing bins unless this bin is the last chance or fit is poor.
        score += 30.0 + open_bins_count as f64 * 1.5;
        // But allow new bin if no open bin fits well (fitting_bins_count small handled via pressure).
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly prefer filling it rather than opening a new one.
        score -= 40.0;
    }

    // Mild global pressure: when many bins are open, prefer tighter packing (larger post_residual tolerance shrinks).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    // Slight preference for bins below mean residual (balancing).
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match strongly rewarded
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Exact match: next item fills bin completely
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Next item slightly too large: small penalty (dead space)
        if next_item_size > post_residual {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 10.0;
    }

    // Relative-to-mean coupling: bins with residual far from mean are
    // penalized when post_residual deviates strongly.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if next item pairs well with a fresh full bin's post placement,
        // a new bin is fine (lookahead pairing with large items)
        if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 30.0;
        }
    }

    // Prefer bins with low residual overall (tight packing)
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward filling the bin well
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize large dead space that is hard to reuse
    if post_residual > 0 {
        let dead = post_residual as f64;
        // dead space is worse when it's small-but-unusable relative to typical item sizes
        score += 0.5 * dead;
        if dead < 10.0 {
            score += 15.0; // tiny sliver, nearly unusable
        }
    } else {
        score -= 30.0; // perfect fit
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else {
            score += 0.3 * next_item_size as f64;
        }
    }

    // Global state: many open bins -> prefer consolidating into existing bins
    let open_norm = open_bins_count as f64;
    score += 0.05 * open_norm * (1.0 - fill_ratio);

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.2 * residual_gap;

    // Time horizon: early on, be picky (penalize mediocre fits); late, pack aggressively
    let pickiness = 1.0 - progress;
    score += 10.0 * pickiness * (1.0 - fill_ratio);

    // New empty bin candidate: only attractive when item is large or nothing else fits well
    if bin_residual == bin_capacity {
        let base_penalty = 60.0; // default: prefer existing bins
        let relief = 50.0 * fill_ratio
            + if fitting_bins_count <= 1 { 70.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= bin_capacity - item_size { 20.0 } else { 0.0 };
        score += (base_penalty - relief).max(-20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual
    let fit_ratio = it / cap;

    // Base: waste after placement, softly compressed
    let mut score = pr as f64;

    // Smooth non-linear coupling: prefer small-but-nonzero residuals via quadratic bowl
    score -= 60.0 * x * (1.0 - x);

    // Stream progress: as stream advances, tighten tolerance for large residuals
    score += 40.0 * progress * x * x * cap;

    // Dead-space penalty: residual too small for plausible future items
    let nx = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };
    let unusable = (nx - x).max(0.0);
    score += 80.0 * unusable * (1.0 - progress);

    // Perfect fit reward (smooth)
    score -= 25.0 * (1.0 - x).powi(6);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Crowding: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 5.0 * x;

    // Mean residual coupling: keep global residual spread balanced
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // New-bin candidate: penalize opening a fresh bin when item is small, reward when item is huge
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - fit_ratio) * (1.0 - progress);
        score -= 20.0 * fit_ratio * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // capacity-fraction octaves. Smaller octaves (waste) are penalized harder
    // than linear; large residuals are rewarded (still reusable).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let octave = (pr / cap * 8.0).floor().min(7.0); // 0..7 harmonic class
    score += (7.0 - octave) * (7.0 - octave) * 1.5; // quadratic penalty per class step

    // Exact-fit / perfect packing bonus (residual in low harmonic classes).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: reward if the next item can exactly consume the
    // remaining residual (harmonic match), penalize if next item overshoots
    // the residual leaving this bin stranded anyway.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let match_err = (pr - nx).abs();
            if match_err <= 3.0 {
                score -= 25.0; // next item completes this bin
            } else {
                score -= 10.0 / (1.0 + match_err / cap);
            }
        } else {
            score += 8.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mildly discourage opening new bins when many are already open and
    // mean residual is high (aggregated slack).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * (1.0 - progress) + mean_residual * 0.05;
    } else {
        // Prefer bins with residual far below mean (tight bins) slightly.
        score += ((pr - mean_residual) * 0.02).clamp(-5.0, 5.0);
    }

    // Integer-division threshold on post_residual: residuals that are
    // multiples of common small item sizes are more reusable.
    let pr_i = post_residual;
    if pr_i % 10 == 0 && pr_i > 0 {
        score -= 6.0;
    }
    if pr_i % 20 == 0 && pr_i > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // marginally usable
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual was already small (tight packing pressure).
    score += (bin_residual as f64) * 0.15;

    // Open-bin pressure: discourage spreading into many bins.
    score += open_bins_count as f64 * 0.5;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item cannot fit, penalize the dead space more.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.4;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // New-bin candidate handling: only choose a fresh bin when the item is
    // large and would leave a poor residual in an existing bin, or when no
    // existing bin fits well.
    if bin_residual == bin_capacity {
        if item_size >= 50 {
            score -= 10.0; // large items start fresh bins cheaply
        } else {
            score += 20.0; // small items should fill existing bins
        }
        // Early in stream, fresh bins are fine; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight preference toward bins below mean residual (consolidate slack).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (50.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here: penalize proportionally to the leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when many bins are open.
    let mean_gap = mean_residual - post_residual as f64;
    if open_bins_count > 1 {
        score -= 0.3 * mean_gap;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened casually.
        score += 250.0;
        // If the item is large relative to capacity, a fresh bin is more reasonable.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 200.0 * frac;
        // Lookahead: fresh bin can host current + next item nicely.
        if next_item_size > 0 && (item_size + next_item_size) as f64 <= bin_capacity as f64 {
            score -= 150.0;
        }
        // If this bin is the only fitting option, opening a new bin is less costly.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
    }

    // Slight stream-progression pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> be picky; late stream -> consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (low post_residual) more strongly as stream progresses.
    score -= (bin_capacity as f64 - post_residual as f64) * (0.6 + 1.2 * progress) * 0.5;

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leaves more fragmentation: mild penalty proportional to waste
            let nxt_left = post_residual - next_item_size;
            score -= 25.0 - 0.3 * nxt_left as f64;
        } else {
            // next item cannot follow here: penalize bins that would strand space
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // (avoids opening a new bin), especially early/mid stream.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins -> favor filling existing ones over spreading; few open bins -> allow new bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 0.4 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Penalize leaving residual far from mean residual (fragmentation outlier avoidance),
    // but relax this late in the stream.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - 0.6 * progress);

    // New-bin candidate: only attractive when item is huge relative to capacity or
    // existing residuals are poor; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 55.0 * fill_ratio;
        // if open bins are very fragmented, new bin becomes more attractive
        score -= 0.2 * mean_residual.max(0.0).min(bin_capacity as f64) * (1.0 - fill_ratio);
        // late stream: opening new bins is wasteful
        score += 25.0 * progress;
    }

    // Small global bonus for using bins with already-low residual (pack tight bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: residual cost warped by stream progress.
    let norm_pr = pr / cap;
    let warp = 1.0 + 2.0 * progress * progress;
    score += 40.0 * norm_pr * norm_pr * warp;

    // Tight fits rewarded more strongly as the stream progresses.
    let fit = (item_size as f64) / (bin_residual as f64);
    score -= 25.0 * fit * fit * (0.5 + progress);

    // Penalize residuals that cannot host the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 30.0 * (1.0 - pr / nx) * (1.0 + progress);
        } else {
            score -= 10.0 * (nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins, coupled with mean residual.
    score += 3.0 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: discourage unless existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes.
    // Perfect fills (post_residual == 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small to be useful later.
        // Items are 1..100, but small residuals (<10) are nearly dead.
        if post_residual < 10 {
            score += 40.0;
        }
        // Harmonic classes: check divisibility of post_residual by
        // common granularity classes (2,4,5,8,10,16,20,25,50).
        // A residual divisible by a class is more likely to be filled
        // exactly by future items of that class size.
        let classes: [u32; 9] = [2, 4, 5, 8, 10, 16, 20, 25, 50];
        let mut harmony = 0.0f64;
        for (k, &c) in classes.iter().enumerate() {
            if post_residual % c == 0 {
                harmony += 1.0 / ((k as f64) + 1.0);
            }
        }
        score -= harmony * 8.0;

        // Integer-division thresholds: residual in a "good band"
        // (multiple of 10 but nonzero) is reusable by typical items.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 5.0;
        }

        // Coupling with lookahead item: if next item fits exactly
        // into post_residual, strong reward; if it fits at all, mild reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 60.0;
            } else if next_item_size <= post_residual {
                score -= (post_residual - next_item_size) as f64 * 0.3;
            } else {
                // next item cannot use this residual: penalize
                // proportionally to wasted harmonic potential.
                score += (next_item_size - post_residual) as f64 * 0.15;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave
    // awkward dead space and stream is early (many items remain).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = if post_residual > 0 && post_residual < 15 { 1.0 } else { 0.0 };
        score += 30.0 - awkward * 45.0 - (1.0 - progress) * 10.0 + open_bins_count as f64 * 0.5;
    }

    // Mild tie-break toward compacting the global state.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky if the next item cannot use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward when the leftover exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // New-bin candidate (empty bin): make it attractive only when the
    // current bin would leave a large, awkward residual or the item is big.
    if bin_residual == bin_capacity {
        if item_size > 60 || post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size) {
            score -= 45.0; // open a fresh bin rather than fragmenting
        } else {
            score += 40.0; // prefer existing bins for decent fits
        }
    }

    // Mild pull toward bins with below-average residual (already compacted).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is better, but only if usable.
    if post_residual == 0 {
        score -= 200.0; // perfect fit: close the bin
    } else if post_residual < 10 {
        score -= 40.0; // near-perfect fit
    }

    // Aggressive 2-step lookahead: reward bins whose residual matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // chain: next item fills this bin perfectly
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 15 {
                score -= 60.0; // next item leaves a small usable remainder
            } else {
                score += 0.15 * gap as f64; // large leftover penalized mildly
            }
        } else {
            // next item won't fit: residual becomes dead space until later
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins below-average residual
    // (consolidating space) when they still fit well.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 0.0 };
        score += 120.0 - desperation;
        // allow new bin when very few open bins and item is large
        if item_size > 60 && open_bins_count > 0 {
            score -= 30.0;
        }
    }

    // Mild stream-progression pressure: later in stream, prefer filling existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight_fit * tight_fit;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // small unusable sliver
    }

    // Lookahead coupling: if next item exactly fits post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to overshoot
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer fullest packing
        score -= 30.0;
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins unless
    // the item is large relative to mean residual of open bins.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        let waste_if_force = (mean_r - item_size as f64).max(0.0);
        score += 55.0 - 40.0 * (item_size as f64 / bin_capacity as f64) - 0.3 * waste_if_force;
        // late in the stream, prefer closing out open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer bins below mean residual (balancing), scaled by congestion.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev * (1.0 + open_bins_count as f64 * 0.05);

    // Time horizon: early on, keep flexibility (favor larger post-residual bins);
    // later, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize many open bins mildly to encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual (tight packing), non-linearly shaped.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: as the stream progresses, tighten preference for
    // small post residuals (dead space becomes costlier later).
    score *= 1.0 + 0.6 * progress * norm_post;

    // Interaction with mean residual: bins far below mean residual are better
    // targets (concentrate waste); bins above mean get penalized smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * (1.0 - norm_post);

    // Lookahead coupling: reward leaving room for the next item; penalize
    // post residuals that just barely fail to fit next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // smooth reward proportional to how well next item nests
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // near-miss penalty: dead space that almost fit the next item
            let miss = (nxt - post) / cap;
            score += 12.0 * miss * (1.0 - miss);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, mildly prefer tighter ones (already via post)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: empty bin. Penalize opening a new bin unless the item
    // fits poorly everywhere else (large post residual elsewhere makes new bin
    // attractive since its post residual is huge; counteract with a penalty
    // scaled by stream progress and open bin count).
    if bin_residual == bin_capacity {
        let new_bin_post = (bin_capacity - item_size) as f64;
        let waste = new_bin_post / cap;
        // base penalty for opening a bin, decaying as stream progresses
        score += 30.0 * (1.0 - 0.5 * progress) + 20.0 * waste * (1.0 - progress);
        // if many bins are open and fragmented, opening fresh is less bad
        score -= 1.5 * (open_bins_count as f64).min(20.0);
        // if next item is large, a fresh bin is more valuable
        if next_item_size > 0 {
            score -= 0.05 * next_item_size as f64;
        }
    }

    // Gentle global tightening late in stream
    score -= 5.0 * progress * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes mod 10.
    // Classes that pair well with common item sizes (multiples of 10) are rewarded.
    let class = post_residual % 10;
    let harmonic_bonus: f64 = match class {
        0 => 6.0,   // perfect multiple of 10, most reusable
        5 => 2.0,   // half-class, moderately reusable
        2 | 4 | 6 | 8 => 0.0,
        _ => 3.5,   // odd leftovers are awkward dead space
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: large usable chunks are valuable.
    let chunk = post_residual / 25; // 0..=4 quarters of usable space
    score -= chunk as f64 * 8.0;

    // Penalize tiny unusable dead space (< 10, minimum item size).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits, but check the chain residue class too
            let chain_class = (post_residual - next_item_size) % 10;
            if chain_class == 0 {
                score -= 15.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use this bin's leftover: leftover likely wasted
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    } else {
        // last item: any fit is fine, prefer tightest
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins offer bad fits. Give it a moderate default score.
    if bin_residual == bin_capacity {
        score = 55.0
            + post_residual as f64
            - (open_bins_count as f64).min(20.0) * 0.5
            + if next_item_size > 0 && next_item_size > bin_residual {
                10.0
            } else {
                0.0
            };
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits, must open
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual tightly matches the item (best-fit sharpening).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Slight preference for keeping mean residual high (avoid fragmenting full bins).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when open bins are crowded or fit is terrible.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.8 + mean_residual * 0.05;
        score -= pressure;
        if post_residual < 25 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect chain fit (item exactly fills bin, next item fits remaining)
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that neither fits next item nor is small dead space
        if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 20.0; // dead space creation
        }
    } else {
        // Last item: prefer tightest fit
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize near-full bins slightly less than wasteful large residuals
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * tightness * tightness;

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral baseline, penalize slightly unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 40.0 - 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post residual scaled by how "wasted" it is relative to mean residual.
    let waste = post_residual as f64 - mean_residual;
    score += 0.35 * waste.max(0.0);

    // Reward tight fits: small post residual relative to item size.
    if item_size > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / (bin_residual as f64 + 1.0));
    }

    // Lookahead: if the next item fits the post residual, reward this bin strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space that cannot serve the next item: penalize proportionally.
            score += 0.5 * post_residual as f64 * (next_item_size as f64 / (post_residual as f64 + next_item_size as f64));
        }
    } else {
        // Last item: just minimize post residual.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (penalize
    // filling bins too tightly early); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses unless current bin is very tight.
        score += 4.0 + 20.0 * progress;
        // But if all open bins would leave terrible residuals, allow opening a new bin.
        if post_residual >= 40 {
            score -= 6.0 * progress;
        }
    } else {
        // Open bin: reward more as stream progresses (consolidation pressure).
        score -= 3.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Mild penalty for leaving residuals in the awkward 1..10 range (hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), non-linearly coupled with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Dead-space penalty: quadratic in normalized residual, amplified late in stream
    score += norm_pr * norm_pr * cap * (0.5 + 1.5 * progress);

    // Reward last-chance bins (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt).abs();
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 4.0;
        }
    }

    // Coupling with mean residual: penalize bins far from the mean (keeps diversity usable)
    let dev = (pr as f64 - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Mild preference for existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residuals that could hold common
    // future item sizes (multiples of 10) are valuable; odd/dead classes penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead space: residual below the minimum plausible item size is nearly useless.
    if post_residual < 10 {
        score += 40.0;
    }

    // Harmonic class via integer division: residuals divisible by 10 can be
    // exactly filled by standard items -> reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        // odd class: penalize fractional waste
        score += 6.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual,
    // this bin is a great chain candidate.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: mild reward scaled
            // by how well it harmonizes (post2 divisible by 10).
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 {
                score -= 20.0;
            } else if post2 < 10 {
                score += 10.0; // creates dead space after next item
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: slight penalty if residual is large
            // enough that it's "wasted" on small future items.
            if pr > 50.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins whose post_residual stays small; only open a
    // new bin when existing residuals would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing as stream progresses
        // (fewer chances left to amortize the bin).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 20.0 * progress;

        // If open bins are already fragmented (high mean residual), a fresh
        // bin is more attractive.
        score += (mean_residual / cap) * 30.0;

        // Don't open a new bin for a tiny item when good fits exist.
        if item_size < 30 {
            score += 25.0;
        }
    } else {
        // Reusing a bin: reward tight fits relative to capacity fraction.
        let fill_frac = item_size as f64 / cap;
        score -= fill_frac * 15.0;
    }

    // Large post_residual on an old crowded bin set: encourage consolidation
    // when many bins are open.
    if open_bins_count > 8 && pr > 40.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are the worst outcome; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residual states that can still fit likely future items
    // (small items >= 1..=10 are always usable, so mild gaps are ok if >= 10).
    if post_residual >= 10 {
        // Usable leftover: mild bonus scaled by how much future items could use it.
        score -= 2.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheaper.
    let open_pressure = (open_bins_count as f64).ln().max(0.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open or the item fits
        // an existing bin well; reward when item is large relative to gaps.
        score += 10.0 * open_pressure;
        if fitting_bins_count > 0 {
            // There exists an open bin that fits; only open a new bin if the
            // item would leave a big gap there anyway.
            score += (item_size as f64).min(60.0) * 0.2;
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        score -= (next_item_size as f64) * 0.15;
    } else {
        // Existing bin: reward filling bins that are already partially used,
        // scaled by how "committed" the bin is.
        let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 8.0 * used_frac;
        // Lookahead: if next item fits exactly in this bin's post_residual,
        // strongly prefer this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate aggressively to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chain: this bin becomes exactly full next step
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (-gap / 15.0).exp(); // smooth reward for near-chain fits
        } else {
            // Next item cannot use the leftover: penalize dead space scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 40.0).min(1.5);
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // waste than other bins is bad; leaving less is good.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when open bins could reasonably fit,
    // especially early/mid stream where consolidation matters.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * (1.0 - progress); // new bins are costly, less so late
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Opening a new bin is attractive only if item is large and would leave
        // a very awkward residual elsewhere (small post_residual everywhere).
        if post_residual == 0 {
            score -= 60.0; // item exactly fills a fresh bin: great
        }
    }

    // Mild penalty for leaving residuals in the awkward 1..10 dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Encourage using bins with many siblings open (spread load) slightly less.
    if open_bins_count > 20 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * (0.4 + 0.6 * progress);

    // Penalize dead space: residuals too small to likely fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted pairing.
            score += 6.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 && mean_residual > 30.0 {
        let excess = (mean_residual - 30.0) / (bin_capacity as f64 - 30.0);
        score -= 10.0 * excess.min(1.0);
    }
    // Few open bins: mild penalty for spreading across bins.
    if open_bins_count <= 2 && bin_residual < bin_capacity {
        score += 4.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual < 15)
            || item_size > 80;
        if poor_fit {
            score -= 60.0;
        } else {
            score += 45.0 + 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: penalize leftover space, quadratically for small residuals (dead space).
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, leftover space matters more (fewer chances to fill it).
    let progress_weight = 0.5 + 1.5 * progress * progress * (3.0 - 2.0 * progress);
    score += progress_weight * pr_norm * 20.0;

    // Reward tight fits: item filling most of the bin gets a smooth bonus.
    let tightness = 1.0 - (pr_norm * 4.0 - 1.0).abs().min(1.0);
    score -= 15.0 * tightness * fit_ratio;

    // Lookahead: if the next item fits the post-residual, reward leaving usable space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let nxt_norm = nxt / cap;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        // smooth compatibility of residual with next item size
        let compat = (1.0 - (pr_norm - nxt_norm).abs()).max(0.0);
        score -= 10.0 * fits_next * compat;
        score += 6.0 * (1.0 - fits_next) * (nxt_norm * (1.0 - progress));
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mean residual context: prefer bins deviating below the mean residual
    // (consolidate into emptier bins, keep tight bins tight).
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 8.0 * dev * (1.0 - progress);

    // Slight penalty for spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // New-bin candidate: make an empty bin mildly attractive only when the item
    // is large or progress is late; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        let new_bin_bias = 20.0 - 30.0 * fit_ratio - 15.0 * progress;
        score += new_bin_bias.max(-20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands on a
    // "clean" division of capacity are more reusable later.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-class penalty: residuals that are small and not divisible by
    // common item sizes create dead space.
    if post_residual > 0 {
        let mut div_penalty = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                div_penalty -= 3.0;
            }
        }
        score += div_penalty;
        // Dead-space cliff: leftover too small for the smallest plausible item.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 8.0;
        }
    } else {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
            // Harmonic class match: next item divides the leftover evenly.
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this leftover: penalize proportional waste.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Empty new-bin candidate: only attractive when current item is large
    // relative to capacity or open bins are fragmented.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score -= 10.0 * large;
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any future item
    // (items are 1..100, so treat very small gaps as near-wasted, but keep a
    // gradient so the tightest fit still wins).
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr <= 10.0 {
            // Unusable sliver: strong penalty on top of the base value.
            score += (11.0 - pr) * 8.0;
        } else if pr <= 25.0 {
            // Likely unusable for most items: moderate penalty.
            score += (25.0 - pr) * 2.5;
        }
    }

    // Reward exact / near-exact fits (post_residual == 0 is a perfect close).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: mildly discourage spreading across many open bins
    // so we consolidate into existing bins rather than fragmenting.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has no dead-space risk yet.
    // Make it attractive only when no open bin offers a good fit, i.e. when
    // the item would leave a large awkward gap in the best existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales slightly with stream position
        // (late in the stream, consolidation matters a bit more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 20.0 * progress;
        // If lookahead item could use the leftover of a fresh bin placement,
        // opening a new bin is slightly more attractive.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
        // With very few open bins, prefer opening a new one less harshly.
        if open_bins_count <= 2 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if placing here leaves exactly the space the next
    // item needs, reward it (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when the next item fits snugly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.6 * slack;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize proportionally.
        score += 0.8 * (next_item_size - post_residual) as f64;
    }

    // Coupling with mean residual: prefer bins deviating favorably.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 10.0;
        }
    }

    // Late-stream bias: consolidate into fewer bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize dead space: residuals too small to hold the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // If next item exactly fills the bin, strong bonus.
        if next_item_size == post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, prefer opening new bins less (keep options open);
    // late in the stream, fill existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer filling bins.
    if open_bins_count > 2 && mean_residual > 20.0 {
        score -= 5.0 * (mean_residual / 100.0);
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual < 25 { 0.0 } else { 1.0 };
        score += 20.0 * poor_fit + 3.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // new bin useful if item barely fits elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = item_size as f64;
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // tight fits are increasingly rewarded as the stream advances.
    let tightness = (1.0 - pr / cap).powi(2);
    score -= 30.0 * tightness * (0.5 + progress);

    // Smooth penalty for medium-dead-space zones (non-linear in post_residual).
    let dead = (pr / cap) * (1.0 - pr / cap);
    score += 12.0 * dead * dead * (1.0 + progress);

    // Reward bins whose residual is close to the item (perfect fit term, cubic).
    let fit_gap = (bin_residual as f64 - ir).abs() / cap;
    score -= 20.0 * (1.0 - fit_gap).powi(3) * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly favor this bin when it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward;
    // if next item would be wasted, penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let exact = (pr - nx).abs();
        if exact <= 1.0 {
            score -= 15.0;
        } else if nx > pr {
            // next item can't fit here; small penalty grows with wasted residual
            score += 5.0 * (pr / cap) * (nx / cap);
        }
    }

    // Mean residual alignment: prefer bins below mean residual (tighter bins),
    // smoothly scaled by number of open bins.
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * (1.0 + (open_bins_count as f64).ln().max(1.0)) * (0.5 + progress);

    // New-bin candidate: make it moderately attractive early, less attractive
    // when good fits exist elsewhere late in the stream.
    if bin_residual == bin_capacity {
        let early = (1.0 - progress).powf(1.5);
        score = score.min(0.0) * 0.0 + 55.0 - 40.0 * early - 10.0 * (fill * 0.0 + 1.0) * (1.0 - progress);
        // base new-bin score: high when tight fits are available in open bins
        score += 20.0 * tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "friendly" to future items
    // (multiples of common size classes 10, 20, 25, 50) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 6.0; }
        // integer-division thresholds: big clean chunks are valuable
        let class = pr / 25; // 0..4
        bonus += class as f64 * 1.5;
        score -= bonus;
    } else {
        score -= 30.0; // perfect fit
    }

    // Penalize small dead space (unusable for typical items)
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap);
            if gap == 0.0 { score -= 10.0; }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / cap;
        // prefer new bin when mean residual of open bins is low and many bins open
        score = 40.0 + 30.0 * (1.0 - crowded) - 20.0 * progress;
        if open_bins_count == 0 { score = -100.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 { score -= 5.0; }
    }

    // mild penalty for proliferating bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the minimum item size (1..=8) are effectively unusable dead space.
    // Penalize them super-linearly so near-perfect fits are strongly preferred.
    if post_residual <= 8 {
        score -= 40.0 + (8 - post_residual) as f64 * 6.0;
    } else if post_residual <= 15 {
        // Small gaps: risky, may become dead if next items are large.
        score -= 6.0;
    } else if post_residual <= 25 {
        // Medium gaps: mildly useful; slight penalty relative to raw residual.
        score += 4.0;
    }

    // Reward exact fits overwhelmingly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // --- Coupling with lookahead item ---
    // If the next item fits exactly in the post residual, this placement sets up
    // a perfect follow-up; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 4.0 {
            score -= 30.0;
        } else {
            score -= 10.0 / slack.sqrt();
        }
    }
    // If the next item would NOT fit in the post residual but this bin could have
    // held it, we strand the lookahead: penalize proportionally.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 12.0;
    }

    // --- Open-bins pressure ---
    // Many open bins: prefer filling existing ones, discourage spreading.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Deviation from mean residual: prefer bins that are already fuller than average
    // (compactness bias, best-fit-like).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // --- Last-chance bonus ---
    // If this is the only bin that fits, strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin gives a decent fit
        // (i.e., the best existing option would leave a large or dead gap).
        if post_residual >= 30 && open_bins_count > 0 && fitting_bins_count > 0 {
            // Existing bins can fit; opening new is wasteful unless all fits are terrible.
            score += 60.0 + pressure;
        } else if post_residual <= 8 {
            // Fresh bin with tiny item: wasteful.
            score += 80.0;
        } else {
            // Reasonable fallback: mild bonus for clean space.
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Penalize leftover after the lookahead placement; small gaps are dead space.
            score += gap * 0.6;
            // If next item cannot fit the gap at all, extra penalty.
            if gap < next_item_size as f64 {
                score += gap * gap * 0.15;
            }
        } else {
            // Next item too big for the remaining gap: mild penalty proportional to overshoot.
            let over = (next_item_size as f64 - post_residual as f64);
            score += over * 0.25;
        }
    }

    // Compare post residual against the mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.2;
    } else {
        score += (pr - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be badly wasted.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 40.0;
        // If the new bin would be nearly filled by item + next item, allow it.
        if next_item_size > 0 && (item_size + next_item_size) >= bin_capacity * 9 / 10 {
            score -= 55.0;
        }
        if waste < 10.0 {
            score -= 20.0;
        }
    }

    // Late in the stream: prefer tighter packing (smaller post residual matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight preference for keeping number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: residual tightness rewarded with smooth decay
    let tight = 1.0 - (pr / cap).powf(2.0);
    score -= 18.0 * tight * tight;

    // Smooth interaction of item size with stream progress
    let norm_item = it / cap;
    score -= 10.0 * norm_item * (1.0 - progress) * (1.0 - progress);

    // Penalize residuals that neither fit next item nor are near zero (dead space), smooth bump
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let waste = (pr - nx).max(0.0) / cap;
        score += 22.0 * waste * waste * (1.0 - progress);
        // Reward exact-ish fit for lookahead
        let fit_gap = (pr - nx) / cap;
        score -= 12.0 * (-fit_gap * fit_gap * 40.0).exp() * (1.0 - progress);
    }

    // Last-chance bonus: smooth in fitting pressure
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild pull toward mean residual state (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (cap * cap) * 10.0;

    // New-bin candidate: penalize slightly unless residuals across bins are large
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - (mean_residual / cap).powi(2));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction band does it fall in?
    let pr = post_residual;
    let class = if pr == 0 { 0 }
        else if pr <= cap as u32 / 8 { 1 }        // tiny sliver
        else if pr <= cap as u32 / 4 { 2 }
        else if pr <= cap as u32 / 2 { 3 }
        else { 4 };                                // more than half empty

    // Reward placements whose leftover matches the NEXT item's size class (perfect follow-up).
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        // Perfect nesting: next item exactly fills the residual.
        if gap == 0 {
            score -= 60.0;
        } else {
            // Harmonic reward decays with the gap; mod-8 bands of gap give stepped bonuses.
            let band = (gap % 8) as f64;
            score -= 25.0 * (1.0 - gap as f64 / cap) - 0.8 * band;
        }
    } else if next_item_size > pr {
        // Next item cannot use this leftover at all: penalize by leftover size class.
        score += match class { 1 => 6.0, 2 => 10.0, 3 => 14.0, 4 => 18.0, _ => 0.0 };
    }

    // Integer-division thresholds on post_residual: dead space that nothing (min size 1) can use
    // is worthless; leftover below 20 is hard to fill for mid/large items.
    if pr > 0 && pr < 20 {
        score += 12.0 - 0.5 * pr as f64; // small residuals penalized but not zero-residual
    }
    if pr == 0 {
        score -= 40.0; // perfect fill is the best outcome
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * (cap - post_residual as f64);
    }

    // New-bin candidate handling: empty bin gets a baseline that keeps it competitive
    // only when open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.25 * mean_residual - 5.0 * open_bins_count.min(20) as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 8.0; // big next item: fresh bin is useful
        }
        return score;
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= 15.0 * fill_frac * fill_frac;

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * (post_residual as f64 - mean_residual);

    // Modulo harmonic coupling: residual divisible by common item sizes (10, 20, 25, 50)
    // is more reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no future item (>=1..100)
    // can use efficiently are the worst outcome. Treat residuals below the
    // minimum plausible item size as nearly worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver -> strong penalty
        } else if post_residual <= 25 {
            score += 25.0; // only fits very small items -> risky dead space
        } else if post_residual <= 50 {
            score += 8.0;  // moderately usable
        }
    } else {
        score -= 40.0; // perfect closure: reward heavily
    }

    // Reward tight fits relative to the residual before placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // fresh capacity; when few bins are open, opening new bins is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above good fits, but attractive
        // when the fit into open bins would leave large dead space.
        score += 35.0 + pressure;
        if post_residual == bin_capacity && next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 30.0; // lookahead: next item can't use open residuals -> new bin helps
        }
    }

    // Coupling with mean residual: bins far below the mean residual are
    // "wasted" bins; filling them is good (lower their score).
    score -= 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Lookahead synergy: if the next item exactly fits the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot fit here anyway; slight penalty for awkward gap
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (waste-free placement)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits inside remaining space: mild reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= 80.0 * tight;
        } else {
            // next item cannot use this bin: penalize leaving space that next item overshoots
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    }

    // Penalize residual relative to mean residual (tighter than average is good)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer it only when current bin would leave large dead space
    if bin_residual == bin_capacity {
        // neutral-ish baseline, adjusted by how well this bin could serve the stream
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 100.0; // existing bin handles next item too
        }
        if fitting_bins_count <= 1 {
            score += 400.0; // discourage new bin when this is last chance
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 50.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Many open bins: favor consolidation into existing bins
    score += 2.0 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core with sharpening).
    let cap = bin_capacity as f64;
    let fit_ratio = post_residual as f64 / cap;
    score += 18.0 * fit_ratio * fit_ratio;

    // Penalize residuals that are small but unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Perfect chain: item + next item exactly fill the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.6 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more willing to open new bins
    // (keep residual space flexible); late, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 10.0 * t - 5.0 * (1.0 - t);
        if post_residual == 0 {
            score -= 30.0; // perfect fill with new bin
        }
    } else {
        score -= 5.0 * t;
    }

    // Exact fill is always excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 - prn) * (1.0 - progress) + prn * (1.0 - prn) * (1.0 - prn) * progress;
    score += 12.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= (item_size as f64 / cap) * tightness * (1.0 + progress) * 8.0;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= (pr - nx) / cap * 4.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins late in the stream
    score += (open_bins_count as f64) * 0.05 * progress;

    // Mean residual alignment: prefer bins whose residual is near the mean
    score += ((pr - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.5 * (post_residual as f64 / cap);

    // Harmonic class of the leftover: classify post_residual into residue bands
    // via integer division thresholds on capacity fractions.
    let q = post_residual / (bin_capacity / 10); // coarse class 0..=10
    match q {
        0 => score -= 30.0,               // near-perfect fit, waste < 10
        1 => score -= 18.0,               // very good fit
        2 => score -= 8.0,                // decent fit
        3 | 4 => score += 4.0,            // mediocre leftover
        5 | 6 => score += 10.0,           // half-empty bin: wasteful unless reusable
        _ => score += 16.0,               // mostly empty: placing here is pointless
    }

    // Modulo arithmetic on post_residual: leftovers divisible into common
    // item-size classes (multiples of 10) are more likely reusable later.
    let r10 = post_residual % 10;
    if r10 == 0 && post_residual > 0 {
        score -= 6.0; // leftover aligns with decade-sized items
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0; // quarter-capacity alignment
    }

    // Lookahead: does the next item fit exactly into the post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Perfect lookahead fit is the best possible outcome
        if next_item_size == post_residual {
            score -= 25.0;
        }
        // Harmonic class check: next item fits into a reusable leftover class
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Leftover becomes dead space for the next item
        score += 8.0;
        if post_residual < 10 {
            score += 10.0; // tiny dead space: strongly penalize
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // and open bin count is low; otherwise defer to existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.65 + 12.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
        if open_bins_count as f64 > 3.0 + 6.0 * progress {
            score += 15.0; // too many open bins already
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big item coming: fresh bin is useful
        }
    }

    // Mild pressure toward compacting global residual mass
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // hard penalty for unusable slivers
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that still fit the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // residual too small for next item => likely dead space
    }

    // Open-bin pressure: prefer spreading into existing bins when many are open.
    score += open_bins_count as f64 * 0.9;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild pull toward bins whose residual is close to this item (best-fit shaping).
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.15;

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 + desperation - progress * 5.0 + mean_residual * 0.1;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0; // new bin fine if current item is the big one of the pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: exact 2-step lookahead match (item + next item fills bin perfectly)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item fits into the post-residual: keep this bin attractive
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Next item would NOT fit: penalize proportionally to wasted dead space
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Small post-residuals are good (tight packing)
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Compare against mean residual of open bins: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins with decent fits
        score += 40.0;
        // If item nearly fills a fresh bin, opening new bin is fine
        if item_size >= 70 {
            score -= 50.0;
        }
        // If the next item is large, a fresh bin gives flexibility
        if next_item_size >= 60 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 30.0;
        }
        // Many open bins already: discourage new ones
        score += open_bins_count as f64 * 2.0;
    }

    // Slight preference for bins with smaller residual overall (best-fit flavor)
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Penalize dead space that cannot be used by the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Reward leaving space exactly usable by next item.
            let slack = post_residual - next_item_size;
            score -= 2.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 12.0 - 0.15 * open_bins_count as f64 - 3.0 * progress + 0.5 * mean_residual * 0.1 * crowd * 0.0;
        score += mean_residual * 0.05; // if mean residual is large, prefer reusing bins (penalize new bin)
        if next_item_size > 0 && item_size >= 90 {
            score -= 10.0; // very large item fits perfectly in fresh bin
        }
    }

    // Favor bins whose residual deviates favorably from the mean (consolidate small residuals).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Slight time horizon modulation: early on, be greedy about tight fits; later, preserve flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling of residual with stream progress
    let poly = 1.0 + progress * (1.0 - progress) * 4.0;
    score -= poly * (fit_frac * fit_frac) * 30.0;
    // reward tight fits more strongly later in stream
    score -= (item_size as f64 / cap) * (1.0 + progress) * 12.0;
    // penalize large dead space nonlinearly
    score += (fit_frac * fit_frac * fit_frac) * 40.0;
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0;
    }
    // new-bin candidate: penalize mildly, more when many bins open
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }
    // mean residual coupling
    score += (mean_residual - pr) * 0.2;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let quarter = bin_capacity / 4;      // 25
    let eighth = bin_capacity / 8;       // 12
    let half = bin_capacity / 2;         // 50

    // Penalize post_residuals that are "almost reusable" dead space
    // (just below a harmonic class boundary): residues like 24, 12, 49.
    let cls = |r: u32| r / quarter;      // integer-division class 0..4
    let boundary_waste = {
        let r = post_residual % quarter;
        if r == quarter - 1 { 6.0 } else if r >= quarter - 3 { 3.0 } else { 0.0 }
    };
    score += boundary_waste;

    // Reward exact harmonic alignment: post_residual divisible by eighth
    // leaves chunks usable by small future items (sizes 10..80 often multiples).
    if post_residual > 0 && post_residual % eighth == 0 {
        score -= 4.0;
    }
    // Extra reward for perfect class alignment (residual is a capacity fraction)
    if post_residual % quarter == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            let chain_post = post_residual - next_item_size;
            score -= 6.0;
            // reward harmonic residue after the chain too
            if chain_post % quarter == 0 { score -= 4.0; }
        } else {
            // next item cannot use leftover: penalize proportional to leftover size
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it is
    // chosen only when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * 0.6;
        // late in the stream with few open bins, new bins are cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        if open_bins_count == 0 { score -= 40.0; }
    } else {
        // prefer fuller bins (small residual before placement)
        score += (bin_capacity - bin_residual) as f64 * -0.1;
    }

    // Spread load: if this bin's residual is far from mean residual, slight penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Prefer bins whose residual is closest to item size (tight fit)
    let tight = (bin_residual - item_size) as f64;
    score += tight * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (1..100 range),
    // but we treat gaps below ~20 as highly risky.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize bins whose remaining residual can't host the lookahead item
    // if the lookahead item would otherwise need a new bin.
    if next_item_size > 0 {
        if post_residual < next_item_size as u32 {
            score += 15.0;
        } else {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; new-bin candidate gets penalized via residual==cap.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Slight preference for bins with below-average residual (tighter bins first),
    // keeping looser bins available for larger future items.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late in the stream, close out bins aggressively: reward filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;

        if post_residual == next_item_size {
            // Perfect 2-step fit: strongly favor this bin.
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits too, but leftover remains: partial reward scaled by tightness.
            let tight = (pr - ni) / bin_capacity as f64; // small = tight pair
            score -= 20.0 * (1.0 - tight);
        } else {
            // Next item cannot follow: penalize dead space, worse when post_residual is small-but-nonzero.
            let dead = ni - pr;
            score += dead * 0.5;
        }

        // If post_residual can't fit ANY plausible item (below min size 1 it's pure waste),
        // penalize near-full bins that strand tiny leftovers.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 1.5;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual deviates above the mean
    // (i.e., use up the roomier bins first, keep tight bins for tight fits).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += rel * 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it when
    // the item would leave a large awkward residual in an existing bin, but discourage
    // opening new bins early in the stream while open bins are underutilized.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 - 15.0 * progress;
        // If no open bin can fit at all, opening is mandatory/cheap.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Lookahead: opening a new bin is good if the next item pairs well with the
        // residual this placement would leave (100 - item_size).
        if next_item_size > 0 {
            let future_residual = (bin_capacity - item_size) as f64;
            if future_residual == next_item_size as f64 {
                score -= 35.0;
            } else if future_residual > next_item_size as f64 {
                score -= 15.0 * (1.0 - (future_residual - next_item_size as f64) / bin_capacity as f64);
            }
        }
    }

    // Mild pressure to keep the number of open bins bounded as stream progresses.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let cap = bin_capacity as f64;
    let tightness = post_residual as f64 / cap;
    score += 12.0 * tightness * tightness;

    // Exact fit -> overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space (unusable for typical items) is penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving residual that the next item can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            if post_residual == next_item_size {
                score -= 40.0; // perfect chain fit
            }
        } else {
            // Next item cannot use this residual: penalize proportional to leftover waste.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.9;
        // Cheaper to open a bin early when few bins are open and stream is long.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // If many bins are open with slack, discourage adding another.
        score += 0.6 * mean_residual;
        // If this bin is the last chance, opening a new bin is worse.
        if fitting_bins_count == 1 {
            score += 120.0;
        }
        // Perfect-fit competition: never open a new bin when an exact fit exists.
        if post_residual == 0 && item_size < bin_capacity {
            score += 2000.0;
        }
    }

    // Mild preference to fill bins with larger residual (balance load).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Time-horizon modulation: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals become more acceptable (bins nearly full),
    // so we scale the base residual by a progress-dependent factor.
    let progress_factor = 0.7 + 0.6 * progress * progress;
    score *= progress_factor;

    // Non-linear penalty for residuals that are too large relative to capacity
    // (wasteful empty space), smoothly growing as residual approaches capacity.
    let normalized_residual = pr / cap;
    score += 25.0 * normalized_residual * normalized_residual;

    // Dead-space penalty: if the next item cannot fit in the post residual,
    // penalize proportionally to the shortfall, amplified by progress.
    if next_item_size > 0 {
        let shortfall = (next_item_size as i64 - post_residual as i64).max(0) as f64;
        score += shortfall * (0.5 + progress);
    }

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 20.0 * (1.0 - normalized_residual) * (1.0 - normalized_residual) * (1.0 - normalized_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild penalty when many bins are already open (encourage consolidation),
    // scaled smoothly by how far above the mean residual this bin sits.
    score += 0.05 * (open_bins_count as f64).sqrt() * (pr - mean_residual).max(0.0);

    // New-bin candidate handling: brand-new empty bin gets a smooth offset that
    // decays with progress, so late in the stream we prefer filling existing bins.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it divides against capacity fractions
    let post = post_residual as u32;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward near-perfect fills: post_residual in small "harmonic" classes
    if post == 0 {
        score -= 500.0; // perfect fit
    } else if post <= bin_capacity / 10 {
        score -= 120.0;
    } else if post < quarter {
        score -= 40.0;
    } else if post == quarter || post == half {
        score -= 60.0; // harmonic division points are reusable
    }

    // Dead-space penalty: residual that no typical item (1..=cap) can pair with later
    if post > 0 && post < 10 {
        score += 90.0; // tiny sliver, unusable for most items
    }

    // Modulo arithmetic on post_residual: residual divisible by small item sizes is reusable
    let post_u = post;
    if post_u > 0 {
        let div_bonus = ((post_u % 10 == 0) as i32) * 2
            + ((post_u % 5 == 0) as i32)
            + ((post_u % 25 == 0) as i32) * 2;
        score -= 15.0 * div_bonus as f64;
    }

    // Lookahead: if next item fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 200.0;
        } else if next_item_size <= post_u {
            score -= 60.0;
            // harmonic match: next item leaves another divisible residual
            if (post_u - next_item_size) % 10 == 0 {
                score -= 30.0;
            }
        } else {
            // next item won't fit here; penalize large leftovers slightly
            score += (post_u as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer it only when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        // fresh bin: neutral baseline, penalize when many bins already fit the item
        if fitting_bins_count > 0 {
            score += 120.0 + 20.0 * (fitting_bins_count as f64);
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    }

    // Waste-avoidance: compare post residual against mean residual across open bins
    score += 0.25 * (mean_residual - post_residual as f64).max(0.0);

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / cap;
    score -= 50.0 * fill_ratio * fill_ratio;

    // Slight preference to keep bin count low when many bins open
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit anything
    // useful are heavily penalized (treated as wasted capacity).
    if post_residual > 0 {
        // smallest possible item is 1 in this interface; but penalize gaps that
        // likely become dead weight relative to typical item sizes
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else {
            // quadratic penalty for growing dead space
            score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;
        }
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large/wasteful or many bins are already open.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 8.0;
        // pressure from open bins count: more open bins -> discourage new bins
        score += 1.5 * open_bins_count as f64;
        // but if current bin would leave a bad residual, fresh bin may win
        // (implicit via dead-space penalties above)
        // early in stream, new bins are cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    } else {
        // mild preference for reusing bins when many are open
        score -= 0.8 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post_residual too small for next item: penalize leaving it
            score += 4.0;
        }
    }

    // Prefer bins whose residual is already below the mean (compact them),
    // keep wide-open bins available for large future items.
    let res = post_residual as f64;
    if res > mean_residual {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    } else {
        score -= 1.0 * (mean_residual - res) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 5 {
            score -= 35.0 - diff as f64 * 3.0;
        } else {
            // Penalize residual that is awkwardly close-but-unusable for next item.
            if next_item_size > post_residual && next_item_size - post_residual <= 10 {
                score += 12.0;
            }
            // Reward residuals that stay large enough to remain versatile.
            if post_residual >= next_item_size {
                score -= 4.0;
            }
        }
        // If next item can't fit here anyway, prefer bins that keep large residual.
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last chance: only this bin can fit the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Penalize creating tiny dead space (<10, unusable for any item).
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Relative to mean residual: prefer bins with below-average residual
    // (tighter bins get packed first, keeping larger residuals for future items).
    score += (mean_residual - post_residual as f64).max(-30.0).min(30.0) * 0.3;

    // Early in stream, be slightly conservative: keep big residual bins alive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    // New-bin candidate: only attractive when no existing bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Penalize large dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // perfect-ish fill
    } else if post_residual >= 10 {
        score += 0.05 * (post_residual as f64).powf(1.3);
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 2.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            score += 0.03 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins is costlier late in the stream; discourage always.
        score += 25.0 - 10.0 * progress;
        // If mean residual across open bins is small, a new bin is more reasonable.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
        // Many open bins -> prefer filling them.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (balance loads).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / c;
    let norm_item = item_size as f64 / c;
    let norm_next = next_item_size as f64 / c;

    let mut score = pr as f64;

    // Non-linear waste penalty: dead space hurts more as it grows
    score += 8.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: late in stream, prefer tighter fits
    score += 20.0 * progress * norm_pr * (1.0 - norm_pr);

    // Post residual vs lookahead item: reward residuals close to next item size
    let gap = (norm_pr - norm_next).abs();
    score -= 6.0 * (1.0 - gap).max(0.0) * (1.0 - gap).max(0.0);

    // Last-chance bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 5.0 * (1.0 - norm_item);
    }

    // Crowd pressure: many open bins -> discourage opening more via high residual
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * norm_pr;

    // Mean residual coupling: prefer bins deviating favorably from mean
    score -= 0.3 * (mean_residual - pr) / c;

    // New-bin candidate penalty: only open new bin when residual is empty and item large
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize residual into capacity/8 buckets
    let q = (bin_capacity / 8).max(1);
    let class = (post_residual / q) as f64;
    score += class * class * 0.5;

    // Reward near-perfect fills (post_residual in small modulo classes)
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    }

    // Penalize residuals that no plausible item (1..100) can use efficiently
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space class
    }

    // Lookahead coupling: if next item exactly fits post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item can still fit: mild reward scaled by tightness
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this bin's remainder: penalty grows with closeness
            score += 8.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only prefer fresh bin when all open fits are bad
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).min(1.0);
        // open new bin if open bins are fragmented (low mean residual)
        score = 55.0 + 45.0 * pressure;
        if next_item_size > 0 && next_item_size >= mean_residual as u32 {
            score -= 20.0;
        }
    }

    // Progress term: slightly prefer reusing bins early, consolidating late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / cap);

    // Prefer bins below mean residual (tighter bins) mildly
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: residuals too small for the smallest possible item (1..100 range,
    // but practically penalize gaps below a usable threshold more aggressively).
    if post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 40 {
        score += 8.0;
    }

    // Superlinear dead-space component: moderate gaps still waste capacity.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    }
    // If next item cannot fit here but could fit in a fresh bin, mild penalty for filling.
    if next_item_size > post_residual && next_item_size > 0 && bin_residual == bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales with how many bins are already open.
        score = 70.0 + (open_bins_count as f64) * 2.0;
        // If the item fits perfectly in a fresh bin and next item is large, that's fine.
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // Early in stream, opening bins is cheaper (need bins anyway).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
    }

    // Open-bin pressure: prefer packing into fewer bins when many are open.
    score += (open_bins_count as f64) * 0.3;

    // Prefer bins tighter than average (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 0.6;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward post_residual that exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward proportional to how close
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space left behind
            score += 30.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than the mean wastes capacity elsewhere
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 80.0;
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
        // late in stream, prefer consolidating rather than opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild penalty for many open bins to encourage packing into existing ones
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (item_size as f64) * 0.6 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving space exactly usable by next item
            score -= 0.5 * next_item_size as f64 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect closure bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is large
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing bins have room; opening new bin is wasteful
        }
        // Early in stream, allow exploration of new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    } else {
        // Favor bins with residual close to mean (balance load)
        score += 0.1 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Late in stream, be conservative: prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: post residual beyond what next item could use
    let usable = if next_item_size > 0 { (next_item_size as f64).min(pr) } else { 0.0 };
    let waste = pr - usable;
    score += 0.8 * waste * waste / cap;

    // Tight-fit reward (smooth polynomial in fill ratio)
    let fill = 1.0 - pr / cap;
    score -= 12.0 * fill * fill * fill;

    // Stream-progress coupling: prefer using open bins more aggressively later
    score -= 6.0 * progress * fill * fill;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * fill;
    }

    // Discourage opening new bins when open bins exist and fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: penalize bins far from mean (fragmentation)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (1.0 - pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it decomposes modulo common item sizes
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are "harmonious" — divisible by small common sizes,
        // meaning future items can tile the leftover space exactly.
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 3.0; }
        if pr % 20 == 0 { harmony += 2.0; }
        if pr % 25 == 0 { harmony += 2.0; }
        if pr % 50 == 0 { harmony += 2.5; }
        score -= harmony;
    }

    // Penalize tiny dead-space classes: residuals in (0,10) are almost always waste.
    if pr > 0 && pr < 10 {
        score += 25.0 * (1.0 - pr as f64 / 10.0);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 40.0; // perfect two-item packing
        } else {
            let gap = pr - next_item_size;
            score -= 15.0;
            if gap < 10 { score += 10.0; } // but don't leave a sub-10 sliver
        }
    } else if next_item_size > pr {
        // Next item can't use this bin's leftover; leftover becomes dead weight.
        score += 0.3 * pr as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer reusing bins early, allow opening new bins
    // when the stream is young or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = cap - 5.0;
        score += 30.0 * (1.0 - progress);            // early stream: reuse open bins
        score -= 10.0 * open_bins_count.min(20) as f64 * 0.0; // (kept neutral)
        if fragmentation > 30.0 {
            score -= 15.0; // existing bins are fragmented; fresh bin is attractive
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    } else {
        // Reward tight fits on existing bins.
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 12.0 * fit_ratio;
        // Penalize leaving residuals in awkward classes (13..19, 23..29 style gaps)
        if pr >= 11 && pr <= 19 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item can use are dead space.
    let min_item = 1u32; // items can be as small as 1, but small gaps are still hard to fill
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // Gap smaller than the next item AND smaller than typical items => likely unusable
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }
    // Small gaps (< 20) are disproportionately hard to fill: superlinear penalty
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item is huge or open bins are congested
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        score += open_bins_count as f64 * 3.0;
        // Don't open a new bin when a decent fit exists
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Existing bin: reward using bins when many are open
        score -= open_bins_count as f64 * 1.5;
        // Prefer bins with lower residual among comparable fits (tighter packing)
        score += (bin_residual as f64 - post_residual as f64) * 0.0; // neutral, post_residual already covers this
        // Reward bins whose residual is close to mean (keeps residuals uniform)
        score -= (bin_residual as f64 - mean_residual).abs() * 0.3;
    }

    // Lookahead: if next item fits exactly in the post-residual, big bonus
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 100.0;
        } else if slack <= 10 {
            score -= 30.0;
        }
    }

    // Early stream: be slightly more willing to open bins (build diversity)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Next item fits in the leftover space -> strong reward.
            let gap = post_residual as f64 - nxt;
            score -= 60.0 / (1.0 + gap);
            // Exact match is best.
            if gap < 1.0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit: penalize leaving residual smaller than next item.
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: avoid creating below-average dead space.
    if mean_residual > 0.0 {
        score += 0.3 * (mean_residual - post_residual as f64).abs();
        if (post_residual as f64) < mean_residual {
            score += 5.0;
        }
    }

    // Penalize very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let tight_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual > item_size as f64;
        if tight_fit_exists {
            score += 120.0;
        } else {
            score += 10.0;
        }
    }

    // Slight preference to fill fuller bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small but nonzero.
    if post_residual > 0 {
        score += 6.0 * ((post_residual as f64) / (bin_capacity as f64)).sqrt();
    } else {
        score -= 25.0; // perfect fill
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        }
        // Penalize if post-residual is dead space that neither next item nor typical items fit.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // Opening a new bin is attractive when open bins are fragmented (high mean residual spread).
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 8.0;
        }
    } else {
        // Prefer bins with residuals close to item size (good packing ratio).
        let waste_ratio = (bin_residual - item_size) as f64 / bin_residual as f64;
        score += 10.0 * waste_ratio;
        // Prefer bins whose residual differs from mean residual (target the emptiest useful bin).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit preferred (quadratic coupling with stream progress).
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);

    // Non-linear penalty for dead space: post_residual normalized, cubed.
    let pr_norm = pr / cap;
    score += 25.0 * pr_norm * pr_norm * pr_norm;

    // Reward using a bin whose residual matches item size well (smooth fit term).
    let fit_quality = 1.0 - ((bin_residual as f64 - item_size as f64) / cap).abs();
    score -= 8.0 * fit_quality * fit_quality;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly early, more strongly when many open bins exist.
    if bin_residual == bin_capacity {
        let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
        score += 6.0 + 10.0 * open_norm * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-gap / 20.0).exp();
    }

    // Coupling with mean residual: prefer bins close to the mean (balance residual spread).
    let dev = (pr - mean_residual).abs();
    score += 3.0 * (dev / cap) * (dev / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in coarse
    // capacity fractions are more reusable. Reward small residuals (tight fits).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Integer-division thresholds on post_residual: residuals that are multiples
    // of common item sizes (10, 20, 25, 50) are "harmonic" and reusable.
    let harmonic = (post_residual % 10 == 0) as i32
        + (post_residual % 20 == 0) as i32
        + (post_residual % 25 == 0) as i32
        + (post_residual % 50 == 0) as i32;
    score -= 6.0 * harmonic as f64;

    // Lookahead: penalize if next item cannot fit in post_residual (dead space risk),
    // reward if it fits exactly-ish.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0;
        } else {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 20.0;
            } else {
                score += gap as f64 * 0.15;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist with decent residual.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 15.0 + mean_residual * 0.5;
        }
    } else {
        // Favor filling bins with larger residuals (waste less overall).
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Late-stream pressure: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item occupies most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Penalize leaving gaps the next item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual {
            score += 10.0;
        } else {
            score -= 6.0;
            if next_item_size == post_residual {
                score -= 25.0; // next item closes this bin perfectly
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is below the mean (filling emptier bins first
    // keeps a set of large-residual bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: keep it competitive only when the item is large
    // relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 15.0 - large_item * 30.0;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, normalized by capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Perfect fit: strongly favor.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item fits; reward proportionally to how snugly.
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * (1.0 - slack);
        } else {
            // Next item won't fit here; mildly penalize leaving residual that
            // is close to but smaller than the next item (dead space trap).
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 0.6 * (15.0 - gap);
            }
        }
    }

    // Compare against mean residual: bins with residuals below mean are more
    // "used up"; placing into them is cheaper than fragmenting fat bins.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep empty bins attractive only when current
    // fit is terrible; otherwise push items into existing bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Small bonus for filling bins when many are open (bin count pressure).
    score -= 0.05 * open_bins_count as f64 * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize mildly so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * open_bins_count as f64;
        // Late in the stream, closing out cleanly matters more; favor new bins less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        return score;
    }

    // Reward tight fits (small post_residual already does this); extra bonus for exact fit.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: penalize if post_residual can't fit the next item but could have
    // if we placed elsewhere — i.e., wasted opportunity for a chain placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // enables a follow-up placement
        } else if bin_residual >= next_item_size + item_size {
            score += 5.0; // this bin could have served next item too; wasteful now
        }
        // If next item exactly matches post_residual, strongly reward.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 0.1 * open_bins_count as f64;
    }

    // Penalize creating dead space far below the minimum future item size (assume ~1..100,
    // small residuals under ~10 are near-useless).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Global residual coupling: prefer bins whose residual is above the mean
    // (consume the fullest bins first, keep slack concentrated).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 1.5;
    }

    // Time horizon: as the stream ends, avoid leaving many fragmented open bins;
    // prefer placements that minimize total residual mass.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        - 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - t)
        + 20.0 * x * x * t
        - 12.0 * (x * (1.0 - x)) * (1.0 - t) * t;

    // Penalize dead space relative to lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap < 0.0 {
            score += (-gap) * (0.5 + 0.5 * t);
        } else {
            score -= 8.0 * (gap / cap) * (1.0 - (gap / cap)) * (1.0 - t);
        }
    }

    // Reward tight fits, penalize near-misses
    let fit = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit * fit * (1.0 - t);
    score += 10.0 * (1.0 - fit) * (1.0 - fit);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - t);
    }

    // New-bin candidate: discourage early, allow late when open bins are messy
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - t) - 15.0 * t;
        if open_bins_count > 0 {
            score += (mean_residual / cap) * 10.0 * (1.0 - t);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead" (too small
    // for typical items) get penalized, residues that can host a future item
    // get rewarded. Class thresholds via integer division on capacity.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual < eighth {
        // dead space: unusable for items >= 1..80 typically
        score += 40.0;
    } else if post_residual < quarter {
        score += 10.0;
    } else if post_residual == quarter
        || post_residual == bin_capacity / 2
        || post_residual == 3 * quarter {
        // harmonic sweet spots: exact capacity fractions
        score -= 12.0;
    }

    // Lookahead: does next_item_size fit exactly / well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect follow-up fill
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap < eighth {
                score -= 18.0; // near-perfect follow-up
            } else {
                score -= 4.0 * (post_residual as f64) / cap;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 6.0 * (1.0 - (post_residual as f64) / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave
    // awkward residue or no bin fits well.
    if bin_residual == bin_capacity {
        // opening fresh: neutral-ish baseline, discourage when an open bin
        // has a tight fit available
        if fitting_bins_count > 0 && post_residual < eighth {
            score += 15.0;
        }
        score += 20.0 * (open_bins_count as f64) / ((total_items.max(1)) as f64);
        // encourage fresh bin late in stream less (bins already amortized)
        score -= 5.0 * (step_index as f64) / ((total_items.max(1)) as f64);
    }

    // Prefer bins whose residual is close to mean (keep residuals uniform)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Tight fits are great: small post_residual (but not dead) rewarded
    if post_residual > 0 && post_residual < eighth {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual was already small (tight packing pressure).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Penalize creating gaps that cannot fit the next item if it exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.3 * open_bins_count as f64;

    // Slightly prefer bins below mean residual (denser bins) early-to-mid stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (mean_residual - bin_residual as f64) * (1.0 - progress);

    // New-bin candidate: neutral baseline with mild penalty so it's chosen
    // only when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fits post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        // Perfect chain: post_residual == next_item_size -> huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Post residual slightly larger than next item is still good.
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space: post_residual can't hold next item; penalize proportionally.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residuals far below mean (fragmented bins); reward bins tighter than mean.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists (post_residual large waste).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Slight preference to fill bins early in the stream.
    score -= 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with non-linear waste penalty.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / bin_capacity as f64;

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residuals too small for typical items (1..100 unknown, so
    // penalize residuals below the smallest plausible item threshold lightly).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to leftover unusability.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: discourage opening new ones; encourage filling existing.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is high.
        score += 20.0 + 2.5 * open_pressure + 0.4 * mean_residual;
        // Early in stream, opening a new bin is cheaper; late in stream it is costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * (1.0 - progress);
    } else {
        // Reward placing into open bins, more so when many are open.
        score -= 0.5 * open_pressure;
    }

    // Mean-residual coupling: if this bin's residual is far below mean (it's a "small" bin),
    // filling it down further is good (consolidation of tight bins).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.05 * dev; // negative dev lowers score -> favors tighter bins
    } else {
        score += 0.10 * dev; // penalize loose bins
    }

    // Mild time-horizon term: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - waste / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress.clamp(0.0, 1.0);
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep
    let coupling = pr * pr / (cap * cap); // normalized quadratic dead-space term
    score += 2.5 * coupling * (0.5 + poly);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr / cap;
    score -= 1.8 * tightness * tightness * (1.0 + poly);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * poly;
    }

    // Lookahead: penalize leaving residual that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 1.5 * (nx - pr) / cap;
        } else {
            score -= 0.8 * (1.0 - ((pr - nx) / cap).min(1.0));
        }
    }

    // Mild penalty when many bins are open relative to stream progress
    score += 0.3 * (open_bins_count as f64 / (1.0 + t * total_items.max(1) as f64)).ln().max(0.0);

    // Pull toward mean residual to consolidate space
    score += 0.2 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: discourage opening a fresh bin unless residual is large
    if bin_residual == bin_capacity {
        score += 4.0 - 2.0 * poly;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize into capacity fractions.
    let post = post_residual as f64;
    let frac = post / cap; // 0..1
    let class = (frac * 10.0).floor(); // 0..9 decile class

    // Reward (subtract) when post_residual lands in a "harmonically useful" class:
    // small residuals (class 0..2) are near-perfect fits; large residuals (class 8..9)
    // still leave a big usable slot. Mid residuals (class 4..6) are dead-space risk.
    let class_bonus = match class as u32 {
        0 | 1 | 2 => 12.0,
        8 | 9 => 6.0,
        4 | 5 | 6 => -8.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division harmony: does post_residual divide nicely with next item?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if post_residual >= nxt {
            // Next item fits here: strong reward, scaled by leftover after that too.
            let after2 = post_residual - nxt;
            score -= 15.0;
            // harmonic check on the twice-removed residual
            if after2 % 10 == 0 {
                score -= 5.0;
            }
            if after2 < 10 {
                score -= 6.0; // nearly exhausted bin is excellent
            }
        } else {
            // Post-residual cannot host next item: penalize wasted look-ahead space,
            // but only if next item is small (it will fit anywhere cheaply anyway).
            if nxt <= 20 {
                score += 4.0;
            } else {
                score += 8.0;
            }
            // modulo penalty: residual that misses next_item by a tiny amount is worst
            let miss = nxt - post_residual;
            if miss <= 5 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual > bin_capacity / 2 {
            score += 10.0; // bad fit in last-chance bin: soften the reward
        }
    }

    // New-bin candidate handling: empty bin gets a neutral-to-high base so that
    // open bins with decent fits win; but if all open bins fit poorly, empty bin
    // (post_residual == capacity - item) competes via its naturally large residual.
    if bin_residual == bin_capacity {
        // New bin: mild penalty so it's chosen only when open fits are bad,
        // less penalty late in the stream when consolidation matters less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 - 6.0 * progress;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Prefer placing into bins whose residual deviates from mean residual
    // in the "tightening" direction (below mean => bin is more filled).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo-class reward: residuals that are multiples of common item sizes
    // (10,20,25,50) tend to be reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit after this placement: penalize proportionally to wasted space
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Dead-space penalty: tiny residuals are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Favor bins tighter than average (best-fit flavor)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference to keep bins balanced early vs late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin would leave large unusable gap
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; becomes attractive if best existing fit is bad
        score = 70.0 + 0.1 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 30.0; // fresh bin can absorb the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimal post_residual is good.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize creating dead space that no future item (>= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving moderately large gaps unused
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty for wasting space in a crowded field.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Time horizon: early on, prefer consolidation; late, prefer balanced residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Global state: few open bins -> encourage filling them fully.
    if open_bins_count > 0 {
        score += 3.0 / open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when item fits poorly everywhere
    // (i.e., this empty bin gives perfect post_residual for the item's size).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // fresh bin is good if it leaves a "clean" residual for next item
            if next_item_size > 0 && next_item_size == post_residual {
                score -= 8.0;
            }
            // discourage opening new bins when a decent fit exists elsewhere
            if fitting_bins_count > 0 && post_residual <= item_size {
                score += 30.0;
            }
            score += 10.0; // base cost of opening a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted residual, non-linearly
    let mut score = pr as f64;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x; // fraction of bin filled after placement
    let progress_coupling = (tightness * tightness - tightness * progress) * cap * 0.5;
    score -= progress_coupling;

    // Cubic dead-space penalty: residuals near mid-capacity are least usable
    let dead = (x - 0.5) * (x - 0.5) * (x - 0.5);
    score += dead * cap * 0.8;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so mid/late stream
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 25.0 + 20.0 * (1.0 - progress) + openness * 2.0;
    } else {
        // Mild penalty per open bin to encourage consolidation
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 10.0 + 15.0 * fit_quality * (0.5 + progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving residual it nearly fits
        let gap = pr - next_item_size as f64;
        if gap > -20.0 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from mean smoothly
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0 - dev * 5.0;

    // Smooth late-stream tightening: penalize any residual quadratically as stream ends
    score += x * x * cap * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Perfect fit bonus (dead space zero)
    if post == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable residues
    if post > 0 && post < 10 {
        score += 25.0 * (10 - post) as f64;
    }

    // Harmonic classes: residues divisible by common item sizes are reusable
    for d in [10i64, 20, 25, 50] {
        if post % d == 0 && post > 0 {
            score -= 8.0;
        }
    }

    // Quarter-capacity classes of post_residual
    let quarter = cap / 4;
    let cls = post / quarter;
    score -= 5.0 * (cls as f64 - 2.0).abs().recip().max(0.0);

    // Next item lookahead: does post_residual fit next item?
    if next_item_size > 0 {
        if (next_item_size as i64) <= post {
            score -= 12.0;
            // exact match of next item into post residual
            if (next_item_size as i64) == post {
                score -= 40.0;
            }
        } else {
            score += 6.0;
            // penalize residues that waste the next item's class
            if post > 0 && (next_item_size as i64) % post == 0 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than mean residual
    score += 0.4 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: prefer opening new bin only if current fit is very poor
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual >= 50 {
            score += 20.0;
        }
        // early stream: allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Integer-division threshold on item size: large items prefer tight fills
    if item_size >= 50 && post_residual < 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post-residual is just barely too small for the next item (wasted potential).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= next_item_size.saturating_sub(6) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor consolidation into existing bins.
    let pressure = (open_bins_count as f64) * 0.8;
    if bin_residual < bin_capacity {
        score -= pressure;
    } else {
        score += pressure * 0.5;
    }

    // Prefer bins whose residual is already below the mean (tighter bins).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Early in the stream, allow slightly more freedom to open bins for good structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            // Slack proportional to how loosely the next item fits.
            score -= 300.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize dead space relative to mean residual.
            score += 0.5 * (post_residual as f64 - mean_residual).abs()
                  + 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers (wasted space).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a nearly empty bin's flexibility early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well.
        score += 250.0 - 100.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    } else {
        // Prefer filling bins that are already heavily loaded.
        score -= 0.2 * (bin_capacity - bin_residual) as f64;
    }

    // Slight preference to keep the number of open bins manageable.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item can fit in the post-residual, reward keeping
    // this bin alive for a chained placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item: penalize proportionally.
        score += 10.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // existing bin fits well. Make the empty bin moderately attractive so it
    // wins only when open bins would create large dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // (consolidation pressure) and early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 25.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // If this item leaves a large residual in a fresh bin that nothing
        // chains into, discourage slightly more.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate small leftovers),
    // keeping large-residual bins free for bigger items.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.3 * mean_gap;

    // Mild penalty for wasting space in bins that are already mostly full
    // (preserve them via tightness, but avoid scattering across many bins).
    if open_bins_count > 8 {
        score += 0.05 * open_bins_count as f64 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, with non-linear (quadratic) waste penalty.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling: waste matters more as the stream progresses.
    let coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 30.0 * coupling * norm_pr * (1.0 - norm_pr); // reward mid-range fits
    score += 50.0 * progress * norm_pr; // late stream: strongly avoid large residuals

    // Perfect-fit reward (smooth via quadratic term).
    let perfect = 1.0 - norm_pr * norm_pr;
    score -= 25.0 * perfect * perfect;

    // Lookahead: reward residual that can fit the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_quality = (pr - n).abs();
        let kernel = (-fit_quality * fit_quality / 200.0).exp();
        score -= 20.0 * kernel;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
    }

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Slight preference toward bins tighter than the mean residual.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect/near-perfect fits are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // exact closure
    } else if pr < 10 {
        score -= 35.0; // dead space too small for any item -> effectively closed
    } else {
        // Modulo classes: residuals divisible by small item sizes are reusable.
        let mut reusable_bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                reusable_bonus += 12.0;
            }
        }
        score -= reusable_bonus;

        // Fractional capacity classes of post_residual
        let frac = pr as f64 / cap;
        if frac > 0.5 {
            score -= 10.0; // still roomy bin, fine
        } else if frac > 0.25 {
            score -= 4.0;
        } else {
            score += 6.0; // small awkward residual
        }

        // Lookahead: does next item fit exactly into post_residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 45.0; // perfect chain
            } else if next_item_size < pr {
                let slack = (pr - next_item_size) as f64;
                score -= 15.0 * (1.0 - slack / 80.0); // tight chain reward
            } else {
                // next item cannot use this residual: residual wasted for lookahead
                let gap = (next_item_size - pr) as f64;
                score += 8.0 * (1.0 - gap / 80.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 {
            score += 0.1 * next_item_size as f64;
        }
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    score += 0.02 * (step_index as f64 / (total_items.max(1) as f64)) * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < 10 && post_residual >= min_item {
        // Unusable small gap -> heavy penalty proportional to how "stuck" the space is.
        score += (12.0 - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    } else if post_residual >= 10 {
        // Usable residual: mild reward for larger usable space, but scaled down
        // so tight fits still win.
        score -= 2.0;
    }

    // Reward tightness: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless it creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 10.0; // ...but not if it strands the bin.
        }
    }

    // Open-bin pressure: many open bins -> discourage opening yet another one.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 6.0 + 1.5 * open_bins_count as f64;
        // Lookahead: if the next item fits comfortably in the leftover of a fresh bin
        // and current placement would strand this bin, opening is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    } else {
        // Using an existing bin reduces open-bin count pressure slightly.
        score -= 1.0;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Mean-residual coupling: when mean residual is high, prefer consolidating
    // into bins with above-mean residual (keep small-residual bins pristine).
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect match: next item exactly fills the leftover space -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward proportionally to how much room remains after it too.
            let two_step_waste = post_residual - next_item_size;
            score -= 25.0 - (two_step_waste as f64) * 0.15;
        } else {
            // Next item won't fit here: penalize wasted potential.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Reward bins with residuals below the mean (tighter than average).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progression: as stream advances, be more conservative (favor filling existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.25;

    // Penalize opening new bins when several bins are already open and one fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Small penalty for creating very small dead space (< 10) that likely can't fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize creating dead space that cannot fit even a small item (<=10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // If next item almost fits (within 10), mild reward.
    else if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(10) && post_residual > 0 {
        score -= 4.0;
    }
    // Penalize if next item is large and this bin would be left with useless space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: empty bin gets a moderate baseline; prefer it
    // when open bins are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // Penalize new bin when existing bins are roomy on average.
        score += 14.0 + 10.0 * mean_residual / bin_capacity as f64;
        // But discount the penalty late in the stream or when bins are crowded.
        score -= 8.0 * progress;
        score -= 3.0 * crowded.min(6.0);
        // Large items prefer fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Slight preference for fuller bins (waste-not).
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mild reward for consolidating when many bins are open.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Tight-fit reward: strongly favor small post_residual, non-linear (quartic)
    let pr = post_residual as f64;
    let tightness = (pr / cap).powf(4.0);
    score += 12.0 * tightness; // penalize wasted space super-linearly

    // Perfect / near-perfect fit bonus (subtract)
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let fit_quality = 1.0 - (pr / cap);
        score -= 8.0 * fit_quality * fit_quality * fit_quality;
    }

    // Lookahead coupling: reward residual that can still host the next item,
    // scaled by progress (late in stream, flexibility matters more)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (0.5 + progress);
        } else {
            // residual too small for next item: mild penalty growing with progress
            score += 4.0 * progress * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count > 0 { 20.0 + 10.0 * (1.0 - progress) } else { -5.0 };
        score += penalty;
    }

    // Dead-space avoidance: penalize residuals that are small but unusable
    let small_dead = (pr / cap) * (1.0 - (pr / cap));
    score += 3.0 * small_dead * (1.0 + 2.0 * progress);

    // Mild preference to fill bins with larger residuals early (balance load)
    score += (bin_residual as f64 - mean_residual) * 0.05 * (1.0 - progress);

    // Open-bin pressure: many open bins -> prefer compacting into existing ones
    score += open_bins_count as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" residue classes are more likely to host future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty grows super-linearly for tiny residuals (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic bucketing of post_residual by integer division thresholds.
    let bucket = post_residual / 10; // 0..10
    score -= match bucket {
        0 => 15.0,
        1 => 10.0,
        2 => 6.0,
        3 => 3.0,
        4 => 1.0,
        5 => 0.0,
        6 => -1.0,
        7 => -2.0,
        8 => -3.0,
        _ => -4.0,
    };

    // Modulo coupling: post_residual divisible by common item sizes (10,20,25,50)
    // is a "harmonic" leftover that future items tile well.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Lookahead: if next item fits exactly into post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Prefer leftovers that leave a good residue for the next item too.
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 { score -= 5.0; }
            score -= (post_residual - next_item_size) as f64 * 0.05;
        } else {
            score += 4.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the current item is large and would fragment a small bin badly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < 25.0 && open_bins_count > 2;
        let big_item = item_size > 60;
        if crowded || (big_item && post_residual < 35) {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 15.0; // prefer existing bins by default
        }
    } else {
        // Prefer filling bins with small residuals relative to mean.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Tightness reward: the smaller the leftover relative to capacity, the better.
    score -= 20.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (<= 1) are worthless; residuals that cannot
    // hold the NEXT item are partially wasted.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 50.0;
    } else {
        // Dead-space penalty: small gaps are unusable dead space.
        let dead = if post_residual < 10 { 40.0 } else { 0.0 };
        score += dead;

        // If the leftover cannot accommodate the lookahead item, penalize
        // proportionally to how "wasted" the gap is.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits: the smaller the item relative to the residual,
    // the better the packing efficiency of this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    score += 0.3 * open_bins_count as f64;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when existing bins have large mean residual but poor fit potential,
    // or early in the stream when consolidation pressure is low.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // Early stream: slightly cheaper to open bins (build a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If no open bin fits well, new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Many open bins with high mean residual: discourage another bin.
        score += 0.2 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // close to what remains after placement (keeps residuals uniform,
    // leaving large coherent gaps for future items).
    let gap_diff = (mean_residual - post_residual as f64).abs();
    score += 0.1 * gap_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead matching: reward post_residual that fits next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: next item can also be placed here.
            // Stronger reward when post_residual is a tight fit for next item.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 + 20.0 * tightness;
        } else {
            // Penalize dead space that cannot host the next item,
            // scaled by how small the leftover is (waste ratio).
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 25.0 * (1.0 - waste).max(0.0);
        }
        // Perfect match bonus: bin becomes exactly full after next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // --- Relative to mean residual: prefer bins whose post residual is below mean ---
    // (compact bins, keep large residuals in other bins flexible)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (pr - mean_residual);
    }

    // --- Last chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // --- Prefer filling bins that are already mostly full (small residual) ---
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // --- Penalize tiny unusable post residual (dead space) nonlinearly ---
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0;
    }

    // --- New bin candidate: only attractive when open bins are crowded or
    //     current bin would leave a very poor fit for the next item ---
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = 45.0 + 20.0 * crowded - 10.0 * poor_fit;
        // Early in stream, opening new bins is cheaper; later, avoid bin proliferation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Exact or near-exact fill is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for any plausible item (items >= 1).
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // post_residual cannot host next item: mild penalty scaled by wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has no sunk cost; prefer it only when
    // existing bins fit poorly. Penalize opening new bins when many bins are open
    // and mean residual is large (fragmentation risk).
    if bin_residual == bin_capacity {
        // base new-bin score: item leaves residual = capacity - item_size
        score = (bin_capacity - item_size) as f64;
        // discourage new bins when open bins have plenty of aggregate space
        score += open_bins_count as f64 * 2.0;
        score += mean_residual * 0.5;
        // early in stream, opening bins is cheaper (build diversity)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory
        }
        if fitting_bins_count == 1 {
            score += 40.0; // an existing bin alone fits: prefer it
        }
    } else {
        // Existing bins: slight preference for bins with less residual overall
        // (pack fullest bins first) scaled by global mean.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Late-stream consolidation: as stream ends, avoid leaving many open bins;
    // favor filling existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        score -= 10.0 * progress;
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, quadratically coupled with stream progress.
    let mut score = pr as f64 * (1.0 + 0.8 * progress * progress);

    // Non-linear waste term: dead space that is too small to be useful is worse.
    let dead = (x - (item_size as f64 / cap)).max(0.0);
    score += 15.0 * dead * dead * (0.5 + progress);

    // Reward tight fits (post residual near zero), more so late in the stream.
    score -= 20.0 * (1.0 - x).powi(3) * (0.6 + 0.4 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual, reward it.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - ((post_residual as u32 - next_item_size) as f64 / cap);
        score -= 8.0 * fit_quality * fit_quality;
    }

    // Penalize bins whose residual is far below the mean residual (fragmentation).
    score += 3.0 * ((mean_residual - pr) / cap).max(0.0);

    // Slight preference to keep the number of open bins low.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make empty bins moderately attractive when current fits are poor.
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - x.abs()) * (0.3 + 0.7 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item-size divisors.
    let pr = post_residual;
    // Dead-space penalty: residuals that few item sizes can fill are bad.
    // Residual in (0, 10) is unusable (min item 1, but small slivers waste).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Perfect fit: zero residual is ideal.
    if pr == 0 {
        score -= 40.0;
    }

    // Harmonic classes: post_residual divisible by 50 or 25 leaves clean slots.
    if pr % 50 == 0 || pr % 25 == 0 {
        score -= 6.0;
    }
    if pr % 10 == 0 {
        score -= 3.0;
    }

    // Lookahead harmony: does the next item fit the post-residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        } else if next_item_size < pr {
            let gap = (pr - next_item_size) as f64;
            score += gap * 0.4; // prefer bins where next item fits snugly
            if gap < 10.0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // open bins are crowded (high mean residual) or few bins fit.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score = cap * 0.55 - crowded * 18.0;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 > cap * 0.6 {
            score -= 6.0; // big next item: fresh bin useful
        }
    }

    // Progress coupling: late in stream, tighten packing (penalize slack more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * progress * 0.5;

    // Fractional capacity coupling: prefer filling bins past half full.
    let fill = 1.0 - (post_residual as f64) / cap;
    if fill > 0.5 {
        score -= 4.0 * (fill - 0.5);
    }

    // Small penalty for spreading across too many bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit any plausible item (1..=100, min item 1)
    // are wasted capacity. Penalize gaps in [1, 9] harshly (unusable if min item is 10-style),
    // and mildly penalize gaps that cannot fit the lookahead item.
    if post_residual > 0 {
        let dead = (9u32).saturating_sub(post_residual.saturating_sub(1)) as f64;
        score += 12.0 * dead;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this gap: it becomes dead space for the lookahead
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones (favor low post_residual),
    // penalize opening new bins when open_bins_count is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which would strand the residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it attractive
    // only when no open bin fits well. Base cost for opening a new bin:
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        // Opening is cheap early, expensive late or when many bins already open
        let open_cost = 15.0 + 0.5 * open_bins_count as f64 + 10.0 * progress;
        // If mean residual across open bins is small, open bins are nearly full -> opening is fine
        let mean_fit_bonus = if mean_residual < item_size as f64 { 8.0 } else { 0.0 };
        score = open_cost - mean_fit_bonus - 0.2 * spread;
    }

    // Mild alignment with mean residual: prefer bins whose residual is near the mean
    // (keeps the bin pool homogeneous and predictable).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus: next item exactly fills the remaining space
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement: reward small leftover gap
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit after placement: penalize dead space
            score += 15.0 + diff * 0.2;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when good fits exist (new-bin candidate has residual == capacity)
    if bin_residual == bin_capacity {
        // New bin only attractive if current item is large and no tight fits exist
        score += 25.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    // Waste-fraction penalty: dead space relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Late-stream pressure: tighten packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward mid-range dead space (post_residual too small for
    // typical future items but not near zero).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 8.0; // nearly perfect fill, small residual is fine
    } else if pr >= 10.0 && pr <= 30.0 {
        score += 6.0; // awkward dead zone
    }

    // Lookahead: reward if next item fits into post_residual, penalize if not.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 5.0;
        }
        // Extra reward when next item exactly chains into remaining space.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer reusing bins with smaller residuals overall (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Early in stream: be picky (encourage spreading); late: accept decent fits.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - t) * 5.0 * fit_ratio;

    // Many open bins: discourage opening yet another bin.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if nothing fits well anywhere, new bin is attractive.
        if fit_ratio < 0.5 && open_bins_count > 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual (larger leftover = worse fit)
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post residual with stream progress.
    // Early in stream: prefer tight fits less aggressively (keep bins flexible).
    // Late in stream: strongly penalize large residuals (dead space).
    let bend = 0.5 + 1.5 * progress * progress;
    score += bend * (x * x) * cap;

    // Cubic term: heavily punish near-empty leftovers (large x) especially late.
    score += progress * (x * x * x) * cap * 0.8;

    // Lookahead: if next item fits exactly into post residual, reward this bin.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        if n <= pr {
            score -= (1.0 - gap / cap) * 12.0 * (0.5 + progress);
        } else {
            score += gap / cap * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean residual coupling: placing into a bin below-mean residual keeps
    // large residual bins available; reward that.
    score += (mean_residual - pr) * 0.15;

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: neutral-ish baseline, penalized slightly so it is
    // chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lies in "useful"
    // residue classes (multiples of small denominators) are more valuable.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 25 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        6.0 // awkward residue: penalize dead space
    };
    score += class_penalty;

    // Fractional fill: reward bins that become highly filled.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if pr >= next_item_size {
            score -= 10.0 * (pr as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item cannot use leftover: dead-space penalty scaled by gap
            score += 4.0 + (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when existing fits
    // are poor. Penalize the fresh bin mildly by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 8.0 * progress;
        // If many open bins already fit the item, opening new bins is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 0.3 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

