    // Tight fit reward: small post residual relative to bin capacity.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= tightness * 3.0;

    // Prefer bins with residuals below mean (use space efficiently).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening new bins when open bins exist and fit is reasonable.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
    }

    // Late in stream: be greedier, fill existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // New-bin candidate handling: penalize opening a new bin unless nothing fits
    if bin_residual == bin_capacity {
        let mut new_bin_score = post + cap * 1.5;
        if fitting_bins_count == 0 {
            new_bin_score -= cap * 2.0; // forced: no open bin can fit
        } else if fitting_bins_count == 1 {
            // last-chance bin exists; only prefer new bin if fit would be terrible
            let fit_quality = item / bin_residual as f64;
            if fit_quality > 0.95 {
                new_bin_score -= cap * 1.2;
            }
        }
        // late in stream, avoid opening bins for small items
        let t = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += t * cap * 0.5 * (1.0 - item / cap);
        return new_bin_score;
    }

    // Reward tight fits: prefer small post_residual nonlinearly
    score -= (cap - post) * (cap - post) / cap;

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * 0.8; // wasted gap below lookahead size
        } else if post >= nxt {
            score -= 6.0; // lookahead fits in the remainder
            if (post - nxt) < 10.0 {
                score -= 4.0; // near-perfect two-item packing
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= cap * 0.9;
    } else if fitting_bins_count > 1 {
        // mild penalty to encourage discrimination among many options
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling bins
    let open_f = open_bins_count as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let fill_pressure = mean_residual / cap;
    score -= fill_pressure * (open_f.sqrt()) * 3.0;

    // Time horizon: early on, keep flexibility (penalize very small residuals mildly);
    // late, pack greedily
    let flexibility_penalty = if t < 0.5 { (cap * 0.15 - post).max(0.0) * 0.5 } else { 0.0 };
    score += flexibility_penalty;
    if t > 0.7 {
        score -= (item / cap) * 5.0; // late: prefer placing big items in existing bins
    }

    // Exact-fill reward
    if post_residual == 0 {
        score -= cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual (waste) plus quadratic coupling with stream progress.
    let mut score = pr + 8.0 * (pr / c) * (pr / c) * (0.5 + progress);

    // Reward tight fits: small post-residual relative to item size.
    score -= 20.0 * (it / c) * (1.0 - pr / c);

    // Penalize bins whose residual deviates from mean residual (fragmentation).
    score += 0.3 * (br - mean_residual) * (br - mean_residual) / c;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (nxt / c) * (1.0 - (pr - nxt) / c);
        } else {
            score += 4.0 * (nxt / c) * (1.0 - progress);
        }
    }

    // Late stream: prefer consolidating into open bins over opening new ones.
    score += 12.0 * progress * (open_bins_count as f64).sqrt() / (1.0 + (open_bins_count as f64));

    // Smooth non-linear residual decay term.
    score -= 5.0 * (1.0 - (pr / c).powi(2)) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score += 20.0 * (1.0 - fit_ratio);

    // Harmonic classes: post_residual mod 10 classes
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in {0} are perfect; small residuals (1..=5) are near-dead space; penalize
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score += 25.0;
    } else if pr <= 10 {
        score += 10.0;
    }

    // Harmonic compatibility: can next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward if post_residual falls in a harmonic class of next_item_size
            let k = pr / next_item_size.max(1);
            let rem = pr % next_item_size.max(1);
            if rem == 0 {
                score -= 30.0 + 10.0 * k as f64;
            } else {
                score -= 10.0 * (next_item_size as f64 / pr as f64);
            }
        } else {
            // Next item won't fit here; penalize wasted lookahead compatibility
            score += 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Only attractive when current item leaves awkward residual or few bins
        let awkward = (pr <= 10 && pr > 0) as i32 as f64;
        score += 35.0 + 40.0 * awkward - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // pairing potential in fresh bin
        }
    }

    // Dead-space penalty scaled by capacity fraction
    let dead_frac = (pr as f64) / (bin_capacity as f64);
    if dead_frac > 0.0 && dead_frac < 0.1 {
        score += 15.0 * (0.1 - dead_frac) * 10.0;
    }

    // Progress-aware mild regularization
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * t * (mean_residual - pr as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are almost unusable
    // (smallest item is 1, but tiny gaps fragment capacity). Penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    } else if post_residual > 20 && post_residual <= 30 {
        score += 8.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 40.0;
        } else {
            score -= 15.0 * (1.0 - slack / 50.0).max(0.0);
        }
    }
    // If next item cannot fit in the gap, the gap is dead space for lookahead.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    // The new-bin candidate has bin_residual == bin_capacity; make it
    // progressively less attractive as open_bins_count grows.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * open_bins_count as f64 + 10.0 * progress;
        // But if no open bin has a decent fit (high mean residual fragmentation),
        // allow a fresh bin.
        if mean_residual < 15.0 && fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate space).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

