        } else if post_residual > next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 6.0 * (mean_residual / bin_capacity as f64);
    } else if open_bins_count == 0 {
        score -= 20.0; // no open bins: opening one is fine
    }

    // New-bin candidate: empty bin should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when open bins are scarce
        // or the current fit is bad.
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
        let mut new_bin_score = 30.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_score -= 50.0;
        }
        if fit_quality < 0.35 {
            new_bin_score -= 20.0; // current fit is poor, new bin more attractive
        }
        if open_bins_count > 6 {
            new_bin_score += 15.0; // too many open bins already
        }
        score = score.min(new_bin_score);
    }

