    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (low post residual)
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; small residuals get extra discount.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * 40.0
                 + pr_norm * progress * 25.0;
    score += coupling;

    // Reward near-perfect fits with a smooth quadratic discount
    let tight = 1.0 - pr_norm;
    score -= 12.0 * tight * tight * tight;

    // Lookahead: bonus if next item fits the post-residual (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 8.0 * (1.0 - slack / cap);
