    // Last-chance bin: strong discount to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize proportionally to how full it would leave the stream
    if bin_residual == bin_capacity {
        score += 18.0 + 20.0 * (1.0 - progress);
        // but late in the stream with many bins, spreading is fine
        score -= 8.0 * progress;
    }

    // Mild preference for bins deviating from mean residual (balance-aware)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
