    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let residual = bin_residual as f64;
    let fit_ratio = item_size as f64 / residual.max(1.0);
    score -= 55.0 * fit_ratio * fit_ratio;

    // Penalize post-residual dead space that is too small to be useful
    // (assuming items >= 1, a small leftover is nearly worthless).
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Dead-space penalty grows as leftover shrinks toward unusable sizes.
        score += 30.0 / pr.sqrt();
        // Sharp penalty for leaving a sliver (1..=10) that likely can't fit future items.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills leftover
            let next_fit = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * next_fit;
        } else {
            // next item won't fit here: penalize leaving residual just barely below next size
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 18.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
        // Extra reward if the fit is decent.
        if fit_ratio > 0.5 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bins should only win when open bins have bad fits.
    if bin_residual == bin_capacity {
        // Base handicap so a fresh bin only wins when placements into open bins score badly.
        score += 40.0;
        // Early in the stream, opening bins is cheap-ish; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins: discourage opening more.
        score += 2.5 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin may be wise.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Global residual pressure: when mean residual across bins is low, be frugal
    // with remaining space; when high, tolerate looser placements.
    let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 12.0 * pressure * fit_ratio;

    // Late-stream consolidation: prefer tightest bins as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // Mild preference for bins with residuals close to the item (best-fit flavor)
    score += 0.15 * (residual - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strongly reward exact closure.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize small nonzero residuals (dead space) with smooth polynomial coupling.
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score += 6.0 * tightness * tightness * (pr / bin_capacity as f64).max(0.0);

    // Reward if the lookahead item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Progress coupling: later in the stream, prefer tighter placements.
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    // New-bin candidate: penalize so it's only chosen when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild preference for bins with below-mean residual (denser bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic classes: dead space divisible into common small denominators
    // is more recoverable than arbitrary dead space.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus = if pr % 10 == 0 {
            6.0
        } else if pr % 5 == 0 {
            3.0
        } else if pr % 25 == 0 {
            4.0
        } else {
            0.0
        };
        score += harmonic_bonus;

        // Very small non-harmonic residues are dead space; penalize.
        if pr < 10 && pr % 5 != 0 {
            score += 8.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if pr >= next_item_size {
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 10.0;
            }
            score += npr as f64 * 0.3;
        } else {
            // next item won't fit here; residual becomes temporary dead space
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            (fitting_bins_count as f64).ln() + 1.0
        };
        score += 30.0 * pressure;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for bins with residual close to mean (balance load).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Prefer fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (low post_residual).
    score += post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Gaps that can never fit even the smallest item are dead space.
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Coupling: if the next item fits exactly into the resulting gap, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 - gap_waste * 0.5;
        } else {
            // Next item cannot use this gap: penalize proportionally to wasted potential.
            score += post_residual as f64 * 0.4;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins when decent fits exist.
    score += open_bins_count as f64 * 0.3;

    // Mean-residual coupling: placing into a bin whose residual is below average
    // preserves larger gaps elsewhere.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a good fit; make the empty-bin option costly by default.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 0.0;
        // If item is large relative to capacity, a fresh bin is more reasonable.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // Late in the stream, avoid leaving many half-empty bins behind.
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight preference to fill bins with larger residual first (first-fit-like
    // consolidation), scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (bin_residual as f64 / bin_capacity as f64) * (2.0 + 3.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Post residual can still hold the next item: strong reward, tighter is better
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 100.0 - slack * 0.8;
    }
    // Next item cannot fit here: penalize proportionally to wasted potential
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Prefer bins tighter than the mean residual (good fits)
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Avoid fragmenting large residuals into tiny dead space
    if post_residual > 0 && next_item_size > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild encouragement to fill bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * progress;

    // New-bin candidate: keep it moderately attractive only when few bins fit
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 30.0;
        } else {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with non-linear squashing
    let post = post_residual as f64;
    score = post * (1.0 + 0.5 * (post / bin_capacity as f64));

    // Penalize bins whose residual is much larger than needed (wasteful use of big space)
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.3 * waste * (waste / bin_capacity as f64);

    // Lookahead: reward if next item fits in post_residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else {
            // dead space that next item cannot use
            let dead = (post_residual as f64 - (next_item_size as f64).min(post));
            score += 0.15 * dead;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, mild preference for tighter ones (already via post)
        score += 1.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor fits
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty to prefer reusing open bins
        score += 10.0;
        // but if no open bin fits, this call is the only option -> must win
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // late in stream or many open bins with high mean residual -> avoid new bins more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
        score += 0.05 * open_bins_count as f64;
        score += 0.1 * mean_residual;
        // if next item is large, opening fresh bin may still be fine
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 4.0;
        }
    } else {
        // reusing bins with residual close to mean keeps balance
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // small penalty scaling with number of open bins to encourage consolidation
        score += 0.02 * open_bins_count as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mr = mean_residual / cap;

    // Quadratic penalty on wasted residual, modulated by stream progress
    score += 2.0 * norm_pr * norm_pr * (0.5 + t);

    // Cubic coupling: penalize large residuals more as stream progresses
    score += 3.0 * norm_pr.powi(3) * t;

    // Reward tight fits (small post_residual) more strongly over time
    score -= (1.0 - norm_pr).powi(2) * (1.0 + 2.0 * t);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Prefer bins with residual close to the mean (balance preservation)
    score += (norm_pr - mr).abs() * 2.0 * (1.0 - t);

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 1.5 * (ns / cap) * (1.0 + t);
        } else {
            score += 1.0 * (ns / cap);
        }
    }

    // Mild penalty for spreading across too many open bins late in stream
    score += (open_bins_count as f64 / (total_items.max(1) as f64)).sqrt() * 0.5;

    // New-bin candidate: make it moderately attractive only when fit is poor
    if bin_residual == bin_capacity {
        score += 0.5 - 4.0 * norm_pr * (0.5 + t) - (1.0 - item_size as f64 / cap) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small-item friendly" residue class are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by small sizes (10/20/25) -> reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
        if post_residual % 20 == 0 {
            score -= 2.0;
        }
    } else {
        // Perfect fit: strongest reward.
        score -= 25.0;
    }

    // Dead-space classes: leftover in awkward bands (1..10, 11..14, 16..19, 21..24)
    // that few items (min size 1, but typical stream items larger) can use.
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 8.0;
    } else if r >= 11 && r <= 14 {
        score += 5.0;
    } else if r >= 16 && r <= 19 {
        score += 3.0;
    } else if r >= 21 && r <= 24 {
        score += 1.5;
    }

    // Integer-division threshold on post_residual quarters of capacity.
    let quarter = (post_residual * 4) / bin_capacity.max(1);
    match quarter {
        0 => score += 6.0,          // < 25% left: nearly full, good
        1 => score -= 1.0,          // 25-50%: decent
        2 => score -= 2.0,          // 50-75%: fine
        _ => score += 2.0,          // >75%: bin barely used, penalize lightly
    }

    // Lookahead coupling: does the leftover exactly fit next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // perfect two-step chain
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 5.0; // next item nearly fills remainder
            } else {
                score -= 1.0;
            }
        } else {
            score += 4.0; // next item cannot use this leftover
        }
        // Harmonic match: leftover divisible by next item size
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor fits or are very fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Early in stream or many open bins: opening is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 30.0;
        }
        // If mean residual is large, open bins are roomy -> prefer them.
        score += (mean_residual / cap) * 20.0;
        // If next item is large and this item is small, opening fresh is fine.
        if next_item_size > 60 && item_size < 30 {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing),
    // penalize outliers via quadratic deviation.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 8.0;

    // Slight preference for tighter bins overall.
    score -= (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are effectively wasted capacity.
    if post_residual > 0 {
        let dead = post_residual < 10; // unusable gap below the minimum item size
        if dead {
            score += 60.0; // hard penalty for creating dead space
        } else {
            // Non-linear reward for small but usable residuals (tight fit).
            let tightness = post_residual as f64 / bin_capacity as f64;
            score -= 40.0 * (1.0 - 2.0 * tightness).max(0.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Reward exact match with the lookahead item (best-fit-k=2 coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 90.0;
    }
    // Penalize leaving a residual slightly above the next item (near-miss waste).
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 8 {
        score += 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate (bin_residual == bin_capacity) gets a penalty that
    // grows with the number of open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 6.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Mild mean-residual coupling: prefer bins whose residual is below average
    // (i.e., bins that are already fairly full).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual (good chaining).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit: post residual is likely dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Penalize very small unusable leftovers (< 10 = min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Relative-to-mean adjustment: bins with residual below mean are tighter,
    // prefer filling tight bins; bins far above mean are wasteful targets.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (large post_residual baseline keeps it unattractive normally).
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, a fresh bin is cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    // Mild preference for bins that become perfectly packed.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (best-fit core), stronger as the stream progresses.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let tight = (bin_residual - item_size.min(bin_residual)) as f64;
    score -= tight * (0.3 + 0.7 * t) * 0.5;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small post residual that is likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize leaving a gap that blocks the next item if gap is small.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(20) {
        score += 8.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residuals below the mean (tighter bins first).
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but less penalized late in the stream when many bins are open.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > 40.0;
        score += if bad_fit { -10.0 - 5.0 * t } else { 30.0 + 20.0 * (1.0 - t) };
    }

    // Mild penalty for very large item into nearly-full bin creating slivers.
    if item_size > 60 && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: waste left after placement
    let mut score = pr;

    // Smooth non-linear waste penalty: quadratic in normalized post-residual
    let norm_pr = pr / cap;
    score += 30.0 * norm_pr * norm_pr;

    // Reward near-perfect fits (smooth exponential reward as residual -> 0)
    score -= 25.0 * (-norm_pr * 8.0).exp();

    // Lookahead coupling: penalize leaving residual that neither fits next item well
    // nor is usefully small; smooth interaction between post_residual and next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        // If next item fits exactly-ish in the leftover, reward strongly (smooth bell)
        let sigma = cap * 0.08;
        let bell = (-(gap * gap) / (2.0 * sigma * sigma)).exp();
        score -= 18.0 * bell;
        // Penalize residual that is just barely too small for the next item (dead space)
        if gap < 0.0 {
            let miss = -gap / cap;
            score += 12.0 * miss * (1.0 - miss).max(0.0);
        }
    }

    // Scarcity pressure: if this is the last fitting bin, strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: add a smooth opening cost that grows with stream progress
    // and with how many bins are already open relative to a soft reference.
    if is_new_bin {
        let open_pressure = (open_bins_count as f64 / 8.0).tanh();
        score += 6.0 + 14.0 * progress + 8.0 * open_pressure;
    } else {
        // Mild reward for consolidating into existing bins as stream progresses
        score -= 3.0 * progress;
    }

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (tighter bins) with a smooth quadratic term.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and small remainders
    // that pair with small items are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fractional capacity classes: post_residual as a fraction of capacity.
        let frac = pr / cap;
        // Dead-space penalty grows superlinearly for mid-range waste.
        if frac > 0.45 {
            score += (frac - 0.45) * 120.0;
        }
        // Reward remainders that fall in "usable" harmonic classes:
        // multiples of common item sizes (10, 20, 25, 50) are reusable.
        let usable = post_residual % 10 == 0 || post_residual % 25 == 0;
        if usable {
            score -= 12.0;
        }
        // Modulo-5 class: very fine remainders (1..4) are near-dead space.
        if post_residual % 5 != 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // reward tight lookahead fits, penalize leaving next item stranded
            score -= (20.0 - gap.min(20.0)) * 1.5;
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64).min(60.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when many bins are open with low mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        // Base reluctance to open new bins; relax when residual spread is poor.
        score += 55.0 + progress * 40.0 + openness * 3.0;
        if mean_residual > 0.0 && pr > mean_residual {
            score -= 30.0; // fresh bin has above-average residual: keep option alive
        }
        if next_item_size >= 90 {
            score -= 45.0; // big next item: fresh bin is strategic
        }
    }

    // Prefer filling fuller bins when alternatives exist.
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= fullness * 15.0;

    // Mild stochastic-free tie-break via integer division class of item size.
    score += (item_size / 16) as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: gaps too small for any item are pure waste ---
    if post_residual < 10 {
        score -= 50.0; // perfect or near-perfect closure is excellent
    } else if post_residual < item_size.min(next_item_size.max(1)) {
        // gap cannot fit the current minimum granularity nor the lookahead item
        score += 25.0;
    }

    // Dead space that cannot host the next item is a liability
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits: fraction of residual consumed
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening new bins unless the current fit is poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // opening is attractive when the item is huge relative to capacity
        if item_size > bin_capacity * 3 / 4 {
            score -= 25.0;
        }
        // avoid bin explosion: pressure against too many open bins
        score += open_bins_count as f64 * 3.0;
    }

    // Mild pressure on number of open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual deviates favorably from the mean (fill emptier bins)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, prioritize closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for wasted residual space (superlinear).
    let post = post_residual as f64;
    score += 0.35 * post * post / bin_capacity as f64;

    // 2-step lookahead: reward if next item fits exactly into the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Reward tight chains: next item leaves small or zero leftover.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // perfect 2-item pairing
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / nxt.min(bin_capacity as f64)).max(0.0);
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    score += 0.5 * (mean_residual - post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post > 40.0;
        if poor_fit {
            score -= 18.0; // open a new bin rather than create dead space
        } else {
            score += 15.0; // discourage wasting a fresh bin on a good fit
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for bins among many fitting options (keep flexibility).
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post residual is already the base, amplify it)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space: post_residual that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 10.0 + 0.25 * (post_residual as f64);
        } else {
            // Reward residuals that exactly accommodate the lookahead item
            let gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many fitting bins: mild penalty to avoid wasting an abundant bin when a tighter one exists
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer bins with residuals below mean (compact bins) early, spread later
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (1.0 - progress) * 0.05 * dev - progress * 0.05 * dev;

    // Penalize opening a new bin when open bins can absorb the item, especially early
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        score += 8.0 + 12.0 * open_pressure + 6.0 * (1.0 - progress);
        // A new bin is fine if the item is huge and would leave nearly nothing behind
        if item_size as f64 / bin_capacity as f64 > 0.9 {
            score -= 15.0;
        }
    }

    // Mild penalty for very large leftover fragments that likely become dead space
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // tiny leftovers are fine (near-perfect packing)
    } else if post_residual >= 10 && post_residual < 30 {
        score += 3.0; // awkward mid-range fragment
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core waste term: quadratic in post_residual (dead space penalized super-linearly).
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth non-linear coupling of waste with stream progress:
    // late in the stream, dead space matters more (less chance to fill it).
    let prog_coupling = 1.0 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - post / cap; // in (0,1]
    score -= 6.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fit_quality = 1.0 - (post - nx) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // Next item cannot use this residual: mild penalty proportional to gap.
            score += 0.05 * (nx - post);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize crowding: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into low-residual bins.
    let mean_gap = mean_residual - post;
    score += 0.3 * mean_gap;

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        let open_cost = 25.0 * (1.0 - 0.5 * progress);
        // If residual of this new bin would fit the next item perfectly, soften cost.
        let soft = if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            3.0 * (1.0 - ((cap - item_size as f64) - next_item_size as f64) / cap)
        } else {
            0.0
        };
        score += open_cost - soft;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (quarters). Residuals that are "useless" (small,
    // below the minimum item size band) are dead space -> penalize.
    let quarter = bin_capacity as f64 / 4.0;
    let frac = post_residual as f64 / quarter;
    let class = frac.floor(); // 0..4 integer class via integer-division-like threshold
    match class as u32 {
        0 => score += 18.0,               // tiny leftover, near-perfect fit
        1 => score -= 4.0,                // small but potentially usable
        2 => score -= 10.0,               // half-ish leftover, very reusable
        3 => score -= 6.0,                // three-quarter leftover
        _ => {}                           // nearly empty bin placement
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits into the post-residual
    // (harmonic chaining), penalize if it just barely doesn't.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // exact modular harmony: next item leaves another clean class
            let nr = post_residual - next_item_size;
            if nr % 25 == 0 {
                score -= 6.0;
            }
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 8.0; // next item would need this bin's pre-place space
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bin fits are all poor (large post_residual) or no fit exists.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its future residual is capacity - item
        score = (bin_capacity - item_size) as f64;
        // late in the stream, avoid spawning bins for small leftovers
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual < quarter {
            score += 15.0 * (0.5 + progress);
        }
        // many open bins -> discourage further sprawl
        score += open_bins_count as f64 * 1.5;
        // if next item is large, a fresh bin may be justified
        if next_item_size > 3 * quarter as u32 && post_residual < next_item_size as f64 {
            score -= 10.0;
        }
    } else {
        // slight preference for fuller bins (low residual before placement)
        score += (bin_residual as f64) * 0.05;
        // align with global mean residual: prefer bins below mean (fuller)
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (min size 1..10)
    // can use are pure waste. Penalize the "unusable band" aggressively.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 120.0;
    } else if post_residual >= 50 {
        // Large leftover space is flexible; mildly reward keeping it.
        score -= 15.0;
    }

    // Reward tight fits relative to current residual.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // a new bin (residual == capacity) should be penalized more as open_bins_count grows.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + 2.5 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 5.0 + 1.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement;
    // if the next item is large and this bin is the only fit for the current item, be careful.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Align with global mean residual: bins far below mean residual are "emptier"
    // than average; prefer filling those (lower residual deviation -> lower score).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward near-exact match of post_residual to next item.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - look).abs();
        if post >= look {
            // Next item fits perfectly in the leftover space: strong reward.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // exact two-item completion
            }
        } else {
            // Next item won't fit here; penalize wasted residual that is too small to be useful.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 6.0 * progress * (1.0 - post / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Relative to mean residual: filling a below-average-residual bin is good (reduces fragmentation).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last chance: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity as f64 - item_size as f64);
        let poor_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 20.0 * poor_fit + 0.05 * waste;
        if next_item_size > 0 && next_item_size >= item_size && (bin_capacity - item_size) >= next_item_size {
            score -= 15.0; // new bin can host a nice pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to item size is better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 40 {
        score -= 4.0; // usable mid-range residual
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last chance: only one bin fits — strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual → prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mean_ratio = mean_residual / bin_capacity as f64;
    score -= 6.0 * mean_ratio * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin unless nothing else makes sense.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
        // If next item is large, a fresh bin may be attractive anyway.
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mild preference for bins that are already partially filled.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual
    let poly = prn * prn * (1.0 + progress) + prn * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits (small post residual) more strongly as stream progresses.
    let tight = 1.0 - prn;
    score -= 8.0 * tight * tight * (0.5 + progress);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // Reward leaving exactly usable space for next item.
        let waste = pr - next_item_size as f64;
        score += 0.02 * waste * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let load = item_size as f64 / cap;
        score += 10.0 - 14.0 * load * load;
        score += 5.0 * (open_bins_count as f64).ln1p();
    }

    // Mild penalty for spreading residual far from mean residual.
    let dev = pr - mean_residual;
    score += 0.01 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // "compatible" with the coarse item grid and easier to fill later.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0; // perfectly harmonic residual
    } else if class <= 3 {
        score += 4.0; // tiny dead-space slivers
    } else {
        score += 2.0 * class as f64;
    }

    // Integer-division threshold: residual that can still hold a mid item
    // (>= 40) is valuable; below that it is near-dead space.
    if post_residual >= 40 {
        score -= 5.0;
    } else if post_residual < 15 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward; if it cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new one unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize by remaining stream length so early
    // streams prefer reusing bins, but allow escape from bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * (1.0 - progress);
        // opening a new bin is fine if the item is large and would leave
        // an awkward residual elsewhere
        if item_size >= 60 {
            score -= 6.0;
        }
    }

    // Mild pressure toward bins with below-average residual (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Tie-break: prefer filling more-open bins when many are open.
    score -= 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that still leave room for a plausible next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Creating a gap just below the next item is bad.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Tightness reward: filling most of the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, discourage fragmenting further;
    // prefer consolidating into existing bins (especially the new-bin candidate gets penalized).
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * 3.0;

    // New-bin candidate handling: only attractive when current bins have poor fit potential.
    if bin_residual == bin_capacity {
        // Baseline penalty so new bins are opened only when justified.
        score += 15.0;
        // If mean residual across open bins is small (bins nearly full), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // Many fitting bins means no need for a new one.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // Early in stream, more willing to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for bins tighter than average (keep big residuals for big items).
    if (bin_residual as f64) > mean_residual + 20.0 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 150.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally
        // to how much dead space is stranded.
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual against mean residual: leaving more than
    // average slack wastes capacity; leaving less is good compaction.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item
    // is large and would leave a small, unusable residual elsewhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Large items near stream end may justify a fresh bin.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 {
            score -= 80.0 * progress;
        }
    }

    // Mild preference for tighter bins among equals.
    score += 0.1 * (bin_capacity - bin_residual) as f64 * 0.0
        + 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead reward: if the next item can also fit here, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    }
    // Lookahead penalty: if the next item almost fits but not quite, mild penalty
    // (this bin becomes a dead-end for the upcoming item).
    if next_item_size > 0 && post_residual < next_item_size && post_residual + 10 >= next_item_size {
        score += 6.0;
    }

    // Last-chance bonus: this is the only open bin that can take the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: discourage opening a fresh bin when open bins
    // still carry usable residual capacity; encourage it late in the stream or
    // when existing residuals are small.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - t) + 0.6 * mean_residual + 0.4 * open_bins_count as f64;
        // If item is huge, a fresh bin is relatively attractive.
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Penalize creating tiny unusable dead space (below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight global pressure: prefer consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer tighter fits nonlinearly.
    let fit_ratio = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 10.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: early on tolerate waste (explore), later be tight.
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Dead-space penalty: residuals too small for typical future items are costly.
    let dead = ((pr - 1.0).max(0.0) / cap).powi(3);
    score += 25.0 * dead * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward residuals that can hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: bins far from the mean get a mild correction.
    score += 0.15 * (pr as f64 - mean_residual).abs();

    // New-bin candidate handling: penalize opening a new bin when open bins fit,
    // but relax late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let relax = 0.3 * progress + 0.05 * (open_bins_count as f64).min(20.0) / 20.0;
        score += (40.0 - 25.0 * relax).max(8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual by capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let half = c / 2.0;

    if pr > 0.0 {
        if pr < quarter {
            // Small dead space: penalize proportionally harder (non-linear).
            score += (quarter - pr) / quarter * 15.0;
        } else if pr < half {
            // Mid-range residual: mildly attractive.
            score -= 5.0;
        } else {
            // Large residual left: generally fine, small bonus.
            score -= 8.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes are more reusable. Use gcd-like harmonic check.
    let pr_u = post_residual;
    if pr_u > 0 {
        let mod10 = pr_u % 10;
        let mod20 = pr_u % 20;
        if mod10 == 0 {
            score -= 6.0; // divisible by 10: likely reusable by decile-sized items
        } else if mod20 == 0 {
            score -= 3.0;
        } else {
            score += mod10 as f64 * 0.4; // ragged remainder penalty
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportional to tightness of that fit.
            let nn = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - nn / c).max(0.0);
        } else {
            // Next item won't fit here: penalize if we also leave dead space.
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with stream progress and number of open bins, encouraging consolidation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + progress * 20.0 + open_bins_count as f64 * 2.0;
        // But if no open bin offers a decent fit, new bin becomes viable:
        // handled implicitly since real bins with bad fits get high scores.
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (filling the emptier-relative bins first keeps spread tight).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to be
    // useful are heavily penalized (they become wasted capacity).
    if post_residual > 0 {
        let min_useful = 10u32.min(bin_capacity);
        if post_residual < min_useful {
            score += 40.0 * (min_useful - post_residual) as f64;
        }
        // Non-linear coupling: small-but-nonzero gaps are the worst dead space.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        if gap_frac > 0.0 && gap_frac < 0.15 {
            score += 60.0 * (1.0 - gap_frac / 0.15);
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (i.e., penalize the empty new-bin candidate relative to existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64 + 10.0 * progress;
    } else {
        score -= 0.1 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize placements that leave a gap just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Mild pull toward bins with residuals close to what we need (best-fit flavor)
    score += 0.2 * (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward exact chain fits (post_residual == next_item_size) ---
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 == nr {
            // Perfect 2-chain: residual consumed exactly by next item
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits: penalize leftover after the chain
            let chain_residual = post_residual as f64 - nr;
            score += chain_residual * 0.8;
            // Bonus for tight chain (little waste after two items)
            score -= (1.0 - chain_residual / bin_capacity as f64) * 15.0;
        } else {
            // Next item does NOT fit this residual: the residual becomes dead space
            // unless it is small. Penalize medium dead residuals.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < nr {
                // Dead space that likely cannot be used soon
                score += dead * 0.5 + 10.0;
            }
        }
    }

    // --- Relative to mean residual: prefer bins that become tighter than average ---
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += rel * 12.0;
    }

    // --- Reward filling large residuals (avoid fragmenting big spaces) ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // --- Last-chance bonus: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling: only prefer a fresh bin when the item is huge
    //     relative to every residual and stream is early (many future items to fill it) ---
    if bin_residual == bin_capacity {
        let tight_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual - item_size) > 0
            && item_size as f64 / bin_residual as f64 > 0.7;
        if tight_fit_exists && progress > 0.15 {
            score += 55.0; // discourage opening new bin when a tight fit exists
        } else {
            score -= 5.0 + 10.0 * (1.0 - progress);
        }
    }

    // --- Small penalty for very tiny residuals that are hard to fill (1..10) ---
    if pr > 0.0 && pr < 10.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty for wasting the residual
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 0.5 * open_bins_count as f64 + 10.0 * (1.0 - progress);
        // But if the item is huge relative to mean residual space, opening may be fine
        let gap = mean_residual - item_size as f64;
        if gap < 5.0 {
            score -= 18.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (consolidate small leftovers)
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Mild preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * norm_pr * cap * (0.35 + 0.55 * p2 + 0.30 * p3);

    // Reward tight fits, more strongly late in the stream
    let tight = 1.0 - norm_pr;
    score -= cap * tight * tight * (0.45 + 0.65 * progress);

    // Lookahead coupling: penalize residuals that can't host the next item
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        if gap < 0.0 {
            score += (-gap) * cap * (0.25 + 0.45 * progress);
        } else {
            // residual that exactly hosts next item is valuable
            score -= gap * (1.0 - gap) * cap * 0.35;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap * 0.30 * (0.5 + 0.5 * progress);
    }

    // Scarcity pressure: fewer fitting bins -> prefer using them
    if fitting_bins_count > 0 {
        score -= cap * 0.10 / fitting_bins_count as f64;
    }

    // Mean-residual anchoring: prefer bins near the mean state (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.12 * (1.0 - progress);

    // Mild preference to fill existing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += cap * (0.45 + 0.55 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity-fraction classes)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual % 10) as f64;
    let quot = (post_residual / 10) as f64;

    // Dead-space penalty: residual that cannot host the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // usable for next item: reward proportionally
            score -= ((post_residual - next_item_size) as f64).min(20.0) * 0.15;
        }
    }

    // Class-based dead space: small nonzero residuals are waste
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - class) * 1.5;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Integer-division threshold coupling: quot tiers of residual
    score -= quot * 0.4;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when mean residual across open bins is large
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 20.0 * pressure.max(0.0) - 5.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Stream progression: late in stream, tighten packing (prefer tight fits more)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress * (post / cap);

    // Harmonic coupling between class and next item size class
    let next_class = (next_item_size % 10) as f64;
    if next_item_size > 0 && post_residual >= next_item_size {
        let harmony = ((class - next_class).abs()) / 10.0;
        score -= (1.0 - harmony) * 3.0;
    }

    // Open bins count: discourage proliferation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (0 < post_residual < 10) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading (favor new bin only when very poor fit).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when pressure is high and this is a decent fit window,
        // but avoid opening bins when the item fits snugly elsewhere.
        score -= 12.0 + 3.0 * pressure;
        if post_residual >= 10 {
            score -= 5.0;
        }
    } else {
        // Slight penalty for putting item into a bin whose residual is far above item (bad tightness).
        if (bin_residual as i64 - item_size as i64) as f64 > mean_residual {
            score += 4.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item is bigger than post_residual but smaller than full capacity,
    // leaving a gap it can't use is mildly bad.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Late in stream: prefer closing bins out (favor tight fills, avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, huge reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tight the fit is
            score -= 150.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving large unusable gaps
            score += 40.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Penalize small post_residuals that are likely dead space relative to item range
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: prefer bins whose residual deviates favorably
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize so we only open when fits are truly bad
    if bin_residual == bin_capacity {
        score += 200.0;
        // But if nothing fits well elsewhere, opening may still win via lookahead
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 50.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            let waste = post_residual as f64 - (post_residual as f64 - next_item_size as f64).abs();
            score += 0.05 * (post_residual as f64).powf(1.2);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when open bins have plenty of room.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 10.0 + 20.0 * pressure;
        // Early in the stream, opening new bins is cheaper (keeps options open).
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 12.0 * (1.0 - t);
        // Many open bins -> discourage more fragmentation.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins with residual close to the item (best-fit flavor).
    let gap = (bin_residual - item_size) as f64;
    score += 0.03 * gap;

    // Time horizon: later in stream, be greedier about tight fits.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // normalized post-residual in [0,1]

    // Base: wasted space after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // late in the stream, small residuals become increasingly dead space (quadratic & cubic growth)
    let t = progress;
    score += (norm_pr * norm_pr) * 30.0 * (0.5 + t);
    score -= (norm_pr * norm_pr * norm_pr) * 20.0 * t;

    // Reward tight fits: smooth bell-shaped bonus around small post-residual
    let tightness = (-norm_pr * norm_pr * 8.0).exp();
    score -= 25.0 * tightness * (1.0 + t);

    // Penalize residuals that are too small to ever fit typical future items
    // (smooth penalty rising as post-residual falls below ~20% capacity)
    let unusable = (-(norm_pr / 0.2).max(0.001)).exp();
    score += 15.0 * unusable * (1.0 - t);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + t);
    }

    // Many open bins: prefer consolidating into existing space
    let open_f = open_bins_count as f64;
    score += open_f * 0.5 * norm_pr;

    // Lookahead: if next item fits into post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 20.0;
    } else if next_item_size > 0 {
        // next item won't fit: mildly penalize leaving awkward gaps
        score += 5.0 * (1.0 - (pr / next_item_size as f64)).max(0.0);
    }

    // Compare against mean residual: prefer bins below mean (filling emptier bins keeps flexibility)
    score += (mean_residual - pr) * 0.1;

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // attractive only when the item is large or stream is late and fits are poor
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 10.0 - 15.0 * large_item * (0.3 + t);
        if fitting_bins_count <= 1 {
            score -= 30.0 * (1.0 + t);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted after placement

    // Non-linear reward for tight fits (small post_residual is exponentially good).
    score -= 40.0 * (-frac * 6.0).exp();

    // Harmonic class penalty: dead space in awkward zones is less reusable.
    // Classes via integer division of post_residual into bands of 12 (100/12 ~ 8 classes).
    let class = post_residual / 12;
    let class_penalty = match class {
        0 => -25.0,           // 0..11: near-perfect fit, strongly favored
        1 => 5.0,             // 12..23: small gap, still useful
        2 => 12.0,            // 24..35: moderate
        3 => 20.0,            // 36..47: awkward zone
        4 => 14.0,            // 48..59: half-ish bin, can host medium items
        5 => 18.0,
        6 => 10.0,            // 72..83: large gap, reusable
        _ => 2.0,             // near-empty bin: fine
    };
    score += class_penalty;

    // Lookahead coupling: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (-slack / 15.0).exp(); // next item fits well here
        } else {
            // next item cannot use this bin's residue: dead space more likely permanent
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item) up front.
    if bin_residual == bin_capacity {
        // Prefer new bin only when all open residuals are poor and item is large.
        let mean_frac = mean_residual / cap;
        score += 20.0 + 30.0 * mean_frac; // default penalty: reuse open bins
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 10.0; // chaining large items together into fresh bins
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        if mean_residual < 25.0 && item_size > 60 {
            score -= 35.0; // large item into fresh bin beats crushing small residuals
        }
    }

    // Mild pressure against bin sprawl late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * progress;

    // Slight preference to balance residuals toward the mean.
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical items are wasted.
    // Items range 1..100, so a residual < 10 is nearly unusable; < 25 is risky.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space
        } else if post_residual < 25 {
            score += 25.0 + (25 - post_residual) as f64 * 1.5;
        } else if post_residual < 50 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Lookahead: if next item fits exactly in post_residual, this is a great pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let left_after_next = post_residual - next_item_size;
            if left_after_next < 10 {
                score -= 15.0; // nearly exhausts bin with two items
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: mildly penalize leaving a mid-size gap.
            if post_residual >= 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_bins_count as f64 * 4.0 + progress * 20.0;
    } else {
        // Mild reward for using existing bins when bin count is high.
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins with residuals close to the item (below mean residual = tighter bin).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: large reward for tiny post residual
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item exactly fills the post residual, reward strongly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next == post {
            score -= 500.0;
        } else if next < post {
            // next item fits after this placement: reward proportional to tightness
            let tight = 1.0 - (post - next) / bin_capacity as f64;
            score -= 50.0 * tight;
            // exact chain: post - next leaves small residue again
            let chain = post - next;
            if chain <= 5.0 {
                score -= 150.0;
            }
        } else {
            // next item will NOT fit here: penalize leaving moderate dead space
            if post < next && post > 0 {
                score += 30.0 * (1.0 - post / next.max(1.0) as f64);
            }
        }
    } else {
        // last item: strongly prefer filling bins as much as possible
        score -= 300.0;
    }

    // Dead space penalty relative to mean residual: bins with residual far from typical
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize leaving residual smaller than the minimum plausible item (1..100 unknown, assume >=10-ish)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer denser packing when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins would leave bad residuals
    if bin_residual == bin_capacity {
        // neutral base; opening a new bin competes via post_residual = capacity - item
        score += 60.0;
        if next_item_size > 0 && (bin_capacity - item_size) as f64 == next_item_size as f64 {
            score -= 400.0;
        }
        // late in stream, avoid opening new bins too eagerly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);

    // Base: prefer leaving as little residual as possible.
    let mut score = post;

    // Reward near-perfect fits superlinearly (dead space is the enemy).
    if post <= 5.0 {
        score -= 8.0;
    } else if post <= 10.0 {
        score -= 4.0;
    } else {
        // Penalize large leftover space proportionally to how unusable it is
        // relative to the smallest plausible item.
        score += (post / cap).powf(2.0) * 6.0;
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // heavily; if it would fit in post-residual anyway, mild reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() <= 1.0 {
            score -= 10.0; // perfect pairing
        } else if nxt <= post {
            score -= 3.0; // next item still fits here
        } else {
            // Next item won't fit here: mild penalty proportional to gap,
            // softened late in the stream.
            score += ((nxt - post) / cap) * 6.0 * (1.0 - 0.5 * progress);
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // encourage consolidating into existing bins (avoid fragmentation).
    let open_bonus = (open_bins_count as f64).ln().max(0.0);
    let frag_pressure = (mean_residual / cap) * open_bonus * 2.0;
    if bin_residual != bin_capacity {
        score -= frag_pressure; // reward filling existing bins when fragmented
    }

    // New-bin candidate handling: baseline penalty so a fresh bin is chosen
    // only when every open bin would leave a wasteful residual.
    if bin_residual == bin_capacity {
        score += 14.0;
        // If no open bin fits at all, opening is mandatory: remove penalty.
        if fitting_bins_count == 1 {
            score -= 14.0;
        }
        // Late in the stream, slightly discourage sprawling new bins.
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * pr / cap) - 12.0 * (1.0 - pr / cap).powi(3);

    // Stream-progress coupling: early on, tolerate larger residuals (keep bins flexible);
    // later, tighten aggressively (favor near-full bins)
    let tighten = 0.5 + 1.5 * progress;
    score += pr * (1.0 - progress) * 0.6;
    score -= (cap - pr) * tighten * 0.4;

    // Non-linear coupling of post-residual with mean residual of open bins:
    // penalize leaving residual far above the mean (dead space outlier)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Lookahead: reward residual that can host the next item (smooth bell)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = pr - n;
            score -= 6.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 0.4 * (n - pr);
        }
    }

    // Last-chance bin: strong smooth bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Many open bins: mild pressure to consolidate
    score += 0.05 * open_bins_count as f64;

    // New empty bin candidate: heavily penalized unless it yields an exact/near-exact fill
    if bin_residual == bin_capacity {
        let exactness = 1.0 - pr / cap;
        score += 25.0 - 20.0 * exactness.powi(4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let pr = post_residual;
    let class = (pr % 10) as f64;
    let div10 = (pr / 10) as f64;

    // Penalize residuals that fall into "dead zone" classes (1..=9 hard to fill)
    if pr > 0 && pr < 10 {
        score += 18.0 - class; // small awkward leftover
    } else if pr >= 10 && pr < 20 {
        score -= 4.0 - class * 0.3; // mildly fillable
    }

    // Reward residuals that are multiples of 10 (harmonic with typical sizes)
    if pr % 10 == 0 {
        score -= 6.0;
    }
    // Reward residuals that are multiples of 20
    if pr % 20 == 0 {
        score -= 4.0;
    }
    // Reward residuals that are multiples of 25 (quarter-capacity)
    if pr % 25 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let leftover2 = pr - next_item_size;
            score -= 8.0 - (leftover2 % 10) as f64 * 0.4;
            if leftover2 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size as f64 - pr as f64).min(20.0) * 0.25;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish score so only good fits beat it
    if bin_residual == bin_capacity {
        score = cap * 0.75;
        if item_size >= 60 {
            score -= 10.0; // big items start fresh bins
        }
    }

    // Tight fit reward: near-perfect packing
    let tight = (pr as f64) / cap;
    score += tight * tight * 10.0;

    // Progress modulation: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * div10 * 0.5;

    // Many open bins: prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Distance from mean residual: prefer bins below mean (fill fuller bins)
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: subtract when post_residual is small relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Strict dead-space avoidance: post_residual in [1, 15] is nearly unusable
    // for future items; penalize it quadratically on top of the base value.
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 4.0;
    }
    // Medium gaps (16..30) are mildly risky.
    if post_residual > 15 && post_residual <= 30 {
        score += 3.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling
    // existing bins over the new-bin candidate.
    let open_pressure = (open_bins_count as f64).ln() * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, modulated by how badly
        // this item fits existing bins and by stream progression.
        let mut new_bin_cost = 25.0 + open_pressure;
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0; // forced open, make it cheap
        }
        // Lookahead: if next item is large, a fresh bin may be valuable.
        if next_item_size > item_size {
            new_bin_cost -= 6.0;
        }
        // Late in the stream, avoid leaving many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost += (1.0 - progress) * 5.0;
        score = score.max(0.0) + new_bin_cost;
    } else {
        // Existing bin: slight bonus for being below mean residual (emptier bin
        // absorbs item, preserving tight bins).
        if (bin_residual as f64) > mean_residual {
            score -= 2.0;
        }
        // Lookahead synergy: if next item fits exactly into post_residual,
        // strongly favor this bin.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
            score -= 10.0;
        } else {
            // next item won't fit here; penalize wasted residual
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: residual value is zero, prefer any fit
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins that are more filled than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral-ish score so it's only chosen when fits are poor
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= next_item_size as f64 * 0.3;
        }
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            score += 30.0; // discourage opening new bin when only one fit exists
        }
    }

    // Late-stream: consolidate, avoid leaving many small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness of the fit: fraction of the bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Penalize dead space that no plausible item (>=1) can use well:
    // small residuals are fine (covered above); mid-range residuals are wasteful
    if post_residual > 10 && post_residual < 25 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // this placement is very attractive; if it almost fits, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let leftover_after_next = post_residual as f64 - nxt;
            score -= 22.0 * (1.0 - leftover_after_next / bin_capacity as f64);
        } else {
            let miss = (next_item_size as u32 - post_residual) as f64;
            score += 8.0 * (miss / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score -= 6.0 * pressure;

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let open_penalty = 55.0 * (1.0 - progress) + 20.0 * (1.0 - mean_residual / bin_capacity as f64);
        score += open_penalty;
        // A new bin is cheap if the item is large (little residual wasted)
        score += 0.3 * post_residual as f64;
        // Late in the stream with many open bins, avoid opening more
        if progress > 0.7 && open_bins_count > 4 {
            score += 40.0 * progress;
        }
    } else {
        // Favor bins that are already fairly full (keep many options open elsewhere)
        let used_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * used_ratio;
    }

    // Mild time-horizon modulation: early stream, be exploratory (slightly
    // prefer larger residual bins to keep flexibility); late, be greedy.
    score += 12.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: prefer tight fills (low post_residual); late stream: tolerate slack less
    let coupling = pr_norm * pr_norm * (1.0 - progress) * (1.0 - progress)
                 + pr_norm * p3 * 2.0;
    score += coupling * cap * 0.5;

    // Reward near-perfect fits smoothly (post_residual close to 0)
    let tightness = (1.0 - pr_norm).powi(3);
    score -= tightness * it * 0.35;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 18.0 + 0.2 * it;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use
        score += 4.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)).min(1.0)) * pr_norm;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.25 - dev * cap * 0.15 * (1.0 - progress);

    // New-bin candidate: penalize mildly so real bins are preferred unless fit is bad
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity split into 4 bands.
    // Small post_residual = tight fit = reward strongly.
    let q = post_residual * 4 / bin_capacity;
    match q {
        0 => score -= 45.0,               // near-perfect fit (<=25% left)
        1 => score -= 15.0,               // decent
        2 => score += 8.0,                // mediocre
        _ => score += 20.0,               // wasteful (>50% left)
    }

    // Harmonic class of post_residual relative to next item size:
    // if the next item fits exactly-ish in the leftover, big reward.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 60.0;                // chain of perfect fits
        } else if gap > 0 && (gap as u32) * 4 <= bin_capacity {
            score -= 25.0;                // next item still fits well here
        } else if gap < 0 && (next_item_size as u32) <= bin_residual {
            score += 10.0;                // next item won't fit after us
        }
    }

    // Last chance: only this bin can host the item -> strong reward.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // New-bin candidate: opening a bin is costly unless open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64;
        score += 55.0 - 12.0 * crowded.min(6.0) - 20.0 * progress;
        // If this bin would be the ONLY fitting option anyway, allow opening.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Dead-space penalty: leftover that no plausible item (min size 1, typical
    // >= 10) can use is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer bins whose residual deviates from the mean (specialized packing):
    // filling a bin far below mean residual consolidates space.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Mild tie-break: favor fuller bins early, spread later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; the smaller the usable remnant, the worse.
    if post_residual > 0 {
        let waste = 1.0 / (post_residual as f64);
        score += 40.0 * waste;
    } else {
        // Perfect fit is excellent: strong reward.
        score -= 60.0;
    }

    // Penalize residuals that cannot fit the lookahead item but could otherwise
    // be useful: dead space relative to next_item_size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }
    // Reward when the next item fits exactly in the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // (penalize the new-bin candidate implicitly by rewarding existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * (open_bins_count as f64).sqrt() * (0.5 + progress);

    // Prefer bins tighter than average (they are the most constrained resource).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Prefer placing into bins with small residual overall (tight fit priority).
    score += 0.2 * (bin_residual as f64);

    // Mild reward for large item consumption of the bin.
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: squaring post_residual amplifies small leftovers.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward perfect fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 80.0;
        }
        // Penalize leaving a residual that is just barely too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when open bins
    // have plenty of residual; only attractive when existing residuals are small.
    if bin_residual == bin_capacity {
        // Base penalty for a new bin, scaled by how much space is idle elsewhere.
        score += 30.0 + mean_residual * 0.8;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
        // If many open bins exist, slightly prefer consolidating into them.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > item_size {
            score -= 15.0;
        }
    } else {
        // Favor bins whose residual is close to the mean (balance load) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
        // Favor fuller bins (smaller residual) when many bins are open.
        score -= (bin_capacity - bin_residual) as f64 * 0.05 / (1.0 + open_bins_count as f64 * 0.05);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly prefer bins where item fills most of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio * (1.0 + 0.5 * progress);

    // Non-linear coupling of post_residual with progress: dead space costs more later.
    let norm_post = post / cap;
    score += 25.0 * norm_post * norm_post * (0.4 + 0.9 * progress);

    // Penalize near-miss residuals (unusable small gaps), smooth via sine bump.
    let small_gap = (norm_post * 20.0).sin().abs();
    score += 6.0 * small_gap * (1.0 - norm_post) * (0.5 + progress);

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap) * (0.6 + 0.4 * progress);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate: open a fresh bin only when open bins are crowded late in stream.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let mean_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 30.0 - 20.0 * crowd * mean_tight * (0.3 + 0.7 * progress);
    }

    // Mild preference to consolidate into fewer bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue buckets.
    let pr = post_residual;
    let class = pr / 10; // 0..=10 classes of leftover space

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize residuals that fall into "awkward" harmonic classes:
    // small nonzero leftovers (< 10) are dead space; large leftovers are still useful.
    if pr > 0 && pr < 10 {
        score += 25.0 - 2.5 * (pr as f64); // tiny leftovers are worst
    } else if pr == 0 {
        score -= 40.0; // perfect fit: heavily reward
    } else {
        // Cosine-shaped reward over harmonic classes: classes near multiples of 5
        // (i.e., residuals 0, 50, 100 mod 100) are more reusable for mid-size items.
        let phase = (pr as f64) * std::f64::consts::PI / 50.0;
        score -= 6.0 * phase.cos();
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward proportionally, but less if leftover after next item would be tiny
        let pr2 = pr - next_item_size;
        if pr2 < 10 && pr2 > 0 {
            score -= 5.0; // mild reward, would create dead space after next
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity && pr < next_item_size {
        // next item won't fit here; slight penalty since bin will be closed wastefully
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should be discouraged unless
    // current bin fit is bad. The empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open.
        score += 15.0 + 2.0 * (open_bins_count as f64).sqrt() * 3.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // But if the item is huge and mean residual is small, opening is fine.
        if (mean_residual < item_size as f64) && item_size > 60 {
            score -= 25.0;
        }
    }

    // Prefer filling bins with below-average residual (balance + close-out).
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64) - mean_residual;
        score += 0.15 * diff;
    }

    // Modulo-class penalty: residuals congruent to 1..9 mod 10 are hardest to reuse.
    let m = pr % 10;
    if m >= 1 && m <= 9 {
        score += 3.0 + 0.5 * (9 - m) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderately awkward gap: mild penalty scaled by tightness.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if next item fits perfectly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + slack / 5.0);
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: base score is post_residual == capacity; make it
    // unattractive unless open-bin fits are bad (dead space / no alternatives).
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * (open_bins_count.min(20) as f64);
        // If item is large relative to capacity, opening a fresh bin is fine.
        score -= item_size as f64 * 0.2;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    if bin_residual != bin_capacity {
        score -= (open_bins_count.min(30) as f64) * 1.2;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0);

    // Early stream: allow slightly more aggressive bin consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly/well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_waste / bin_capacity as f64);
            // Perfect chain bonus: next item exactly fills the bin
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: penalize dead space creation
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid making this bin an outlier
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless the item is huge relative to capacity
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 * (1.0 - big_item);
        // If nothing else fits, opening a new bin is fine
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Late in the stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items are wasted.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 12.0 * dead * (post_residual as f64 + 1.0).ln();
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is cheap early, expensive late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Lookahead: reward leaving room for the next item; penalize if post_residual
    // can't hold next_item_size while bin_residual could have.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else if bin_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Prefer filling bins with small residuals relative to mean (consolidation).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Mild preference to spread across fewer bins when many are open.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr;
    score += 20.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 15.0 * norm_pr * progress * (1.0 - progress);

    // Reward tight fits, scaled by progress.
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit * fit * (0.5 + progress);

    // Penalize dead space below smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 10.0 * (n / cap) * (1.0 + progress);
        } else {
            score += 6.0 * (1.0 - n / cap);
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: prefer opening a bin early, less so late.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling.
    score += 0.1 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: residual mod 10 buckets
    let resid_class = (post_residual % 10) as f64;
    score += resid_class * 0.35;

    // Perfect / near-perfect closures get strong rewards
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic pairing: does next item divide into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        // reward tight harmonic follow-ups (ratio near 1)
        score -= 30.0 * fit_ratio * fit_ratio;
    } else if next_item_size > 0 {
        // penalize if next item cannot use the leftover space
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap.min(40.0);
    }

    // Fractional capacity coupling: post_residual as fraction of capacity
    let frac = post_residual as f64 / cap;
    score += 20.0 * frac * frac;

    // Last-chance bin bonus: only one bin fits -> strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap).min(1.0);
        score += 55.0 - 45.0 * tight;
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Congestion pressure: many open bins -> prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64) * 0.8 * (0.5 + progress);

    // Dead-space penalty for awkward mid-range residuals (harmonic valleys)
    if post_residual > 30 && post_residual < 50 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero residuals are the worst outcome.
    // A residual that cannot fit even the smallest plausible item (or the lookahead)
    // is "dead space" — penalize it steeply and non-linearly.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual < min_useful {
        // Unusable sliver: heavy penalty proportional to tightness.
        score += (min_useful - post_residual) as f64 * 3.0 + 15.0;
    } else {
        // Usable but small gaps still mildly penalized (wasted capacity).
        score += (post_residual as f64).powf(0.35) * 1.5;
    }

    // Tight-fit reward: fraction of residual consumed by the item.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate gets penalized via open_bins_count), and encourage
    // consolidating into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 10.0 + open_bins_count as f64 * 4.0;
        // But if no open bin can fit at all, opening is fine (handled implicitly
        // since fitting bins get last-chance / fit rewards).
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Lookahead synergy: opening a fresh bin is better if the next item
        // is large and current mean residuals are small.
        score -= (next_item_size as f64 / 100.0) * (100.0 - mean_residual) * 0.1;
    } else {
        // Placing into an existing bin slightly rewarded when open bins are many.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (tighter bins first — classic best-fit behavior with adaptive tilt).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: as the stream progresses, waste matters more,
    // so tighten the dead-space penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + progress * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack * 0.2); // next item fits with bounded slack
        } else {
            // next item won't fit: penalize wasted residual
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
        // residual too small for anything useful (dead space)
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 8.0; // using more space than average => good consolidation
        } else if rel > 1.5 {
            score += 5.0; // leaving unusually large residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    // (i.e., item is large relative to typical residuals and next item is large).
    if bin_residual == bin_capacity {
        let tight_fit = (bin_residual as f64 - item_size as f64).abs() * 0.15
            + if next_item_size > 0 && post_residual >= next_item_size { 25.0 } else { 0.0 };
        score += 30.0 - tight_fit; // default penalty; reduced when item is large / chains well
        if item_size >= 60 {
            score -= 20.0; // big items deserve fresh bins
        }
        if fitting_bins_count > 1 {
            score += 10.0; // alternatives exist, discourage new bin
        }
    }

    // Early stream: slightly encourage consolidation to build dense bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that no future item could plausibly use.
    // Small residuals (< typical minimum item size) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement; otherwise penalize creating unusable leftovers.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than
    // spreading items out (avoid bin proliferation).
    score += 0.4 * open_bins_count as f64;

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // current item is large and fits poorly everywhere else. An empty bin
    // should be kept pristine for big items.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Large items justify a fresh bin more than small ones.
        score -= 0.12 * item_size as f64;
        // If no open bin fits well, opening a new bin becomes more attractive.
        if post_residual > 40 {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be more conservative with bin
    // openings (many items remain to fill bins); late in the stream,
    // tightness dominates and consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;

    // Mean residual coupling: when open bins are already loose on average,
    // prefer filling this one tightly rather than adding slack.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Mild preference toward bins with less residual before placement
    // (fill fuller bins first, classic best-fit behavior).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) shaping
    let mut score = pr + 8.0 * norm_pr * norm_pr * cap;

    // Early in stream: tolerate larger residuals (future items may fill them);
    // late in stream: penalize residual more aggressively.
    let progress_bias = 12.0 * (1.0 - progress) * norm_pr - 10.0 * progress * norm_pr;
    score += progress_bias;

    // Cubic coupling: residual squared times progress — dead space matters more later
    score += 6.0 * norm_pr * norm_pr * norm_pr * cap * progress;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - norm_pr;
    score -= 5.0 * tightness * tightness;

    // Lookahead: if next item could fit into post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_after = (pr - nxt) / cap;
            score -= 7.0 * (1.0 - fill_after);
        } else {
            // next item won't fit; penalize proportional to leftover dead space
            score += 4.0 * norm_pr * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 6.0 * open_norm * norm_pr;

    // Mean residual coupling: placing into a bin far from the mean residual
    // smooths the residual distribution, mildly rewarded
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate penalty: opening a fresh bin wastes capacity unless
    // post residual would be huge in every existing bin
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let residue_class = (post_residual % 10) as f64;
    let quotient_class = (post_residual / 10) as f64;

    // Dead space penalty: residuals that cannot accommodate common small items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class bonus: residuals that are multiples of 10 are more reusable
    if post_residual % 10 == 0 {
        score -= 15.0 + quotient_class * 0.5;
    } else {
        score += residue_class * 0.8; // penalize awkward remainders
    }

    // Fractional capacity coupling
    let frac = post_residual as f64 / cap;
    score -= 40.0 * (frac * std::f64::consts::PI).sin().abs();

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New bin candidate handling: only open when no open bin gives decent fit
    if bin_residual == bin_capacity {
        score += 90.0;
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
        // open new bin if mean residual across open bins is fragmented
        if mean_residual < 25.0 {
            score -= 40.0;
        }
        // early stream: prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
            // harmonic match: next item leaves another clean class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize large residuals slightly less
            score += 5.0;
        }
        // penalize leaving residual just below next item (near-miss dead space)
        if post_residual < next_item_size && post_residual + 5 >= next_item_size {
            score += 35.0;
        }
    }

    // Fragmentation guard: avoid spreading across too many bins
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer bins below mean residual to balance load
    score += 0.3 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (1..=10) are toxic dead space.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 2.0;
    } else if post_residual <= 20 {
        // Small-but-usable gaps: moderate penalty scaled by tightness.
        score += (20.0 - post_residual as f64) * 0.8;
    }

    // Reward very tight fits (post_residual near 0 handled above, but
    // also reward near-perfect packing explicitly).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if (post_residual as i64 - (bin_capacity as f64 * 0.5) as i64).abs() <= 2 {
        // Half-capacity residuals are awkward: mildly penalize.
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / 30.0).max(0.0);
            if slack <= 10 {
                score += 10.0; // would create new dead space next step
            }
        } else {
            // next item won't fit here anyway; slight bonus for leaving
            // a mid-size residual that other items may use.
            score -= 3.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual alignment: bins whose residual deviates from the mean
    // are either hoarders or nearly full; prefer near-mean residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the item is large relative to capacity or all
    // open bins would leave severe dead space.
    if bin_residual == bin_capacity {
        let base = score; // current computed score for the empty bin
        let large_item_bonus = if item_size > bin_capacity / 2 { 12.0 } else { 0.0 };
        let desperate = if fitting_bins_count <= 1 { 20.0 } else { 0.0 };
        score = base - large_item_bonus - desperate + 10.0;
        // Late in the stream, opening fresh bins is more acceptable.
        score -= progress * 5.0;
        let _ = fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_bonus = (bin_capacity as f64 - gap) * 0.9;
        score -= fit_bonus;

        // Perfect chain: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item slightly smaller than post_residual: still a good chain.
        else if next_item_size <= post_residual {
            score -= 15.0;
        }
        // Next item cannot fit: this bin's leftover is dead space relative to lookahead.
        else {
            score += 20.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual across open bins.
    let mean_post = mean_residual - item_size as f64;
    let dev = post_residual as f64 - mean_post;
    // Favor bins whose post-residual deviates from mean in a "tight" direction.
    score += 0.25 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins generally (small post_residual already does this).
    // Penalize leaving very small unusable slivers (< 10) unless next item matches.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual of a fresh bin is large, so add a mild penalty unless forced).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { -80.0 } else { 25.0 };
        score += pressure;
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Many open bins: encourage filling existing ones tighter.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let item_f = item_size as f64;

    // Exact fit: strongly reward closing a bin perfectly.
    if post_residual == 0 {
        score -= 6.0;
    } else if post_residual < 10 {
        // Tiny dead space is nearly unusable (min item size historically small);
        // penalize creating fragment residual.
        score += 5.0 - 0.5 * post_residual as f64;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item,
    // scaled by how snugly the next item fits.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual as f64 - next_f) / bin_capacity as f64;
            score -= 2.0 + 4.0 * snug;
        } else {
            // Next item won't fit here; slight penalty so bins that chain well win.
            score += 0.8;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids
    // opening a new bin — reward unless the fit is terrible.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 4.0 + 0.03 * post_residual as f64;
    }

    // New-bin candidate handling: opening a bin is expensive early and when many
    // bins are open; cheaper late in the stream. Penalize default opening.
    if is_new_bin {
        let mut open_penalty = 3.0 + 0.06 * open_bins_count as f64;
        open_penalty -= 4.0 * progress; // near the end, hoarding residual is fine
        // If existing bins are crowded (low mean residual), opening is more justified.
        if mean_residual < item_f {
            open_penalty -= 2.5;
        }
        // A fresh bin has perfect flexibility for the lookahead item.
        if next_item_size > 0 && next_item_size <= post_residual {
            open_penalty -= 1.0;
        }
        score += open_penalty.max(-2.0);
    }

    // Prefer bins tighter than the fleet average (concentrate filling).
    score += 0.04 * (bin_residual as f64 - mean_residual);

    // Mild preference for using bins with more accumulated fill (fewer bins touched).
    score += 0.01 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let nz = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    // Base: post residual, smoothed by non-linear coupling with stream progress
    let mut score = pr;

    // Polynomial penalty for wasted space, amplified late in the stream
    let waste = x * x * (1.0 + t * 3.0);
    score += 40.0 * waste;

    // Reward tight fits: smooth bump around small post residual
    let tight = (1.0 - x) * (1.0 - x) * (1.0 + t);
    score -= 30.0 * tight;

    // If next item fits into post residual, reward strongly (smooth interaction)
    let fits_next = if nz > 0.0 { (x - nz).max(0.0) } else { 0.0 };
    score -= 25.0 * fits_next * (1.0 + t * t);

    // Penalize leaving residual just below next item (dead space coupling)
    let dead = if nz > 0.0 && x > 0.0 && x < nz { (nz - x) / nz.max(1e-6) } else { 0.0 };
    score += 20.0 * dead * (1.0 + t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - x);
    }

    // New-bin candidate: mildly penalize opening new bins early, allow later
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - t) - 10.0 * t;
        // discourage new bin if an open bin fits nearly perfectly
        score += 8.0 * (1.0 - (mean_residual / cap).min(1.0));
    }

    // Mean residual coupling: prefer bins below mean residual (larger fill)
    score += 5.0 * (mean_residual - pr / cap * cap) / cap * (1.0 + t);

    // Open bins pressure: many open bins -> favor consolidation
    score += (open_bins_count as f64).ln() * 3.0 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers that are multiples of 10
    // or land in "usable" bands are more likely to absorb future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-10 class penalty: odd/awkward remainders create dead space.
    let m = post_residual % 10;
    score += match m {
        0 => -6.0,
        1 | 9 => 4.0,
        2 | 8 => 2.5,
        3 | 7 => 1.0,
        _ => 0.5,
    };

    // Integer-division thresholds on post_residual: band the leftover into
    // deciles and reward bands that historically pair with small items.
    let band = post_residual / 10; // 0..=10
    score += match band {
        0 => -10.0, // perfect fit
        1 => -5.0,
        2 => -2.0,
        3 | 4 => 0.0,
        5 | 6 => 1.0,
        _ => 2.0,
    };

    // Capacity-fraction coupling: how full will the bin be after placement?
    let fill_frac = 1.0 - post / cap;
    score -= 8.0 * (fill_frac * fill_frac); // reward high fill quadratically

    // Lookahead harmony: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 3.0; // divisible leftover: harmonic class match
            }
        } else {
            // next item cannot use the leftover at all: mild penalty scaled
            // by how much would be stranded.
            score += 0.05 * post;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // residuals are poor (large leftovers) or the fit here is very loose.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; mitigated when mean residual is high.
        score = 55.0 - 0.3 * mean_residual;
        // If no open bin even fits, the new bin is effectively forced cheap.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild global pressure: many open bins with low mean residual -> pack tighter.
    score += 0.02 * open_bins_count as f64;
    score -= 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the smallest plausible item are "dead".
    // Penalize unusable slivers super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 12.0;
    } else if post_residual < 20 {
        score += 15.0 + (20 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // Reward near-exact fits relative to residual (best-fit core with sharpening).
    if bin_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.8 {
            score -= 18.0 * (fit_ratio - 0.8);
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // next item cannot use the gap -> gap is likely dead
            score += 8.0;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize the new-bin candidate more when bins are already plentiful.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with open bins and stream progress.
        score += 30.0 + 6.0 * open_bins_count as f64 + 20.0 * progress;
        // But if all residuals are fragmented (high mean residual spread) and this
        // item is large, opening a fresh bin can be right; soften slightly.
        if item_size > 70 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild reward for reducing fragmentation vs mean.
        if (post_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Encourage using bins with small residuals first (shrink-to-fit).
        score += (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // next item fits; smaller leftover is better
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item does NOT fit; penalize dead space more when it's tiny
            let waste = post_residual as f64;
            score += waste * 0.8;
            if post_residual < 10 {
                score += 15.0; // nearly unusable sliver
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins with less residual (tighter fit)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * (0.3 + 0.2 * progress);

    // New-bin candidate: keep it neutral-ish so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Penalize wasted space if item barely fits (post_residual small but bin was large)
    if post_residual > 0 {
        let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += waste * 5.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 15.0;
    }
    // If next item would NOT fit in post_residual, mildly penalize fragmentation
    if next_item_size > 0 && next_item_size <= bin_capacity && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 0 {
        let fill_pressure = mean_residual / bin_capacity as f64;
        if bin_residual < bin_capacity {
            score -= fill_pressure * 10.0;
        }
    }

    // New-bin candidate handling: make empty bin less attractive unless nothing fits well
    if bin_residual == bin_capacity {
        // Base penalty so existing bins with decent fits win
        score += 40.0;
        // If item is large relative to capacity and few bins fit, new bin is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // Early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 20.0;
        }
        // If mean residual across open bins is low (they are all nearly full), new bin deserved
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 35.0;
        }
    }

    // Dynamic time horizon: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap; // fraction of bin filled after placement

    // Base: prefer small post-residual (tight fit), smoothly scaled
    let mut score = post * (1.0 + 0.5 * fill * fill);

    // Non-linear coupling: as stream progresses, penalize residual more strongly
    score += post * t * t * 0.8;
    score -= post * t * (1.0 - t) * 0.4;

    // Reward using bins that are already quite full (polynomial in fill)
    score -= fill * fill * fill * 12.0;

    // Penalty for leaving awkward residual relative to mean residual of open bins
    let diff = post - mean_residual;
    score += 0.15 * diff * diff / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * t;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in post-residual, reward heavily
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post {
            let tight = 1.0 - ((post - n) / cap).abs();
            score -= 8.0 * tight * tight;
        } else {
            score += 3.0;
        }
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.3 * (open_bins_count as f64) * t;

    // New-bin candidate handling: neutral-ish baseline with slight late-stream bias
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 15.0 * t - (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / cap;
    let harmonic_class = (frac * 10.0).floor() as i32; // 0..10 classes

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (or near them) are more likely to be filled later.
    let pr = post_residual;
    let mod_hits = ((pr % 10 == 0) as i32 + (pr % 20 == 0) as i32 + (pr % 25 == 0) as i32 + (pr % 50 == 0) as i32) as f64;
    score -= 15.0 * mod_hits;

    // Penalize awkward residuals (prime-ish / odd dead zones between 11 and 30)
    if pr > 10 && pr < 30 && pr % 5 != 0 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty scaled by wasted potential
            score += 10.0;
        }
    }

    // Integer-division threshold: residual class relative to typical small items
    let div_class = pr / 10; // 0..10
    score -= (10 - div_class as i32) as f64 * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current
    // open bins are very full or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64) * 5.0;
        let mean_fill = cap - mean_residual;
        let item_big = item_size as f64 > 0.6 * cap;
        let mut new_bin_penalty = 60.0 + open_pressure * 0.5;
        if item_big {
            new_bin_penalty -= 40.0;
        }
        if mean_residual < 15.0 {
            new_bin_penalty -= 50.0; // existing bins nearly full -> new bin fine
        }
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            new_bin_penalty += 30.0; // next item could use existing slack
        }
        score += new_bin_penalty * (0.5 + 0.5 * progress);
    }

    // Slight preference for tighter bins overall (best-fit flavor)
    score += (bin_residual as f64 - post_residual as f64).signum() * 0.0
        + (mean_residual - (bin_residual as f64)) * 0.05;

    // Harmonic class bonus: residuals in classes 0-1 (nearly full) are ideal
    if harmonic_class <= 1 {
        score -= 40.0;
    } else if harmonic_class >= 8 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space: can never fit a future item (min size 1..100 unknown, but
            // tiny gaps are likely wasted) -> strong penalty.
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * (1.0 + 0.5 * progress);
        if fitting_bins_count == 1 {
            score += 80.0; // don't open new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            // next item wouldn't fit here anyway; slightly less bad
            score -= 10.0;
        }
    }

    // Lookahead: bonus if the post residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Deviation from mean residual: prefer bins with residual close to item need.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward a post_residual that exactly fits the next item (perfect 2-step match)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain: this bin becomes exactly usable next step
        } else if post_residual > next_item_size {
            // partial credit: closeness of next item fit, scaled by leftover waste
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 / (1.0 + gap / 10.0));
        } else {
            // next item cannot fit here: penalize dead space relative to next item
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual near the mean (balanced packing),
    // penalize bins that deviate strongly (fragmented outliers).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (small post_residual)
        score -= 8.0 * (1.0 - pr / bin_capacity as f64);
    }

    // New-bin candidate: only open a new bin when current fit is terrible
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: slightly above a perfect-fit open bin
        score = 55.0 + 0.1 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // empty bin fits next item too
        }
    }

    // Late-stream pressure: as the stream progresses, be greedier about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Many open bins: discourage opening more bins
    score += 0.5 * open_bins_count as f64 * (if bin_residual == bin_capacity { 1.0 } else { 0.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless fit is bad
    if bin_residual == bin_capacity {
        // Baseline penalty for wasting a fresh bin; reduced when current fit is poor
        score += 35.0;
        // If no open bin fits well, allow opening a new bin
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If mean residual across open bins is large, opening new bin is wasteful
        score += mean_residual * 0.3;
    }

    // Prefer bins with residual close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * gap;

    // Mild load-balancing: prefer bins with below-mean residual to keep spread usable
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Slight preference for fewer open bins early on
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress
    let progress_w = 8.0 * t * (1.0 - t) + 2.0 * t * t;
    score += progress_w * 20.0 * pr_norm * pr_norm;

    // Penalize residuals too small for the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (next_norm - pr_norm).max(0.0);
        score += 15.0 * gap * gap * cap;
        // Reward residuals that still fit the next item
        let fit_bonus = (1.0 - (pr_norm - next_norm)).max(0.0);
        score -= 10.0 * fit_bonus * pr_norm * (1.0 - t);
    }

    // Reward tight fits (small post_residual relative to item)
    score -= 12.0 * item_norm * (1.0 - pr_norm);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // New-bin candidate: prefer it only when post_residual is large and bins are many
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 18.0 * openness * (1.0 - item_norm) * (1.0 + t);
        score -= 5.0 * (1.0 - openness);
    }

    // Mild attraction toward bins whose residual is close to the mean (balance)
    let dev = (pr_norm - mean_norm).abs();
    score += 6.0 * dev * dev * cap * (0.5 + 0.5 * t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if pr == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals in awkward "harmonic" classes that
    // most future items cannot fill (tiny slivers).
    if pr > 0 && pr < 10 {
        score += 18.0;
    }
    // Modulo-class shaping: residuals just below common item sizes
    // (e.g. 51..59, 76..79) are hard to reuse; penalize those bands.
    if pr >= 51 && pr <= 59 {
        score += 6.0;
    }
    if pr >= 76 && pr <= 79 {
        score += 4.0;
    }
    // Residuals in friendly classes (multiples of 10-ish zones) reuse well.
    if pr >= 10 && pr <= 30 && pr % 10 == 0 {
        score -= 4.0;
    }

    // Lookahead (k=2): reward if next item fits into the post-residual.
    if next_item_size > 0 {
        if (pr as u64) >= next_item_size as u64 {
            score -= 10.0;
        } else {
            // Next item won't fit here: penalize proportionally to wasted space.
            score += next_item_size as f64 * 0.25;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // General tightness reward: fraction of capacity consumed.
    score -= (1.0 - pr as f64 / cap) * 6.0;

    // Slight pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;
    score -= (mean_residual - pr as f64).max(0.0) * 0.05;

    // New empty bin candidate: default is unattractive; only beat open bins
    // when the current fit is poor (large post-residual waste) or when this
    // is a forced last chance but the fit is still bad.
    if bin_residual == bin_capacity {
        score = 45.0 + item_size as f64 * 0.3;
        // Attractive to open a new bin for very large items (they pack cleanly).
        if item_size >= 60 {
            score -= 20.0;
        }
        // If next item pairs well with what remains, opening is even better.
        if next_item_size > 0 && (pr as u64) >= next_item_size as u64 {
            score -= 6.0;
        }
        // Never open a new bin when a decent existing fit exists:
        // make it lose unless the best alternative would leave >40 waste.
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
        // Early in the stream, opening bins is cheap and builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (small gaps that few items can ever fill) are heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (post residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is highly desirable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Partially usable residual is fine; penalize only mild waste.
            score -= 5.0;
        } else {
            // Next item cannot use the residual: it becomes dead space.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins
    // are crowded and the current fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        score += 20.0 - pressure * 5.0;
        if (item_size as f64) > mean_residual * 0.9 && open_bins_count > 2 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // (higher utilization) rather than spreading items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    // Slight preference for bins with residual close to the item (tight fit).
    score += (bin_residual - item_size) as f64 * 0.1;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already well packed; reward finishing it off.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves more waste: mild penalty proportional to gap
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use this residual: penalize large leftover less if residual is small
            score += 0.3 * post_residual as f64;
        }
    }

    // Penalize post_residual that is too small for typical items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins whose residual is below mean residual (tighter packing)
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: mildly discouraged unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * mean_residual;
    }

    // Late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (low post residual) more strongly over time.
    score -= (bin_capacity as f64 - post_residual as f64) * (0.2 + 0.8 * progress) * 0.5;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < item_size.min(40) {
        score += 8.0 * (40.0 - post_residual as f64) / 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Many open bins: prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += crowding * (mean_residual - post_residual as f64).abs() * 0.3;

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty for creating awkward residue.
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate logic: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity as f64 - mean_residual) >= item_size as f64 * 0.5;
        if good_fit_exists {
            score += 60.0; // discourage opening a new bin when decent fits exist
        } else {
            score -= 15.0 + 10.0 * (1.0 - progress);
        }
        // Scale new-bin appeal with how many bins are already open.
        score += open_bins_count as f64 * 0.5;
    }

    // Slight preference for bins with residuals close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // Small stochastic-free tie-breaker using step parity-free deterministic jitter.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mean_gap = mean_residual - pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, compacting residual space matters more.
    let w = 0.6 + 1.4 * progress;
    score += w * norm_pr * norm_pr * cap * (1.0 + 0.5 * progress);

    // Reward tight fits via smooth quadratic interaction between item and residual.
    score -= 3.0 * norm_item * (1.0 - norm_pr) * cap;

    // Penalize divergence from the mean residual (keeps bins homogeneous).
    score += 0.15 * mean_gap * mean_gap / cap;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * progress;
    }

    // Lookahead coupling: smooth reward if the next item fits the post-residual.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let slack = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 2.0 * fits_next * slack * (1.0 - progress);
    }

    // Mild penalty for bin proliferation early in the stream.
    score += 0.05 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        score -= 1.0 + 3.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and "harmonic" leftovers
    // (residuals that combine well with common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Modulo classes: residuals that are multiples of small common sizes
    // (10, 20, 25, 50) are more likely to be filled later.
    let harmonic_bonus = |r: u32| -> f64 {
        if r == 0 { 60.0 }
        else if r % 50 == 0 { 40.0 }
        else if r % 25 == 0 { 25.0 }
        else if r % 20 == 0 { 20.0 }
        else if r % 10 == 0 { 12.0 }
        else if r % 5 == 0 { 6.0 }
        else { 0.0 }
    };
    score -= harmonic_bonus(post_residual);

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - tight / cap);
        } else {
            // next item cannot use this residual: penalize large dead space
            score += 0.15 * pr;
        }
    }

    // Integer-division threshold on residual fraction of capacity.
    let frac = pr / cap;
    if frac < 0.05 {
        score -= 20.0; // bin nearly full, good to close it out
    } else if frac > 0.5 {
        score += 10.0 * frac; // leaving more than half a bin empty is wasteful
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (large mean residual mismatch) or early in the stream.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins when existing residuals are small (tight bins)
        score += 40.0 + 0.5 * mean_residual - 20.0 * progress;
        let _ = spread;
    }

    // Prefer bins tighter than the mean (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild pressure to keep the number of open bins low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item almost fits (small miss), slight penalty for wasting the gap.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (next_item_size - post_residual as u32) <= 10 {
        score += 6.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening unless current bins are quite full.
        score += 20.0 + pressure;
        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
    } else {
        // Reward placing into bins that are below mean residual (balancing toward fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        score -= pressure * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 60.0 * (1.0 - (diff as f64 / 50.0).min(1.0)).powi(3);
        // exact match bonus
        if diff == 0 {
            score -= 40.0;
        } else if diff <= 5 {
            score -= 15.0;
        }
        // penalize leaving space too small for next item (dead space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: minimize residual directly (already done)
        score -= 20.0;
    }

    // Prefer bins tighter than the mean (best-fit bias)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless item is huge relative to residual
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow opening a new bin early in stream when many bins already open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // if item nearly fills a fresh bin, opening is fine
        if item_size >= 80 {
            score -= 45.0;
        }
    }

    // mild preference for compacting many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly favored.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 6.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // penalize leaving a residual that just barely blocks the next item
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize creating tiny dead space (< 10 units of smallest item) more harshly.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Global state: when many bins are open, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 3.0 * open_pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be more willing to open fresh bins (mild penalty
    // for using a nearly-full bin); late in stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= 4.0 * (1.0 - progress);
        score += 5.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Mean residual anchor: prefer bins whose residual is below mean (tighter bins)
    // to keep a pool of large residuals available.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 2.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate larger residuals (favor spreading). Late: penalize dead space strongly.
    let prog_sq = progress * progress;
    let prog_cub = prog_sq * progress;
    let dead_space_penalty = norm_pr * norm_pr * (2.0 + 6.0 * prog_cub) * cap;
    score += dead_space_penalty;

    // Reward tight fits with a smooth cubic in item size, modulated by progress.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * tightness * (8.0 + 10.0 * prog_sq) * cap;

    // Smooth interaction: if lookahead item can use the post-residual, reward this bin.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        let gap_norm = gap / cap;
        let fit_quality = 1.0 - gap_norm;
        if fit_quality > 0.0 {
            score -= fit_quality * fit_quality * (6.0 + 8.0 * progress) * cap;
        } else {
            // Post-residual too small for lookahead: penalize smoothly.
            score += (-fit_quality) * (-fit_quality) * 2.0 * cap;
        }
    }

    // Last-chance bonus: only one fitting bin; avoid forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 * cap * (1.0 + progress);
    }

    // New-bin candidate: mildly discourage early, more acceptable when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += cap * (1.5 - 2.0 * fragmentation) * (1.0 - 0.5 * prog_cub);
        if open_bins_count == 0 {
            score -= 10.0 * cap;
        }
    }

    // Smooth preference toward bins with residuals near mean (balanced packing).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 2.0 * cap * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue classes.
    let class = (post_residual % 10) as f64;

    // Dead-space penalty grows when post_residual falls into "unusable" classes.
    // Residues 1..9 (mod 10) with small value are hard to fill by any future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Harmonic alignment: post_residual divisible by 10 or 20 is more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Integer-division thresholds: how many "typical" items (10..80 buckets) fit.
    let fits_small = post_residual / 10;
    let fits_mid = post_residual / 25;
    if fits_small == 0 && post_residual > 0 {
        score += 12.0; // truly dead space below smallest item
    }
    if fits_mid >= 2 {
        score -= 3.0; // roomy bin, good target
    }

    // Lookahead coupling: next item fits harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or leaves a harmonic class residue
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
            if next_post == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize slightly less if class is reusable
            score += class * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current bin's
    // post_residual would be a bad harmonic class and stream is early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // fresh bin: base score is full capacity; adjust with occupancy pressure
        score -= 30.0 * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
        if mean_residual < 20.0 && open_bins_count > 3 {
            score -= 5.0; // open bins nearly full, new bin sensible
        }
    } else {
        // existing bin: reward tight fits relative to capacity fraction
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * frac;
        score += 0.2 * (open_bins_count as f64).sqrt();
    }

    // Mean-residual coupling: prefer bins deviating from mean toward fullness.
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Small class-based tiebreaker jitter (deterministic).
    score += class * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space severity: gap too small for typical items (<= 10) is waste.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else {
            // Larger gaps are more reusable; mildly reward larger usable gaps.
            score -= (post_residual as f64).ln() * 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 120.0;
    }

    // Coupling: dead space penalty scales with pressure from open bins count.
    let pressure = (open_bins_count as f64).sqrt();
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * pressure;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: make it unattractive unless current bin would leave bad waste.
    if bin_residual == bin_capacity {
        // Fresh bin baseline; slight preference early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // Penalize new bin more when many bins are open (consolidation pressure).
        score += 8.0 * pressure;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the known next item: penalize proportionally.
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Mean residual alignment: prefer bins near the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward if next item fits into post_residual exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.5 * slack; // perfect lookahead match strongly favored
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to wasted potential
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste;
    }

    // Penalize post_residual that is small-but-unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare residual against mean residual across open bins
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Early in stream: be more conservative (prefer tight fits), later: allow spreading
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening new bins when many bins are already open and fit exists
    if bin_residual == bin_capacity {
        let base = 12.0 + 2.0 * open_bins_count as f64;
        score += base * (1.0 - 0.5 * progress);
        // opening new bin is fine if lookahead item would also fit nicely
        if next_item_size > 0 && (bin_capacity - next_item_size) >= item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            // Lookahead item fits perfectly or nearly: big reward.
            let gap = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space that the next item cannot use.
            score += 6.0 + 0.08 * post_residual as f64;
        }
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.05 * item_size as f64;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // residuals are fragmented and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bins mildly; the penalty shrinks when open bins are fragmented
        // or the item is huge relative to typical residual.
        let mut new_bin_penalty = 12.0
            - 0.15 * open_bins_count as f64
            - 0.04 * fragmentation
            - 6.0 * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, prefer closing out existing bins.
        new_bin_penalty += 8.0 * progress;
        if next_item_size > 0 && next_item_size > mean_residual {
            // Next item won't fit typical bins anyway; a fresh bin absorbs both.
            new_bin_penalty -= 5.0;
        }
        score += new_bin_penalty.max(-20.0);
    }

    // Mild preference for bins below the mean residual (consolidate emptier bins
    // so fuller ones stay flexible for large items).
    if bin_residual < bin_capacity {
        score += 0.03 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_n = pr / cap;
    let mean_n = if cap > 0.0 { mean_residual / cap } else { 0.0 };

    // Base: post residual, with smooth non-linear penalty on tiny residuals (dead space)
    let mut score = pr - 18.0 * (1.0 - pr_n) * (1.0 - pr_n) * (1.0 - pr_n);

    // Perfect fit reward (smooth, quadratic coupling with stream progress)
    let fit_quality = 1.0 - pr_n;
    score -= 10.0 * fit_quality * fit_quality * (1.0 + t);

    // Stream-progress coupling: tighten preference for tight fits later in stream
    score += 8.0 * pr_n * pr_n * (1.0 - t);

    // Mean residual interaction: avoid leaving residual far from mean (keeps bin family coherent)
    let dev = pr_n - mean_n;
    score += 6.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + fit_quality);
    }

    // Lookahead: penalize leaving residual slightly too small for next item (wasted space)
    if next_item_size > 0 && (next_item_size as f64) > pr {
        let gap = next_item_size as f64 - pr;
        score += 4.0 * (gap / cap) * (gap / cap);
    } else if next_item_size > 0 {
        // reward residual that can still host next item
        score -= 3.0 * (pr / (next_item_size as f64 + 1.0)).min(1.0);
    }

    // Many open bins: prefer consolidating (mild penalty for spreading)
    if open_bins_count > 4 {
        score += 0.4 * (open_bins_count as f64).ln() * pr_n;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // --- Tight-fit rewards (harmonic classes of post_residual) ---
    if post_residual == 0 {
        score -= 70.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Harmonic class discount: residuals aligned to decade boundaries are
    // statistically more reusable by mid-sized items.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Odd/awkward residuals (modulo 3 == 1) tend to become dead space.
    if post_residual % 3 == 1 && post_residual > 0 {
        score += 4.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= ni {
            // Next item can land here: chain placement is valuable.
            score -= 10.0 + 0.15 * ni;
            if (pr - ni) <= 5.0 {
                score -= 10.0; // near-perfect two-step packing
            }
        } else {
            // Residual too small for the lookahead item: dead space risk.
            score += 8.0 + 0.25 * (ni - pr);
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
        // If the leftover would be large anyway, using this bin is even better.
        if post_residual >= 30 {
            score -= 10.0;
        }
    }

    // --- New-bin candidate penalty (discourage bin proliferation) ---
    if is_new_bin {
        score += 18.0
            + 0.35 * mean_residual          // open bins still have room
            + 2.0 * open_bins_count as f64 * (1.0 - progress).min(1.0);
        // Late in the stream, opening a bin is less costly structurally.
        score -= 12.0 * progress;
        // A new bin is acceptable if the item is huge and would leave
        // awkward crumbs anywhere else.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // --- Fragmentation guard: tiny unusable crumb with big lookahead ---
    if !is_new_bin && post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps that no
    // realistic item (min size 1..100 stream) can reliably fill.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap); // tiny gaps are dead space
        } else if gap < 25.0 {
            score += 15.0 * (25.0 - gap) / 15.0; // moderately awkward gaps
        }
        // Large residual is fine; mild reward proportional to gap.
        score -= 0.05 * gap;
    }

    // If the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }
    // If next item is bigger than post residual but small enough that the
    // gap becomes dead space, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new bins; penalize the new-bin candidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure.
        score += 30.0 + pressure * 2.0;
        // If no open bin fits well, opening is fine: reduce penalty when
        // fitting bins are scarce.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        score -= pressure * 0.3;
        // Prefer bins whose residual deviates most from mean (fill laggards).
        score += 0.1 * (bin_residual as f64 - mean_residual).abs().signum()
            * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            // leftover after the next item would also fit here later
            let after = post_residual - next_item_size;
            score -= 12.0 - (after as f64).min(12.0);
            if after <= 5 {
                score -= 10.0; // near-perfect chain
            }
        } else {
            // next item cannot use this bin's leftover: dead space risk
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Reward tight fits relative to residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 20.0;

    // Penalize small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (consolidate space).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when nothing fits well and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = if next_item_size > 0 && post_residual_check(post_residual, next_item_size) { 1.0 } else { 0.0 };
        score = 70.0 + 30.0 * (1.0 - progress) - 20.0 * poor_fit - (item_size as f64) * 0.2;
        if fitting_bins_count == 1 {
            score += 60.0; // an open bin is the last chance: don't open new
        }
    }

    score
}

#[inline]
fn post_residual_check(post_residual: u32, next_item_size: u32) -> bool {
    next_item_size > post_residual
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual reduces score for near-full placements.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new bins (bin_residual == bin_capacity) progressively as stream advances,
    // unless the fit is terrible in open bins anyway.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 12.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 10.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving awkward residuals.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Global state: prefer filling bins below mean residual (consolidating space).
    if !is_new_bin {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // Penalize creating small dead space that likely wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let base = pr;

    // Smooth non-linear coupling: waste grows super-linearly with residual, modulated by stream progress
    let mut score = base
        + 18.0 * pr_norm * pr_norm * (0.5 + t)
        - 8.0 * pr_norm * (1.0 - t);

    // Reward tight fits smoothly (small post_residual)
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 14.0 * tightness * (0.6 + 0.4 * t);

    // Penalize dead space relative to next item lookahead
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0);
        let unusable = 1.0 - (fit_next / pr.max(1.0));
        score += 10.0 * unusable * pr_norm * (1.0 - t);
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * (1.0 - t);
    }

    // New-bin candidate handling: mildly penalize opening new bins early, more late
    if bin_residual as f64 == cap {
        score += 12.0 * (1.0 - t) + 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mean residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild open-bin pressure to consolidate
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes (or leaving nice fractions of capacity) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Divisibility rewards: residual that is a multiple of small sizes is
        // more likely to be filled exactly by future items.
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 4.0; }
        if pr % 20 == 0 { bonus += 3.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr % 50 == 0 { bonus += 4.0; }
        score -= bonus;

        // Integer-division class: how many "medium" items (size ~25) fit.
        let fits25 = pr / 25;
        score -= fits25 as f64 * 1.5;

        // Dead-space penalty for tiny unusable slivers.
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }
    } else {
        // Perfect fill: strongly reward closing the bin exactly.
        score -= 25.0;
    }

    // Fractional capacity coupling: prefer post_residual near harmonics of
    // capacity (1/4, 1/2, 3/4).
    let frac = post_residual as f64 / cap;
    let harmonics = [(0.0f64, 6.0), (0.25, 3.0), (0.5, 4.0), (0.75, 2.0)];
    let mut hbonus = 0.0;
    for (h, w) in harmonics.iter() {
        let d = (frac - h).abs();
        if d < 0.06 {
            hbonus += w * (1.0 - d / 0.06);
        }
    }
    score -= hbonus;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            let new_pr = pr - next_item_size;
            if new_pr % 10 == 0 { score -= 5.0; }
            if new_pr < 10 { score += 4.0; }
        } else {
            // Next item won't fit here; mild penalty scaled by overflow gap.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 18.0
            - fragmentation * 0.3
            - (open_bins_count as f64).sqrt() * 2.0
            - progress * 5.0;
        if pr == 0 { score += 0.0; }
        // Penalize new bin more when a decent fit exists elsewhere.
        if post_residual as f64 >= mean_residual { score += 6.0; }
    } else {
        // Mild preference for bins tighter than the mean (best-fit flavor).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1..100, but typical
    // items are >= 10) can reuse are worthless. Penalize tiny unusable gaps hard.
    if post_residual > 0 {
        // gap below ~10 is almost surely dead space
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual <= 30 {
            score += 5.0;
        }
    }

    // Reward tight fits: residual nearly consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it over
    // opening a new bin (avoids wasting an existing opportunity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead synergy: if next item fits in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item almost fits (small gap), slight reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score -= 4.0;
    }
    // Penalize if next item cannot fit but a fresh bin would serve it well.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than opening new ones; new empty bin gets a penalty.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // but if all open bins would leave terrible dead space, allow new bin
        if fitting_bins_count > 0 {
            let worst_case_gap = (bin_capacity as f64 - mean_residual).min(100.0);
            if worst_case_gap < 10.0 {
                score -= 30.0;
            }
        }
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 10.0; // big next item: fresh bin is valuable
        }
    } else {
        // Mild preference for bins with smaller residuals (tighter packing).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs().signum() * (bin_residual as f64 - mean_residual);
    }

    // Early in stream: be slightly more willing to open bins (build diverse
    // residual set); late in stream: consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    } else {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
