pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // Penalize small dead space more than proportionally (non-linear waste).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well. Penalize the fresh bin mildly so tight fits in open
    // bins win, but let it win over bad fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening bins is cheaper than leaving fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 3.0; // creates likely dead space for the next item
        }
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual < item_size as f64 {
        score -= 4.0;
    }

    // Prefer placing into bins whose residual is close to mean residual (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 + 2.0 * progress);
    score -= 18.0 * poly;

    // Penalize large dead space that shrinks with progress (late bins should be tight)
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + 2.0 * progress);
    }

    // New-bin candidate: penalize mildly unless post_residual is large and early
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * (1.0 - progress);
        score = score - 8.0 * early_bonus + 5.0 * (1.0 - early_bonus) + 0.05 * open_bins_count as f64;
    }

    // Lookahead coupling: reward bins whose post residual could host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 7.0 * (1.0 - (pr - ni) / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 3.0 * (mean_residual - pr / 1.0) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Exact / near-exact fit: strongly reward (harmonic class 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 + (5 - post_residual) as f64 * 40.0;
    }

    // Harmonic classes on post_residual: dead-space classes
    // residuals in (0,10] are nearly useless; 10..=30 usable for small items
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 - post_residual as f64 * 8.0; // tiny slivers penalized
    }

    // Fraction-of-capacity coupling: post_residual / capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 60.0; // large leftover fraction penalized mildly (waste)
    score -= (1.0 - frac) * 20.0; // reward tight fills

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + slack.min(30.0); // reward bins that can host the next item too
            if post_residual == next_item_size {
                score -= 150.0; // perfect chain
            }
        } else {
            // next item won't fit here: penalize proportionally to how close
            let miss = (next_item_size - post_residual) as f64;
            score += miss.min(50.0) * 0.8;
        }
    }

    // Last-chance bin: only bin that fits the item
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 200.0;
    }

    // Many open bins: prefer consolidating into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 10.0 * (1.0 - progress);

    // Mean residual coupling: bins below mean residual are "emptier" -> less attractive
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // New-bin candidate handling: default mild penalty so good fits beat it,
    // but attractive when item is large relative to open residuals.
    if is_new_bin {
        let openness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 90.0 - big_item * 80.0 + openness * 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        if fitting_bins_count <= 1 {
            score -= 100.0; // no real alternative: open new bin
        }
    }

    // Integer-division threshold on post_residual classes
    let class = post_residual / 10; // 0..10 harmonic decile
    score += match class {
        0 => 0.0,
        1 => -5.0,
        2 => 0.0,
        3 => 5.0,
        4 => 10.0,
        5 => 15.0,
        _ => 20.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
