    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 3.0;

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: neutral-ish baseline with slight penalty so it's chosen
    // only when open bins create large dead space.
    if bin_residual == bin_capacity {
