    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, be more conservative: discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual would be tiny (near-perfect fit)
        score += 25.0 - 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        if progress > 0.8 { score += 10.0; }
    }

