    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; mild penalty scaled by wasted capacity.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Cheaper to open a new bin early in the stream (long horizon ahead).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many open bins have large mean residual, prefer reusing them.
        score += 0.15 * mean_residual;
        // If no open bin fits well (post_residual huge waste elsewhere), new bin more attractive.
        if post_residual >= item_size && fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Slight preference for fuller bins (best-fit-like behavior).
        score += 0.1 * (bin_capacity as f64 - bin_residual as f64) * -1.0;
        // Encourage consolidation when many bins are open.
        score -= 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Discard tiny useless remnants harder as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 5 {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - norm_pr);
    score -= 40.0 * coupling * (0.5 + progress);
    score -= 25.0 * coupling * coupling;
    // Penalize large wasted residual as stream advances
    score += 10.0 * norm_pr * norm_pr * progress;
    // Reward tight fits more strongly late in the stream
    let tight = 1.0 - norm_pr;
    score -= 15.0 * tight * tight * (1.0 - progress);
    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }
    // Slight penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }
    // Lookahead: favor bins whose post residual matches next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "nice" fractions of capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fill reward: post_residual == 0 is perfect
    if post_residual == 0 {
        score -= 500.0;
    }

    // Class-based dead-space penalty: residuals that are hard to fill later
    // (small residuals < 10 are dead space; mid residuals near 10..30 are risky)
    if pr > 0.0 && pr < 10.0 {
        score += 25.0;
    }

    // Harmonic classes: residuals divisible by common item sizes are reusable
    let classes: [u32; 6] = [10, 20, 25, 40, 50, 100];
    let mut reusable = false;
    for c in classes.iter() {
        if post_residual > 0 && post_residual % c == 0 {
            reusable = true;
            break;
        }
    }
    if reusable {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize proportional to leftover waste after next
            let after_next = post_residual - next_item_size as f64;
            score -= 20.0 - 0.2 * after_next;
        } else {
            // next item won't fit here: mild penalty for tight fills
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling bins with low residual relative to mean (best-fit sharpening)
    score -= 0.5 * (mean_residual - pr);

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // empty bin: baseline score; make it unattractive unless post_residual waste is high
        // a new bin has post_residual = capacity - item_size
        let waste_open = (post_residual as i64).abs();
        score += 40.0 - (waste_open as f64).min(40.0);
        // early in stream, new bins are cheaper to open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    } else {
        // existing bin: reward reuse, more so when many bins are open
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Tight fit bonus: item nearly fills the bin
    let tightness = 1.0 - (pr / cap);
    score -= 10.0 * tightness * tightness;

    // Small modulo-harmonic tiebreak on post_residual
    score -= match post_residual % 7 {
        0 => 1.5,
        3 | 5 => 0.5,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: small unusable gaps are the worst outcome ---
    if post_residual > 0 {
        if post_residual <= 10 {
            // tiny gap: nearly always dead space -> heavy penalty
            score += (11.0 - post_residual as f64) * 60.0;
        } else if post_residual <= 20 {
            // small gap: likely dead unless a tiny item arrives
            score += (21.0 - post_residual as f64) * 12.0;
        } else if post_residual >= 30 && post_residual <= 60 {
            // mid gap: reusable by the broadest item range -> mild reward
            score -= 15.0;
        } else if post_residual >= 61 {
            // large residual: flexible, but wasteful if item was small
            score -= 5.0;
        }
    } else {
        // perfect fit: maximal reward
        score -= 200.0;
    }

    // --- Tightness reward: fraction of bin consumed by this placement ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // --- Last-chance pressure: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // base cost of opening a bin; acceptable only if fits elsewhere are bad
        score += 40.0;
        // opening a fresh bin is attractive early (many future items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 55.0;
        // many open bins -> discourage opening even more
        score += (open_bins_count as f64).min(20.0) * 4.0;
    }

    // --- Open-bins pressure: prefer reusing bins when many are open ---
    score += (open_bins_count as f64).min(15.0) * 1.5;

    // --- Lookahead (k=2): reward bins whose post_residual matches next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 90.0; // next item fits almost perfectly
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the known next item
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // --- Mean-residual coupling: avoid leaving this bin far from the pack average ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Exact chain: item fills residual now, next item fills the remainder.
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        }
    }

    // Reward tight fits now (small dead space relative to capacity).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize creating unusable slivers (post residual small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (consolidate space).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: keep it expensive, but cheaper late in the stream
    // or when many bins are open (accepting poor fits becomes costly).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress - 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post placement residual (lower is tighter, but very small residuals are dead space)
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever host a typical item are wasted.
    // Items >= 10 traditionally, but interface allows 1..100, so penalize residuals < ~12 heavily.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0 * (12.0 - post_residual as f64) / 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward (subtract) to prioritize exact closures.
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to how badly it misses.
        score += 5.0 * ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Fill-level reward: bins that are already heavily used should be preferred
    // (consolidate load into few bins).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio * fill_ratio;

    // Time horizon: early in the stream, be more willing to open new bins (keep options
    // open); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage consolidating
    // into existing bins rather than opening more.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin; reduced early in the stream, increased
        // when other bins already fit the item (fitting_bins_count > 1 means other
        // options exist since this candidate is not counted as a fitting open bin).
        let mut new_bin_cost = 30.0;
        if fitting_bins_count == 1 {
            new_bin_cost += 25.0; // a real bin fits; only open new bin if that fit is terrible
        }
        if next_item_size > 0 && next_item_size >= 50 {
            new_bin_cost -= 10.0; // big upcoming item: fresh bin preserves capacity
        }
        score += new_bin_cost * (1.0 - 0.5 * progress);
        // Penalize opening new bins when existing bins have plenty of room.
        if mean_residual > 40.0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Tightness reward: strongly favor bins where item fills most of the residual.
    let tightness = 1.0 - (pr / cap);
    score -= 6.0 * tightness * tightness * (1.0 + 2.0 * progress);

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 18.0 * dead * dead;

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 3.0 * (1.0 - ((pr - nxt) / cap)) * (0.5 + progress);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for consolidating into bins below mean residual (filling emptier bins).
    score += 0.5 * ((mean_residual - bin_residual as f64) / cap).max(0.0);

    // New-bin candidate: penalize opening bins, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    // Smooth open-bin pressure: with many open bins, prefer existing bins.
    score -= (open_bins_count.min(20) as f64) * 0.15 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 act as dead-space classes
    let res_class = post_residual % 10;
    score -= (10 - res_class) as f64 * 0.8; // reward residuals that sit near a "clean" class boundary

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit: post_residual smaller than the smallest plausible item is dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // wasted lookahead: penalize proportionally to overshoot
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
        // harmonic check: next_item_size class matches capacity fractions
        let next_frac = (next_item_size * 4) / bin_capacity; // 0..4 quarters
        let post_frac = (post_residual * 4) / bin_capacity;
        if next_frac == post_frac && post_frac >= 1 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual > 50 {
            score += 10.0; // opening a bin for a small item wastes capacity
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        // early stream: prefer filling bins before opening new ones
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Integer-division threshold on post_residual: bins left with <=20 are "closable"
    if post_residual <= 20 && post_residual > 0 {
        score -= 6.0;
    }

    // Penalize leaving residuals in awkward mid-range (30..45) that few items fit
    if post_residual > 30 && post_residual < 45 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a plausible
    // item are heavily penalized (items are >= 1, but small gaps < 12 are nearly
    // unusable in practice; gaps below next_item_size are dead for the lookahead).
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 4.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward tight relative fit (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * (0.5 + progress);

    // New-bin candidate: only attractive when this item is huge relative to
    // typical residuals or no good fits exist.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 0.0 && fitting_bins_count > 1 {
            score += 12.0 + mean_gap * 0.3;
        } else {
            score += 3.0;
        }
        // Late in the stream, keep consolidating into open bins.
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small residual penalty: dead space that likely can't be used
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize, worse if post_residual is small dead space
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare residual to mean residual across open bins
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins open
        score += 30.0 + 50.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_residual / 2 {
            // large next item: fresh bin less bad
            score -= 20.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (nothing 1..100 can ever fill it well)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0 - post_residual as f64;
    }

    // Reward tight fits (small post_residual) more aggressively
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap < 5 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    }
    // If next item would be blocked by the leftover, mild penalty
    if next_item_size > post_residual && post_residual < 10 {
        score += 4.0;
    }

    // New-bin candidate handling: prefer new bin when item is large relative
    // to capacity or when open bins are mostly full (mean residual small)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / bin_capacity as f64;
        // New bin attractive if item big, few fitting bins, or late in stream
        score -= 6.0 * (item_size as f64 / bin_capacity as f64);
        score -= 5.0 * progress;
        score -= 8.0 * (1.0 - openness.min(1.0));
        // Discourage hoarding many bins early
        score += (open_bins_count as f64).sqrt() * 1.5;
    } else {
        // Slight preference for fuller bins (close them out)
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * fill;
        // If many bins can fit, mild penalty to keep diversity of residuals
        if fitting_bins_count > 2 {
            score += 1.5;
        }
    }

    // Global pressure: when mean residual is low, conserve space harder
    score += 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * t * t);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 25.0 * t);

    // Penalize dead space (small unusable residuals) with smooth cubic term
    let dead = if x < 0.15 { (0.15 - x) / 0.15 } else { 0.0 };
    score += dead * dead * dead * 30.0 * (1.0 + t);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = ((x - nx) / x.max(0.001)).max(0.0).min(1.0);
        score -= fit * 12.0 * (1.0 - t);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - t);
    }

    // New-bin candidate: smooth penalty scaled by open bins and mean residual
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits strongly (non-linear).
    score -= (bin_residual as f64 - item_size as f64).abs().powi(2) * 0.01;

    // Harmonic class of post_residual: small leftovers are "dead space".
    // Class 0: post_residual == 0 (perfect). Class 1..3: nearly unusable.
    let pr = post_residual;
    let dead_penalty = match pr {
        0 => -40.0,
        1..=3 => 25.0 + (4 - pr) as f64 * 5.0,
        4..=9 => 12.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Modulo-arithmetic classes: residuals that are multiples of common
    // item-size blocks (e.g. multiples of 10 or 25) are more reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 20 == 0) {
        score -= 8.0;
    }
    // Odd, prime-ish residuals are less reusable.
    if pr > 0 && pr % 2 == 1 && pr < 50 {
        score += 6.0;
    }

    // Integer-division thresholds: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Great: lookahead item fits here too.
            score -= 10.0 + (pr - next_item_size) as f64 * 0.3;
            // Exact pairing bonus.
            if next_item_size == pr {
                score -= 15.0;
            }
        } else {
            // Lookahead won't fit: penalize leaving a mid-sized orphan gap.
            let gap_class = pr / (next_item_size.max(1));
            score += (gap_class as f64) * 2.0;
            if pr < next_item_size && pr > 10 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is costly; make the empty
    // bin attractive only when open bins are scarce or this is a big item
    // that would leave a bad gap elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if open_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / cap) > 0.6;
        let poor_fit = fitting_bins_count >= 1 && (bin_capacity - bin_residual) == bin_capacity && post_residual > 0 && next_item_size > post_residual;
        // Base cost of a new bin.
        score += 35.0;
        if scarcity > 0.0 {
            score -= 60.0;
        }
        if big_item {
            score -= 10.0;
        }
        if poor_fit {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper (more items to fill them).
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference to balance load across many open bins.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Penalize leaving gaps just below the next item size (near-miss waste),
    // reward gaps that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size.saturating_sub(2) && post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large/wasteful or open-bin pressure is low.
    if bin_residual == bin_capacity {
        // base cost of consuming fresh capacity
        score += 45.0;
        // cheaper to open new bins early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // if many open bins with big mean residual, prefer reusing them
        score += 0.15 * open_bins_count as f64 + 0.25 * mean_residual;
        // if the item is large, a fresh bin keeps flexibility for big items
        if item_size >= 70 {
            score -= 20.0;
        }
    } else {
        // open-bin pressure: many open bins -> favor consolidation into
        // already-open bins to avoid bin-count sprawl.
        score += 0.05 * open_bins_count as f64;
        // favor bins with residual close to item (best-fit style)
        score += 0.2 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (low post_residual) win.
    // Normalize post_residual relative to capacity.
    let pr = post_residual as f64 / bin_capacity as f64;
    score += pr * 30.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits: strong reward, exact match best.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize wasted potential proportional to gap.
            score += 0.15 * diff;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers far below mean
    // (fragmentation) but also avoid leaving bins too full to be useful.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bin is more acceptable early in the stream or when item is large.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += 15.0 - large_item_bonus - 10.0 * progress;
        // If next item could pair into the fresh bin, soften penalty.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 8.0;
        }
    }

    // Mild tie-breaker: prefer bins with more open competition (spread load).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste-aware, non-linear).
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * tight * tight;

    // Penalize small post-residuals that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: bonus if next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let poor_fit = 1.0 - tight;
        score += 20.0 * (1.0 - crowding) * (0.5 + 0.5 * poor_fit);
        // Late in the stream, prefer consolidating into open bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * t;
    }

    // Mild preference for bins with residuals above the current mean (balance).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight preference for fuller bins among equals.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = pr * (1.0 + 0.8 * progress);

    // Quadratic dead-space penalty: waste grows super-linearly.
    score += 0.35 * (pr * pr) / cap;

    // Smooth coupling: residual relative to mean residual of open bins.
    let rel = if mean_residual > 0.0 { pr / mean_residual } else { pr / cap };
    score += 12.0 * rel * rel;

    // Last-chance bonus: only bin that fits -> strong reward (subtract).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mildly penalize consuming this bin.
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Perfect fit reward (smooth, non-piecewise).
    score -= 30.0 * (-pr as f64 / 8.0).exp();

    // Penalize opening a new bin when open bins exist and fit is acceptable.
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * fit_norm + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Mild pressure to consolidate into fewer bins early.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let frac = post_residual as f64 / cap_f;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals that cannot hold typical items (1..100 unknown, but
    // small residuals are the classic waste). Penalize tiny non-zero residuals harshly.
    if post_residual > 0 {
        let class = post_residual % 10; // harmonic decade class
        if class == 0 {
            score -= 5.0; // round residual: reusable for many sizes
        } else if post_residual < 10 {
            score += 40.0 + (10 - post_residual) as f64 * 3.0; // dead space
        } else if post_residual < 20 {
            score += 12.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            score -= (10.0 - (next_waste as f64 / cap_f) * 10.0).max(0.0);
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so existing bins win unless they waste a lot
        score += 60.0
            - (fitting_bins_count as f64) * 2.0
            - (step_index as f64 / total_items.max(1) as f64) * 10.0;
    } else {
        // Tightness reward: relative fit quality
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 25.0;
        // Prefer filling bins whose residual is below mean (consolidate waste)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
        // Many open bins: encourage closing them out
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: gaps too small for even the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Dead-space avoidance: if post_residual can't fit the lookahead item but is
    // large enough to be "usable-looking", penalize mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // chain-friendly gap
    }

    // Open bins pressure: many open bins -> discourage spreading, favor filling existing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when existing
        // residuals are large and fits are poor.
        score += 90.0 + bin_pressure;
        if fitting_bins_count == 1 {
            score += 70.0; // don't abandon the only fitting bin
        }
        if mean_residual < 20.0 {
            score -= 25.0; // existing bins nearly full, new bin reasonable
        }
    } else {
        score -= bin_pressure * 0.5;
    }

    // Alignment with mean residual: prefer bins whose post residual stays near mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (dead space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else {
        // Penalize small unusable dead space quadratically
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // heavily reward this placement
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fills the remainder
            score -= 200.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does not fit here; penalize if it leaves a large orphan residual
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last chance bin: strong bonus to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New empty bin candidate: only attractive when item is large or no good fit exists
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // new bin is good for big items, bad for small ones (wastes capacity)
        score += 120.0 * (1.0 - tightness);
        // if many bins already fit the item, discourage opening another
        if fitting_bins_count > 0 {
            score += 80.0 * fitting_bins_count as f64;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
    }

    // Mild penalty per open bin to discourage proliferation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
