pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 8.0 * poly * cap * 0.01;

    // Penalize dead space more as stream progresses (fewer chances to reuse)
    score += progress * (norm_pr * norm_pr) * 20.0;

    // Reward tight fits smoothly (low post residual)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 6.0;

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 12.0;
    }

    // New bin: penalize mildly, less when many open bins are fragmented
    score += is_new * (10.0 + 15.0 * (1.0 - progress));

    // Lookahead: favor bins whose residual after placement fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Fragmentation pressure: if mean residual is low, protect remaining space
    score += (mean_residual / cap) * (norm_pr * 3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fraction quantum)
    let post = post_residual as u32;
    let residue_class = (post % 10) as f64;
    // Penalize post-residuals that are neither 0 (perfect fit) nor large enough to host a typical item
    if post == 0 {
        score -= 25.0; // perfect fit reward
    } else if post < 10 {
        score += (10.0 - post as f64) * 3.0; // tiny dead space penalty
    } else {
        // reward post_residuals in harmonic bands that commonly fit items (10..=80)
        score -= residue_class * 0.5;
        if post >= 10 && post <= 80 {
            score -= 6.0;
        }
    }

    // Integer division threshold: can next item fit after this placement?
    if next_item_size > 0 {
        if post >= next_item_size {
            // chain fit: reward proportionally to leftover after chaining
            let chain_left = post - next_item_size;
            score -= 10.0 + (chain_left as f64) * 0.15;
            // harmonic bonus if chain_left lands on a clean class
            if chain_left % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot chain here; penalize by gap size
            let gap = (next_item_size - post) as f64;
            score += gap * 0.4;
            if post > 0 && post < 10 {
                score += 8.0; // stranded micro-residual
            }
        }
    } else {
        // last item: prefer tightest closure
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Discourage opening new bins when open bins are underutilized
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from mean residual and phase
        score += 5.0 + mean_residual * 0.3 + progress * 10.0;
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > post.min(bin_capacity as u32) {
            score -= 20.0; // open a fresh bin when existing fits are hopeless for lookahead
        }
    } else {
        // mild penalty for spreading across many bins
        score += (open_bins_count as f64) * 0.05;
    }

    // Capacity fraction coupling: prefer bins whose fill fraction is near-full
    let fill_frac = 1.0 - (bin_residual as f64) / cap;
    score -= fill_frac * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 4.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize leaving residual that cannot fit the next item if next item exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward residual that can accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Slightly favor bins tighter than the mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * (-0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits into post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain placement: excellent, subtract proportional to tightness of chain
            let chain_tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 25.0 + 30.0 * chain_tightness;
        } else {
            // Next item cannot chain here; penalize wasted residual
            score += 8.0;
        }
    }

    // Reward tight fits (low post residual relative to item)
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= 10.0 * fit_ratio;

    // Penalize creating dead space relative to mean residual of open bins
    if (post_residual as f64) > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for opening a new bin when open bins exist that fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    // Slightly favor bins with lower residual (best-fit bias)
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;

    // Reward tight fits: minimize post_residual nonlinearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Penalize dead space that no plausible item can fill (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable slivers
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }
    if fitting_bins_count == 1 && is_new_bin {
        score += 60.0; // don't open a new bin when only one bin fits
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate: penalize proportionally to how well existing bins fit,
    // but allow opening new bins late when mean residual is fragmented.
    if is_new_bin {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + 0.3 * open_bins_count as f64 - 0.5 * fragmentation;
        if progress > 0.7 && mean_residual < item_size as f64 {
            score -= 30.0; // late stream, existing space too fragmented
        }
    }

    // Prefer bins whose residual deviates from mean (consolidate similar bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fewer open bins early, consolidation pressure.
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 12.0 * fit * fit * (1.0 - progress);
    score -= 30.0 * fit * progress * progress;
    score += 8.0 * fit * fit * fit;

    // Reward tight fits smoothly
    score -= 25.0 * (1.0 - fit) * (1.0 - fit) * (item_size as f64 / cap);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - fit);
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - nx / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild pressure toward consolidation as bins accumulate
    score += 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * fit;

    // New-bin candidate penalty unless current bins are nearly full
    if bin_residual == bin_capacity {
        score += 20.0 - 18.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit (best-fit style).
    score -= (post_residual as f64 / cap) * 30.0;

    // Harmonic class of post_residual: classify dead space by modulo classes.
    // Residuals divisible by 10 are "usable" (items come in multiples of 10 classically);
    // small odd residuals are dead space -> penalize.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, excellent
    } else if pr < 10 {
        score += 25.0; // tiny unusable dead space
    } else {
        let class = pr % 10;
        match class {
            0 => score -= 12.0,                 // harmonic class 0: highly reusable
            1 | 3 | 7 | 9 => score += 10.0,     // coprime class: harder to fill
            5 => score += 2.0,                  // half-class
            _ => score += 4.0,                  // even non-harmonic
        }
    }

    // Integer-division thresholds on post_residual: does next item fit harmonically?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0; // next item can chain into this bin
        // Bonus if post_residual is an exact harmonic multiple of next item size
        if pr % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot fit here; residual becomes dead unless reusable later
        score += 6.0;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only good when current bin
    // would leave a bad harmonic class or the item barely fits.
    if bin_residual == bin_capacity {
        let waste = post_residual;
        // Prefer opening a new bin when existing bins are fragmented (low mean residual)
        // and this item is large.
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 15.0;
        }
        if waste >= 20 {
            score += 8.0; // opening fresh bin leaves big residual: mild penalty
        }
    } else {
        // Existing bin: reward when item fills a large fraction of residual.
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill * 15.0;
        // Penalize leaving residual in a bad class when mean residual is already high.
        if mean_residual > cap * 0.6 && pr > 0 && pr % 10 != 0 {
            score += 5.0;
        }
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Many open bins: discourage spreading, favor bins below mean residual (tighter).
    if open_bins_count > 3 {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Larger leftover space is mildly rewarded (still usable).
        score -= 0.3 * (post_residual as f64);
    }

    // Pressure from number of open bins: prefer filling existing bins
    // when many are open; prefer new bins when few are open.
    score += 4.0 * (open_bins_count as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when
    // mean residual across open bins is small (they are nearly full).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if mean_r < 15.0 {
            score -= 50.0; // open bins nearly full -> prefer new bin
        } else {
            score += 40.0 + mean_r; // discourage wasting fresh bins
        }
    }

    // Lookahead: if the next item would fit the post-residual exactly-ish,
    // reward leaving that gap; if post-residual is too small for the next
    // item but nonzero, penalize (dead space for the near future).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= n && pr - n < 10.0 {
            score -= 30.0; // next item nearly fills this bin perfectly
        } else if pr > 0.0 && pr < n {
            score += 15.0; // leftover can't fit next item
        }
    }

    // Late in the stream, tighten up: avoid opening bins near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress > 0.9 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits, but penalize leftover slack proportionally
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack * 0.8;
        } else {
            // next item won't fit here after placement: penalize
            score += 150.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end below mean
    // (tight fits) and penalize leaving large residuals relative to mean.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Penalize small unusable dead space (wasted capacity)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // open bins would leave awkward fits; base cost of opening a bin.
    if bin_residual == bin_capacity {
        // base opening cost, reduced late in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 250.0 - 120.0 * progress;
        // if item is large, opening fresh bin is reasonable
        if item_size > bin_capacity / 2 {
            score -= 80.0;
        }
        // avoid opening new bins when many are open with room
        score += open_bins_count as f64 * 5.0;
    }

    // Mild preference for filling larger-residual bins first (best-fit core)
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64) * (post_residual as f64) * 0.005;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            if gap == 0.0 {
                score -= 45.0;
            } else {
                score -= 15.0 * (1.0 - gap / 100.0);
            }
        } else {
            // Next item cannot fit here; mild penalty proportional to overshoot.
            score += 0.15 * (nxt - pr);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 0.05 * mean_residual * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin is acceptable early or when no good fit exists,
    // but penalize opening new bins when existing bins are nearly empty of load.
    if bin_residual == bin_capacity {
        let base = 0.5 * bin_capacity as f64;
        // Prefer new bin when current item is large (hard to place later).
        let large_item_bonus = if item_size > 60 { 20.0 } else { 0.0 };
        score = base - large_item_bonus + 10.0 * progress + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: new bin is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, tight fits are rewarded more strongly.
    let tightness = 1.0 - fit_ratio; // fraction of residual used by this item
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize very small post residuals that become dead space, weighted by progress
    let dead = (1.0 - fit_ratio.min(1.0)) * (fit_ratio.max(0.0));
    score += 20.0 * dead * dead * (1.0 - progress);

    // Perfect-fit bonus (smooth, quadratic peak at fit_ratio = 0)
    score -= 15.0 * (1.0 - fit_ratio).powi(3) * (0.3 + 0.7 * progress);

    // Lookahead coupling: if next item fits the post residual, reward smoothly
    if next_item_size > 0 {
        let next_fits = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 10.0 * (1.0 - next_fits) * (pr >= next_item_size as f64) as i32 as f64;
        // penalize if post residual is slightly too small for next item
        let miss = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 8.0 * miss * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure to consolidate when many bins are open
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= 6.0 * bin_pressure * tightness;

    // Mean-residual coupling: prefer bins close to the mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate handling: prefer opening a new bin only when current fits are poor
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * (1.0 - fit_ratio) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 classes
    let class = post_residual / 10;
    // Penalize leftovers that are "almost full classes" (wasted near-complete slots)
    score += (class % 3) as f64 * 2.0;

    // Perfect or near-perfect fits get strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead space: leftovers below the smallest item class are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item's harmonic class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward proportionally to tightness of the pair
            let pair_tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 20.0 * pair_tightness;
            // harmonic bonus if pair leaves another clean class boundary
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow here; penalize if leftover is in a "useless gap"
            let gap_class = post_residual / 10;
            if gap_class == 0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Fraction of capacity filled by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Prefer tighter bins relative to fleet mean residual
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Stream progression: early on, be picky (penalize loose fits); late, pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    // New-bin candidate handling: only open a new bin if it promises a big clean slot
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted by how much of it the item fills
        score += 35.0 - 25.0 * fill_frac;
        // if item is large (>50% capacity), a fresh bin is attractive
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // avoid opening new bins when good fitting bins exist
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Integer-division threshold on item size: big items deserve priority placement
    if item_size / 20 >= 3 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are penalized heavily.
    // A gap is "dead" if it cannot hold even a modest future item (assume min ~10,
    // but be conservative: anything below 12 is likely waste).
    if post_residual < 12 {
        score += 40.0; // essentially full bin, great — but tiny gap is fine actually
        score -= 60.0; // net strong reward for near-perfect fill
    } else if post_residual < 25 {
        // Risky dead zone: gap too small for many items, too big to ignore.
        score += 18.0;
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless this placement meaningfully consolidates.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is
    // large relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Opening a new bin is attractive only when existing bins are too full
        // (low mean residual) or the stream is early and we can afford spread.
        score += 25.0 * fragmentation + 10.0 * (1.0 - progress);
        if item_size >= 60 {
            score -= 20.0; // big items justify fresh bins
        }
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving
    // exactly that much space (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 12 {
            score -= 8.0; // next item nearly fills it
        } else if next_item_size > post_residual {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Mild preference for bins below mean residual (balance load).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space penalty, non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus grows as the next item fills the remaining space well.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fill;
        } else {
            // Penalize creating residual that cannot fit the next item,
            // scaled by how "wasted" the leftover is.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 15.0 * (1.0 - waste).max(0.0);
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.15 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins fit well (new-bin candidate
    // has bin_residual == bin_capacity and post_residual == capacity - item).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0;
        // Allow opening a new bin if the item is large and would leave tiny
        // unusable slivers in existing bins.
        let sliver_risk = (post_residual as f64) / (bin_capacity as f64);
        if sliver_risk < 0.2 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly more willing to open bins to build diversity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post residual.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tight * tight;

    // Penalize dead space that no typical item can use (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: penalize if placing here blocks the next item from fitting.
    if next_item_size > 0 {
        if post_residual < next_item_size && bin_residual >= next_item_size {
            score += 8.0; // wasted opportunity to keep next item together
        }
        if post_residual >= next_item_size {
            score -= 6.0; // leaves room for the next item: chain-friendly
        }
        // Perfect pair: item + next item exactly fills this bin.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: an empty bin is only attractive when open bins
    // are all fairly full or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - (mean_residual / cap);
        let pressure = mean_fullness * (open_bins_count as f64).sqrt();
        // Early stream: allow opening bins more liberally to build diversity.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = 15.0 * (1.0 - progress);
        score = cap * 0.6 - pressure * 20.0 + openness;
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    if bin_residual as f64 > mean_residual + 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual scaled by a smooth non-linear function of stream progress.
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Non-linear coupling: dead space (very small residual) penalized more as stream advances.
    let dead = (1.0 - norm_pr).powi(3);
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with a saturating non-linear term.
    score -= 25.0 * (1.0 - (pr / 30.0).powi(2).min(1.0)) * (1.0 - norm_pr);

    // Last-chance bonus: only one fitting bin -> smooth quadratic urgency.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * progress);
    }

    // Penalize bins whose residual deviates strongly from the mean (imbalance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev.abs() * (1.0 - progress);

    // Lookahead coupling: if next item fits nicely in post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - (fit_gap * 3.0).min(1.0));
    }

    // Mild penalty for opening a brand-new bin when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "resonant" class (multiples of 10) remain reusable by future items.
    let post = post_residual as u32;
    let harmonic = (post % 10) as f64;
    // Penalize off-class remainders proportionally (dead-space creation).
    score += harmonic * 0.6;

    // Integer-division class: leftover usable slots of size 10.
    let slots = post / 10;
    score -= slots as f64 * 2.0;

    // Perfect fit reward: residual exactly zero is ideal.
    if post == 0 {
        score -= 50.0;
    }

    // Tight fit: post_residual smaller than the smallest plausible item (1..100
    // unknown distribution, but small items are common) -> penalize tiny dead space
    // that nothing can use.
    if post > 0 && post < 5 {
        score += 25.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            // next item fits but leaves another remainder: mild reward scaled
            // by how much slack remains after the next placement.
            let chain_post = post - next_item_size;
            score -= 10.0 + ((chain_post % 10) as f64) * (-0.5) + (chain_post / 10) as f64;
        } else {
            // next item cannot use this bin's leftover: penalize if leftover is
            // in an awkward class (not a multiple of 10).
            if post % 10 != 0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give the empty bin a base penalty that shrinks when
    // mean residual across open bins is small (open bins are nearly full).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // 0 => open bins nearly full
        score += 30.0 * (1.0 - pressure.min(1.0)) + 10.0;
        // Late in the stream, opening bins is less costly than fragmenting.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
    }

    // Prefer bins whose residual is far from the item (bad fits) less:
    let waste = (bin_residual - item_size) as f64;
    score += 0.1 * waste;

    // Modulo coupling between item size and capacity thirds: items that land a
    // bin into the lower third residual tend to strand space; penalize mildly.
    if post < bin_capacity / 3 && post > 0 {
        score += 5.0;
    }

    // Small global regularization against open-bin explosion early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - (post as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable dead space (gap < 10 can never fit any item)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // gaps 10..19 are only usable by small items; mild penalty
        score += 12.0;
    }

    // Reward very tight fits (perfect or near-perfect packing)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    }

    // Penalize placement that leaves residual far below the mean (fragmentation)
    let pr = post_residual as f64;
    if pr < mean_residual * 0.4 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly
    if bin_residual == bin_capacity {
        if fitting_bins_count == 1 {
            // forced to open new bin anyway; make it neutral-low
            score -= 20.0;
        } else {
            // discourage opening a new bin when other bins can fit the item
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 40.0; // perfect two-item fill
            }
        } else {
            // next item cannot fit here; penalize more when gap is small (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Penalize large residual relative to mean (wasting space in a roomy bin)
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Tight-fit bonus on current item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Early in stream: encourage opening bins to build flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
        // New bin attractive only if no good lookahead match exists in open bins
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight preference to fill older/more crowded bin sets
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to smallest plausible future item
        score += (post_residual as f64).powf(1.35) * 0.15;
    }

    // Tight fit bonus: fraction of bin consumed
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 40.0;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
        // Extra reward if next item nearly fills the remainder too
        let nxt_fit = next_item_size as f64 / post_residual as f64;
        score -= nxt_fit * 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving large unusable remainder
        score += (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer best fit more strongly
        score += (fitting_bins_count as f64).ln() * 5.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let urgency = (fitting_bins_count == 0) as i32 as f64;
        score = 250.0 + urgency * 400.0 - pressure * 100.0
            + (open_bins_count as f64) * 8.0
            - (step_index as f64 / total_items.max(1) as f64) * 50.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 30.0;
        }
        return score;
    }

    // Prefer bins whose residual deviates from mean (consolidate space)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Late in stream: be more conservative, minimize wasted space harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Prefer bins with small residual overall (best-fit core)
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items as f64;
    let mean_res = mean_residual;

    // Smooth non-linear polynomial coupling of post_residual with progress
    let x = post / cap; // normalized post residual in [0,1]
    let p = progress;

    // Base: reward small post_residual, with progress-dependent curvature
    let mut score = post * (1.0 + 0.8 * p * p) - 30.0 * x * (1.0 - x) * (1.0 - 0.5 * p);

    // Interaction: dead-space penalty grows quadratically with progress
    let dead = x * x;
    score += 45.0 * dead * (0.3 + 0.7 * p);

    // Coupling with mean residual: prefer bins below mean residual (tighter packing)
    let dev = (post - mean_res) / cap;
    score += 20.0 * dev * dev - 12.0 * dev;

    // Last-chance bonus: smooth reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 25.0 * scarcity * (1.0 - dead);

    // Lookahead: reward if next item fits smoothly in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs() / cap;
        score += 15.0 * gap * gap - 10.0 * (1.0 - gap);
    }

    // Mild penalty for too many open bins late in the stream
    score += 0.5 * (open_bins_count as f64) * p;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which residue class / capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward small post_residual (tight fit)
    score -= 60.0 * (-frac * 6.0).exp();

    // Dead space penalty: residuals in "unusable" harmonic classes (very small)
    if post_residual > 0 {
        let cls = post_residual % 10;
        if post_residual < 10 {
            score += 45.0; // nearly dead space
        } else if cls == 0 {
            score -= 25.0; // perfectly divisible residual is reusable
        } else {
            score += (10 - cls) as f64 * 1.5; // awkward residue class
        }
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * next_item_size as f64; // chainable bin
        } else {
            // next item won't fit; penalize proportionally to wasted gap
            let gap = (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
            score += 0.3 * gap;
            if post_residual < next_item_size / 2 {
                score += 15.0; // residual too small for next item's half
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        // penalize opening new bin when good alternatives exist
        score += 70.0 + 20.0 * pressure;
        // but if stream is late and mean residual is fragmented, new bin is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 25.0 && progress > 0.3 {
            score -= 60.0;
        }
        // never open a new bin for a tiny item if any bin fits
        if item_size <= bin_capacity / 4 && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate fullness)
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Slight preference to fill bins earlier in the open set (limit bin spread)
    score += 0.05 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits (small but usable-ish residuals) mildly.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 30.0;

    // Penalize leaving a gap that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: only attractive when residuals are large/wasted.
    if bin_residual == bin_capacity {
        let avg_dead = mean_residual - post_residual as f64;
        score = bin_capacity as f64 * 0.55 - avg_dead * 0.2;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item chains perfectly: strong reward proportional to tightness
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 60.0 + 40.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.5 * gap;
        }
        // exact chain: post_residual equals next item size
        if post_residual == next_item_size {
            score -= 250.0;
        }
    } else {
        // last item: prefer minimal residual strongly
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins with residual below average (tighter bins)
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.8 * (mean_residual - resid);
    } else {
        score += 0.4 * (resid - mean_residual);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize leaving dead space that is too small for typical items (1..100 range)
    if resid > 0 && resid < 10 {
        score += 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists; penalize opening new bins
    // when open bins can reasonably accommodate the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 150.0 * pressure + 50.0 * (1.0 - progress);
        // allow new bin if item is large and mean residual is small
        if item_size as f64 > mean_residual + 20.0 {
            score -= 100.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (best-fit core with quadratic decay).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward partial compatibility, scaled by how much would remain after next item
            let after_next = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - after_next / bin_capacity as f64);
        } else {
            // next item can't use the leftover: penalize proportionally to wasted space
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid wasting it on a poor fit
    // but reward using it when the fit is tight (avoids opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 10 {
            score -= 25.0;
        } else {
            score += 12.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin when good fitting options exist.
        score += 15.0 * fitting_bins_count as f64;
        // Early in stream, opening bins is cheaper (builds diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is small (fragmented), a fresh bin is valuable.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 8.0;
        // Large items justify fresh bins.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    } else {
        // Slight preference for filling bins that are already heavily loaded.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
        // Penalize scattering across many open bins when mean residual is large.
        if mean_residual > 30.0 {
            score += 0.05 * open_bins_count as f64;
        }
    }

    // Dead-space guard: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Normalized post-residual and its smooth non-linear couplings
    let x = post / cap; // in [0,1)
    let x2 = x * x;
    let x3 = x2 * x;

    let mut score = post * (1.0 + 0.8 * x2);

    // Polynomial coupling with stream progress: late in the stream,
    // waste is penalized more strongly (smooth cubic ramp).
    let p = progress;
    score += 12.0 * p * p * p * x2 * cap * 0.1;

    // Reward tight fits: subtract for small post_residual (smooth quadratic)
    score -= 6.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far above/below mean residual (fragmentation smoothing)
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (cap * 0.01);

    // Lookahead: if next item could fill this bin's post-residual exactly, reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * x;

    // New-bin candidate: neutral-ish baseline, penalized unless residuals are tight
    if bin_residual == bin_capacity {
        score = post + 4.0 + 10.0 * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: quantize leftover space ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    // Integer-division class: leftover in bands of 10 (dead-space buckets)
    let dead_class = post_residual / 10;
    // Penalize dead space superlinearly: small leftovers are "unusable"
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if dead_class == 0 {
        score += 0.0;
    } else {
        // harmonic weighting: 1/class-like decay on band index
        score += (dead_class as f64).powf(-0.5) * 6.0;
    }

    // Perfect or near-perfect closure reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // --- Modulo arithmetic on capacity fractions ---
    // Residual congruence classes mod 10: leftover matching common item
    // size residues (10..80 step classes) is more likely reusable.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // aligned leftover, easy to fill exactly
    } else if m >= 5 {
        score -= 2.0; // mid-band leftover moderately reusable
    } else {
        score += 3.0; // awkward small-modulo leftover
    }

    // --- Lookahead coupling: does next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin
            let chain_waste = post_residual - next_item_size;
            score -= 25.0 - (chain_waste as f64) * 0.5;
            if chain_waste == 0 {
                score -= 20.0; // exact two-item closure
            }
        } else if next_item_size > post_residual && post_residual >= 10 {
            // bin left with medium hole that next item cannot use
            score += 6.0;
        }
    } else {
        // last item: strongly prefer closing bins
        score -= 15.0;
    }

    // --- Scarcity: last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost, attractive only if current bins are
        // fragmented (high mean residual relative to capacity) or item huge.
        let frag = mean_residual / cap;
        score = cap - item_size as f64; // fresh-bin post residual baseline
        score += (1.0 - frag) * 10.0;   // penalize opening when bins are tight
        if item_size >= 60 {
            score -= 12.0; // big items like a fresh bin
        }
        if post_residual as f64 > 0.0 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can also chain next item
        }
        // never let fresh bin beat exact closures
        if post_residual == 0 { score = f64::MAX; }
    }

    // --- Stream progression: tighten packing as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // --- Mild penalty for spreading across many open bins ---
    score += (open_bins_count as f64).powf(0.3) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold another item (min item size = 1, but practically tiny gaps)
    // are pure waste. Penalize unusable slivers harshly.
    if post_residual > 0 && post_residual < 5 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Mild reward for tight-but-usable fits, scaled by fit quality.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness;
    }

    // If the next item fits exactly into the post-residual, reward heavily
    // (chained placements are ideal).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual can't host next item: slight penalty unless it's zero.
        if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // Late in the stream, new bins are especially wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // But if the new bin would host the next item too, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced usage),
    // avoiding one bin being drained to a dead state early.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: prefer bins whose post-residual matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: residual exactly consumed by next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * slack;
            if slack == 0.0 {
                score -= 20.0; // chain continues perfectly next step too
            }
        } else {
            // Next item cannot use this bin's residual: penalize dead space
            // proportionally to how far the residual falls short.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
            // Extra penalty if residual is small unusable dead space.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Compare post_residual relative to mean residual across open bins:
    // favor bins left tighter than average (good packing), penalize loose ones.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it attractive only when current bins
    // would leave large dead space; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // If lookahead suggests the new bin would be well-used by next item, discount.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Late in stream, opening bins is cheaper than fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // Many open bins with high mean residual: opening new bin may help.
        if mean_residual > 40.0 {
            score -= 5.0;
        }
    }

    // Slight preference for filling bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
