pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize residuals into [0,1]
    let pr = post_residual as f64 / cap;              // post-fit residual fraction
    let br = bin_residual as f64 / cap;               // pre-fit residual fraction
    let fill = 1.0 - pr;                              // achieved fill fraction
    let prog = step_index as f64 / total_items as f64; // stream progress in [0,1]

    // Smooth non-linear polynomial coupling between fill and progress.
    // Early stream: value near-perfect fits moderately; late stream: strongly
    // reward tight fits because remaining opportunities shrink.
    let tightness = (fill * fill * (3.0 - 2.0 * fill)); // smoothstep on fill
    let late_bonus = 2.0 + 6.0 * prog * prog;           // grows quadratically with progress
    score -= tightness * late_bonus * cap * 0.1;

    // Penalize large dead space with a convex (quadratic) term so small
    // residuals are strongly preferred over medium ones, smoothly.
    score += pr * pr * cap * (0.5 + 1.5 * prog);

    // Interaction: residual relative to mean residual across open bins.
    // Placing into a bin whose leftover is below average keeps spread balanced.
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += dev * (1.0 + prog) * 10.0;

    // Last-chance bin (only one fitting bin): strongly favor using it
    // to avoid opening a new bin, smoothly scaled by how well it fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (30.0 + 40.0 * prog) * (0.5 + 0.5 * fill);
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let nx_fit = 1.0 - (post_residual as f64 - nx) / cap;
            score -= 15.0 + 25.0 * nx_fit * (0.5 + prog);
        } else {
            let miss = (nx - post_residual as f64) / cap;
            score += 10.0 * miss * (0.5 + prog);
        }
    }

    // New-bin candidate: prefer it only when it beats a poor fit into open
    // bins — penalize opening new bins mildly, more so late in the stream.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * prog + 2.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins early (keeps bin count low).
        score -= (1.0 - prog) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod common item sizes
    let residue = post_residual % 10;
    // Penalize post_residuals that fall into awkward residue classes (hard to fill later)
    score += (residue as f64) * 0.7;

    // Reward post_residuals near harmonic multiples of 10 (divisible classes)
    if residue == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: dead space zones
    let q = post_residual / 10;
    if q == 1 || q == 2 {
        score += 5.0; // small dead-space band, hard to reuse
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward if next item divides post_residual nicely
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize leaving large unusable space
            if post_residual > 30 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Prefer tighter bins overall (below mean residual means well-packed)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item.
    let dead_zone = 9.0; // items >= 1, but tiny gaps waste capacity
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += 40.0 * (dead_zone - post_residual as f64) / dead_zone;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-fit bonus: reward filling a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a gap that no future item can plausibly use well:
    // gap just below next_item_size is wasted for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Bonus if the lookahead item fits exactly in the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean residual coupling: prefer bins whose residual is below average (denser bins),
    // keeping loose bins for large future items.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer a new bin when the item is large and would leave a big gap
    // in every existing bin, or when no tight option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Large items are fine in a fresh bin.
        score -= 30.0 * fill_ratio;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is wasteful.
        score += 6.0 * fitting_bins_count as f64;
        // If the lookahead item is large, a fresh bin preserves room for it.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
