        } else {
            // next item won't fit here; penalize blocking large residuals less
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (explore); late in stream, consolidate tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // open bins could still host the item.
        score += 15.0 + 30.0 * t;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // If current item is large and mean residual is small, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    } else {
        // Late stream: reward filling existing bins harder.
        score -= 10.0 * t * (bin_residual as f64 - post) / cap * 10.0;
    }

    // Global state: many open bins with high mean residual -> favor
    // placements that reduce spread (fill the emptiest usable bin).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev; // prefer bins below mean residual (emptier)
    }

    // Mild penalty for leaving large residuals when item is small.
    if (post_residual as f64) > (item_size as f64) * 1.5 && post > 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = (1.0 - norm_post) * (1.0 - norm_post);
    score -= tightness * (1.0 + progress) * 12.0;

    // Non-linear penalty on large dead space, amplified mid/late stream.
    let dead = norm_post * norm_post * norm_post;
    score += dead * (1.0 + 3.0 * progress) * 20.0;

    // Interaction: item size vs residual — reward bins whose residual is close to item size.
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += fit_gap * fit_gap * 15.0;

    // Lookahead coupling: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / bin_capacity as f64;
        let slack = (norm_post - nx).max(0.0);
        score -= (1.0 - slack) * (1.0 - slack) * nx * 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, penalize opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_post * 0.5);
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    let mean_gap = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += mean_gap * mean_gap * 4.0;

    // Slight late-stream preference for consolidating into existing bins.
    score += progress * 2.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residues are "dead space" classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted after placement.
    score += (pr / cap) * 40.0;

    // Integer division thresholds: residue classes mod 10.
    let class = post_residual % 10;
    score += match class {
        0 => -25.0,          // perfectly aligned residue
        1..=5 => 8.0,        // small awkward slivers
        6..=9 => -5.0,       // moderate residue may fit small items
        _ => 0.0,
    };

    // Modulo coupling with next item: does post_residual align with next_item_size?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // next item fits exactly or nearly: reward alignment
            let diff = pr - nxt;
            score -= 18.0 * (1.0 - diff / cap);
            if post_residual % (next_item_size.max(1)) == 0 {
                score -= 15.0; // harmonic divisibility bonus
            }
        } else {
            // next item cannot fit here: penalize by gap size
            score += (nxt - pr) / cap * 30.0;
        }
    }

    // Last-chance bin: strongly reward using it (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Empty new-bin candidate: penalize mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64) * 2.0;
        // but if current bin would leave tiny dead space, opening new bin becomes attractive
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
    }

    // Tight fit reward: near-exact fill.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins below mean residual (larger fill).
    score += (pr - mean_residual) * 0.25;

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving a gap that exactly blocks the next item if it would fit now-ish.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: prefer tighter bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mild preference toward fuller bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight early-stream openness to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (item + next item fill the bin).
    if next_item_size > 0 {
        let combined = item_size + next_item_size;
        if combined <= bin_residual {
            let slack = (bin_residual - combined) as f64;
            // Perfect two-item fill is extremely attractive.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 25.0; // perfect packing bonus
            }
        } else {
            // Next item cannot join: penalize leaving dead space next item can't use.
            let unusable = post_residual as f64 - next_item_size as f64;
            if unusable > 0.0 {
                score += 0.8 * unusable;
            }
        }
        // Reward residual that still fits next_item_size (keeps flexibility).
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 3.0; // stranded small residual
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Allow new bin early in stream or when few bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for tighter fits overall.
    score += 0.1 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else if next_item_size > 0 && (next_item_size as f64) > dead {
            score += 8.0 * (next_item_size as f64 - dead) / 100.0;
        }
    }

    // Lookahead coupling: prefer bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global state: many open bins with high mean residual -> discourage fragmenting,
    // favor packing into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * (open_bins_count.max(1) as f64));
    score += (1.0 - pressure) * 10.0 * (1.0 - progress);

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to residual or existing bins are nearly full.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * big_item + 15.0 * scarcity - 10.0 * (1.0 - progress);
        // Penalize opening new bins early in the stream.
        score += 15.0 * (1.0 - progress);
    }

    // Mild penalty for leaving residual near half capacity (awkward zone).
    let half = (bin_capacity as f64) * 0.5;
    let dev = ((post_residual as f64) - half).abs() / half;
    score += 3.0 * (1.0 - dev);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: tightness of fit (post_residual), non-linearly shaped
    let norm_post = post / cap; // 0..1
    let mut score = norm_post * norm_post * (1.0 + norm_post);

    // Reward near-perfect fits: subtract bonus that peaks when post_residual is small
    let fit_quality = 1.0 - norm_post;
    score -= 3.0 * fit_quality * fit_quality * fit_quality;

    // Smooth progress coupling: early on, keep bins flexible (penalize very small post);
    // late in stream, prefer filling bins as tightly as possible.
    let flexibility = norm_post * (1.0 - norm_post) * 4.0; // peaks at 0.5 post
    score += (1.0 - progress) * 0.8 * (1.0 - flexibility);
    score -= progress * 1.2 * flexibility;

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next > 0.0 {
        let next_norm = next / cap;
        let fits_next = if post >= next { 1.0 } else { 0.0 };
        let closeness = (post - next).abs() / cap;
        score -= fits_next * (1.5 - closeness) * (0.5 + 0.5 * (1.0 - progress));
        score += next_norm * 0.3 * (1.0 - fit_quality);
    }

    // Mean residual coupling: placing into a bin far from mean residual spreads waste
    let dev = (post - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Congestion: many open bins -> prefer using existing ones (penalize new-bin tendency)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // New-bin candidate: make empty bins less attractive unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 1.0 - (item / cap) * (item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (best-fit core).
    score -= 24.0 * (1.0 - post_residual as f64 / cap);

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Residuals that are small multiples of common item sizes (10,20,25,30,40,50)
    // are "usable" classes; odd/prime-ish remainders are dead space.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -18.0,
        1..=9 => 14.0,
        10 | 20 | 25 | 30 | 40 | 50 => -10.0,
        _ if pr % 10 == 0 => -6.0,
        _ if pr % 5 == 0 => 2.0,
        _ => 6.0,
    };
    score += class_penalty;

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 16.0;
        } else {
            score -= 8.0 * (1.0 - slack as f64 / cap);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize mildly, scaled by how far off.
        score += 4.0 * ((next_item_size - post_residual) as f64 / 100.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: keep new bins attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin competes via mean residual pressure: if open bins are nearly full,
        // opening fresh is good; if they have room, discourage.
        score += 6.0 + mean_residual * 0.12;
        // Early in stream, slightly favor consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
        // Many open bins -> prefer filling them rather than opening more.
        score += 0.8 * open_bins_count as f64;
    }

    // Integer-division threshold: post_residual in [1,9] is prime dead space;
    // escalate penalty as stream progresses (late waste hurts more).
    if pr >= 1 && pr <= 9 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins below mean residual (balance load across classes).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (waste-proportional quadratic term).
    let waste = post_residual as f64;
    score += 0.15 * waste * waste / bin_capacity as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty * 2.0;
        // But allow new bin if it would leave a large usable residual for next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        } else if next_item_size > 0 {
            score += 20.0; // next item won't fit nicely either
        }
    } else {
        // Existing bin: slight preference when mean residual is high (bins are loose).
        score -= mean_residual * 0.05;
        // If next item fits in this bin's post residual, reward the placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual still usable by next item: mild reward scaled by tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.2;
    } else if next_item_size > 0 {
        // Post-residual too small for next item: dead-space penalty.
        score += 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (keeps residual distribution balanced),
    // reward bins that are tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for opening new bins early in the stream (more future freedom),
    // but only for the empty-bin candidate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 - 10.0 * progress;
        // Don't open a new bin when an existing bin fits perfectly.
        if post_residual == 0 {
            score += 40.0;
        }
    }

    // Reward exact fills (zero waste).
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing current item blocks the next item in this bin
            score += 6.0;
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_penalty = open_bins_count as f64 * 1.5;
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 - mean_residual).abs()
        };
        // Prefer new bin when mean residual of open bins is small (all tight)
        // and we are early (future items may fill leftovers better).
        score = 100.0 - 0.5 * mean_residual + avg_open_penalty * progress - poor_fit * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0; // empty bin can always take the next item too
        }
    }

    // Mild preference for bins with residual close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Slight time pressure: late in the stream, avoid leaving scraps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let fit = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * fit * fit);

    // Polynomial coupling with stream progress: later in the stream,
    // punish leftover space more aggressively (quadratic + cubic terms).
    let prog_term = progress * progress * (1.0 - progress);
    score += 40.0 * fit * fit * progress;
    score -= 25.0 * fit * prog_term;

    // Reward tight fits (near-zero post-residual) with a smooth bump.
    score -= 12.0 * (1.0 - fit).powi(6);

    // Dead-space penalty: residuals too small for typical items.
    if next_item_size > 0 && pr > 0.0 && (next_item_size as f64) > pr {
        score += 15.0 * ((next_item_size as f64) - pr) / cap;
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // New empty bin candidate: penalize unless it yields a genuinely tight fit.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / cap;
        score += 30.0 - 45.0 * tight * tight;
    }

    // Mild preference for balancing residual spread across bins.
    score += 0.05 * ((pr - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: group residuals into decile classes of capacity
    let class = post_residual / 10;
    let class_center = (class * 10 + 5) as f64;
    // Reward residuals that sit near class boundaries (small within-class offset)
    let within = post_residual as f64 - (class * 10) as f64;
    score += within * 0.3;

    // Dead space: residual too small for the smallest plausible item (1..100, min 1)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits the post residual, reward keeping this bin flexible
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize slightly more if waste is large
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.4;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to residual
    // of all other bins; only attractive when this bin is empty and mean residual is high
    if bin_residual == bin_capacity {
        // empty candidate: base score is full capacity; adjust by stream progress and congestion
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * mean_residual / bin_capacity as f64 * (1.0 - progress);
        // discourage hoarding too many open bins
        score += open_bins_count as f64 * 1.5;
        // perfect-fit class for empty bin when item is large relative to capacity
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    }

    // Prefer filling bins with larger residual when many bins are open (consolidation)
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(20) as f64) * 0.5;

    // Mild bonus for tight integer division: item divides residual evenly
    if post_residual > 0 && bin_residual % item_size.max(1) == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=18) are nearly unusable
    // for future items (sizes >= 1, practically >= 10 in typical streams),
    // so penalize them quadratically beyond the raw residual.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 18 {
        score += (19.0 - pr) * (19.0 - pr) * 0.9;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward filling bins deeply (high fill ratio reduces score).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into existing
    // bins; but for a brand-new bin candidate (residual == capacity) the
    // pressure applies as a penalty so new bins are opened only when clearly
    // better (e.g. avoiding dead space).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        score += pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Slight preference for bins already below mean residual (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild stream-progression term: late in the stream, avoid creating gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual <= 18 {
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item size
    // (enables a perfect follow-up placement), penalize near-miss dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            if gap == 0.0 {
                score -= 400.0; // perfect 2-step chain
            } else if gap <= 10.0 {
                score -= 200.0 - 15.0 * gap; // close chain
            } else {
                // unusable-ish leftover for next item: penalize proportionally
                score += 0.5 * gap;
            }
        } else {
            // next item cannot fit in this bin's leftover; leftover is dead
            // space unless tiny. Penalize dead space relative to capacity.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 0.0; // tiny scraps are fine
            } else {
                score += 0.3 * (dead - 10.0);
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarcer;
    // placing into a below-mean bin (tight bin) is good if it fits well.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f / mean_residual;
        if rel < 1.0 {
            score -= 30.0 * (1.0 - rel); // favor tight bins
        } else {
            score += 10.0 * (rel - 1.0).min(2.0); // discourage very loose bins
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // item is large relative to typical residuals or fits are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // open a new bin mainly for large items late in the stream or when
        // post_residual would be very small elsewhere anyway
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let openness = 0.35 * item_frac + 0.3 * progress + 0.35 * pressure;
        score += 120.0 - 240.0 * openness;
        // never open a new bin when a perfect follow-up chain exists elsewhere
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
            score += 500.0;
        }
    }

    // Mild penalty for waste relative to capacity, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that is hard to reuse later (below typical small item size).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward leaving post_residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Leaving dead space the next item cannot use is mildly bad.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
        // If the next item fits exactly in what we leave behind, extra reward.
        if next_item_size == post_residual {
            score -= 8.0;
        }
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (penalize new bins less aggressively later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized, more so when many bins are already open
        // and other bins could fit the item.
        let mut penalty = 20.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            penalty += 10.0 + 15.0 * (1.0 - progress);
        }
        // If the item is large relative to mean residual, open bins are poor hosts.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual * 1.5 {
            penalty -= 12.0;
        }
        score += penalty;
    }

    // Mild preference for bins below the mean residual (consolidate fuller bins).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Prefer bins that are already fairly full (small residual) to consolidate.
    score += 0.08 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping.
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 40.0;

    // Non-linear coupling: as stream progresses, waste matters more (bins are committed).
    let urgency = progress * progress;
    score += urgency * norm_pr * 80.0;

    // Dead-space penalty: residuals too small to fit typical items (smooth sigmoid-like gate).
    let dead = (1.0 - (pr / 20.0).tanh()) * 25.0 * (0.5 + urgency);
    score += dead;

    // Lookahead: reward bins whose post-residual can host the next item (smooth coupling).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = 1.0 - (1.0 / (1.0 + (pr - ns).max(0.0) / 15.0));
        score -= fits_next * 30.0 * (1.0 - urgency);
        // Penalize leaving exactly awkward space the next item cannot use.
        let waste = ((pr - ns) / cap).max(0.0);
        score += waste * waste * 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 45.0 + 30.0 * urgency;
    }

    // Mild penalty proportional to open bins count to discourage bin sprawl.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Slight pull toward bins with above-mean residual (balance residuals smoothly).
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and highly reusable
    // residuals (multiples of common item sizes) are desirable.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit: always best
    } else {
        // Modulo-harmonic reward: residuals divisible by small item classes
        // (e.g. 10, 20, 25, 50) are more likely to be filled later.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 6.0; }
    }

    // Integer-division threshold on post_residual: dead space below the
    // minimum plausible item size is nearly unusable -> penalize.
    if pr > 0 && pr < 10 {
        score += 40.0;
    } else if pr <= 30 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && pr < bin_capacity as f64 * 0.9 as f64 {
        score -= 25.0;
    }

    // New-bin candidate: empty bin residual == capacity. Penalize opening a
    // new bin unless existing fits create large dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
    }

    // Prefer bins with below-mean residual (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: avoid opening a new bin when only this bin fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        if next_item_size >= post_residual - 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: keep it attractive only when item is large relative to residual.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > 70 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: bin becomes exactly full
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Prefer residual that still hosts the next item but leaves little waste.
            score -= 10.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            let gap = next_item_size - post_residual;
            score += 0.15 * gap as f64;
        }
    }

    // Relative-to-mean coupling: bins with below-average residual are more
    // valuable to fill up (close them out); above-average residual bins get
    // penalized slightly to keep a spread of usable gaps.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // fit is terrible (large dead space) and other options exist.
    if bin_residual == bin_capacity {
        let dead = post_residual as f64; // = capacity - item_size
        if dead < 35.0 {
            score += 40.0; // keep using open bins for decent fits
        } else {
            score += 5.0 + 0.1 * dead; // mild preference for new bin on huge items
        }
    }

    // Slight late-stream consolidation: prefer existing bins as stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward leaving room for the next item.
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.4 + (open_bins_count as f64) * 0.8;
        // But open a new bin if mean residual is low (existing bins are full).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 30.0;
        }
    }

    // Time-horizon scaling: early in stream, be more conservative (favor tight fits harder);
    // late in stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (balancing residual distribution).
    score += ((bin_residual as f64 - mean_residual) * 0.15).max(-6.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn);
    score -= 60.0 * poly * (0.5 + progress);

    // Tight fits favored more strongly as stream progresses
    let tight = 1.0 - prn;
    score -= 25.0 * tight * tight * progress;

    // Penalize residual that cannot fit the next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 40.0 * gap * gap;
        // Reward residual that exactly accommodates lookahead (smooth)
        let fit_lookahead = (prn - next_item_size as f64 / cap).abs();
        score -= 15.0 * (1.0 - fit_lookahead.min(1.0)) * (1.0 - fit_lookahead.min(1.0));
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count <= 1 {
        score -= 30.0;
    } else {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Mild penalty for residual far from mean residual (dispersion coupling)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Penalize very small dead space relative to capacity, smoothed by progress
    let dead = prn * prn;
    score += 20.0 * dead * (1.0 - progress);

    // New-bin candidate: prefer only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = pr + 50.0 * (1.0 - crowding) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual gap after placement.
    // Small dead-space classes are penalized superlinearly; perfect fits rewarded.
    let gap = post_residual;
    if gap == 0 {
        score -= 50.0; // perfect fit
    } else {
        // modulo classes on capacity: gaps that could host common small items are fine
        let mod10 = gap % 10;
        // gaps in [1..9] that are NOT multiples of 5/10 are awkward dead space
        if gap < 10 && mod10 != 0 && mod10 != 5 {
            score += 25.0 + (10 - gap) as f64 * 3.0;
        }
        if gap >= 10 {
            // residual still reusable: reward proportional to how it splits
            let half = gap / 2;
            score -= (half.min(30)) as f64 * 0.8;
            // bonus if residual can host the lookahead item exactly
            if next_item_size > 0 && gap == next_item_size {
                score -= 30.0;
            }
            if next_item_size > 0 && gap >= next_item_size {
                score -= 8.0;
            } else if next_item_size > 0 && next_item_size > 0 {
                // lookahead cannot fit here: mild penalty scaled by how much it misses
                let miss = (next_item_size - gap) as f64;
                score += miss * 0.15;
            }
        }
        // integer-division threshold: penalize gaps in (0,10) generally
        if gap / 10 == 0 {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no open bin is a good fit.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.75 {
            score -= 20.0 * (frac - 0.75) / 0.25;
        } else {
            score += 15.0 + 30.0 * (0.75 - frac);
        }
        // early stream: opening bins is cheap-ish; late stream: consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins first)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f).min(40.0) * 0.3;
    } else {
        score += (res_f - mean_residual).min(40.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small-but-usable gap: moderate penalty, worse the smaller it is.
        score += 2.0 * (20 - post_residual) as f64;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many bins open, discourage spreading items
    // across bins; prefer filling existing bins (favor small post_residual
    // implicitly) but slightly penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded
        // or the fit here would leave a bad gap.
        score += 25.0 + 5.0 * open_bins_count as f64;
        // Lookahead: if the next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward bins that can also fit the lookahead item.
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Penalize leaving a gap that blocks the next item.
        score += 10.0;
    }

    // Mild coupling with mean residual: prefer bins below mean residual
    // (fill the emptier-ish bins less, keep balanced capacity usable).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: exact packing is always desirable.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size,
    // penalize near-misses that strand unusable dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nxt;
        if diff == 0.0 {
            // Next item exactly consumes this bin's leftover: excellent chaining.
            score -= 150.0;
        } else if diff > 0.0 {
            // Next item fits, but leaves slack; penalize proportional dead space.
            score += 0.5 * diff;
            // Small slack (< 10) is likely unusable: extra penalty.
            if diff < 10.0 {
                score += 40.0;
            }
        } else {
            // Next item won't fit here: the residual becomes dead space.
            score += 0.3 * (-diff);
            if pr < 10.0 {
                score += 60.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when the item
    // fills a large fraction of the residual (good density), avoid spreading load.
    let frac = item_size as f64 / bin_residual as f64;
    if bin_residual < bin_capacity {
        if frac > 0.8 {
            score -= 50.0 * frac;
        } else if frac < 0.4 {
            score += 20.0 * (0.4 - frac);
        }
        // Prefer consuming bins with below-average residual (they are closest to closing).
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item is
    // large relative to capacity or current bins are nearly full / fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 120.0;
        // Large items pair well with a fresh bin (room for lookahead item too).
        new_bin_score -= 100.0 * big_item;
        if next_item_size > 0 && (next_item_size as u32 + item_size) <= bin_capacity {
            new_bin_score -= 60.0;
        }
        // Late in the stream, avoid proliferating bins with small loads.
        new_bin_score += 50.0 * progress;
        // Many open bins with high mean residual => fragmentation; a fresh bin is fine.
        if open_bins_count > 4 && mean_residual > 40.0 {
            new_bin_score -= 30.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later:
    // residuals below ~min item size (assume >=1, but penalize < 10 heavily).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here; mild reward proportional to leftover
            let leftover_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin; penalize if post_residual
            // is small (wasted capacity for the upcoming item).
            let gap = (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
            score += 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: many open bins -> discourage opening new ones (favor reuse).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 2.0 * openness * (1.0 - progress);

    // Mean residual coupling: bins with residual far below mean are precious
    // (large residual bins are flexible); prefer filling below-mean bins.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: an empty bin is flexible; only prefer it
    // when the fit here is poor. Penalize empty-bin choice mildly otherwise.
    if bin_residual == bin_capacity {
        // opening a new bin wastes nothing now but forgoes consolidation;
        // make it slightly unattractive unless post_residual is large.
        score += 15.0 - 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small dead space matters more (tighten), early it matters less
    let tighten = 1.0 + 1.5 * progress * progress;
    score *= tighten;

    // Penalize residuals that no plausible future item can use, scaled smoothly by progress
    let waste = norm_pr * norm_pr * (0.5 + 1.5 * progress);
    score += 25.0 * waste;

    // Lookahead: reward bins whose post_residual fits the next item, smoothly weighted
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= 8.0 * fit_next * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty for spreading across many open bins, smooth in count
    score += 0.15 * (open_bins_count as f64).powf(1.3) * (0.5 + 0.5 * progress);

    // New-bin candidate: neutral-ish baseline, penalized when decent fits exist,
    // favored when post_residual would be large in an existing bin (poor fit)
    if bin_residual == bin_capacity {
        score = 55.0 + 40.0 * progress - 0.2 * item_size as f64;
        // allow new bin when item barely fits any open bin (post_residual tiny gap)
        let gap = (bin_residual - item_size) as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        let _ = gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item-size divisors are more reusable. Reward low "harmonic distance".
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 { harmony += 1.0; }
        }
        score -= 2.0 * harmony;

        // Dead-space penalty: residual below the smallest plausible item
        // (and not zero) is nearly unusable.
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 8.0; }
    } else {
        // Perfect closure is ideal.
        score -= 15.0;
    }

    // Quantized fraction of capacity consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    let quant = (fill_frac * 4.0).round() / 4.0; // quarter-capacity classes
    score -= 5.0 * quant;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (harmonic chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score += 0.15 * slack;
        } else {
            // next item cannot use this bin's remainder at all
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when few bins fit; otherwise penalize so existing bins get used.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bonus = 12.0 * (1.0 - progress) + 4.0 * (open_bins_count as f64).ln();
        score -= new_bonus;
        if fitting_bins_count > 2 { score += 10.0; }
        if next_item_size > 0 && next_item_size as f64 > cap * 0.5 { score += 5.0; }
    }

    // Mild pressure toward bins tighter than the mean residual (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Small tie-break noise via integer-division hash on step and residual.
    let h = ((step_index as u64).wrapping_mul(2654435761) ^ (pr as u64)) % 7;
    score += h as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space that cannot even fit the smallest plausible item (<=10)
        if post_residual < 10 {
            score += 60.0;
        } else {
            // Nonlinear penalty: dead space that is large but still small
            // relative to typical items is wasteful.
            let r = post_residual as f64;
            if r < 20.0 {
                score += (20.0 - r) * 3.0;
            } else if r < 35.0 {
                score += 5.0 + (35.0 - r) * 0.5;
            }
        }
    } else {
        // Perfect fit is strongly rewarded.
        score -= 40.0;
    }

    // Reward tight fits relative to the item itself.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 10.0;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into fresh bins and encourage consolidating into existing space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // Mean residual coupling: if this bin's residual is far below the mean
    // (a "leftover" bin), penalize slightly; bins near the mean are safer targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if the next item fits in the post-residual, reward this choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If the next item almost fits (small gap), mild penalty for blocking it.
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it is only chosen
    // when all open bins score poorly (e.g. huge dead-space penalties).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if no open bin can fit, opening is fine (handled by fitting_bins_count==0
        // implicitly since only the new bin is a candidate then).
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.14;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: if post_residual is smaller than the
    // smallest plausible item (1), nothing is lost, but small non-zero
    // residuals below next_item_size are wasted unless tiny.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 6.0;
            if post_residual >= next_item_size && post_residual < next_item_size + 10 {
                score -= 4.0; // nearly perfect two-item packing
            }
        } else {
            // Dead space that the next item cannot use.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin unless the item fits
    // very poorly elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 8.0;
        // If many bins are open and mean residual is large, discourage new bins.
        score += 0.15 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (reduces bin count sprawl).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight reward for placing into bins whose residual is close to item size
    // (best-fit flavor with a soft margin).
    let margin = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += 0.08 * margin;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: quadratic dead-space penalty modulated by stream progress
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly early on
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Penalize bins far from mean residual (fragmentation dispersion)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 5.0 * (nx / cap);
        } else {
            score += 3.0 * (1.0 - pr_norm);
        }
    }

    // Mild pressure against spreading across many bins
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // New-bin candidate bias: prefer reusing open bins unless waste is huge
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division harmonic classes: post_residual falls into bands of size 10.
    let band = post_residual / 10;
    let band_center = (band * 10 + 5) as f64;
    let band_offset = post_residual as f64 - band_center;

    // Reward small band offsets (tight fit within its harmonic class).
    score -= 3.0 * (1.0 - (band_offset.abs() / 5.0));

    // Perfect fits get a strong harmonic bonus.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Post residual exactly matching next item's size is a perfect handoff.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Penalize residuals that no plausible item (1..=100) can use well:
    // dead space in (0, 10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class of next_item_size modulo capacity fractions:
    // if next item fits exactly in post residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let next_frac = next_item_size as f64 / bin_capacity as f64;
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            // next item fits: reward proportional to how little slack remains
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty scaled by closeness of miss
            score += 5.0 * ((-gap) as f64 / bin_capacity as f64).min(1.0);
        }
        // Modulo coupling: next_item_size harmonic class vs residual class
        let next_class = next_item_size / 10;
        if next_class == band {
            score -= 6.0; // same harmonic class -> likely compatible
        }
        let _ = next_frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current residuals are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.5;
        // But if stream is early, opening bins is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with residual far below mean (denser bins keep big residual bins flexible).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Fractional capacity coupling: reward post residuals that are nice fractions (0, 1/4, 1/2 of capacity).
    for &q in &[0u32, 25, 50, 75] {
        if post_residual == q {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small to hold even the smallest item
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Non-linear penalty on small but non-zero post_residual gaps (dead space zones)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0;
    }

    // Reward tight fits (post_residual near zero but usable)
    if pr >= 1.0 && pr <= 5.0 {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure
        score += 15.0 + bin_pressure;
        // But allow new bin if current item would leave a very tight squeeze elsewhere
        if fitting_bins_count >= 1 && (post_residual as f64) < 3.0 && bin_residual == bin_capacity {
            score -= 10.0;
        }
    } else {
        // Slight reward for using existing bins when many are open
        score -= bin_pressure * 0.3;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) == pr {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item won't fit here anyway; slightly reduce penalty for wasting space
        score += 2.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: mild reward proportional to tightness
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space a bit
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leaving small unusable residuals (< 10 typical min item)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer tighter bins relative to mean residual
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for reusing open bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins that absorb a large fraction of the item (denser packing).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead (k=2): favor residuals that can still host the next item.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else {
            score += 9.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many alternatives exist: mild penalty to keep options open for tight fits.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count.min(6) as f64 - 2.0);
    }

    // New-bin candidate: default penalty so open bins are used, but allow
    // opening when no open bin fits or the item is huge relative to stream.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size as u32 > item_size {
            score -= 8.0; // big item coming: fresh capacity valuable
        }
    }

    // Fragmentation guard: leaving residual far above the mean wastes capacity.
    if post_residual as f64 > mean_residual * 1.3 {
        score += 4.0;
    }

    // Late in the stream: slightly prefer consolidating into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr) - 0.35 * cap * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits more aggressively as the stream progresses (quartic in fill ratio).
    let fill = 1.0 - norm_pr;
    score -= 25.0 * fill.powi(4) * (0.5 + progress);

    // Penalize dead space that is too small for typical items (smooth dead-zone curve).
    if pr > 0.0 {
        let dead = (pr / 20.0).exp() * (-pr / 15.0).exp();
        score += 6.0 * dead * (1.0 - progress);
    }

    // Last-chance bin bonus: smooth ramp when few fitting bins remain.
    if fitting_bins_count <= 1 {
        score -= 12.0 + 8.0 * progress;
    } else {
        score -= 4.0 / fitting_bins_count as f64;
    }

    // Lookahead coupling: prefer bins whose post residual still fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - (pr - nx).abs() / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mild pressure to consolidate into fewer bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean-residual deviation term: favor bins near the mean to preserve spread.
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residuals that are "usable" sizes (small dead space)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residuals below smallest plausible item are worthless
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo-class logic: residuals divisible by common item sizes are more reusable
    let mut reusable = 0.0;
    for &d in &[10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            reusable += 8.0;
        }
    }
    score -= reusable;

    // Fractional capacity classes: quantify residual as fraction of capacity
    let frac = pr / cap;
    if frac < 0.1 {
        score += 15.0; // tiny sliver, near-dead
    } else if frac > 0.5 {
        score -= 10.0; // still roomy bin
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize less if residual still large
            score += 5.0 * (pr / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 5.0;

    // Mean-residual coupling: avoid leaving this bin far above mean (fragmentation)
    score += 0.3 * (pr - mean_residual).abs();

    // Late-stream tightness: as stream progresses, prefer tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post;

    let open_count = open_bins_count as f64;
    let open_sqrt = (open_count + 1.0).sqrt();
    let mean_res = if mean_residual.is_finite() { mean_residual.max(0.0) } else { 0.0 };
    let residual_health = if cap > 0.0 { (mean_res / cap).min(1.0) } else { 0.0 };
    let item_ratio = if cap > 0.0 { (item / cap).min(1.0) } else { 1.0 };

    let next_not_smaller = next_item_size >= item_size;
    let next_likely_elsewhere = next_item_size > 0
        && open_bins_count > 1
        && mean_res >= next
        && !(next_not_smaller && fitting_bins_count <= 1);

    if post_residual == 0 {
        score -= 5.0 + 0.07 * cap + 0.03 * item + 0.02 * open_sqrt;
    }

    let dead_gap = next_item_size > 0 && post_residual > 0 && post < next;
    if dead_gap {
        let severity = if bin_residual as f64 >= next { 1.0 } else { 0.55 };
        let lost = next - post;
        let crowd = 1.0 + 0.05 * open_sqrt + 0.20 * residual_health;
        let maturity = 0.80 + 0.40 * progress;
        score += (12.0 + 0.22 * cap) * severity * crowd * maturity + 0.25 * lost * severity;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = if cap > 0.0 { ((post - next) / cap).min(1.0).max(0.0) } else { 0.0 };
        score -= (1.0 + 0.04 * next + 0.015 * cap) * (1.0 - 0.25 * slack);
    }

    if is_new_bin {
        let mut pressure = 2.5 + 0.05 * cap + 0.35 * open_sqrt + 0.03 * mean_res + 0.10 * item_ratio;

        if fitting_bins_count >= 2 {
            pressure *= if next_likely_elsewhere {
                2.0 + 2.0 * (fitting_bins_count - 1) as f64
            } else {
                1.25
            };
        } else if fitting_bins_count == 1 {
            if open_bins_count <= 1 {
                pressure *= 1.25;
            } else if next_likely_elsewhere {
                pressure *= 3.50 + 0.50 * open_sqrt;
            } else {
                pressure *= 1.25;
            }
        }

        score += pressure;
    } else if fitting_bins_count == 1 {
        let mut last_chance = 2.0 + 0.04 * cap + 0.02 * open_sqrt;
        if dead_gap {
            last_chance *= 0.25;
        }
        score -= last_chance;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff); // perfect lookahead match gets big discount
        // If next item fits exactly into post_residual, strongly favor this bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize dead space that neither the next item nor typical small items can use.
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: minimize leftover waste directly.
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: prefer bins with below-average residual (tighter packing).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64) * 0.5).max(0.0);
        score = (bin_capacity as f64) * 0.6 + fragmentation * 0.5
            - (fitting_bins_count as f64) * 2.0;
        // Late in the stream, prefer reusing open bins more strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild penalty for very large dead space after placement.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals more aggressively (dead space grows superlinearly in waste).
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Reward tight fits (small post-residual relative to item).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= 8.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; penalize slightly more if we waste a lot.
            score += 0.15 * pr;
        }
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Time horizon: late in the stream, avoid opening new bins / leaving fragmented residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (pr / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        let excess = (mean_residual - pr).abs();
        score += 0.05 * excess * (open_bins_count.min(50) as f64).ln().max(1.0);
        // If this bin is below mean residual, it's a good filler target.
        if (pr as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // New-bin candidate: make it moderately costly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress;
        // But if item is huge and leaves little dead space, a fresh bin is attractive.
        if post_residual <= 10 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 6.0 * norm_pr * progress;
    // penalize tight fits more as stream progresses (dead space matters later)
    score += 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // lookahead: reward residual that can hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 5.0 * (1.0 - nx / cap);
        } else {
            let gap = (nx - pr) / cap;
            score += 6.0 * gap * gap * cap * 0.1;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }
    // prefer bins below mean residual slightly (balance load)
    score += 2.0 * (pr - mean_residual) / cap;
    // new-bin candidate: penalize mildly, but allow when fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (1.0 - norm_pr) * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Penalize post_residuals that are "unusable" classes.
    // Since items are 1..=100, residual < smallest plausible next item is dead space.
    // Class thresholds via integer division on post_residual.
    let cls = post_residual / 10; // harmonic class 0..=10
    match cls {
        0 => score -= 50.0,          // tiny residual, nearly perfect
        1 => score += 5.0,           // 10..19: moderately reusable
        2 => score += 10.0,          // 20..29
        3 => score += 12.0,          // 30..39
        4 => score += 15.0,          // 40..49
        5 => score += 18.0,          // 50..59
        6 => score += 20.0,          // 60..69
        7 => score += 22.0,          // 70..79
        8 => score += 24.0,          // 80..89
        9 => score += 26.0,          // 90..99
        _ => score += 30.0,          // full-ish bin (new bin candidate)
    }

    // Lookahead: does next item fit into post_residual? Reward exact/near couplings.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
            // Harmonic bonus: post_residual is a multiple of next_item_size
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this residual: penalize more for mid-range waste
            score += 8.0 * (1.0 - frac);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when residual would be large AND
    // mean residual across open bins is already high (open bins are fragmented)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        // penalize new bins normally, discount when open bins are fragmented
        score += 40.0 - 60.0 * fragmentation * (0.5 + 0.5 * progress);
        // early stream: prefer filling existing bins
        if progress < 0.2 {
            score += 25.0;
        }
    }

    // Mild preference to balance load across bins: avoid extreme imbalance
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1
    // is guaranteed, but small gaps below typical item sizes are near-useless).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 12.0; // awkward gap zone
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space relative to lookahead item: gap that cannot host next item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // gap remains usable for lookahead
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins / spreading).
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 {
            score += 30.0; // discourage bypassing existing fitting bins
        }
        if mean_residual < 20.0 {
            score -= 20.0; // existing bins nearly full -> new bin is fine
        }
    }

    // Slight preference for bins below mean residual (balance load).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Early in stream: be pickier about tight fits (more future items to serve).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but dead space below the smallest plausible
    // follow-up item is pure waste — penalize it super-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Post-residual can host next item AND still leave usable space
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 15.0;
    }

    // Relative-to-mean coupling: a bin with residual far below the mean is
    // already "cramped"; using it well avoids fragmenting fatter bins.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel); // prefer consuming low-residual bins
        } else {
            score += 3.0 * (rel - 1.0).min(2.0); // mild penalty for raiding fat bins
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
        // But if the fit leaves a large hole, soften the bonus.
        if post_residual > bin_capacity / 3 {
            score += 12.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit — make the fresh bin moderately unattractive
    // so tight existing placements win, but keep it competitive vs. awful fits.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 18.0;
        // Late in the stream, opening fresh bins is cheaper than fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference to keep the number of open bins low early on.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize awkward residuals: leftover space too small for typical items.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 10 {
            score += 25.0 * (1.0 - dead); // tiny dead space is wasted capacity
        } else if post_residual < 30 {
            score += 8.0 * dead; // mildly awkward
        } else {
            score -= 4.0 * dead; // large residual stays reusable
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / (bin_capacity as f64));
        }
    }

    // Prefer filling bins with residuals near the mean (keeps bin pool balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 2.0 * dev / (bin_capacity as f64);

    // Time horizon: early in stream, be conservative about opening new bins;
    // late in stream, consolidate into existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a bin is attractive when current bins
    // would be badly fragmented or when item barely fits anywhere.
    if bin_residual == bin_capacity {
        let mut nb = 15.0; // base cost of opening a new bin
        nb -= 20.0 * progress; // later items: cheaper to open new bins? no—favor consolidation
        if fitting_bins_count == 0 {
            nb = -1000.0; // must open
        }
        // If item is large relative to capacity, new bin gives perfect fit potential
        if item_size * 5 >= bin_capacity * 4 {
            nb -= 12.0;
        }
        // If many open bins fit the item, opening new bin is wasteful
        if fitting_bins_count >= 3 {
            nb += 15.0;
        }
        // If mean residual is large, existing bins have room; discourage new bin
        nb += 0.3 * mean_residual;
        score = nb;
    }

    // Slight penalty for using many bins when few would do.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, prefer tight fills (low post_residual); later,
    // weight residual waste more heavily via smooth polynomial terms.
    let w = 0.5 + 1.5 * progress;
    score += w * norm_post * norm_post * (bin_capacity as f64);

    // Reward tight fits with a smooth cubic discount scaled by progress.
    let tightness = 1.0 - norm_post;
    score -= (0.5 + progress) * tightness * tightness * tightness * (item_size as f64);

    // Lookahead coupling: if next item fits smoothly in post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= (1.0 - progress) * (1.0 - gap * gap) * 8.0;
    } else if next_item_size > post_residual {
        // Penalize leaving a residual that cannot host the next item.
        score += (1.0 - progress) * 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight penalty for bin hoarding when many bins are open relative to mean residual.
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 0.05 * (open_bins_count as f64).ln() * (1.0 - (norm_post - mean_norm).abs());

    // New-bin candidate adjustment: make empty bins mildly attractive only for
    // large items or when mean residual across open bins is small.
    if bin_residual == bin_capacity {
        let attract = 0.5 * norm_item + 0.5 * (1.0 - mean_norm);
        score += 12.0 - 14.0 * attract;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it falls into.
    // Bins whose leftover lands on "nice" modular classes are more reusable.
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12
    let post = post_residual as i64;

    // Reward residuals that are multiples of small harmonic units (8, 16, 25, 50).
    if post % (eighth as i64) == 0 {
        score -= 6.0;
    } else if post % (quarter as i64) == 0 {
        score -= 5.0;
    } else if post % 16 == 0 {
        score -= 4.0;
    } else if post % 8 == 0 {
        score -= 2.5;
    }

    // Penalize dead space: residual too small to hold any plausible item (min size 1..10 band).
    let small_threshold = eighth; // 12
    if post > 0 && post < small_threshold as i64 {
        score += 15.0; // nearly unusable sliver
    } else if post < quarter as i64 {
        score += 4.0; // tight band: hard to refill
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 12.0;
        } else if next_item_size < post_residual as u32 {
            // harmonic match: next item leaves another clean residual
            let next_post = post_residual as i64 - next_item_size as i64;
            if next_post % (eighth as i64) == 0 || next_post % (quarter as i64) == 0 {
                score -= 5.0;
            }
            if next_post < small_threshold as i64 {
                score += 6.0; // chains into dead space
            }
        } else {
            // next item won't fit here; slightly favor bins that still keep post flexible
            score += 1.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post >= 0 {
        score -= 10.0;
        if post < small_threshold as i64 {
            score -= 6.0; // still worth it: avoids a whole new bin
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in the stream or when few bins fit.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        score = bin_capacity as f64 - 8.0 * pressure + 20.0 * (1.0 - progress) - 10.0 * progress;
        // Discourage opening new bins when mean residual across open bins is still large.
        score += 0.15 * mean_residual;
    }

    // Mild global balance: prefer bins below the mean residual (tighter bins first),
    // keeping larger residuals for future big items.
    score += 0.05 * (mean_residual - bin_residual as f64).abs() * 0.5
        - 0.03 * (bin_residual as f64 - mean_residual);

    // Progress-based tie-break: early on, consolidate (prefer low post_residual);
    // late in stream, slight preference to fill tightest bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap is "dead" if it cannot hold the smallest plausible item (<= 10 or next item).
    let min_gap = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_gap {
        score += 40.0; // tiny useless gap -> strong penalty
    } else if post_residual <= 15 {
        score += 18.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer packing into existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual < bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New-bin candidate: penalize unless it promises a great future fit.
        score += 10.0 + 6.0 * pressure;
        if next_item_size > 0 && next_item_size as f64 >= 0.9 * bin_capacity as f64 {
            score -= 20.0; // next item is huge, fresh bin is valuable
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // lookahead fits this bin too
        }
    }

    // Lookahead synergy: reward bins whose post-residual accommodates next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // creates a gap that blocks the lookahead
    }

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step fit: residual fully consumed next turn
        } else if post_residual >= next_item_size {
            // partial lookahead credit, stronger the closer the match
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (-gap / 15.0).exp();
        } else {
            // dead space: next item cannot use this residual
            let waste = (next_item_size - post_residual) as f64;
            score += 6.0 + 0.15 * waste;
        }
    }

    // Penalize residuals far below mean residual (fragmented bin)
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Slight penalty for very tight fits that leave tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Late in the stream: consolidate, prefer filling existing bins over new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress; // new-bin candidate penalized more later on
    } else {
        score -= 3.0 * progress;
    }

    // Prefer bins with larger current residual when everything else is close
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post-residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 25 {
        score += 12.0 * (25.0 - post_residual as f64) / 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly and the item is large.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual < 20 { 1.0 } else { 0.0 };
        score += 30.0 - 35.0 * poor_fit;
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // If item is small, opening a fresh bin wastes capacity.
        if item_size < 40 {
            score += 15.0;
        }
    }

    // Lookahead coupling: if the next item could use this bin's post-residual,
    // reward leaving that exact gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item fits here now but not after this placement: penalize.
            score += 8.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage filling
    // existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > item_size as f64 * 2.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Late stream: squeeze remaining capacity harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) - pr_norm * (0.5 + progress);
    score += 40.0 * poly;

    // Penalize tight fits that leave near-zero dead space less harshly as stream advances.
    let tight = 1.0 - pr_norm;
    score -= 25.0 * tight * tight * (0.5 + progress);

    // Reward bins whose post-residual matches the lookahead item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * mean_residual / cap;

    // New-bin candidate: neutral-ish baseline, slightly worse late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Penalize dead space non-linearly; tiny residuals (<10) are near-perfect fits
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, strongly favored
    } else if post_residual < 10 {
        score -= 200.0;
    } else {
        // modulo arithmetic classes on post_residual (harmonic buckets)
        let bucket = post_residual / 10; // 0..10 integer division threshold
        score += (bucket as f64) * (bucket as f64) * 3.0; // quadratic dead-space penalty
        score += frac * 50.0;
    }

    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * next_item_size as f64;
        // harmonic match: residual class equals next item class mod 10
        if post_residual % 10 == next_item_size % 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that the next item cannot use
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer fuller bins when many bins are open (contain open-bin proliferation)
    score += 2.0 * open_bins_count as f64 * frac;

    // Early in stream: encourage exploration of new bins slightly less aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * (1.0 - progress) * frac;

    // New-bin candidate: neutral baseline; only chosen when all open bins score poorly
    if bin_residual == bin_capacity {
        score = cap - 0.5 * mean_residual + 10.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size >= item_size {
            score -= 80.0; // open fresh bin when existing fit is last-chance and next item is big
        }
    }

    // Mean-residual coupling: avoid bins far below the mean fullness (fragmentation)
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
