    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 40.0;
    }
    // Penalize any residual below 10 (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
