    }

    // Open-bin pressure: many open bins -> favor filling existing ones,
    // and penalize opening new bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + 3.0 * open_pressure;
        // But if no open bin fits, new bin becomes attractive naturally
        // (other candidates carry dead-space penalties).
        if fitting_bins_count == 0 {
