    // New-bin candidate: prefer it only when open bins have poor residuals
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual (concentrate filling)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good via base term.
    // Penalize large post_residual non-linearly (dead space that likely can't be reused).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.05;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else {
            score += gap as f64 * 0.35;
        }
    }
    // If next item cannot fit in post_residual, mild penalty scaled by how much it misses.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.12;
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless the current
    // residual is small/unusable. Penalize new bins when mean residual across open
    // bins is large enough to absorb future items.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0;
        // If mean residual of open bins is generous, discourage new bins more.
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
        // Early in the stream, new bins are cheaper; later, consolidation matters.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        // If many bins are open, avoid adding more.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Reward using bins whose residual is below the smallest possible item (10),
    // since they are otherwise dead space — filling them with anything is good.
    if bin_residual < bin_capacity && bin_residual - item_size < 10 && post_residual > 0 {
        score -= 8.0;
    }

    // Coupling with mean residual: prefer bins below the mean residual (tighter bins),
    // which keeps looser bins available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.08;

    // Mild time-horizon effect: as stream progresses, prioritize exactness more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (100.0 - post_residual as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: dead-space penalty grows quadratically with stream progress
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress);
    score += 20.0 * coupling;

    // Reward tight fits via smooth cubic term in item utilization
    let util = item_size as f64 / cap;
    score -= 10.0 * util * util * util * (1.0 - progress);

    // Last-chance bonus: strongly favor the single fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (packing denser bins first), smoothly
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Lookahead: penalize leaving residuals that barely fail to fit the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if pr < next_item_size as f64 {
            score += 0.3 * (next_item_size as f64 - pr);
        } else {
            score -= 0.3 * (1.0 - gap / cap);
        }
    }

    // New-bin candidate: smooth penalty decreasing with progress (late stream: reuse more)
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (dead space) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity occupancy after placement
    let fill = 1.0 - pr / cap;
    score -= 30.0 * fill * fill; // reward high fill quadratically

    // Modulo/harmonic classes on post_residual (C=100 base, scaled by capacity)
    let unit = (bin_capacity / 10).max(1);
    let cls = post_residual / unit; // 0..=10 harmonic class
    match cls {
        0 => score -= 25.0,           // perfect fit
        1 => score -= 10.0,           // tiny gap, likely dead space but great fill
        2 | 3 => score -= 3.0,        // medium-small gap
        4 | 5 | 6 => score += 2.0,    // mediocre
        _ => score += 6.0,            // large gap remains
    }

    // Dead-space penalty: gap too small for the smallest plausible item
    let min_item = (item_size.min(if next_item_size > 0 { next_item_size } else { item_size })).max(1);
    if post_residual > 0 && post_residual < min_item {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            score -= 12.0 * (1.0 - npr as f64 / cap);
        } else {
            // next item cannot follow here; mild penalty proportional to overflow
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded && open_bins_count > 0 {
            score -= 8.0 + 10.0 * progress;
        } else {
            score += 12.0; // prefer reusing open bins normally
        }
    }

    // Slight preference for tighter bins among equals
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..=100 stream, but
    // practically gaps below ~15 rarely get filled). Penalize non-linearly.
    if post_residual > 0 {
        let dead = if post_residual < 15 {
            (15 - post_residual) as f64 * 6.0
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits generally: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        if next_fit < 10 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual cannot host the next item: mild dead-space penalty.
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (new-bin candidate has bin_residual == bin_capacity, gets penalized).
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    } else {
        // Mild preference to fill existing bins when many are open.
        score -= 0.15 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate space).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Early in the stream, be slightly more willing to open bins (build diversity);
    // later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: penalize post_residual quadratically so tight fits win.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);

        // Exact 2-step chain: item + next item fills bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: only tightness matters.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate: make empty bins moderately unattractive so we prefer
    // existing bins with good fits, but attractive when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening new bins is less costly than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Penalize spreading across many open bins when residuals are already small.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 + 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward leftovers.
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).min(1.0);
        }
    }

    // Time horizon: early in the stream, be more open to new bins (exploration);
    // later, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins are few.
        score += 12.0 * progress + 2.0 * open_bins_count as f64;
        // Allow new bin early if current bin fits poorly.
        if fit_ratio > 0.6 && progress < 0.4 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward slightly more late in the stream.
        score -= 5.0 * progress;
    }

    // Coupling with mean residual: placing into a bin far from the mean residual
    // helps balance residual distribution; prefer bins near mean or below it.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.06 * diff.abs();

    // Prefer filling larger-residual bins when many bins are open (reduce fragmentation).
    score -= 0.03 * bin_residual as f64 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate slack (fill fast); late: strongly punish residual waste.
    let t = progress.clamp(0.0, 1.0);
    let decay = 1.0 + 2.5 * t * t + 1.5 * t * t * t;
    score += 0.35 * pr * pr / cap * decay;

    // Reward tight fits (small post_residual relative to item) with smooth saturation.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: if next item fits into post_residual, bonus (smooth).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = (pr / nxt).min(2.0);
        score -= 3.0 * (fit_ratio * fit_ratio) / (1.0 + fit_ratio);
    } else {
        // Last item: minimize residual aggressively.
        score += 0.5 * pr;
    }

    // Mean-residual coupling: prefer bins below mean residual (fill emptier bins first,
    // keeps many mid-size residuals alive) — smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.1;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; more so as fitting bins exist and progress grows.
        score += 6.0 + 4.0 * t;
        // But if the item is large relative to capacity, a fresh bin is attractive.
        score -= 6.0 * (item / cap) * (item / cap) * 4.0;
    }

    // Slight preference for fewer open bins (compactness) — smooth.
    score += (open_bins_count as f64).ln() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class of post_residual: modulo classes on capacity fraction
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => -60.0,
        1..=5 => -35.0,          // near-perfect: dead space is tiny
        6..=15 => -10.0,
        16..=30 => 0.0,
        31..=45 => 5.0,
        46..=60 => 10.0,
        _ => -5.0,               // large residual still flexible
    };
    score += class_bonus;

    // Divisibility structure: residuals divisible by common item sizes are reusable
    if pr > 0 {
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                score -= 8.0;
            }
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            score += (next_item_size - pr).min(30) as f64 * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = mean_residual / cap;
        // opening a new bin is penalized mildly, more when bins are mostly empty
        score += 30.0 + 40.0 * congestion - 20.0 * progress;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 15.0; // an open bin could take it; discourage new bin
        }
    }

    // Mild tie-break: prefer fuller bins (lower residual already does this),
    // but add small penalty proportional to open bins to consolidate
    score += open_bins_count as f64 * 0.05;

    // Harmonic coupling: integer division threshold on item_size classes
    let item_class = item_size / 20; // 0..4 coarse class
    score -= (item_class as f64) * 1.5; // bigger items slightly favored into existing bins

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
