    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 55.0;
        // More open bins with fragmented residuals -> opening a new bin is more acceptable.
        let frag = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        score -= 0.15 * open_bins_count as f64;
        score += 0.2 * frag;
        // Early in stream, new bins are cheaper (long horizon to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into fuller bins.
    if !is_new_bin {
        let deviation = mean_residual - bin_residual as f64;
        score += 0.3 * deviation;
    }

    // Time horizon: later in the stream, be more conservative, prefer exact consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: post_residual shaped by stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 20.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead: penalize leaving residual that barely fails next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = pr - nx;
            score += 0.03 * gap;
        } else {
            score += 6.0 * (nx - pr) / bin_capacity as f64;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * tightness;
    }

    // Penalize divergence from mean residual (smooth quadratic)
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / (bin_capacity as f64);

    // Mild new-bin preference when current bin would leave large dead space
    score += 8.0 * pr_norm * pr_norm * pr_norm * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by modulo classes
    // Residuals divisible by large chunks (>=20) are reusable; tiny ones are dead.
    let pr = post_residual;
    let class = pr / 20; // 0..5 harmonic class
    // Penalize small classes (unusable slivers), reward large reusable classes
    score += match class {
        0 => 60.0,               // 0..19: dead space
        1 => 20.0,               // 20..39
        2 => 0.0,                // 40..59
        3 => -15.0,              // 60..79
        _ => -30.0,              // 80+: nearly fresh bin
    };

    // Fine-grained modulo: residuals that are multiples of 10 pair well with
    // typical item sizes (multiples of 10 dominate many streams)
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 10 != 0 {
        score += (pr % 10) as f64 * 0.8;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward proportionally to how well next item uses leftover
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
            if pr == next_item_size {
                score -= 60.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here: leftover is likely dead
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // current fit is poor (large post_residual waste relative to capacity)
    if bin_residual == bin_capacity {
        let waste_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        // opening a new bin costs ~1 bin; prefer it if this placement wastes a lot
        score = 30.0 + waste_ratio * 20.0;
        if fitting_bins_count <= 1 {
            score -= 70.0; // no good alternative: open new bin
        }
    }

    // Progress-aware tightening: later in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mean residual context: if mean residual is high, tighten less aggressively
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 0.5;

    // Pressure from many open bins: prefer filling existing bins when crowded.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize unless item is large relative to residual
    // or the fit into open bins would be poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size > 60 {
            score -= 10.0;
        }
        if post_residual < 10 {
            score -= 6.0;
        }
    }

    // Lookahead: if next item could use the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }
    // If next item is close to post_residual but slightly bigger, penalize.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 4.0;
    }

    // Early stream: mild preference for compacting into few bins.
    let progress = step_index as f64 / total_items as f64;
    score -= (1.0 - progress) * 1.0;

    // Prefer bins with residual near mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with little waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 2.0;
    }
    // Next item does NOT fit: dead space penalty scaled by gap
    else if next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 3.0;
    }

    // Penalize tiny unusable post_residual (dead space), except perfect match already handled
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward filling bins tightly relative to mean residual
    score -= (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: expensive unless current item is large and residuals are small
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Opening a new bin is good for large items when open bins are fragmented
        let open_bonus = if item_frac > 0.6 && mean_frac < 0.35 { -80.0 } else { 0.0 };
        score = bin_capacity as f64 - open_bonus + (1.0 - item_frac) * 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space that nothing else can use (post_residual < next item).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Reward bins whose leftover can host the lookahead item.
            score -= 4.0;
        }
        // If lookahead fits exactly after this placement, strong reward.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Tight fits are good: reward small relative waste.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 6.0;

    // Penalize leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Time horizon: early on, prefer keeping bins flexible (moderate residual);
    // late in stream, prefer filling bins tightly and avoid new bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if t > 0.7 {
        score -= post_residual as f64 * 0.3; // squeeze existing bins late
    } else {
        // Early: prefer bins with residual near mean to balance load.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Prefer reusing bins when many are open (consolidation pressure).
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // Make new-bin candidate less attractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Open a fresh bin early if current item is large and next is large too.
        if next_item_size >= 70 && item_size >= 50 && t < 0.5 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly damped
    let mut score = pr;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, large residuals are fine (penalize less); late, waste hurts more.
    let waste_penalty = norm_pr * norm_pr * (1.0 + progress) * 40.0;
    score += waste_penalty;

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tight_reward = (1.0 - norm_pr).powi(3) * 30.0;
    score -= tight_reward;

    // Last-chance bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // many fitting bins: mild penalty to prefer best-fit discrimination
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead coupling: if next item fits smoothly into post_residual, reward
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        let fit_next = if pr >= ni { 1.0 } else { 0.0 };
        // smooth interaction: reward when next item nests into leftover
        score -= fit_next * (1.0 - gap / cap).powi(2) * 15.0;
        // penalize leaving exactly a tiny sliver the next item can't use
        let sliver = (1.0 - (pr / cap).powi(2)) * (ni / cap).powi(2) * 10.0;
        score += sliver * (1.0 - fit_next);
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's an outlier;
    // gently prefer bins near the mean to keep residual distribution compact.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 20.0;

    // Smooth progress-driven opening bias: late in the stream, slightly discourage
    // opening new bins (favor consolidation) via interaction with residual.
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (8.0 + 12.0 * progress + norm_pr * 0.0);

    // Mild penalty proportional to open bins count to discourage bin sprawl
    score += (open_bins_count as f64).powf(0.5) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: residues mod 10 (classic harmonic bin classes).
    let residue_class = (post_residual % 10) as f64;
    score -= (10 - residue_class) * 0.8; // prefer leftovers that sit on class boundaries (multiples of 10)

    // Dead space penalty: leftovers below the smallest plausible item cannot be reused.
    if post_residual < 10 {
        score += 60.0;
    }

    // Prefer post_residual that can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.15;
            // bonus if it also fits a second time (harmonic pairing)
            if post_residual >= next_item_size * 2 {
                score -= 6.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Integer-division thresholds: how many "average items" still fit after placement.
    let slots = (post_residual / 25) as f64;
    score -= slots * 4.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if post_residual > 0 {
            // opening a new bin wastes the residual of every other open bin
            score += open_bins_count as f64 * mean_residual * 0.35;
            if fragmentation > 0.45 {
                score -= 30.0; // fragmented state: fresh bin is fine
            }
        } else {
            score -= 500.0; // exact fit into a fresh bin is fine
        }
    }

    // Mild pressure to close bins early when many bins are open.
    score += (post_residual as f64) * (open_bins_count as f64) / (bin_capacity as f64) * 0.5;

    // Stream progression: later in the stream, be more aggressive about filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (keeps bin states uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically tiny gaps < 12 are waste)
    // are heavily penalized in a non-linear way.
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * (12.0 - post_residual as f64) * 2.5;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it can use the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: mild penalty for wasted potential.
        score += 4.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one;
    // the new-bin candidate has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + open_bins_count as f64 * 3.0 + progress * 10.0;
    } else {
        // Slight preference for tighter (smaller-residual) bins beyond raw post_residual.
        score += (bin_residual as f64) * 0.05;
    }

    // Coupling with mean residual: bins far below mean residual are "fresher";
    // prefer filling bins with residual near or below the mean.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            // Prefer the bin where next item leaves the least leftover after two placements.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 400.0; // perfect 2-item chain
            }
        } else {
            // Next item cannot follow here; penalize proportionally to wasted potential.
            let waste = nxt - post_residual as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 50.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when reasonable fits exist, more so early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 * (1.0 - 0.5 * progress);
    }

    // Slight preference for bins with more open competition (spread load evenly).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // awkward zone
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0; // next item leaves near-perfect fit
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 5.0; // next item won't fit here; dead end risk
        }
    }

    // Time horizon: early in the stream, be more willing to spread load;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are underutilized.
        score += 10.0 + 0.15 * mean_residual + 1.5 * open_bins_count as f64;
        // But if no open bin fits well (this item is huge relative to mean residual),
        // soften the penalty so a fresh bin can win.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late stream: opening a new bin is riskier.
        score += 8.0 * progress;
    } else {
        // Reward filling bins whose residual is above mean (balance across bins).
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.05 * dev;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let r2 = r * r;
    let r3 = r2 * r;
    // smooth polynomial coupling of residual with stream progress
    score -= (1.0 - r) * (1.0 - r) * (1.0 + t);
    score += r3 * (0.5 + t);
    // lookahead: reward bins whose post-residual fits next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0 * (1.0 - t);
    }
    // penalize near-empty usage of open bins late in stream
    score += (r - mean_residual / bin_capacity as f64).abs() * (1.0 + 2.0 * t);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }
    // new-bin candidate: penalize unless residual waste would be large
    if bin_residual == bin_capacity {
        score += 2.0 - 4.0 * (1.0 - r2) * t;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual in low harmonic classes
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if frac < 0.25 {
        score -= 8.0;
    } else if frac < 0.5 {
        score -= 2.0;
    } else {
        // large leftover: penalize more the bigger it is
        score += 5.0 * frac;
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits perfectly or well here: strong reward
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 30.0;
            } else if next_post <= 10 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
        } else if next_item_size <= bin_residual {
            // next fits only before placing (unlikely relevant) — mild penalty
            score += 2.0;
        } else {
            // next item won't fit here regardless: this bin should absorb current item
            score -= 10.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 25.0;
        // early in stream, new bins are cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // many open bins with high mean residual: prefer reusing
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // prefer bins whose residual is close to item (best fit)
        score += (bin_residual as f64 - item_size as f64).abs() * 0.3;
    }

    // modulo harmonic class of post_residual: small residues mod 10 are more reusable
    let m = post_residual % 10;
    if m == 0 && post_residual > 0 {
        score -= 3.0;
    } else if m <= 3 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 0.5;

    // Slight preference toward bins tighter than average (better consolidation).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + item_size as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64 - post_residual as f64).abs();
        if next_item_size <= post_residual {
            score -= 2.0 * next_fits + 10.0;
        } else {
            // next item can't use the leftover: penalize dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins tighter than the mean residual
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist with decent fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 0.3 * mean_residual;
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (<=100 cap).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits the post-residual, reward this placement strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 + 20.0 * chain_fit;
        } else {
            score += 10.0; // breaks the chain
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).sqrt());
    score += 8.0 * pressure * (bin_residual == bin_capacity) as i32 as f64;

    // Time horizon: early on, allow spreading (new bins); late, pack densely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64 * -1.0;

    // Global residual balance: prefer bins whose residual is near the mean (keeps fleet uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic coupling of post residual with stream progress.
    // Early on, prefer tight fits (low post residual); later, residual
    // becomes less costly so scale its weight down.
    let progress_weight = 1.0 + 0.8 * progress * progress;
    let mut score = post * (1.0 - 0.35 * progress) + progress_weight * norm_post * norm_post * cap * 0.5;

    // Smooth interaction: dead space that cannot fit the next item is worse.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = post - nx;
        if gap > 0.0 {
            let unusable = (gap / cap).min(1.0);
            score += 25.0 * unusable * unusable * (1.0 - progress);
        } else {
            // Reward bins that can also host the lookahead item (chaining).
            score -= 8.0 * (nx / cap) * (1.0 - 0.5 * progress);
        }
    }

    // Last chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - norm_post);
    }

    // Penalize spreading across many open bins; encourage consolidation
    // smoothly via mean residual deviation.
    let dev = (mean_residual - post).abs() / cap;
    score += 5.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: make empty bin attractive only when open bins
    // would leave large unusable residue or few fitting options exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let openness = (open_bins_count as f64 / (1.0 + mean_residual / cap)).tanh();
        score = cap * (0.9 - 0.25 * progress) - 20.0 * pressure * (1.0 - openness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Harmonic class of post_residual: residues that are "dead space"
    // (too small to hold typical items) get penalized via modulo classes.
    let pr = post_residual;
    if pr > 0 {
        let dead = if pr < 10 { 1.0 } else { 0.0 };
        score += 40.0 * dead;
        // Modulo-10 class: residuals near multiples of 10 are more reusable.
        let m = pr % 10;
        let class_penalty = if m == 0 { -8.0 } else if m <= 2 { 4.0 } else if m >= 8 { 6.0 } else { 0.0 };
        score += class_penalty;
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // Integer-division threshold: post_residual bucket by capacity fraction.
    let quarter = bin_capacity / 4;
    if pr >= quarter && pr < 2 * quarter {
        score -= 6.0; // can host medium items
    } else if pr < quarter && pr > 0 {
        score += 10.0; // risky sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 12.0;
        } else {
            // Next item won't fit here; mildly penalize leaving large residual.
            score += 5.0;
        }
        // Harmonic pair: item_size + next_item_size divides capacity class.
        let s = item_size + next_item_size;
        if s == bin_capacity {
            score -= 25.0;
        } else if bin_capacity % s == 0 && s <= bin_capacity {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is expensive; make it
    // attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32;
        if pressure == 1 {
            score -= 20.0; // must open a new bin
        } else {
            score += 25.0 + 10.0 * (open_bins_count as f64).min(5.0); // discourage wasting fresh bins
        }
    }

    // Late in stream: consolidate; fewer open bins preferred.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.5;

    // Mean residual context: if this bin is far from mean residual, nudge.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

