    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Gaps that can still host a typical item are mildly rewarded.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Prefer bins whose residual was already tight (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Open-bin pressure: with many open bins, discourage spreading; opening
    // a new bin (residual == capacity) is penalized proportionally.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
