    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mild normalization by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect lookahead match: next item still fits snugly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 / (post_residual as f64 + 1.0)) * 50.0;
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (post_residual as f64) / (next_item_size as f64);
        score += (1.0 - waste) * 30.0;
    }

    // Strongly prefer tight fills relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 2.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving very small unusable slivers (< 10, minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    }

    // New-bin candidate: neutral-ish baseline; slightly discourage early on,
    // allow it when open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = bin_capacity as f64 - mean_residual;
        score = bin_capacity as f64 - 60.0 * progress + (avg_fill / bin_capacity as f64) * 120.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits, must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
