pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: reward tight fits via non-linear decay of post_residual
    let mut score = norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of fit quality with stream progress:
    // early on, prefer filling bins tightly; later, weight dead space more heavily
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * fit_norm * cap * 0.5;

    // Penalize leaving residuals that are unusable for typical items,
    // with a smooth bump around small-but-nonzero residuals
    let dead = (norm_pr * (1.0 - norm_pr)).sin();
    score += dead * dead * 8.0 * (0.3 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward residuals that still fit the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        let kernel = (-diff * diff / (2.0 * 20.0 * 20.0)).exp();
        score -= kernel * 12.0 * (1.0 + progress);
    }

    // Mild pressure against spreading across many open bins when mean residual is high
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - progress);

    // New-bin candidate handling: make empty bin attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        score = cap * 0.9 + mean_residual * 0.3 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item sizes (mod classes 10..=80) are far more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Reward residuals that fall on "harmonic" grid points (multiples of 5/10).
    let harmonic_bonus = if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -9.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: tiny unusable leftovers (below smallest plausible item).
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Integer-division thresholds: bucket post_residual into capacity fractions.
    let frac = pr as f64 / cap;
    if frac < 0.1 {
        score += 12.0; // nearly-full bin: good, keep it attractive
    } else if frac > 0.5 && pr % 20 != 0 {
        score += 6.0; // large awkward leftover not on 20-grid
    }

    // Lookahead coupling: if next item fits exactly into the post residual
    // (harmonic pairing), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 25.0;
        } else if next_item_size > pr {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the current item is large relative to capacity
    // or no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * cap;
        if big_item || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 10.0; // discourage wasteful new bins for small items
        }
    }

    // Progress-aware tightening: late in the stream, be greedier about
    // filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any gap that no plausible future item (>=1)
    // can use is pure waste; gaps too small for typical items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable dead space
        } else if post_residual < 20 {
            score += 18.0; // nearly unusable
        } else if post_residual < 30 {
            score += 7.0;
        }
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness coupling: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills;
    // few open bins -> allow opening new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + 2.0 * progress);
    score += 3.0 * pressure;

    // If bin residual deviates strongly above mean residual, it's roomier than
    // average; slight bonus to place there when open-bin count is high.
    if open_bins_count > 2 {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        }
        // Penalize leaving a gap the next item almost fits (wasted potential).
        if post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
            score += 10.0;
        }
    }

    // New-bin candidate: neutral baseline that competes only when open bins
    // would create dead space. Make it attractive when open-bin pressure is high
    // and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let base = 55.0 + 2.5 * pressure - 8.0 * progress;
        // If the only alternative is a poor fit, opening fresh is fine.
        score = score.min(base);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins whose post_residual matches the next item exactly (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.5;

        // Strong reward for exact chain: post_residual == next_item_size.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement; mild reward proportional to tightness.
            score -= (next_item_size as f64) * 0.3;
        } else {
            // Next item will NOT fit: penalize dead space relative to item size.
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Tight fit reward: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.2;

    // Penalize deviating from mean residual (keep bin population balanced).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless it looks genuinely better
    // (e.g., many open bins already, or item is large relative to residuals).
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (mean_residual.max(1.0));
        score += 20.0;
        if pressure > 1.0 && open_bins_count > 3 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for wasting space
            score += 2.0;
        }
    }

    // Prefer filling bins with low residual relative to mean (balance avoidance of fragmentation)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early on, be conservative about opening bins; late, fill aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount late
        score += 25.0 * (1.0 - progress) - 5.0 * progress;
    } else {
        // Late in stream, reward using existing bins more
        score -= 4.0 * progress * tight;
    }

    // Many open bins: discourage spreading, encourage consolidation
    score += 0.3 * open_bins_count as f64 * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post residual, with non-linear shrink of small dead space
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress: early on, tolerate
    // residual (keep flexibility); later, strongly punish waste.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * pr_norm * cap * 0.2;

    // Perfect fit reward (smooth via squared term)
    score -= 12.0 * (1.0 - pr_norm).powi(2) * (pr_norm <= 0.05) as i32 as f64;

    // Last-chance bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        // mild penalty spread across many fitting bins to prefer tightest fit
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits_next = (ns <= pr) as i32 as f64;
        let slack_ratio = if pr > 0.0 { (pr - ns).abs() / cap } else { 1.0 };
        score -= 8.0 * fits_next * (1.0 - slack_ratio);
        score += 2.0 * slack_ratio * progress;
    }

    // Crowd-out control: penalize bins when many open bins with high mean residual
    let crowd = (open_bins_count as f64).ln() * (mean_residual / cap);
    score += 0.5 * crowd * (1.0 - progress);

    // New-bin candidate: make empty bin moderately attractive only when
    // current fit is poor (post residual large relative to capacity)
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.35 * progress) + 0.4 * pr_norm * cap;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes modulo 10
    let post_class = post_residual % 10;
    // Dead-space penalty: residuals that are awkward (1..9 mod 10) waste space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable dead space
    } else if post_class != 0 {
        score += (post_class as f64) * 0.8;
    } else {
        score -= 6.0; // perfectly divisible residual class is valuable
    }

    // Integer-division thresholds on post_residual
    let quarter = bin_capacity / 4;
    if post_residual <= quarter / 2 {
        score += 12.0; // bin nearly full -> good packing, slight reward
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match bonus
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize more if residual is small dead space
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.35;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would leave big waste
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
        // allow new bin late in stream if item is huge
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Stream progression: early on, be pickier about tight fits; later, fill greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.25;

    // Prefer bins with residual close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that can only fit the very smallest items are also risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the lookahead item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If the next item cannot fit the post residual but is close, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins
    // (the new empty bin candidate has post_residual == bin_capacity, so this
    // pressure applies to it and favors reusing existing bins).
    if bin_residual == bin_capacity {
        score += 5.0 + 1.5 * open_bins_count as f64;
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean residual (consolidating
    // fullness into nearly-full bins keeps other bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Early in the stream, be slightly more willing to open new bins for
    // structure; later, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (bin_residual == bin_capacity) as u8 as f64;
    score -= progress * 5.0 * (post_residual <= 10) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (waste-free placement).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward when next item can exactly fill
    // the post residual (chained perfect packing), penalize when next item
    // cannot fit into post_residual (dead space risk).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let dead = (next_item_size - post_residual) as f64;
            score += 15.0 * dead / (bin_capacity as f64);
        }
    }

    // Penalize large post residuals relative to mean residual (avoid
    // creating bins with unusable slack compared to the fleet average).
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.3 * mean_diff.max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 0.5 * (bin_residual.saturating_sub(item_size)) as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the
    // stream or when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 50.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if next item is large and would waste this bin's capacity,
        // opening fresh can still win: soften penalty slightly.
        if next_item_size > 70 {
            score -= 30.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * cap;
    score += 0.35 * coupling;
    score -= 0.15 * norm_pr * progress * cap;

    // penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 0.5 * (ns - pr);
        } else {
            score -= 0.2 * (1.0 - (pr - ns) / cap);
        }
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // smooth penalty for residual deviation from mean
    score += 0.1 * (pr as f64 - mean_residual).abs();

    // prefer tighter fits slightly, smoothed
    score += 0.05 * (item_size as f64 / cap) * (bin_residual as f64 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Penalize dead space in fine granularity: leftover in (0..10) is nearly unusable.
    if post > 0 && post < 10 {
        score += 25.0;
    } else if post == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Harmonic class reward: leftover that is a "nice" fraction of capacity
    // (25, 50, 75, 100 or multiples of 10) is more reusable.
    if post % 25 == 0 && post > 0 {
        score -= 20.0;
    } else if post % 10 == 0 && post > 0 {
        score -= 12.0;
    }

    // Integer division thresholds on post_residual: classify leftover size.
    let post_class = post / 20; // 0..5 harmonic band
    score -= post_class as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == post {
            score -= 45.0;
        } else if nxt < post {
            // next item fits but leaves residue; reward if residue stays in a good class
            let nxt_post = post - nxt;
            if nxt_post % 10 == 0 {
                score -= 15.0;
            } else if nxt_post < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot fit here; penalize slightly, more if this was the only fitting bin
            score += 6.0;
            if fitting_bins_count == 1 {
                score += 12.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless post residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post > 0 && post < 10 {
            score -= 15.0; // still better than wasting a fresh bin on small dead space
        }
    }

    // New-bin candidate handling: empty bin gets a moderate default score so that
    // good fits in existing bins win, but terrible fits (large dead space) lose.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
        // If many bins are open, discourage opening more.
        score += open_bins_count as f64 * 2.0;
    }

    // Mean residual context: if this bin's residual is far below mean, it's a
    // "leftover" bin; prefer filling those to keep mean residual high.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.15;
    }

    // Item size harmonic class: large items (>50) should prefer tightest fits,
    // small items tolerate looser fits.
    if item_size > 50 {
        score += post_residual as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps (< 10, or below typical small item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize moderately small residuals that few items can still use
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward keeping this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item does NOT fit and post residual is small, penalize
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 45.0;
        // Exception: current item is large and would leave a bad residual in any bin
        if item_size >= 50 && fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post - nxt;
        score -= 18.0 * (1.0 - gap / cap).max(0.0);
        if gap == 0.0 {
            score -= 25.0; // exact 2-step completion
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty scaled by how badly the next item is blocked.
        score += 6.0 + 4.0 * ((nxt - post) / cap);
    }

    // Compare post_residual against mean residual: avoid creating outlier waste.
    score += 0.5 * (post - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize new-bin usage when plenty of reasonable open bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
        // Opening a bin is fine late in the stream if many bins already open (diversification).
        if open_bins_count > 3 {
            score -= 4.0;
        }
    }

    // Early stream: be slightly greedy on tightness; late stream: conserve bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (post / cap);

    // Slight reward for leaving residuals that are common "complement" sizes.
    let complement = (bin_capacity - item_size) as f64;
    if post > 0.0 && post <= complement * 0.5 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is good, amplify non-linearly
    score -= 3.0 * (bin_capacity as f64 / (1.0 + post_residual as f64));

    // Penalize dead space that is too small for the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: if next item fits in the post-residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty unless residual becomes useless anyway
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: many open bins with slack -> encourage consolidation
    if open_bins_count > 2 {
        let slack = mean_residual - bin_residual as f64;
        if slack > 0.0 {
            score += 0.5 * slack; // prefer bins below-average residual (fuller bins)
        } else {
            score -= 0.5 * (-slack);
        }
    }

    // Early stream: slightly favor opening new bins to build diversity of residuals
    if progress < 0.25 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Late stream: discourage opening new bins; squeeze into existing ones
    if progress > 0.75 && bin_residual == bin_capacity {
        score += 25.0 * progress;
    }

    // New-bin candidate handling: neutral base so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 8.0 - 4.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to item size (perfect packing)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: quadratic in post_residual (dead space penalized super-linearly)
    let mut score = post * post / cap;

    // Cubic coupling of dead space with stream progress: late in the stream,
    // leftover space is more costly since fewer items remain to fill it.
    score += post * post * post / (cap * cap) * (0.5 + progress);

    // Smooth interaction: item fill fraction vs progress
    let fill = item / cap;
    score -= fill * fill * (1.0 + progress) * 20.0;

    // Reward tight fits (small post_residual) with smooth exponential-like term
    score -= (1.0 - post / cap) * (1.0 - post / cap) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize bins whose residual deviates from mean (fragmentation control)
    let dev = bin_residual as f64 - mean_residual;
    score += dev * dev / (cap * cap) * 5.0;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap) * (1.0 + 0.5 * progress);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: smooth penalty growing with stream progress and item size,
    // so early on opening new bins is cheap, late it is discouraged unless fit is poor.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 12.0 + 15.0 * progress + 0.3 * open_pressure - 10.0 * fill * (1.0 - progress);
    }

    // Mild preference for fewer open bins overall
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible by 10 are
    // "usable" classes (likely to host future items drawn from a 10-multiple
    // grid); odd/prime leftovers are dead space and must be penalized.
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        score -= 6.0;
    } else if harmonic == 5 {
        score -= 1.0;
    } else {
        score += 4.0 + harmonic as f64 * 0.3;
    }

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fill: leave less than the minimum item size (1..100 unknown, but
    // small items exist) -> prefer very small leftovers only if harmonic.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0; // tiny slivers are usually dead space
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward; if next item cannot fit, penalize mildly
    // unless this bin was a last-chance bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size).min(20) as f64 * 0.2;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is really bad.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + (bin_residual - item_size) as f64 * 0.05;
    }

    // New-bin candidate: score it against mean residual of open bins.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are fragmented
        // (low mean residual) or many bins are already open.
        score = bin_capacity as f64 - 10.0
            + mean_residual * 0.5
            + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host anything next
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are waste.
    let dead_threshold = 25.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward good fits relative to mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is tight.
    score += (open_bins_count as f64) * 1.5 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9 - 10.0
            + (open_bins_count as f64) * 0.5;
        if post_residual + item_size == bin_residual {
            // item is tiny relative to bin; opening new bin wastes capacity
            score += 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item (perfect 2-chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0) * 0.5;
        // Perfect closure: next item exactly fills the bin afterwards.
        if slack == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the remainder.
        score += (post_residual as f64).min(next_item_size as f64) * 0.4;
    }

    // Tight fits are good: small post residual is naturally rewarded by base term,
    // but amplify when the item nearly closes the bin.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Relative-to-mean residual: prefer bins that are already more filled than average.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        score += 55.0
            - (item_size as f64 / bin_capacity as f64) * 40.0
            + fitting_bins_count as f64 * 3.0;
    }

    // Late in the stream, prioritize closing bins to reduce spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize proportionally to wasted remainder
            let left = post_residual - next_item_size;
            score += left as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty for breaking pairing
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If many bins are already open, discourage more sprawl.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If the mean residual is large, prefer using existing space instead.
        score += mean_residual * 0.4;
        // If item is large, a fresh bin is more attractive.
        score -= item_size as f64 * 0.15;
        // If this is the only fitting option anyway, neutralize the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins with residual close to item size (best-fit flavor with lookahead coupling).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.2;

    // Global state coupling: when mean residual is high, squeeze existing bins harder.
    score -= mean_residual * 0.05;

    // Late in the stream, be conservative: prefer filling existing bins fully.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 30.0 * poly;

    // Penalize tight fits that strand dead space late in the stream
    let tightness = 1.0 - (pr / cap);
    score += 15.0 * tightness * tightness * (0.5 + progress);

    // Reward using nearly-full bins (low post residual) especially when many bins are open
    score -= 20.0 * (1.0 - norm_pr) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Lookahead: favor bins whose post residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr / (next_item_size as f64 + cap));
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mild penalty for opening new bins when open bins fit
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    // Mean residual alignment: prefer bins close to mean residual
    let dev = (pr - mean_residual).abs();
    score += 3.0 * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 (dead-space class)
    let post_class = (post_residual % 10) as f64;
    // Penalize residuals that fall into "awkward" classes (1..9 mod 10 wastes space)
    if post_residual > 0 {
        score += (10.0 - post_class) * 0.35;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tiny dead space classes: post_residual in 1..10 is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division thresholds: post_residual / 10 gives usable "slots"
    let slots = (post_residual / 10) as f64;
    score -= slots * 0.6;

    // Lookahead coupling: if next item fits in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic bonus when next item exactly matches post_residual class
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize proportional to waste
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral base, slightly penalized so we only
    // open new bins when existing bins look bad
    if bin_residual == bin_capacity {
        score += 6.0 + 0.05 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Progress-based mild tightening: later in stream, prefer tighter fits more
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving room for the next item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if the next item cannot fit anywhere else and this bin would be wasted.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Slight preference for filling bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good, already captured by base.
    // Penalize dead space that is too small to be useful for future items.
    let min_item = 1.0f64;
    let dead_penalty = if post_residual > 0 && (post_residual as f64) < min_item {
        1000.0
    } else {
        0.0
    };
    score += dead_penalty;

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // next item cannot fit here; penalize leaving large unusable gaps
            let gap = post_residual as f64;
            score += 0.3 * gap;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "fuller";
    // prefer filling them further only if the fit is tight.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin if the item is large and
    // fits poorly everywhere else (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: keep it high unless the fit is excellent.
        score += 25.0;
        // Large items pack better into fresh bins when little room is left elsewhere.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to chain).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins already: consolidate when possible.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward filling bins deeply relative to capacity.
    let fill_ratio = (bin_residual as f64 - pr) / cap;
    score -= fill_ratio * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item would fit into post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
            // Extra reward if next item exactly fills the bin afterwards.
            if post_residual as u32 == next_item_size {
                score -= 10.0;
            }
        } else {
            // Penalize leaving dead space that the next item cannot use.
            score += (pr / cap) * 15.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (plenty of future items to fill them); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as stream progresses,
        // and penalize when many bins are already open.
        score += 20.0 + progress * 30.0 + (open_bins_count as f64) * 2.0;
        // But if item barely fits nowhere well, opening a new bin is fine early.
        if post_residual > item_size && progress < 0.3 {
            score -= 10.0;
        }
    }

    // Global state coupling: if mean residual is high, prefer bins below mean
    // (balance), else prefer bins above mean (drain large residuals first).
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score -= diff * 0.08;
    } else {
        score += (-diff) * 0.05;
    }

    // Discourage leaving residuals below the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post_residual (waste), modulated by stream progress
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr) * (1.0 + 0.5 * progress);

    // Reward tight fits: post_residual near zero strongly favored
    score -= (1.0 - norm_pr).powi(3) * 2.0;

    // Coupling with mean residual: avoid bins deviating from fleet state
    score += 0.3 * (norm_pr - mean_residual / cap).abs();

    // Lookahead: penalize leaving residual that neither fits next item nor is tiny
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // next item fits: mild bonus for useful leftover
            score -= 0.2 * (1.0 - (ni / cap));
        } else {
            // dead space relative to next item
            score += 0.5 * (pr / ni.max(1.0));
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.0 + norm_item;
    }

    // Crowding: mild penalty per open bin to prefer consolidation early
    score += 0.05 * (open_bins_count as f64 / (1.0 + progress));

    // New-bin candidate: neutralize its residual advantage so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 0.8 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "usable" classes.
    let c = bin_capacity as f64;
