    // Penalize dead space: residuals too small to fit typical small items (<10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo-class bonus: residuals that are multiples of common small sizes
    // (10, 20, 25, 50) are more likely to be exactly filled later.
    let harmonic_bonus = if post_residual % 50 == 0 {
        12.0
    } else if post_residual % 25 == 0 {
        8.0
    } else if post_residual % 20 == 0 {
        6.0
    } else if post_residual % 10 == 0 {
        4.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            // reward tight two-step packing, penalize leaving junk
            score -= 10.0 - (leftover as f64) * 0.15;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins with tighter fit among many options
        score += frac * 10.0;
    }

    // New-bin candidate: baseline preference; only attractive when open bins
    // are very full on average (mean_residual small).
    if bin_residual == bin_capacity {
        // neutral-ish base: post_residual == capacity makes base large already;
        // adjust by stream progress and mean residual
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - mean_residual * 0.5 - progress * 20.0;
    } else {
        // open bin: reward when its residual is far below mean (it is "fuller")
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Nonlinear tightness reward: exact fills are golden.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Integer-division threshold: residual in [10, 30) is a danger zone
    // (fits few future items) unless it's a harmonic class.
    if post_residual >= 10 && post_residual < 30 && post_residual % 10 != 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    // Penalize small nonzero post_residuals heavily; zero residual is perfect.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Treat gaps <= 10 as near-dead space (items are >= 1 in general interface).
        if gap <= 10.0 {
            score += 40.0 * (10.0 - gap) / 10.0;
        } else if gap < 25.0 {
            // Small awkward gaps are mildly penalized beyond their size.
            score += 6.0 * (25.0 - gap) / 15.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Prefer bins whose residual is tight relative to the item (best-fit sharpening).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few bins are open, a fresh bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open or late in stream.
        score += 10.0 + 4.0 * open_pressure + 10.0 * progress;
        // But if the item would leave a bad gap in every existing bin, new bin is fine:
        // mean_residual much larger than item suggests existing bins are poor fits.
        if mean_residual > (item_size as f64) * 1.6 {
            score -= 8.0;
        }
        // Lookahead: if next item is large, an empty fresh bin is valuable.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Lookahead synergy: if post_residual exactly accommodates next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap: dead space confirmed.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly or snugly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward tight fits, penalize wasteful slack for the next item.
            score -= 60.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use this residual: dead space risk.
            score += 0.4 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Prefer bins whose residual is below the mean (tight bins absorb items well).
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Early in the stream, encourage opening bins that leave flexible residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        if post_residual >= 40 {
            score -= 20.0;
        }
    } else {
        // Late stream: penalize leaving medium dead space, reward near-full packing.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // New empty bin: only attractive when existing bins would leave large waste.
    if bin_residual == bin_capacity {
        let best_alternative_waste = 100.0f64.min((post_residual as f64) * 0.5);
        score += 120.0 - best_alternative_waste;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically: small post-residuals are valuable.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Post residual too small for next item: penalize wasted sliver.
            score += 4.0 + 0.1 * pr;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.05 * residual_gap;

    // Time horizon: early in the stream, be more open to opening bins (explore);
    // late in the stream, pack tightly (exploit).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * (1.0 - progress);

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // waste is penalized more heavily as the stream advances.
    let poly = 1.0 + 2.0 * progress * progress + 3.0 * progress * progress * progress;
    score += 0.35 * post * poly / cap;

    // Reward tight fits (small post_residual) with a superlinear discount.
    let fit_frac = post / cap;
    score -= 25.0 * (1.0 - fit_frac).powi(3);

    // Penalize post_residual that cannot hold the lookahead item (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 0.6 * (nxt - post) * (1.0 + progress);
        } else {
            // Bonus when post_residual fits the next item well.
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        }
    } else {
        // Last item: strongly prefer near-zero waste.
        score -= 20.0 * (1.0 - fit_frac);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many fitting bins: mild penalty to prefer best-fit discrimination.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Encourage balancing against mean residual (avoid fragmenting full bins).
    score += 0.2 * (mean_residual - post).abs();

    // New empty bin candidate: penalize unless current bins are quite full
    // or the item leaves a large residual in an existing bin.
    if bin_residual == bin_capacity {
        let pressure = 1.0 - mean_residual / cap;
        score += 15.0 * pressure * (1.0 - progress);
        score += 5.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (large enough for typical items) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty if leftover is too small for the smallest item (1).
        // Classify leftover by integer division into harmonic buckets of 10.
        let bucket = post_residual / 10;
        match bucket {
            0 => score += 40.0,               // unusable sliver
            1 => score += 20.0,               // small but sometimes usable
            2..=4 => score += 0.0,            // sweet spot
            _ => score -= 5.0,                // large leftover, fine
        }

        // Lookahead coupling: reward leftovers that can host the next item.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                let slack = (post_residual - next_item_size) as f64;
                score -= 15.0 + 10.0 * (1.0 - slack / cap);
                // Harmonic bonus: leftover exactly matches a modulo class of next item
                if post_residual % next_item_size.max(1) == 0 {
                    score -= 8.0;
                }
            } else {
                score += 10.0; // next item won't fit here
            }
        } else {
            // Last item: prefer tightest fit overall.
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // would leave a bad class of leftover in every open bin.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Mild base penalty so open bins with decent fits win.
        score += 25.0;
        // But if item is huge relative to mean residual, opening fresh is better.
        if (item_size as f64) > mean_residual {
            score -= 55.0;
        }
        // Late in the stream, consolidate rather than open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference for bins with below-mean residual (tighter packing).
    score += 0.15 * ((bin_residual as f64) - mean_residual).max(-50.0).min(50.0);

    // Small tie-break favoring fewer open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible item are wasted. Penalize small nonzero gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) / (1.0 + post_residual as f64);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: only bin that fits -> prefer using it over new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage packing into existing bins.
    let pressure = open_bins_count as f64 * 0.5;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: baseline cost plus pressure.
        score += 30.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item would NOT fit in the residual, mild penalty for leaving a gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference for bins with residuals below the mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early stream: be more conservative (favor new bins less later is fine;
    // here we slightly favor tight packing as stream progresses).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but penalize tiny unusable slivers.
    if post_residual < 10 {
        // Dead space that nothing (min size 1..100) may fill; mild penalty unless it's zero.
        score += 3.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly (or nearly)
    // matches the next item size, enabling a perfect second placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let lookahead_reward = (next_item_size as f64) * (1.0 - gap / (bin_capacity as f64));
        score -= 1.5 * lookahead_reward.max(0.0);
        // Exact match bonus: next item fills bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Prefer bins with residual close to the mean (balanced packing), unless last chance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current bin would
    // leave a very large residual AND lookahead doesn't justify it.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin attractive only if best-fit alternative is poor (post_residual large)
        // relative to item size, or stream is early and consolidation matters.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 0.7 * bin_capacity as f64;
        if poor_fit {
            score -= 15.0 + 10.0 * (1.0 - progress);
        } else {
            score += 20.0;
        }
    }

    // Slight preference for filling more crowded bins first (closes bins early).
    score -= 0.05 * open_bins_count as f64;

    // Reward larger item placement into tighter bins (best-fit flavor).
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score -= (item_size as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Penalize dead space that no future item (size <= 80... here 1..=100) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, prefer spreading load / opening bins less aggressively;
    // late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 0.5 + 1.5 * progress;
    score += (post_residual as f64 / bin_capacity as f64) * 10.0 * (2.0 - consolidation);

    // Global state: many open bins with high mean residual -> encourage using existing space.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0; // next item needs a fresh bin anyway
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
    }

    // Mild penalty for large residual gap relative to item (waste measure).
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mildly convex penalty.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth stream-progress coupling: early on, tolerate loose fits; later, tighten.
    let tightness = 0.5 + 1.5 * progress * progress;
    score *= tightness;

    // Penalize residuals that cannot accommodate typical future demand,
    // coupled non-linearly with the mean residual of open bins.
    let dead = (pr - mean_residual.min(pr)).max(0.0);
    score += 0.2 * dead * (0.5 + progress);

    // Lookahead: if the next item fits the post-residual, reward this bin;
    // if it almost fits (within a small gap), penalize leaving awkward space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - nx / cap) * (1.0 - progress);
        } else if nx - pr <= 12.0 {
            score += 4.0 * (1.0 - (nx - pr) / 12.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: make empty bins attractive only when no open bin fits
    // well; otherwise keep them slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score = cap - 8.0 * progress - 4.0 * scarcity * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize dead space non-linearly; tiny residuals are nearly worthless.
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else {
        // Class by integer division: 1..=10 (dead), 11..=30 (poor), 31..=60 (usable), 61..=100 (great)
        let class = post_residual / 10; // 0..=10
        let class_penalty = match class {
            0 => 25.0,          // 1..=10 dead space
            1 => 12.0,          // 11..=20
            2 => 6.0,           // 21..=30
            3 => 0.0,           // 31..=40
            4 => -4.0,          // 41..=50
            5 => -8.0,          // 51..=60
            _ => -12.0,         // large residual, still flexible
        };
        score += class_penalty;
    }

    // Harmonic compatibility: does next_item_size divide / align with post_residual?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // next item fills this bin exactly
        } else if next_item_size <= post_residual {
            let rem = post_residual % next_item_size.max(1);
            if rem == 0 {
                score -= 15.0; // harmonic multiple fit
            }
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        } else {
            // next item cannot go here; if this is the last fitting bin, prefer using it now
            if fitting_bins_count == 1 {
                score += 5.0;
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good home
    // (large post_residual on empty bin = full capacity kept, but opening costs a bin).
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 0.5;
        // Late in the stream, opening fresh bins is cheaper (fewer future regrets)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
    }

    // Mild tie-breaker: prefer bins below mean residual (tighter bins get packed first)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Small deterministic jitter via modulo classes to break ties coherently
    score += ((step_index % 7) as f64) * 0.01 - ((post_residual % 3) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps too small to hold even the
    // smallest plausible item (size 1..=100 stream) are pure waste.
    let dead = (post_residual as f64) * (post_residual as f64);
    score += 0.9 * dead / (bin_capacity as f64);

    // Reward tight fits (small post residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Open bins pressure: with many open bins, prefer reusing existing bins
    // over opening new ones.
    let pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0));
    score -= 25.0 * pressure;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Mean residual coupling: bins far below mean residual are less
    // attractive targets; keep fragmentation balanced.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // New bin candidate: neutral baseline; only win when all open bins have
    // terrible fits (their penalties keep them above this).
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
