pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; slight penalty if post_residual is wasted
            score += 1.5;
        } else {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 4.0;
            }
        }
    }

    // New-bin candidate handling: prefer opening a new bin only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral baseline with slight penalty so it's chosen only when needed.
        score += 3.0 + 0.5 * (open_bins_count as f64).sqrt();
        // If the current item is large, a fresh bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 4.0;
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Prefer bins with below-average residual (keeps spread of residuals balanced).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Slight preference for fuller bins overall.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    // Early stream: be more exploratory, mild penalty on all existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 2.0 * (1.0 - progress * 5.0) * (bin_residual != bin_capacity) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): reward small post_residual (tight fits).
    // Later on (progress ~ 1): dead space matters more, penalize large residuals.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_poly * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits more strongly when few bins can take the item.
    if fitting_bins_count == 1 {
        score -= 4.0 + 2.0 * progress;
    } else if fitting_bins_count == 2 {
        score -= 1.5;
    }

    // Penalize placing into bins whose residual is far from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev * cap;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for opening a new bin when many bins are open and progress is high.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
    }

    // Exact fit bonus (cubic smooth term).
    let exact = 1.0 - norm_pr;
    score -= exact * exact * exact * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity wasted if bin closes here

    // Reward tight fits: residual in low harmonic classes (mod 10) are "usable" slots.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 12.0,  // perfect fill
        1..=5 => 6.0, // small gap, likely fillable by small items
        6..=9 => -3.0, // awkward dead space
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize large fractional residual (dead space) quadratically.
    score += 8.0 * frac * frac * cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use residual: penalize leaving medium gaps
            if post_residual > 0 && post_residual < 10 {
                score += 4.0;
            }
        }
    }

    // New-bin candidate: neutral-ish baseline, but prefer it when residual fill
    // would be very poor or when current bin is fresh and item would leave huge gap.
    if bin_residual == bin_capacity {
        // base competitive score: prefer new bin only if all open bins are tight
        score = 0.35 * cap + 3.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0; // fresh bin can host next item too
        }
        if frac > 0.0 {
            // never happens for fresh bin; guard no-op
        }
    } else {
        // Mildly prefer bins whose residual is close to item (best-fit sharpening)
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += 10.0 * tightness;
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    // Mean-residual coupling: if this bin is far below mean residual, it's an outlier;
    // filling outliers is good (balances residual distribution).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    if post_residual > 0 {
        // Gap too small to hold even the smallest plausible item => dead space
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual < 35 {
            score += 12.0;
        }
        // Prefer leaving gaps that can fit the lookahead item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0;
            } else {
                score += 8.0;
            }
        }
    } else {
        // Perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits relative to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 2.0;
        score -= 5.0 - pressure - 10.0 * progress;
        // Penalize opening a bin when item would leave a small gap in it
        if item_size < 50 {
            score += 10.0;
        }
        // Favor new bin if item nearly fills it
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Slight preference for bins below mean residual (consolidation)
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits here too; reward tightness
            score -= 150.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize small leftovers
            score += 60.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare residual against mean residual of open bins
    score -= 20.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize wasting a nearly-empty bin context when a fresh bin would be better
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item is large and lookahead suggests poor fits elsewhere
        score -= 80.0 * item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 50.0; // fresh bin leaves space next item can use
        }
    }

    // Penalize leaving tiny unusable gaps (not matching typical item sizes)
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Late-stream consolidation: prefer tighter packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer reusing among many open bins to reduce bin count
    score += 10.0 * open_bins_count as f64 / (fitting_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_residual as f64;
        score -= (1.0 - tightness) * 60.0;
        // Non-linear penalty on dead space: residuals below ~15 are nearly useless.
        if post_residual < 15 {
            score -= 40.0 * (1.0 - post_residual as f64 / 15.0);
        }
    }

    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // post residual won't serve next item; penalize proportionally to wasted potential
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    } else {
        // Last item: strongly prefer filling a bin completely.
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins have poor residuals.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Opening a new bin is penalized mildly; it becomes attractive only
        // when mean residual of open bins is small (poor fits available).
        score += 30.0 + 20.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternatives: must open new bin
        }
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 15.0;
    } else {
        score += progress * 25.0; // late stream: discourage opening new bins
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score += if bin_residual == bin_capacity { 10.0 } else { -0.5 * open_bins_count as f64 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large post_residual quadratically).
    // Late: relax slightly, favoring consolidation over fragmentation.
    let tightness = (1.0 - progress) * (pr * pr) / (cap * cap);
    score += 40.0 * tightness;

    // Non-linear reward for near-perfect fills, stronger as stream progresses.
    let fill = 1.0 - pr / cap;
    score -= 25.0 * fill * fill * fill * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 + progress);
        // Reward leaving room for the next item smoothly.
        let room = (pr - nxt).max(0.0) / cap;
        score -= 8.0 * (1.0 - (room * 2.0).min(1.0)) * room;
    }

    // Last-chance bin: smooth polynomial reward to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize mildly unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (pr / cap) * (pr / cap);
        let mean_over = (mean_residual / cap).powi(2);
        score += 5.0 + 20.0 * (1.0 - frag) * (1.0 - mean_over) * (1.0 - progress);
    }

    // Mild non-linear penalty coupling open bin count with mean residual.
    let spread = ((pr - mean_residual) / cap).powi(2);
    score += 3.0 * spread * (1.0 + open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 2.5 * tightness * tightness;

    // Penalize dead space: post_residual that is too small to hold any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;  // near-dead space
    }

    // Harmonic class logic: modulo-10 classes of post_residual vs next_item_size.
    if next_item_size > 0 {
        let pr_class = post_residual % 10;
        let nx_class = next_item_size % 10;
        // If next item's unit digit matches residual's unit digit, exact class fit likely.
        if pr_class == nx_class && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Next item fits perfectly into this bin's post residual.
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            // Reward leaving space that the lookahead can still use.
            score -= 3.0;
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score += 5.0; // creates a sliver after lookahead
            }
        } else {
            // Lookahead won't fit here: penalize proportionally.
            score += 4.0;
        }
        // Integer-division threshold: how many times next item fits in post residual.
        let fits = post_residual / next_item_size.max(1);
        score -= 1.5 * fits.min(3) as f64;
    } else {
        // Last item: strongly prefer minimal waste.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be picky, prefer tightest.
        score += 1.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Discourage over-fragmenting when many bins are open with high mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 3.0 * (0.5 + progress);
    } else if (post_residual as f64) < mean_residual - 20.0 {
        score -= 2.0; // consolidating toward tighter bins
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 18.0 };
        score += desperation + 5.0 * open_bins_count as f64 * (1.0 - progress);
        // If lookahead is huge, opening fresh bin can be wise.
        if next_item_size >= 60 && post_residual == bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
