    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual matches the upcoming item (lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Penalize leaving residual far from mean (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: make it attractive only when the fit is poor.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 5.0 + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already handled), but
    // add a strong quadratic penalty for large dead space.
    let pr = post_residual as f64;
