    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Perfect chaining: next item fits exactly in the leftover.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 1.0 { score -= 8.0; }
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            score += 0.5 * gap;
        }
    } else {
        // Last item: minimize residual as tightly as possible.
        score += 0.2 * pr;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if pr <= 10 { score -= 5.0; }
    }

    // Relative-to-mean coupling: bins with residual below mean are "more full";
    // prefer packing into fuller bins (below-mean residual gets a discount).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Progression: early in the stream, be more willing to open new bins for
    // large items; late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, and when many
        // bins are already open; reward slightly for big items early on.
        score += 15.0 * progress + 0.4 * open_bins_count as f64;
        score -= 0.1 * item_size as f64 * (1.0 - progress);
        // Never open a new bin when the item fits snugly somewhere else.
        if item_size as f64 >= mean_residual * 0.9 { score += 20.0; }
    } else {
        // Established bin: discount grows with progress (favor consolidation).
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3) * item_size as f64;

    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.05;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasting large residuals on small items
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer filling existing ones over opening new
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Prefer bins whose residual is close to mean residual (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    // Time horizon: late in the stream, be greedier about tight fits
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: quadratic penalty on leftover space (wasted capacity).
    let mut score = post * post_norm * 2.0;

    // Smooth non-linear coupling: waste tolerance grows with stream progress.
    let waste_weight = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= waste_weight;

    // Tight-fit reward: strongly favor near-perfect fills via smooth saturation.
    let tightness = 1.0 - post_norm;
    score -= tightness * tightness * cap * 0.8;

    // Lookahead coupling: if next item fits smoothly into post_residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= (1.0 - slack) * 6.0 * (1.0 - progress);
        } else {
            let overflow = (nxt - post) / cap;
            score += overflow * overflow * 12.0;
        }
    }

    // Last-chance bin: penalize opening new bins when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly discouraged early, more acceptable late.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0;
    }

    // Mild pressure to consolidate: prefer bins tighter than average.
    score += (mean_residual - post) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small non-zero residuals are likely dead space; penalize by class.
    let r = post_residual;
    if r > 0 {
        let cls = r % 10;
        // residuals 1..=9 (small dead space) heavily penalized, scaled by class
        if r < 10 {
            score += (12.0 - cls as f64) * 8.0;
        } else if r <= 20 {
            score += 15.0; // awkward zone: too small for most items
        }
        // Larger residuals get mild penalty proportional to waste beyond half capacity
        if r > bin_capacity / 2 {
            score += (r as f64 - cap * 0.5) * 0.5;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // especially when next item exactly fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 300.0; // chain of perfect fits
            } else {
                score -= 20.0;
            }
        } else {
            // post residual too small for next item: dead space ahead
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): only attractive when no good open fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are open
        // or the stream is early (future items may fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 40.0 - 15.0 * (1.0 - progress);
        if open_bins_count > 4 {
            new_bin_score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // roomy bin may serve future large items
            new_bin_score -= 5.0;
        }
        score += new_bin_score;
    }

    // Mild tie-breaking: prefer bins with residual close to mean (balance).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Pressure from number of open bins: discourage spreading.
    score += open_bins_count as f64 * 0.8;

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if current bin would leave bad dead space, new bin looks better.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }

    // Late in stream, tighten packing (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted space
            score += 0.3 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Penalize creating dead space below the minimum plausible item size
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Prefer using more-opened bins when mean residual is high (spread load)
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Discourage opening new bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Tightness reward: prefer bins where the item fills them well ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 0.6 * fill_ratio * (bin_capacity as f64 - post_residual as f64);

    // --- Dead-space penalty: residual too small for any future item (1..100) ---
    if post_residual > 0 {
        // small unusable slivers are bad, but exact-zero residual is perfect
        let sliver = post_residual as f64;
        if sliver < 10.0 {
            score += (10.0 - sliver) * 1.5; // heavy penalty for near-dead space
        }
    }

    // --- Lookahead: reward if next item fits into the post residual ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how snugly the next item fits afterwards
            let after_next = post_residual - next_item_size;
            score -= 4.0 + 0.05 * after_next as f64;
        } else if post_residual > 0 {
            // residual likely wasted given lookahead knowledge
            score += 0.5 * post_residual as f64;
        }
    }

    // --- Last-chance bonus: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin leaves residual = capacity - item_size.
        // Discourage opening new bins when existing bins fit decently,
        // but allow it when the item is large or many bins are open.
        let new_residual = (bin_capacity - item_size) as f64;
        score = new_residual;
        let pressure = (open_bins_count as f64).sqrt();
        score += 6.0 + pressure; // fixed cost of opening a bin
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            // only one fitting bin: prefer it unless fill is excellent
            if fill_ratio < 0.7 {
                score += 3.0;
            } else {
                score -= 5.0;
            }
        }
        // late in the stream, consolidating matters more
        score += 4.0 * progress;
        // if mean residual across open bins is small, avoid new bins
        score += 0.3 * mean_residual.max(0.0);
    }

    // --- Mild preference for packing into fuller bins overall ---
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.1 * used;

    // --- Global state coupling: with many open bins, favor tight fits harder ---
    score -= 0.02 * open_bins_count as f64 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted post-residual, with non-linear growth
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth interaction: as stream progresses, tight fits (small post_residual) become more valuable
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * progress * tightness * tightness * tightness;

    // Coupling post_residual with mean residual: prefer bins whose leftover deviates favorably
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev - 2.0 * dev * (1.0 - progress);

    // Lookahead coupling: reward residual that fits next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            let nd = diff / cap;
            score -= 3.0 * (1.0 - nd * nd) * (0.5 + progress);
        } else {
            score += 1.2 * (-diff / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (0.3 + progress);
    }

    // Mild penalty for many open bins to discourage sprawl
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with slight progress-dependent cost
    if bin_residual == bin_capacity {
        score = 1.0 + 2.0 * progress + 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which capacity fraction slot does the leftover land in
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Dead-space penalties by harmonic class
    if post == 0 {
        score -= 40.0; // perfect fit
    } else if post < eighth {
        score += 25.0; // tiny unusable sliver
    } else if post < quarter {
        score += 8.0;  // small but sometimes usable
    } else if post < 2 * quarter {
        score += 0.0;  // half-bin class, flexible
    } else {
        score -= 10.0; // large leftover, very reusable
    }

    // Modulo-16 class of post_residual: fine-grained dead zone detection
    let m = post % 16;
    if m != 0 && m < 4 {
        score += 6.0; // awkward remainder class
    } else if m == 0 {
        score -= 4.0; // aligned leftover, likely to pair with future items
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // how tightly does the next item fill the leftover (integer division class)
            let fill_class = post / next_item_size.max(1);
            if fill_class == 1 {
                score -= 18.0; // next item almost exactly consumes leftover
            } else {
                score -= 7.0;
            }
        } else {
            score += 12.0; // next item won't fit here; leftover likely stranded
        }
    }

    // Last-chance bin bonus: only one bin can take this item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer tightest relative fit
    score += (post as f64 / cap) * 20.0;

    // Early stream: keep bins open and flexible; late stream: consolidate hard
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 5.0 * (post as f64 / cap); // favor emptier bins early
    } else {
        score -= 5.0 * (1.0 - post as f64 / cap); // favor full bins late
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let poor_fit = post > (bin_capacity as u32 * 2 / 3) && fitting_bins_count == 0;
        if poor_fit {
            score -= 15.0;
        } else {
            score += 45.0; // discourage opening new bins when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are >= 1, but small gaps waste capacity in practice).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0; // harsh penalty for dead space
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward when this bin's leftover can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: mild penalty proportional to waste
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open-bin pressure: discourage proliferating bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (tight fit) rather than wildly larger.
    let fit_tightness = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.15 * fit_tightness.abs();

    // New-bin candidate: only attractive when item is large and no open bin
    // fits well (post_residual after placing in empty bin is small-ish).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        if waste < 20.0 {
            score -= 30.0 - waste; // large item: new bin is fine
        } else {
            score += 40.0 + 0.5 * (waste - 20.0); // discourage wasting a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize large dead space
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    }

    // Relative-to-mean coupling: bins tighter than mean are precious, prefer filling them.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= 0.8 * (mean_residual - res_f);
    } else {
        score += 0.4 * (res_f - mean_residual);
    }

    // Last-chance bonus: only bin that fits the item -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize tiny unusable residuals (dead space < smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer compacting many items into fewer bins as stream progresses.
    if open_bins_count > 0 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    // Mild preference to keep new bins closed early in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small unusable sliver is fine if bin was nearly consumed
    }
    if post_residual >= 10 && post_residual < item_size {
        score += 0.15 * post_residual as f64; // moderately unusable gap
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (fitting_bins_count == 1 && fit_ratio < 0.35);
        if poor_alternatives {
            score -= 10.0;
        } else {
            score += 25.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual * (1.0 - progress);
        score += 0.3 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // Early stream: be slightly conservative, keep bins balanced.
    if progress < 0.2 && bin_residual < bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate larger residuals.
    let progress_weight = 0.5 + progress * progress * 2.0;
    score += progress_weight * norm_pr * norm_pr * cap * 0.5;

    // Reward near-perfect fills smoothly (cubic decay of residual utility).
    score -= (1.0 - norm_pr).powi(3) * 15.0;

    // Penalize residuals that are small but unusable for the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        let waste = if gap < 0.0 { -gap } else { 0.0 };
        score += waste * waste * cap * 0.8;
        // Smooth reward when post_residual still fits next item.
        let fits_next = (gap.max(0.0)).min(1.0);
        score -= fits_next * 5.0 * (1.0 - norm_next);
    }

    // Last-chance bonus: only one bin fits -> smooth extra reward for using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize opening a new bin mildly, more so when open bins exist
    // and mean residual is high (smooth coupling with open_bins_count).
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + openness * 2.0 + (mean_residual / cap) * 10.0 * progress;
    }

    // Mild penalty for deviating from mean residual (smooth dispersion term).
    score += ((pr - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins partitioned into
    // capacity/8 classes; residuals in "useful" classes are rewarded.
    let class_width = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / class_width).floor() as f64;

    // Reward residuals that are small-but-usable (class 0..2),
    // penalize large dead space (high classes).
    score -= (7.0 - class) * 3.0;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item can fit exactly into post_residual,
    // strongly reward; if next item cannot fit any residual class, penalize
    // leaving a residual that is too small for it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.15;
        } else {
            // next item won't fit here; residual becomes dead space for next step
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual
    // is truly fragmented (small residual, large item already consumed).
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 30.0;
        // allow new bin early in the stream or when open bins are nearly full
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_tightness = 1.0 - mean_residual / bin_capacity as f64;
        if mean_tightness > 0.85 || open_bins_count == 0 {
            score -= 40.0;
        }
        if progress < 0.2 {
            score -= 5.0;
        }
    }

    // Mild preference for tighter existing bins (small bin_residual).
    score += bin_residual as f64 * 0.05;

    // Modulo harmonic: residuals divisible by small integers pack better
    // with common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest item are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize leaving a gap that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.15 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, opening a new bin is cheap.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.25 * pressure;

    // Prefer bins whose residual is close to the item (tight fit relative measure).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 8.0 * tightness;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 30.0 } else { 20.0 + 0.5 * open_bins_count as f64 };
        score += desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a perfect two-item chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            // Next item still fits after placement: mild reward proportional to leftover.
            let leftover = (post_residual - next_item_size) as f64;
            score -= 40.0 - leftover * 0.5;
        } else {
            // Next item cannot use this bin's residual: penalize dead space creation
            // relative to how big the next item is.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Compare residual against mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + (mean_residual * 0.2);
    }

    // Early in stream, be more conservative with open bins (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: quadratic in fill ratio.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 40.0 * fill * fill;
    }

    // Penalize dead space that can't fit typical items: small post_residual that is nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            score += 15.0;
        }
    }

    // Global state coupling: prefer filling bins when many bins are open.
    let open_pressure = open_bins_count as f64 / (total_items as f64).max(1.0);
    score -= 30.0 * open_pressure * fill;

    // Mean residual: penalize deviating far from mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Early vs late horizon: early on, allow new bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more as stream progresses.
        score += 20.0 + 60.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post-residual)
    let mut score = pr;

    // Smooth polynomial coupling: post_residual^2 scaled, weighted by stream progress
    score += 2.0 * norm_pr * norm_pr * cap * (0.4 + 0.6 * progress);

    // Dead-space penalty: residual below smallest plausible item is wasted
    let dead = (norm_pr - (norm_pr * norm_pr)) * cap; // peaks at norm_pr=0.5
    score += 1.5 * dead * (1.0 - progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balance residuals)
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: reward bins that can also fit the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 8.0 + 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Slight preference for keeping tight fits as stream ends
    score *= 1.0 - 0.15 * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size is truly wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit
    }

    // Harmonic class of post_residual: bins whose leftover falls into
    // "large" classes (>= half capacity) are reusable; tiny leftovers are not.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr > cap_f * 0.5 {
        score -= 8.0;
    } else if pr > cap_f * 0.25 {
        score -= 3.0;
    } else if pr > 0 {
        score += 5.0; // awkward sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic penalty: prefer slack in coarse classes
            let cls = ((slack / 10.0).floor() as f64) * 2.0;
            score += cls + slack * 0.3;
        } else {
            // next item cannot follow here; mild penalty scaled by overflow
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bins
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full on average (then it may be fine to spread).
    if bin_residual == bin_capacity {
        score += 25.0;
        // allow new bins late in the stream when open bins are congested
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 20.0 && progress > 0.5 {
            score -= 20.0;
        }
    }

    // Modulo harmonic class on post_residual: leftovers that are multiples
    // of common item sizes (10, 20, 25, 50) remain usable.
    let pr_u = post_residual;
    if pr_u > 0 && (pr_u % 10 == 0 || pr_u % 25 == 0 || pr_u % 50 == 0) {
        score -= 4.0;
    }

    // Integer-division threshold: bins in their last quarter of capacity
    // get a small bonus (consolidation).
    if (post_residual / (bin_capacity / 4).max(1)) == 0 && post_residual > 0 {
        score += 2.0;
    }

    // Slight preference for bins below mean residual (fill fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalty grows as post_residual shrinks relative to smallest plausible item.
    let gap_ratio = post_residual as f64 / 10.0;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - gap_ratio) * 4.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space is worse late in the stream (less chance to reuse gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += progress * 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        // But if no good fit exists (post_residual large waste elsewhere), allow it.
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Prefer bins tighter than average (small residual relative to mean).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Large items: prefer bins where they leave small remainder.
    if item_size >= 50 {
        score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: 2-step lookahead matching — reward bins whose post-residual
    // closely matches the next item's size (perfect chain potential).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is a huge win: next item fills this bin perfectly.
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward tightness of the match.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to leftover gap.
            score += 0.5 * diff;
        }
        // If post-residual is too small for typical future items (dead space),
        // penalize extra unless it was a perfect match.
        if post_residual < 10 && post_residual != next_item_size {
            score += 40.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Compare against mean residual: placing into a bin with residual far
    // below the mean (tight bin) is good; above the mean wastes big space.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no good chain exists. Penalize mildly so open bins win ties.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * open_bins_count as f64;
        // Large items keep new bins useful; small items should go to existing bins.
        score -= 0.3 * item_size as f64;
    }

    // Early in the stream, allow slightly more freedom to open bins
    // (structure building); late in the stream, squeeze everything tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    let dead_threshold = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 30.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many bins compete, encouraging consolidation.
        score += 0.15 * (fitting_bins_count as f64).min(8.0);
    }

    // New-bin candidate handling: make opening a new bin costly unless it enables
    // an excellent fit for the current AND next item.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Reward new bin if it would leave room exactly matching the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial reward for leaving usable space for the next item.
        let usable = post_residual as f64 / (post_residual.max(next_item_size)) as f64;
        score -= 8.0 * usable;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating space the next item cannot use (wasted capacity).
        score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Global state coupling: prefer filling bins when mean residual is high
    // (many scattered gaps) to consolidate.
    if mean_residual > (2.0 * item_size as f64) {
        score -= 5.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early stream: slight preference for filling existing bins to keep bin count low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize very large open-bin counts (encourage closing out bins).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fit (low post_residual), with non-linear shaping.
    let norm_post = post / cap; // in [0,1]
    let mut score = post;

    // Non-linear polynomial coupling: dead space is increasingly costly as the stream progresses.
    let dead_penalty = norm_post * norm_post * (1.0 + 2.0 * progress) * cap;
    score += dead_penalty;

    // Reward bins whose residual closely matches the item (smooth interaction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64; // in (0,1]
    score -= 30.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Lookahead: reward residual that can still host the next item, smoothly scaled.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack * slack) * (0.5 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that barely misses the next item (dead space trap).
        let miss = (next_item_size - post_residual) as f64 / cap;
        score += 20.0 * miss * (1.0 - miss) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.3);
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Penalize bins with residual far from the mean (fragmentation smoothing).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make it attractive only when the fit would be very poor.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - fit_ratio) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (multiples of common item sizes / large chunks) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for &m in &[100u32, 50, 25, 20, 10, 5] {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        // small leftovers (<10) are dead space
        if pr < 10 {
            harmony -= 25.0 * (10 - pr) as f64;
        }
        score -= harmony;
    } else {
        // perfect fit is ideal
        score -= 40.0;
    }

    // Fractional capacity classes: reward tight fills (post_residual < 20% of capacity)
    let frac = post_residual as f64 / cap;
    if frac < 0.2 {
        score -= 15.0 * (0.2 - frac);
    }

    // Integer-division threshold on next_item_size: if the next item fits the
    // post_residual exactly or in a harmonic class, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 12.0;
        } else if next_item_size > pr {
            // this bin's leftover won't host the next item; penalize proportionally
            score += 4.0 + (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when existing bins fit well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // but if mean residual is small (open bins nearly full), new bin is fine
        score -= (mean_residual / cap) * 12.0;
        // early in stream, prefer consolidating; late, allow spreading
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild tie-break toward bins with residual close to mean (balanced packing)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // Gap is "unusable" if smaller than the smallest plausible item (1..100 range, be conservative: < 10).
    if post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 20.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bins pressure: discourage spreading across many open bins
    // unless the fit is excellent (low post_residual already lowers score).
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into this bin's post_residual,
    // reward the placement (chaining two items in one bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual too small for next item: mild penalty for stranded gap.
        score += 5.0;
    }

    // Prefer using bins with below-average residual (tighter bins first),
    // keeping loose bins available for larger future items.
    score += 0.4 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Brand-new empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && bin_capacity as f64 - item_size as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits (post_residual == next_item_size)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Reward leaving room for the next item with some slack
            score -= 8.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Penalize dead space smaller than the next item
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare post_residual relative to mean residual: prefer bins that tighten the spread
    score -= 2.0 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer fuller bins as the stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), weighted by stream progress
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr;

    // Smooth cubic coupling: tight fits (small post_residual) become more valuable later
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize bins far from mean residual (imbalance), smoothly
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 + 30.0 * progress;
    } else {
        // mild penalty for spreading across many bins
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let gap = (pr - ns) / cap;
        if gap >= 0.0 {
            score -= 20.0 * gap * (1.0 - gap) * 4.0 * (0.5 + progress);
        } else {
            score += 15.0 * (-gap) * (0.5 + progress);
        }
    }

    // Early stream: slight preference to consolidate into fewer bins
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction classes
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead space in low harmonic classes (unusable slivers)
    if post_residual < 10 {
        score += 50.0; // dead space, very bad
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward exact-fit harmonic classes: post_residual divisible into common item sizes
    let r = post_residual % 10;
    if r == 0 && post_residual > 0 {
        score -= 15.0; // post residual is a clean multiple of 10, likely reusable
    } else {
        score += r as f64 * 0.5; // noisy residual penalized
    }

    // Integer division thresholds on next_item_size: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely; reward proportional to fit quality
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_fit;
        } else {
            // next item won't fit here; penalize more if post residual is a "trap" class
            let trap = (post_residual / 25) * 25 == post_residual && post_residual < next_item_size;
            if trap { score += 10.0; }
            score += 5.0;
        }
    } else {
        // last item: prefer filling as much as possible
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly by default, but attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64;
        score += 30.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item followed by big item: fresh bin may help
        }
        let _ = spread;
    }

    // Progress-aware coupling: later in stream, tighten packing (favor tight fits more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Mean residual coupling: if this bin is far below mean residual, it's a laggard; use it
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward filling a bin deeply (small post residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage opening a new bin when current bins fit poorly.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when mean residual is small (poor fits)
        // or post_residual here (== capacity - item) is large and usable.
        score -= mean_residual * 0.6;
        if post_residual >= 20 {
            score -= 5.0;
        }
        score += open_bins_count as f64 * 0.8;
    } else {
        score += open_bins_count as f64 * 0.3;
    }

    // Lookahead: avoid leaving a gap that exactly blocks the next item while
    // wasting most of the bin; slightly favor bins whose residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    // Mild progression scaling: tighten packing as the stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * (1.0 + item_size as f64 / bin_capacity as f64);

    // 2-step lookahead: reward when next item exactly fills post_residual (perfect chain)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // perfect two-item packing
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to resulting 2-step residual
            let two_step = post_residual - next_item_size;
            score -= 30.0 - two_step as f64 * 0.5;
        } else {
            // next item won't fit here: penalize wasting capacity that could chain
            score += (nxt - post_residual as f64) * 0.3;
        }
    } else {
        // last item: strongly prefer minimal post_residual
        score -= 40.0;
    }

    // Relative to mean residual: placing into a bin with residual far below mean
    // balances open bins, mild reward
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // opening a new bin is fine if post_residual would perfectly chain with next item
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 70.0;
        }
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild penalty for dead space that is too small to fit the smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating.
    let pressure = mean_residual / bin_capacity as f64;
    score += pressure * 6.0 * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: late in the stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate handling: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score = 40.0 + 20.0 * openness * (1.0 - fit_ratio) - 8.0 * progress;
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 40.0 * poly * (0.5 + progress);

    // Penalize large dead space more aggressively as stream progresses
    score += 12.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= 15.0 * (-(pr / 25.0) * (pr / 25.0));

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let fit_frac = next_item_size as f64 / pr.max(1.0);
            score -= 10.0 * fit_frac * (1.0 - fit_frac) * 4.0;
        } else {
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Slight preference toward consolidating into fewer bins early on
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual.max(0.0);
        let waste_if_used = pr - avg_fit;
        score += 8.0 + 5.0 * (waste_if_used / cap).max(0.0) - 10.0 * progress;
    }

    // Mean residual deviation penalty (smooth coupling)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does leftover space align
    // with capacity fractions (1/2, 1/3, 1/4)? Residuals near these fractions
    // are reusable by typical items; awkward residuals are dead space.
    let pr = post_residual;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Distance to nearest harmonic class center (mod-based bucketing)
    let mut best_dist: u32 = u32::MAX;
    for center in [half, third, quarter, bin_capacity / 5, bin_capacity / 6] {
        let d = if pr >= center { pr - center } else { center - pr };
        if d < best_dist { best_dist = d; }
    }
    // Reward proximity to harmonic classes (subtract), penalize dead zones
    score -= (best_dist as f64).min(20.0) * 0.9;

    // Integer-division threshold: residual in [0,10) is unusable dead space
    if pr < 10 {
        score += 30.0;
    } else if pr < 20 {
        score += 12.0;
    } else if pr < 30 {
        score += 4.0;
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.6;
        } else {
            // next item won't fit here; leftover likely wasted
            score += (next_item_size - pr) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so we prefer good fits into open bins,
    // but allow it when open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 25.0 + fragmentation * 0.3;
        // Early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Modulo-10 class of item_size: items in "awkward" classes (e.g. 17, 23)
    // pair poorly with round residuals; slight nudge toward tightest fit.
    let item_class = item_size % 10;
    if item_class > 0 && item_class <= 5 {
        score += 2.0; // small items leave awkward gaps; prefer minimal leftover
    }

    // Mean residual coupling: when average open-bin residual is large,
    // we can afford looser fits; when small, demand tight fits.
    let tightness = (post_residual as f64 - mean_residual) / cap_f;
    score += tightness * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any realistic item are wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Fully unusable gap -> heavy penalty (large score) so oracle avoids it.
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    } else if (post_residual as f64) < 20.0 {
        // Marginal gap: moderate penalty scaled by how close to dead zone.
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // Reward when the lookahead item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.1 * next_item_size as f64;
        } else {
            // Next item won't fit here: slight penalty proportional to overflow.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins when few are open;
    // encourage using existing bins (lower score) as open count grows.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin: strongly favor placing here instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if this bin's fit is poor
    // (large post residual relative to capacity) and mean residual is already high.
    if bin_residual == bin_capacity {
        // Base score for a fresh bin: capacity-sized residual plus fixed startup cost.
        score = bin_capacity as f64 * 0.9 + 20.0;
        // If current bin leaves a big unusable gap, fresh bin becomes attractive.
        if (post_residual as f64) < dead_threshold {
            score -= 40.0;
        }
        // In early stream, opening bins is cheaper; late stream, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Tight fit reward: exact or near-exact fills are excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Slight preference for bins with residuals close to item size (best-fit core).
    score += 0.1 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack -> moderate reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / 50.0).max(0.0);
    }
    // Next item cannot use the leftover: penalize proportionally to wasted space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward bins whose residual is already below mean (tight bins absorb items well).
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: neutral-ish baseline so it wins only against bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 - score * 0.1;
    }

    // Late in the stream, prefer closing bins tightly (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (post_residual as f64).powi(2) / bin_capacity as f64 * 0.5;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into post_residual, this placement chains nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward for near-exact two-item packing.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 6.0;
            }
        } else {
            // Dead space that next item cannot use; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Penalize creating residuals too small to ever be useful (items >= 1, but typical min waste).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Global state coupling: when many bins are open, prefer consolidating into
    // bins below the mean residual (reduce fragmentation).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.15;
        // Encourage using open bins rather than spawning more when open count is high.
        if bin_residual < bin_capacity {
            score -= (open_bins_count as f64).ln() * 2.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (flexibility preserved); late in the stream, squeeze existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += progress * 20.0;
        score -= (1.0 - progress) * 10.0;
    } else {
        // Existing bin: slightly favored as stream progresses.
        score -= progress * 5.0;
    }

    // Mild penalty for very loose fits regardless of state.
    if post_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 18.0 * poly * (0.4 + 1.6 * progress);

    // Prefer tight fits; penalize large waste with cubic coupling
    score += 0.35 * pr_norm * pr_norm * pr_norm * (1.0 + progress);

    // Reward filling bins deeply as stream advances
    score -= fit_ratio * fit_ratio * 12.0 * (0.5 + progress);

    // Last-chance bin gets strong discount
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: bonus if next item fits into resulting post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 4.0 * (1.0 - (nx / cap)) * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins late in stream
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Mean residual alignment: favor bins near the mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled by capacity fraction.
    let cap = bin_capacity as f64;
    score += 0.35 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * 100.0;

    // Harmonic class of post_residual: residues divisible by small sizes are reusable.
    let pr = post_residual;
    let mut reusable = 0.0;
    for d in [10u32, 20, 25, 50] {
        if pr >= d && pr % d == 0 {
            reusable += 12.0;
        }
    }
    // Exact zero residual is perfect.
    if pr == 0 {
        reusable += 40.0;
    }
    score -= reusable;

    // Penalize dead space in awkward residue classes (prime-ish gaps).
    if pr > 0 && pr % 10 != 0 && pr < 10 {
        score += 25.0;
    }
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0; // tiny unusable slivers
    }

    // Lookahead: reward if next item fits the post residual exactly or nearly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 18.0 * (1.0 - slack as f64 / cap);
            if slack == 0 {
                score -= 22.0;
            }
        } else {
            // next item cannot use this bin's remainder: mild penalty scaled by waste
            score += 6.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it competitive only when current fits are bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin has full residual; make it attractive only if item is large
        // relative to capacity (little choice anyway) or early in stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let size_frac = item_size as f64 / cap;
        score = 55.0 - 20.0 * size_frac + 15.0 * progress;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 8.0; // roomy bin good for a bigger follower
        }
        if open_bins_count > 6 {
            score += 10.0 * (open_bins_count as f64 - 6.0).min(5.0); // too many open bins
        }
    }

    // Mean residual coupling: if average residual is high, tolerate looser fits.
    score -= 0.05 * mean_residual;

    // Harmonic modulo threshold on item size: items in "nice" classes pack predictably.
    if item_size % 25 == 0 || item_size % 50 == 0 {
        score += 3.0; // slightly discourage wasting these on partial bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    if post_residual > 0 {
        score -= (bin_capacity as f64 / post_residual as f64) * 2.0;
    } else {
        // Perfect fit: strongly favored
        score -= 200.0;
    }

    // Penalize unusable dead space: gaps too small for the smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }
    // Penalize gaps that cannot fit the next item (lookahead dead space)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }
    // Reward gaps that exactly or nearly fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 60.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 3.0;

    // Slightly prefer bins with below-mean residual (consolidating large gaps)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize mildly so it's only chosen when no decent fit exists
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    // Late in stream: be more conservative, prefer tight packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect/near-perfect fit (post_residual small)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: bonus proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
        } else {
