            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Penalize large dead space relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    // Progress-based pressure: later in the stream, prefer tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // New-bin candidate: neutral-ish baseline; only chosen if open bins score poorly
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream (0..1)
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Perfect fit reward: strongly favor bins that end exactly full.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Non-linear penalty on wasted space: small leftovers are bad
        // unless they can host the next item.
        let waste = post_residual as f64;
        score += (waste * waste) / (bin_capacity as f64);

        // Lookahead coupling: if the next item fits exactly in the leftover,
        // reward heavily; if it fits at all, mild reward.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if post_residual as f64 == nxt {
                score -= 300.0;
            } else if post_residual as f64 >= nxt {
                score -= 60.0 + 40.0 * (1.0 - (post_residual as f64 - nxt) / (bin_capacity as f64));
            } else {
                // Dead space relative to lookahead: penalize proportionally.
                score += (nxt - post_residual as f64) * 2.0;
            }
        }
    }

    // Fill-ratio bonus: prefer bins where the item occupies a large share
    // of the residual (tight packing).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 120.0 * fill * fill;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 80.0 + 100.0 * progress;
    }

    // Crowd penalty: with many open bins, prefer consolidating into
    // already-open bins rather than spreading; new bins get a surcharge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 150.0 + 30.0 * open_bins_count as f64 * (1.0 - progress);
        // New bin is only attractive when mean residual is small (bins nearly full).
        score -= mean_residual * 1.5;
    } else {
        // Favor bins below mean residual (underfilled) to balance load,
        // but only mildly, so tight fits still dominate.
        score += 0.5 * (mean_residual - post_residual as f64);
    }

    // Late-stream bias: as the stream ends, prefer closing bins tightly
    // (minimize leftover) over opening anything new.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
