    // Penalize large residuals more as stream progresses (less time to fill them)
    let late = progress * progress;
    score += late * fit_norm * fit_norm * 20.0;

    // Reward tight fits (small post_residual) with extra subtraction
    score -= (1.0 - fit_norm).powi(3) * 8.0;

