    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_norm) * 2.0;

    // New-bin candidate: keep it moderately expensive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.05 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class penalty: residuals divisible into capacity-friendly chunks are valuable.
    let pr = post_residual;
    // Perfect fits are ideal.
    if pr == 0 {
        score -= 1000.0;
    }
    // Residuals in "harmonic" classes: 0, 25, 50, 75, 100 mod 100-like chunks
    let harmonic = pr % 25 == 0;
    if harmonic {
        score -= 12.0;
    }
    // Residuals that are multiples of 10 pair well with typical item sizes
    if pr % 10 == 0 {
        score -= 4.0;
    }

    // Dead-space threshold: small unusable residuals are wasteful
    if pr > 0 && pr < 10 {
        score += 30.0; // tiny dead space, nearly unusable
    } else if pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: penalize by how well (smaller leftover better)
            let nxt_left = pr - next_item_size;
            score -= 20.0 - (nxt_left as f64) * 0.2;
        } else {
            // next item won't fit here: mild penalty, bin will likely be closed
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bins is cheap early, expensive late
        score = 100.0 + 120.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin anyway
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // large item arriving, fresh bin useful
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter packing)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Integer-division threshold: residual >= half capacity is flexible
    if pr >= bin_capacity / 2 {
        score -= 5.0;
    } else if pr >= bin_capacity / 4 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
