    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; penalize leaving a tempting gap
            score += 6.0;
        }
    }

    // Penalize high fragmentation relative to mean residual.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 10.0;
    }

