    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly than linear.
    let t = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * t * t;

    // Lookahead: if next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use leftover space: penalize dead space proportionally.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild penalty to prefer spreading load sensibly.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0 * (mean_residual / bin_capacity as f64) * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless current bin would waste a lot.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
        // But if no open bin fits well (large post_residual elsewhere), allow it.
        if post_residual == bin_capacity && item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference for bins that are already partially filled.
    score -= 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (0..1)
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: tight fits (small post_residual) are rewarded
    // quadratically, with reward strength increasing as the stream progresses.
    let tightness = (1.0 - pr) * (1.0 - pr); // 1.0 for perfect fit, 0.0 for empty bin
    score -= 30.0 * tightness * (0.5 + progress);

    // Penalize mid-range residuals (dead space) with a smooth bump centered at ~half capacity
    let bump = 4.0 * pr * (1.0 - pr); // peaks at pr = 0.5
    score += 25.0 * bump;

    // Interaction: post_residual squared vs mean residual — prefer bins whose
    // leftover diverges from the average (extremes are more useful: near-zero or large).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 8.0 * dev.abs() * (1.0 - bump);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin, scaled by progress.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // reward this placement; if next item would waste this bin's space, mild penalty.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let lookahead_fit = 1.0 - gap / bin_capacity as f64;
        score -= 12.0 * lookahead_fit.max(0.0) * (1.0 - progress * 0.5);
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    score += open_bins_count as f64 * 0.5 * pr;

    // New-bin candidate: empty bin gets a moderate baseline penalty so that only
    // genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 35.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Penalize dead space non-linearly: leftover below quarter capacity is hard to use
    if post_residual < quarter {
        score += 25.0;
    } else if post_residual < half {
        score += 8.0;
    }

    // Integer-division threshold: perfect-class residuals (multiples of quarter) are valuable
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead harmony: does next item fit into post_residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair
        } else if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            // harmonic class of the double leftover
            if leftover_after_next % quarter == 0 {
                score -= 15.0;
            } else if leftover_after_next < quarter {
                score += 6.0; // creates tiny dead space
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; residual becomes a waiting buffer
            // small residuals (mod classes) may still pair with future small items
            score += 4.0;
            if post_residual >= 10 && post_residual <= 30 {
                score -= 3.0; // residual in the common small-item band stays usable
            }
        }
    }

    // Last chance: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when placement elsewhere is bad.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes all current residual structure
        score += 60.0;
        // But if existing bins have poor fits (mean residual low relative to item), new bin is fine
        if mean_residual < item_size as f64 * 0.6 {
            score -= 45.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // Many open bins: discourage opening yet another
        score += 3.0 * open_bins_count as f64;
    }

    // Mild preference for tighter bins overall (waste minimization pressure)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Modulo tie-break on bin residual class: bins whose residual is in a "harmonic"
    // class (divisible by 10) tend to compose well with integer item sizes
    if bin_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the smallest
    // future item (size 1..100 unknown, but tiny gaps are highly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: gap too small for anything meaningful
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0); // near-dead gap
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty proportional to wasted potential
        score += 5.0;
    }

    // Open-bins pressure: penalize using existing bins when many are open,
    // to consolidate and close bins; favor filling over spreading.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a good candidate to be drained (low residual = close it out).
    let res_gap = mean_residual - bin_residual as f64;
    score += 0.3 * res_gap;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins have large
        // residuals (poor fits everywhere) and many bins already open.
        score = 0.5 * bin_capacity as f64
            + 10.0 * (open_bins_count as f64).sqrt()
            + 0.5 * mean_residual
            - 30.0 * (fitting_bins_count as f64);
        // If only this new bin fits, it must be chosen.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer reusing existing bins.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff == 0.0 {
            score -= 800.0; // chain of perfect fits
        } else if diff > 0.0 && diff <= 10.0 {
            score -= 400.0; // near-perfect chain
        } else if diff < 0.0 {
            // next item won't fit here; penalize small dead space less if large
            score += (-diff * 0.3).min(150.0);
        }
    }

    // Compare post_residual relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize wasting large residuals on small items
    score += (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64) * 0.2;

    // Prefer keeping large residual bins open for future large items
    score -= (bin_residual as f64 / bin_capacity as f64) * 20.0;

    // Mild preference for consolidating when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use; reward moderate leftover
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 50 {
        score -= 8.0;
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + next_item_size as f64 * 0.2;
        } else {
            // penalize blocking the next item badly
            score += 6.0;
        }
    }

    // Time horizon: early in stream, be conservative (favor filling existing bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> encourage consolidation
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score += 15.0 * mean_res_norm;
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64 - 4.0) * 1.5;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let penalty = 45.0 + 30.0 * (1.0 - fit_ratio);
        score += penalty;
        // allow opening when nearly no fitting bins and item is large
        if fitting_bins_count == 0 && item_size > 60 {
            score -= 70.0;
        }
        // late in stream, prefer closing out bins
        if progress > 0.8 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: post-residual scaled by non-linear progress coupling
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);

    // Non-linear penalty on wasted space (quartic in normalized residual)
    score += 40.0 * norm_pr * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Smooth interaction: post_residual with mean residual (avoid divergence from average)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 + progress);

    // Reward tight fits (low post residual) more strongly as stream progresses
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly prefer this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        score += 5.0 * (fit - 1.0) / (1.0 + open);
    }

    // Lookahead coupling: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste_gap = (pr - ni).max(0.0) / cap;
        score += 20.0 * waste_gap * waste_gap * cap / (1.0 + ni);
        // Reward if next item fits exactly in the post residual
        if ni <= pr {
            score -= 10.0 * (1.0 - ((pr - ni) / cap).abs());
        }
    }

    // Mild penalty for opening many bins late
    score += open * progress * 2.0;

    // New-bin candidate: discourage unless residuals are badly fragmented
    if bin_residual == bin_capacity {
        let frag = norm_pr.max(0.0);
        let pressure = (mean_residual / cap - 0.5).max(0.0);
        score += 12.0 - 10.0 * progress - 8.0 * pressure * open / (1.0 + open);
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
        let _ = frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let fit_ratio = if item_size > 0 { post_residual as f64 / item_size as f64 } else { post_residual as f64 };
    score += 3.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Harmonic classes: quantize post_residual into residue classes.
    // Small dead-space classes (< 10) are wasteful; mid classes (10..50) are reusable.
    let class = post_residual / 10;
    match class {
        0 => score += 8.0,          // 1..9: nearly unusable dead space
        1 | 2 => score -= 5.0,      // 10..29: usable for small items
        3 | 4 => score -= 8.0,      // 30..49: sweet spot
        5 | 6 => score -= 3.0,      // 50..69: large but ok
        _ => {}                     // 70+: mostly empty bin, neutral
    }

    // Lookahead: strongly favor bins whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward if next item fits snugly too
        let next_left = post_residual - next_item_size;
        if next_left <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        score += 6.0; // next item can't use this residual
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor. Compare against mean residual.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If open bins have plenty of space, discourage a new bin.
        score += 25.0 + 30.0 * (1.0 - pressure);
        // Early in stream, more tolerant of opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If no open bin really fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Mild preference for reusing existing bins vs mean residual gap.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Penalize creating residual that is awkwardly just below common item sizes.
    for t in [10u32, 20, 30, 40, 50, 60, 70, 80] {
        if post_residual > 0 && post_residual < t && (t - post_residual) <= 3 && t > item_size {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are useless, big gaps are reusable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 18.0; // mostly dead space
        } else if post_residual >= 50 {
            score -= 8.0; // large residual still very usable
        }
    } else {
        score -= 25.0; // perfect fit: strongly reward
    }

    // Reward exact match of leftover to the next item (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 6.0; // next item fits snugly afterwards
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: baseline plus pressure; only chosen when fits are terrible.
        score += 15.0 + pressure;
        // Prefer a new bin if mean residual of open bins is small (they are nearly full anyway).
        score += (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Progress: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 120.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact match with next item is a near-perfect packing chain.
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 30.0 + 0.5 * post_residual as f64;
        }
    }

    // Compare residual against mean residual across open bins: prefer bins
    // whose post-residual stays near the mean (balanced packing).
    score += 0.8 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are bad fits.
    if bin_residual == bin_capacity {
        score += 150.0;
        // If few bins can fit, opening fresh is more acceptable.
        score -= 40.0 * (fitting_bins_count as f64).min(3.0);
    }

    // Slight preference for tighter bins (small residual before placement).
    score += 0.1 * bin_residual as f64;

    // Late in stream, be greedier about filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 60.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // Penalize residual that is too small to be useful for the next item,
            // scaled by how dead the space is.
            let dead = (post_residual as f64) / (next_item_size as f64);
            if dead < 1.0 {
                score += 3.0 * (1.0 - dead);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        let mut new_bin_penalty = 7.0 * (1.0 - progress * 0.5);
        if mean_residual >= item_size as f64 {
            new_bin_penalty += 4.0 * pressure;
        }
        // If no open bin fits (fitting_bins_count counts only open bins and this
        // call is the new-bin candidate), opening is necessary: reduce penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for filling bins with larger residuals when many bins open.
    score += 0.02 * (bin_residual as f64 - mean_residual) * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth progress-coupled dead-space penalty: residual waste matters more early (need compact bins long-term)
    let progress_weight = 1.0 + 3.0 * t * (1.0 - t);
    score += progress_weight * x * x * cap;

    // Reward tight fits via cubic term in normalized fill
    let fill = (cap - pr) / cap;
    score -= 12.0 * fill * fill * fill * (1.0 + t);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: penalize if post_residual can't fit next item but barely misses
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        if pr < next_item_size as f64 {
            score += 5.0 * (1.0 - gap / cap);
        } else {
            score -= 4.0 * (1.0 - (pr - next_item_size as f64) / cap);
        }
    }

    // Crowding: mild penalty when many bins are open and this residual is above mean
    let crowd = (open_bins_count as f64).ln().max(0.0);
    if pr > mean_residual {
        score += 2.0 * crowd * (pr - mean_residual) / cap;
    } else {
        score -= 1.5 * crowd * (mean_residual - pr) / cap;
    }

    // New-bin candidate: smooth logistic-ish reluctance that grows with stream progress
    if bin_residual == bin_capacity {
        let reluctance = 8.0 + 30.0 * t * t;
        score += reluctance;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Harmonic classes: post_residual bucketed by integer division thresholds.
    // Residuals that are "dead" (too small for typical items) are penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr < 10 {
        score += 40.0; // dead space below minimum item size
    } else if pr < 20 {
        score += 18.0;
    } else if pr < 35 {
        score -= 8.0; // useful mid-range residual
    } else if pr < 60 {
        score -= 12.0; // highly reusable residual
    }

    // Modulo coupling: residual divisible by common item sizes is more reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would leave bad residual AND we already have many open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (post_residual as f64) < 25.0 && post_residual > 0;
        let many_open = (open_bins_count as f64) > 4.0 + 6.0 * (1.0 - progress);
        if bad_fit && many_open {
            score -= 20.0; // opening fresh bin is better than fragmenting
        } else {
            score += 35.0; // prefer existing bins generally
        }
    }

    // Mild preference to consolidate into fuller bins (small residual = full bin).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late-stream bias: tighten packing as stream progresses.
    score -= 10.0 * (step_index as f64 / total_items.max(1) as f64) * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small but nonzero) are heavily penalized since no future item (min size 1..10)
    // can realistically pair with them without waste.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    }
    // Medium dead space (11..25) is mildly risky.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0 * (25 - post_residual) as f64 / 15.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual tightly matches the item (low fragmentation).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 10.0 - slack; // near-perfect chaining
            } else {
                score += slack * 0.15; // wasteful for the chain
            }
        } else {
            // next item cannot use this bin's leftover: leftover becomes dead
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate handling: empty bin should only win when open bins
    // are badly fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        // baseline neutrality with slight pressure to consolidate early
        score = 45.0 + open_bins_count as f64 * 2.0;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    } else {
        // Compare against mean residual: filling below-mean bins is good.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward small slack after hypothetically fitting next item
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportional to leftover unusability
            let gap = (next_item_size - post_residual) as f64;
            score += 60.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score -= 40.0 * ((mean_residual - post_residual as f64) / bin_capacity as f64);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize creating large dead space (residual too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 200.0 + 300.0 * progress;
        if fitting_bins_count >= 1 {
            score += 150.0;
        }
    } else {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste ratio penalty.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing can use later, reward moderate residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward; if this bin
    // could have held the next item better, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_gap = mean_residual - item_size as f64;
        // If mean residual barely exceeds item size, existing bins are tight fits -> avoid new bin.
        if mean_gap < 8.0 {
            score += 30.0;
        } else {
            // Poor fits elsewhere: new bin more attractive, especially early/mid stream.
            score -= 10.0 + 15.0 * (1.0 - progress) * (mean_gap / bin_capacity as f64);
        }
        if open_bins_count > 20 {
            score += 5.0; // too many open bins: discourage proliferation
        }
    } else {
        // Mild bonus for using bins with larger residuals (best-fit style).
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Time-horizon coupling: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - pr / cap;
    score -= (progress * (1.0 - progress) * 4.0) * pr * 0.5; // mid-stream smoothness bonus
    score -= progress * tightness * tightness * 30.0;        // reward tight fits later
    score += (1.0 - progress) * (pr / cap) * (pr / cap) * 20.0; // penalize large dead space early

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill = nx / pr.max(1.0);
            score -= 25.0 * fill * fill;
        } else {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // Prefer filling bins when many bins are open; discourage bin proliferation.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: make it attractive only when current bin would leave
    // unusable residue relative to plausible next item sizes.
    if bin_residual == bin_capacity {
        let waste = if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 { 40.0 } else { 0.0 };
        score = 55.0 + waste - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in "quarter" classes of capacity
    let q = post_residual * 4 / bin_capacity; // 0..=3 harmonic class
    let class_penalty = match q {
        0 => 0.0,
        1 => 12.0,
        2 => 25.0,
        _ => 35.0,
    };
    score += class_penalty;

    // Perfect fit reward: post_residual exactly divisible by small harmonic divisors
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic match: next item leaves another clean residual
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 || next_post == 0 {
                score -= 8.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin fit is terrible
    if bin_residual == bin_capacity {
        let tight = post_residual as f64 / bin_capacity as f64;
        score = 60.0 + tight * 40.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // item might not fit anywhere later anyway
        }
    }

    // Progression: tighten packing later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).abs() * 0.3;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Strict dead-space avoidance ----
    // A post_residual that is too small to ever hold a plausible item (<= 9)
    // is pure dead space: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    }
    // Small-but-usable gap (10..=20) that likely cannot host future items
    // drawn from a wide distribution: moderate penalty, scaled by progress.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0 * (0.5 + progress);
    }

    // ---- Tight-fit reward ----
    // Fraction of the bin consumed by this placement; reward high fill.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // ---- Lookahead (k=2) ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong chaining reward.
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 {
            // Placement strands a gap too small for the next item.
            score += 10.0;
        }
    }

    // ---- Last-chance pressure ----
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        // This is the only bin that fits; avoid opening a new bin.
        score -= 30.0;
    }

    // ---- Open-bin pressure ----
    // Many open bins: prefer consolidating into existing bins; the empty-bin
    // candidate (bin_residual == bin_capacity) loses its tie advantage.
    let pressure = 2.0 * (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New bin: baseline preference only when few bins are open.
        score -= 6.0 - pressure;
        // Penalize new bin more when mean residual across open bins is large
        // (existing capacity is being wasted).
        score += 0.15 * mean_residual;
    } else {
        score -= pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post residual is good.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (-gap / 15.0); // decaying reward for near-match
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (1.0 - (-gap / 20.0)); // penalty when next item can't fit
        }
        // Bonus if next item exactly fills after chaining
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 8.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (consolidating space).
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are badly fragmented or it's a tight future fit.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).powi(2);
        score += 30.0 - 25.0 * fragmentation;
        if next_item_size > 0 && next_item_size >= item_size && item_size >= bin_capacity / 2 {
            score -= 10.0; // big item now, similar next: fresh bin is fine
        }
    }

    // Early stream: be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize residual that is dead space: too small for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.9 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room for the lookahead item.
            score -= 1.6 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64; // = capacity - item_size for empty bin
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 * (1.0 - pressure) + 0.5 * fit_quality;
        // Early in the stream, opening bins is cheaper; later, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // If next item is huge, a fresh bin may be valuable.
        if next_item_size >= 70 && post_residual >= next_item_size {
            score -= 18.0;
        }
    }

    // Prefer bins below mean residual (consolidate sparse bins).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Mild penalty when many bins are open: encourage filling existing ones.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream pressure: close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream progress coupling: later in the stream, waste matters more
    let prog_sq = progress * progress;
    score += 20.0 * norm_pr * norm_pr * (1.0 + 2.0 * prog_sq);

    // Reward using existing bins when many are open (avoid bin proliferation)
    if bin_residual != bin_capacity {
        score -= 3.0 + 0.5 * open_bins_count as f64;
    } else {
        // New bin penalty: heavier late in the stream
        score += 5.0 + 10.0 * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // penalize residuals that block the next item slightly
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual context: bins far from mean residual get mild penalty
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (small or exactly matching common sizes) are favored.
    let cap = bin_capacity as f64;

    // Class A: near-perfect fit (post_residual tiny) -> strong reward.
    if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Class B: leftover exactly divisible by common item sizes (mod logic).
    if post_residual > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 30, 40, 50] {
            if post_residual % d == 0 {
                harmony += 6.0;
            }
        }
        score -= harmony;
    }

    // Class C: leftover can host the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if leftover is an exact multiple of next size.
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to next item: penalize proportionally.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.3 * dead;
    }

    // Integer-division threshold: leftover in the "useless" band (11..=19)
    // is hard to fill -> penalize.
    if post_residual >= 11 && post_residual <= 19 {
        score += 15.0;
    }

    // Capacity-fraction classes: leftover near half or quarter capacity is
    // structurally reusable.
    if (post_residual as f64 - cap * 0.5).abs() <= 5.0 {
        score -= 5.0;
    }
    if (post_residual as f64 - cap * 0.25).abs() <= 3.0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // or late in the stream with large items expected.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_options = if next_item_size == 0 { 0.0 } else {
            (post_residual as f64 - (bin_residual - item_size) as f64).abs()
        };
        let _ = poor_options;
        // Base penalty keeps new bins from being opened casually.
        score += 18.0;
        // Relax when many bins are open but mean residual is fragmented.
        if open_bins_count > 4 && mean_residual < 25.0 {
            score -= 10.0;
        }
        // Late stream: fewer future opportunities, prefer fresh bins for
        // large items.
        if progress > 0.7 && item_size >= 50 {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Mild preference for tighter (fuller) bins overall.
    score += 0.05 * (bin_capacity - bin_residual) as f64 * -0.1;

    // Stream-phase modulation: early on, keep options open (penalize
    // extreme leftovers slightly); late, pack greedily.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress < 0.2 && post_residual > 60 {
            score += 5.0;
        }
        if progress > 0.8 {
            score -= 0.1 * post_residual as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Prefer bins with residual close to the mean (balance), avoid extremes.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Lookahead: if next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // post_residual can't hold next item: mild penalty for wasted space
            score += 8.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; a full new bin wastes nothing now but
        // adds a bin. Make it compete: slightly worse than a perfect fit,
        // better than a poor one.
        score += 30.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: tiny post-residual is excellent.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // small slack after next item => chained fit
            if slack <= 10.0 {
                score -= 35.0 - slack * 1.5;
            } else {
                score -= (20.0 / slack).min(15.0);
            }
        } else {
            // next item cannot fit here; penalize slightly more as gap grows
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Compare against mean residual: bins below mean residual are tighter, prefer filling them
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual {
            score -= (mean_residual - res) * 0.5;
        } else {
            score += (res - mean_residual) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Avoid leaving awkward dead space in a nearly-full bin that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        if post_residual as f64 > mean_residual + 20.0 {
            score += 15.0; // poor fit into any open bin, new bin looks ok
        }
        if crowded < 0.5 {
            score -= 30.0; // few bins / lots of room, opening fresh bin is fine
        } else {
            score += 25.0; // prefer reusing existing bins
        }
        // early stream: opening new bins cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Penalize leaving residual that is small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= (10.0 - next_waste / bin_capacity as f64 * 10.0).max(0.0);
        } else if next_item_size <= bin_residual {
            // next item fits this bin only if we place current item elsewhere
            score += 3.0;
        } else {
            // next item won't fit regardless; free residual is fine
            score -= 1.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.5;

    // Compare residual to mean residual: favor bins below mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in stream: more willing to open new bins (keep flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost plus time-dependent penalty.
        score = bin_capacity as f64 * 0.9 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't open a new bin when a last-chance bin exists
        }
    } else {
        // Late in stream: closing bins tightly is more valuable.
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let tight_fit_bonus = (1.0 - norm_pr).powi(3);
    score -= 30.0 * tight_fit_bonus * (0.5 + progress);

    // Penalize large dead space non-linearly, stronger late in stream
    score += 60.0 * norm_pr.powi(2) * (0.4 + 0.6 * progress);

    // Coupling: small post residual that can't fit next item is wasted
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr).max(0.0) / cap;
        score += 25.0 * waste * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
        // Reward if post residual still fits next item
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= 12.0 * fits_next;
    }

    // Last-chance bin reward
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: prefer bins deviating from mean to balance residuals
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Slight preference for opening new bins early vs late
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if new_bin {
        score += 5.0 + 15.0 * progress;
    }

    // Small cubic interaction of item size with progress
    score += 0.05 * (item / cap).powi(2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on
    // "usable" residue classes (small, re-fillable gaps) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: leftover in [1..=10] is a classic dead zone -> penalize,
    // leftover in [11..=30] is refillable by typical items -> reward.
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual >= 11 && post_residual <= 30 {
        score -= 12.0;
    } else if post_residual >= 31 && post_residual <= 50 {
        score -= 5.0;
    }

    // Modulo-arithmetic coupling: if the next item divides evenly into the
    // post residual (gcd-friendly), this bin chains nicely.
    if next_item_size > 0 && post_residual > 0 {
        let fits_next = next_item_size <= post_residual;
        if fits_next {
            // Reward tight chaining: next item nearly fills the remainder.
            let chain_tightness = next_item_size as f64 / post as f64;
            score -= 20.0 * chain_tightness;
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted harmony.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin residual is very
    // large (item would leave a big gap) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_placed = post as f64; // post_residual == capacity - item
        // Prefer opening a new bin when placing here wastes a lot AND
        // we already have many bins with slack.
        if waste_if_placed > 45.0 && mean_residual > 25.0 {
            score -= 30.0;
        }
        if progress < 0.15 {
            score -= 5.0;
        }
        // Slight default penalty so existing bins usually win ties.
        score += 10.0;
    }

    // Density coupling: placing into a bin whose residual is close to mean
    // keeps balance; deviations from mean get mild penalties.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Fragmentation guard: large open_bins_count with many near-empty bins
    // suggests consolidating into emptier bins.
    if open_bins_count > 8 && bin_residual as f64 > mean_residual + 20.0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 + (post_residual as f64) * 4.0;
    }

    // Reward tight fits: the smaller post_residual relative to bin size, the better.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Reward bins whose residual was already small (consolidating waste).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation, penalize new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 1.5 * (0.5 + progress);

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let perfect_fit_bonus = if post_residual == 0 { -80.0 } else { 0.0 };
        score += 55.0 + perfect_fit_bonus + (open_bins_count as f64) * 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that next item cannot use: penalize mildly.
        score += 5.0;
    }

    // Slightly prefer bins below mean residual (balancing large gaps).
    score += 0.1 * (post_residual as f64 - mean_residual).max(-20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64;

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so we only open when existing bins are poor fits
        score += 40.0 + 0.5 * mean_residual;
    } else {
        // Reward using an existing bin
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: perfect chaining bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact match: item fills bin so next item fits perfectly
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to how snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
        } else {
            // Next item does NOT fit: penalize wasted space that blocks lookahead
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.4;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with residuals below mean (consolidate small leftovers)
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    // Late in stream: tighten up, avoid opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    // Penalize tiny dead space (< 10) that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Many open bins: prefer filling existing ones down
    score += (open_bins_count as f64) * (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item, the better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio;

    // Penalize creating awkward dead space (small but nonzero leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward if next item fits almost exactly after this placement.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 6.0;
        }
    }
    // Penalize if next item would be blocked by this placement while other bins could host it.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 2 {
        let reuse_bonus = (open_bins_count as f64).ln() * 2.5;
        score -= reuse_bonus * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be more conservative (favor spreading);
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate handling: make empty bins less attractive unless the item
    // is large and no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // Large items justify a fresh bin more readily.
        score -= 0.15 * item_size as f64;
        // If few bins can fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
        // Early stream: new bins are cheaper; late stream: reuse is critical.
        score += 15.0 * progress;
        // If mean residual across open bins is high, reuse them instead.
        score += 0.3 * mean_residual;
    }

    // Mild penalty scaling with wasted fraction of this bin's residual.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, but weighted non-linearly by stream progress
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let prn = pr / cap;
    score += 40.0 * prn * prn * (1.0 - progress) * (1.0 - progress);
    score -= 25.0 * prn * (1.0 - prn) * progress;

    // Reward tight fits (small post_residual) more strongly as stream advances
    if pr == 0.0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: penalize if next item fits the post residual exactly (reserve space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let diff = (pr - nx) / cap;
            score -= 18.0 * (1.0 - diff) * (1.0 - diff) * (0.5 + progress);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Mean residual coupling: prefer bins deviating from mean toward small residuals
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev - 8.0 * dev;

    // Many open bins: mild penalty for keeping bins scattered
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residuals divisible by 10 are "harmonic"
    // and more likely reusable by future items (sizes 1..100, common multiples).
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0; // harmonic leftover: strong reward
    } else if class <= 3 {
        score += 3.0 + class as f64; // tiny sliver: dead space penalty
    } else {
        score += 1.0; // mildly awkward leftover
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain-perfect fit
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let fill = nxt / post_residual as f64;
            // harmonic coupling: next item's class vs leftover class
            let coupling = (next_item_size + post_residual) % 10;
            score -= 12.0 * fill + if coupling == 0 { 4.0 } else { 0.0 };
        } else {
            score += 5.0; // next item won't fit here; leftover likely wasted
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate (empty bin): penalize unless residuals are all large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual / cap; // average unusable fraction
        score += 8.0 + 20.0 * (1.0 - progress) - 15.0 * waste;
        // Opening a bin early is fine if item is large (harmonic big class).
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to item (tight fit) via integer
    // division threshold on ratio.
    let ratio = (bin_residual / item_size.max(1)) as f64;
    if ratio == 1.0 {
        score -= 8.0; // near-perfect fit
    } else if ratio >= 3 {
        score += 4.0; // very loose fit, wasteful
    }

    // Mean residual coupling: if this bin is far below mean, it's a good dump.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: less waste is better, superlinear.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Dead space: post_residual that is small but nonzero is hard to reuse.
    if post_residual > 0 && post_residual < 12 {
        score += 18.0 - 1.2 * post_residual as f64;
    } else if post_residual >= 12 && post_residual < 30 {
        score += 2.0; // moderately awkward gap
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: this is the only bin that fits; strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin only when the fit here is poor
    // and open-bin pressure is low.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 8.0 + 2.0 * pressure;
        if fit_ratio > 0.75 {
            score += 10.0; // opening a bin for a near-full item is wasteful
        }
        if post_residual == 0 {
            score -= 20.0; // exact fit into new bin is fine
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        if post_residual - next_item_size < 10 {
            score -= 4.0; // near-perfect two-item chain
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 1.5; // leftover can't serve next item
    }

    // Open-bin pressure: with many open bins, consolidate.
    score += 0.35 * open_bins_count as f64;

    // Late in the stream, favor closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward scaled by remaining slack
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item would NOT fit: penalize dead space creation
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: bins with residuals near the mean are "typical";
    // placing into a much-larger-residual bin wastes its capacity potential
    let gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize very small unusable post-residuals (dead space < 10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Late in the stream: be more conservative, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate: mild penalty so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    score -= 2.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3) * 10.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Reward when post-residual exactly accommodates the next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Reward when next item fits with room to spare after
        if post_residual >= next_item_size && post_residual - next_item_size < item_size.min(next_item_size) {
            score -= 5.0;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Early stream: more willing to open bins (diversity of residuals)
        if progress < 0.25 && open_bins_count < 4 {
            score -= 10.0;
        }
    }

    // Global fragmentation pressure: if mean residual is high, prefer bins
    // that reduce deviation from the mean (balance residuals)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer bins whose residual is closest to item size (waste minimization)
    let gap = (bin_residual as f64 - item_size as f64);
    score += gap * 0.1;

    // Many open bins: discourage spreading, favor filling existing ones
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post_residual, with non-linear emphasis
    let mut score = pr + 30.0 * norm_post * norm_post;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (favor filling many bins);
    // late, demand tight fits (penalize dead space super-linearly).
    let coupling = norm_post * (1.0 - progress) - norm_post * norm_post * progress;
    score += 40.0 * coupling;

    // Reward using bins that would otherwise strand space (last chance)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Penalize leaving residual close to the next item's size mismatch:
    // good if post_residual can host next item, bad if it just misses it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (nxt / cap);
        } else {
            let miss = (nxt - pr) / cap;
            score += 12.0 * miss * miss;
        }
    }

    // Mild penalty when bin residual is far from mean residual (imbalance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + progress);

    // Slight preference for reusing open bins over opening new ones
    score += 3.0 * (open_bins_count as f64).sqrt() * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Dead-space penalty: leftover that is too small to hold even the smallest item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class: how well post_residual divides into capacity fractions
    // Perfect harmonics (cap/1, cap/2, cap/3, cap/4) are desirable leftovers
    let mut harmonic_bonus = 0.0;
    for k in 1..=6u32 {
        let frac = cap / k as f64;
        let diff = (post_f - frac).abs();
        if diff < 2.0 {
            harmonic_bonus += 12.0 / k as f64;
        }
    }
    score -= harmonic_bonus;

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10; // 0..10 harmonic decile
    match class {
        0 => score += 25.0,           // nearly full bin: excellent
        1 => score -= 5.0,            // good tight fit
        2 | 3 => score -= 10.0,       // sweet spot: room for medium items
        4 | 5 => score -= 3.0,        // moderate
        6 | 7 => score += 4.0,        // large leftover, wasteful unless needed
        _ => score += 2.0,            // mostly-empty bin placement
    }

    // Lookahead: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact match modulo classes: next item exactly consumes leftover
            if next_item_size == post_residual {
                score -= 30.0;
            } else {
                score -= (next_item_size as f64) * 0.35;
            }
        } else {
            // Next item won't fit here; penalize proportionally to how close it is
            let miss = (next_item_size - post_residual) as f64;
            if miss < 15.0 {
                score += miss * 1.2;
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Cost of a fresh bin scales with how crowded the open set is
        let crowding = (open_bins_count as f64) * 0.5;
        let mean_gap = (mean_residual - post_f).abs();
        score += 45.0 + crowding + mean_gap * 0.3 - progress * 10.0;
        // If no other bin can fit, new bin must win
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Small tie-break noise-free coupling with step
    score += (step_index % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward if the leftover can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: mild penalty scaled by waste
        score += 0.3 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    if open_bins_count > 3 {
        score += 0.8 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin leaves a bad gap
    // or mean residuals are already low (poor utilization).
    if bin_residual == bin_capacity {
        let bad_gap = post_residual > 0 && post_residual < 10;
        if bad_gap {
            score -= 30.0; // fresh bin avoids creating dead space here
        } else {
            score += 45.0 + 0.5 * mean_residual; // prefer reusing open bins
        }
        // early stream: opening bins is cheap and useful
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (using a bin with residual near item size keeps mean residual low).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Next item cannot fit here afterwards: mild penalty for dead space.
        if next_item_size > post_residual {
            score += 4.0;
        }
    }

    // Penalize leaving residual far above mean (fragmentation risk).
    score += 0.8 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits (small post residual relative to capacity).
    score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer it only when it enables a good 2-step chain
    // or all existing fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 3.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Late in stream: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity, especially for big items.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * dead * dead;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // Reward leaving usable space for the next item, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 3.0;
        }
    }

    // Prefer filling bins when many bins are open (reduce bin count).
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * fit_ratio;

    // Prefer keeping residuals near the mean residual (balance across bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 2.0 * dev / bin_capacity as f64;

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize less early, more late.
        score += 5.0 + 10.0 * progress;
        // Opening a new bin is attractive if the item is large and no tight fit exists.
        if fit_ratio > 0.8 {
            score -= 8.0;
        }
    } else {
        score -= 4.0 * progress * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) dead-space cost
    let mut score = pr + 40.0 * fit_norm * fit_norm;

    // Smooth stream-progress coupling: later in the stream, dead space hurts more
    score += 30.0 * fit_norm * fit_norm * progress;

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= 25.0 * (-fit_norm * 6.0).exp() * (1.0 - progress * 0.5);

    // Last-chance bin: strongly favor using it, smoothly scaled
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - fit_norm);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - (next_item_size as f64) / pr.max(1.0));
    } else if next_item_size > 0 {
        // penalize leaving space that next item cannot use
        score += 5.0 * (1.0 - (next_item_size as f64) / (pr + (next_item_size as f64)));
    }

    // Coupling with mean residual: prefer bins below mean residual (consolidation)
    let dev = (mean_residual - pr) / cap;
    score -= 10.0 * dev;

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize mildly so we prefer good existing fits,
    // but allow opening when all fits are poor
    if bin_residual == bin_capacity {
        score = pr + 15.0 + 20.0 * fit_norm * (1.0 - progress) - 25.0 * (fit_norm * 5.0).exp() * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into capacity-fraction buckets.
    // Dead space classes: (0,10], (10,25], (25,50], (50,100]
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward small dead-space classes (lower class = better packing)
    score -= (4 - class) as f64 * 18.0;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo arithmetic on residual: residuals that are multiples of small
    // harmonics (10, 20, 25, 50) are more likely reusable by future items.
    let harmonic_bonus = if post_residual > 0 {
        let mut h = 0.0;
        if post_residual % 10 == 0 { h += 8.0; }
        if post_residual % 20 == 0 { h += 6.0; }
        if post_residual % 25 == 0 { h += 6.0; }
        if post_residual % 50 == 0 { h += 8.0; }
        h
    } else { 0.0 };
    score -= harmonic_bonus;

    // Lookahead coupling: reward if next_item_size fits exactly in post_residual,
    // penalize if next item cannot use the leftover space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residue
            let chain_res = post_residual - next_item_size;
            score -= 20.0 - (chain_res as f64) * 0.15;
        } else {
            // next item cannot use the leftover: penalize proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Integer-division threshold: leftover in [1,9] is near-useless dead space
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or we are early in the stream with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 0.0 }
            else if next_item_size > 0 && post_residual < next_item_size { 15.0 }
            else { 45.0 };
        score += desperation + progress * 20.0 - mean_residual * 0.05;
    }

    // Tie-break toward consolidating into fuller bins (smaller residual before placement)
    score += (bin_residual as f64) * 0.05;

    // Mild pressure against proliferating many open bins
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: subtract for small post_residual (nonlinear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize unusable dead space: gaps too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Penalize very small dead gaps (< 10) that likely can never be used.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 12.0 + 3.0 * open_bins_count as f64;
        // If no other bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Slight preference to fill existing bins as stream progresses.
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins with residuals close to what we leave behind (consistency).
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item fits exactly
    // into the post residual, mildly reward a compatible leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 50.0;
        } else {
            // leftover too small for next item -> dead space penalty scaled
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 40.0 * waste;
        }
    }

    // Prefer tight fits relative to mean residual.
    let tightness = 1.0 - (post_residual as f64 / (bin_residual as f64).max(1.0));
    score -= 30.0 * tightness;

    // Penalize bins far from mean residual (outliers).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good reuse exists.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring amplifies the benefit of small post_residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 40.0;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }

    // Lookahead: strongly reward if the next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize bins whose leftover is just below next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 25.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no good reuse exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If mean residual is large, reusing is likely better -> penalize new bin more.
        score += mean_residual * 0.6;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 50.0 * progress;
        // But if the item is huge relative to mean residual, new bin is fine.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 45.0;
        }
    } else {
        // Slight preference for bins that are already fairly full (waste-minimization).
        let fill = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
        score -= 15.0 * fill;
    }

    // Mild global balancing: prefer bins near the mean residual to keep options open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early stream: keep bins flexible (mild penalty for very low residuals early on).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && post_residual < 30 && bin_residual != bin_capacity {
        score += 10.0 * (1.0 - progress / 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover space, with non-linear (quadratic) coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress) + 0.004 * pr * pr * (0.5 + progress);

    // Reward tight fits: interaction between fill fraction and progress.
    let fill = item_size as f64 / cap;
    score -= 18.0 * fill * fill * (1.0 + progress);

    // Penalize dead space that is too small to be useful for typical items.
    let dead = pr / cap;
    if dead > 0.0 {
        score += 25.0 * dead * (1.0 - dead) * (1.0 - dead);
    }

    // Lookahead: reward residuals that can fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap) * (0.5 + progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: prefer it only early or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 8.0 + 20.0 * fragmentation - 10.0 * progress;
    }

    // Mild penalty for accumulating many open bins late in the stream.
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // small divisors of capacity are far more reusable than "odd" leftovers.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for &d in &[1u32, 2, 4, 5, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 1.0 / d as f64;
            }
        }
        // Reward harmonious residuals (subtract), penalize coprime-ish ones.
        score -= 12.0 * harmony;
        // Dead space penalty: tiny unfillable leftovers (< 10 min item).
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strongly favored.
        score -= 200.0;
    }

    // Fractional capacity coupling: prefer filling bins past half capacity.
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    if fill_frac > 0.5 {
        score -= 10.0 * fill_frac;
    } else {
        score += 8.0 * (0.5 - fill_frac);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            // next item fits: mild reward scaled by tightness
            score -= 20.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 5.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible
    // (large post_residual waste) or stream is early with few bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
    }

    // Divergence from mean residual: prefer bins whose residual is below
    // average (denser bins), gently.
    score += 0.3 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    // Integer-division threshold: residuals in (50, 60] are prime real estate
    // for mid-size items; keep them intact.
    if pr > 50 && pr <= 60 {
        score -= 15.0;
    }
    // Residuals just above a typical item size (20/40) are awkward.
    if (pr > 40 && pr < 50) || (pr > 20 && pr < 30) {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (low post_residual) are naturally favored.

    // Aggressive 2-step lookahead: strongly reward exact match between the
    // residual left behind and the next item's size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            let match_gap = pr - nx;
            // Perfect chain (post_residual == next_item_size) gets a big bonus.
            if match_gap == 0.0 {
                score -= 40.0;
            } else {
                // Reward proportionally to how close the next item fills the leftover.
                score -= 25.0 * (nx / pr);
                // Small extra penalty for wasted gap beyond the next item.
                score += 0.05 * match_gap;
            }
        } else {
            // Next item cannot use this residual at all: penalize dead space.
            score += 8.0 + 0.1 * (nx - pr);
        }
    }

    // Compare against mean residual across open bins: placing into a bin whose
    // post-residual deviates strongly (too large) is less attractive.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly so tight existing fits win,
    // but let it win when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Neutral-ish score: slightly above a good fit, below a bad fit.
        score = 45.0 + 0.2 * item_size as f64;
        // Late in the stream, opening fresh bins is riskier (leftover waste),
        // so make new bins slightly more expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the next item is large, a fresh bin has good future utility.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Discourage leaving residuals below the minimum item size (unusable dead space),
    // unless it is an exact fill.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 60.0 * (fit_ratio - 0.85);
    }

    // Penalize dead space: small post_residual is good, but tiny unusable slivers
    // (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 && pressure > 0.5 {
        score -= 10.0 * pressure;
    }

    // Time horizon: early in stream, prefer keeping bins flexible (moderate residual);
    // late in stream, prefer filling bins fully.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if t > 0.7 {
        score -= 8.0 * t;
    } else if post_residual as f64 > 0.8 * bin_capacity as f64 {
        // Avoid leaving huge residuals early unless it's a fresh bin.
        score += 5.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (fit_ratio < 0.6 && fitting_bins_count <= 2);
        if poor_fit_elsewhere {
            score -= 30.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, mildly sub-linear via quadratic damping
    let mut score = pr * (1.0 - 0.15 * norm_pr * norm_pr);

    // Smooth polynomial coupling of residual waste with stream progress
    let waste = norm_pr * norm_pr;
    score += waste * cap * (0.2 + 0.8 * progress * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving room close to next item size (smooth bell)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (-20.0 * diff * diff);
    }

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 10.0 * last_chance * (0.3 + 0.7 * progress);

    // Penalize bins far from mean residual (fragmentation signal)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Mild penalty when many bins already open (prefer consolidation)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin smoothly unless residual is tiny
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 4.0 * norm_item * cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small sizes (10, 20, 25, 50) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        let harmonic_bonus = if pr % 50 == 0 { 30.0 }
            else if pr % 25 == 0 { 20.0 }
            else if pr % 10 == 0 { 12.0 }
            else if pr % 5 == 0 { 6.0 }
            else { 0.0 };
        score -= harmonic_bonus;

        // Penalize awkward tiny dead space that nothing (min size 1..10) uses well
        if pr < 10 {
            score += (10 - pr) as f64 * 1.5;
        }
    }

    // Lookahead: reward if next item fits the post residual (harmonic chaining)
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + (pr - next_item_size) as f64 * 0.3;
            // exact chain: next item leaves zero again
            if pr == next_item_size {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; slight penalty for blocking chain
            score += 3.0;
            // if the next item exactly matches current residual, prefer keeping this bin for it
            if next_item_size == bin_residual && post_residual > 0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 55.0;
        // cheaper to open new bin early in stream or when many bins are open with low residuals
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        if open_bins_count > 0 {
            score += (mean_residual / cap) * 40.0; // crowded open bins -> new bin ok
        }
        // if no bin fits, opening is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Prefer tighter existing bins: scale by fill fraction
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= fill * 10.0;
        // spread load: mildly prefer bins below mean residual (more room left overall)
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    // Integer-division threshold on post_residual: bins leaving >= half capacity residual
    // are flexible; reward mildly.
    if pr >= bin_capacity / 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item.max(next_item_size.min(item_size)) {
            score += 500.0; // tiny unusable sliver
        } else if next_item_size > 0 && post_residual < next_item_size {
            // gap can't fit the lookahead item: dead space risk
            score += 40.0 + 2.0 * post_residual as f64;
        } else if post_residual <= 10 {
            score += 15.0; // near-perfect fit reward instead
        }
    }
    if post_residual == 0 {
        score -= 100.0; // perfect fit: close the bin
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage new-bin opening
    // and encourage consolidating into existing bins.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are open
        score += 25.0 + 8.0 * open_bins_count as f64;
        // but allow opening when existing residuals are large and fragmented
        if mean_residual > 45.0 {
            score -= 20.0;
        }
    } else {
        // placing into an existing bin reduces open-bin pressure
        score -= 3.0 * open_bins_count as f64;
    }

    // Match bin residual to upcoming need: prefer bins whose leftover
    // accommodates the next item snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / 100.0);
    }

    // Late in the stream, avoid leaving scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // exactly matches the next item's size (perfect chained fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 40.0; // exact 2-chain match
        } else if pr >= nxt {
            // leftover after next placement: penalize remaining dead space
            let after = pr - nxt;
            score += after * 0.6;
            score -= (100.0 - after).min(100.0) * 0.05;
        } else {
            // next item won't fit here; penalize proportionally to mismatch
            score += diff * 0.35;
        }
        // small lookahead alignment bonus: post_residual near next size
        score -= 12.0 / (1.0 + diff * 0.15);
    } else {
        // last item: prefer tightest fit
        score += 2.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter;
    // reward filling tighter-than-average bins, penalize loose ones.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 10 {
            score -= 15.0; // near-perfect fill
        }
    }

    // New-bin candidate: discourage opening a new bin unless all fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // allow new bin late in stream if many bins open (fragmentation)
        score -= (open_bins_count as f64) * 0.8;
    }

    // Progress-based mild tightening: prefer tight fits as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.3;

    // Penalize huge dead space nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // tiny leftover = excellent fill
    }
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space that cannot hold the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residuals that can still host the next item, scaled by how well.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space penalty: wasted residual relative to next item.
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 8.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but discourage opening
    // new bins when open bins fit reasonably well, especially late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * progress;
        if fitting_bins_count > 0 {
            score += 6.0;
        }
        // New bin is attractive if next item is huge and current residual can't chain.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if bin_residual < bin_capacity {
        let mean_gap = mean_residual - post_residual as f64;
        if mean_gap > 0.0 {
            score -= mean_gap * 0.5; // below-average residual => good bin, reward
        } else {
            score += (-mean_gap) * 0.25; // above-average residual => penalize mildly
        }
        // Consolidation pressure grows with number of open bins.
        score += open_bins_count as f64 * 0.3;
    }

    // Time horizon: early in stream, keep flexibility (prefer moderate residuals);
    // late in stream, pack aggressively into tightest fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let w = 0.5 + 0.5 * progress; // weight grows over stream
    score -= w * (prn * prn) * 20.0;          // reward large residual quadratically, more later
    score += (1.0 - prn) * (1.0 - prn) * 15.0; // penalize tight fits smoothly

    // Lookahead coupling: reward residual that can host next item (smooth kernel)
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let k = (diff / cap).clamp(0.0, 1.0);
        score -= 10.0 * k * k;
        score += 5.0 * (-diff / 20.0) * (-diff / 20.0); // penalize near-miss fits smoothly
    }

    // Last-chance bin: strong reward if it is the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Crowd penalty: with many open bins, discourage spreading (favor filling existing)
    let crowd = (open_bins_count as f64).ln() / (1.0 + (total_items as f64).ln());
    score += 8.0 * crowd * (1.0 - prn);

    // Mean residual alignment: prefer bins near the mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize opening a fresh bin unless residual is large
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * (1.0 - progress) + 6.0 * crowd;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: classify post_residual into capacity-fraction classes.
    // Small post_residual (<= 10) is dead space; penalize harshly.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }

    // Integer-division thresholds on post_residual: which future item sizes
    // (1..=100) can still fit? Reward bins that keep a "harmonically useful" residual.
    let usable = if post_residual >= 50 { 2 } else if post_residual >= 34 { 3 } else if post_residual >= 26 { 4 } else if post_residual >= 20 { 5 } else if post_residual >= 17 { 6 } else if post_residual >= 13 { 7 } else if post_residual >= 10 { 8 } else { 0 };
    score -= (usable as f64) * 8.0;

    // Coupling with next item: if next_item_size fits exactly into post_residual,
    // strongly favor this bin (lookahead harmony).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 500.0;
        } else if gap <= 10 {
            score -= 30.0;
        } else {
            score -= (gap.min(50)) as f64 * 0.3;
        }
    }
    // If next item cannot fit here, slightly penalize (this bin less useful for chain).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer reusing open bins when their residual
    // is reasonably tight; opening a new bin only attractive when mean residual
    // is large (open bins are fragmented) and this bin would be a fresh start.
    if bin_residual == bin_capacity {
        // Fresh bin: score is its full residual; adjust by fragmentation context.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - (mean_residual * 0.5) + progress * 30.0;
        // Discourage opening new bins when few bins are open (early stream).
        if open_bins_count <= 2 {
            score += 50.0;
        }
        // If the item is large, a new bin is fine (it will fill well).
        if item_size >= 50 {
            score -= 25.0;
        }
    } else {
        // Reuse bonus: slight reward for any existing bin.
        score -= 10.0;
        // Prefer bins whose residual is below mean (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are harmonically reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        else if post_residual % 25 == 0 { score -= 10.0; }
        else if post_residual % 20 == 0 { score -= 8.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        else { score += 4.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small for
    // typical future items but wasted) is heavily penalized.
    let dead_threshold = 30.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual < bin_capacity {
        // partial credit if next item still fits after this placement
        score -= 8.0;
    }

    // New-bin candidate: only attractive when this bin's fit is bad relative
    // to mean residual; penalize opening new bins when open bins exist and fit well.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // allow new bin late in stream when residuals are fragmented
        if open_bins_count > 0 {
            score += (mean_residual - post_residual as f64).abs() * 0.3;
        }
    }

    // Progress-based mild tightening: early stream, prefer keeping bins tidy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (low post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / cap;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size; penalize near misses that leave
    // awkward slivers.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as f64 - nx).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect chaining: item + next item fill bin
        } else if post_residual as f64 >= nx {
            score -= 25.0 * (1.0 - diff / cap);
        } else {
            // next item cannot fit here; penalize dead space proportional to gap
            score += diff * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter (smaller residual) than average.
    let rel = (post_residual as f64 - mean_residual) / cap;
    score += rel * 20.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual <= 5 {
            score -= 20.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current fit is very poor and the next item is small enough to pair
    // with the remainder of a fresh bin.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio > 0.55; // would leave more than 55% wasted
        let next_fits_pair = next_item_size > 0 && next_item_size as f64 >= post_residual as f64;
        if poor_fit || next_fits_pair {
            score -= 15.0;
        } else {
            score += 25.0; // discourage opening bins when good fits exist
        }
    }

    // Mild stream-progression pressure: later in the stream, be greedier
    // about filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (1.0 - fit_ratio);

    // Tie-break toward fewer open bins (consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 12.0 * fit_ratio;
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Bonus if next item then fits almost exactly.
            let nxt_fit = post_residual - next_item_size;
            if nxt_fit < 10 {
                score -= 15.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins mildly, more early when open bins exist.
        score += 20.0 + 15.0 * progress;
        if open_bins_count > 0 && mean_residual > item_size as f64 + 5.0 {
            score += 30.0;
        }
        // If nothing else fits well, opening a fresh bin is fine.
        if next_item_size > 0 && item_size > 60 {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate into bins with small mean residual (nearly full bins).
    if bin_residual != bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Slight time-dependent preference for filling bins later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize residuals and stream progress
    let pr = post_residual as f64 / cap;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: penalize large residuals early, less late
    let progress_weight = 0.6 + 0.8 * progress * progress;
    score += progress_weight * (pr * pr) * cap * 0.5;

    // Reward tight fits: smooth quadratic bonus as post_residual -> 0
    score -= (1.0 - pr) * (1.0 - pr) * 8.0;

    // Penalize dead space that cannot fit typical small items (non-linear)
    if post_residual > 0 {
        let dead = (post_residual as f64 / 10.0).powi(2);
        score += 0.15 * dead * (1.0 - progress);
    }

    // Lookahead coupling: reward residual that can fit next item, penalize otherwise
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let smooth = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score -= 4.0 * fits_next * (1.0 - smooth);
        score += 2.0 * (1.0 - fits_next) * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Slight penalty for spreading across many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Mild attraction toward bins near mean residual (smooth coupling)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 1.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4; // 25
    let class = (post_residual % quarter) as f64 / quarter as f64; // 0..1
    let class_index = post_residual / quarter; // 0..4

    // Reward placements whose post_residual lands in "usable" harmonic classes
    // (small post_residual = tight fit is good; post_residual exactly at class
    // boundaries like 25/50/75 are especially reusable by mid-size items).
    let tight_bonus = (1.0 - class) * 12.0;
    score -= tight_bonus;

    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual == quarter || post_residual == 2 * quarter || post_residual == 3 * quarter {
        score -= 18.0; // exact harmonic boundary residual
    }

    // Penalize dead space in the lowest class (tiny unusable slivers)
    if class_index == 0 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            // extra reward if next item also lands on a harmonic boundary
            if (post_residual - next_item_size) % quarter == 0 {
                score -= 10.0;
            }
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless existing residuals are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual - item_size as f64;
        let mut new_bin_penalty = 20.0 + 30.0 * progress;
        if avg_waste > item_size as f64 {
            new_bin_penalty += 10.0; // existing bins have plenty of room on average
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += new_bin_penalty;
        } else {
            score -= 5.0; // no alternative: new bin is fine
        }
    }

    // Mild preference for bins already below mean residual (balancing)
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Late-stream consolidation: tighten up as the stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let post = post_residual as f64;
    let next = (next_item_size as f64).min(cap);
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let open = open_bins_count as f64;
    let fits = fitting_bins_count as f64;
    let fill = (item_size as f64 / cap).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;

    // Convex waste term: strongly prefer tight placements.
    let mut score = post + 0.30 * post * post / cap;

    // Closing a bin completely is highly desirable.
    if post_residual == 0 {
        score -= 8.0 + 4.0 * progress + 0.10 * open + 2.0 * fill;
    }

    // Penalize residuals too small for the lookahead item; the penalty is
    // larger when the next item is large, because the replacement bin would
    // otherwise have little leftover room.
    if post_residual > 0 && next > 0.0 && post < next {
        let missing = next - post;
        let next_ratio = next / cap;

        score += missing * (2.0 + 3.0 * progress) * (1.0 + 0.02 * open)
            + next_ratio * (30.0 + 20.0 * progress)
            + 0.03 * missing * missing;
    } else if post_residual > 0 && next > 0.0 && post >= next {
        // Reward leaving a residual that can still absorb the next item.
        score -= 2.0 + 2.0 * progress + 2.0 * (next / cap);
    }

    if !is_new_bin {
        // General pressure toward using already-open bins.
        score -= 0.8 + 0.08 * open;

        // Last fitting bin: avoid opening a new bin unless the fit is terrible.
        if fitting_bins_count <= 1 {
            score -= 3.0 + 2.0 * progress + 0.08 * open;
        }
    } else {
        let fitting_pressure = if fitting_bins_count > 0 {
            4.0 + 1.2 * fits.sqrt()
        } else {
            0.0
        };

        score += 8.0
            + fitting_pressure
            + (1.0 - fill) * 6.0
            + open * (0.45 + 0.55 * progress)
            + 0.04 * mean_residual.max(0.0);

        // If any open bin fits, a new bin is dominated when it cannot absorb
        // the lookahead item, or when there is no lookahead item left.
        if fitting_bins_count > 0 && (next_item_size == 0 || post < next) {
            score += 1.0e9;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits again: penalize leftover dead space relative to match quality.
            let second_post = post_residual - next_item_size;
            score -= 60.0 - second_post as f64 * 0.8;
        } else {
            // Next item won't fit here: penalize proportionally to wasted capacity.
            let waste = next_item_size - post_residual;
            score += waste as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual of open bins.
    // Leaving residual close to mean keeps flexibility; extreme small residuals are dead space.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < mean_residual * 0.35 {
            score += 25.0; // fragmenting a bin below typical residual
        } else if (pr - mean_residual).abs() < 5.0 {
            score -= 15.0; // keeps balanced residuals
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor
    // and the next item is large (would benefit from a fresh full bin).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0
            && next_item_size > 0
            && (next_item_size as f64) > post_residual as f64;
        if poor_fit || open_bins_count == 0 {
            score -= 180.0;
        } else {
            score += 150.0;
        }
    }

    // Slight preference to fill more-occupied bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (1.0 - progress);

    // Tie-break: prefer bins with fewer alternatives competing.
    if fitting_bins_count > 3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small dead space only if it can't plausibly host a future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance logic: if this is the only fitting bin, keep the item here
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins are open with slack, discourage another one.
        score += 3.0 * open_bins_count as f64;
    }

    // Prefer bins with residual above the mean (use big bins for big items).
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smoothly increasing penalty on leftover space as stream progresses
    let tightness = (pr / cap).powi(2) * (1.0 + 3.0 * progress);
    score += tightness * cap * 0.5;

    // Reward near-perfect fits (small post_residual) with a non-linear bonus
    let fit_bonus = (1.0 - pr / cap).powf(3.0) * 30.0;
    score -= fit_bonus;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Dead-space coupling: post_residual too small for typical items is waste
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += ((next_item_size as f64 - pr) / cap).powi(2) * 20.0;
    } else if next_item_size > 0 {
        score -= 8.0;
    }

    // New-bin candidate: prefer it when open bins are mostly full
    if bin_residual == bin_capacity {
        score -= 10.0 + 15.0 * (mean_residual / cap) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 10.
    // Residuals that are "dead" (small, hard to fill) get penalized super-linearly.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // Dead-space penalty: quadratic in post_residual, modulated by class.
        let class_factor = match class {
            0 => 0.8,               // perfectly aligned residual, very reusable
            5 => 1.0,               // half-capacity aligned
            2 | 4 | 6 | 8 => 1.1,   // even, moderately reusable
            _ => 1.35,              // odd residuals, awkward
        };
        score += 0.06 * (pr as f64).powi(2) / cap * (class_factor - 1.0);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // fraction of post residual consumed by next item
            let fill = next_item_size as f64 / pr as f64;
            score -= 18.0 * fill * fill;
        } else {
            // next item cannot fit here: mild penalty scaled by waste
            score += 0.10 * (next_item_size as f64 - pr as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: neutral base so it's chosen only when
    // all open bins score poorly (large post_residual / dead classes).
    if bin_residual == bin_capacity {
        // Opening a new bin: cost grows with stream progress and open-bin count
        // (encourage consolidation late in the stream).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.55 * cap + 8.0 * progress + 0.5 * open_bins_count as f64;
        // A new bin is attractive if next item is huge and nothing fits well
        if next_item_size > 0 && next_item_size > bin_residual.saturating_sub(item_size) {
            score -= 5.0;
        }
    }

    // Tie-break toward tighter fits relative to mean residual of open bins.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Exact fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are pure waste.
    // Treat residuals in (0, 10] as near-total loss; small gaps < next_item_size are dead too.
    if post_residual > 0 {
        let dead_by_lookahead = next_item_size > 0 && post_residual < next_item_size;
        let tiny = post_residual <= 10;
        if dead_by_lookahead || tiny {
            score += 40.0 + post_residual as f64 * 0.5; // heavy penalty for unusable gap
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead synergy: if the next item exactly fits the leftover space, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // leftover usable by next item: mild reward proportional to usability
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a new bin unless fit is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
        // Penalize opening new bins mildly; worse when open bins are already tight (low mean residual).
        score += 20.0 + 0.5 * open_bins_count as f64 - 0.3 * mean_residual + 0.1 * fragmentation;
        let _ = pressure; // reserved coupling
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Open-bins pressure: gently prefer filling existing crowded bins to cap bin count.
    score += 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // exact match: item chain continues perfectly
        } else {
            score -= 25.0 * (-diff / 20.0).exp(); // graded lookahead reward
        }
        // Penalize post_residual too small for next item AND small in general (dead space)
        if (post_residual as i64) < (next_item_size as i64) {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal leftover
        score += 0.5 * post_residual as f64;
    }

    // Reward bins that are tighter than the mean residual (good fills)
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        // New bin: residual = C - item; attractive only if open bins are fragmented
        score += 20.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin can host next item too
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize tiny dead space only if it is truly unusable later; otherwise
    // small residuals are fine (near-perfect fits). Use a dead-zone curve.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fit: small leftover is harmless
    } else if post_residual >= 10 && post_residual < 30 {
        score += 3.0 * (1.0 - tightness); // medium dead space penalty scaled by sloppiness
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_ratio = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 8.0 * (1.0 - slack_ratio);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for next item: penalize proportionally to wasted capacity
        score += 4.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a new bin is bad early and when open bins are still roomy.
        score += 20.0 * (1.0 - progress) + 25.0 * fragmentation;
        // But if the item is large and would leave bad residue anywhere, new bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 10.0;
        }
        // Late in the stream with many bins, avoid spreading.
        if progress > 0.8 {
            score += 10.0 * progress;
        }
    }

    // Prefer bins below the mean residual (concentrate filling).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Mild pressure to close out nearly-full bins.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, non-linearly in post_residual
    let mut score = pr * pr / cap;

    // Smooth coupling: post_residual value decays with stream progress
    // (late in the stream, residual space is less valuable to preserve)
    score -= pr * (1.0 - progress) * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score += (1.0 - norm_pr).powi(3) * 20.0 * (0.5 + progress);

    // Penalize opening new bins late; slight reward early
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (5.0 + 40.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-diff / 10.0).exp();
    }

    // Mild preference for bins deviating from mean residual (consolidation)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0 * progress;

    // Crowding penalty: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod 10 buckets.
    // Residuals that are multiples of 10 are "harmonic" — easier for future
    // items (drawn from a 1..100 grid) to pair with them.
    let harmonic_class = post_residual % 10;
    let harmonic_penalty = (harmonic_class as f64) * 0.35;
    score += harmonic_penalty;

    // Dead-space cliff: post_residual below 10 is nearly unusable waste.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but measure the leftover after it (chained residual).
            let chained = post_residual - next_item_size;
            score -= 8.0 - (chained % 10) as f64 * 0.3;
        } else {
            // Next item cannot use this residual: penalize proportionally to waste.
            score += (next_item_size.min(bin_capacity) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit
    // elsewhere is bad. Penalize fresh bins mildly.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Tightness reward: filling most of the current residual is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Integer-division threshold on post_residual: residual in [30,50) is a
    // "sweet spot" class (fits mid-size items), residual in [10,30) is risky.
    let div_class = post_residual / 25;
    match div_class {
        0 => score += 6.0,          // 0..24 : near-dead
        1 => score += 2.0,          // 25..49: medium
        2 => score -= 2.0,          // 50..74: sweet
        _ => score -= 1.0,          // large residual, item was small
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // Slight pressure when many bins are open: prefer consolidation.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals below the minimum item size are unusable forever.
    if post_residual > 0 && post_residual < 10 {
