    // Small residuals (10..20) are only usable by the smallest items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward very tight fits (post_residual small but nonzero).
    if post_residual > 0 && post_residual <= 10 {
        score -= 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // Penalize leaving a residual the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no open bin
    // offers a good fit (i.e., when all fits would be wasteful).
    if bin_residual == bin_capacity {
        // Base competitive score for a fresh bin.
        score = 55.0 + (item_size as f64) * 0.3;
        // If the item nearly fills a fresh bin, opening a new bin is great.
        if item_size >= 80 {
            score -= 30.0;
        }
        // If other bins fit, discourage opening a new bin unless they'd waste space.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // Early in the stream, opening new bins is cheaper (future flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual deviates favorably from the mean (larger residual
    // bins are better targets for big items, smaller residual for small items).
    let diff = bin_residual as f64 - mean_residual;
    score -= diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
