            score += 3.0 + 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive
    // only when it enables a very tight placement, otherwise discourage it.
    if bin_residual == bin_capacity {
        score += 6.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> favor filling
    // existing bins rather than spreading.
    if open_bins_count > 2 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
        score -= 0.02 * (open_bins_count as f64 - 2.0);
    }

    // Reward placing large items into bins with just enough room.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: residual waste penalized more later in the stream
    score += 60.0 * t * norm_pr * (1.0 - t) * 4.0;

    // Reward tight fits: subtract when post_residual is small, scaled by item size
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (item_size as f64 / cap);

    // Lookahead: if next item fits perfectly in post residual, favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 30.0 * fit_ratio * (1.0 - (fit_ratio - 0.5) * (fit_ratio - 0.5));
    } else if next_item_size > post_residual {
        // Next item can't use this leftover: mild penalty, stronger late in stream
        score += 15.0 * (0.5 + t) * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: prefer only if open bins are nearly full on average
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - (mean_residual / cap);
        score += 80.0 - 70.0 * mean_fullness * mean_fullness;
    }

    // Penalty for excessive fragmentation relative to mean residual
    score += 10.0 * ((pr - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into
    // capacity fractions (1/8 granularity) and reward "usable" classes.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor();
    let class_center = class * eighth + eighth * 0.5;
    let deviation = (post_residual as f64 - class_center).abs();

    // Reward post-residuals that align with harmonic grid points
    // (they are more likely to be exactly filled by future items).
    score -= 6.0 * (1.0 - deviation / eighth);

    // Integer-division dead-space penalty: leftovers smaller than the
    // smallest plausible item chunk are nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item can't use the leftover -> leftover likely dead
            score += 0.25 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has huge residual; make it
    // attractive only when no open bin fits well (its raw residual is
    // large, so subtract a controlled bonus but keep it worse than a
    // tight fit).
    if bin_residual == bin_capacity {
        score = 0.5 * (bin_capacity as f64) - 10.0 * open_bins_count as f64;
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // if next item is large, a fresh bin is more flexible
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from
    // the mean toward smaller values (consolidate space).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Modulo logic on residual: leftovers congruent to multiples of 10
    // are statistically easier to fill exactly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the next item
    // (or any plausible small item, min size 1..=10) are heavily penalized.
    if post_residual > 0 {
        let unusable_for_next = next_item_size > 0 && post_residual < next_item_size;
        let tiny_gap = post_residual < 10; // dead space below smallest plausible item
        if unusable_for_next {
            score += 25.0 + 0.5 * (post_residual as f64);
        }
        if tiny_gap {
            score += 40.0; // hard penalty for near-unusable slivers
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.1 * slack; // prefer just-enough room over excess
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when open-bin pressure
    // is low; allow it when many bins are open and mean residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 35.0 - 20.0 * (open_bins_count as f64 / 20.0).min(1.0)
                     - 15.0 * fragmentation
                     + 10.0 * (1.0 - progress);
    } else {
        // Mild pressure to prefer fuller bins among open candidates.
        score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect packing (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 15 {
        score -= 150.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let next_gap = post_residual - next_item_size;
            if next_gap <= 10 {
                score -= 300.0 - next_gap as f64 * 10.0;
            } else {
                score -= 100.0 - next_gap as f64 * 2.0;
            }
        } else {
            // Next item won't fit here: penalize more if we leave a large unusable gap.
            let gap = post_residual as f64;
            if next_item_size <= bin_capacity {
                score += gap * 0.5;
            }
        }
    }

    // Compare residual against mean residual: leaving less than average is good.
    score -= (mean_residual - post_residual as f64) * 3.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if the item is large, filling a fresh bin is natural.
        if item_size >= bin_capacity / 2 {
            score -= 200.0;
        }
        // Late in stream, prefer reusing open bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Mild pressure to prefer fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Exact fill is excellent
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= (1.0 - gap / bin_capacity as f64) * 10.0;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap = post_residual as f64;
            if gap < 10.0 {
                score -= 5.0; // tiny dead space is fine
            } else {
                score += gap * 0.15;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when good options exist,
    // but allow it when residuals are all small (fragmented state)
    if bin_residual == bin_capacity {
        let avg_frag = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        if avg_frag > 0.5 {
            score -= 10.0; // if open bins are half-empty, fresh bin less costly
        }
    }

    // Prefer bins with residuals below the minimum item size (10) — they're nearly dead
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    // Mild penalty for deviating from mean residual (balance the pool)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Later in the stream, dead space matters more -> amplify residual penalties.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear penalty for residual that is too small to be useful
    // (dead space), weighted by lookahead item size.
    let next = next_item_size as f64;
    if next > 0.0 {
        let usable = (pr - next).max(0.0);
        let waste = pr - usable; // smooth ramp, not a hard step
        score += 1.5 * waste * (1.0 - progress * 0.5);
        // Reward bins that can still hold the next item (smooth quadratic bonus)
        let fits_next = (pr >= next) as f64;
        score -= 6.0 * fits_next * (1.0 - (pr_norm - next / cap).abs());
    }

    // Penalty for very large post-residual early on (fragmentation risk),
    // smoothly decreasing as stream progresses.
    score += 10.0 * pr_norm * pr_norm * (1.0 - progress) * (mean_residual / cap).max(0.0).min(2.0) * 0.5;

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation),
    // smoothly scaled by how full this placement keeps the bin.
    let fill = 1.0 - pr_norm;
    score += 3.0 * (open_bins_count as f64).ln() * (1.0 - fill) * (1.0 - progress);

    // Tight fits reward: quadratic coupling of fill with progress.
    score -= 8.0 * fill * fill * progress;

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are more reusable; reward them.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best outcome
    } else {
        if post_residual % 50 == 0 { score -= 18.0; }
        else if post_residual % 25 == 0 { score -= 12.0; }
        else if post_residual % 20 == 0 { score -= 10.0; }
        else if post_residual % 10 == 0 { score -= 8.0; }
        else {
            // irregular residual: penalize dead space more strongly
            score += 6.0;
        }
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain a perfect follow-up
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // harmonic class of the leftover after next item
            if slack % 10 == 0 { score -= 8.0; } else { score += slack as f64 * 0.15; }
        } else {
            // next item won't fit here; residual likely becomes dead space
            score += post_residual as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if post_residual == 0 {
            score -= 50.0;
        }
        // penalize opening new bins when open bins still have room
        score += pressure * 25.0 + (open_bins_count as f64).sqrt() * 5.0;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer tight fits generally: reward small post_residual relative to item
    score -= (item_size as f64) * 0.1;

    // Mild preference for bins below mean residual (balance spreading)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (below the minimum item size, or a tiny unusable sliver)
    // are heavily penalized, scaled by how "trapped" the gap is.
    let min_item = 1.0f64;
    if post_residual > 0 {
        if (post_residual as f64) < min_item {
            score += 1000.0; // exact-fill is ideal; unreachable branch guard
        }
        // Dead space: gap smaller than half a typical item is likely wasted.
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 8.0; // unusable sliver -> big penalty
        } else if gap < 25.0 {
            score += (25.0 - gap) * 2.5; // risky small gap
        }
    } else {
        // Perfect fill: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 20.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the gap -> dead space confirmed for one step.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading residual space;
    // prefer placements that consolidate (large post_residual is worse then).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (open_bins_count as f64) * 1.5 * (0.5 + progress);

    // Prefer bins whose residual is below mean residual (consolidating small ones),
    // penalize dumping into already-large-residual bins.
    score += ((post_residual as f64) - mean_residual) * 0.4;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit or the item nearly fills a fresh bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // But if the item is large, a fresh bin wastes little; discount.
        score -= (item_size as f64 - 50.0).max(0.0) * 0.5;
        // If many bins fit the item, opening new is unattractive.
        score += (fitting_bins_count as f64) * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            // partial match: reward proportional to how much of post_residual gets used
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * usage * usage;
        } else {
            // next item cannot use the leftover: penalize large dead space
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving more than average leftover is wasteful when space is plentiful.
    if post_residual as f64 > mean_residual {
        score += 0.20 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        // opening a new bin is fine if the item is large relative to capacity
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect closure bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small dead space (< 10) that likely can't fit future items (min size 1,
    // but small gaps rarely match). Scale by how much of the bin is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item won't fit here; slight penalty proportional to leftover waste.
            score += 0.05 * post_residual as f64;
        }
    }

    // New-bin candidate handling: make empty bins mildly unattractive so we prefer
    // existing bins with decent fits, but attractive when fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many bins are open already, discourage opening another.
        score += 1.5 * open_bins_count as f64;
    }

    // Global balance: prefer bins whose residual is close to the mean residual
    // (keeps the pool of usable space uniform), unless it's a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Slight preference for fuller bins (smaller residual) generally.
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space after placement
    let mut score = pr + 0.9 * pr * norm_pr;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight packing; late, prefer preserving flexibility
    let progress_coupling = (pr / cap).powf(1.0 + 2.0 * progress) * (1.0 - progress) * 30.0;
    score += progress_coupling;

    // Interaction: post_residual vs mean residual (harmony bonus)
    let harmony = (pr - mean_residual) / cap;
    score += 12.0 * harmony * harmony - 8.0 * harmony * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let fit_quality = 1.0 - (pr - n) / cap;
            score -= 10.0 * fit_quality * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * (n - pr) / cap;
        }
    }

    // Mild penalty when many bins are open (consolidation pressure)
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: bias against opening a new bin unless residual is huge
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress) + item_size as f64 * 0.3;
    } else {
        // Reward using existing bins proportionally to fill ratio
        score -= (item_size as f64 / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and small-dead-space classes rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 30.0;
    } else if pr <= 20 {
        score -= 12.0;
    } else {
        // penalize dead space super-linearly, quantized into capacity fractions
        let frac = pr as f64 / cap;
        score += 25.0 * frac * frac;
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes (10..=20)
    // are "harmonic" and likely reusable by future items.
    let mut harmonic = 0.0;
    for m in [10u32, 12, 15, 16, 20, 25, 30, 40, 50].iter() {
        if pr % m == 0 && pr > 0 {
            harmonic += 8.0;
        }
    }
    score -= harmonic;

    // Integer-division thresholds: post_residual bucketed by cap/4 quarters.
    let quarter = bin_capacity / 4;
    if pr < quarter {
        score += 6.0; // tiny remainder, hard to reuse
    } else if pr >= 2 * quarter {
        score -= 10.0; // half or more free: very reusable
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize leaving awkward gap
            score += 5.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default mildly discouraged unless current fit is bad
    // or stream is early (building a pool of bins can help).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (post_residual as f64 / cap) < 0.35;
        if bad_fit || progress < 0.1 {
            score -= 14.0;
        } else {
            score += 10.0;
        }
    }

    // Slight preference for tighter bins overall (below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual exactly matches the next item (lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that the next item barely misses.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over wasting it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: make it moderately attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64) <= 0.0
            || (fitting_bins_count > 0 && (bin_residual - item_size) < 10);
        score += 45.0 - if poor_fit { 55.0 } else { 0.0 };
    }

    // Slight preference for filling larger-residual bins to consolidate space.
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += tightness * 20.0;

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the leftover
            let chain_fit = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 30.0 * chain_fit;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    } else {
        // last item: prefer minimal waste
        score += 10.0;
    }

    // Last chance: this is the only bin that fits; strongly prefer using it over a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Compare residual against mean residual: bins with below-mean residual (tighter) are preferred
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Penalize leaving very small unusable gaps (dead space < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Prefer filling already-open bins over opening new ones, especially late in the stream
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    if bin_residual == bin_capacity {
        // new bin candidate: add penalty so it's chosen only when fits are bad
        score += 40.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward small residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space trap
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong bonus to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // If next item is large, prefer conserving big-residual bins.
        if next_item_size >= 60 && post_residual < next_item_size as u32 {
            score += 6.0;
        }
    }

    // Global dispersion: if this bin's residual deviates strongly from the mean,
    // mildly penalize to keep residual profile homogeneous (easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins (score new
    // bins better); late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 20.0 - 35.0 * progress;
        // Never open a new bin when an existing bin closes perfectly or is last chance.
        if post_residual == 0 || fitting_bins_count == 1 {
            score += 60.0;
        }
    } else {
        // Prefer fuller bins among open ones (more packed bins get priority).
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
        // Many open bins: encourage consolidation into existing bins.
        if open_bins_count > 4 {
            score -= 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 12.0 * poly;

    // Tight fits are rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.5 + t);

    // Penalize dead space that can't fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (pr - ni).max(0.0) / cap;
        score += 8.0 * waste * waste * (1.0 + t);
        // Reward leaving room exactly for next item
        let gap = (pr - ni).abs() / cap;
        score -= 4.0 * (1.0 - gap.min(1.0)) * (1.0 - t);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many bins
    score += 0.05 * open_bins_count as f64 * t;

    // Prefer bins below mean residual slightly (balance residuals)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 5.0 * (1.0 - fill) * (1.0 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover: residual classes by capacity fraction
    let frac = post_residual as f64 / cap;
    // Penalize "dead" residuals that are too small to be useful (below smallest item scale)
    let tiny_dead = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
    score += tiny_dead;

    // Reward near-perfect fits (harmonic resonance: residual divisible into small classes)
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if frac < 0.2 {
        score -= 10.0;
    }

    // Modulo logic: leftover that is a multiple of common item sizes (10,20,25,50) is reusable
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if reusable && post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use leftover -> leftover likely dead
            score += 12.0;
        }
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // cheaper to open new bin early in stream or when few bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // if next item is large, a fresh bin is attractive
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference to keep bins balanced relative to mean residual
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
