    }
    // Penalize if the residual left is just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: if this bin is much tighter than average, prefer it.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Early in the stream, be slightly more willing to use open bins (avoid bin proliferation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // New-bin candidate: only attractive when it beats a very poor fit elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent chain: next item slots perfectly after current one
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 0.5 * slack;
            // Perfect two-item fill
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward leftover space
            score += 10.0;
            // Extra penalty when leftover is small (unusable dead space)
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Tight fit reward: prefer bins where post_residual is small but non-wasteful
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Compare against mean residual: prefer bins that reduce residual imbalance
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin is acceptable if current item is large or fitting options are scarce
        if item_size > 50 || fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 30.0;
        }
    }

    // Slight late-stream bias toward consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of fit: reward near-exact fills.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver -> fine, waste is bounded
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0; // moderately hard to reuse
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let wasted = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - wasted / (bin_capacity as f64));
        } else {
            // next item can't follow here; slight penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin that becomes most reusable.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: if mean residual is high, prefer bins that
    // consume the most space (reduce fragmentation across the fleet).
    let residual_gap = (mean_residual - post_residual as f64).abs();
    score -= 0.5 * residual_gap;

    // Time horizon: early in the stream, be conservative about opening new
    // bins (favor existing); late in the stream, tightness dominates anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tight;

    // New-bin candidate handling: empty bin should only win when the item
    // fits poorly everywhere else or fleet is saturated.
    if bin_residual == bin_capacity {
        let fleet_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let poor_fit_elsewhere = (fitting_bins_count == 0) as i32 as f64;
        let lookahead_mismatch = if next_item_size > 0 && next_item_size > item_size { 1.0 } else { 0.0 };
        score += 40.0
            - 10.0 * poor_fit_elsewhere
            - 0.3 * fleet_pressure
            - 8.0 * lookahead_mismatch
            - 5.0 * (1.0 - progress);
    }

    // Mild bonus for filling a bin completely (zero waste).
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and item size
    let pr = post_residual as f64 / bin_capacity as f64;
    let s = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: penalize large post-residuals more as stream progresses
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;
    score += t * (2.0 * pr2 + 4.0 * pr3) * (bin_capacity as f64);

    // Reward tight fits smoothly: quadratic in item size, amplified by progress
    score -= (s * s) * (1.0 + 2.0 * t) * 10.0;

    // Dead-space term: post-residual too small for typical future items is wasted
    let dead = (1.0 - pr).max(0.0);
    score += dead * dead * (bin_capacity as f64) * 0.5;

    // Interaction with mean residual: prefer bins deviating below mean when mean is high
    let mr = mean_residual / bin_capacity as f64;
    score += 3.0 * t * mr * (pr - mr).abs();

    // Last-chance bonus: smooth reward when few fitting bins
    let fit_norm = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
    score -= 8.0 * fit_norm * fit_norm;

    // Lookahead coupling: reward leaving room for the next item (smooth quadratic)
    if next_item_size > 0 {
        let n = next_item_size as f64 / bin_capacity as f64;
        let gap = (pr - n).abs();
        score -= 5.0 * (1.0 - gap.min(1.0)) * (1.0 + t);
    } else {
        // Last item: strongly prefer minimal post-residual
        score += 3.0 * pr2 * (bin_capacity as f64);
    }

    // Mild pressure against bin proliferation
    score += (open_bins_count as f64).sqrt() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into coarse buckets.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual in 1..=10 (small dead space, likely unusable for min items) -> penalize.
    // Class 2: post_residual in 11..=50 (usable mid-range) -> mild reward.
    // Class 3: post_residual in 51..=100 (large leftover) -> neutral-to-good.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 10 {
        score += 60.0;
    } else if pr <= 50 {
        score -= 15.0;
    } else {
        score -= 5.0;
    }

    // Integer-division thresholds: how well does next_item_size divide into post_residual?
    if next_item_size > 0 && pr > 0 {
        let nxt = next_item_size;
        if nxt <= pr {
            let quot = pr / nxt;
            let rem = pr % nxt;
            if rem == 0 {
                // next item exactly fills leftover after this placement
                score -= 80.0 * (quot as f64).min(3.0);
            } else if rem <= 10 {
                score += 40.0; // leaves tiny dead space for the item after next
            } else {
                score -= 20.0 * (quot as f64).min(2.0);
            }
        } else {
            // next item cannot use this bin's leftover at all
            score += 30.0;
        }
    }

    // Last-chance bonus: only one bin can fit this item; using it avoids opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when fit elsewhere is poor
    // or leftover would be tiny dead space.
    if bin_residual == bin_capacity {
        // base preference for new bin when current placement leaves dead space
        if pr <= 10 && pr > 0 {
            score -= 100.0; // open new bin rather than create unusable sliver
        } else {
            score += 120.0; // default: prefer existing bins
        }
        // early stream: bins are cheap to open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    }

    // Tightness reward: prefer bins that end up mostly full.
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    score -= 50.0 * fill * fill;

    // Mean-residual coupling: if this bin is below-mean residual (tighter), favor it.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Modulo-10 harmonic class of item_size: items that are divisors of capacity pair well.
    if item_size > 0 && (bin_capacity % item_size) == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are wasted. Penalize them heavily.
    let min_item = 1u32;
    let dead_threshold = 30u32; // gaps below this are rarely reusable
    if post_residual > 0 && post_residual < dead_threshold {
        let unusability = 1.0 - (post_residual as f64) / (dead_threshold as f64);
        score += 40.0 * unusability * unusability;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Pressure from many open bins: prefer filling existing bins rather
    // than spreading out. Compare this bin's residual to the mean.
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        // Favor bins tighter than average (below-mean residual => lower score)
        score += 0.3 * diff;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot fit here; penalize leaving a gap it almost fits
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 15.0;
            }
        }
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Make the empty bin moderately
    // attractive by default but beatable by good fits.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64;
        // late in the stream, slightly prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward placements that leave zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            // Next item also fits here: chain bonus scaled by leftover slack after both.
            let two_step_left = post_residual - next_item_size;
            score -= 200.0 - 2.0 * two_step_left as f64;
            if two_step_left == 0 {
                score -= 400.0;
            }
        } else {
            // Next item will NOT fit in this bin: penalize small, stranded residuals.
            let gap = next_item_size - post_residual;
            score += 0.5 * gap as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Penalize large wasted residuals relative to capacity.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when the item is huge or fits are scarce.
    if bin_residual == bin_capacity {
        let tight = if next_item_size > 0 && next_item_size + item_size > bin_capacity { 1.0 } else { 0.0 };
        score += 250.0 - 200.0 * tight - 1.5 * item_size as f64;
    }

    // Late in the stream: consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (bin_residual - item_size) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item (sizes >= 1, typical mid sizes) can use well.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste * waste;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: mild penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Spread items across bins when many fit; prefer bins with larger residual generally.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Coupling with global state: if this bin's residual is above mean, slightly discourage
    // fragmenting an unusually full bin; encourage using emptier bins when mean is high.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // New-bin candidate handling: empty bin gets a base penalty so existing bins are preferred,
    // unless the fit is poor (large post_residual) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual as f64 > 0.45 * bin_capacity as f64 {
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
        if open_bins_count > 3 {
            score -= 2.0 * (open_bins_count as f64).ln();
        }
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins well);
    // later, allow more aggressive consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr * pr / cap * (0.5 + progress) - pr * (1.0 - progress) * 0.8;
    score += 0.35 * poly;

    // Reward tight fits (low post_residual) more strongly later in the stream
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * 12.0 * (0.4 + 0.6 * progress);

    // Penalize dead space that can't fit typical future items
    if pr < 10.0 {
        score -= 8.0 * (1.0 - pr / 10.0);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Mild preference for consolidating into bins below mean residual
    score += 0.1 * (pr - mean_residual);

    // New-bin candidate: penalize opening new bins unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Residuals divisible by 5 or 10 are more "usable" for future items
    // drawn from typical size grids -> reward them (subtract).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure, ideal
    } else {
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 5 == 0 {
            score -= 5.0;
        }
        // Small residuals are dead space; penalize tiny leftovers harshly
        // unless they exactly match a common small-item class.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }
        // Harmonic class via integer division thresholds: bucket the residual
        // into capacity fractions (0-25%, 25-50%, 50-75%, 75-100%).
        let quarter = (bin_capacity / 4) as f64;
        let frac = pr as f64 / bin_capacity as f64;
        if frac > 0.75 {
            score -= 10.0; // large residual left: bin still very usable
        } else if frac > 0.5 {
            score -= 3.0;
        } else if frac > quarter / bin_capacity as f64 * 1.0 {
            score += 2.0;
        } else {
            score += 10.0; // mostly full bin, little flexibility left
        }
        // Modulo-3 class coupling with next item size class.
        if next_item_size > 0 {
            let nc = next_item_size % 3;
            let pc = pr % 3;
            if nc == pc && pr >= next_item_size {
                score -= 8.0; // lookahead item fits a harmonic residue match
            }
            if pr >= next_item_size {
                score -= 6.0; // lookahead can also fit here: strong bonus
            } else {
                score += 4.0; // lookahead won't fit: mild penalty
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0;
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0));
        score -= crowding.min(15.0);
    }

    // Progress-based mild adaptation: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize leaving gaps that next item could not use anyway
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Mild pull toward bins with below-average residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual near zero).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward if the next item exactly matches the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chain perfect pair
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportional to wasted gap after the chain
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.5;
            if gap <= 10 {
                score -= 50.0; // tight chain
            }
        } else {
            // next item cannot fit in this bin after placement: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins whose residual is tighter than the mean (good fit relative to fleet).
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Penalize leaving large unusable fragments (dead space below minimum item size 1..10).
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Early in the stream, be more willing to spread items (penalize new-bin-like choices less);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for opening a brand-new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good, but tiny
    // unusable slivers (< smallest plausible item) are dead space.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual <= 20 {
        score += 5.0; // moderate dead space penalty on top of raw residual
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0; // keeps future options open
        } else {
            score += 6.0; // blocks the next item
        }
    }

    // Last-chance bonus: if this is the only bin that can fit, prefer it
    // strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> be picky,
    // prefer filling scattered bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 4 {
        score -= pressure * 10.0;
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the fit here would be very
    // tight (item large relative to capacity) or late in the stream.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_bonus = -20.0 * fill_ratio;
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            new_bin_bonus -= 15.0; // room for lookahead item in fresh bin
        }
        if t > 0.8 {
            new_bin_bonus += 25.0; // late stream: consolidate instead
        }
        score -= new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let coupling = prn * prn * (0.5 + 2.0 * progress) - prn * (0.3 + 1.5 * progress);
    score += 20.0 * coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - prn) * (1.0 - prn) * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += gap * gap / (bin_capacity as f64 * 2.0);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * prn;

    // Prefer bins with residuals below the mean (tighter consolidation)
    score += (mean_residual - post_residual as f64) * 0.1;

    // Slight bias toward opening new bins early, filling later
    score += (1.0 - progress) * 5.0 * (bin_residual == bin_capacity) as u32 as f64 * 0.0
        - (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by small
    // class sizes are more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward residuals in "good" harmonic classes (multiples of 10, 25, 50)
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 {
        score -= 4.0;
    }
    if pr % 50 == 0 {
        score -= 3.0;
    }

    // Penalize residuals in awkward classes: 1..9 slivers are dead space
    if pr < 10 {
        score += (10 - pr) as f64 * 1.5;
    }

    // Integer-division thresholds: residual in [next_item_size, next+9]
    // means next item fits with small waste -> reward.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack <= 9 {
                score -= 5.0;
            } else {
                // next item fits but leaves a mid residual: mild reward
                score -= 1.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Prefer tighter fits overall (small post_residual relative to capacity)
    score += (post_residual as f64 / cap) * 4.0;

    // Mild preference for keeping number of open bins low early on
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 && progress < 0.5 {
        score -= 1.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 3.0;
        } else {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps < 10 are hard to fill; gaps < 20 are risky)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Reward using a bin whose residual closely matches the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // If the next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to wasted opportunity
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Prefer bins with below-mean residual (consolidate filling)
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: only attractive when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // But if this item is the only one that fits anywhere, opening is cheap
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, opening a fresh bin is less costly than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus for zero or tiny dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0 - (post_residual as f64) * 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0; // exact chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 2.0; // tighter leftover after chain is better
        } else {
            // next item cannot fit here; penalize proportionally to how close it was
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 3.0;
        }
    }

    // Penalize dead space relative to mean residual (wasted capacity).
    score += (post_residual as f64 - mean_residual).max(0.0) * 1.5;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // Prefer compacting into existing bins as stream progresses / bins accumulate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 30.0;
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make empty bins less attractive unless current bin is unusable.
    if bin_residual == bin_capacity {
        score += 250.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful
    // (below the smallest plausible item size ~10, or below next item).
    let min_useful = if next_item_size > 0 { next_item_size.min(30) } else { 10 } as f64;
    if (post_residual as f64) < min_useful {
        score += 25.0 * (min_useful - post_residual as f64);
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.35 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize blocking the next item slightly, scaled by how close we are.
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (1.0 - (gap / (bin_capacity as f64)).min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: make empty bins moderately attractive so
    // we don't force awful fits, but not so attractive that we never reuse.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = (open_bins_count as f64).ln().max(0.0);
        // Opening new bins is cheaper early and when many bins are already open
        // relative to mean residual (fragmentation pressure).
        let frag = (mean_residual - post_residual as f64) / (bin_capacity as f64);
        score += 55.0 - 25.0 * progress - 8.0 * crowd + 30.0 * frag.max(0.0);
        // Large items prefer fresh bins (avoid splitting awkwardly).
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate fragmented space into predictable buckets).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Slight time-dependent aggression: late in the stream, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += 0.5 * poly;

    // Penalize dead space that is too small for typical items
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) / 10.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 0.4 * fit_ratio * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    // Lookahead coupling: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.3 * (post - nxt) / cap;
        } else if post > 0.0 {
            score += 0.3 * (nxt - post) / cap;
        }
    }

    // Mild preference to fill existing bins as stream progresses
    score += 0.2 * progress * (bin_residual as f64 / cap);

    // New-bin candidate: penalize slightly unless existing bins are poor fits
    if bin_residual == bin_capacity {
        score += 0.6 - 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // modular classes (multiples of 10, and > 20) are penalized less.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Perfect decade residuals are highly reusable -> reward.
        if class == 0 {
            score -= 6.0;
        } else if class <= 2 {
            score -= 1.5;
        } else if class >= 8 {
            score += 1.0; // awkward sliver, mild penalty
        }
        // Integer-division thresholds: leftover too small for smallest item class.
        if pr < 10 {
            score += 25.0; // dead space
        } else if pr < 20 {
            score += 8.0;
        } else if pr < 35 {
            score += 2.0;
        }
    } else {
        score -= 12.0; // perfect closure
    }

    // Lookahead: if the next item fits the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 9.0;
            // harmonic coupling: next item exactly matches a decade class
            if pr % 10 == 0 && next_item_size % 10 == 0 && next_item_size == pr {
                score -= 5.0;
            }
        } else {
            score += 3.0;
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 4.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced late in the stream or
        // when many bins are open (consolidation pressure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 14.0;
        new_bin_penalty *= 1.0 - 0.4 * progress;
        if open_bins_count > 4 {
            new_bin_penalty += 1.5 * ((open_bins_count - 4) as f64).min(6.0);
        }
        // If mean residual across open bins is small, opening is more justified.
        if mean_residual < item_size as f64 {
            new_bin_penalty -= 6.0;
        }
        score += new_bin_penalty;
    } else {
        // Prefer tighter existing bins: reward closeness of residual to item.
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 5.0 * tightness;
        // Slight preference for bins below mean residual (more filled bins).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1, but realistically
    // typical item sizes) can use are heavily penalized.
    if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable tiny gap: penalize as if it were nearly full dead space.
        score += (10 - post_residual) as f64 * 4.0;
    } else {
        // Usable gap: reward proportionally to how much of it is usable
        // (a residual that exactly accommodates the next item is valuable).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if next item fits exactly.
            if post_residual == next_item_size {
                score -= 18.0;
            }
        } else if next_item_size > 0 {
            // Gap too small for the lookahead item: mild dead-space penalty.
            score += 6.0;
        }
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones; when few bins are open,
    // spreading is less costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Last-chance bin: if this is the only fitting bin, opening a new bin is
    // costly, so strongly favor using this one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: bins with residual far below the mean are the
    // "crumbs" of the system; placing here when it fits well helps compact them.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15; // below-mean residual bins get slight penalty unless tight fit already rewarded
    } else {
        score += dev * 0.05;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the item is large or no good existing fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 10.0; // big items start fresh bins happily
        } else if fitting_bins_count > 1 {
            score += 15.0; // prefer existing bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits the residual left behind.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Next item fits exactly or nearly: reward tight coupling.
            let slack = pr - nxt;
            if slack == 0.0 {
                score -= 300.0;
            } else {
                score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize leaving residual that is
            // too small to be useful (dead space trap).
            score += 40.0 * (1.0 - pr / nxt);
        }
    }

    // Penalize small unusable residuals relative to mean residual.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.5 {
        score += 30.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residuals
    // of open bins are all poor (large post_residual penalty above handles it).
    if bin_residual == bin_capacity {
        score += 50.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * pr / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly as item gets larger.
    let fit_quality = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fit_quality * fit_quality;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * chain_tightness;
    } else if next_item_size > 0 {
        // Creating dead space the next item can't use: penalize proportional to waste.
        score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Penalize leaving small unusable gaps (dead space < min plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins generally; open a new bin
    // only when the item is large and fit across open bins is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_penalty = if fitting_bins_count == 0 { 0.0 } else {
            let avg_gap = mean_residual / (open_bins_count.max(1) as f64);
            (avg_gap - item_size as f64).max(0.0) / bin_capacity as f64
        };
        // Opening a new bin is attractive when item is big relative to mean residual.
        let big_item = item_size as f64 / bin_capacity as f64;
        let new_bin_bonus = 40.0 * big_item * poor_fit_penalty - 15.0 * (1.0 - progress);
        score = bin_capacity as f64 - new_bin_bonus;
        // Slight bias against accumulating many open bins early.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Mild preference for bins with above-average residual (balance load).
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual (tight fit).
    let mut score = post;

    // Non-linear tightness reward: quadratic coupling of fill ratio with stream progress.
    let fill = item / cap;
    score -= fill * fill * (1.0 + 2.0 * progress) * cap * 0.5;

    // Penalize small unusable dead space with a smooth non-linear bump.
    let dead = post / cap;
    score += dead * dead * (1.0 - dead) * cap * 0.3;

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs() / cap;
        score -= (1.0 - gap * gap) * 4.0 * (1.0 - progress);
    }

    // Last-chance bonus: only one open bin fits, favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * progress;
    }

    // Penalize spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln() * (1.0 + progress) * 2.0;

    // New-bin candidate: empty bin should lose unless residual waste is huge.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress + mean_residual * 0.1;
    }

    // Mean residual coupling: avoid bins far below average residual.
    score += (mean_residual - post).abs() * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into eighths.
    // Leftovers in the "sweet spot" classes (small, reusable by typical items) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Exact-fit bonus: zero dead space is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Classify post_residual into harmonic bins of capacity/8.
    let class = (post_residual * 8 / bin_capacity) as i32; // 0..=7
    match class {
        0 => score -= 25.0,             // tiny leftover, nearly full bin: excellent
        1 => score -= 15.0,             // ~12.5% leftover, still reusable
        2 => score -= 8.0,              // ~25% leftover
        3 => score += 0.0,              // neutral
        4 => score += 10.0,             // ~50% leftover: half-wasted bin
        5 => score += 16.0,
        6 => score += 22.0,
        _ => score += 30.0,             // mostly empty: wasteful placement
    }

    // Modulo-10 residue classes: leftovers divisible by 10 pair well with
    // common item sizes; awkward leftovers (e.g. 7, 13) are penalized.
    let m = post_residual % 10;
    if post_residual > 0 {
        if m == 0 {
            score -= 6.0;
        } else if m <= 2 {
            score += 2.0;
        }
    }

    // Lookahead coupling: does the leftover fit the next item exactly or well?
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 30.0; // perfect chained fit
        } else {
            score -= 12.0 * (1.0 - gap / cap); // tighter chain fit is better
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover at all: penalize proportionally
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // fits poorly everywhere else. Give the fresh bin a mild baseline penalty
    // so open bins with decent fits beat it, but huge leftovers in open bins
    // lose to it.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * (open_bins_count as f64);
    }

    // Tightness term: prefer bins where the item fills a large share of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Mean-residual coupling: when open bins are generally slack, discourage
    // leaving this one even slacker; when bins are tight, be less picky.
    score += 0.15 * (post - mean_residual);

    // Late in the stream, prioritize closing bins out (smaller post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps below min item size threshold)
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (item_size as f64) / (bin_residual as f64) * 8.0;
    }

    // Open-bin pressure: penalize opening new bins when many open bins exist
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 4.0 + 15.0;
    } else {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Progression: slightly stronger dead-space pressure later in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + progress * 0.2;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: big bonus; decays quadratically with mismatch.
        score -= 60.0 * (1.0 - (diff / 100.0).min(1.0)).powi(2);
        // Also reward next item fitting with small leftover after it.
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            // dead space too small for anything: mild penalty
            score += 8.0;
        }
    }

    // Tight fit reward: penalize (favor) small post residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Relative-to-mean residual: prefer bins that become tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Discourage opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current post residual would be very tight anyway.
        score += 25.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening a fresh bin is attractive if next item exactly fits capacity
            if next_item_size == bin_capacity {
                score -= 60.0;
            }
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tight * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        score += 8.0; // next item won't chain here
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins
    // are open and mean residual is still usable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = (open_bins_count as f64).ln() * 6.0;
        let usable = mean_residual / bin_capacity as f64;
        score += 40.0 + open_penalty + 20.0 * usable - 15.0 * progress;
    } else {
        // Slight preference for fuller bins among open bins.
        let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fullness;
        // Prefer bins whose residual is near mean (avoid fragmenting outliers early).
        let dev = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();
        score += 5.0 * dev;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of dead space with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress * progress;
    score += 8.0 * poly;

    // Tight fits are rewarded, more so as the stream advances.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 6.0 * (1.0 - nx / cap);
        } else {
            score += 4.0 * (nx / cap) * (0.5 + progress);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).sqrt() * (1.0 + progress) * 0.4;

    // New-bin candidate: bias toward consolidation early, allow opening late.
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable remainders (harmonic classes mod 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Harmonic class: post_residual divisible by 5 is more reusable
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: next item fits exactly or well in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 250.0;
        } else if gap < 10 {
            score -= 60.0;
        } else {
            score -= 25.0;
        }
    }
    // Next item just misses: penalize near-miss residual
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let miss = next_item_size - post_residual;
        if miss <= 5 {
            score += 40.0;
        }
    }

    // Last fitting bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless it's the only option or current bins are tight
    if bin_residual == bin_capacity {
        let prog = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64 * 0.8;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score += 180.0; // prefer the last-chance existing bin
        } else {
            score += 60.0 + 40.0 * (1.0 - prog);
        }
        if tight {
            score -= 50.0;
        }
    }

    // Mild preference for bins below mean residual (balance residuals)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: residuals too small to hold any plausible item
    // (items >= 1, but small gaps < ~10 are effectively unusable).
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual > 80 {
        // Large leftover is fine (very reusable), mild reward.
        score -= 10.0;
    } else {
        // Mid-range leftovers: mildly penalize, scaled by how far from reusable sizes.
        score += 5.0;
    }

    // Lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 20.0; // would create dead space for next item
            } else {
                score -= 15.0;
            }
        }
    }

    // Last chance: this is the only bin that fits; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins tighter than average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Prefer using existing bins over the brand-new empty bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Early stream: slightly more willing to open bins (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize wasted residual
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are very tight
    if bin_residual == bin_capacity {
        score += 120.0 + 0.3 * mean_residual;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fills: fill ratio of the bin
    score -= 4.0 * (item / residual);

    // Lookahead coupling: if the next item also fits in the leftover space,
    // this bin is doubly valuable; if it leaves a dead sliver, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 3.0 * (1.0 - nxt / cap);
        } else if post < 10.0 {
            score += 2.0; // dead space penalty
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: make it expensive by default, scaled with how many
    // bins are already open; relax late in the stream when mean residual is high.
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 8.0; // a fresh bin can host a chain of items
        }
        score -= 5.0 * t * (mean_residual / cap);
    }

    // Global pressure: when open bins are collectively empty, prefer
    // consolidating into existing bins (higher mean residual => lower score).
    score += 2.0 * (1.0 - t) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress * progress + 0.4 * (1.0 - progress));

    // Smooth penalty for tight fits (small post residual) early vs late
    score -= 3.0 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - x * x);
    }

    // Penalize bins far below mean residual (fragmentation avoidance)
    score += 0.5 * (mean_residual - pr).abs() / cap;

    // Lookahead: reward leaving space for the next item smoothly
    let n = next_item_size as f64;
    if n > 0.0 {
        let fits_next = ((x * cap - n).max(0.0)) / cap;
        score -= 1.5 * fits_next * fits_next;
    }

    // Mild pressure toward consolidation as stream progresses
    score += 0.3 * progress * (x - 0.5) * (x - 0.5);

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual as f64 == cap {
        let best_possible = if n > 0.0 { (cap - n) / cap } else { 0.0 };
        score += 4.0 + 2.0 * (1.0 - progress) - 2.0 * best_possible * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "coarse" classes (multiples of capacity/8) are more reusable.
    let cap = bin_capacity as f64;
    let octant = cap / 8.0;
    let pr = post_residual as f64;
    let class_index = (pr / octant).floor();
    let class_center = class_index * octant;
    let deviation = pr - class_center;

    // Reward near-exact octave fits (tight packing leaves class-aligned slack).
    score -= (octant - deviation) * 0.15;

    // Penalize residuals that are too small to be useful (dead space < small item).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: harmonic class of next item size (mod 10 buckets).
    if next_item_size > 0 {
        let nclass = next_item_size % 10;
        // If next item is small, leaving medium residual is fine; if next is large,
        // prefer bins with large residual.
        if next_item_size > post_residual {
            // this bin can't host the next item; mild penalty scaled by tightness
            score += (nclass as f64) * 0.3;
        } else {
            score -= (nclass as f64) * 0.2;
        }
    }

    // Progress-aware new-bin logic: late in the stream, prefer closing out
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus progress pressure.
        score = cap * (0.5 + 0.5 * progress);
        // Opening a new bin is attractive if current bins are very full on average.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Prefer bins tighter than the mean residual (best-fit flavor).
        if (pr as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += (pr as f64 - mean_residual) * 0.1;
        }
    }

    // Integer-division threshold on post_residual: quarter-capacity boundaries.
    let quarter = (post_residual * 4) / bin_capacity.max(1);
    score -= quarter as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 120.0;
    }
    // Gap large enough to plausibly hold a future item: mild reward
    else if post_residual >= 10 && post_residual <= 40 {
        score -= 12.0;
    }
    // Very large leftover waste
    else if post_residual > 60 {
        score += 10.0;
    }

    // Tight-fit bonus: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage opening new bins when existing ones fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0 + 4.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 35.0; // never open a new bin when an open bin fits
        }
    } else {
        // Reward using existing bins, more so when bins are scarce fits
        score -= 8.0;
        if fitting_bins_count == 1 {
            score -= 40.0; // last chance: strongly prefer this bin
        }
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that gap
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 30.0; // next item will perfectly consume the gap
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 20.0; // gap useless for the known next item
        }
    }

    // Mild pressure to consolidate into few bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (open_bins_count as f64 / 20.0).min(1.0);

    // Prefer bins whose residual deviates from the mean in a controlled way:
    // using a below-mean-residual bin preserves larger residuals elsewhere
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 150.0; // perfect chain
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 100.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Penalize residual far below mean residual (wasteful bin usage)
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when few/no good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (open_bins_count as f64).ln().max(1.0);
        // discourage opening new bins early / when many bins open, unless item is large
        score += 40.0 + 30.0 * progress + 10.0 * openness;
        if item_size > 50 {
            score -= 60.0; // large items may justify a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    }

    // Mild preference for tight fits generally
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful (min item ~1).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the next item needs the space.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64) / cap;
        let mut new_bin_penalty = 30.0;
        if fitting_bins_count >= 1 {
            new_bin_penalty += 20.0 * (1.0 - fit_quality);
        }
        // Lookahead: if next item is large, opening fresh bin may be good.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 + 20.0 {
            new_bin_penalty -= 25.0;
        }
        // Late in stream, avoid opening new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 30.0 * progress;
        score += new_bin_penalty;
    }

    // Lookahead coupling: reward bins whose post_residual can still host next item.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean (reduce fragmentation).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Time horizon: early stream, be picky (penalize mediocre fits); later, accept.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // Slight preference for fuller bins overall.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_fit = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with smooth non-linear polynomial shaping.
    let mut score = r * (1.0 + 0.9 * fit_ratio * (1.0 - progress));

    // Non-linear penalty for residual that is too small to ever be useful,
    // smoothly scaled by stream progress (dead space hurts more early).
    let dead = (1.0 - r / cap).powi(3);
    score += 60.0 * dead * (1.0 - progress) * (1.0 - progress);

    // Smooth interaction: reward tight fits more strongly as stream advances.
    score -= 25.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Last-chance bonus: smooth reward when few bins fit, stronger early.
    let scarcity = 1.0 / (fitting_bins_count as f64).powf(1.5);
    score -= 30.0 * scarcity * (1.0 - 0.5 * progress);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = (r - next_fit * cap).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins vs mean residual alignment.
    score += 0.05 * (open_bins_count as f64) * ((r - mean_residual).abs() / cap);

    // New-bin candidate: smooth penalty so it is only chosen when residuals are poor.
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        score += 10.0 + 20.0 * (1.0 - progress) * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that can never be reused is worse.
    // Class small residual (<=10) as fully wasted but "closed"; mid residuals are the danger zone.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals in the "awkward zone" (11..=30) heavily; tiny residuals are effectively closed bins.
    if post_residual <= 10 {
        score -= 15.0; // sealed bin, fine
    } else if post_residual <= 30 {
        score += 25.0 + (30.0 - pr) * 0.8; // awkward dead space
    } else if post_residual <= 50 {
        score += 8.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 tend to pair with common item sizes.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Integer-division thresholds: can post_residual host the lookahead item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect class match: next item exactly fills the remainder.
            if next_item_size == post_residual {
                score -= 30.0;
            } else {
                score -= 5.0;
                // penalize leaving a tiny awkward remainder after the hypothetical next placement
                let pr2 = post_residual - next_item_size;
                if pr2 > 0 && pr2 <= 10 {
                    score += 5.0;
                }
            }
        } else {
            score += 10.0; // this bin won't help the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral baseline, only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.5 + mean_residual * 0.3 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild pressure against proliferating many open bins with large mean residual.
    score += (open_bins_count as f64) * 0.3 + mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host typical items (>= next item or >= 10).
    if post_residual >= 10 {
        score -= 6.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    } else if post_residual > 0 {
        // Dead space that can't fit the minimum item size: strong penalty.
        score += 15.0;
    }

    // Open-bins pressure: prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // or when this is the last fitting bin and fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0; // slight preference for reusing open bins by default
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0; // opening a fresh bin beats creating dead space
        }
    }

    // Last-chance bin: strong incentive to use it rather than open a new one,
    // unless it creates dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual > 0 && post_residual < 10 {
            score += 25.0; // dead space here is worse than a new bin
        }
    }

    // Lookahead: if the next item fits the post-residual exactly, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward perfect chain fits (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // perfect chain: post_residual exactly fits next item
        } else if diff <= 5 {
            score -= 25.0;
        } else if diff <= 10 {
            score -= 10.0;
        } else if post_residual < next_item_size {
            // next item cannot follow here; dead space unless post_residual tiny
            score += (post_residual as f64) * 0.15 + 5.0;
        }
        // bonus if current item + next item chain well relative to capacity
        let chain = item_size as f64 + next_item_size as f64;
        if chain >= bin_capacity as f64 * 0.95 && bin_residual as f64 >= chain {
            score -= 15.0;
        }
    }

    // Penalize leaving tiny unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (low post_residual that is still usable)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad fit
    if bin_residual == bin_capacity {
        let avg_waste = if post_residual < next_item_size && next_item_size > 0 { 20.0 } else { 0.0 };
        score += 25.0 + avg_waste - mean_residual * 0.1;
        // early in stream, spreading load across bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for bins with residuals above mean (keep balanced spread)
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize large dead space when post_residual is small but unusable
    // (worse than next item size => likely wasted gap).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space that the next item cannot use.
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly enough room for the lookahead item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 1.5 * (-gap / 20.0).exp();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin for a poor-fit item.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer bins where this item fits snugly relative
        // to the average available space.
        let rel = bin_residual as f64 / mean_residual.max(1.0);
        score += 2.0 * (rel - 1.0).abs();
    }

    // Prefer filling bins that are already mostly full (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill_ratio;

    // Mild penalty for opening new bins as stream progresses, unless item is big.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 10.0 * progress - 0.05 * item_size as f64;
        // Opening a new bin is attractive when open bins are fragmented.
        score += 0.3 * open_bins_count as f64;
    }

    // Late in the stream, avoid leaving tiny residuals that can never be used.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual in [0,1]
    let x = post / cap;

    // Base: prefer small post residual (tight fit), with non-linear sharpening
    let mut score = 3.0 * x + 2.0 * x * x + 1.5 * x * x * x;

    // Smooth stream-progress coupling: later in stream, tolerate less dead space
    score *= 1.0 + 0.8 * progress * x;

    // Penalize residual that cannot host a typical future item (non-linear dead-space term)
    let unusable = (1.0 - x).max(0.0);
    score += 1.2 * unusable * unusable * (1.0 - progress);

    // Lookahead: reward if next item fits into post-residual (smooth quadratic bonus)
    if next_item_size > 0 {
        let fits = (next_item_size as f64) <= post;
        let gap = ((next_item_size as f64) - post).abs() / cap;
        if fits {
            score -= 1.5 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 1.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.5;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate (bin_residual == bin_capacity): its post residual is large;
    // only make it attractive when the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 0.5;
    }

    // Slight tie-break toward bins with residuals below the mean (fragmentation cleanup)
    score += 0.1 * ((post - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "useful"
    // residue classes (multiples of small item sizes), penalize dead space.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -14.0,           // perfectly reusable residual class
        5 => -7.0,
        2 | 4 | 6 | 8 => -3.0,
        1 | 3 | 7 | 9 => 5.0, // awkward dead space
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold on post_residual: bins whose residual falls
    // into the "dead zone" (small but nonzero) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // existing bins would create large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = (bin_capacity - item_size) as f64;
        score = dead * (1.0 + progress) - 12.0;
        // prefer opening a new bin when open bins are fragmented
        if mean_residual < 20.0 {
            score -= 8.0;
        }
    }

    // Mild preference for tighter bins overall (low residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Fragmentation guard: penalize bins far above the mean residual
    // (they are already loose; keep tight bins for big future items).
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 6.0;
    }

    // Late-stream consolidation: fewer open bins is better near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // since items are >= 1 but typically larger; penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual tightly matches the item (waste ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize bins that could still fit the lookahead item if we fill them now,
    // unless post_residual would be unusable anyway.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score += 15.0;
    }
    // Reward placing here if post_residual can host the next item (chaining).
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: only one bin fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer compacting into
    // existing bins; with few open bins, allow opening a new one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (1.0 - tightness);

    // New-bin candidate: residual == capacity. Prefer it only when the
    // item fits poorly in existing bins (low tightness) or few bins open.
    if bin_residual == bin_capacity {
        let escape_bonus = 30.0 * (1.0 - tightness) + 10.0 * (1.0 - progress);
        score -= escape_bonus;
        // Discard hoarding many open bins with large mean residual.
        score += mean_residual * 0.05;
    }

    // Mild global dead-space tax scaled by mean residual across open bins.
    score += (post_residual as f64) * (mean_residual / (bin_capacity as f64)) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual exactly matching next item,
    // penalize residuals that are small but nonzero (dead space unusable by next item).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 400.0; // chain placement: this bin will be perfectly consumed next step
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            // dead space: too small for the next item; penalize proportionally to how tight it is
            let tightness = 1.0 - (post_residual as f64 / nxt).max(0.0);
            score += 60.0 + 80.0 * tightness;
        } else if (post_residual as u32) > next_item_size {
            // mild reward for leaving room larger than the next item (still reusable)
            score -= 30.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit well.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Base penalty for not reusing; escalate when many bins could fit.
            let mut penalty = 250.0;
            if fitting_bins_count > 0 {
                penalty += 120.0 * fitting_bins_count as f64;
            }
            // If next item is large, keeping current residuals flexible matters more;
            // soften the penalty when mean residual is small (open bins nearly full).
            if mean_residual < 25.0 {
                penalty *= 0.4;
            }
            score += penalty;
        } else {
            // First bin of the stream: neutral-to-good.
            score -= 50.0;
        }
    }

    // Prefer packing into bins whose residual is already below mean (consolidate waste).
    if bin_residual < bin_capacity {
        let dev = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score -= 40.0 * dev;
    }

    // Late-stream consolidation: as the stream progresses, favor filling existing bins
    // tightly rather than spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 80.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small absolute preference for larger fills.
    score -= 0.5 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is ideal).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Scarcity pressure: fewer fitting bins -> prefer this bin more.
    if fitting_bins_count > 0 {
        score -= 3.0 / fitting_bins_count as f64;
    }

    // Prefer bins with residual below mean residual (denser bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Prefer bins that are already fairly full early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness * (1.0 - progress);

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But allow a new bin if the item is large and nothing fits well.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Small nudge toward balanced residual usage across bins.
    score -= 0.05 * (post_residual as f64 - mean_residual).abs().recip().min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: quadratic polynomial in normalized post_residual, modulated by progress
    let mut score = prn * (1.0 + 0.35 * progress) - 0.22 * prn * prn;

    // Smooth cubic interaction between post_residual and stream progress
    score += 0.15 * prn * prn * prn * (0.5 + progress);

    // Lookahead: reward residual that accommodates the next item (smoothly)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = if pr >= ns { 1.0 - (pr - ns) / cap } else { 0.0 };
        score -= 0.30 * fit_next * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 0.60 * (1.0 + 0.5 * progress);
    }

    // Penalize bins whose residual deviates badly from mean (fragmentation pressure)
    score += 0.08 * ((pr - mean_residual) / cap).abs();

    // Mild penalty for opening a new bin late in the stream when alternatives exist
    if bin_residual == bin_capacity {
        score += 0.25 + 0.20 * progress;
    } else {
        score -= 0.05; // slight preference for reusing open bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Post-residuals divisible by 5/10 are "harmonic" and easier to fill later.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else {
            // Non-harmonic dead space: penalize small awkward leftovers.
            if pr < 10 {
                score += (10 - pr) as f64 * 2.5;
            }
        }
    } else {
        // Perfect fit: strongly favored.
        score -= 60.0;
    }

    // Integer-division thresholds: can next item fit into post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits: reward proportional to tightness of that fit.
            let tight = (pr - next_item_size) as f64;
            score -= 10.0 + 20.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // Lookahead would not fit here: penalize more if this bin becomes stranded.
            score += 6.0;
        }
        // Harmonic coupling: next item and post residual share a common divisor class.
        if pr % 10 == next_item_size % 10 && pr >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Empty new-bin candidate: only attractive when existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty keeps new bins from being opened frivolously.
        score += 30.0
            - 20.0 * fragmentation
            - 10.0 * progress;
        // If item is large relative to capacity, a fresh bin is more forgiving.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is far below the mean (tighter, more filled bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate: reward bins that are already partially filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_raw = bin_capacity as f64;
    let cap = if cap_raw > 0.0 { cap_raw } else { 1.0 };
    let before = bin_residual as f64;
    let r = post_residual as f64;
    let s = item_size as f64;
    let open = open_bins_count as f64;
    let fits = fitting_bins_count as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let mean_res = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        0.5 * cap
    };

    let is_new = bin_residual == bin_capacity;
    let next = if next_item_size == 0 {
        0.0
    } else {
        (next_item_size as f64).min(cap)
    };

    let next_scarcity = if next > 0.0 {
        (((next - mean_res) / cap).max(0.0)).min(1.0)
    } else {
        0.0
    };

    let size_hint = if next > 0.0 {
        s.min(next).max(1.0)
    } else {
        s.max(1.0)
    };

    let dead_floor = ((0.10 * cap).min(size_hint)).max(1.0);

    let mut score = r;

    if item_size > bin_residual {
        score += 1.0e9;
    }

    if r > 0.0 && r < dead_floor {
        let gap = dead_floor - r;
        let dead_penalty = 6.0 + (gap * gap) / dead_floor + 0.55 * gap;
        score += dead_penalty * (1.0 + 0.35 * progress + 0.025 * open.min(24.0));
    }

    if r <= 0.0 {
        score -= 9.0 + 0.10 * s;
        if next > 0.0 {
            score += 0.10 * next;
        }
    } else if next > 0.0 {
        if r >= next {
            score -= 8.0 + 0.22 * next + 10.0 * next_scarcity + 0.05 * open.min(20.0);
        } else {
            let mismatch_factor = 0.40 + 0.50 * next_scarcity;
            score += 4.0 + mismatch_factor * (next - r);
        }
    }

    if !is_new {
        score -= 0.03 * (mean_res - before).max(0.0);

        if fits <= 1.0 {
            let avoid_new = 5.0 + 0.35 * open.min(25.0) + 4.0 * (1.0 - progress);
            let weak_last_chance = next > 0.0 && r > 0.0 && r < next && next_scarcity > 0.25;
            let last_chance_factor = if weak_last_chance {
                0.25 + 0.35 * progress
            } else {
                1.0
            };
            score -= avoid_new * last_chance_factor;
        }
    } else {
        let mut new_cost = 35.0
            + 0.90 * open
            + 10.0 * fits
            + 0.05 * mean_res
            + 12.0 * progress;

        if next > 0.0 && r >= next {
            let pair_bonus = (35.0 + 0.80 * next)
                * (0.55 + 0.45 * next_scarcity)
                * (1.0 - 0.30 * progress);
            new_cost -= pair_bonus;
        } else if next > 0.0 && r < next {
            new_cost += 0.05 * (next - r) * (0.5 + 0.5 * next_scarcity);
        }

        score += new_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: the less wasted space, the better (super-linear penalty).
    score += (post_residual as f64) * (post_residual as f64) / cap;

    // 2-step lookahead: strongly reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item can follow into this bin: reward proportional to match quality.
            score -= 40.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit: penalize dead space left behind.
            score += 15.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Prefer bins whose residual deviates from the mean (keep a spread of sizes).
    score -= ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    // relative to capacity or there are no real alternatives.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let pressure = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let penalty = 30.0 + 40.0 * frac - 20.0 * pressure;
        score += if fitting_bins_count == 0 { -50.0 } else { penalty };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // the minimum plausible item size is wasted.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 30.0;

    // Penalize leaving residuals that no typical item can use efficiently
    // (very small residuals are dead space unless nearly zero).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // creates stranded space relative to lookahead
        }
        // Perfect chain: this + next item exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 12.0;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer bins already below mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Time horizon: late in the stream, discourage opening new bins
    // (fewer chances to fill them), encourage using existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive early or when open bins are crowded.
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 5.0 + progress * 20.0 - crowding * 2.0;
        if item_size >= 70 {
            score -= 6.0; // huge items fit fine in a fresh bin
        }
    } else {
        score -= progress * 4.0;
    }

    // Mild penalty on too many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post residual (tight fit), non-linearly scaled.
    let mut score = post * (1.0 + 0.5 * post_norm * post_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (favor filling many bins); later, penalize dead space harder.
    let coupling = 1.0 + 2.0 * progress * progress;
    score += 30.0 * post_norm * post_norm * coupling;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_quality = 1.0 - post_norm;
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening new bins when the stream is late and open bins are underused.
    let mean_norm = mean_residual / cap;
    score += 10.0 * mean_norm * progress;

    // Lookahead: reward leaving space compatible with the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs() / cap;
        score += 8.0 * gap * gap;
    } else {
        // Last item: pure tightness.
        score += post_norm * 5.0;
    }

    // Mild pressure against bin proliferation mid-stream.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward tight fits (small post_residual), with a harmonic-style bonus
    // when post_residual lands in "useful" residue classes (multiples of
    // small item granularity), penalizing dead space in awkward classes.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: gold
    } else {
        // modulo classes: residues divisible by 10/20 are easier to fill later
        let r10 = post_residual % 10;
        let r20 = post_residual % 20;
        if r10 == 0 {
            score -= 8.0 + 0.5 * (post / 10.0);
        }
        if r20 == 0 {
            score -= 5.0;
        }
        // awkward residues (e.g. 1..=9 remainder) create dead space
        if r10 != 0 && post_residual < 10 {
            score += 15.0;
        }
        // integer-division thresholds: big leftover chunks are reusable
        let bucket = post_residual / 20; // 0..=5
        score -= bucket as f64 * 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= 10.0 - (nxt_post as f64) * 0.15;
        } else {
            // next item cannot follow here: penalize small leftovers
            if post_residual < 10 {
                score += 12.0;
            }
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins below mean residual (denser bins first), mild pressure
    score += 0.2 * (mean_residual - post).max(0.0) - 0.1 * (post - mean_residual).max(0.0);

    // New-bin candidate handling: only attractive when current bin would leave
    // a terrible tiny remainder and the item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit {
            score -= 20.0; // fresh bin beats creating dead space
        } else {
            score += 30.0 + 0.3 * (open_bins_count as f64); // keep using open bins
        }
    }

    // Late in stream: consolidate harder, avoid sprawl
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap smaller than the smallest conceivable item (1)
    // scaled by stream progress: later in the stream, gaps matter more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = 10.0_f64.max(2.0 + 8.0 * progress);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * (6.0 + 14.0 * progress);
    }
    // Zero post_residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (best-fit flavor).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio * fill_ratio;
    }

    // Penalize leaving a gap that exactly invites a wasteful tiny future item:
    // if post_residual is nonzero but smaller than next_item_size, it is dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.5 * post_residual as f64;
    }
    // Reward leaving a gap that next item can exactly fill.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // encourage using existing bins rather than opening new ones.
    score += 0.6 * open_bins_count as f64;
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Last-chance bin: strongly prefer using it over opening a new bin.
        score -= 30.0;
    }
    // If several bins fit, mildly prefer this one when its residual is below mean
    // (consolidating into fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // or the fit elsewhere would be terrible. Penalize the fresh bin by
        // default, scaled by how many bins could fit the item.
        let crowding = mean_residual / bin_capacity as f64;
        let mut new_bin_score = 15.0 + 8.0 * fitting_bins_count as f64 + 20.0 * (1.0 - crowding);
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        new_bin_score -= 0.1 * item_size as f64;
        // Late in the stream, avoid opening bins unnecessarily.
        new_bin_score += 10.0 * progress;
        // If this is the only fitting option, allow the new bin more readily.
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Reward exact/near-exact fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs
            let combo = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * combo;
        } else {
            // next item won't fit in this bin's leftover: penalize large dead space
            let dead = post_residual as f64;
            score += 0.1 * dead;
        }
    }

    // Relative to mean residual: prefer bins that are below-average residual
    // (tighter bins) when they can still fit the item
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // new-bin candidate: only attractive if item is large and lookahead is large
        let lookahead_bonus = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        score += 20.0 - 0.1 * item_size as f64 - 0.05 * lookahead_bonus;
    }

    // Mild late-stream pressure: consolidate more aggressively as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_ratio;

    // Penalize creating residuals that are awkward (e.g., 1..9 dead zone)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving small, hard-to-use dead space (post_residual in [1, 10]).
    if post_residual > 0 && post_residual <= 10 {
        score += 12.0;
    }
    // Reward leaving residual large enough to be reusable later.
    if post_residual >= 20 {
        score -= 6.0;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            // Placement leaves residual too small for the next item: mild penalty.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: discourage opening a new bin when the item
    // fits reasonably well in an existing bin (fill_ratio already rewards this),
    // but allow opening a new bin for large items that would leave bad leftovers.
    if bin_residual == bin_capacity {
        // Empty-bin baseline: neutral-ish score, penalized if item is small
        // (wasteful to dedicate a fresh bin to a small item).
        score += 15.0 + 0.3 * item_size as f64;
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is mandatory.
            score -= 100.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively to avoid
    // opening bins that will see little further use.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer packing
    // into existing bins to reduce fragmentation.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    // beyond the raw post_residual ordering.
    score -= 4.0 * (1.0 - (bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, with non-linear polynomial coupling
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth progress coupling: tighter packing valued more later in stream
    score *= 1.0 + 0.6 * progress * progress;

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = post - nx;
        if slack >= 0.0 {
            // next item fits: bonus proportional to leftover tightness
            score -= 8.0 * (1.0 - slack / cap) * (1.0 + progress);
        } else {
            // next item does not fit: penalize proportionally to wasted potential
            score += 0.02 * (-slack) * (0.5 + progress);
