    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty for scattering across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - post).abs() / cap;

    // New-bin candidate: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: opening a bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes are more reusable than awkward ones.
    let pr = post_residual;
    if pr > 0 {
        let mut usable = 0u32;
        for k in 1..=10u32 {
            let cls = k * 10;
            if pr % cls == 0 {
                usable += 1;
            }
        }
        score -= 6.0 * usable as f64;

        // Dead-space penalty: residual too small for the smallest plausible item
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 12.0;
        }

        // Integer-division thresholds: quantize residual quality
        let q = pr / 10;
        score -= (q as f64).powi(2) * 0.4;
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
        // exact chain fit is excellent
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to overshoot
        let over = next_item_size - post_residual;
        score += 0.15 * over as f64;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin; relax late in the stream or when
        // existing residuals are large and fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 55.0;
        penalty -= 20.0 * progress;
        penalty -= 0.3 * (mean_residual - (bin_capacity as f64 - item_size as f64)).max(0.0);
        if fitting_bins_count == 0 {
            penalty -= 100.0; // nothing fits: must open
        }
        score += penalty;
    } else {
        // mild preference for tighter existing bins
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Congestion: with many open bins, consolidate rather than spread
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 10] are nearly unusable
    // (min item size is small but still wasteful) -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0;
    }
    // Perfect fit: zero dead space, strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 25 {
        // Small residual is only acceptable if the lookahead item can use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        } else {
            score += 15.0;
        }
    }

    // Reward filling bins deeply (large item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when
    // the stream is still long; encourage consolidation early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.0 - progress) * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a poor candidate (fragmented bin); penalize deviation.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    // New-bin candidate handling: an empty bin gets a mild penalty so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large and fits only barely in open bins,
        // a fresh bin may be better: reduce penalty for big items.
        if item_size >= 70 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 1.0 {
            score -= 500.0;
        } else {
            score += diff * 0.5;
        }
        // Penalize leaving residual that is too small for any plausible item (dead space)
        if post_residual > 0 && (post_residual as f64) < nxt {
            score += 30.0;
        }
    } else {
        // Last item: prefer minimal residual
        score += post_residual as f64 * 0.1;
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with residual close to item size (good fill) relative to average
    let res = post_residual as f64;
    let mean_gap = res - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 1 {
        score += 150.0;
    }
    // New bin is attractive only if it enables a clean two-item pairing
    if bin_residual == bin_capacity && next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
        score -= 50.0;
    }

    // Mild stream-position regularization
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste quadratically relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            // Next item can't use leftover space; penalize large leftovers slightly.
            score += 0.15 * post_residual as f64;
        } else {
            let next_waste = post_residual - next_item_size;
            score += 0.2 * next_waste as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Time horizon: early in the stream, be more conservative (prefer filling bins well);
    // late in the stream, closing out bins matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * waste_frac;

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins
    // over opening new ones; penalize candidates that leave big residual when mean residual is low.
    if bin_residual == bin_capacity {
        // New-bin candidate: open a new bin only if existing fits are poor or none exist.
        let poor_fit_threshold = 0.35 * bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        } else if (mean_residual - item_size as f64) > poor_fit_threshold && open_bins_count > 0 {
            // existing bins would waste a lot; new bin attractive
            score -= 30.0;
        } else {
            score += 60.0 + 0.5 * open_bins_count as f64;
        }
    } else {
        // Reusing an existing bin is generally good when open bins are numerous.
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty when this bin's residual is far above mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.9 * progress * norm_pr + 0.6 * (1.0 - progress) * norm_pr * norm_pr);

    // Penalize dead space that is too small to be useful later (smooth quadratic).
    let dead = 1.0 - norm_pr;
    score += 8.0 * progress * dead * dead * cap;

    // Reward tight fits: post_residual near zero.
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: bonus if next item fits the resulting residual (smooth margin term).
    if next_item_size > 0 {
        let margin = pr - next_item_size as f64;
        if margin >= 0.0 {
            score -= 6.0 * (margin / cap) * (1.0 - progress);
        } else {
            score += 3.0 * (-margin / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Prefer bins whose residual deviates smoothly from the mean (balance).
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and 25 capture
    // "companion-friendly" gaps for typical item sizes.
    let pr = post_residual;
    let residue10 = (pr % 10) as f64;
    let residue25 = (pr % 25) as f64;
    let harm25 = if residue25 == 0.0 { -6.0 } else if residue25 <= 10.0 { -2.0 } else { 2.0 };
    score += harm25;
    score -= (10.0 - residue10.min(10.0)) * 0.15;

    // Zero residual is perfect.
    if pr == 0 { score -= 25.0; }

    // Dead space penalty: small unusable leftover that no plausible item fills.
    if pr > 0 && pr < 10 { score += 18.0; }

    // Lookahead coupling: does post_residual exactly fit next item?
    if next_item_size > 0 {
        if next_item_size == pr { score -= 20.0; }
        else if next_item_size <= pr {
            let r2 = (pr - next_item_size) % 10;
            score -= 4.0 - (r2 as f64) * 0.3;
        } else {
            score += 3.0; // next item cannot follow here
        }
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only prefer it when all open bins are poor fits.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.6;
        if tight { score -= 8.0; } else { score += 10.0; }
    }

    // Slight preference for fuller bins relative to mean residual.
    score -= ((bin_residual as f64) - mean_residual) * 0.05;

    // Late-stream tightening: waste less as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer bins whose residual before placement was small (best-fit flavor).
    score += 0.35 * (bin_residual as f64 - item_size as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-attractive only
    // when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score -= 10.0;
        if post_residual < 10 && post_residual > 0 {
            score += 55.0; // don't open a fresh bin to create a tiny gap
        }
        if post_residual as f64 <= mean_residual {
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage proliferating bins.
    score += (open_bins_count as f64) * 0.6;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Mean-residual coupling: prefer bins with residual below the mean (tighter bins).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 400.0;
    }

    // 2-step lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 700.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasted space relative to mean residual.
            score += 60.0 + (post_residual as f64 - mean_residual).abs();
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize creating tiny unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Mild penalty when many bins are open: discourage bin proliferation.
    score += open_bins_count as f64 * 0.5;

    // Slight late-stream tightening: favor compact packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // New-bin candidate: make empty bin costly unless it promises a good future fit.
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: strongly reward small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize leaving a gap just below the next item size (awkward gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).ln1p();

    // Prefer bins below mean residual (more crowded bins absorb items well).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or existing bins are all poor fits.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let size_relief = 0.35 * item_size as f64;
        let crowding = 2.0 * open_bins_count as f64;
        score += base_penalty - size_relief - crowding;
        // If next item is large and would not fit after this placement, opening
        // a fresh bin is more attractive.
        if next_item_size > post_residual {
            score -= 8.0;
        }
        // Early stream: opening bins is cheap; late stream: consolidate.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, tighter fits matter more.
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= progress_coupling * 8.0 * (1.0 - norm_pr);

    // Penalize leaving residual close to but below the smallest plausible item (dead space),
    // smoothly via a bump function around small residuals.
    let small_zone = (1.0 - norm_pr).min(1.0);
    score += 6.0 * small_zone * small_zone * (1.0 - small_zone) * (1.0 - small_zone);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item can fit into post-residual.
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as i32 as f64;
        let tightness = 1.0 - ((post_residual as i64 - next_item_size as i64).unsigned_abs() as f64 / cap);
        score -= next_fits * 6.0 * tightness;
        // Penalize if next item nearly fits but not quite (smoothly).
        let miss = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 4.0 * miss * (1.0 - miss);
    }

    // Mild preference for filling bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make it unattractive unless residual is large relative to item need.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - item_size as f64 / cap) + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by large item classes are "harmonic" (reusable); others are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class 1: residual in {0} perfect; {10,20,...} multiples of 10 moderately good.
    if pr == 0 {
        score -= 1000.0;
    } else if pr % 10 == 0 {
        score -= 15.0;
    } else if pr % 5 == 0 {
        score -= 5.0;
    }

    // Integer-division thresholds: small residuals (< 10) are dead space -> penalize.
    if pr < 10 && pr > 0 {
        score += 40.0;
    }

    // Harmonic coupling with next item: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 25.0;
        } else if pr >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here: residual likely dead -> penalty scaled by deadness
            score += 8.0 + (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with harmonic tilt).
    score += 0.3 * (prf - mean_residual).max(-cap).min(cap);

    // Late in the stream, consolidate: favor existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, reduced early when few bins open
        score += 20.0 + 30.0 * progress - (open_bins_count as f64).min(10.0);
    }

    // Fraction-of-capacity harmonic bonus: residual near capacity fractions (25/50/75) is reusable.
    let frac = prf / cap;
    for h in [0.25f64, 0.5, 0.75] {
        let d = (frac - h).abs();
        if d < 0.05 {
            score -= 12.0 * (1.0 - d / 0.05);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += 60.0 * (1.0 - pr / 10.0); // tiny gap = wasted space
        } else if post_residual < 20 {
            score += 20.0 * (1.0 - pr / 20.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Prefer bins whose residual tightly matches the item (low slack ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bins pressure: with many open bins, avoid spreading; favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // blocks next item -> dead space
    }

    // Mean residual coupling: placing into a bin far above mean residual is wasteful.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only allow opening a new bin when item is large relative
    // to typical residuals or no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0
            + (mean_residual / bin_capacity as f64) * 30.0;
        score += 45.0 - pressure.min(60.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize extreme waste.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.05;
    } else {
        // Perfect fill is heavily rewarded.
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits too: good chaining, reward proportional to leftover slack.
            score -= 10.0;
            score += (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item won't fit here: dead space risk grows with gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.10;
        }
    }

    // Relative-to-mean coupling: bins with residual well below mean are "tight"
    // and should be filled first to avoid stranding them.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the fit
    // in every open bin is poor. Penalize the fresh bin mildly so it loses to any
    // reasonable fit, but let it win over huge dead-space placements.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, prefer closing out open bins rather than spawning.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Many open bins: encourage consolidation to reduce spread.
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward small dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly or well into the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 18.0 * next_fit;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for "stranding" residual.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only allow opening a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 55.0 + 30.0 * (1.0 - progress);
        // If many open bins with large residuals, discourage new bins.
        new_bin_penalty += 0.15 * mean_residual;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        new_bin_penalty -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If no open bin fits (fitting_bins_count == 0 besides new bin), drop penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty -= 100.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for consolidating into bins with above-average residual
    // (keeps tight bins tight, uses roomy bins).
    let resid_diff = bin_residual as f64 - mean_residual;
    score += 0.05 * resid_diff;

    // Slight penalty for very small post residuals that waste capacity on near-full bins
    // unless it was a tight fit (already rewarded).
    if post_residual > 0 && post_residual <= 5 {
        score -= 10.0; // near-perfect fill
    }

    // Small noise-free tie-breaker based on step progression: earlier, prefer packing
    // existing bins; later, allow slightly more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let shape = 1.0 + progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += shape * (pr_norm * pr_norm) * 30.0;

    // Reward tight fits increasingly over time
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (10.0 + 40.0 * progress);

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (nxt - post).max(0.0) / cap;
        score += unusable * unusable * 25.0 * (0.5 + progress);
        // Reward leaving space exactly usable by next item
        let fit_gap = (post - nxt).abs() / cap;
        score -= (1.0 - fit_gap).max(0.0) * 8.0;
    }

    // Mean-residual deviation penalty (smooth quadratic)
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (cap * cap) * 100.0;

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Mild penalty for proliferating open bins late in stream
    score += (open_bins_count as f64).ln() * (2.0 + 4.0 * progress);

    // Discard tiny unusable residuals smoothly
    score += (1.0 - (pr_norm * 10.0).tanh()) * 5.0 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartiles
    let q = bin_capacity / 4; // 25
    let class = post_residual / q; // 0..4
    let phase = post_residual % q;

    // Reward tight fits: small post_residual gets a strong discount
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    } else if class == 0 {
        score -= 8.0 - phase as f64 * 0.2;
    } else if class == 1 {
        score -= 2.0;
    } else if class == 2 {
        score += 4.0;
    } else {
        score += 8.0;
    }

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0; // next item fills nearly perfectly
        }
        // harmonic coupling: next item's class vs remaining phase
        let next_phase = next_item_size % q;
        if next_phase <= phase {
            score -= 3.0;
        }
    } else {
        // last item: any residual is pure waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless no good fit exists
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -60.0 // nothing fits elsewhere: open new bin
        } else if fitting_bins_count == 1 {
            5.0
        } else {
            25.0 + open_bins_count as f64 * 2.0
        };
        score += penalty;
        // early stream: favor opening bins to build diversity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins below mean residual (balance load)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for fuller bins overall
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    }
    // Medium dead space (11..=25) is also risky since min item is small but unknown.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits (near-zero post residual is ideal).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Perfect fill of the bin (item exactly matches residual) — strongest reward.
    if post_residual == 0 && item_size == bin_residual {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless it creates severe dead space.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates from the mean in a usable way:
    // a bin with larger-than-mean residual is a better host for the current item.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item could fit into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover gap — mild penalty for creating stranded space.
        score += 5.0;
    }

    // New-bin candidate handling: only attractive when current item is large or
    // no open bin offers a decent fit. Penalize default empty-bin score otherwise.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        if large_item && fitting_bins_count == 0 {
            score -= 25.0; // opening a fresh bin for a big item is good
        } else if fitting_bins_count == 0 {
            score -= 5.0; // no alternative: new bin acceptable
        } else {
            score += 18.0; // discourage abandoning open bins that fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward bins whose post-residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // tight chain fit: strongly reward
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            // exact chain fit bonus
            if post_residual == next_item_size {
                score -= 60.0;
            }
        } else {
            // next item cannot chain here; penalize proportional dead space
            score += 0.5 * post_residual as f64;
        }
        // coupling with mean residual: prefer bins deviating purposefully
        score -= 0.3 * (post_residual as f64 - mean_residual);
    }

    // Penalize creating unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are too full
    if bin_residual == bin_capacity {
        let avg_fill = mean_residual;
        score += 55.0 + 0.4 * avg_fill;
        // early stream: keep new-bin penalty high to consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // if next item fits perfectly in an empty bin, ease penalty
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: post_residual that is too small to hold the smallest item (1..100, min 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot follow here: slight penalty proportional to overshoot
            score += 3.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (penalize existing-bin use less? no —
    // early on, spreading items keeps flexibility; late in stream, consolidate tightly).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // Global state: many open bins with low mean residual -> prefer filling existing bins harder.
    if open_bins_count > 2 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 5.0 * pressure; // high mean residual => bins are empty-ish, less urgency
    }

    // New-bin candidate handling: an empty bin has zero fit quality; make it attractive only when
    // existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // neutral base: competitive with bins that would leave >30% waste
        score = 0.35 * bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
        // late in stream, prefer consolidating into open bins
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = (pr / cap).clamp(0.0, 1.0);

    // Base: post residual, mildly non-linear (waste grows superlinearly at small residuals)
    let mut score = pr * (1.0 + 0.35 * (1.0 - fit) * (1.0 - fit));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early: prefer tight fits less aggressively; late: penalize residual more
    let prog_poly = 1.0 + 0.6 * progress * progress + 0.4 * progress * (1.0 - progress);
    score *= prog_poly;

    // Interaction: residual relative to mean residual across open bins
    let rel_mean = (pr - mean_residual) / cap;
    score += 12.0 * rel_mean * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = if pr >= n { 1.0 } else { 0.0 };
        let gap = ((pr - n).abs()) / cap;
        score += fits_next * 8.0 * gap * gap - (1.0 - fits_next) * 6.0 * (1.0 - progress);
    }

    // Penalize opening new bins when many bins already open, scaled by progress
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward tight fits: post_residual in low harmonic classes.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    }

    // Penalize dead-space classes: residual too small for the smallest plausible item (1..100 unknown, use small guard)
    if post_residual > 0 && post_residual < 5 {
        score += 30.0; // nearly unusable sliver
    }

    // Modulo arithmetic on post_residual: "harmonic" bins whose leftover is a divisor-friendly
    // quantity (divisible by common item sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [5u32, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 8.0;
            }
        }
        score -= harmony;
    }

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - waste / cap);
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 5.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins only
    // when all open bins would create bad fits.
    if bin_residual == bin_capacity {
        score = 35.0 + frac * 10.0;
        // If no open bin fits at all, opening new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in stream, prefer fresh bins slightly more (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    } else {
        // Prefer bins with lower residual relative to mean (fill fuller bins first).
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Mild pressure to keep open bin count low.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny gap: worst kind of dead space
        } else if post_residual < 20 {
            score += 22.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            score -= 6.0; // large residual keeps bin usable
        }
    } else {
        score -= 25.0; // perfect fit: strongly reward closing a bin exactly
    }

    // Lookahead coupling: penalize leaving a gap that cannot host the next item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // gap too small for the next item
        } else if post_residual >= next_item_size {
            score -= 10.0; // gap can absorb the next item
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another bin.
    if bin_residual == bin_capacity {
        score += 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual = tighter fill).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Stream progression: late in the stream, tighten up and close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Two-step lookahead: strongly reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: subtract a bonus proportional to how snugly the next item fits
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 + 0.5 * (bin_capacity as f64 - chain_waste);
        } else {
            // Next item won't fit here: penalize proportionally to leftover dead space
            score += 10.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize leaving residuals far below mean (fragmenting the bin landscape)
    let dev = post_residual as f64 - mean_residual;
    score += 0.1 * dev;

    // Slight preference for filling older bins early in the stream (keep bin count low)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward when next item exactly leaves another tight fit.
            let nr = post_residual - next_item_size;
            if nr <= 10 {
                score -= 6.0;
            }
        } else if next_item_size > post_residual {
            // Penalize leaving a residual that just barely fails the next item.
            score += 5.0;
        }
    }

    // Prefer filling already-open bins when many bins are open (avoid bin proliferation).
    let open_f = open_bins_count as f64;
    if bin_residual < bin_capacity {
        score -= 4.0 + open_f * 0.6;
    } else {
        // New-bin candidate: penalize opening a new bin unless the item is large
        // and few bins are open.
        score += 10.0 + open_f * 1.5;
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Global state: if mean residual is high, prefer bins below the mean
    // (drive toward uniform packing); if low, prefer larger residuals.
    let diff = (bin_residual as f64) - mean_residual;
    if mean_residual > 0.0 {
        if diff < 0.0 {
            score += 0.15 * diff; // negative addition = reward below-mean bins
        } else {
            score += 0.10 * diff;
        }
    }

    // Time horizon: late in the stream, be more conservative (favor tight fits,
    // discourage new bins even more since fewer items remain to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 1.0 - progress;
    score *= 0.7 + 0.3 * horizon;
    if bin_residual == bin_capacity {
        score += 15.0 * progress; // opening new bins gets costlier late in the stream
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear coupling: residual value decays with stream progress
    let decay = 1.0 - 0.5 * progress * progress;
    score *= decay;

    // Tightness reward: strongly favor small post_residual (quadratic dead-space penalty)
    let tightness = 1.0 - (post / cap);
    score -= 20.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins with residual far above mean (fragmented fleet)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: bonus if next item fits exactly into the post_residual
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack * slack);
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual as f64 == cap {
        score += 8.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual buckets via integer division on capacity/8.
    let class = post_residual / (bin_capacity / 8);
    score += match class {
        0 => -60.0,          // tiny leftover (1..12): excellent
        1 => -30.0,          // small leftover
        2 => 10.0,           // mid: risky dead space
        3 => 35.0,
        4 => 55.0,
        5 => 70.0,
        6 => 85.0,
        _ => 95.0,           // large leftover: bin barely used
    };

    // Modulo-10 arithmetic: leftover that is a multiple of 10 is more reusable
    // for the common item-size granularity.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves a poor remainder
            let nr = post_residual - next_item_size;
            if nr <= (bin_capacity as f64 * 0.05) as u32 {
                score -= 120.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item will not fit here: penalize leftovers too small for it
            if post_residual < next_item_size {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin should only win when the current
    // item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // baseline penalty so full bins usually win
        score += 40.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early stream: opening bins is cheap; late stream: consolidate
        score -= 30.0 * (1.0 - progress);
        // large items tolerate fresh bins
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // many open bins already: discourage spreading
        score += 3.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin's residual deviates from the mean,
    // prefer bins close to (or below) the mean to keep balance.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Waste-per-placement style term: penalize leaving space that no typical
    // item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10, the minimum item size) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Slightly-larger-but-still-awkward gaps are partially wasted too.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placing item so that the next item can still fit in the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if next item almost fits but not quite (near-dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer existing bins when bin count is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below mean (filling emptier-of-space bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for tight fits overall.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // New-bin candidate: make it attractive only when item is large (little waste)
    // and existing bins are crowded; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0;
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        score += open_bins_count as f64 * -0.3;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0; // new bin would create awkward gap for next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - match_quality / bin_capacity as f64);
    }
    // Penalize post_residuals that are too small for the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare residual against mean residual across open bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating tiny unusable slivers (< 10, minimum item size)
    if post_residual < 10 {
        score += 8.0;
    }

    // Late in the stream, consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - mean_residual / bin_capacity as f64) * 2.0;

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 20.0 };
        score += 10.0 + poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual < item_size {
        // residual smaller than smallest possible next item => dead space
        score += 20.0;
    }

    // Penalize opening a new bin when existing bins can fit, scaled by how many alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // early stream: cheap to open bins; late stream: prefer filling existing bins
        score += 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            score += 60.0; // last-chance bin: strongly prefer using it over new bin
        }
    } else if fitting_bins_count == 1 {
        // this is the only bin that fits: strong reward
        score -= 120.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize large leftover.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (post_residual as f64) * 0.3;
        }
    }

    // Prefer bins with residual close to item (best-fit style) via mean-residual context.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.5;

    // Mild preference for consolidating into bins below mean residual (balance load).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight penalty per open bin to discourage bin proliferation.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, favor tight fits (low post_residual); later, tolerate slack
    // and reward keeping flexibility for future items.
    let flex_weight = 0.5 + 2.0 * progress * progress;
    score -= flex_weight * (norm_pr * (1.0 - norm_pr)) * cap;

    // Penalize large dead space quadratically, modulated by progress.
    score += (1.0 + 2.0 * progress) * norm_pr * norm_pr * cap * 0.5;

    // Reward bins whose residual matches the next item's need (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-diff / 20.0) * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Penalize when this bin is far from the mean residual (imbalance).
    score += 0.3 * (pr - mean_residual).abs();

    // Mild penalty for spreading across many bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Prefer fuller bins: subtract fill fraction.
    score -= (bin_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters: reward residuals
    // that fall into "usable" classes for typical small items.
    let quarter = bin_capacity / 4; // 25
    let class = post_residual % quarter;
    let class_bonus = match post_residual / quarter {
        0 => 12.0,          // tiny residual: near-dead space, penalize
        1 => -6.0,          // 25..49: fits mid-size items, good
        2 => -10.0,         // 50..74: sweet spot
        _ => -4.0,          // 75..99: fine
    };
    score += class_bonus + (class as f64) * 0.15;

    // Exact-fit harmony: post_residual divisible by common item sizes is valuable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        else if post_residual % 5 == 0 { score -= 2.0; }
    } else {
        score -= 15.0; // perfect closure
    }

    // Lookahead harmonic coupling: does post_residual's class admit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here later: reward alignment of integer division
            let gap = post_residual - next_item_size;
            score -= 5.0;
            score += (gap % 10) as f64 * 0.2;
        } else {
            score += 6.0; // next item won't fit: this bin becomes dead after placement
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    // or the fit here is poor (harmonic class 0 dead space).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 3.0 + mean_residual * 0.1;
        score = 40.0 + pressure - (post_residual as f64) * 0.1;
        if fitting_bins_count == 0 { score -= 30.0; }
        if next_item_size > 0 && next_item_size >= bin_residual { score -= 10.0; }
    }

    // Mild stream-phase adaptation: later in stream, prefer tightening bins.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is worthless
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual < 35 {
            score += 12.0;
        }
    } else {
        score -= 25.0; // perfect fill is excellent
    }

    // If the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_eff = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * gap_eff;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // post residual cannot host next item: penalize more the smaller it is
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64;
        if post_residual < item_size && item_size > 0 {
            // empty bin always has post_residual = capacity - item, fine.
        }
        if fitting_bins_count == 1 {
            score += 20.0; // don't abandon the only fitting bin
        }
    }

    // Prefer bins tighter than average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in stream: allow new bins slightly more; late: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(40.0);
        }
    }

    // Relative to mean residual: prefer bins below-average residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins could still take the item,
    // unless the item is large and a fresh bin is genuinely useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = if next_item_size > 0 && next_item_size as f64 >= 0.9 * bin_capacity as f64 {
            25.0
        } else {
            0.0
        };
        score += 10.0 + new_bin_bonus - 5.0 * progress;
    }

    // Slight preference to fill older/more bins when many are open (bin consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: non-linear penalty on wasted fraction.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no future item (min size 1..100) can use efficiently.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item cannot use leftover; mild penalty proportional to leftover.
            score += 3.0 * post_residual as f64 / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, unless item is huge relative to capacity
    // or many bins are already open (fragmentation control).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        let mut open_penalty = 12.0 + 10.0 * (1.0 - item_frac);
        // Late in the stream, prefer consolidating into open bins.
        open_penalty += 15.0 * progress;
        // Many open bins with large mean residual: opening new bin wastes that space.
        open_penalty += 0.3 * open_bins_count as f64 * (mean_residual / cap);
        score += open_penalty;
        // Huge items (>= 80% of capacity) are fine in a fresh bin.
        if item_frac >= 0.8 {
            score -= 20.0;
        }
        // If next item is nearly as large as this one, a fresh bin gives more flexibility.
        if next_item_size >= item_size && item_frac >= 0.6 {
            score -= 8.0;
        }
    }

    // Global state coupling: prefer bins whose residual is far from mean residual
    // (keep a diverse residual portfolio), mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear stream progress in [0,1]
    let progress = if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Normalized post-residual (waste potential)
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;

    // Polynomial coupling: residual waste matters more as stream progresses
    score += (pr2 * 14.0 + pr * 4.0) * (0.6 + 1.4 * prog3 + 0.8 * prog2);

    // Tight fit reward: smooth bell around zero post-residual
    let tight = (-2.8 * pr).exp();
    score -= 18.0 * tight * (1.0 + 0.5 * progress);

    // Last-chance bin: strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate penalty: only open a new bin when this bin's residual
    // cannot plausibly serve the lookahead item, weighted by progress
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 30.0;
        // Allow opening new bin if post_residual here (== capacity) is much better
        // than the alternative residual would be... expressed via lookahead fit:
        let look_fits_here = (next_item_size as f64) <= pr * cap && next_item_size > 0;
        if look_fits_here {
            score += 40.0; // this bin can serve the next item too: don't open new
        }
        score -= 35.0 * (1.0 - (post_residual as f64 / cap)); // always 0 for new bin
    }

    // Lookahead coupling: penalize leaving residual that no future item uses,
    // reward residual that matches next item size (smooth kernel)
    if next_item_size > 0 {
        let diff = (pr * cap - next_item_size as f64).abs();
        let match_kernel = (-(diff * diff) / 180.0).exp();
        score -= 12.0 * match_kernel * (0.5 + progress);
        score += 6.0 * (diff / cap) * (0.4 + 0.6 * prog2);
    } else {
        // Last item: minimize residual as much as possible
        score -= 10.0 * (1.0 - pr);
    }

    // Congestion term: many open bins -> prefer filling existing ones
    let congestion = (open_bins_count as f64).ln_1p();
    score += congestion * 2.0 * pr * (0.5 + prog2);

    // Deviation from mean residual: prefer bins below mean residual (fuller bins)
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: bucket post_residual into capacity-fraction classes.
    // Residuals that are "perfect" (0) are best; small unusable slivers (<10) are heavily penalized.
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else if post_residual < 10 {
        score += 200.0; // dead sliver
    } else {
        // modulo arithmetic: residual classes mod 10 — small residues mean near-perfect fits
        let cls = post_residual % 10;
        score -= (10 - cls) as f64 * 2.0;
        // integer-division thresholds: residual in [10,30] can still host small items
        if post_residual >= 10 && post_residual <= 30 {
            score -= 15.0;
        }
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + next_item_size as f64 * 0.5;
    } else if next_item_size > 0 {
        // penalize if next item cannot fit here (will likely need new bin anyway)
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only when
    // no open bin gives a tight fit, or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // baseline cost of a fresh bin: high, but discounted late in stream
        score += 120.0 - 30.0 * progress;
        // if many open bins have large residuals, opening new bins is wasteful
        if mean_residual > 40.0 {
            score += 40.0;
        }
        // if the item is large relative to capacity, a fresh bin is reasonable
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // pairing potential in fresh bin
        }
    } else {
        // reward using bins with large residuals (spread load evenly)
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // Slight preference to fill older bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Dead-space coupling: penalize large leftover when next item cannot use it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual {
            score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score -= 15.0; // next item can reuse the gap
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 90.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 40.0; // big upcoming item: fresh bin is fine
        }
    }

    // Mild stream progression: prefer consolidating early, allow new bins late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64 - 0.5).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Perfect 2-step fill: residual consumed exactly by next item.
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
        // Post residual too small for next item: dead space penalty scaled by item size.
        if (post_residual as u32) < next_item_size {
            score += 8.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 0.0;
    }

    // Relative to mean residual: prefer bins with residual near/below mean (avoid fragmenting large-residual bins).
    score += 0.4 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If next item won't fit with current item in a fresh bin, opening is more attractive.
        if next_item_size > 0 && bin_capacity - item_size < next_item_size {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference for tighter existing fits overall.
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 2.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / bin_capacity as f64);
        }
    } else {
        // Last item: closing bins fully is free; reward near-full packing.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 15.0 * (fit_ratio - 0.5);
        }
    }

    // New empty bin candidate: penalize opening a new bin when open bins exist,
    // scaled by how many bins could fit the item and stream progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut penalty = 20.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            penalty -= 30.0; // must open a bin
        }
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            penalty += 8.0; // an open bin could take it, discourage new bin
        }
        score += penalty;
    }

    // Mild pressure to consolidate into bins with larger residuals early on
    // (fills big holes first), but relax late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_dev = bin_residual as f64 - mean_residual;
    score += (1.0 - progress) * 0.05 * residual_dev;

    // Slight preference for bins with fewer siblings when many bins are open
    // (encourage closing bins out).
    score += 0.02 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, with a non-linear polynomial coupling to stream progress
    let mut score = pr as f64;

    // Smooth polynomial penalty on wasted space, amplified late in the stream
    let tight = 1.0 - x;
    score -= 8.0 * tight * tight * (0.5 + progress);

    // Penalize post-residuals that are small but non-zero (dead space), smoothly via sin-like poly
    let dead = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += 6.0 * dead * (0.3 + progress);

    // Last-chance bin: reward strongly, more so late in stream
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.5 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
        score -= 7.0 * fits_next * (1.0 - gap / cap).max(0.0);
        // mild penalty for near-miss lookahead
        score += 2.0 * (1.0 - fits_next) * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    let mean_x = mean_residual / cap;
    score += 3.0 * (x - mean_x) * (x - mean_x) * (1.0 + progress) - 2.0 * (x - mean_x);

    // Crowding: many open bins -> discourage opening new bins implicitly via residual on empty bin
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 6.0 * crowd * x;

    // Smooth early-stream openness: allow new bins early, discourage later
    score += 5.0 * (1.0 - progress) * (1.0 - progress) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: multiples of common item classes (10,20,25,50)
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 { 60.0 }
        else if pr % 50 == 0 { 25.0 }
        else if pr % 25 == 0 { 18.0 }
        else if pr % 20 == 0 { 15.0 }
        else if pr % 10 == 0 { 10.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Reward when next item fits exactly into post residual (perfect lookahead chain)
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // partial credit, stronger for smaller leftover waste
            score -= 20.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item cannot fit here: penalize leaving awkward gaps
            let gap = (pr - (pr % next_item_size.max(1))) as f64;
            score += 8.0 * (gap / cap);
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Penalize tiny dead space that nothing (min size ~1..10) can use
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Modulo class coupling on item size: items in coarse classes pair well with matching residuals
    let item_class = item_size / 10;
    let resid_class = pr / 10;
    if item_class == resid_class && pr > 0 {
        score -= 6.0;
    }

    // Late in stream: consolidate, prefer filling existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        // new bin candidate: penalize more when many bins are open or stream is late
        score += 12.0 * progress + 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first)
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for any item (min size 1, but practically
    // gaps below ~10 are hard to reuse). Penalize quadratically in the "useless" zone.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    } else if post_residual < 20 {
        // Semi-dead zone: mild penalty to prefer fuller fits elsewhere.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: fraction of residual consumed.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the post residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If post residual can't host the next item but the bin is nearly full anyway,
    // that's fine; but if we leave a gap that blocks the next item, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing bins
    // rather than opening more.
    let pressure = (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual < bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: baseline offset so it only wins when fits are poor.
        score += 25.0 + pressure;
        // If no existing bin fits well (this call is the new-bin candidate and
        // fitting bins exist but we still evaluate), keep it competitive when
        // the stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // Mean residual coupling: if the average residual is high, we have slack
    // elsewhere; slightly prefer opening fresh bins for awkward items.
    if bin_residual == bin_capacity {
        score -= (mean_residual - 30.0).max(0.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: waste below a small threshold is heavily discounted.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves a gap; penalize proportional gap quality
            let gap = (post_residual - next_item_size) as f64;
            score += 0.6 * gap - 6.0;
        } else {
            // next item cannot use this bin's remainder: dead space risk
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Relative fit against mean residual: bins already tighter than average are better targets.
    let rel = post_residual as f64 - mean_residual;
    score += 0.25 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // with multiple options, prefer the tightest fits (post_residual already does this)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: neutral base; make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let stream_pos = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 - 15.0 * stream_pos;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big upcoming item: fresh bin keeps space flexible
        }
    }

    // Late in the stream, be more tolerant of imperfect fits to close out bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placements whose leftover can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild penalty for proliferating open bins (fragmentation pressure).
    score += 0.05 * (open_bins_count as f64).sqrt();

    // Progress-aware dead-space penalty: waste matters more late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score -= 4.0 * (1.0 - progress);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Baseline: opening a new bin is moderately expensive.
        score = bin_capacity as f64 * 0.75 + item_size as f64 * 0.1;
        // Open a fresh bin when the item is large and existing residuals are poor.
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // Late in the stream, avoid opening bins that would be nearly empty forever.
        if post_residual > 60 {
            score += 10.0;
        }
    } else {
        // Penalize leaving a residual that no plausible item (min size ~ small) can use,
        // scaled by how fragmented the pool already is.
        if post_residual > 0 && post_residual < 5 {
            score += 6.0;
        }
        // Slight preference for bins whose residual is close to the item (tight fit).
        score += 0.05 * (bin_residual as f64 - item_size as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual value modulated by stream progress
    score -= 30.0 * norm_pr * (1.0 - progress) * norm_pr;
    score += 20.0 * norm_pr * progress * progress;

    // Penalize dead space quadratically when residual becomes unusable
    let dead = if next_item_size > 0 && (next_item_size as f64) > pr { 1.0 } else { 0.0 };
    score += dead * (norm_pr * norm_pr) * 40.0 * (1.0 - progress);

    // Lookahead synergy: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 25.0 * (-8.0 * gap * gap).exp() * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - progress);
    }

    // Crowding pressure: with many open bins, favor filling existing ones
    let crowd = (open_bins_count as f64).ln_1p();
    score -= crowd * norm_pr * 10.0;

    // Mean-residual deviation term: prefer bins deviating from the mean fill smoothly
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * (0.5 + progress);

    // New-bin candidate: make empty bins mildly unattractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - progress) * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common size
    // classes (10, 20, 25, 50) are more reusable than arbitrary residues.
    let mut class_bonus = 0.0;
    if post_residual == 0 {
        class_bonus += 60.0; // perfect fit: ideal
    } else if post_residual % 50 == 0 {
        class_bonus += 45.0;
    } else if post_residual % 25 == 0 {
        class_bonus += 30.0;
    } else if post_residual % 10 == 0 {
        class_bonus += 20.0;
    } else if post_residual % 5 == 0 {
        class_bonus += 10.0;
    }
    score -= class_bonus;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how well it packs
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize small dead residuals
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 25.0 + 20.0 * (1.0 / (1.0 + crowded));
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += 0.3 * (bin_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Late in the stream, consolidate: favor bins with residual close to item size.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size of 1, but practically below ~10)
    // are heavily penalized, with a non-linear blowup for near-zero gaps.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr) / 10.0; // dead space wedge penalty
        }
        // superlinear waste term: bigger leftover gaps are progressively worse
        score += 0.02 * pr * pr;
    } else {
        // perfect fill is the best possible outcome
        score -= 40.0;
    }

    // Reward tight fits: fraction of the bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // with multiple options, mildly prefer bins that are more filled
        score += 3.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    // (large dead space) or no bin fits well. An empty bin has post_residual ==
    // bin_capacity, which the superlinear term already penalizes; add explicit
    // open-bin pressure so we don't proliferate bins unnecessarily.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // but if the next item is large and current residuals are small,
        // reserving a fresh bin can pay off
        if next_item_size > 0 {
            let avg_gap = mean_residual.max(0.0);
            if (next_item_size as f64) > avg_gap && post_residual >= next_item_size {
                score -= 30.0;
            }
        }
        // late in the stream, avoid opening bins at all costs
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    }

    // Lookahead: if placing here leaves room exactly for the next item,
    // reward it; if it leaves a gap just below the next item size, penalize.
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nr).abs() < 1.0 {
            score -= 20.0;
        } else if pr < nr && pr < 10.0 {
            score += 10.0;
        }
    }

    // Gentle preference for fuller bins overall (mean residual coupling).
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;

    // 2-step lookahead: does the next item fit into the post-residual?
    let next_fits = next_item_size > 0 && post_residual >= next_item_size;
    if next_fits {
        // Reward: this bin can host the current item AND the next one.
        score -= 30.0 + (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize dead space that the next item cannot use.
        let waste = post_residual as f64;
        score += waste * 0.6;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Tightness relative to mean residual: prefer bins that are already
    // partially filled (small residual) to consolidate load.
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // New-bin handling: opening a fresh bin is expensive; only allow it
    // when no open bin offers a decent fit. Penalize new bin by default,
    // but relieve the penalty when the item is large relative to capacity
    // (poor fit anywhere) or when open bins would leave big waste.
    if is_new_bin {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let best_open_waste = if next_item_size > 0 {
            (bin_capacity as f64 - item_size as f64) - next_item_size as f64
        } else {
            0.0
        };
        // Base cost of opening a bin.
        score += 70.0;
        // Large items justify opening a new bin more.
        score -= item_frac * 40.0;
        // If the leftover after placing in a new bin is small (good packing),
        // the new bin becomes attractive.
        if post_residual <= 10 {
            score -= 45.0;
        }
        // If open bins would waste a lot relative to next item, new bin ok.
        if best_open_waste > 20.0 {
            score -= 25.0;
        }
    }

    // Late in the stream, slightly prefer closing bins tightly (fewer open bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: penalize opening a new bin unless the fit is poor
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual >= 20 && post_residual <= 40 {
            score -= 25.0; // new bin is fine if it leaves a usable mid-range residual
        }
        if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 * 0.9 {
            score -= 30.0; // lookahead item may fill the fresh bin well
        }
        return score;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_residual as f64) * 30.0;

    // Penalize creating small unusable dead space
    if post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 6.0;
        }
    }

    // Global state coupling: spread out fills when many bins are open
    score += (open_bins_count as f64).sqrt() * 2.0;
    score -= (post_residual as f64 - mean_residual).abs() * 0.15;

    // Time horizon: prefer tight fits more aggressively late in the stream
    score -= (bin_residual - post_residual) as f64 * progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fit), with mild non-linear shaping
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score = 0.9 * pr + 30.0 * norm_pr * norm_pr;

    // Reward tight fits more strongly as the stream progresses (consolidation pressure)
    let tightness = 1.0 - norm_pr;
    score -= (1.0 + 2.0 * progress) * 12.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful later (waste), smoothly coupled with progress
    let dead = if pr > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 };
    // Smooth version: dead-space penalty grows as pr approaches 0 relative to capacity
    score += progress * 20.0 * (1.0 - norm_pr).exp() * (1.0 - (pr / 10.0).min(1.0));

    // Lookahead: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 6.0 * progress;
    }
    // If next item would exactly consume the residual, extra reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slightly prefer bins with below-average residual (balance preservation), non-linear
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "reusable"
    // classes (multiples of common item sizes) should be favored.
    let reusable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if r > 0 && r % m == 0 {
                bonus += 4.0;
            }
        }
        bonus
    };
    score -= reusable(post_residual);

    // Penalize dead space: residual too small to fit the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: does post_residual still fit the next item? Reward that.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64) * 0.1;
        } else {
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tighter fits: small waste relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 10.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; let good existing fits win.
        score += 12.0;
        // But if the current item would leave a bad residual in any existing bin,
        // opening fresh is fine — reduce penalty late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 4.0;
    }

    // Slight preference for bins below mean residual (consolidate space).
    let diff = (bin_residual as f64) - mean_residual;
    score += diff * 0.05;

    // Integer-division threshold: bins whose residual class (residual / 10)
    // matches item's decade get a small harmonic alignment bonus.
    let cls_r = post_residual / 10;
    let cls_i = item_size / 10;
    if cls_r > 0 && cls_r % (cls_i.max(1)) == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (0 < post_residual < 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps that likely become dead space for typical items.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if item_size > 0 && post_residual * 4 <= item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin count and remaining stream.
        score += 25.0 + pressure * 3.0;
    } else {
        // Mild reward for filling existing bins, stronger when many bins are open.
        score -= pressure * 0.5;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        // Next item would leave dead space; slight penalty.
        score += 8.0;
    }

    // Prefer bins with residual close to item (avoid wasting large residual on small item).
    let waste_ratio = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += waste_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-perfect match: next item fits leaving minimal waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + slack / 20.0);
    }
    // Penalize dead space: post_residual too small for any plausible item (min size 1).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Compare against mean residual: placing into a bin with residual near the mean
    // keeps bin states balanced; penalize bins far below mean (precious tight bins).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.5 * (-dev);
    } else {
        score -= 0.2 * dev;
    }

    // New-bin candidate handling: empty bin gets moderate baseline; prefer it only
    // when no open bin offers a good lookahead match.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 150.0;
        }
        // Early in stream, opening bins is cheap; late, conserve.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream, prefer tighter packing (best-fit bias).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.8 * t;

    // Fragmentation penalty: residual that is small but nonzero is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leftover becomes dead weight relative to mean.
        score += 4.0 + (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0;
    }

    // New empty bin candidate: penalize mildly by default.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item is large and fits poorly elsewhere,
        // or when existing bins are too fragmented (low mean residual).
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fits = fitting_bins_count <= 1 || mean_residual < item_size as f64 * 0.5;
        if large_item && poor_fits {
            score -= 20.0;
        } else if large_item {
            score -= 8.0;
        } else {
            score += 15.0 + 0.2 * (open_bins_count as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap;

    // Base: prefer small post-residual, with a smooth convex penalty on large residuals.
    let mut score = pr + 18.0 * pr * pr / (cap * cap);

    // Reward tight fits more as the stream progresses (consolidate early slack later).
    score -= 30.0 * tightness * (0.5 + progress);

    // Non-linear coupling of post-residual with stream progress: late in the stream,
    // dead space is more costly, so penalize it super-linearly.
    score += 25.0 * (pr / cap) * (pr / cap) * progress;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Compare against mean residual: bins far below mean residual (already fragmented)
    // are better targets; smooth quadratic deviation term.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev - 6.0 * dev;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack_fit / cap);
    } else if next_item_size > 0 {
        // Post-residual too small for the next item: penalize creating near-dead space.
        score += 10.0 * (1.0 - pr / cap) * progress;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 20.0 + 35.0 * (1.0 - tightness) * crowding + 15.0 * progress;
        // If no other bin fits, new bin must win: heavy discount.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of 25
    // are "harmonic wells" because typical item sizes (1..100) cluster
    // around small denominators (25, 33, 50, 20...).
    let post = post_residual as i64;
    let mut well = f64::INFINITY;
    for m in [20i64, 25, 33, 50, 100] {
        let r = (post % m).abs();
        let d = r.min(m - r) as f64;
        if d < well {
            well = d;
        }
    }
    score += well * 0.9; // penalize post-residuals far from harmonic classes

    // Integer-division thresholds: post_residual bucketed by /10
    // rewards leaving residual in "usable" coarse bands.
    let band = post_residual / 10;
    match band {
        0 => score += 60.0,          // dead space (<10)
        1..=3 => score += 18.0,      // poor
        4..=6 => score -= 12.0,      // good band
        7..=9 => score -= 6.0,       // fine
        _ => {}                       // exact fit / fresh bin
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item exceeds post_residual, mildly penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size).min(20) as f64 * 0.4;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin is neutral baseline but
    // penalize opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.3;
    }

    // Tightness reward: smaller relative waste wins.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Late-stream pressure: consolidate more aggressively near the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 + (open_bins_count as f64).ln() * 2.0;

    // Mean-residual deviation: prefer bins whose residual is below average
    // (filling the emptier-feeling bins keeps many mid-size bins open).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (<10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fill is the ideal outcome.
        score -= 40.0;
    }

    // Non-linear penalty on wasted fraction of the bin's residual capacity.
    let waste_frac = post_residual as f64 / bin_residual.max(1) as f64;
    score += waste_frac * waste_frac * 30.0;

    // Reward tight fits: item consuming most of the residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 25.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: baseline preference so it's only chosen when
    // all open bins offer bad fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening new bins is more costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement is extra valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0; // chains perfectly for the next item
        } else {
            score -= 10.0 / slack.max(1.0);
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0; // dead space that even the next item cannot use
    }

    // Mild alignment with mean residual: prefer bins near the mean state.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0; // chain two items perfectly
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // residual can still host the next item: mild reward proportional to slack
        score -= 2.0 + (post_residual - next_item_size) as f64 * 0.05;
    }

    // Penalize tiny dead space (unusable residuals below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 5.0; // perfectly closed bin
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item barely fits anywhere else
    // or the stream is early and we want parallel capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let waste = (bin_capacity - item_size) as f64;
        score = waste + desperation - 40.0 * (1.0 - progress) * (open_bins_count as f64).recip();
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (filling the emptiest bins first keeps many medium residuals alive).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, with a convex penalty for waste.
    let waste_frac = post_residual as f64 / cap;
    score += 8.0 * waste_frac * waste_frac * cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 5.0 + 3.0 * (nxt / cap);
        } else {
            // Penalize leaving dead space that the next item cannot use.
            let dead = post_residual as f64 - nxt.min(cap);
            score += 0.5 * dead.max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits poorly
    // or many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let frag = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so new bins are only chosen when existing fits are bad.
        score += 20.0;
        // If this bin is the only fitting bin, opening new bin is bad.
        if fitting_bins_count <= 1 {
            score += 25.0;
        }
        // Early stream: slightly discourage hoarding new bins.
        score += 10.0 * (1.0 - progress);
        // High fragmentation: opening a fresh bin is more acceptable.
        score -= 8.0 * frag;
    }

    // Mild preference for bins with residual close to item (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 4.0 * gap * gap;

    // Slight tie-break by mean residual alignment.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress:
    // early on, prefer tight packing (low post_residual); later, tolerate larger leftovers.
    let residual_f = post_residual as f64;
    let coupling = residual_f * residual_f * (0.5 + 1.5 * progress) / (bin_capacity as f64);

    score += coupling;

    // Reward near-perfect fits with a smooth quadratic discount
    let perfect = 1.0 - (residual_f / bin_capacity as f64);
    score -= 30.0 * perfect * perfect * perfect;

    // Penalize dead space that no plausible next item can use (lookahead-aware)
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        let usable = if nxt <= gap { 1.0 } else { (gap / nxt).min(1.0) };
        score += 12.0 * (1.0 - usable) * (gap / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // spread preference among many fitting bins by residual quality
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 8.0 + 3.0 * open_f.sqrt() * (0.5 + progress);
    }

    // Alignment with mean residual: prefer bins whose resulting residual matches the mean
    let dev = (residual_f - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: empty bin gets a baseline tied to mean residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when existing bins would be badly fragmented.
        // If the best fit among open bins is poor (high mean residual spread), favor new bin.
        score = 55.0 + 0.10 * (open_bins_count as f64);
        // If item is small relative to capacity, opening fresh bin is wasteful early on.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // Large items justify fresh bins.
        score -= 0.25 * item_size as f64;
        // If many bins can fit the item, no urgency to open a new bin.
        if fitting_bins_count > 2 { score += 25.0; }
        if fitting_bins_count == 1 { score -= 15.0; }
        return score;
    }

    // Harmonic class of post_residual: modulo-classes of capacity fractions.
    let pr = post_residual;
    // Dead space classes: residuals that very few item sizes can use are penalized.
    // Items are 1..100, but usable residual classes matter most in low ranges.
    let class = pr % 10;
    // Residuals in (0,10) are nearly dead space -> strong penalty.
    if pr > 0 && pr < 10 {
        score += 30.0 - 3.0 * pr as f64;
    }
    // Harmonic sweet spots: residuals that are multiples of 25 or 50 are highly reusable.
    if pr % 50 == 0 && pr > 0 { score -= 12.0; }
    else if pr % 25 == 0 && pr > 0 { score -= 6.0; }
    else if class == 0 { score -= 3.0; }

    // Exact fit is perfect.
    if pr == 0 { score -= 50.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // Next item fits: reward proportional to how well it fills.
            score -= 10.0 * (next_item_size as f64 / pr as f64);
        } else {
            // Next item won't fit here; penalize residuals just below next_item_size.
            if pr > 0 && pr >= next_item_size - 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tighter fit (already via post_residual),
        // slight penalty scaled by competition to keep discrimination.
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins below mean residual (tighter bins) to consolidate fragmentation.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Late in stream, squeeze more aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever fit another item (min size 1..=100 unknown,
    // so treat small gaps < ~15 as likely dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 30 {
        score += 15.0;
    }

    // Reward near-perfect fits (waste minimization).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // If the next item fits exactly in the post residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // Extra reward if next item fills the bin almost completely after being placed.
        if post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && post_residual < next_item_size.min(30) {
        // Next item cannot use this gap; penalize slightly if gap is small.
        score += 8.0;
    }

    // Last chance: if this is the only bin that fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Pressure from number of open bins: prefer already-open bins over spawning new ones.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Prefer bins with residuals below the mean (consolidating fullness).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Mild late-stream tightening: as the stream progresses, prioritize compact packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    // New empty bin candidate: make it slightly unattractive unless item is large relative to residual alternatives.
    if bin_residual == bin_capacity {
        score += 10.0 + item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit lookahead bonus: post residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain two items perfectly
        } else if post_residual >= next_item_size {
            // next item fits with small leftover: reward tight chains
            let chain_left = post_residual - next_item_size;
            score -= 40.0 - (chain_left as f64).min(40.0);
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 0.15 * post_residual as f64;
        }
    }

    // Reward bins tighter than the mean residual (good packing candidates)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when it enables a perfect next fit
    // or when open bins are nearly full; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0;
        } else {
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Slight preference to fill older bins early in the stream
    if step_index < total_items / 2 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual)
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).ln().max(0.0);

    // Penalize dead space that is too small to fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.3 + 0.7 * progress);
    }

    // Reward leaving room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Penalize opening new bins, more so early in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 0.5 * progress) + open_bins_count as f64 * 0.1;
        // But allow opening if the item fits poorly everywhere else
        if post_residual < 5 { score -= 8.0; }
    } else {
        // Mild preference for bins with above-average fill
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth non-linear scaling over progress
    let mut score = pr * (1.0 + 0.8 * t * t);

    // Polynomial coupling of post-residual with stream progress:
    // later in the stream, dead space is penalized more aggressively
    score += 30.0 * t * norm_pr * norm_pr * cap * 0.1;

    // Reward tight fits (post_residual small relative to item)
    let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_quality * fit_quality * (1.0 - t * 0.5);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / cap * (1.0 + t);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + t);
    }

    // New-bin candidate: penalize opening a new bin, less so early in the stream
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 12.0 + 6.0 * openness * (0.5 + 0.5 * t) + 10.0 * t * t;
    }

    // Mild penalty for bins far below mean residual (fragmentation avoidance)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.5 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: capacity divided into quarters
    let q = post_residual / (bin_capacity / 4).max(1); // 0..=4 harmonic class
    score += match q {
        0 => 0.0,                       // perfect fit, best
        1 => 25.0,                      // dead quarter, bad
        2 => 8.0,                       // half slot, still reusable
        3 => 3.0,
        _ => 0.0,
    };

    // Exact modulo harmonic: residuals that are multiples of common item sizes
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 12.0;
    }

    // Penalize residual that cannot host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // bonus if post_residual exactly matches next item (harmonic pairing)
            if post_residual == next_item_size {
                score -= 20.0;
            }
            // integer-division harmonic: post_residual can host next item k times
            let k = post_residual / next_item_size.max(1);
            if k >= 2 {
                score -= 5.0 * (k.min(4) as f64);
            }
        } else {
            score += 10.0; // dead space relative to lookahead
        }
    } else {
        // last item: prefer tightest fit
        score = post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish, slightly penalized unless current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 40.0 + fragmentation * 0.2 - (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits, must open
        }
    }

    // Late in the stream, tighten packing (favor small residuals more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Reward bins below mean residual (tighter bins first)
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: exact match leaves zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 2.0;
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize dead space the next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well.
    if bin_residual == bin_capacity && bin_capacity - item_size > 0 {
        score += 40.0 + (bin_capacity - item_size) as f64 * 0.3;
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // Prefer tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * progress * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: bin remains usable for the lookahead item.
            score -= 6.0;
            // Extra reward if post_residual is close to next_item_size (near-perfect chain).
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Dead space for the known next item.
            score += 5.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins fit the item, mild pressure toward best-fit (post_residual term dominates).
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when open bins have poor residuals
    // or few bins can fit the item.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        // Opening a new bin is penalized normally...
        score += 30.0;
        // ...but rewarded when existing bins are fragmented or scarce.
        score -= 40.0 * scarcity * (1.0 - avg_pressure).max(0.0);
        // Late in the stream, avoid opening bins that will be mostly empty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 {
            score += 10.0 * progress;
        }
    }

    // Fragmentation penalty: leaving residuals far from any typical item size.
    let mid_gap = (post_residual as f64 - bin_capacity as f64 * 0.4).abs();
    score += 0.05 * mid_gap;

    // Mild preference to spread load when many bins are open with high mean residual.
    if open_bins_count > 4 && mean_residual > item_size as f64 * 1.5 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, smoothly coupled.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_curve = progress * (1.0 - progress) * 4.0; // peaks at 0.5, smooth

    // Reward tight fits: penalize less when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * (20.0 + 15.0 * progress_curve);

    // Non-linear polynomial coupling of post_residual with progress:
    // mid-stream, prefer filling bins aggressively; early/late, mild.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += pr_norm * pr_norm * (1.0 - pr_norm) * (10.0 + 20.0 * progress_curve);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += waste * (1.0 + 0.5 * pr_norm) * (0.5 + progress);
        } else {
            // Reward leaving a gap exactly matching next item (perfect lookahead fit).
            let gap_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= gap_fit * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: neutral-ish baseline; open new bins when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
        score = 0.5 * bin_capacity as f64 + 10.0 * crowd - 12.0 * progress_curve;
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that are awkwardly small (dead space) with super-linear cost
    if post_residual > 0 {
        let awkward = (bin_capacity as f64 / post_residual as f64).powi(2);
        score += 12.0 * awkward * frac;
    } else {
        score -= 30.0; // perfect fit is great
    }

    // Reward tight fits (post_residual below harmonic threshold classes)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving a residual that wastes the class
            let waste_class = post_residual % 10;
            score += 6.0 * (waste_class as f64 / 10.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly, but allow it when mean residual is high and
    // this placement would leave a large awkward residual
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 - 15.0 * pressure;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    } else {
        // Slight preference for bins already below mean residual (consolidating space)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Modulo harmonic class of post_residual: residuals divisible by common item classes
    // (10, 20, 25) are more reusable
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable && post_residual > 0 {
        score -= 8.0;
    }

    // Early in stream: be more willing to open bins (keep options open)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Many open bins: favor consolidating into existing bins
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).sqrt() * frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Favor bins whose residual tightly matches the item (relative fill).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead coupling: reward if the next item can use the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer consolidation when many bins are open.
    score += 1.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins below-average residual (tighter bins).
    score += 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it unattractive unless it would otherwise be a last resort.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.3 * open_bins_count as f64;
    }

    // Slight late-stream tightening: waste matters more as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain fit: strongly favor this bin.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but with slack: partial reward scaled by how snug.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 30.0 * snug;
        } else {
            // Next item cannot follow into this bin: penalize, worse if gap is small.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.15 * gap;
        }
    }

    // Compare residual against mean residual of open bins: prefer using bins
    // that are already more depleted than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid wasting it
    // on a loose fit; but if the fit is tight, strongly prefer it.
    if fitting_bins_count == 1 {
        if post_residual <= 10 {
            score -= 25.0;
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
        score += 20.0 * pressure + 0.3 * (open_bins_count as f64);
    }

    // Late in the stream, prioritize closing bins tightly (reduce open-bin sprawl).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste by relative fill of the bin.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score += 0.35 * (post_residual as f64) * fill_ratio;

    // Penalize very small dead space less if it exactly fills (perfect fit bonus).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 8.0; // tiny sliver is nearly dead space
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // blocks the next item
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the item
    // would leave a large, unusable gap in an existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, discounted early in the stream
        // and when many items remain to be packed.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 30.0 - 10.0 * progress;
        // If the current bin would be left with a hole smaller than the
        // smallest plausible item, opening fresh is attractive.
        if post_residual < 15 && bin_residual < bin_capacity {
            new_bin_cost -= 25.0;
        }
        // With many open bins and low mean residual, avoid spreading.
        if open_bins_count > 4 && mean_residual < 30.0 {
            new_bin_cost += 15.0;
        }
        score += new_bin_cost;
    }

    // Mild pressure to consolidate into bins that are already fairly full.
    score -= 5.0 * fill_ratio;

    // Global-state coupling: when mean residual across bins is high,
    // prefer bins below the mean (they have more usable structure).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    // Base: normalized post residual (small post = tight fit)
    let norm_post = post / cap;
    let mut score = norm_post * (1.0 + 0.8 * progress);

    // Smooth quadratic coupling: punish mid-range waste more as stream progresses
    let waste_curve = norm_post * norm_post * (1.0 - norm_post);
    score += 2.5 * progress * waste_curve;

    // Reward tight fits (post_residual near zero) with smooth sigmoid-like term
    let tight = (-norm_post * 12.0).exp();
    score -= 3.0 * tight * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_ratio = nxt / post.max(1.0);
            score -= 2.0 * fit_ratio * fit_ratio;
        } else {
            // next item won't fit here; slight penalty for leaving large unusable gap
            score += 0.5 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless item is large
    if bin_residual == bin_capacity {
        score += 1.0 - 0.5 * (item / cap);
        // open new bin late in stream if item barely fits elsewhere is discouraged
        score += 0.5 * progress;
    }

    // Mild penalty when this bin's residual far exceeds mean residual (fragmentation)
    score += 0.3 * ((resid - mean_residual) / cap).abs();

    // Slight preference for consolidating into few bins when many are open
    score += 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "usable" classes (divisible cleanly by common item sizes 10..80).
    let pr = post_residual;
    let mut class_bonus = 0.0;
    for d in [10u32, 20, 25, 50] {
        if pr >= d && pr % d == 0 {
            class_bonus += 6.0;
        }
    }
    // Perfect fit classes
    if pr == 0 {
        class_bonus += 25.0;
    } else if pr < 10 {
        class_bonus -= 12.0; // dead space below minimum item size
    }
    score -= class_bonus;

    // Modulo coupling with next item: if the next item fits exactly the post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if pr >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // harmonic pairing: item+next divides capacity nicely
        if (item_size + next_item_size) % 50 == 0 || (item_size + next_item_size) % 100 == 0 {
            score -= 10.0;
        }
    }

    // Integer-division threshold on post residual
    let q = pr / 25;
    score -= q as f64 * 2.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins when many bins are open
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 15.0 * (open_bins_count.min(20) as f64 / 10.0);

    // New-bin candidate: penalize opening a bin unless residuals are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual < 15.0 && open_bins_count > 0;
        if tight {
            score -= 10.0;
        } else {
            score += 20.0 + mean_residual * 0.3;
        }
    }

    // Slight progression pressure
    score -= (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure loss; penalize gaps that can never be filled by any plausible item.
    let dead_threshold = 10.0f64; // below this, gap is likely unusable
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize mid-range dead space that only fits tiny items: quadratic blowup
    // on gaps in (10..=20] which are awkward for future items.
    if post_residual > 0 && post_residual <= 20 {
        score += 8.0 * (21.0 - post_residual as f64);
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item is large and residual barely
    // covers it, keep the bin attractive; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 4.0 * (next_item_size - post_residual) as f64;
        } else {
            score += 1.5 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., tighter bins) to keep a pool of large residuals for big items.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Slight preference to fill bins as the stream progresses (avoid leftover sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // New-bin candidate: make empty bins mildly attractive only when it is a
    // genuinely bad fit elsewhere; penalize default new-bin choice.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item does not fit: penalize dead space creation.
        score += 20.0;
    }

    // Penalize small unusable residuals (waste), unless it's a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    // Prefer bins tighter than the mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last fitting bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the item fits very poorly elsewhere
    // (e.g. residual much larger than item leaves lots of dead space). Penalize mildly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Encourage new bin early in stream when many bins are open anyway.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward filling bins with large items (reduces long-term fragmentation)
    score -= 0.4 * item_size as f64;

    // Lookahead: reward leaving exactly room for the next item (perfect pairing)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // dead space too small for the next item
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize a brand-new bin more aggressively early on (when open bins are cheap to use),
    // less aggressively late in the stream
    if bin_residual == bin_capacity {
        score += 15.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins whose residual is close to the global mean residual
    // (keeps residual distribution balanced, avoids extreme fragmentation)
    score += 0.08 * (mean_residual - post_residual as f64).abs();

    // Extra penalty for creating very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic dead-space penalty, weighted up as stream progresses
    let base = pr_norm * pr_norm * (1.0 + 2.0 * progress) * cap;

    // Smooth coupling: post_residual interacting with item tightness
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    let coupling = pr_norm * (1.0 - tightness).powi(2) * 20.0;

    // Lookahead reward: if next item fits into post_residual, strongly favor this bin
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -30.0 * (1.0 - (next_item_size as f64 / pr.max(1.0))) * (0.5 + progress)
    } else {
        0.0
    };

    // Penalize wasting the last-chance bin
    let last_chance = if fitting_bins_count == 1 { 15.0 + 10.0 * (1.0 - progress) } else { 0.0 };

    // Slight preference for bins below mean residual (consolidating fuller bins)
    let mean_pull = (mean_residual - pr) * 0.1;

    // New-bin candidate: mild penalty so it's only chosen when open bins are truly bad
    let new_bin_bias = if bin_residual == bin_capacity { 8.0 + 12.0 * progress } else { 0.0 };

    let mut score = base + coupling + last_chance + mean_pull + new_bin_bias + lookahead_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into coarse buckets
    // via integer division on capacity fractions (e.g. 100 -> classes of 12).
    let class = (post_residual / 12) as f64;
    score += class * class * 0.35; // superlinear penalty for large dead classes

    // Lookahead coupling: reward bins whose post_residual still fits the next item,
    // with bonus scaled by how tightly the next item fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 14.0 + 0.25 * (next_item_size as f64) - 0.10 * tightness;
    } else if next_item_size > 0 {
        // Dead space that cannot host the next item: penalize proportionally
        // to how much of the class range is wasted.
        let waste = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
        score += 0.20 * waste;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = -50.0; // must open a bin
        } else {
            // Base cost of a fresh bin + discourage when mean residual is large.
            score = 90.0 + 0.5 * mean_residual + 2.0 * open_bins_count as f64;
            // Late in the stream, prefer closing out existing bins.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * progress;
        }
    }

    // Small harmonic ripple: modulo-3 modulation on post_residual to break ties
    // toward residues that historically pair well with common item sizes.
    score += match post_residual % 3 {
        0 => -1.5,
        1 => 0.5,
        _ => 1.0,
    };

    // Mild preference for tighter fits overall.
    score += 0.05 * (bin_residual - item_size) as f64 * 0.0; // no-op guard
    score += 0.03 * item_size as f64 * (bin_capacity as f64 / (bin_residual.max(1) as f64)) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest future item are pure waste — penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (post residual near zero is excellent).
    if post_residual == 0 {
        score -= 60.0;
    }

    // If the lookahead item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead can't use the gap: penalize proportional to wasted gap.
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // encourage filling existing ones (subtract more for real bins).
    let pressure = (open_bins_count as f64).ln() * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += pressure + 10.0;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is already below the mean (they are "tighter").
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be more willing to open bins (less pressure);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * -15.0; // cheaper new bins early
        score += progress * 20.0;          // expensive new bins late
    }

    // Penalize leaving a gap that matches no plausible small item range.
    if post_residual > 0 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match -> big bonus; near-match -> graded bonus
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 40.0 - 4.0 * diff;
        } else {
            // residual that can't hold next item is dead space; penalize mildly
            score += 0.15 * diff;
        }
    }

    // Reward small post residuals generally (tight fit)
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // Penalize leaving residuals that are unusable for typical items (too small)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when open bins have poor residuals
    if bin_residual == bin_capacity {
        let desperation = if nxt > 0.0 && mean_residual < nxt {
            1.0
        } else {
            0.0
        };
        // base penalty for opening a new bin, reduced when open bins are bad
        score += 20.0 - 25.0 * desperation + 0.1 * mean_residual;
    }

    // Slight bias toward consolidating into fewer bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt().ln_1p();

    // Prefer bins whose residual is above mean (use the roomier ones for big items)
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the fuller the bin becomes, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fill_ratio;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 10.0 * (1.0 - next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Penalize leaving residual that the next item cannot use (dead space risk).
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure tight-fit maximization.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals
    // are all too small (fragmented state) or many bins are open late in stream.
    if bin_residual == bin_capacity {
        score += 35.0;
        if mean_residual >= item_size as f64 {
            score += 20.0;
        } else {
            // Fragmentation: new bin may genuinely be needed.
            score -= 15.0;
        }
        if open_bins_count as f64 > 0.3 * (total_items as f64).max(1.0) {
            score += 10.0;
        }
    }

    // Small dead-space bonus: near-perfect closure of a bin.
    if post_residual < 10 {
        score -= 18.0;
    }

    // Early stream: be slightly conservative, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping
    let mut score = pr;

    // Quadratic/cubic coupling of residual with stream progress:
    // early on, prefer tight packing (low post_residual) more strongly;
    // later, tolerate larger residuals since bins are sunk costs.
    let t = progress;
    let shape = 1.0 + 0.6 * t - 0.4 * t * t + 0.3 * t * t * t;
    score *= shape;

    // Non-linear interaction: post_residual relative to mean residual
    let mean_r = mean_residual.max(1.0);
    let rel = pr / mean_r;
    score += 12.0 * (rel * rel - rel) * (1.0 - t);

    // Reward filling bins nearly exactly (post_residual near 0) super-linearly
    score -= 30.0 * (-(pr / 8.0) * (pr / 8.0)).exp();

    // Penalize leaving residuals that match nothing useful: dead space grows
    // quadratically when post_residual is small but not zero (wasted sliver)
    if pr > 0.0 {
        score += 6.0 * (cap / (pr + 1.0)).sqrt() * t;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-(gap / 10.0) * (gap / 10.0)).exp();
        // penalize if next item is much larger than post_residual (bin becomes dead)
        if next_item_size as f64 > pr {
            score += 0.05 * (next_item_size as f64 - pr);
        }
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Small tie-break noise-free deterministic jitter via polynomial of step
    score += ((step_index as f64 * 0.017).sin()) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;

    // Reward tight fits strongly
    score -= 60.0 * fill_frac * fill_frac;

    // Harmonic class of post_residual: dead space classes
    // Residuals <= 10 are near-unusable (min item is 1, but small residuals waste capacity)
    if post_residual == 0 {
        score -= 100.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    } else {
        // Penalize dead space non-linearly: unusable gap between 1 and next item
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // residual too small for the known next item -> dead space
                let dead = (next_item_size - post_residual) as f64;
                score += 0.8 * dead;
            } else {
                // residual can host next item: reward
                let slack = (post_residual - next_item_size) as f64;
                score -= 2.0 * (1.0 - slack / bin_capacity as f64);
            }
        }
    }

    // Modulo-class logic on post_residual (harmonic classes mod 10 / mod 25)
    let m10 = post_residual % 10;
    let m25 = post_residual % 25;
    if m10 == 0 {
        score -= 6.0; // round residuals pair well with decadal items
    }
    if m25 == 0 {
        score -= 4.0;
    }
    // Awkward middle classes (residual in 11..=19) are hard to fill
    if post_residual >= 11 && post_residual <= 19 {
        score += 8.0;
    }
    if post_residual >= 26 && post_residual <= 34 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 35.0;
        // But if placing here would leave a very awkward residual and next item is big,
        // opening fresh is better
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 10 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight preference for fuller bins when many bins are open
    score += 0.05 * (open_bins_count as f64).min(20.0) * (1.0 - fill_frac);

    // Nudge toward bins whose residual is close to the mean (keeps balance)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fills relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Dead space becomes more wasteful when the bin residual was small.
    if bin_residual <= 30 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: prefer compacting into few bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is below mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    }
    // If next item cannot fit post_residual, mild penalty for leaving a gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 }
            else if post_residual > 0 && post_residual < 10 { 20.0 }
            else { 55.0 };
        score += desperation;
        // Late in the stream, avoid opening new bins even harder.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: post_residual matches next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead match: next item fits within post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // reward proportional to how well next item consumes the leftover
        let consume_ratio = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * consume_ratio;
    } else if next_item_size > 0 {
        // next item won't fit in the leftover: penalize dead space
        score += 10.0;
    }

    // Reward tight packing relative to mean residual: bin below mean residual is a good squeeze.
    let tightness = (mean_residual - post_residual as f64).abs();
    if (post_residual as f64) < mean_residual {
        score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 5.0 * tightness / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent fits exist, unless residual too fragmented.
    if bin_residual == bin_capacity {
        // new bin candidate: baseline cost, slightly worse than a good fit, better than awful fits
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        // late in the stream, prefer consolidating into existing bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 5.0;
        }
    }

    // Mild penalty for very small leftovers (fragmentation), scaled by stream position.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 + (step_index as f64 / (total_items.max(1) as f64)));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = post_residual - next_item_size;
        score -= 25.0 - (chain_fit as f64) * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space that blocks the next item
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits or the fit is very poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 60.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // late in stream, prefer reusing existing bins more strongly
        score += 80.0 + scarcity + progress * 40.0 - (open_bins_count as f64).min(20.0);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 30.0; // new bin can host the chain
        }
    } else {
        // Last-chance bin bonus: if this is the only bin that fits, use it
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
        // Prefer bins with lower residual relative to mean (consolidate fullness)
        score += (mean_residual - post_residual as f64) * 0.3;
    }

    // Mild preference for using more open bins early (spread load) vs late (fill up)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: as the stream advances, tolerate less waste.
    score *= 1.0 + 0.6 * progress * norm_post;

    // Interaction: post-residual vs. mean residual — penalize bins that are
    // outliers above the fleet mean (fragmented bins), reward below-mean.
    let mean_gap = (post - mean_residual) / cap;
    score += 12.0 * mean_gap * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize opening a new bin, more so mid/late stream
    // and when other bins can fit the item.
    let is_new_bin = (bin_residual == bin_capacity);
    if is_new_bin {
        score += 25.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap <= 1.0 {
            score -= 15.0 * (1.0 - progress);
        } else {
            // penalize post-residuals that are just barely too small for next item
            let near_miss = (next_item_size as f64 - post) / cap;
            if near_miss > 0.0 && near_miss < 0.15 {
                score += 10.0 * (1.0 - near_miss / 0.15);
            }
        }
    }

    // Mild open-bins regularization: discourage bin proliferation early on.
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Dead-space penalty grows super-linearly for unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if frac < 0.2 {
        score += 18.0 * (0.2 - frac) * 5.0;
    }

    // Harmonic classes via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..=10
    score += match class {
        0 => 25.0,
        1 => 8.0,
        2 | 3 => 0.0,
        4 | 5 => -4.0,
        6 => 3.0,
        _ => 6.0,
    };

    // Lookahead: reward if next item fits exactly into the post residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            // Reward chains that leave a usable harmonic-class remainder.
            score -= 10.0;
            if npost < 10 { score += 12.0; }
        } else {
            // Next item cannot use this bin's remainder: penalize wasting large residuals.
            score += 6.0 + 20.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: empty bin should only win when this bin's fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0
            + 0.15 * open_bins_count as f64
            + (mean_residual - post).abs() * 0.1;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when only one bin fits
        }
    }

    // Mild stream-progression coupling: later in stream, prefer tightening fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - frac);

    // Penalize bins far from the mean residual (fragmentation avoidance).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable gaps (dead space): gaps too small for the
    // smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that cannot fit the lookahead item are dead space for the near future.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * next_item_size as f64;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio; // prefer bins where the item fills most of the residual
    }

    // Perfect-fit lookahead: if the next item exactly fills the post residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones; the new-bin candidate has
    // bin_residual == bin_capacity and gets penalized here.
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure proportional to open bins.
        score += 35.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is more attractive late in the stream when mean
        // residual across bins is small (existing bins nearly full).
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward scaled by how much residual it still has
        // relative to the mean, encouraging balanced usage.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Stream progression: early on, allow slightly more freedom to open bins;
    // later, strongly prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 40.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize small dead space
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is below mean (tighter packing).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize so we only open when open fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
        // but if lookahead chain is perfect in a fresh bin, allow it
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Late in the stream: tighten packing, avoid waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual nonlinearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        }
        // If next item cannot fit here and post_residual is tiny, this bin is "finished" — good.
        if post_residual < next_item_size && post_residual <= 10 {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: prefer new bin only when residuals are fragmented or fit is bad.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin scales with number of open bins and mean residual quality.
        let fragmentation = if mean_residual > 0.0 {
            1.0 - (mean_residual / bin_capacity as f64).powi(2)
        } else {
            1.0
        };
        score += 200.0 + 15.0 * open_bins_count as f64;
        // Early in stream, opening new bins is cheap; later, prefer packing into open bins.
        score += (1.0 - progress) * 100.0;
        // If mean residual is large (lots of slack available), opening new bins is wasteful.
        score += fragmentation * 150.0;
    }

    // Mild penalty when this bin's residual deviates from the mean (keep residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins with larger residuals early, tighter bins later.
    score += progress * 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Penalize leaving dead space in the 11..20 window (classic bad gap).
    if post_residual >= 11 && post_residual <= 20 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * (1.0 - progress);

    let mut score = post * (1.0 + 0.5 * poly);

    // Reward tight fits
    let tight = 1.0 - norm_post;
    score -= 20.0 * tight * tight;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize dead space relative to mean residual
    if post > 0.0 {
        score += 0.3 * (post - mean_residual).abs();
    }

    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post >= n {
            score -= 8.0 * (1.0 - ((post - n) / cap).abs());
        } else {
            score += 6.0 * (n - post) / cap;
        }
    }

    // Mild penalty for too many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Base penalty: opening a new bin should lose against any decent fit.
        let mut nb = bin_capacity as f64 * 1.5;
        // If no other bin can fit the item, the new bin is the only option.
        if fitting_bins_count == 0 {
            nb = 0.0;
        } else if fitting_bins_count == 1 {
            // Last-chance bin: only open new bin if the fit is terrible.
            let waste = (bin_residual - item_size) as f64;
            if waste > bin_capacity as f64 * 0.4 {
                nb -= 40.0;
            }
        }
        return nb;
    }

    // ---- Tight fit rewards ----
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - post / cap;

    // Reward high fill ratio (subtract from score).
    score -= 30.0 * fill * fill;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // ---- Lookahead: next item fits exactly or well into the leftover ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 80.0; // chained perfect fit
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot fit: leftover is likely dead space.
            score += 0.3 * (nxt - post);
        }
    }

    // ---- Harmonic / modulo class logic on post_residual ----
    // Quantize leftover into harmonic classes of capacity.
    let class = post_residual / 25; // 0..3 classes (0-24, 25-49, 50-74, 75+)
    score -= match class {
        0 => 12.0, // small leftover: bin nearly sealed, good
        1 => 6.0,
        2 => 2.0,
        _ => 0.0,
    };

    // Modulo-10 harmonic alignment: leftovers that are multiples of 10
    // are statistically reusable by typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer-division threshold: leftover that cannot hold the smallest
    // plausible future chunk (post < 5) is effectively closed — mild reward.
    if post_residual < 5 {
        score -= 10.0;
    }

    // ---- Context coupling ----
    // Progress: late in the stream, avoid fragmenting capacity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post / cap);

    // Many open bins: prefer consolidating into ones with low residual.
    score += 0.5 * (post - mean_residual).max(-20.0).min(20.0);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && open_bins_count > 1 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item (1..=100) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Perfect pre-fit (item exactly fills what was left).
    if item_size == bin_residual {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it attractive unless the current fit is good.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many are already open.
        score = 70.0 + (open_bins_count as f64).sqrt() * 8.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // Late in the stream, opening new bins is less costly than fragmenting.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into emptier bins.
    score += (open_bins_count as f64) * 0.4;

    // Prefer bins whose residual is below average (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead: if the leftover after placement can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that just barely fails the next item.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item pairing
        }
        // Penalize leaving dead space smaller than the next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (post_residual as f64);
        }
    } else {
        // Last item: prefer filling bins as tightly as possible
        score -= 10.0;
    }

    // Tight fit reward relative to mean residual
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness).max(0.0) * (mean_residual / bin_capacity as f64 + 0.5);

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer many open bins being consolidated; penalize opening new bins late in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Small bonus for using fuller bins (low residual)
    score += 0.15 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Strong reward for perfect / near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Fill ratio coupling: prefer bins where item occupies a large fraction of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill;

    // Lookahead: penalize leaving a residual that fails to host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // residual still useful for next item: mild reward proportional to snugness
            let snug = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - snug / cap).max(0.0);
        } else {
            // dead space for the lookahead item
            let waste = (next_item_size - post_residual) as f64;
            score += 6.0 * (waste / cap);
        }
        // bonus if this bin could take both item and next item snugly
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0;
        }
    } else {
        // last item: strongly prefer filling existing space
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // are mostly full (low mean residual) or many bins are already open
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let pressure = mean_r / cap; // high = open bins have room
        let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        let mut new_score = 35.0 * pressure + 20.0 * open_pressure;
        // early in stream, opening bins is cheaper
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_score += 10.0 * (1.0 - t);
        // if item is large relative to mean residual, new bin is fine
        new_score -= 5.0 * (item_size as f64 / cap);
        // if no open bin fits at all, opening is mandatory-ish
        if fitting_bins_count == 0 {
            new_score -= 50.0;
        }
        score = new_score;
    } else {
        // penalize using a bin whose residual is far above item (wasteful fit)
        let slack = (bin_residual - item_size) as f64;
        score += 4.0 * (slack / cap) * (slack / cap);
        // slight preference to keep some bins emptier for future large items
        score += 2.0 * (bin_residual as f64 / cap) * (mean_residual / cap.max(1.0));
    }

    // mild global regularization
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * norm_pr * (40.0 + 60.0 * p2) * (1.0 - 0.5 * p3);

    // Reward tight fits more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 0.6 * gap * (0.5 + progress);
        } else {
            score -= 8.0 * (1.0 + progress);
        }
    } else {
        // last item: prefer filling existing bins as much as possible
        score -= 15.0 * tightness;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 + 25.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    // Deviation from mean residual: prefer bins near/below mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate should be penalized unless residuals are very fragmented
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress) - 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (multiples of common item sizes) are less penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: leftover too small for any plausible item (1..=100,
    // but tiny leftovers under ~10 are nearly dead) get a superlinear penalty.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class: post_residual divisible by 25 or 50 keeps usable chunks.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual,
    // penalize if next item is large and this bin would be nearly full.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= (next_item_size as f64) * 0.35;
        } else {
            // next item won't fit here; leftover waste matters more late in stream
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += post * (0.15 + 0.25 * progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so
    // it only wins when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, waste in fresh bins is amortized less; keep
        // new bins slightly cheaper early when many items remain.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        score -= (remaining / (total_items.max(1) as f64)) * 10.0;
    }

    // Prefer bins below mean residual (they will otherwise strand space).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Modulo threshold on item size: awkward sizes (prime-ish, e.g. 37, 41)
    // are harder to combine; slight preference to pack them tightly.
    if item_size % 10 != 0 && item_size % 5 != 0 {
        score -= post_residual as f64 * 0.05;
    }

    // Fraction-of-capacity harmonic band: leftover in [0, cap/8) is dead,
    // [cap/8, cap/4) is awkward, larger is reusable.
    if post > 0.0 && post < cap / 8.0 {
        score += 8.0;
    } else if post < cap / 4.0 {
        score += 3.0;
    }

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are pure waste. Penalize them super-linearly.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powf(2.0) * 3.0;
    }

    // Nonlinear "wasted fraction" penalty: quadratic in how full the bin gets.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when open_bins_count is high.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can still host the
    // next item (keeps chains of placements alive); penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect two-item packing: post_residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Mean-residual coupling: bins deviating far below mean residual are
    // nearly closed; slight penalty for scattering small leftovers.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.05;
    }

    // Early stream: be more tolerant of opening bins (exploration);
    // late stream: tighten to squeeze everything into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    // New-bin candidate: an empty bin gets a neutral-ish but non-trivial
    // baseline so it only wins when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 50.0;

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves further residual
            let nxt_post = post_residual - next_item_size;
            score -= 40.0 * (1.0 - nxt_post as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a residual close to but smaller than next item
            let gap = next_item_size - post_residual;
            if gap <= 20 {
                score += 25.0 * (1.0 - gap as f64 / 20.0);
            }
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers (dead space).
    score += 0.8 * (post_residual as f64 - mean_residual).abs();

    // Penalize large post_residual relative to capacity (unusable space).
    score += 0.3 * post_residual as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins unless fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if no existing bin fits well, allow opening new bin.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
    }

    // Early stream: be slightly more willing to open bins for good structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    // Many open bins: discourage spreading, prefer consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
    score -= 20.0 * open_pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Time horizon: early on, be picky (penalize loose fits); late, just fill anything
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global residual balance: prefer bins whose residual deviates favorably from mean
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score -= 5.0 * dev;

    // Mild bonus for using existing bins vs opening new ones
    if bin_residual < bin_capacity {
        score -= 5.0;
    } else {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * prn * prn);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (fewer chances to fill it)
    let coupling = prn * prn * (3.0 * progress - 1.5) * cap;
    score += coupling;

    // Reward tight fits smoothly (item nearly fills bin)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Prefer spreading across many open bins slightly; penalize relative residual vs mean
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: mild penalty so it's only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket into capacity fractions (eighths).
    let class = post_residual / (bin_capacity / 8).max(1);
    score += match class {
        0 => -30.0, // near-perfect fill
        1 => -15.0,
        2 => -5.0,
        3 => 0.0,
        4 => 3.0,
        5 => 6.0,
        6 => 10.0,
        _ => 14.0,
    } as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (1..=10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Pairing bonus: does next item fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (20.0 - slack.min(20) as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default unless open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - cap).abs() / cap;
        score += 18.0 - 25.0 * fragmentation;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0; // open bins can't hold next item; fresh bin useful
        }
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Penalize leaving residuals in awkward modular classes (mod 10 dead zones).
    let m = post_residual % 10;
    if m == 1 || m == 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum item size (1..=2) are pure waste; gaps just above
    // the next item's size are wasted opportunities.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else if post_residual < 3 {
        // Tiny dead space, essentially unusable: penalize hard.
        score += 60.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap too small for the lookahead item: dead space risk.
        score += 25.0 + pr * 0.5;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Gap exactly matches the next item: excellent two-item packing.
        score -= 20.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the residual (low post_residual relative to bin_residual).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // encourage consolidation by penalizing the new-bin candidate.
    if bin_residual == bin_capacity {
        // New empty bin: only attractive when no open bin fits well.
        score += 50.0
            + 8.0 * open_bins_count as f64
            - (if fitting_bins_count == 0 { 60.0 } else { 0.0 });
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward using it to avoid opening a new bin.
        score -= 15.0;
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Slight preference for bins below mean residual (consolidation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but with a twist:
    // exact match with next item is ideal (residual becomes fully usable).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        if post_residual == next_item_size {
            // Perfect 2-chain: this bin will be exactly filled by next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here; reward proportional slack match.
            let slack = post - next;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize the unusable gap.
            let dead = next - post;
            score += 0.8 * dead;
        }

        // Coupling: if next item is large and this bin leaves a big residual,
        // that residual is likely wasted forever.
        if next >= 50.0 && post < next {
            score += 0.5 * (next - post);
        }
    } else {
        // Last item: pure tightness.
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already tight; wasting their remaining space is costly.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        if post_f < mean_residual {
            score -= 0.3 * (mean_residual - post_f);
        } else {
            score += 0.15 * (post_f - mean_residual);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // the item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral anchor; make it slightly unattractive so good fits win,
        // but attractive when all open fits are bad.
        score += 10.0;
        // If the item is big (>= half capacity), a fresh bin keeps flexibility.
        if item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins with high mean residual => prefer consolidation.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 8.0;
        }
    } else {
        // Slight preference for filling existing bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * (1.0 - progress);
    }

    // Penalize leaving residuals in the awkward 1..=9 band (nearly dead space).
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: make it attractive only when the item fits poorly everywhere
    // (fit_ratio low means lots of waste) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 20.0 * (1.0 - fit_ratio) - 10.0 * progress;
        if fitting_bins_count == 1 {
            score += 30.0; // discourage abandoning the sole fitting bin
        }
    }

    // Mild pressure to consolidate: many open bins with large mean residual
    // favors packing into existing space.
    if open_bins_count > 2 && bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
    }

    // Prefer bins below mean residual (tighter bins get emptied first).
    if bin_residual != bin_capacity {
        score += 0.03 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = x * x * (3.0 - 2.0 * x); // smoothstep shaping of dead space
    let mut score = post * (1.0 + base * (0.5 + progress));

    // Tight fits rewarded
    score -= (item_size as f64 / cap) * 8.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: penalize wasting space needed by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 4.0 * (nx / cap);
        } else {
            score += 6.0 * ((nx - post) / cap);
        }
    }

    // New-bin candidate: mildly penalized unless post_residual would be large
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * (1.0 - progress);
    }

    // Spread pressure via mean residual
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does the leftover fall into?
    let band = (post_residual / (bin_capacity / 10).max(1)) as f64; // 0..=10 deciles
    score += band * 1.5;

    // Exact-fit reward: post residual is a perfect divisor-fraction of capacity
    if post_residual == 0 {
        score -= 40.0;
    } else if bin_capacity % post_residual == 0 {
        score -= 12.0; // clean harmonic leftover, reusable in equal chunks
    } else if post_residual < 10 {
        score += 25.0; // dead space penalty (unusable sliver)
    }

    // Modulo-10 class coupling between item and next item
    let item_class = item_size % 10;
    let next_class = next_item_size % 10;
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits here: strong reward, scaled by class harmony
        let harmony = if item_class == next_class { 6.0 } else { 0.0 };
        score -= 18.0 + harmony;
    } else if next_item_size > 0 {
        // lookahead won't fit: penalize slightly unless this bin was last chance
        score += 4.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_residual - item_size) as f64;
        // prefer new bin only if placing here would strand a huge remainder
        if waste > 0.45 * cap {
            score -= 20.0;
        } else {
            score += 15.0 + 0.05 * open_bins_count as f64;
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / cap);

    // Mean-residual pull: favor bins near the mean (keeps distribution balanced)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize unusable gaps quadratically.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward when the leftover can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover exists but cannot host next item: mild penalty
        score += 6.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening yet another one.
    // New-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits well (this is the only fitting bin), allow opening.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Early stream: opening bins cheaply is fine.
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for bins whose residual is already small (tight packing).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small to ever hold a future item.
        if post_residual < 10 {
            score += 200.0;
        }
        // Aggressive 2-step lookahead: reward if the next item fits perfectly
        // into the post-residual (chained exact packing).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 900.0;
            } else if next_item_size < post_residual {
                // Reward proportionally to how well the next item fills the remainder.
                let fill = next_item_size as f64 / post_residual as f64;
                score -= 150.0 * fill;
            } else {
                // Next item cannot fit here: mild penalty for leaving a large gap
                // that won't be used by the lookahead item.
                score += 30.0;
            }
        } else {
            // Last item in the stream: strongly prefer minimizing final residual.
            score -= 500.0;
        }
    }

    // Prefer bins with residuals below the mean (tighter bins get packed first),
    // keeping larger residuals available for larger future items.
    let resid_f = bin_residual as f64;
    score += 0.5 * (resid_f - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - resid_f).max(0.0);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it if all existing fits would waste a lot of space.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9;
        if fitting_bins_count == 0 {
            // No open bin fits: opening a new bin is necessary.
            score -= 500.0;
        } else if next_item_size > 0 {
            // Favor a fresh bin if the next item is large and would fit a new
            // empty bin exactly (reserve capacity strategy).
            if next_item_size == bin_capacity {
                score -= 800.0;
            }
        }
    }

    // Early in the stream, slightly discourage spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that cannot host the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual >= next_item_size {
            score -= 8.0; // bin remains useful for the next item
        }
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate proportionally to how well open bins could absorb the item,
    // scaled by global slack (mean residual) and stream horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: penalize more when mean residual across open bins is ample.
        score += 35.0 + mean_residual * 0.8 + open_bins_count as f64 * 1.5;
        // Early in the stream, opening bins is cheaper; late, keep consolidating.
        score += (1.0 - progress) * -15.0;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0; // fresh bin won't fit next item either
        }
        if mean_residual < item_size as f64 {
            score -= 20.0; // open bins nearly exhausted -> new bin is fine
        }
    } else {
        // Slight preference for bins whose residual is large but not wasteful.
        score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;
        // Prefer bins with residual close to mean (regularity) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: normalized post-residual (dead space), quadratic penalty
    let x = pr / cap;
    let mut score = x * x * cap + pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, small residuals matter less; late, they hurt more.
    let coupling = x * (1.0 - x) * (0.25 + 1.5 * progress * (1.0 - progress) * 4.0);
    score -= coupling * cap;

    // Reward near-perfect fills more aggressively as stream progresses
    let fill_quality = 1.0 - x;
    score -= fill_quality * fill_quality * (10.0 + 30.0 * progress);

    // Last-chance bin: strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits exactly in the resulting residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let nxn = nx / cap;
            score -= (1.0 - (pr - nx) / cap) * 20.0 * (1.0 + nxn);
        } else {
            // next item won't fit here: penalize slightly if residual becomes tiny waste
            score += (1.0 - x) * 5.0;
        }
    }

    // Prefer bins with residual close to item size (tight fit) via smooth term
    let tight = 1.0 - ((bin_residual as f64 - item_size as f64) / cap);
    score -= tight * tight * 8.0;

    // Mild penalty when many bins are open and this would leave large waste
    score += (open_bins_count as f64).ln().max(0.0) * x * 3.0;

    // Mean-residual alignment: prefer bins near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * 6.0;

    // New-bin candidate: keep neutral-ish baseline but discourage early opening
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 20.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when an existing one is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        return -1_000_000.0;
    }

    // Harmonic class of the leftover space: integer-division thresholds.
    // Class 0: tiny dead space (1..=5)  -> nearly wasted, heavy penalty
    // Class 1: small (6..=15)           -> mostly wasted
    // Class 2: medium (16..=35)         -> partially usable
    // Class 3: large (36..=100)         -> still useful
    let cls = if post_residual <= 5 { 0 } else if post_residual <= 15 { 1 } else if post_residual <= 35 { 2 } else { 3 };
    score += match cls {
        0 => 400.0,
        1 => 120.0,
        2 => 0.0,
        _ => -60.0,
    };

    // Modulo-arithmetic coupling: leftover divisible by common item sizes
    // (10, 20, 25, 50) is more likely to be filled later -> reward.
    if post_residual % 10 == 0 { score -= 25.0; }
    if post_residual % 25 == 0 { score -= 15.0; }
    if post_residual % 50 == 0 { score -= 15.0; }

    // Lookahead: if the next item fits exactly into the leftover, big reward;
    // if it fits at all, moderate reward; if not, mild penalty for hoarding space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate (empty bin): must be penalized unless everything else is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain
        // and few bins are open (early stream, plenty of room to plan).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 250.0 + 200.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual {
            new_bin_cost += 100.0; // shouldn't happen for empty bin, safety
        }
        // If existing bins would leave horrible dead space, allow the new bin.
        if cls <= 1 && fitting_bins_count == 1 {
            new_bin_cost -= 200.0;
        }
        score += new_bin_cost;
    }

    // Mild pressure to consolidate: prefer bins whose residual is below the mean
    // (filling fuller bins first keeps many partially-filled bins available).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for larger items into this bin (big items in tight slots).
    score -= 0.2 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are essentially unusable
    // for typical items; penalize them hard, scaled by how tight the fit was.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fill: reward strongly.
        score -= 30.0;
    } else {
        // Larger gaps are reusable: mild reward proportional to reusability.
        score -= (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Reward tight fits (small post_residual) but only when not dead space.
    score -= (bin_residual - post_residual) as f64 * 0.05;

    // If this bin is the last chance before opening a new bin, prefer using it
    // (avoid bin proliferation) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual >= 10 {
            score -= 8.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (use up the tighter bins first, keep slack bins flexible).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // New-bin candidate handling: an empty bin has high residual; make it a
    // mediocre default so it wins only when open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If no open bin can fit the item, the new bin must win.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the NEXT item fits snugly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 200.0; // chain perfect fit
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to next item: penalize proportionally.
        score += 1.5 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that waste large residuals.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when current
    // bins would leave large dead space; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item is large, a fresh bin has good future utility.
        if next_item_size > 0 && next_item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: squash small post_residuals superlinearly.
    if post_residual <= 10 {
        score -= 30.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual < 20 {
        score -= 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Dead-space penalty: residuals that can't hold typical items are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for lookahead item: penalize wasted space.
        score += 8.0;
    }

    // Prefer bins with smaller residuals among comparable fits (best-fit coupling).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // Penalize spreading across too many open bins; encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Mean-residual coupling: bins below mean residual are more "complete".
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in the stream, be more open to opening new bins;
    // late in the stream, pack tightly to close out cleanly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New empty bin candidate: make it attractive only when it's a clean,
    // large item placement or when consolidation is bad; otherwise discourage.
    if bin_residual == bin_capacity {
        let clean_fit = item_size as f64 / bin_capacity as f64;
        if clean_fit > 0.7 {
            score -= 20.0 * clean_fit;
        } else {
            score += 18.0;
        }
        // Late stream: discourage new bins unless item is huge.
        if progress > 0.8 && clean_fit <= 0.8 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let fit_frac = item_size as f64 / cap;

    let mut score = pr;

    // smooth non-linear coupling of post-residual with stream progress
    let t = progress * progress;
    score += 30.0 * norm_pr * norm_pr * (0.5 + t);
    score -= 20.0 * fit_frac * (1.0 - progress);

    // penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * gap * gap;
        let use_next = if pr >= next_item_size as f64 { next_item_size as f64 / cap } else { 0.0 };
        score -= 12.0 * use_next * (1.0 - t);
    } else {
        score -= 10.0 * norm_pr;
    }

    // last-chance fitting bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * fit_frac;
    }

    // pressure from open bins vs mean residual
    let pressure = (open_bins_count as f64).ln() * (mean_residual / cap);
    score += 8.0 * pressure * norm_pr;

    // new-bin candidate: prefer it only when item is large and residuals are tight
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * (1.0 - fit_frac) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
