    } else if post_residual <= 10 {
        score -= 300.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small residue classes (1..=9) are "dead space" unless the next item matches.
    let residue_class = post_residual % 10;
    if residue_class != 0 {
        // Dead space penalty grows for awkward classes (7,8,9 are hard to fill).
        let awkward = match residue_class { 7 | 8 | 9 => 3.0, 4 | 5 | 6 => 1.5, _ => 1.0 };
        score += 20.0 * awkward;
