        if slack == 0.0 {
            score -= 500.0;
        } else if slack <= 10 {
            score -= 150.0;
        } else {
            score -= 50.0 / slack;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's remainder: penalize proportionally.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are badly
        // fragmented (high mean residual relative to item size) or no bin fits well.
        let fragmentation = mean_residual / bin_capacity as f64;
        if post_residual == bin_capacity {
            // This IS the new-bin call: score it as its own cost (full capacity unused).
            score = bin_capacity as f64;
            if fitting_bins_count == 0 {
                score -= 400.0; // must open a bin anyway
            } else if fragmentation > 0.5 {
                score -= 50.0; // open bins are fragmented; fresh bin competitive
            }
        }
    } else {
        // Existing bin: reward bins with residual below the item's integer-division
        // threshold, i.e., bins that will be "closed out" by this placement.
        let k = bin_residual / item_size.max(1);
        if k == 1 {
            score -= 100.0; // this placement nearly fills the bin
        }
        // Prefer filling bins with smaller residuals first (best-fit bias).
        score += 0.3 * (bin_residual as f64 - post_residual as f64).signum().max(0.0) * 0.0;
        score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Late in the stream, consolidate: penalize keeping many open bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.7 {
            score += 0.5 * open_bins_count as f64;
        }
    }

    // Slight preference for bins below mean residual (balance consolidation).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Strict dead-space avoidance ----
    // Items below the minimum stream size create "unusable" gaps.
    // Penalize any post_residual that is too small to ever be refilled
    // (assume worst-case min item size of 1, but weight small gaps heavily).
    let dead_threshold: f64 = 12.0; // gaps smaller than this are likely dead space
    if (post_residual as f64) < dead_threshold {
        // Harsh penalty proportional to how "wasted" the gap is relative to capacity
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // ---- Reward tight fits (small post_residual, but still usable) ----
    // Perfect/near-perfect fills should be strongly preferred.
    if post_residual == 0 {
        score -= 50.0; // perfect fill: best possible outcome
    } else if (post_residual as f64) < dead_threshold {
        // already penalized above, but also subtract a bonus for being very tight
        // so tight-but-not-dead fits still rank better than loose fits
        score -= 20.0;
    }

    // ---- Usable-gap matching: reward bins whose leftover fits the lookahead ----
    if next_item_size > 0 && post_residual >= next_item_size {
        // The next item can exactly fill this bin's residual — excellent chaining
        if post_residual == next_item_size {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover is too small for the next item: mild penalty (potential dead space)
        score += 5.0;
    }

    // ---- Open bins pressure ----
    // When many bins are open, prefer consolidating into existing ones
    // rather than opening new bins (which increases open_bins_count).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += open_pressure * 4.0;

    // ---- New-bin candidate handling ----
    // bin_residual == bin_capacity identifies the fresh empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive: only attractive when existing bins
        // would create large dead space or when few bins fit the item.
        let last_chance = fitting_bins_count == 1 && bin_residual > item_size;
        // If this is the ONLY fitting bin among open bins... but wait, the
        // new bin always fits, so fitting_bins_count for real bins is what matters.
        // Penalize the new bin moderately; it should win only when alternatives are bad.
        score += 25.0;

        // Bonus (score reduction) if the current item would leave a huge unusable
        // gap in every existing bin — approximated via mean_residual being large
        // while the item barely fits nowhere nicely.
        if last_chance {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftover content
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress > 0.9 {
            score += 10.0;
        }
    }

    // ---- Last-chance bin bonus ----
    // If this is the only open bin that can fit the item, using it avoids
    // opening a new bin — strongly reward it.
    if bin_residual != bin_capacity && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // ---- Mean residual coupling ----
    // Bins with residual far below the mean are "almost full": finishing them
    // is good. Bins with residual far above the mean have room; placing here
    // is neutral-to-good if the fit is tight.
    let residual_diff = mean_residual - post_residual as f64;
    score += residual_diff * 0.05;

    // ---- Slight preference for filling fuller bins first (best-fit core) ----
    // Already captured by post_residual base term, but add a mild non-linear
    // nudge: squaring emphasizes differences among tight fits.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap == 0 {
            score -= 25.0;
        } else {
            // penalize large gap between post residual and next item
            let gap_f = gap as f64;
            score += 0.08 * gap_f * gap_f / (bin_capacity as f64);
            // if next item fits perfectly after this placement, strong bonus
            if next_item_size <= post_residual {
                let after = post_residual - next_item_size;
                if after <= 5 {
                    score -= 15.0;
                }
            }
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins)
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fit
    if bin_residual == bin_capacity {
        let waste_threshold = (item_size as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // penalize opening new bin when existing bins fit, more so early in stream
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 20.0 + 15.0 * (1.0 - progress);
            // but if best existing fit would leave big dead space, soften penalty
            let min_waste = if next_item_size > 0 {
                (post_residual as f64 - next_item_size as f64).abs()
            } else {
                post_residual as f64
            };
            if min_waste > waste_threshold {
                score -= 25.0;
            }
        }
    }

    // Mild penalty for very small unusable leftovers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: penalize leaving residual that fails to fit next item
    // when the next item could otherwise pair with this residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            // residual just fits next item nicely — reward
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space relative to lookahead — penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: empty bin gets base cost of opening.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        // If many bins are open with large mean residual, prefer consolidating.
        score += (open_bins_count as f64).sqrt() * 3.0;
        score += mean_residual * 0.2;
    } else {
        // Using existing bins: mild reward scaled by scarcity of fitting bins.
        if fitting_bins_count > 0 {
            score -= 5.0 / fitting_bins_count as f64;
        }
        // Prefer filling bins with smaller residuals first (best-fit bias).
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Time horizon: early on, be picky about waste; late, just fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual scaled non-linearly (dead space hurts quadratically).
    let mut score = post + (post * post) / cap;

    // Smooth interaction: dead space becomes more tolerable as stream progresses.
    let progress_relief = progress * (post * post) / (2.0 * cap);
    score -= progress_relief;

    // Tight-fit reward: near-zero post residual strongly favored, smoothly.
    let tightness = 1.0 - (post / cap).min(1.0);
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward if next item fits into post residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = if post >= nx { 1.0 } else { 0.0 };
        let slack = ((post - nx).abs()) / cap;
        score -= 8.0 * fits * (1.0 - slack) - 3.0 * (1.0 - fits) * (1.0 - slack);
    }

    // Last-chance bonus: only fitting bin -> strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Mild competition pressure: more alternatives, slightly less urgency.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean residual coupling: prefer bins whose post residual sits below mean
    // (consolidating waste), penalize bins that end far above mean.
    score += 0.15 * (post - mean_residual).abs() * (1.0 - 0.5 * progress);

    // New-bin candidate penalty: empty bin must only win when placement here
    // would be terrible; make its score high but smoothly reducible by item size.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 30.0 + 20.0 * (1.0 - fill) + 10.0 * progress * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap_u32 = bin_capacity;
    let quarter = cap_u32 / 4;
    let half = cap_u32 / 2;
    let eighth = cap_u32 / 8;

    // Dead-space classes: residuals that few item sizes can fill are penalized.
    let class = post_residual % quarter;
    score += (class as f64) * 0.35;

    // Sweet-spot rewards: post_residual in {0, small, half} harmonics are reusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= eighth {
        score -= 25.0; // nearly full, minimal waste
    } else if post_residual == half {
        score -= 20.0; // half harmonic: next half-item fits exactly
    }

    // Integer-division threshold: large dead space is bad unless a known next item fits.
    if post_residual > half {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0; // lookahead fits: keep this bin attractive
        } else {
            score += 8.0; // large unusable gap
        }
    }

    // Exact lookahead fill bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < cap_u32 {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open bins when fits are poor,
    // but allow it when residuals across open bins are already fragmented.
    if bin_residual == cap_u32 {
        score = 55.0 + (open_bins_count as f64).sqrt() * 6.0
            - (mean_residual / cap_u32 as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= half {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Late-stream tightening: consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    // Tie-break: prefer tighter existing bins (smaller residual) when scores equalize.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual in (0, 10) is wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that cannot fit the smallest plausible item (1..=100 range).
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward residual that exactly fits the next item (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.3;
    }

    // Mild progression scaling: tighten packing as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (tighter bins first keeps loose bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong bonus; near match: partial bonus.
        if gap == 0.0 {
            score -= 60.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to leftover dead space.
            score += 0.15 * gap;
        }
    } else {
        // Last item: leftover waste is pure loss.
        score += 0.5 * post_residual as f64;
    }

    // Prefer tight fits relative to mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly discourage opening a new bin instead.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open candidates exist.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / item_size.max(1) as f64);
        score += 8.0 + 2.0 * pressure;
        // Late in the stream, waste matters more; avoid new bins unless necessary.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Slight preference for leaving large usable residuals (>= 10) over tiny slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 6.0 * (post_residual as f64 / next_item_size as f64).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
    score += 0.05 * crowding * (1.0 - progress);

    // Penalize bins far from the mean residual (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight bias toward fuller bins (smaller residual).
    score += 0.1 * bin_residual as f64 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > (bin_capacity as f64 - item_size as f64);
        score += if bad_fit { 5.0 } else { 20.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear penalty on small post-residuals (dead space), smoothed polynomial
    score -= 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item * (1.0 - norm_item);

    // Smooth interaction: prefer tight fits as stream progresses
    score -= 12.0 * progress * (1.0 - norm_pr).powi(3);

    // Reward if next item fits into post_residual (chaining bonus), smooth gate
    let fits_next = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
    let slack = if next_item_size > 0 { (pr - next_item_size as f64) / cap } else { 0.0 };
    score -= 10.0 * fits_next * (1.0 - slack * slack) * (0.5 + 0.5 * progress);

    // Penalize when post_residual is small but nonzero and cannot fit next item
    let dead = if next_item_size > 0 && pr > 0 && pr < next_item_size { 1.0 } else { 0.0 };
    score += 15.0 * dead * (1.0 - pr / cap) * (1.0 - progress);

    // Last-chance bin pressure: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating open bins, modulated by mean residual
    score += 0.6 * (open_bins_count as f64).powf(0.5) * (1.0 - (mean_residual / cap).min(1.0));

    // New-bin candidate handling: neutral base, opened only when open bins score badly
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress + 8.0 * norm_next;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes on post_residual: exact fill is divine, small dead space is penalized super-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always best
    } else {
        // classify dead space by harmonic residue class (mod 10 buckets)
        let class = (post_residual % 10) as f64;
        let quot = (post_residual / 10) as f64;
        // dead space in low residue classes (1..5) is nearly unusable -> extra penalty
        if post_residual <= 5 {
            score += 40.0 + (5.0 - post_residual as f64) * 8.0;
        } else if post_residual <= 10 {
            score += 12.0 + class * 0.5;
        } else {
            // larger residuals are workable; mild reward scaled by quotient
            score -= quot * 0.8;
        }
    }

    // Coupling with lookahead: if next item exactly fits post_residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits into the would-be residual: mild reward proportional to tightness
        score -= (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > post_residual {
        // next item cannot use the residual: penalize proportionally to wasted potential
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item is large
    // relative to capacity and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // base cost of a fresh bin, discounted for large items
        score += 60.0 - fill_frac * 55.0;
        // if other fitting bins exist, make new bin less attractive
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // late in the stream, avoid needless bin proliferation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Mean-residual coupling: when open bins are generally empty, prefer reusing them.
    let mean_frac = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= mean_frac * 5.0;
    }

    // Slight preference for bins with lower current residual (better fit) via tie-break.
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post residual relative to item).
    if post_residual == 0 {
        score -= 80.0; // perfect fill
    } else {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 40.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 6.0;

    // New-bin candidate: only attractive if every open bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let gap_if_used_elsewhere = post_residual as f64; // residual of this new bin after placement
        let bad_alt = fitting_bins_count == 0
            || (post_residual as f64) < 10.0 && fitting_bins_count == 1 && false;
        if bad_alt {
            score -= 70.0;
        } else {
            score += 45.0 + open_bins_count as f64 * 2.0;
        }
        let _ = gap_if_used_elsewhere;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Late in stream: consolidate, avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward low post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // 2-step lookahead: perfect if post_residual equals next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff / 10.0);
        // Penalize wasted residual that next item cannot use.
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: just minimize residual.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are precious.
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 25.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when fitting bins exist, unless residual is very fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open new bin when existing residuals are small (fragmented) or stream is young.
        score += 55.0 - 45.0 * fragmentation - 20.0 * progress;
        if fitting_bins_count > 0 && post_residual as f64 > next_item_size as f64 {
            score += 10.0; // extra deterrent when a decent fit exists
        }
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Slight early-stream bias toward filling bins fully.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: reward filling the bin well.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Penalize dead space non-linearly: residuals that are too small for
    // typical future items (<= 10) are almost pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 8.0 * (1.0 - fill_ratio);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // prefer it when existing bins fit poorly (large post_residual there).
    let is_new_bin = bin_residual == bin_capacity && item_size == 0;
    let is_empty_candidate = bin_residual == bin_capacity;
    if is_empty_candidate {
        // Base cost of opening a new bin, softened late in the stream or
        // when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 70.0;
        new_bin_score -= 20.0 * progress;
        new_bin_score -= (open_bins_count as f64).min(10.0);
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size > bin_capacity / 2 {
            new_bin_score -= 15.0;
        }
        // If mean residual across open bins is small, opening is wasteful.
        new_bin_score += (mean_residual - 30.0).max(0.0);
        score = new_bin_score;
        if is_new_bin {
            score += 1.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best fit flavor).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 30.0 * tightness;

        // Mild preference for more-utilized bins when many bins are open
        // (consolidation pressure).
        score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.5 * progress) + 0.8 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress) * 2.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) / cap * (1.5 + progress);
        } else {
            score -= (pr - nxt).min(pr) / cap * 0.5;
        }
    }

    // Last-chance bin bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.8 * progress;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral-to-slightly-high baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score += 1.0 + 0.5 * progress - 0.3 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
