pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 200.0; // unusable dead space penalty (item sizes >= 1, small gaps often dead)
    } else {
        // Reward tight fits: post_residual small relative to residual.
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 60.0 * tightness * tightness;
    }

    // Penalize leaving a gap that next item cannot use (coupled lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 + 0.5 * next_item_size as f64;
        } else {
            // Reward if next item exactly-ish fits the remaining gap.
            let gap_diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= 20.0 / (1.0 + gap_diff);
        }
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are crowded.
        score += 30.0 + 8.0 * open_bins_count as f64 + 0.3 * mean_residual;
    } else {
        // Reusing existing bins is better when open_bins_count is high.
        score -= 2.0 * open_bins_count as f64;
        // Slight bonus for bins below mean residual (consolidating slack).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild stream-position adaptation: early on, prefer flexibility (larger post_residual ok);
    // later, tighten packing aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 2.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead item
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Reward tight fits relative to mean residual
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 1.5;
    } else {
        score += (pr - mean_residual) * 1.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        let decent = if next_item_size > 0 && post_residual == next_item_size { 0.0 } else { 50.0 };
        score += 40.0 + decent + open_bins_count as f64 * 5.0;
    }

    // Progress-based tightening: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (1.0 - pr / bin_capacity as f64);

    // Avoid leaving tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Wasted residual that the next item cannot use: penalize proportionally.
            score += 0.25 * post_residual as f64 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly reward using it
    // (avoids opening a new bin for a poor fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a bin should only win when the current fit is poor
    // (item nearly fills a fresh bin or existing fits are very loose).
    if bin_residual == bin_capacity {
        score += 25.0 - 0.4 * item_size as f64;
        if item_size >= 70 {
            score -= 30.0; // large item: fresh bin is efficient
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    score += 0.05 * (open_bins_count as f64).powf(1.3);
    score -= 0.10 * mean_residual;

    // Time horizon: early in the stream, be conservative (penalize near-full fills
    // that strand residual); late in the stream, exploit tight fits harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (15.0 * progress) * fit_ratio;
    score += (1.0 - progress) * 0.08 * post_residual as f64;

    // Dead-space penalty: residual that is very small but nonzero is hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post-residual, with smooth non-linear coupling to stream progress
    let mut score = pr * (1.0 + 0.6 * t * pr_norm);

    // Penalize large post-residuals more as stream progresses (dead space matters later)
    score += 12.0 * t * pr_norm * pr_norm * cap;

    // Reward tight fits (small post-residual) with a smooth quadratic bonus
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * item_norm * cap * (0.5 + 0.5 * t);

    // Lookahead: reward if next item fits into post-residual (smooth coupling)
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let fit = if next_item_size <= post_residual { 1.0 } else { 0.0 };
        let smooth = fit * (1.0 - (pr_norm - next_norm).abs());
        score -= 8.0 * smooth * (0.4 + 0.6 * t);
    }

    // Last-chance bin: strong smooth reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - pr_norm) * (1.0 + t);
    }

    // Mean residual divergence: prefer bins near mean residual (smooth Gaussian-like)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap * (1.0 - t);

    // Slight penalty for spreading across too many bins late in stream
    score += 0.5 * open_bins_count as f64 * t * pr_norm;

    // New-bin candidate: mild penalty so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * t) + item_norm * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "useful"
    // residue classes (multiples of small divisors of capacity) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement.
    let fill = 1.0 - pr / cap;

    // Reward high fill non-linearly (best-fit with curvature).
    score -= 12.0 * fill * fill;

    // Harmonic class bonus: post_residual divisible by 10 or 25 is a
    // "clean" residual likely to be exactly filled by future items.
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }
    // Penalize awkward dead zones: residual in (0,10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Penalize mid-range awkward residuals via integer-division thresholds.
    if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - pair_waste / cap);
            // Harmonic check on the double-pairing leftover.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here; mild penalty scaled by how far off.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no good fit exists (mean residual low means open
    // bins are already tight).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 5.0;
        // If existing bins are tight (low mean residual), opening is fine.
        score -= 10.0 * (1.0 - mean_residual / cap);
        // Early in stream, prefer consolidating; later, allow spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Penalize many open bins with slack (encourage closing bins out).
    score += 0.5 * (open_bins_count as f64).sqrt() * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

