    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // with few open bins, opening a new bin is less costly.
    let pressure = (open_bins_count as f64).ln().max(0.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted when few bins are open
        // or when this bin would fit the next item well too.
        score = 55.0 + 8.0 * pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            if next_item_size <= post_residual {
                score -= 10.0; // next item also fits this fresh bin
            }
        }
        if next_item_size > 0 && next_item_size > post_residual.max(0) && post_residual < next_item_size && post_residual > 0 {
            score += 15.0; // fresh bin would strand the next item elsewhere
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Existing bin: mild penalty scaled by how much this placement
        // diverges residual from the mean (keep residuals homogeneous).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev * pressure;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into the post-residual: strong reward, scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack.min(50.0);
    }
    // Next item does NOT fit: penalize proportionally to wasted lookahead space.
    else if next_item_size > 0 {
        let overflow = (next_item_size - post_residual) as f64;
        score += overflow * 2.0;
    }

    // Reward tight fits relative to bin capacity (small dead space fraction).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize creating residual far below the mean residual (fragmenting space).
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += (-dev) * 0.5;
    } else {
        score -= dev * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Early in the stream, be more willing to open fresh bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        // Mild penalty per open bin to discourage bin proliferation.
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post-residual, superlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead-space penalty: residual that likely cannot host future items
    // (items range 1..100, but small residuals under ~10 are near-waste).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * gap / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new-bin opening for a marginal item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes existing capacity.
    if bin_residual == bin_capacity {
        // Base penalty grows with number of open bins and mean residual.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 0.3 * mean_residual;
        // Exception: if current item is large and no open bin fits well,
        // opening a fresh bin can be fine — reduce penalty when item is big.
        if item_size >= 60 {
            score -= 25.0;
        }
        // Late in stream, consolidating matters more: keep penalty high.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Reward using already-open bins slightly more as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balance load),
    // penalizing extremes that strand capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled smoothly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, avoid creating tiny dead spaces; later, tighten more aggressively.
    let progress_coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * fit_ratio * (1.0 - progress);
    score += 6.0 * progress_coupling;

    // Reward bins whose residual can host the next item (smooth lookahead term).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 4.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use, growing with progress.
        score += 2.0 * progress * norm_pr;
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely better
    // (i.e., few fitting bins and existing residuals are large).
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        let pressure = (fitting_bins_count as f64) / (open_bins_count.max(1) as f64);
        let penalty = 18.0 * (1.0 - mean_norm) * (1.0 + pressure) + 8.0 * (1.0 - progress);
        score += penalty;
        // Smooth reward for a fresh bin if the item is large and fits poorly elsewhere.
        score -= 3.0 * fit_ratio * fit_ratio * (1.0 + progress);
    }

    // Mild consolidation pressure: prefer bins below mean residual (filling fuller bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev.abs();

    // Small preference for bins with residual close to item size (smooth quadratic).
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 2.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual * 4) / bin_capacity; // integer division class 0..3
    let eighth = (post_residual * 8) / bin_capacity;

    // Reward tight fits: post_residual in lowest classes gets strong discounts.
    match quarter {
        0 => score -= 40.0,                       // nearly perfect fit
        1 => score -= 18.0,                       // usable remainder
        2 => score -= 6.0,                        // mediocre
        _ => score += 10.0,                       // large dead space penalty
    }

    // Fine-grained harmonic bonus on eighths: odd classes (non-aligned residuals)
    // are less likely to be filled by future items; penalize them slightly.
    if eighth % 2 == 1 {
        score += 4.0;
    }

    // Residual exactly matching common small-item sizes is valuable.
    let r = post_residual;
    if r >= 10 && r <= 25 {
        score -= 12.0; // likely fillable by a typical small item
    } else if r > 25 && r < 40 {
        score -= 3.0;
    } else if r >= 40 && r < 60 {
        score += 6.0;  // awkward middle dead zone
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if next_item_size <= r {
            let waste = (r - next_item_size) as f64;
            score -= 15.0 - waste * 0.3;
        } else {
            // next item won't fit here regardless; slight penalty for hoarding space
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Baseline competitiveness: score equals a mediocre residual.
        score = cap * 0.5;
        // Opening new bins is costly when few items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
        // If many bins already open and this bin is a last chance, discourage new bin.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // If next item is large and current item small, a fresh bin may be attractive.
        if next_item_size > item_size && item_size < cap * 0.35 {
            score -= 10.0;
        }
    }

    // Mild pressure against spreading across too many open bins.
    score += open_bins_count as f64 * 0.15;

    // Tie-break: prefer bins whose residual is close to the mean (balanced packing).
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // A residual below the minimum item size (1..100 interface => min size 1,
    // but typical items are >=10) is dead space; penalize heavily as it approaches 0.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Smooth dead-space pressure: quadratic penalty on small residuals even above threshold.
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += (dead_threshold / (pr + 1.0)) * 2.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= tightness * 6.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins implicitly by making new-bin scores worse).
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and when this bin's post-residual would be large (wasteful start).
        score += obp * 3.0 + pr * 0.5;
    } else {
        // Existing bin: reward using it, more so when bins are plentiful.
        score -= obp * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr).abs() < 0.5 {
            score -= 20.0;
        } else if ni <= pr {
            score -= 5.0 * (ni / (pr + 1.0));
        } else {
            // Next item won't fit: residual becomes dead space for the next step.
            score += (ni - pr).min(20.0) * 0.4;
        }
    }

    // Mean-residual alignment: prefer bins whose post-residual moves toward the mean.
    score -= (mean_residual - pr).abs() * -0.1 * -1.0; // penalize divergence mildly
    score += (mean_residual - pr).abs() * 0.1;

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - pr) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next_item_size,
    // penalize otherwise (wasted space that next item can't use).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
            // Bonus if next item fills it nearly exactly (chain match).
            let chain_gap = post_residual - next_item_size;
            score -= (20.0 * (1.0 - chain_gap as f64 / bin_capacity as f64)).max(0.0);
        } else {
            score += 60.0;
        }
    }

    // Penalize opening a new bin when existing bins fit decently.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if this is a last-chance situation elsewhere, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Prefer bins below mean residual (consolidate space into fewer bins).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Late in stream: prefer closing bins tightly (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that no plausible item could use (items <= 80).
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill
    } else if post_residual > 80 {
        score += 0.5 * (post_residual - 80) as f64; // wasteful large gap
    }

    // Lookahead: if the next item fits into post_residual, this placement chains well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            score += 2.0;
        }
    } else {
        // Last item: filling as much as possible is ideal.
        score -= 25.0 * tight;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly and the item is large.
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a new bin, discounted when open bins are poor fits.
        score = 60.0
            - 25.0 * pressure
            - 20.0 * (avg_fit_gap / bin_capacity as f64)
            - 10.0 * item_frac
            + 15.0 * progress * (1.0 - pressure);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // room for the lookahead item in a fresh bin
        }
    } else {
        // Slight penalty scaling with congestion of open bins to encourage consolidation.
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
        // Reward bins whose residual is close to mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let pr_sq = fit_norm * fit_norm;
    let mut score = pr * (1.0 + 0.6 * pr_sq);
    // smooth progress coupling: penalize waste more later in the stream
    score += 12.0 * fit_norm * progress * (1.0 - progress) * 4.0;
    // reward bins whose residual is close to mean residual (balanced usage)
    score -= 3.0 * (1.0 - ((pr - mean_residual).abs() / cap).min(1.0));
    // last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }
    // lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).max(0.0) / cap;
        score -= 8.0 * (1.0 - gap) * (1.0 - gap);
        score += 4.0 * gap * gap;
    }
    // mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64 - 10.0 * progress;
    }
    // small tie-break on tightness
    score -= 0.05 * (item_size as f64 / cap) * (1.0 - fit_norm);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c * 0.25;
    let half = c * 0.5;
    let three_quarter = c * 0.75;

    // Reward placements that leave residuals in "usable" harmonic classes
    // (multiples of quarter capacity are re-fillable by common item sizes).
    if pr == 0.0 {
        score -= 60.0; // perfect fit
    } else if pr <= quarter {
        score -= 25.0; // small, nearly-full leftover is good
    } else if pr <= half {
        score -= 10.0;
    } else if pr <= three_quarter {
        score += 15.0; // awkward mid-size dead space
    } else {
        score += 5.0; // large leftover: bin was mostly empty anyway
    }

    // Integer-division harmonic bonus: leftover divisible into expected item classes.
    let pr_i = post_residual;
    if pr_i >= 10 && (pr_i % 10 == 0) {
        score -= 8.0; // residue matches decimal item classes
    }

    // Lookahead coupling: penalize if next item cannot use this leftover,
    // reward if it fits snugly.
    if next_item_size > 0 {
        if next_item_size <= pr_i {
            let snug = (pr_i - next_item_size) as f64;
            score -= 12.0 - snug * 0.15;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Avoid scattering across many open bins when mean residual is large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 * (1.0 - progress);
    score += crowding * 0.4;

    // Prefer bins whose residual is below the mean (pack the emptier bins less).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: opening a fresh bin is only attractive when no good
    // harmonic fit exists among open bins; make it moderately costly.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gap is "dead" if no plausible future item (min size 1..~30) can use it well.
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0; // steep penalty for tiny gaps
        }
        // Perfect fit bonus: reward tight packing.
        if post_residual == 0 {
            score -= 25.0;
        } else if post_residual <= 5 {
            score -= 10.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress) * 0.3;

    // Prefer bins whose residual is close to what we consume (good fit relative to mean).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.2;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if (gap as f64) < 20.0 {
            score -= 5.0;
        }
    }

    // New-bin candidate: opening a new bin should only win when no open bin fits
    // well. Give it a moderate baseline so good fits in open bins beat it, but
    // dead-space-heavy fits in open bins lose to it.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    let residual = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = residual / cap;
    score += 30.0 * frac * frac;

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
    } else if next_item_size > 0 {
        // Next item can't fit here: penalize, worse the tighter the bin was.
        score += 6.0 * (1.0 - frac);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: heavy bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let good_fit = (post_residual as f64) < 8.0;
        score += if good_fit { 60.0 } else { 5.0 + 20.0 * frac };
    }

    // Prefer filling existing bins when many are open.
    score += 0.5 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically relative to capacity.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 8.0 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Post-residual fits next item: reward.
            score -= 4.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += crowd * (post_residual as f64) * 0.05;

    // New-bin candidate: only attractive when mean residual is low (existing bins nearly full)
    // or the item leaves a very usable residual in a fresh bin.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - (post_residual as f64);
        let new_bin_bonus = 30.0 * (1.0 - mean_residual / cap) - 10.0 * progress;
        score -= new_bin_bonus;
        // Opening a new bin for a large item is fine; for small items it wastes space.
        score += (item_size as f64) * 0.1;
        let _ = mean_gap;
    }

    // Prefer bins whose residual is close to the item (waste minimization).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * fit_gap * fit_gap;

    // Late in stream, tighten packing: punish large residuals more.
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Normalized post residual and item size
    let pr = post_residual as f64 / bin_capacity as f64;
    let isz = item_size as f64 / bin_capacity as f64;
    // Base polynomial coupling: penalize mid-range residual (dead space) more than extremes
    let dead = pr * (1.0 - pr); // peaks at pr=0.5
    score += 12.0 * dead * (0.5 + progress);
    // Reward tight fits (small post_residual) with progress-dependent weight
    score -= 8.0 * (1.0 - pr).powi(3) * (0.4 + 0.6 * progress);
    // Interaction: item size with post residual — large items should prefer tight bins
    score -= 6.0 * isz * (1.0 - pr) * (1.0 - pr);
    // Last-chance bin bonus: strongly favor the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }
    // Penalty when many bins are open and this placement wastes space
    score += (open_bins_count as f64).ln().max(0.0) * dead * 3.0;
    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            score += 4.0 * ((nxt - post_residual as f64) / bin_capacity as f64).min(1.0);
        }
    }
    // Mean residual anchoring: prefer bins near the mean (keeps residuals uniform)
    score += 2.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();
    // New-bin candidate: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - isz) * (1.2 - progress) + 10.0 * (fitting_bins_count.max(1) as f64).recip();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small item sizes (10, 20, 25, 50)
    // are more likely to be filled later -> reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Dead space: residual below the minimum plausible item size
        if pr < 10 { score += 30.0; }
        else if pr < 20 { score += 10.0; }
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let exact = (pr % next_item_size == 0) as f64;
        score -= 8.0 + 4.0 * exact;
        score -= (pr - next_item_size) as f64 * 0.3;
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this bin's leftover; leftover likely dead
        score += (pr as f64) * 0.15;
    }

    // Integer-division threshold on bin fill fraction
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let quartile = (fill * 4.0) as u32; // 0..3 harmonic class
    score -= match quartile {
        3 => 10.0, // very full bin: excellent
        2 => 5.0,
        1 => 1.0,
        _ => 0.0,
    };

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if all open bins would leave tiny dead space, opening a new bin is fine
        if fitting_bins_count > 0 {
            let worst_dead = (bin_residual - item_size) as f64;
            if worst_dead < 10.0 { score -= 30.0; }
        }
    }

    // Slight preference to balance residuals across many open bins
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Mild exploration pressure over the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (<= 10% of capacity) are the worst outcome.
    let dead_threshold = (bin_capacity as f64 * 0.10).ceil() as u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 45.0 + (dead_threshold - post_residual) as f64 * 2.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residuals that can still host a mid-size follow-up item.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, favor it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize creating that situation
        // unless the residual is still large.
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.5 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless existing bins fit
    // poorly (large mean residual dispersion handled via mean_residual).
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual < 25.0 {
            score += 10.0;
        }
    } else {
        // Reward placing into bins with residuals close to the mean (stable packing).
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            // slack after next item would remain; penalize proportionally
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.35;
        } else {
            // next item cannot follow into this bin; penalize dead space growth
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.55;
        }
        // bonus if next item fits tightly relative to mean residual
        let mean_res = mean_residual.max(1.0);
        if (next_item_size as f64 - mean_res).abs() < 3.0 {
            score -= 5.0;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0;
    }

    // Penalize large unusable post-residual (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 12.0 };
        score += 8.0 + bad_fit_penalty
            - (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Slightly prefer consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of residual consumed by this item (fit tightness).
    let fill = item_size as f64 / bin_residual as f64;
    // Reward high fill ratio (tight packing), strongest for near-perfect fits.
    score -= 30.0 * fill * fill;

    // Penalize small dead space asymmetrically: residuals < 10 are nearly unusable
    // since min item size is 1..100 unknown; treat tiny leftovers as waste.
    let tiny = (post_residual < 10) as i32 as f64;
    score -= 8.0 * tiny;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate detection.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // Opening a new bin wastes the residual of all open bins; penalize unless
        // this item fits poorly everywhere (post_residual in a fresh bin is large,
        // so base score already high). Escalate penalty when many bins are open
        // and mean residual is healthy.
        let health = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let crowd = (open_bins_count as f64 / 20.0).min(1.0);
        score += 15.0 + 20.0 * health * (0.5 + crowd);

        // If the next item would fit in the leftover of an existing bin but this
        // item barely fits the fresh bin, discourage opening a new bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0;
        }
    } else {
        // Reward placing into existing bins whose leftover would suit the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
        // If this placement leaves a residual that cannot host the next item,
        // mild penalty (dead space risk).
        if next_item_size > post_residual && post_residual > 0 {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be conservative (keep bins open and
    // flexible); late in the stream, pack greedily since flexibility matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fill;

    // Prefer bins whose residual is below mean (consolidating fuller bins),
    // leaving emptier bins flexible for future items.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: quadratic in post_residual normalized by capacity
    let x = pr / cap;
    score += 40.0 * x * x * (1.0 - x);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= (1.0 + 3.0 * progress) * tightness * tightness * item_size as f64 * 0.15;

    // Lookahead coupling: penalize residuals that can't host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 + 12.0 * (nx - pr) / cap;
        } else {
            // smooth reward for leaving room usable by next item
            let fit = 1.0 - ((pr - nx) / cap);
            score -= 6.0 * fit * fit;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a bin when good fits exist
    if bin_residual == bin_capacity {
        let base = 12.0 + 25.0 * (1.0 - progress);
        let crowding = if open_bins_count > 0 { (open_bins_count as f64).ln() } else { 0.0 };
        let fit_exists = fitting_bins_count > 0;
        let mean_gap = (mean_residual - item_size as f64).abs() / cap;
        score += base + 3.0 * crowding
            + if fit_exists { 20.0 * (1.0 - mean_gap).max(0.0) } else { -8.0 * progress };
    }

    // Mild preference to fill bins with lower mean residual (consolidation)
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of capacity
    let mod_class = post_residual % bin_capacity.max(1);
    if mod_class == 0 {
        score -= 8.0; // perfect fill
    } else if mod_class <= 10 {
        score -= 4.0; // near-perfect: residual fits smallest items
    } else if mod_class > 50 {
        score += 6.0; // large dead space half of capacity
    }

    // Integer-division threshold: how many "smallest item slots" remain
    let slots = post_residual / 10;
    score -= slots as f64 * 0.8;

    // Fraction of capacity filled by this item
    let fill_frac = item_size as f64 / cap_f;
    score -= fill_frac * 20.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0; // default penalty: prefer existing bins
        // open new bin if placing here would leave awkward residue
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0; // perfect-ish fill of a fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Lookahead coupling: reward leaving space the next item can use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // harmonic match: post_residual mod next_item_size small => reusable
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 8.0;
            } else if rem <= 5 {
                score -= 3.0;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
        // avoid leaving a gap exactly between sizes (dead zone)
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 5.0;
        }
    }

    // Stream progression: early on, keep bins roomy; late, pack tight
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (post_residual as f64 / cap_f);

    // Mean residual coupling: penalize bins far from mean residual (balance)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Many open bins: encourage closing them out
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * fill_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 10)
    // are permanently wasted — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: fully packed bin is ideal.
    if post_residual == 0 {
        score -= 6.0;
    }

    // Lookahead (k=2): if the next item can fit into the post-residual,
    // this placement creates future value — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bins pressure: opening a brand-new empty bin is penalized,
    // scaled by how many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
    } else {
        // Reward reuse of an existing open bin.
        score -= 3.0;
    }

    // Last-chance bin: if this is the only open bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild pressure toward compacting when many bins are open and mean residual is low.
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual,
    // penalize if post residual is a "dead" gap just below next_item_size.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Extra reward for near-exact 2-step chaining.
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space: post_residual too small for next item.
            let deadness = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 6.0 * deadness;
        }
    }

    // Penalize bins far from mean residual (prefer balanced residual profiles),
    // but only mildly so tight fits still dominate.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If no open bin fits tightly, opening a new bin becomes more attractive.
        if post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks (non-linearly).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 1.8 * tightness * tightness * cap * 0.1;

    // Penalize dead space: residuals too small for any future item (1..100).
    let dead_threshold = 1.0f64;
    if (post_residual as f64) < dead_threshold.max(mean_residual * 0.25) {
        score += 6.0;
    }
    // Small residuals that can't fit the known minimum item size are waste.
    if post_residual < 1 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 12.0;
        } else if (post_residual as f64) >= nxt {
            score -= 2.0 * (nxt / cap);
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by waste.
            score += 1.5 * ((post_residual as f64) / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large or existing bins are crowded. Penalize the empty-bin call
    // (bin_residual == bin_capacity) when open bins are underutilized.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 {
            1.0 - (mean_residual / cap)
        } else {
            1.0
        };
        // pressure high => bins nearly full => opening new bin is fine.
        score += 10.0 * (1.0 - pressure);
        // Late in the stream, discourage new bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
        // Large items fill a fresh bin efficiently; reward slightly.
        score -= 0.05 * item_size as f64;
    }

    // Global balance: prefer bins whose residual is below mean (fill fuller bins
    // first, keeping larger residuals in other bins for future big items).
    let diff = mean_residual - bin_residual as f64;
    score += 0.6 * diff;

    // Mild preference for using many open bins efficiently early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 {
        score -= 1.0 * (1.0 - progress) * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr * (0.5 + progress));

    // Progress-scaled polynomial coupling: late in the stream, tighten residual tolerance
    score += 30.0 * progress * norm_pr * (norm_pr - 0.5) * (norm_pr - 0.5) * 4.0;

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + progress);
    }

    // Penalize when this bin is one of many fitting options and fit is mediocre
    if fitting_bins_count > 1 {
        score += 4.0 * ((fitting_bins_count - 1) as f64).ln().max(0.0) * norm_pr;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = pr - nx;
        if room >= 0.0 {
            score -= 12.0 * (room / cap) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * (-room / cap) * (0.5 + progress);
        }
    }

    // Coupling with mean residual: prefer bins deviating favorably from the mean
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);
    score -= 6.0 * dev * progress;

    // Mild penalty for opening new bins when open bins exist, relaxed late
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 10.0 + 15.0 * (1.0 - progress) - 5.0 * (open / (open + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "useful" residue class (small or exactly reusable sizes) are favored.
    let pr = post_residual;
    let class = match pr {
        0 => -1,                      // perfect fit
        1..=10 => -2,                 // near-perfect fill
        _ => {
            // integer division thresholds: leftover usable by small items?
            if pr % 10 == 0 { -3 }    // decade-aligned leftover is highly reusable
            else if pr / 10 >= 1 { 0 }
            else { 2 }                // tiny awkward remainder (1..9 after 10) is dead space
        }
    };
    score += class as f64 * 4.0;

    // Lookahead coupling: reward when next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // partial fit: reward proportional to how much of next item fits
            let frac = next_item_size as f64 / pr.max(1) as f64;
            score -= 15.0 * frac;
        } else {
            // next item cannot use leftover: penalize wasted space mildly
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin for a mediocre placement.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize scattering across many open bins; encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    // Favor bins whose residual is far below mean (denser bins get priority).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        // default neutral-to-slightly-bad; last-chance logic above will
        // usually beat it, but a perfect-fit class on an open bin beats it too.
        score += 8.0 + 0.1 * (pr as f64);
    }

    // Progress-aware mild annealing: early stream, be more tolerant of spread.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible future item are useless.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item.max(0.0) {
        score += 1000.0; // cannot happen, but guard
    }
    // Treat small gaps (< ~10) as dead space: heavily penalize.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    } else if post_residual < 40 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover gap: penalize proportionally to gap smallness.
        if post_residual < next_item_size && post_residual < 20 {
            score += 15.0;
        }
    }

    // Open-bin pressure: fewer open bins -> prefer reusing; many open bins -> favor consolidation.
    let pressure = open_bins_count as f64;
    score -= pressure * 0.5 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when no open bin gives a decent fit.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 - 30.0 * tightness;
        // If existing bins are fragmented (mean residual low) and item is large, opening new bin is fine.
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        score -= 40.0 * fragmentation * tightness;
        // If there are fitting bins and one would leave a small gap, discourage new bin.
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 20.0;
        }
        // Last-chance override: never open a new bin when exactly one bin fits.
        if fitting_bins_count == 1 {
            score += 500.0;
        }
    }

    // Mild stream-progression term: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large post_residual less mildly
            score += 20.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let diff = post_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 40.0;
        // allow new bin if item is large and would leave huge dead space elsewhere
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Early in stream, be more willing to open bins (spread items)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: penalize if post_residual can't fit the next item but is
    // small enough to be wasted; reward if next item fits exactly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // dead space for the next item; penalize proportionally
            score += (post_residual as f64 / bin_capacity as f64) * 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residuals below mean (fill emptier-of-space bins first
    // keeps large residuals available for large future items).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in the stream: be pickier about tight fits (more items to come);
    // late: accept anything that fits to close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // When many bins are open, encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * t) - 2.0 * pr_norm * t * t;
    score += 8.0 * poly;

    // Penalize tiny unusable residuals, more strongly late in stream
    let tiny = ((10.0 - pr).max(0.0)) / 10.0;
    score += 25.0 * tiny * (0.5 + 0.5 * t);

    // Reward tight fits (small post_residual)
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + t);

    // Last-chance bin: strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only if current fit is bad and lookahead is large
    if bin_residual == bin_capacity {
        let bad_fit = pr_norm > 0.5;
        let lookahead_big = next_item_size as f64 > 0.6 * cap;
        if bad_fit || lookahead_big {
            score -= 12.0 + 10.0 * t;
        } else {
            score += 20.0 + 15.0 * (1.0 - t);
        }
    }

    // Lookahead coupling: favor bins whose residual can still host next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 5.0 * (pr / cap);
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Mean residual coupling: penalize bins far from mean residual
    score += 3.0 * ((pr - mean_residual).abs() / cap);

    // Mild penalty for many open bins to discourage sprawl
    score += 0.5 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by integer division into capacity fractions.
    let pr = post_residual as u32;
    let class = pr / 10; // 0..10 harmonic band
    // Dead-space penalty: residuals that cannot fit small items (10..80) are worse.
    if pr < 10 {
        score += 40.0; // unusable sliver
    } else if pr < 25 {
        score += 12.0; // only fits tiny items
    } else if pr < 40 {
        score += 4.0;
    }

    // Modular resonance: residual divisible by common item sizes is valuable.
    if pr % 10 == 0 { score -= 6.0; }
    else if pr % 5 == 0 { score -= 3.0; }
    if pr >= 20 && (pr % 20 == 0 || pr % 25 == 0) { score -= 4.0; }

    // Perfect fit reward.
    if pr == 0 { score -= 60.0; }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= next_item_size {
            score -= 10.0 + n * 0.15; // keeps a useful slot for lookahead
            if pr == next_item_size { score -= 15.0; }
            if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            score += 8.0; // breaks the bin for the lookahead item
        }
        // Harmonic pairing: item + next sums to a capacity fraction
        let s = item_size + next_item_size;
        if s <= bin_capacity {
            if s % 50 == 0 { score -= 8.0; }
            else if s % 25 == 0 { score -= 4.0; }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tightness term: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 15.0;

    // Phase adaptation: early stream, be lenient about opening bins; late stream, consolidate.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= phase * 5.0;

    // New-bin candidate handling: penalize opening a new bin unless current residual is small.
    if bin_residual == bin_capacity {
        let waste = mean_residual.min(cap);
        score = 55.0 - phase * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big lookahead item deserves a fresh bin
        }
        if open_bins_count > 0 && waste > 30.0 { score += waste * 0.4; }
        if open_bins_count == 0 { score = -100.0; }
    }

    // Mild penalty for bin proliferation relative to mean residual alignment.
    if bin_residual != bin_capacity && (bin_residual as f64 - mean_residual).abs() < 2.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty: post-residuals that are too small to be useful later are "dead space".
    // Typical minimum item is small; treat residuals below a threshold as unusable.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 50.0 - post_residual as f64; // strong penalty for tiny unusable gaps
    }

    // Reward near-perfect fits heavily (post_residual close to 0 but still usable).
    if post_residual == 0 {
        score -= 100.0; // perfect fit: bin completely filled
    } else if post_residual <= 15 {
        score -= 20.0; // tight fit, still potentially usable for small items
    }

    // Penalize leaving moderately large residuals only mildly; they stay usable.
    if post_residual > 50 {
        score += 5.0; // slight preference to consolidate into fuller bins
    }

    // Open-bin pressure: prefer using existing bins over opening new ones,
    // especially as the number of open bins grows.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the resulting post_residual,
    // reward this placement; otherwise penalize slightly.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0;
        } else {
            score += 3.0;
        }
    }

    // Stream progression: early on, be slightly more conservative about filling bins
    // tightly (keep flexibility); later, push toward tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean residual coupling: if this bin's post_residual is far below the mean
    // residual, it's a good consolidation target.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post-residual space: reward proportionally
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - tight / bin_capacity as f64);
    }

    // Dead space: post_residual too small for any plausible next item (min size 1, but
    // penalize very small leftover fragments relative to mean residual)
    if post_residual > 0 && next_item_size > post_residual {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual is below mean (tighter packing)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current bins
    // would leave terrible dead space
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if next item is large and this bin is fresh, slight discount
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Early in stream: allow opening bins more freely to build flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    // Many open bins: discourage adding more
    if bin_residual == bin_capacity && open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the lookahead item
            score -= 8.0;
        }
    } else {
        // Last item: prefer filling existing bins as fully as possible
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless
    // current placement would leave a large, unusable residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_score = bin_capacity as f64 * 0.6;
        // If existing bins would create bad dead space, opening a new bin
        // becomes relatively more attractive.
        let bad_fit = if post_residual > 0 && post_residual < next_item_size.max(1) {
            1.0
        } else {
            0.0
        };
        new_bin_score -= 40.0 * bad_fit;
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); late in the stream, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 30.0 * progress;
        // Many open bins with high mean residual: avoid spreading further
        if mean_residual > 40.0 && open_bins_count > 3 {
            new_bin_score += 15.0;
        }
        score = score.max(new_bin_score) + (score - new_bin_score).abs() * 0.0;
        score = new_bin_score;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: penalize wasted space super-linearly,
    // amplified as the stream progresses (dead space matters more later).
    let norm_post = post_residual as f64 / cap;
    let waste = norm_post * norm_post * (1.0 + 2.0 * progress);
    score += 40.0 * waste;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness;

    // Lookahead coupling: bonus if post_residual can host the next item,
    // scaled smoothly by how snugly the next item fits.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let snug = (next_item_size as f64 / cap) * (1.0 - norm_post);
        score -= 10.0 * snug;
    } else if next_item_size > 0 {
        // Penalize residuals that cannot host the lookahead item.
        score += 5.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / cap;
        score += 30.0 * (1.0 - crowd) + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: classify dead space into
    // capacity fractions. Small dead space (<= 10) is nearly perfect.
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual <= 10 {
        score -= 50.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual > 50 {
        // Large residual: wasteful but reusable; mild penalty only.
        score += 15.0;
    }

    // Modulo-arithmetic class: residuals divisible by common item sizes
    // (5, 10, 20, 25) are "harmonic" — future items likely to fit exactly.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next fits: good, but prefer leaving harmonic-class residuals.
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item won't fit here: penalize small unusable leftovers.
            score += frac * 40.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only open a new bin when current residuals are
    // fragmented (high mean residual spread) or the fit here is terrible.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0;
        // Encourage opening a new bin late in the stream if existing bins
        // are congested (many open bins with poor fit).
        if fitting_bins_count == 0 || post_residual as f64 > mean_residual * 0.9 {
            score -= 45.0;
        }
        // Early stream: prefer filling existing bins to build density.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score += 20.0;
        }
    }

    // Prefer denser bins: lower residual before placement is generally better
    // (best-fit flavor), scaled by how many alternatives exist.
    score += (bin_residual as f64) * 0.05 * (1.0 + (fitting_bins_count as f64).recip());

    // Mild exploration: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items are 1..100, but small gaps under ~10 are effectively dead).
    if post_residual < 10 {
        score += 25.0; // creating an unusable sliver is bad
    }

    // A residual that cannot fit the known next item is less useful.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item.
        score -= 6.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when the
    // current fit is poor (large post_residual) or bins are few.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        let mut new_bin_cost = 30.0;
        // Cheap to open when few bins are open early on.
        new_bin_cost -= (open_bins_count.max(4) as f64 - 4.0) * 1.5;
        // Expensive if this bin would be the only fitting option elsewhere.
        if fitting_bins_count >= 1 {
            new_bin_cost += 10.0;
        }
        // Perfect-fit potential: a fresh bin wastes nothing now.
        new_bin_cost -= item_size as f64 * 0.1;
        score = new_bin_cost.max(score - 5.0);
    }

    // Mild alignment with mean residual: prefer bins whose residual is below
    // average (they are closer to being closed out).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 30.0 * (1.0 - tightness.min(1.0));

    // Reward perfect fit
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + next_fit);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize dead space unusable by the next item
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64).max(0.0);
    }

    // Relative to mean residual: prefer bins with residual below average (consolidate waste)
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or no good fit exists
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 35.0 + 0.3 * waste;
        if fitting_bins_count > 0 && item_size <= 60 {
            score += 25.0; // discourage new bin when open bins can fit medium items
        }
    }

    // Late in stream: prefer closing out bins (avoid leaving many open bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual by capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Penalize opening a new bin when other bins fit, reward it when last chance.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    } else {
        score -= 3.0;
        if fitting_bins_count == 1 {
            score -= 12.0; // last chance: strongly favor using this bin
        }
    }

    // Lookahead: if next item could use the post_residual, reward leaving exactly that space.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1.0 {
            score -= 20.0; // perfect pairing with lookahead item
        } else if post_residual >= next_item_size {
            score -= 6.0; // residual still usable by next item
        } else {
            score += (nr - post_residual as f64) * 0.15; // dead space vs lookahead
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= mean_residual * 0.05 * (1.0 + progress);
    }

    // Late in the stream, be more conservative about opening bins.
    if bin_residual == bin_capacity && progress > 0.7 {
        score += 15.0 * progress;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Non-linear coupling: squared post-residual normalized by capacity,
    // weighted by stream progress (dead space hurts more later).
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (0.3 + 0.7 * progress);

    // Strong reward for tight fits (small post_residual relative to item size).
    let tightness = 1.0 - pr / (item_size as f64).max(1.0);
    score -= 6.0 * tightness * tightness;

    // Lookahead coupling: reward if next item fits the post-residual well.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 4.0 * (1.0 - gap / cap);
        } else {
            score += 0.5 * (-gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.4 * open_bins_count as f64;
        // But late in the stream, new-bin penalty grows (avoid sprawling open bins).
        score += 10.0 * progress;
    }

    // Mild penalty for deviating from mean residual (keeps bin pool balanced).
    score += 0.05 * (pr - mean_residual).abs();

    // Small cubic smoothing term on progress-residual interaction.
    score += 3.0 * pr_norm * pr_norm * pr_norm * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is already the base; boost small residuals.
    if post_residual > 0 {
        // Harmonic class of post_residual modulo capacity fractions
        let pr = post_residual as f64;
        let frac = pr / cap;
        // Dead-space penalty: residuals too small for typical items (1..100 unknown, assume >=10 risk)
        if pr < 10.0 {
            score += 40.0 * (10.0 - pr) / 10.0;
        } else {
            // Prefer post_residual that is a "harmonic" usable chunk (multiples of 10, 20, 25, 50)
            let usable = (pr as u32 % 10 == 0) || (pr as u32 % 25 == 0) || (pr >= 50.0);
            if usable {
                score -= 6.0;
            }
            // Penalize awkward mid-range residuals (e.g. 11..19) that few items fit
            let m = post_residual % 10;
            if m >= 1 && m <= 9 && post_residual < 50 {
                score += 3.0 + 0.5 * m as f64;
            }
        }
        // Non-linear: squared fraction penalty for large leftover waste
        score += 8.0 * frac * frac;
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if post_residual - next_item is also small
        let nn = post_residual - next_item_size;
        if nn <= 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: penalize leaving stranded space
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful when decent fits exist
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += 30.0;
        // If no other bin fits, opening is necessary: reduce penalty
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins with large mean residual: avoid opening another
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild preference to fill bins that are already fairly full
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 4.0 * fill;

    // Small tie-breaker toward fewer open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits (small relative waste).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Penalty for leaving a gap that exactly fits the next item is good.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, prefer new bins less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean residual coupling: prefer bins with residual below mean (consolidation).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: base cost of opening a bin, modulated by whether
    // existing fits are poor (large post_residual means poor fit -> new bin viable).
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64 * 0.1 - (post_residual as f64 - mean_residual).max(0.0) * 0.3;
        if fitting_bins_count == 0 {
            score = -10.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 15.0; // new bin can host both current and next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit via post_residual, with a convex penalty on large waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Aggressive 2-step lookahead: reward when the residual exactly accommodates
    // the next item (perfect chaining), penalize when next item leaves large dead space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            let second_post = post_residual - next_item_size;
            score -= 12.0;
            score += 0.5 * second_post as f64; // penalize leftover after chaining
        } else {
            // next item cannot fit here; mild penalty proportional to shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.3 * shortfall;
        }
    } else {
        // Last item: minimize final residual strongly.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer resources;
    // wasting them is costlier.
    let rel = post_residual as f64 - mean_residual;
    if rel > 0.0 {
        score += 0.25 * rel;
    } else {
        score += 0.1 * rel; // slightly reward below-mean residuals
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: default neutral-ish; only attractive when the
    // item fits poorly everywhere (large item, high mean residual suggests
    // fragmented open bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for large items late in stream with fragmented bins.
        score = 55.0
            + 40.0 * (1.0 - fit_quality)
            - 25.0 * progress * (mean_residual / bin_capacity as f64)
            + 0.3 * post_residual as f64;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 15.0; // new bin can chain current + next item
        }
        // Never let new-bin beat a perfect chain or last-chance fit.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Slight scaling with number of open bins: discourage spreading across many bins.
    score += 0.05 * open_bins_count as f64 * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small to fit a typical future item.
    if post_residual > 0 {
        let dead_threshold = 12.0 + 0.3 * (mean_residual.max(0.0));
        if (post_residual as f64) < dead_threshold {
            score += 0.6 * (dead_threshold - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when the item fits nowhere well
    // (large item, poor fit in open bins) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let mut penalty = 15.0;
        // Large items justify a fresh bin more often.
        penalty -= 6.0 * fit_ratio;
        // Early in stream with few open bins, opening is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty -= 4.0 * (1.0 - progress) * (1.0 - progress);
        // If many bins are open with slack, discourage proliferation.
        penalty += 0.05 * open_bins_count as f64;
        // If lookahead item would pair with the leftover of this item, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 3.0;
        }
        score += penalty.max(0.0);
    }

    // Lookahead synergy: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.3 * (next_item_size as f64);
    }

    // Slight preference for bins with residuals below mean (consolidate slack).
    score += 0.1 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(0.0);

    // Mild pressure to close out bins as stream progresses.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more (quadratic in pr, scaled by progress)
    score += progress * (pr * pr) / cap;

    // Tightness reward: smooth bell around small residuals
    let tight = 1.0 - (pr / cap).powi(2);
    score -= 8.0 * tight.max(0.0);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many bins relative to mean residual
    score += (open_bins_count as f64).ln().max(0.0) * (pr - mean_residual).abs() / cap;

    // Lookahead coupling: reward leaving space for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = ((pr - nxt).max(0.0)) / cap;
        score += 4.0 * fit_next * (1.0 - fit_next) * 4.0; // smooth bump rewarding exact next-fit
        score -= 6.0 * (1.0 - ((pr - nxt).abs() / cap).min(1.0));
    }

    // New-bin candidate: penalize mildly so it only wins when fits are poor,
    // scaled by how much of the new bin would remain idle
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * (item_size as f64 / cap).powi(2) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are heavily rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward small post_residual super-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Dead-space penalty: residuals that few common item sizes can use.
    // Item sizes 1..=100; residuals in [1,10] or [11,19] etc. are awkward.
    let awkward = post_residual > 0 && post_residual < 10;
    if awkward {
        score += 25.0;
    }

    // Modulo-class logic: residual divisible by common small sizes is more reusable.
    let mut reuse = 0.0;
    for d in [2u32, 3, 4, 5, 10, 20, 25, 50] {
        if post_residual % d == 0 {
            reuse += 4.0;
        }
    }
    score -= reuse;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item nests
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 0.1 * (next_item_size as f64 - post) / cap * 50.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins relative to mean residual.
    score -= (mean_residual - post) * 0.5;

    // Mild pressure to close bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post * 0.3;

    // New-bin candidate: penalize opening a new bin unless item is large relative
    // to capacity or open bins are mostly full.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 40.0 - 30.0 * fill_ratio;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit anything are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward using a bin whose residual is nearly consumed (tight fit).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // If next item is large, opening a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Lookahead: avoid leaving a residual that barely fails to fit the next item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap < 0 && gap > -(next_item_size as i64 / 2) {
            score += 12.0;
        }
        if gap == 0 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: when open bins are already loose, discourage spreading.
    if mean_residual > bin_capacity as f64 * 0.5 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual is better (already base), add non-linear bonus
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: bin fully closed after two items
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses the leftover
            let use_frac = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * use_frac;
        } else {
            // next item does NOT fit leftover: penalize, since leftover becomes dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    } else {
        // Last item: strongly prefer closing bins completely
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins with residual below mean (consolidate fullness)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins, more so early in the stream
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Penalize leaving a residual too small for the next item (dead space risk),
            // scaled by how close it is to being usable.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 4.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / (bin_capacity as f64);
        // New bin is more acceptable early or when existing residuals are small.
        score += 10.0 + 20.0 * pressure - 6.0 * progress;
        // If the item is large, a fresh bin is more attractive.
        score -= (item_size as f64) / 20.0;
        // Many open bins: discourage spreading further.
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    } else {
        // Prefer bins with residual close to item size (minimize fragmentation).
        let waste_ratio = (bin_residual - item_size) as f64 / (bin_capacity as f64);
        score += 6.0 * waste_ratio;
        // Slight preference for bins below mean residual (consolidate emptier space usage).
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (pr / cap); // 0 = perfect fit, 1 = empty bin

    let mut score = pr as f64;

    // Non-linear coupling: prefer small post_residual with super-linear penalty on waste
    score += 0.6 * tightness * tightness * cap;

    // Smooth progress interaction: later in stream, penalize waste more strongly
    score += (0.4 + 1.2 * progress) * pr * pr / cap;

    // Reward exact-ish fits: subtract when post_residual is small relative to smallest plausible item
    let fit_bonus = (1.0 - pr / cap).powi(4);
    score -= 8.0 * fit_bonus;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * progress;
    }

    // Many fitting bins: slight penalty so we diversify fills
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Mean-residual coupling: prefer bins whose post-residual tracks mean residual (balance)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate handling: make empty bin moderately attractive only when current bin fits poorly
    if br >= cap - 0.5 && bin_residual == bin_capacity {
        score = cap - 0.5 * item_size as f64 + 3.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the new-bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residual that no typical item (>=1) can pair with well.
    // Classify post_residual into modulo classes w.r.t. small item sizes.
    let pr = post_residual;
    if pr > 0 {
        // Residuals divisible by common small sizes are reusable.
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 5 == 0 { score -= 3.0; }
        // Very small unusable slivers are fine (near-perfect fill).
        if pr < 4 { score -= 15.0; }
        // Large awkward residuals are penalized more when many bins are open.
        if pr > 40 { score += (pr as f64 - 40.0) * 0.3 * (open_bins_count as f64).sqrt(); }
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item nearly fills the leftover.
        let gap = post_residual - next_item_size;
        if gap <= 5 { score -= 10.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Leftover too small for next item: mild penalty scaled by sliver size.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // New-bin candidate: base cost of opening a bin, adjusted by context.
    if is_new_bin {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (more items to come to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If many bins already open and mean residual is high, discourage new bins.
        score += 0.5 * mean_residual;
        // If current item is large, a fresh bin gives good future flexibility.
        if item_size > bin_capacity / 2 { score -= 10.0; }
        // If only one fitting bin and its post-fit residual would be terrible, allow new bin.
        if fitting_bins_count == 1 {
            // compare: a new bin leaves residual = C - item_size
            let new_res = bin_capacity - item_size;
            if new_res < 15 { score -= 20.0; }
        }
    }

    // Prefer denser bins: lower current residual (before placement) slightly favored.
    score += 0.05 * bin_residual as f64;

    // Mild preference to spread load when few bins are open early on.
    if open_bins_count == 0 { score -= 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size of 1..=10) are heavily penalized,
    // but an exact or near-exact fit (post_residual == 0) is rewarded.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else if post_residual <= 10 {
        score += 25.0; // tiny unusable gap: worst kind of dead space
    } else if post_residual <= 20 {
        score += 8.0;  // marginal gap, likely hard to fill
    } else {
        // Larger residuals: mildly discount since they remain reusable
        score -= 2.0;
    }

    // Reward good relative fill of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading out; when few bins are open, this is weak.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (1.0 - fill_ratio);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Penalize the empty-bin call moderately
    // so tight fits in existing bins win, but let it win over bad fits.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If the next item is small, a fresh bin is more valuable
        if next_item_size > 0 && (next_item_size as f64) < 0.3 * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward creating that "sandwich" fit.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: this residual may become dead space
        score += 4.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (fill the emptier-feeling tight bins first, keep large residual bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late-stream tightening: as the stream progresses, be stricter about
    // dead space to squeeze the final bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)) + 15.0;
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to the shortfall.
        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.5 * shortfall;
    }

    // Penalize post-residual far above mean residual (wasteful leftover space).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Discard near-empty usage of a fresh bin unless item is huge (new-bin candidate logic).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio < 0.5 {
            score += 25.0 * (1.0 - fill_ratio);
        } else {
            score -= 5.0 * fill_ratio;
        }
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 {
        score += 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (best-fit core).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space that is too small to be useful later (items >= 10 classically,
    // but sizes 1..100 here): residual chunks below ~ the smallest plausible item are waste.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else if post_residual < 20 { 1.5 } else { 0.0 };
        score += dead * (post_residual as f64).sqrt();
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
            // Perfect chain: next item exactly fills the remainder.
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            // Post-residual too small for next item: mild penalty proportional to gap.
            score += 0.03 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * fit_ratio * 10.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins are open
    // with slack; encourage consolidation.
    if bin_residual == bin_capacity {
        // Base cost of a new bin rises with the number of open bins and mean slack.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 0.4 * open_bins_count as f64 + 0.05 * mean_residual;
        // Late in the stream, opening new bins is even worse.
        score += 6.0 * progress;
        // Exception: if no open bin can chain the next item and mean slack is small,
        // a fresh bin is less bad.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 8.0;
        }
    } else {
        // Existing bin: slight reward when its residual is below the mean (denser bin),
        // encouraging packing into already-busy bins.
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Mild preference for bins whose post-residual aligns with common future sizes
    // (diversity of slack): round residuals near multiples of 25 are more reusable.
    let pr = post_residual as f64;
    let align = ((pr / 25.0) - (pr / 25.0).round()).abs();
    score += align * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling: penalize mid-range waste more as stream progresses
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * (1.0 - norm_pr) * 40.0 * (0.5 + progress);

    // Reward tight fits (small post_residual) increasingly over time
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // If the next item fits exactly in the post residual, strongly reward
    if next_item_size > 0 {
        let nd = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-nd / 20.0).exp();
    }

    // Last chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Penalize fragmenting bins with large residuals when many alternatives exist
    if fitting_bins_count > 2 {
        score += norm_pr * 10.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged unless current fit is bad
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 20.0 * progress - pr * 0.3;
        if pr < 20.0 { score += 50.0; } // never open new bin for near-perfect fits elsewhere
    }

    // Mean residual coupling: prefer bins deviating from mean in the right direction
    score += (pr - mean_residual) * 0.15 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let post_frac = post_residual as f64 / cap;
    score -= 60.0 * (1.0 - post_frac).powi(3);

    // Harmonic classes: bucket post_residual into modulo classes of capacity.
    let class = post_residual % 25;
    score -= match class {
        0 => 40.0,           // perfect reusable class (e.g. 0, 25, 50, 75)
        1..=9 => 10.0,       // small gap, still usable by small items
        10..=19 => 0.0,      // mid gap
        _ => -8.0,           // larger residual, more flexible
    };

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 - (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use the gap: penalize wasted space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a bin is only good when no open bin
    // fits well (post_residual would be tiny) or bin pressure is high.
    if bin_residual == bin_capacity {
        // Empty bin baseline: moderate score; beaten by good fits, beats bad fits.
        score = 55.0 + 0.15 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 15.0; // stacking similar items in fresh bin is fine
        }
    }

    // Progress pressure: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_frac);

    // Penalize bins that deviate from mean residual (keep residuals balanced).
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 12.0;

    // Integer-division threshold: post_residual divisible chunks usable later.
    if post_residual > 0 && item_size % post_residual.max(1) == 0 && post_residual <= 50 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - progress * 20.0; // tiny dead space is worst outcome
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - progress);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: make empty bins moderately unattractive unless
    // the alternative is a very poor fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item is large relative to capacity, a fresh bin is more valuable.
        if next_item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving a gap that blocks the next item
        score += 8.0;
    }

    // Mild preference toward bins with lower residual (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of next item into post_residual is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;

        // Exact fit for the NEXT item: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits exactly with a small remainder chain: mild reward.
        else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 25.0;
        }
        // Next item cannot fit here: penalize leaving a large unusable residue.
        else if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: any placement is final; prefer tightest fit (low post_residual).
        score += 10.0;
    }

    // Reward bins that are already fairly full (low residual relative to mean).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.5;

    // Penalize bins with residual far below mean (they are outliers / poor fits).
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Slight penalty for opening a brand-new bin when others could fit,
    // unless the item is large and the new bin offers a fresh full capacity.
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 0.5;
        if item_size >= 50 && next_item_size > 0 && next_item_size <= 50 {
            score -= 40.0; // large item + moderate next item: fresh bin pairs well
        }
    }

    // Late in the stream: consolidate more aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    score -= 3.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);

    // Penalize dead space: post_residual too small for typical future items (1..100, mean ~50)
    if post_residual > 0 {
        let usable = if post_residual >= 50 { 1.0 } else { post_residual as f64 / 50.0 };
        score += (1.0 - usable) * 10.0;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is bad;
    // but when many bins are open with high mean residual, opening fresh bin can be good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
        score += (open_bins_count as f64).sqrt() * 1.5;
        score += mean_residual / 20.0;
    }

    // Penalize fragmenting bins with large residuals when item is small
    if item_size < 30 && bin_residual > 70 {
        score += 4.0;
    }

    // Mild preference for bins below mean residual (balance load)
    score += ((bin_residual as f64 - mean_residual) / 50.0).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Reward tight fits: non-linear decay of penalty as post_residual -> 0
    score -= 60.0 * (1.0 - norm_pr).powi(3) * (1.0 + 0.5 * progress);

    // Penalize large dead space superlinearly
    score += 40.0 * norm_pr.powi(2);

    // Interaction: tight fit worth more late in stream
    score -= 25.0 * progress * (1.0 - norm_pr) * fit;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when other bins fit, unless
    // residuals are large and scattered (fragmentation escape)
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count > 0 {
            (mean_residual / cap).powi(2) * 20.0
        } else {
            60.0
        };
        score += 25.0 - escape;
        // Lookahead: opening new bin is fine if next item pairs with current one
        if next_item_size > 0 {
            let pair = (item_size as f64 + next_item_size as f64) / cap;
            if pair <= 1.0 {
                score -= 20.0 * (1.0 - pair);
            }
        }
    }

    // Lookahead synergy in existing bin: leaving room for next item
    if next_item_size > 0 && bin_residual != bin_capacity {
        let nr = next_item_size as f64;
        if (pr - nr).abs() < 5.0 {
            score -= 15.0;
        } else if pr < nr && pr > 0.0 {
            score += 5.0 * (nr - pr) / cap;
        }
    }

    // Mild preference to spread load when many bins open
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual), with a harmonic-style
    // nonlinearity on the capacity fraction of the item.
    let item_frac = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * item_frac * (1.0 - item_frac);

    // Perfect fit bonus (harmonic class: post_residual == 0).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty for small unusable leftovers (modulo classes on post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (harmonic pairing class).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Reward partial compatibility scaled by how much room remains.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted pairing potential.
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly awful.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to mean residual stranded in open bins.
        score += 10.0 + mean_residual * 0.15;
        // More open bins with room => stronger penalty for opening yet another.
        score += open_bins_count as f64 * 1.5;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Big items justify a new bin more (they'd otherwise leave huge gaps).
        score -= 20.0 * item_frac;
    } else {
        // Slight preference for filling already-open bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Penalize bins whose residual is far from the mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold class on post_residual: quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual < 2 * quarter {
        score -= 3.0; // mid-range residual is still reusable
    } else if post_residual >= 2 * quarter && post_residual < 3 * quarter {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable gaps: residuals below the minimum item size are dead space.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }

    // Dead-space penalty grows sharply for small residuals that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 20.0;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * (next_item_size as f64);
    }
    // If next item almost fits (small miss), slight penalty for blocking.
    else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins fit or mean residual is high (fragmented).
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 25.0 + (open_bins_count as f64) * 3.0 - fragmentation * 30.0;
        if fitting_bins_count <= 1 {
            score -= 30.0; // last chance: prefer using the single fitting bin
        }
    } else if fitting_bins_count == 1 {
        // This is the only fitting bin: strong reward to use it.
        score -= 35.0;
    }

    // Mild pressure to close out bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (post_residual as f64 / bin_capacity as f64) * progress * 5.0;

    // Penalize bins whose residual deviates strongly below mean residual (fragmenting the fleet).
    score += ((mean_residual - post_residual as f64).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: perfect match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying with difference.
        let match_reward = 40.0 / (1.0 + diff * diff * 0.05);
        score -= match_reward;

        // If next item fits exactly after this placement, huge bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit in the leftover, penalize dead space quadratically.
        if post_residual < next_item_size && next_item_size > 0 {
            score += 0.35 * diff;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Compare post_residual relative to mean residual across open bins.
    // Prefer bins whose leftover lands near the mean (balanced packing),
    // but strongly prefer leftovers far BELOW mean (tight fills).
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap > 0.0 {
        score += 0.15 * mean_gap; // leaving more than average: penalty
    } else {
        score += 0.05 * mean_gap; // leaving less than average: mild reward
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Make it moderately attractive only when current bins are tight or
    // the item is large relative to the residuals available.
    if bin_residual == bin_capacity {
        let tightness = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // When open bins are mostly full (low mean residual), opening fresh is good.
        score = 55.0 - 45.0 * tightness - 20.0 * progress;
        // Large items benefit from a fresh bin.
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
        // If many bins already open, discourage unbounded growth slightly.
        score += 0.8 * open_bins_count as f64;
        // But if next item is large and this item is small, fresh bin is bad.
        if next_item_size > item_size {
            score += 10.0;
        }
    }

    // Late in the stream, tighten packing: penalize wasted space more.
    score += 0.5 * progress * post_residual as f64;

    // Small constant tie-breaker against dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating small unusable dead space (< next item or < min item).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < next_item_size.max(min_item) {
        score += 8.0 + 0.25 * post_residual as f64;
    }

    // Lookahead coupling: bonus if next item fits in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer spreading across bins (open new bins cheaply);
    // late in stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score += 2.0 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.35 && post_residual > 0;
        if poor_fit {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Smooth non-linear coupling: waste normalized by capacity, shaped by progress
    let waste_norm = pr / cap;
    let shape = 0.5 + 0.5 * (std::f64::consts::PI * progress).sin();
    score += 40.0 * waste_norm * waste_norm * (1.0 + shape);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= 25.0 * (1.0 - tightness) * (1.0 - tightness) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Penalize opening a new bin when other bins could fit, scaled by how well item would fit elsewhere
    if is_new_bin {
        let fits_well_elsewhere = (fitting_bins_count > 0) as i32 as f64;
        let next_fits = (next_item_size > 0 && next_item_size <= post_residual) as i32 as f64;
        score += 35.0 * fits_well_elsewhere * (1.0 - 0.5 * progress);
        score += 15.0 * next_fits;
        score -= 10.0 * (1.0 - progress); // early stream: fresh bins slightly cheaper
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        score += 0.3 * gap * gap / cap;
    }

    // Mild coupling with mean residual: prefer bins deviating favorably from mean
    score += 0.2 * (pr - mean_residual).abs();

    // Small penalty for proliferating bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Integer-division thresholds on post_residual: bins whose leftover falls into
    // "dead zones" (too small for typical items) are heavily penalized.
    let dead_zone = post_residual / 10; // harmonic class: 0..10
    match dead_zone {
        0 => score += 40.0,                      // residual < 10: nearly unusable
        1 => score += 25.0,                      // 10..19: only tiny items fit
        2 => score += 10.0,                      // 20..29
        3 => score += 4.0,
        4 | 5 => score -= 6.0,                   // 40..59: sweet spot, flexible
        _ => {}
    }

    // Modulo arithmetic: leftover congruent to small classes mod 10 is more usable
    // with typical item sizes (10..80 multiples/clusters).
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // exact decade leftover: perfect for decade-sized items
    } else if m <= 3 {
        score += 3.0; // awkward sliver above a decade
    }

    // Perfect fit reward: exact packing is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 2 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how tight the fit is
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 * tightness;
        } else {
            // next item won't fit here; if this bin's leftover becomes a dead zone,
            // mild penalty since we'll strand the space
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity => post_residual == cap - item).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin: keep it mildly expensive.
        score += 12.0 + 0.5 * open_bins_count as f64;
        // Opening a new bin is attractive when existing fitting options are poor
        // (this call already has post_residual = cap - item, usually a good leftover),
        // and when many open bins are badly fragmented.
        let fragmentation = (mean_residual - frac * 0.0).max(0.0);
        if fragmentation < 20.0 {
            score += 10.0; // open bins already tight; prefer reusing them
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If a future item of size next_item_size pairs perfectly with a new bin's
        // leftover, discount the new bin slightly.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Existing bin: reward tight fits relative to capacity fraction.
        score -= 5.0 * (1.0 - frac);
        // Prefer bins whose residual is close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Small tie-breaker toward earlier bins via step index (deterministic, grounded).
    score += 0.001 * (step_index % 7) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // tiny dead space is wasted capacity
        } else if gap < 20.0 {
            score += 25.0 * (20.0 - gap) / 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it can still fit afterwards.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // gap blocks the next item => extra penalty
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing bins.
    let obp = open_bins_count as f64;
    score += 0.35 * obp * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bins are nearly full / poor fits.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * obp;
        score += 20.0 + 5.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative: opening a new bin is fine
        }
    }

    // Slight progression bias: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));
        // Perfect match: post_residual == next_item_size, strong reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Dead space: post_residual too small for any item (min size 1..10 range guard)
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
        // If next item cannot fit here but could fit a fresh bin, penalize mildly.
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    } else {
        // Last item: minimize waste directly.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when all open bins are tight or full-ish.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        // Penalize opening new bins when open bins still have slack.
        score += 30.0 * (1.0 - mean_frac);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If item is huge and nothing fits elsewhere, new bin is fine.
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Favor tight fits relative to mean residual: bins below mean residual are more "used up".
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize wasted space, superlinear in dead space.
    let waste = post_residual as f64;
    score += 0.35 * waste * (waste / bin_capacity as f64);

    // Reward tight fits (small post residual relative to item).
    if item_size > 0 {
        score -= 12.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize leaving a gap that no typical item can use (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(20) {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalized when open bins
    // are plentiful or residuals are large (prefer reusing open capacity).
    if bin_residual == bin_capacity {
        score += 20.0;
        score += 2.0 * (open_bins_count as f64).sqrt();
        score += 0.5 * mean_residual.max(0.0);
        // Early in stream: new bins are cheaper; late in stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
        // If next item is large and this new bin would fit it too, slightly favor.
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 6.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Small penalty for very small residual bins becoming near-closed anyway.
    if bin_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear waste term: quadratic-cubic coupling of post-residual with progress
    let mut score = pr * (1.0 + 0.8 * progress) - 12.0 * x * (1.0 - x) * (1.0 + progress);

    // Tight fit reward (smooth, peaked near zero residual)
    score -= 18.0 * (-x * 6.0).exp();

    // Penalize residuals that are dead space (too small for typical future items)
    let dead = (cap * 0.2 - pr).max(0.0) / cap;
    score += 25.0 * dead * dead;

    // Lookahead: reward if next item fits in post-residual
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            score -= 10.0 * (1.0 - fits_next) * (1.0 + progress);
        } else {
            score += 4.0 * (-fits_next) * (0.5 + progress);
        }
    }

    // Last chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin, more so early and when open bins exist
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // still allow new bin if mean residual is very small (all bins nearly full)
        score -= 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space into residue classes mod 10
    let class = post_residual / 10;
    // Penalize dead space classes that are hard to fill (small nonzero residuals)
    match class {
        0 => { if post_residual > 0 { score += 25.0; } }       // tiny unusable sliver
        1 => { score += 12.0; }                                 // 10-19: hard to reuse
        2 => { score += 6.0; }                                  // 20-29
        3 => { score -= 2.0; }                                  // 30-39: decent
        4 => { score -= 5.0; }                                  // 40-49
        5 => { score -= 8.0; }                                  // 50-59
        6 => { score -= 10.0; }                                 // 60-69
        7 => { score -= 11.0; }                                 // 70-79
        8 => { score -= 12.0; }                                 // 80-89
        9 => { score -= 12.0; }                                 // 90-99
        _ => {}
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // exact chain match
        } else if next_item_size <= post_residual {
            score -= 40.0;
            // smoother chain: leftover after chaining
            let chain_left = post_residual - next_item_size;
            score -= (chain_left / 10) as f64 * 3.0;
        } else {
            // next item won't fit here; penalize large residuals less if next item is big
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer fuller bins overall (tighter packing pressure)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 60.0;
        // If existing fits are plentiful, opening new bin is costly
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 8.0;
        }
        // If mean residual across open bins is small (all open bins nearly full),
        // opening a new bin is more attractive
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 55.0;
        }
        // Early stream: slight preference to keep bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Mild penalty when many bins already open (encourage consolidation)
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest items are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits strongly
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Penalize opening new bins when decent fitting bins exist
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild pressure from number of open bins: prefer consolidating when many open
    if bin_residual != bin_capacity {
        score += 0.4 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Slight preference for using existing bins early vs late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for a perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward if next item fits exactly with slack tolerance.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward closeness of the fit; small slack is good.
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        // Extra bonus if next item also fits tightly (within 10 units).
        if slack <= 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Penalize creating residual too small for the lookahead item (dead space).
        let dead = next_item_size - post_residual;
        score += 15.0 + 0.5 * dead as f64;
    }

    // Penalize post_residual that is small but nonzero (hard-to-fill sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward bins whose residual is already below mean (tighter bins get filled first).
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 0.05 * ((post_residual as f64) - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well, i.e. when the item leaves large unusable residue everywhere.
    if bin_residual == bin_capacity {
        // Base penalty for spawning a new bin.
        score += 40.0 + 5.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
        // If next item is small, a fresh bin is more forgiving; slightly reduce penalty.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
        // If the item would leave a perfect residual for the next item in a fresh bin,
        // opening a new bin becomes competitive.
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 55.0;
        }
    }

    // Mild global scaling to keep magnitudes comparable.
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize wasting a nearly-full bin's remaining sliver on a small item
    // when that sliver could serve a smaller future item.
    if post_residual > 0 && post_residual < item_size {
        score += 6.0 * (post_residual as f64 / item_size as f64);
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here anyway; slight penalty if we leave
            // a large awkward gap that nothing typical can use.
            if post_residual > 0 && post_residual < 10 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when many
    // open bins already have large residuals (fragmentation is high) or
    // when the fit in existing bins would be terrible.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let mut new_bin_penalty = 10.0 + 5.0 * (open_bins_count as f64);
        if fragmentation > 0.5 {
            new_bin_penalty -= 6.0 * (fragmentation - 0.5);
        }
        // If the best existing fit is bad (large post_residual among fitting
        // bins is unknown here), use mean_residual as proxy: high mean
        // residual means existing bins are roomy, so opening new is cheaper.
        score += new_bin_penalty;
        // Early in the stream, opening bins is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
    }

    // Mild preference for bins with residual close to item_size (perfect fit).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let pr2 = fit_norm * fit_norm;
    let pr3 = pr2 * fit_norm;

    // Base: reward tight fits via smooth cubic in post_residual
    let mut score = 2.0 * pr - 1.5 * cap * pr2 + 0.5 * cap * pr3;

    // Non-linear coupling with stream progress: early on tolerate slack,
    // later aggressively punish residual waste
    let progress_coupling = (0.5 + 2.0 * progress) * pr2 * cap;
    score += 0.35 * progress_coupling;

    // Lookahead: reward bins whose leftover matches the next item smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 1.2 * gap * gap * cap;
        // if next item fits exactly in post residual, strong bonus
        let fits_next = (pr - next_item_size as f64).max(0.0) * (next_item_size as f64 / cap);
        score -= 0.8 * fits_next;
    }

    // Last-chance bin bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else {
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: penalize bins far from mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 0.4 * dev * dev * cap;

    // Mild penalty for proliferating bins early (encourage consolidation)
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress) * fit_norm;

    // New-bin candidate: make empty bin attractive only for large items / late stream
    if bin_residual == bin_capacity {
        let openness = 0.5 + 0.5 * (item_size as f64 / cap);
        score -= 2.5 * openness * (0.3 + 0.7 * progress);
        // penalize opening new bins when good fits exist
        score += 0.4 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with diminishing penalty.
    let mut score = post;

    // Harmonic class of post_residual: dead-space quality classes via integer division.
    // Class 0: post < 10 (nearly perfect), class 1: 10..25, class 2: 25..50, class 3: >=50.
    let cls = post_residual / 10;
    let class_penalty = match cls {
        0 => -6.0,
        1 => -2.0,
        2 => 4.0,
        _ => 10.0,
    };
    score += class_penalty;

    // Modulo-10 harmonic: post_residual near multiples of 10 leaves room for common
    // small items (sizes 10..80 often decompose into 10-blocks).
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 3.0;
    } else if rem10 >= 8 {
        score += 2.5; // awkward sliver
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 8.0; // perfect chain fill
        } else if next_post <= 10 {
            score -= 5.0;
        } else {
            score -= 2.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover: leftover likely dead space.
        score += (post_residual as f64) * 0.08;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // all open bins fit poorly (high post_residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // New bin gets a fixed cost that grows with stream progress and open-bin count.
        score = cap * 0.55 + 18.0 * progress + 0.8 * open_pressure;
        // If this is the only fitting option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild tie-break toward using emptier bins when many are open.
    score -= (bin_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold: f64 = 12.0; // gaps <= 12 are nearly unusable for future items
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64 + 1.0) * 18.0;
    }

    // Reward very tight fits (post_residual close to zero but not dead).
    if post_residual <= 2 {
        score -= 25.0;
    }

    // Reward when the leftover can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: mild penalty proportional to gap
        score += (next_item_size as f64 - post_residual as f64).min(10.0) * 1.5;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (already
    // "used" bins) so fuller bins get priority.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it moderately attractive only when no open bin
    // offers a tight fit; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        score += 15.0 - (post_residual as f64 - item_size as f64).abs() * 0.0;
        if fitting_bins_count > 0 {
            // an open bin fits; discourage new bin unless that fit would be terrible
            score += 10.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // pairing lookahead with fresh bin is attractive
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills the residual exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into the post residual,
    // reward this bin heavily (a chained match is very desirable).
    if next_item_size > 0 && post_residual >= next_item_size {
        // Tighter chain (less slack left after the hypothetical next placement) is better.
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - chain_slack * 0.4;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item (dead space risk),
        // scaled by how close the next item is to fitting.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.3;
    }

    // Relative-to-mean coupling: a residual much smaller than the mean residual
    // means this bin is nearly full -> placing here consolidates waste; reward it.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.15;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline penalty so
    // that only genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If no open bin competition exists (or lookahead suggests a fresh bin is
        // better for a large upcoming item), soften the penalty.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, avoid opening bins,
    // prefer packing tightly into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 5.0;
    }

    // Small penalty proportional to how much of the bin's residual is wasted
    // relative to capacity (non-linear squashing of small wastes).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits strongly.
    let tightness = (item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 6.0 * tightness * tightness;

    // Penalize large dead space quadratically (wasted capacity).
    let dead = post_residual as f64;
    score += 0.02 * dead * dead / bin_capacity as f64;

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
        // Extra reward if next item then fits almost perfectly.
        let after_next = post_residual - next_item_size;
        score -= 3.0 * (1.0 - (after_next as f64) / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize if post-residual is small but nonzero relative to next item.
        score += 1.5 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // or mean residual is very low relative to item size.
    if bin_residual == bin_capacity {
        score += 3.0 * open_bins_count as f64;
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            score -= (-mean_gap).min(30.0) * 0.3;
        } else {
            score += mean_gap * 0.15;
        }
        // Slightly cheaper to open new bins late in the stream (avoid stranding).
        score -= 4.0 * progress;
    } else {
        // Prefer bins with below-average residual (consolidate fullness).
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Mild bonus for filling bins near capacity overall.
    let fill = (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 2.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 60.0 * norm_pr * norm_pr + 40.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in the stream, penalize large residuals more strongly
    let coupling = 1.0 + 1.5 * progress * (1.0 - progress + 0.25);
    score *= coupling;

    // Perfect fit bonus (smooth, not piecewise)
    score -= 25.0 * (-pr * pr / 8.0).exp();

    // Lookahead: reward leaving room for the next item (smooth polynomial in gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        let fit_lookahead = (-8.0 * gap * gap).exp();
        score -= 15.0 * fit_lookahead;
        // Penalize near-miss residuals that neither fit next item nor stay useful
        let near_miss = (-(gap + 0.5) * (gap + 0.5) * 12.0).exp();
        score += 10.0 * near_miss;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and residual is large (dead space accumulation)
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * open_norm * norm_pr * (pr - mean_residual).abs() / cap;

    // New-bin candidate: prefer opening fresh bins early, less so later; penalize slightly so it's only chosen when fit is poor
    if bin_residual == bin_capacity {
        score = pr + 12.0 - 15.0 * progress + 8.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in a
    // "reusable" class (multiples of 10, or >= 10) are rewarded.
    let pr = post_residual;
    let harmonic_class = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if harmonic_class == 0 {
        score -= 15.0; // round leftover, likely reusable
    } else if pr < 10 {
        score += 40.0; // dead space below minimum item size
    } else {
        score += harmonic_class as f64 * 0.8; // oddness penalty
    }

    // Fractional capacity logic: how much of the bin is consumed.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 30.0;

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0 + (pr - next_item_size) as f64 * 0.2;
        } else {
            score += 18.0;
        }
        // Harmonic match: next item's class aligns with leftover class
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: discourage fragmentation, prefer tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - fill_frac);
    score += progress * 5.0;

    // Prefer bins whose residual is near the mean (balanced packing).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead" residual: gaps too small to ever hold a plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual is close to the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins implicitly
    // by rewarding placement into existing bins.
    score -= open_bins_count as f64 * 0.8;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open bins count.
        score = 25.0 + open_bins_count as f64 * 1.5;
        // If the current item leaves a large residual in a fresh bin and
        // lookahead item is small, a new bin is reasonable.
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in stream, be slightly more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits with little waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 - (post_residual - next_item_size) as f64 * 0.5;
    }
    // Next item cannot follow into this bin: penalize proportionally
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits relative to bin capacity (small dead space fraction)
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Deviation from mean residual: prefer bins that deviate less (keep residuals uniform),
    // but a much-larger-than-mean residual is a good target to fill.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.15;
    } else {
        score += (-dev) * 0.10;
    }

    // Last-chance bin: only bin that can fit the item -> strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current open bins would waste a lot.
    // New bin gets post_residual == bin_capacity - item_size, so scale by open-bin pressure.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 120.0 + pressure * 5.0;
        // Allow opening a new bin early in the stream (build a pool of bins)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
        // If next item is large, a fresh bin is attractive
        if next_item_size > 60 {
            score -= 50.0;
        }
    }

    // Many open bins: discourage spreading, prefer consolidation into existing bins
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on leftover space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward if next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * tightness;
        } else if post_residual > 0 && post_residual < 10 {
            // Leaving tiny dead space is bad if next item can't use it.
            score += 8.0;
        }
        // If next item is large and this bin is roomy, prefer saving this bin's space.
        if next_item_size > post_residual && post_residual > next_item_size / 2 {
            score += 5.0;
        }
    }

    // Global state: with many open bins, prefer filling existing ones over opening new.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score -= 6.0 / pressure;

    // Deviation from mean residual: prefer bins that deviate less (balance load),
    // but allow using large-residual bins when item is large.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: opening a new bin is correct
        } else if post_residual as f64 > mean_residual {
            score += 15.0; // wasteful to open a new bin when others fit
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    // Small nudge against creating residuals that no typical item (>=1) can pair with.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: best-fit core, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, dead space is costly (superlinear in pr).
    let waste_penalty = (pr / cap).powf(2.0 + 2.0 * progress);
    score += 2.0 * waste_penalty;

    // Smooth interaction: small post_residual becomes more valuable as stream advances
    let tightness = 1.0 - pr / cap;
    score -= progress * tightness.powi(3) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Penalize opening a new bin when open bins could fit, more so late in the stream
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress + 0.05 * open_bins_count as f64;
        // If next item could also use this fresh bin's space, soften slightly
        if next_item_size as f64 > pr {
            score -= 0.3;
        }
    }

    // Mild tie-break toward bins below mean residual (consolidating fuller bins)
    let resid_diff = mean_residual - bin_residual as f64;
    score += 0.1 * resid_diff / cap;

    // Lookahead: reward leaving space the next item can use (smooth coupling)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.5 * (1.0 - pr / cap) * (next_item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual via integer division by 10.
    let post_class = post_residual / 10;
    match post_class {
        0 => {
            // Residual in 0..=9: near-perfect or dead space.
            if post_residual == 0 {
                score -= 60.0; // perfect closure, strongly reward
            } else {
                score += 12.0; // small dead space, mildly penalize
            }
        }
        1 => {
            // 10..=19: usable only for small items; penalize unless next item fits.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 8.0;
            } else {
                score += 10.0;
            }
        }
        2 | 3 => {
            // 20..=39: mid-class; reward if next item fits exactly-ish.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 6.0 + (post_residual - next_item_size) as f64 * 0.3;
            } else {
                score += 5.0;
            }
        }
        _ => {
            // 40..=99: large residual, flexible; mild reward for keeping it.
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits into post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.25;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: discourage unless it's genuinely attractive.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    }

    // Progress coupling: later in the stream, be more conservative about leaving large residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    // Distance from mean residual: prefer bins whose residual is above mean (absorb slack there).
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=9) are wasted capacity forever.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10.0 - post_residual as f64) * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward filling bins below mean residual (consolidating space).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if next_item_size == post_residual {
            score -= 40.0;
        }
    }
    // Penalize if next item cannot fit into post_residual but could fit elsewhere (dead space risk).
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open-bin pressure: discourage opening new bins when many bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and stream progress.
        score += 55.0 + open_bins_count as f64 * 6.0
            + (step_index as f64 / total_items.max(1) as f64) * 25.0;
        // Slightly more willing to open a bin early when residuals are large (items big).
        score -= mean_residual * 0.1;
    } else {
        // Mild reward for using existing bins as open-bin count grows.
        score -= open_bins_count as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already does most of this).
    let frac_used = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * frac_used;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are quite full or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64 * avg_fill) / (open_bins_count as f64 + 1.0);
        // Prefer new bin when existing bins are full and item is big.
        let open_bonus = pressure * 30.0 + frac_used * 20.0 + progress * 5.0;
        score = 60.0 - open_bonus;
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 15.0; // an open bin could still serve the next item
        }
    }

    // Mild preference to fill bins that are already mostly full.
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += 5.0 * (1.0 - residual_frac);

    // Slight time-dependent tie-breaker to diversify choices over the stream.
    score += 0.01 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: quadratic penalty on wasted residual, amplified by stream progress
    let mut score = pr + (pr * pr) / cap * (0.5 + progress);

    // Smooth interaction: residual relative to mean residual across open bins
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score += rel * (1.0 + progress) * 10.0;

    // Lookahead coupling: reward if next item fits snugly in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= (1.0 - snug / cap) * 15.0 * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // penalize dead space that blocks the next item
        score += 8.0 + progress * 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly, more so early when consolidation is cheap
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Cubic smooth coupling of post_residual with progress
    score += (pr / cap).powi(3) * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands (classic capacity/10 classes)
    let post = post_residual;
    let class = (post % 10) as f64;
    let band = (post / 10) as f64; // integer division threshold band

    // Reward residuals that fall into "usable" harmonic classes for typical small items.
    // Residuals like 0 are perfect; residuals in [1,9] are near-dead space (penalize heavily).
    if post == 0 {
        score -= 200.0;
    } else if post < 10 {
        // dead space: unusable for items >= 10 in classic regime, still might fit tiny items
        score += 60.0 - class * 6.0;
    } else {
        // Reward small multiples of common item sizes (harmonic alignment)
        let mut align = 0.0f64;
        for k in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
            if post >= k && (post % k == 0 || post % k >= k - 2) {
                align += 8.0;
            }
        }
        score -= align;

        // Prefer residuals that can still host a mid-size chunk: band thresholds
        score -= band * 2.0;

        // Modulo-10 penalty: residuals just above a multiple of 10 waste less
        score += class * 0.8;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 150.0;
        } else if next_item_size < post {
            score -= 10.0 + (post - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: slight penalty if this bin becomes stranded
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin should be penalized unless
    // the current item leaves a terrible residual everywhere else.
    if bin_residual == bin_capacity {
        // empty bin: neutral-ish baseline, plus pressure from open bins count
        score = 100.0 - post_residual as f64; // post_residual == capacity here
        score += open_bins_count as f64 * 1.5;
        // discourage hoarding new bins early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 20.0;
    }

    // Mean residual context: if this bin's residual is far below mean, it's a tight fit (good)
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.5;

    // Mild packing-density term: reward filling bins fuller relative to capacity
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100
    // interface => dead zone threshold ~10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        score -= 100.0; // perfect fit is always best
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 10.0; // this bin leaves a gap the next item cannot use
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins is penalized via the empty-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly.
        score = bin_capacity as f64
            - 30.0
            + 5.0 * open_bins_count as f64
            + 0.3 * mean_residual
            + (10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)));
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0;
        }
    } else {
        // Mild reward for reducing mean residual spread (consolidation).
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score -= 0.1 * dev;
        }
        score += 0.2 * open_bins_count as f64;
    }

    // Stream progression: later in the stream, be more conservative about
    // opening bins and more aggressive about closing gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * lookahead_gap;
        // Perfect chain: this item's leftover exactly fits the next item.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Usable leftover for the next item: reward proportionally.
            score -= 0.5 * next_item_size as f64;
        } else if next_item_size > post_residual {
            // Dead space relative to lookahead: penalize.
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.2 * ((post_residual as f64) - mean_residual);

    // Penalize very small unusable leftovers (dead space).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 60.0 * (1.0 - tightness) + 20.0;
        if fitting_bins_count == 0 || post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 45.0; // allow opening when open bins are poor fits
        }
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 35.0; // fresh bin chains perfectly with next item
        }
    }

    // Slight preference to consolidate fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Penalize large dead space, more so late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / bin_capacity as f64) * (50.0 + 100.0 * progress);

    // Lookahead: reward bins whose residual can host the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 + 0.5 * next_item_size as f64;
        } else {
            // Next item cannot follow here; slight penalty proportional to overshoot.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: this is the only bin that fits; avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0 + 0.5 * item_size as f64;
        // But if the fit leaves a huge unusable gap and a new bin would be cleaner, soften the reward.
        if post_residual > 40 && post_residual < next_item_size.max(1) {
            score += 60.0;
        }
    }

    // New-bin candidate: prefer opening a fresh bin when existing fits are poor,
    // but discourage excessive bin proliferation.
    if bin_residual == bin_capacity {
        let proliferation = open_bins_count as f64;
        let poor_alternatives = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 - mean_residual).max(0.0)
        };
        score = 100.0 + 5.0 * proliferation - poor_alternatives;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin guarantees room for the next item too.
            score -= 30.0;
        }
        if progress > 0.9 {
            score += 50.0; // late stream: consolidate instead of opening bins
        }
    }

    // Mild preference for filling bins that are already relatively full.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    // Global balance: slight penalty for bins deviating from mean residual (keeps pool uniform).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), with smooth polynomial shaping
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress:
    // late in the stream, waste matters more; reward tight fits quadratically.
    score -= 30.0 * (1.0 - x) * (1.0 - x) * t;

    // Penalize dead space that is too small to be useful later (smooth cubic term)
    let dead = (x * (1.0 - x)).max(0.0);
    score += 20.0 * dead * x * x * (1.0 - t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = x - nx;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - diff) * t;
        } else {
            score += 8.0 * (-diff);
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (x - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: perfect fit -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward leftovers that are "harmonically useful": small, or divisible
        // into common item sizes (multiples of 5/10), or able to host next item.
        if post_residual % 10 == 0 {
            score -= 20.0;
        } else if post_residual % 5 == 0 {
            score -= 10.0;
        }

        // Small leftovers are fine (tight packing)
        if post_residual <= 10 {
            score -= 15.0;
        } else if post_residual <= 25 {
            score -= 5.0;
        } else if post_residual >= 60 {
            // big dead space unless next item can use it
            score += 10.0;
        }

        // Lookahead coupling: if next item fits exactly into post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 60.0;
            } else if next_item_size <= post_residual {
                // next fits: leftover still usable
                let slack = (post_residual - next_item_size) as f64;
                score -= 20.0 * (1.0 - slack / cap);
            } else {
                // next item cannot use this leftover: penalize proportionally
                score += 5.0 * (next_item_size as f64 - pr) / cap;
            }
        }

        // Fraction-of-capacity harmonic classes
        let frac = pr / cap;
        score += 30.0 * (frac - 0.5).abs(); // prefer leftovers near half or near zero? penalize mid-zone mildly
        if frac < 0.15 {
            score -= 25.0; // near-perfect packing
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let bad_fit = pr > 40.0; // leaving lots of dead space in an existing bin
        if bad_fit {
            score -= 45.0;
        } else {
            score += 60.0; // prefer reusing open bins for decent fits
        }
        // more open bins -> less eager to open yet another
        score += 8.0 * open_bins_count as f64;
    }

    // Mild drift: early in stream, tolerate slack; late, pack tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum item (size 1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small usable residual still left).
    score -= 60.0 / (1.0 + post_residual as f64);

    // Penalize wasting a large residual on a small item (poor space utilization).
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 1.5;
    }

    // Open-bins pressure: discourage spreading across many bins unless the
    // fit is genuinely tight; encourage closing bins out.
    score += open_bins_count as f64 * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (high mean residual spread) or the next item is large and would benefit
    // from a fresh bin.
    if bin_residual == bin_capacity {
        let fresh_bonus = -30.0
            + mean_residual * 0.3
            + (next_item_size as f64 / bin_capacity as f64) * 20.0;
        score += fresh_bonus.max(-60.0);
    } else {
        // Lookahead coupling: if the next item fits exactly into the resulting
        // residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 30.0;
            }
        }
        // If next item is large and this placement leaves a gap it cannot use,
        // slightly penalize.
        if next_item_size > post_residual && post_residual > 0 {
            score += 5.0;
        }
    }

    // Mild stream-progress term: late in the stream, be more conservative
    // about opening bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= progress * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual near 0).
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // 2-step lookahead: reward if the next item fits into the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how well it uses the leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (-slack / 10.0).exp();
        } else {
            // Next item does NOT fit: penalize leftover space that is too small to be useful.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 8.0 * (10.0 - waste);
            }
        }
    }

    // Relative-to-mean-residual coupling: bins with residual below mean are scarcer;
    // placing into them is fine if the fit is tight, otherwise penalize.
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.15 * dev.max(0.0);           // leaving more than average space: mild penalty
    score -= 0.10 * (-dev).max(0.0);        // leaving less than average space: mild reward

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded (mean residual low)
    // or no tight fit exists. Penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0;
        let mut penalty = 45.0;
        if crowded { penalty -= 20.0; }
        if next_item_size > 0 && post_residual >= next_item_size { penalty -= 10.0; }
        score += penalty;
        // A fresh bin is better when many bins are open (consolidation pressure low).
        score += 0.5 * open_bins_count as f64;
    }

    // Slight early-stream preference to keep bins open longer (build good packing structure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on large post-residual chunks.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect or near-perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item can fit in the post-residual, reward;
    // if next item is small and post_residual is just below it, penalize dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64 / bin_capacity as f64) * 15.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 25.0; // stranded sliver below next item's size
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Global mean residual coupling: prefer bins whose residual deviates
    // favorably (below mean) so big residuals stay available for big items.
    let res = post_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - res) * 0.2;
    }

    // Early in the stream, be slightly more willing to keep bins tight;
    // late in the stream, favor closing bins out (minimize post-residual more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this is called with full residual and few fitting alternatives).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // opening a new bin is reasonable
        } else {
            score += 45.0 + (mean_residual / bin_capacity as f64) * 30.0; // prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Primary objective: minimize wasted space, with non-linear emphasis
    let norm_post = post / cap;
    score += 8.0 * norm_post * norm_post * cap;

    // Perfect fit reward (smooth bump near zero post-residual)
    score -= 12.0 * (-post / 8.0).exp();

    // Dead-space penalty: residual too small to plausibly fit future items
    let dead_threshold = 10.0;
    if post < dead_threshold {
        let t = (dead_threshold - post) / dead_threshold;
        score += 15.0 * t * t;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 5.0 * (-slack * 10.0).exp();
        } else {
            let gap = (nxt - post) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Stream-progress coupling: late in the stream, be more frugal with open bins
    let progress_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= progress_term * (post / cap) * 6.0;
    score += progress * 3.0 * (post / cap);

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    let open_f = open_bins_count as f64;
    score += 0.4 * (open_f - 1.0).max(0.0) * (post / cap);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.05 * (post - mean_residual).abs();

    // New-bin candidate: mild penalty so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into bands of cap/8
    let band = post_residual / (bin_capacity / 8).max(1);
    let band_penalty = match band {
        0 => -40.0,              // near-perfect fit, tiny dead space
        1 => -20.0,              // small residual, still attractive
        2 => 0.0,
        3 => 10.0,
        _ => 18.0,               // large dead space class
    };
    score += band_penalty;

    // Fine harmonic reward: post_residual divisible by common item classes
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 5 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 5.0; }
    } else {
        score -= 60.0; // perfect closure
    }

    // Lookahead coupling: reward if next item fits exactly or well in post_residual
    if next_item_size > 0 && next_item_size <= pr {
        let next_res = pr - next_item_size;
        score -= 12.0;
        if next_res % 10 == 0 { score -= 10.0; }
        if next_res == 0 { score -= 25.0; }
    } else if next_item_size > pr && pr > 0 {
        // residual too small for lookahead: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.4;
    }

    // Fraction-of-capacity residual penalty (non-linear)
    let frac = post_residual as f64 / cap;
    score += 25.0 * frac * frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current open bins are nearly full on average
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = mean_residual / cap;
        score = 55.0 + 40.0 * (1.0 - crowding) - 20.0 * progress;
        if fitting_bins_count == 0 { score -= 45.0; }
    }

    // Mild preference to fill bins when many are open
    score += open_bins_count as f64 * 0.5;

    // Slight tie-break toward larger items placed now
    score -= item_size as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it is smaller than the smallest conceivable item (1),
    // but practically: gaps below the next item's size and below typical small items
    // are hard to fill. Penalize quadratic-like for tiny gaps.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            // gap too small for most items -> strong dead-space penalty
            score += (10.0 - pr) * 8.0;
        } else if post_residual < 20 {
            // small gap zone: harder to fill
            score += (20.0 - pr) * 2.0;
        }
        // Reward near-perfect fits
        if post_residual <= 2 {
            score -= 30.0;
        } else if post_residual <= 5 {
            score -= 15.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open bins pressure: discourage opening/spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 25.0 + open_bins_count as f64 * 2.0;
        // but if no open bin fits well, new bin becomes viable
        if post_residual >= 20 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item can use this bin's post_residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post_residual is just barely below next item (wasted for lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Stream progression: early on, be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor bins whose residual exactly matches the item.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Slack after the lookahead placement is penalized quadratically.
            let slack = post_residual - next_item_size;
            score -= 150.0 - (slack as f64).powi(2) * 0.08;
        } else {
            // Next item won't fit in the leftover: penalize large leftovers mildly.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 50.0;
    }

    // Tightness relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or the stream is early (room to exploit later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_pressure = item_size as f64 / bin_capacity as f64;
        score = 60.0 + size_pressure * 40.0 - progress * 20.0
            - if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 30.0 } else { 0.0 };
    }

    // Mild pressure against hoarding many open bins with large residuals.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit bias: strongly prefer tight fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Dead-space penalty: residual that is too small to ever be useful again
    // (minimum plausible item is 1, but small slivers below a threshold are waste).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 2.0 * post_residual as f64;
    }

    // Lookahead: reward if the next item fits exactly in the post residual
    // (perfect chaining), penalize if next item would be blocked while other
    // bins could still host it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // next item cannot go here; mild penalty scaled by how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.2 * (post_residual as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity and open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Penalize new bins early / when many bins are open; reward when open bins are crowded.
        score += 15.0 + 10.0 * (1.0 - avg_fullness) + 0.3 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        score += 10.0 * progress;
        // But if the item is huge, a fresh bin is actually fine.
        score -= 0.25 * item_size as f64;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalizing outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small global pressure: with many open bins, favor filling existing ones harder.
    score -= 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: squared post-residual penalizes wasted space quadratically.
    let mut score = post * post / cap;

    // Smooth stream-progress coupling: later in stream, waste is costlier.
    score += 12.0 * (post / cap) * (post / cap) * progress;

    // Reward leaving room for the lookahead item (smooth gate via fit ratio).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let tight = 1.0 - (post - nxt).abs() / cap;
            score -= 8.0 * tight.max(0.0);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post / cap);
    }

    // Penalize fragmenting bins with large residuals when many bins are open.
    score += 0.6 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Pull toward mean residual: avoid creating outliers (smooth quadratic).
    score += 0.15 * (post - mean_residual) * (post - mean_residual) / cap;

    // New-bin candidate: only attractive when current bins are too full.
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let pressure = (avg / cap).powi(2);
        score = cap * (0.9 - 0.8 * pressure) + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot class" does the leftover belong to?
    // Classes: tiny (<=10), small (11..25), medium (26..50), large (51..99), exact (0)
    let post = post_residual;
    let class_penalty: f64 = if post == 0 {
        -60.0 // perfect fit is gold
    } else if post <= 10 {
        -35.0 // dead space too small for any item (min size 1..100, but small waste ok)
    } else if post <= 25 {
        -10.0 // usable by small items
    } else if post <= 50 {
        5.0 // half-ish leftover, moderately useful
    } else {
        15.0 // big leftover, but item was small: wasteful pairing
    };
    score += class_penalty;

    // Lookahead coupling: does next_item_size fit into post_residual? (harmonic match)
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= post {
            // modulo-harmony: leftover after chaining next item
            let chain_left = post - next_item_size;
            score -= 8.0 + (chain_left as f64) * 0.15;
            if chain_left <= 10 { score -= 12.0; } // near-perfect double fit
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += 6.0 + (next_item_size - post) as f64 * 0.1;
        }
    }

    // Tightness reward: fraction of bin consumed by this item
    let fill = item_size as f64 / cap;
    score -= fill * 25.0;

    // New-bin candidate logic: empty bin gets a baseline score
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if few bins fit the item
        // and current open bins have poor residual structure.
        let scarcity = (fitting_bins_count as f64).max(0.0);
        let pressure = 30.0 / (1.0 + scarcity * scarcity);
        // penalize opening bins early in the stream mildly, later more if many open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 * 2.0 * (0.3 + 0.7 * progress);
        score += 55.0 - pressure + open_pressure;
        // if the item is huge, a fresh bin is often best (no fragmentation)
        if item_size >= 60 { score -= 25.0; }
    } else {
        // Reward using bins that are scarce fits (last-chance bin)
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins whose residual deviates from mean in a useful way:
        // using a bin with small residual keeps big residuals for big future items.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Integer-division threshold: residual bucket alignment (harmonic classes of 20)
    let bucket = post / 20;
    score -= (bucket % 3) as f64 * 2.0;

    // Mild preference for bins with residual exactly matching item + small waste
    if post > 0 && post < item_size {
        score += 3.0; // item dominated the bin: fine, small score bump handled by fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 3.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Dead space relative to the next item's needs.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // New-bin candidate: only attractive when the item fits badly everywhere else.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            // Opening a new bin wastes the residual of existing bins.
            score += 12.0 + 0.8 * mean_residual.min(60.0);
            if fitting_bins_count == 1 {
                score -= 10.0; // last-chance bin beats opening a new one
            }
        }
    }

    // Last-chance pressure: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: discourage proliferation of many open bins
    // unless this is a genuinely tight placement.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early in the stream, prefer filling existing bins to establish dense packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // leftover space, strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step match
        } else if post_residual >= next_item_size {
            score -= 15.0; // next item still fits after this placement
        } else {
            // post_residual < next_item_size: leftover is dead space for the
            // lookahead; penalize proportionally to how "wasted" it is.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 25.0 * (1.0 - waste);
        }
    }

    // Compare residual against the mean residual across open bins:
    // placing into a bin already below-average residual fragments space.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: make it attractive only when the current
    // item is large (poor fit anywhere) or no open bin fits well.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 30.0;
        } else {
            score += 20.0 + 0.3 * item_size as f64;
        }
    }

    // Mild progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to hold a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the fleet average residual.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Time horizon: early in the stream, be more conservative about filling bins;
    // later, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Many open bins: encourage consolidation into existing bins.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless current item is huge
    // and no bin is a good fit (post_residual of empty bin = capacity - item).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 20.0 + 0.2 * waste - 25.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); late in the stream,
    // dead space is more costly, so amplify post_residual quadratically.
    let prn = pr / cap;
    score += 40.0 * prn * prn * (0.5 + progress);

    // Reward filling bins completely (small post_residual) more aggressively
    // as the stream progresses.
    score -= 25.0 * (1.0 - prn) * (1.0 - prn) * progress;

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item could fit into the post_residual, reward
    // leaving that space (smooth interaction, no hard thresholds).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Slight penalty when many bins are open, encouraging consolidation.
    score += (open_bins_count as f64).ln1p() * 2.0 * (1.0 - progress);

    // New-bin candidate: make it mildly unattractive unless residuals are poor.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "reusable"
    // residue classes (multiples of common item granularities) are preferred.
    let post = post_residual;
    let harmonic_bonus = if post == 0 {
        -40.0 // perfect closure is excellent
    } else if post % 10 == 0 {
        -18.0
    } else if post % 5 == 0 {
        -10.0
    } else if post >= 10 && post <= 20 {
        -6.0 // leftover can host small future items
    } else if post < 10 {
        12.0 // dead space: small unusable sliver
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold: leftover "tier" — coarse quantization of fit quality
    let tier = post / 25; // 0..=4
    score += match tier {
        0 => 6.0,   // tiny leftover, wasteful
        1 => -4.0,  // sweet spot ~25-49
        2 => -2.0,
        3 => 0.0,
        _ => -3.0,  // near-empty bin kept flexible
    };

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post && (post - next_item_size) < 10 {
            score -= 14.0; // next item nearly fills this bin
        } else if next_item_size > post {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if post < 10 && post > 0 {
            score -= 20.0; // prefer fresh bin over creating sliver
        } else if fit_ratio > 0.8 {
            score -= 8.0;  // large item: fresh bin keeps big residual elsewhere
        } else {
            score += 25.0; // otherwise reuse open bins
        }
    }

    // Modulo class of item size: odd-granularity items pack better into
    // bins with matching residue class of residual.
    let item_mod = item_size % 10;
    let res_mod = bin_residual % 10;
    if item_mod == res_mod {
        score -= 3.0;
    }

    // Stream progression: late in the stream, close bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Spread pressure: prefer bins below mean residual when many bins open
    if open_bins_count > 3 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += dev * 10.0; // favor below-average-residual bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Core: penalize post_residual, especially small "dead" gaps that are hard to fill.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 500.0;
    } else if pr < 10.0 {
        // Tiny unusable gap: heavy dead-space penalty.
        score += 300.0 + pr * 10.0;
    } else {
        // Usable residual: mild penalty scaled by how much is left.
        score += pr * 1.5;
    }

    // Reward bins whose residual tightly matches the item (small waste relative to bin).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Prefer bins with lower residual than the mean (better filling bins first).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, discourage opening another one.
    let open_pressure = open_bins_count as f64 * 5.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open pressure, but reward if it enables
        // a good pairing with the next item.
        score += 80.0 + open_pressure;
        if next_item_size > 0 {
            let pair_waste = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).max(0) as f64;
            score += pair_waste * 1.2;
            if pair_waste == 0.0 {
                score -= 200.0; // perfect two-item pairing in a fresh bin
            }
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.9 {
            score += 50.0; // late in stream, avoid scattering
        }
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // This bin can also host the next item: reward.
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty proportional to blocked gap.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) but penalize tiny unusable slivers.
    if post_residual > 0 {
        let sliver = post_residual as f64;
        if sliver < 10.0 {
            score += (10.0 - sliver) * 2.5; // dead space penalty
        }
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly/well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            // perfect match for next item is highly desirable
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 6.0;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            let overflow = nxt - pr;
            if overflow < 30.0 {
                score += overflow * 0.15;
            } else {
                score += 4.5;
            }
        }
    } else {
        // last item: just minimize waste
        score -= 1.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are "loose";
    // placing a small item into a loose bin is fine, into a tight bin is risky.
    let tightness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += tightness * 3.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 14.0; // default bias toward reusing open bins
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening a new bin is fine when fits are scarce
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // fresh bin preserves room for larger next item
        }
    }

    // Stream progression: early on, be conservative with new bins; late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild preference for spreading load when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear penalty on waste.
    let fit_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 60.0 * fit_ratio * fit_ratio;

    // Reward near-perfect packing: bonus when post_residual is tiny.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits the post residual, strongly reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 18.0 - 0.15 * slack.min(50) as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with low residual relative to the mean (denser bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty on proliferation of open bins early; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate handling: only attractive when current bins are poor fits
    // or the item is large and consolidation would waste space.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count <= 1 && (bin_residual - item_size) < next_item_size);
        if poor_fit {
            score -= 15.0 + 0.2 * item_size as f64;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Slight time-dependent tightening: later in stream, favor tighter fits more.
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * fit_norm * (1.0 - fit_norm));

    // Stream-progress coupling: penalize waste more as stream progresses.
    score += 40.0 * progress * fit_norm * fit_norm;

    // Perfect-fit reward (smooth bump near zero residual).
    score -= 25.0 * (-pr / 8.0).exp();

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 15.0 * (-gap / 20.0).exp();
        } else {
            score += 8.0 * (1.0 - (-(-gap) / 30.0).exp());
        }
    }

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly discouraged early, more acceptable later.
    if bin_residual == bin_capacity {
        score += 20.0 - 25.0 * progress + 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mean-residual coupling: avoid creating outliers far from mean residual.
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo common size classes
    let pr = post_residual;
    let class = pr % 10; // fine-grained harmonic class
    // Penalize residuals that fall into "dead" classes (small nonzero remainders)
    if pr > 0 && pr < 10 {
        score += 12.0; // tiny unusable sliver
    } else {
        let dead_penalty: f64 = match class {
            1..=4 => 4.0,
            5..=7 => 2.0,
            8 | 9 => 0.5,
            _ => -1.0, // exact multiple of 10 is re-usable
        };
        score += dead_penalty;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic compatibility: next item fits exactly in post_residual classes
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size < pr {
            let leftover = pr - next_item_size;
            score += (leftover % 10) as f64 * 0.6 + leftover as f64 * 0.05;
        } else {
            score += 3.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Fraction-of-capacity coupling on residual classes
    let frac = bin_residual as f64 / cap;
    if frac > 0.5 {
        score -= (frac - 0.5) * 8.0; // prefer filling large-residual bins
    }

    // New-bin candidate: only attractive when no good harmonic class exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64;
        if good_fit_exists {
            score += 15.0 + 10.0 * progress;
        } else {
            score -= 5.0;
        }
    }

    // Mild preference for tight residual relative to mean
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Integer-division threshold: bins with residual in [item, item+9] are prime targets
    if bin_residual / 10 == item_size / 10 && post_residual < 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals below the minimum item size (1..=10) are unusable "dead" gaps.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // heavy penalty for creating unusable slivers
    }
    // Near-perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0; // still nearly perfect, mild bonus despite sliver risk
    }

    // --- Tightness coupling: reward small post_residual relative to capacity ---
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // --- Open bins pressure: discourage spreading when many bins are open ---
    score += (open_bins_count as f64).sqrt() * 2.0;

    // --- Last-chance bin: strongly favor using the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine if this bin would leave a big useless gap
        // or if no existing bin fits well; otherwise penalize opening.
        if post_residual <= 10 && post_residual > 0 {
            score += 200.0; // never open a bin to create dead space
        }
        if fitting_bins_count > 0 {
            score += 25.0; // prefer existing bins by default
        }
        // Lookahead: if next item fits nicely into the would-be post_residual
        // of an existing placement, opening is less attractive.
        if next_item_size > 0 && next_item_size <= item_size {
            score += 10.0;
        }
        score -= 5.0; // small base bonus so it's a viable fallback
    }

    // --- Lookahead synergy: reward bins whose post_residual matches next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // residual too small for lookahead item
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter) ---
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // --- Stream progression: late in stream, be more conservative about new bins ---
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step matches: post_residual equals next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect fill chain bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize dead space that next item cannot use
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless residual is huge (few alternatives)
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Penalize tiny unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Prefer larger items placed early in stream (tight packing later)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.2 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic bonus for small post residual.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: residual after placement that cannot host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Absolute dead space relative to lookahead item.
            let waste = (next_item_size - post_residual) as f64;
            score += 2.5 * waste;
            // Extra penalty if the next item is large (hard to place elsewhere).
            let la_frac = next_item_size as f64 / bin_capacity as f64;
            score += 20.0 * la_frac * la_frac;
        } else {
            // Reward bins that remain usable for the lookahead item.
            let snug = (post_residual - next_item_size) as f64;
            score -= 1.5 * (1.0 - snug / bin_capacity as f64);
        }
    } else {
        // Last item: minimize post residual aggressively.
        score += 0.5 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin gets a base cost that scales with
    // how many bins already exist and how much total residual capacity is idle.
    if bin_residual == bin_capacity {
        let idle = (mean_residual * open_bins_count as f64) / bin_capacity as f64;
        score += 18.0 + 6.0 * idle + 0.4 * open_bins_count as f64;
        // Late in the stream, opening bins is cheaper (fewer future items to strand).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // But if next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is close to the mean (balance load), mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer fuller bins early on to consolidate open bins.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill * (1.0 - if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling: residual value decays with stream progress (late residual is worth less)
    let decay = (1.0 - progress).powf(1.5);
    score += post * (1.0 - decay) * 0.5;

    // Penalize residuals that cannot fit the next item (dead space), smoothly scaled
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += (nx - post) * (1.0 + 0.5 * (nx / cap));
        } else {
            score -= 1.5 * (1.0 - (post - nx) / cap);
        }
    }

    // Reward tight fits: polynomial in fill ratio
    let fill = 1.0 - post / cap;
    score -= 4.0 * fill * fill * fill;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        score += 0.4 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild preference to spread load when many bins open
    score += 0.3 * (mean_residual - post) / cap;

    // Smooth penalty on opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 * (0.5 + 0.5 * progress) * (1.0 + 0.5 * decay);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (item granularity class)
    let res_class = post_residual % 10;
    let res_quot = post_residual / 10;

    // Reward post-residuals that are "usable" harmonic classes.
    // Small post_residual (< 10) is dead space -> penalize heavily.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect packing
    } else {
        // Reward residual classes divisible into common item sizes (10,20,25,50)
        if post_residual % 20 == 0 { score -= 6.0; }
        else if post_residual % 25 == 0 { score -= 5.0; }
        else if post_residual % 10 == 0 { score -= 4.0; }
        else if res_class == 5 { score -= 2.0; }
        else { score += (res_class as f64) * 0.8; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // reward chains where next placement also leaves a harmonic residual
            if next_post == 0 { score -= 15.0; }
            else if next_post % 10 == 0 { score -= 8.0; }
            score += (next_post % 5) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize leaving large stranded space
            if post_residual > 30 { score += 8.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // but if item is large (>= half capacity), a fresh bin is natural
        if item_size * 2 >= bin_capacity { score -= 25.0; }
        if fitting_bins_count == 0 { score -= 45.0; }
    }

    // Prefer filling bins with low mean residual (tight bins) mildly
    score += (mean_residual - post_residual as f64) * 0.15;

    // Early stream: be conservative (favor tight fits); late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    // Slight preference for bins with residual close to item (tight fit)
    let tight = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += tight * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot fit even the smallest plausible item (<= ~10)
    // is pure waste; scale penalty by how "stuck" the gap is.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0; // hard penalty for near-dead space
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 6.0; // soft penalty for tight gaps
    }

    // Nonlinear dead-space penalty: gaps that cannot fit the lookahead item
    // are likely dead; penalize proportionally to the shortfall.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (favor small post_residual relatively more).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make the empty bin moderately attractive only when
    // the current fit is bad (large post_residual) or no bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        score += 60.0 - 120.0 * bad_fit; // low score only if item is small in empty bin
        if post_residual > 40 {
            score -= 70.0; // poor fit elsewhere: opening a new bin is fine
        }
    }

    // Mild lookahead synergy: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space nonlinearly (worst around tiny residuals).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 4.0;
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let diff = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        score -= 30.0 / (1.0 + diff);
        // Perfect chain: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0;
    }

    // Prefer bins with residual below mean residual (denser bins first).
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 15.0 + 25.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
        // Allow new bin if item is large and lookahead suggests a chain.
        let chain_bonus = if next_item_size > 0 && post_residual >= next_item_size { 10.0 } else { 0.0 };
        score += penalty - chain_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 25.0;

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer filling already-open bins over spreading; penalize when many bins open.
    if bin_residual != bin_capacity {
        score -= 12.0;
        score -= open_bins_count as f64 * 1.5;
    } else {
        // New-bin candidate: penalize unless it's early in the stream or item is large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 25.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Favor bins whose residual deviates favorably from the mean residual
    // (a bin with less residual than average is closer to being closed out).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Mild time-horizon term: early in stream, be slightly more conservative
    // about creating tiny residuals; late, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: small nonzero residuals are wasted capacity.
    // Smoothly strongest when post_residual is tiny but positive.
    let dead = (1.0 - post / cap).powi(12) * (cap / (post + 1.0)).sqrt();
    score += 6.0 * dead;

    // Perfect fill reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = post - nxt;
            score -= 8.0 * (1.0 - slack / cap) * (1.0 - progress);
        } else {
            // Residual too small for next item: mild penalty growing with progress.
            score += 4.0 * (nxt / cap) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a new bin when other bins fit,
    // unless this bin's residual is large (poor fits elsewhere justify a fresh bin).
    if bin_residual == bin_capacity {
        let base = 15.0 + 10.0 * (open_bins_count as f64).ln1p() + 20.0 * progress;
        let escape = if fitting_bins_count > 0 {
            let mean_fit = mean_residual.max(0.0);
            30.0 / (1.0 + (mean_fit / cap).powi(2) * 8.0)
        } else {
            60.0
        };
        score += base - escape;
    }

    // Mild preference for bins with residuals close to the item (tight fit),
    // via smooth interaction of item size with residual.
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 3.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear emphasis.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals that are hard to fill later.
    // Harmonic classes: classify post_residual into "useless" classes.
    let pr = post_residual;
    if pr > 0 {
        // Small leftovers (< 20) are near-dead space for typical items (min size 1..100 unknown,
        // but small residuals waste capacity).
        if pr < 15 {
            score += 18.0 * (15.0 - pr as f64);
        } else if pr < 30 {
            score += 6.0 * (30.0 - pr as f64) / 15.0;
        }
        // Modulo arithmetic: leftover that is a multiple of common item sizes is reusable.
        let reusable = [10, 20, 25, 30, 40, 50, 60, 70, 80];
        let mut bonus = 0.0;
        for &k in &reusable {
            if k <= pr && pr % k == 0 {
                bonus += 5.0;
            }
        }
        score -= bonus;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: mild penalty proportional to overflow.
            score += 4.0 * ((next_item_size - pr) as f64 / 50.0).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits more aggressively.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: empty bin gets a moderate default score so that
    // only genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = 55.0
            - 8.0 * (mean_residual / bin_capacity as f64).min(1.0)
            - if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        // Late in the stream, slightly discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the smallest
    // future item are pure waste -> heavy nonlinear penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // completely unusable gap
        } else if post_residual < 20 {
            score += 25.0; // only fits tiny items
        } else if post_residual < 30 {
            score += 8.0;
        }
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bonus: this is the only bin that fits; avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            score += 6.0; // next item won't fit here; slight penalty
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; a new empty bin candidate gets
    // penalized proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 20.0 + 6.0 * open_bins_count as f64;
        // Late in the stream, opening a new bin is less costly (fewer future
        // items to consolidate), so ease the pressure slightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
    } else {
        // Existing-bin placements get a mild reward scaled by open-bin count.
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the mean (balanced closing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement; reward tightness of the pair.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + gap / 10.0);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.15 * dead;
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let mean_r = mean_residual.max(0.0);
    let pr = post_residual as f64;
    if pr < mean_r {
        score -= 0.30 * (mean_r - pr);
    } else {
        score += 0.10 * (pr - mean_r);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin would leave large unusable dead space.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64 - next_item_size as f64;
        if next_item_size == 0 {
            score += 5.0; // last item: never open a new bin
        } else if item_size + next_item_size > bin_capacity {
            // Pair doesn't pack together anyway; new bin is fine.
            score -= 15.0;
        } else if waste > 15.0 {
            score += 10.0 + 0.2 * waste;
        } else {
            score += 25.0;
        }
    }

    // Mild pressure against bin proliferation late in the stream.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item can fit into the post-residual, this is a
    // good pairing; penalize if the post-residual is just barely too small
    // for the next item (dead space trap).
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
        } else if (post_residual as i64) > 0
            && (post_residual as i64) >= (next_item_size as i64) - 10
        {
            score += 10.0; // near-miss dead space
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize spreading thin); late in the stream, consolidate.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 6.0 * progress;

    // Compare against mean residual: bins with residual far below mean are
    // already "wasted"; prefer to fill those rather than healthy bins.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * tightness;

    // New-bin candidate: only attractive if no open bin fits well
    // (post_residual of an empty bin is large, so base score already
    // penalizes it; add a mild extra penalty so it's chosen only when
    // desperate).
    if bin_residual == bin_capacity {
        score += 15.0;
        // but late in the stream with many bins, opening fresh may still win
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: reward small post_residual quadratically, stronger later in stream
    let pr = post_residual as f64;
    let tight_fit_bonus = -(pr * pr) / bin_capacity as f64 * (0.5 + 1.5 * progress);
    score += tight_fit_bonus;

    // Penalize dead space far from mean residual (misfit bins) with smooth cubic term
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / bin_capacity as f64;

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more later unless item is large relative to capacity
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let next_ratio = next_item_size as f64 / bin_capacity as f64;
        // Opening a bin is better when item is big and next item likely fits leftover
        let leftover_fits_next = (pr >= next_item_size as f64) as i32 as f64;
        score += 25.0 - 15.0 * size_ratio - 10.0 * leftover_fits_next - 10.0 * progress * (1.0 - size_ratio);
    }

    // Mild penalty for spreading across many open bins (fragmentation), smooth in count
    score += 0.3 * (open_bins_count as f64).ln();

    // Smooth lookahead reward: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and "usable" residuals
    // (residuals that can host common small items) should be rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Penalize dead space: residuals too small for the smallest item class.
        if pr < 10 {
            score += 40.0; // unusable sliver
        } else {
            // Reward residuals that match common item sizes (harmonic classes mod 10).
            let class = pr % 10;
            if class == 0 {
                score -= 12.0; // round residual, easy to fill later
            } else if class >= 5 {
                score -= 4.0;
            } else {
                score += 6.0; // awkward class
            }
            // Quadratic waste penalty scaled by how much of the bin remains.
            let frac = pr as f64 / cap;
            score += 30.0 * frac * frac;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 15.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // Opening a new bin costs more early on (bins are precious later is fine).
        score = 50.0 + 40.0 * (1.0 - progress) + 5.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
        // Big items prefer fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mild preference to balance residuals across open bins.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Tiny tie-breaking toward later bins (keeps older residuals for small items).
    score += 0.001 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (<=10) are nearly unusable
    // for future items (min item size 10). Penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0; // moderately risky gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    }

    // Tightness reward: the fuller the bin becomes, the better (beyond raw residual).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins
    // are open; make the fresh-bin call less attractive as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // But if the item would leave a huge usable residual and next item is large,
        // a fresh bin can be reasonable; soften slightly.
        if next_item_size > 0 && next_item_size >= item_size + 20 {
            score -= 15.0;
        }
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving a gap
        // that neither this nor the next item can use well.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Mean-residual coupling: if this bin is far below the mean residual
    // (i.e., it's the tightest bin), prefer packing here to consolidate.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev.clamp(0.0, 40.0) * 0.5;
    }

    // Mild stream progression: later in the stream, be more conservative
    // about creating dead space.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if post_residual > 0 && post_residual <= 10 {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that leave small post-residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing (typical small items) can ever reuse.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly-perfect fill
    }
    if post_residual > 50 {
        score += 6.0; // large leftover but item was small: wasteful
    }

    // Lookahead: bonus if the next item fits exactly in the post-residual,
    // penalty if placing here blocks the next item from fitting.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            let pair_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else (large item, few fitting bins)
    // or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 55.0 + 40.0 * (1.0 - big_item) - 25.0 * scarcity - 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can serve the next big item too
        }
    }

    // Global state coupling: if mean residual across open bins is high,
    // prefer consolidating into existing bins rather than spreading.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Mild preference for bins with residual close to a "nice" multiple structure:
    // leaving residuals that combine with common small items (10..=20) is good.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 5.0;
    }

    // Time horizon: late in the stream, avoid opening bins aggressively
    // (already handled) and slightly favor filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; later, tight fits are strongly favored.
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    let progress_coupling = tightness * tightness * (0.5 + 2.5 * progress);
    score -= 6.0 * progress_coupling;

    // Non-linear penalty on unusable dead space (residual too small for typical items),
    // smoothly weighted by progress.
    let dead = (pr / cap).powi(2);
    score += 12.0 * dead * (0.3 + 1.7 * progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward residual that could still fit the next item,
    // penalize residual that wastes space the next item could use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - (pr - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for bins deviating from mean residual (consolidate waste),
    // smooth quadratic coupling.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let urgency = (fitting_bins_count == 0) as i32 as f64;
        score += 10.0 - 8.0 * urgency - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is divisible by
    // common item sizes (10/20/25/50) are more reusable.
    let pr = post_residual;
    let harmony = if pr == 0 { 30.0 }
        else if pr % 10 == 0 { 12.0 }
        else if pr % 25 == 0 || pr % 20 == 0 { 8.0 }
        else { 0.0 };
    score -= harmony;

    // Dead-space penalty: tiny unusable remainders that fit few future items.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit reward scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr == 0 {
        score -= 40.0 * (0.5 + progress);
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // bonus if next item exactly fills leftover (harmonic pairing)
            if next_item_size == pr {
                score -= 20.0;
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += 6.0 * (1.0 - pr as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer tighter bins relative to mean residual.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 15.0;
    } else {
        score -= 5.0;
    }

    // Integer-division threshold on residual classes (harmonic buckets of 10).
    let bucket = bin_residual / 10;
    score -= bucket as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly punish tiny unusable dead space (< 10), reward exact fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward residuals that can still host mid-size items later.
    if post_residual >= 10 && post_residual <= 50 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full/congested.
    if bin_residual == bin_capacity {
        score = 55.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 50.0; // never open when a last-chance bin exists
        }
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Prefer packing into bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Lookahead: bonus if post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Early in the stream, be slightly more willing to fill existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0); // perfect lookahead match => biggest bonus
    }
    // Penalize post_residual too small to ever be useful (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it mildly unattractive unless item is huge relative to residual
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * fill_frac;
    }

    // Late in stream: prefer tighter packing, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed — a soft time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: quadratic penalty on wasted space, amplified early
    // when conserving bin quality matters most.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac * (1.5 - progress);

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it, otherwise residual is stranded.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 0.2 * bin_residual as f64;
    }

    // Scarcity pressure: when few bins can fit the item, prefer good fits more.
    if fitting_bins_count >= 2 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this bin is doubly valuable; if next item can't use the residual, penalize.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            let gap = post_residual as f64 - nr;
            if gap <= 5.0 {
                score -= 35.0;
            } else {
                score += 0.15 * gap;
            }
        } else if (post_residual as f64) < nr && post_residual > 0 {
            // residual too small for the next item: dead-space risk grows
            score += 0.25 * (nr - post_residual as f64).min(50.0);
        }
    }

    // Global-state coupling: many open bins with large mean residual ->
    // prefer filling existing bins rather than spreading out.
    if open_bins_count > 2 && bin_residual != bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.1 * spread;
        score -= 0.05 * mean_residual.min(50.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. Base new-bin cost, discounted by how
    // much room a fresh bin leaves relative to this bin's post-residual.
    if bin_residual == bin_capacity {
        let mut open_cost = 55.0 + 3.0 * open_bins_count as f64;
        // late in the stream, opening bins is cheaper than stranding space
        open_cost *= 1.0 - 0.4 * progress;
        // a fresh bin always fits the next item; value that when residuals are tiny
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            open_cost -= 25.0;
        }
        score += open_cost;
    }

    // Mild preference for bins whose residual is just above the item
    // (classic best-fit sharpening).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Core: prefer small post_residual, with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress) + 0.35 * pr * pr / cap;

    // Reward tight fits (small post_residual relative to item size) more strongly late in stream
    let tightness = 1.0 - (pr / cap).powf(1.5);
    score -= 12.0 * tightness * fit_ratio * (0.5 + 0.5 * progress);

    // Penalize dead space that next item likely cannot use
    if next_item_size > 0 {
        let waste = (post_residual.min(next_item_size.saturating_sub(1))).max(0) as f64;
        score += 0.6 * waste * (0.5 + 0.5 * progress);
        // Reward bins whose residual exactly accommodates the next item
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across many open bins; encourages consolidation
    score += 0.15 * (open_bins_count as f64).ln();

    // Discourage opening new bins when mean residual is large
    score += 0.05 * (mean_residual - pr).max(0.0);

    // New-bin candidate: penalize unless residual is unusable
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * progress - 0.5 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Chain bonus: if the lookahead item fits exactly into post_residual,
    // this bin is a harmonic pair — reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_residual = post_residual - next_item_size;
        score -= 120.0 - (chain_residual as f64) * 0.8;
    }

    // Dead-space penalty: post_residual too small for ANY plausible item
    // (min size 1) is only bad if it's tiny and the next item can't use it.
    if next_item_size > post_residual {
        // Fractional class of post_residual relative to capacity.
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.10 {
            score += 60.0; // unusable sliver
        } else if frac < 0.25 {
            score += 25.0; // only fits very small items
        } else {
            score += 5.0; // still generically usable
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin has post_residual = C - item.
    // Prefer it when the item is large (poor fit anywhere) or when open
    // bins are already crowded (low mean residual).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let crowded = mean_residual / bin_capacity as f64;
        score -= 30.0 * item_frac + 50.0 * (1.0 - crowded);
        // Don't open a new bin for a small item late in the stream.
        if item_frac < 0.35 && open_bins_count > 0 {
            score += 45.0;
        }
    } else {
        // Reward using existing bins proportional to how full they'd become.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 20.0 * fill;
    }

    // Mild stream-progression pressure: late in the stream, consolidation
    // matters more, so tighten preference for tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 - 2.5 * post_residual as f64;
    } else if post_residual > 12 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward tight fits (perfect fill is ideal).
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the next item exactly fits the post residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 8 {
        score -= 25.0;
    }
    // Penalize if post residual cannot hold the next item (wasted potential).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.3;

    // New-bin candidate handling: a fresh empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream or with few bins.
        score = bin_capacity as f64 - 12.0 * progress - (open_bins_count as f64).min(6.0);
        if fitting_bins_count <= 1 {
            score += 25.0; // keep using the last fitting bin instead
        }
        // If mean residual across open bins is small (bins nearly full), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Mild preference for bins whose residual is close to the item (best-fit coupling).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 6.0;
        // Favor bins below mean residual (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are excellent: strongly reward zero / tiny post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly matches
    // the post residual (chain placement), penalize when next item leaves
    // awkward dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 500.0; // perfect chained fit
        } else if post > nxt {
            // next item fits too: mild bonus proportional to leftover after both
            let double_left = post - nxt;
            if double_left <= 5.0 {
                score -= 150.0 - double_left * 10.0;
            } else {
                score += double_left * 0.5; // accumulating dead space
            }
        } else {
            // next item cannot use this residual: dead space penalty
            score += (nxt - post) * 0.8;
        }
    }

    // Compare residual to mean residual across open bins:
    // prefer filling below-average-residual (tighter) bins.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (post_f - mean_residual) * 0.6;
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when good fitting options exist,
    // more strongly early in the stream and when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 120.0 * (1.0 - progress * 0.5);
        if fitting_bins_count > 0 {
            new_bin_penalty += 80.0 + (post_f.min(30.0)) * 2.0;
        }
        // If next item is large and this fresh bin could chain two placements,
        // soften the penalty.
        if next_item_size > 0 && (next_item_size as f64) <= post_f {
            new_bin_penalty -= 60.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for tighter existing bins as stream matures.
    score += post_f * (0.1 + 0.4 * (step_index as f64 / total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual small relative to capacity
    score -= (1.0 - fill) * (bin_capacity as f64) * 0.5;

    // Penalize dead space that is too small to be useful for typical items:
    // residuals in (0, 10) are pure waste; residuals >= 10 may fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins could fit, especially early/mid stream
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_f = open_bins_count as f64;
        score += 20.0 + open_f * 3.0 * (1.0 - progress);
        // But if existing fitting bins are all poor fits (large post_residual),
        // opening a new bin becomes relatively more attractive: subtract based on
        // how bad typical fits are.
        let mean_waste = (mean_residual - item_size as f64).max(0.0);
        if mean_waste > 20.0 {
            score -= (mean_waste - 20.0) * 0.6;
        }
        // New bin with the item inside leaves residual = capacity - item_size,
        // which is exactly post_residual here; reward perfectly packing a fresh bin.
        if post_residual <= 5 {
            score -= 15.0;
        }
    }

    // Global balance: prefer bins whose residual is close to the mean residual
    // (keeps open bins uniformly filled, leaving big gaps consolidated).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild time-varying exploration: late in the stream, be greedier about tight fits
    score -= (1.0 - fill) * progress * 10.0;

    // Prefer filling bins that are already quite full (low residual) to close them out
    if bin_residual as f64 <= mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let coupling = pr * pr * (1.0 - progress) * 10.0
                 + pr * progress * 5.0
                 + (pr * pr * pr) * 8.0 * (1.0 - progress) * progress;
    score -= coupling;

    // Penalize wasted space when few bins can fit the item (last-chance placement)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as f64 - nx).abs();
        score += 0.3 * diff * (1.0 - progress);
        if post_residual as f64 >= nx {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * progress;

    // Deviation from mean residual: prefer near-mean residuals
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio;

    // Harmonic class of post_residual: reward residuals that form "nice" slots
    // (multiples of common small sizes), penalize dead space.
    let pr = post_residual;
    if pr > 0 {
        let harmonic_bonus = match pr % 10 {
            0 => 25.0,
            5 => 12.0,
            _ => {
                // distance to nearest multiple of 10
                let d = (pr % 10).min(10 - pr % 10);
                -3.0 * d as f64
            }
        };
        score -= harmonic_bonus;

        // Integer division thresholds: residual divisible by next item size
        if next_item_size > 0 && pr % next_item_size == 0 && pr >= next_item_size {
            score -= 20.0;
        }
        // Perfect: next item exactly fills this bin
        if next_item_size > 0 && pr == next_item_size {
            score -= 45.0;
        }
        // Penalize if next item cannot fit here but residual is awkwardly large
        if next_item_size > 0 && next_item_size > pr {
            score += 8.0 * ((pr as f64) / 20.0).min(3.0);
        }
    } else {
        // Perfect fill
        score -= 80.0;
    }

    // Dead space penalty: superlinear in small residuals
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * (10 - pr) as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate logic: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // Opening new bin is expensive; only attractive when fit elsewhere is terrible
        let bad_fit_elsewhere = fitting_bins_count == 0
            || (fit_ratio < 0.55 && mean_residual > 40.0);
        if bad_fit_elsewhere {
            score -= 30.0;
        } else {
            score += 50.0;
        }
        // Slightly prefer opening bins early when many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (pack the emptier bins first)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild pressure against accumulating too many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A residual below the minimum item size (1) is impossible here, but residuals in
    // the "awkward" band (1..=10) are almost certainly dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual can't hold next item: mild penalty scaled by wasted fraction.
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it's only chosen when all fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    } else {
        // Prefer bins tighter relative to mean residual (better fit quality).
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // 2-step lookahead: strongly reward when the next item fits the post_residual exactly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 25.0 * next_tight;
        } else {
            // Next item cannot use the leftover; penalize proportional to wasted space.
            score += 0.35 * (post_residual as f64);
        }
        // Perfect chaining bonus: post_residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score += 0.6 * (post_residual as f64);
    }

    // Penalize bins with residuals far below mean (fragmented bins).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are poor,
    // but slightly less penalty late in the stream when spreading may help.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 8.0 * progress;
    }

    // Slight preference for filling bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += 30.0 * tight * tight;

    // Penalize bins whose residual is far below the mean (fragmented bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 20.0 - gap;
        } else {
            score += gap * 0.15;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // residual too small for next item: penalize dead space
        score += 10.0;
    }

    // Prefer filling older/more crowded bins slightly to keep bin count low
    score += (open_bins_count as f64) * 0.5;
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Time horizon: early on, be conservative (favor tight packing); late, just close bins out
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 5.0 * tight - t * 3.0;

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let threshold = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        score = 40.0 + threshold * 0.2;
        if fitting_bins_count <= 1 {
            score -= 45.0; // opening a new bin is right when nothing else fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in [0,1]
    let progress = if total_items > 1 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Tightness of fit: reward small post_residual non-linearly (quartic coupling)
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness * tightness * tightness * cap * 0.25;

    // Perfect-fit bonus (smoothed quadratic)
    if post_residual == 0 {
        score -= 30.0;
    } else {
        let pr = post_residual as f64;
        score += 0.02 * pr * pr / cap;
    }

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 6.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > 0 {
        // penalize leaving a gap that next item cannot use, scaled by progress
        score += 4.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins far below mean residual (fragmentation avoidance), smooth coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev.abs();

    // New-bin candidate handling: penalize opening a new bin, but relax the
    // penalty when this bin's fit would be very poor (large post_residual)
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / cap).max(0.0);
        score += 25.0 - 20.0 * poor_fit * poor_fit + 5.0 * progress;
    }

    // Mild preference to fill already-open bins as stream progresses
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual as u32;
    let cls = pr % 10; // fine-grained residue class
    // Reward residuals that sit in "usable" harmonic classes for typical item sizes.
    let usable = match cls {
        0 => 8.0,           // perfect fill
        1 | 2 => 4.0,       // near-perfect fill
        3..=7 => 1.5,       // still placeable for small items
        _ => 0.0,           // awkward sliver
    };
    score -= usable;

    // Integer-division thresholds: can a plausible next item (>=1) fit?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to tightness of the pair fit
            let pair_tight = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - pair_tight / cap);
        } else {
            // lookahead does not fit: penalize wasted residual
            score += 0.05 * post_residual as f64;
        }
        // coupling: if next item nearly equals post_residual, strong bonus
        let d = (next_item_size as i64 - post_residual as i64).unsigned_abs();
        if d <= 2 {
            score -= 9.0;
        } else if d <= 5 {
            score -= 4.0;
        }
    } else {
        // last item: maximize fill
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize new-bin candidate lightly so it's only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if mean residual across open bins is tiny (all bins nearly full),
        // opening a new bin is fine
        score -= (mean_residual / cap) * 10.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    // Progress-based nudge: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - post_residual as f64 / cap);

    // Non-linear penalty on large dead space (quadratic beyond half capacity).
    let half = cap * 0.5;
    if post_residual as f64 > half {
        let excess = post_residual as f64 - half;
        score += 0.08 * excess * excess / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can no longer fit the
    // minimum item (1) are pure waste, but residuals that are small enough
    // to be "hard to fill" (below typical item scale) are the real killers.
    // Penalize tiny-but-nonzero residuals super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 20.0 {
            // small gap: likely dead space, punish quadratically
            score += (20.0 - pr) * (20.0 - pr) * 0.35;
        } else if pr <= 50.0 {
            // mid gap: mildly awkward
            score += (50.0 - pr) * 0.4;
        } else {
            // large residual is reusable; reward keeping big usable space
            score -= 12.0;
        }
    } else {
        // perfect fill
        score -= 30.0;
    }

    // Reward exact-ish fits relative to bin residual (tight packing signal).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourages closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress) * 0.6;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the average (keeps the fleet homogeneous and predictable).
    score += (bin_residual as f64 - mean_residual).abs() * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item would be blocked by this placement, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how snugly the next item fits the leftover
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + snug * 15.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when no open bin offers a decent fit, by anchoring
    // its score near a moderate value.
    if bin_residual == bin_capacity {
        // base anchor: slightly worse than a good fit, better than a bad one
        score = 55.0 + (open_bins_count as f64) * 0.3;
        // if nothing else fits, new bin must win
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // late in the stream, be more willing to open fresh bins
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too; slightly favor leaving room.
            score -= (post_residual as f64 - next_item_size as f64).sqrt() * 3.0;
        } else {
            // Next item won't fit in this bin's leftover; penalize large unusable gaps.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 && gap > 0.0 {
                score += gap * 0.3;
            }
        }
    }

    // Compare residual against mean residual of open bins.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.2;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let base = 60.0 + (open_bins_count as f64).sqrt() * 10.0;
        let poor_fit_penalty = if fitting_bins_count == 0 { -150.0 } else { 0.0 };
        let waste = if post_residual as f64 > mean_residual { post_residual as f64 - mean_residual } else { 0.0 };
        score += base + waste * 0.5 + poor_fit_penalty;
    }

    // Mild pressure to consolidate bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual) with a non-linear squash
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize wasted residual that is too small for any plausible future item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the next item would fit *snugly* here
        let snug = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 6.0; // next item cannot use this bin's leftover
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with lower residual among equals (consolidation)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more conservative (favor new bins for flexibility);
    // late in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late
        score += 25.0 * (1.0 - progress) - 15.0 * progress;
        // Never open a new bin if an existing bin fits almost perfectly
        if post_residual < 5 && fitting_bins_count >= 1 {
            score += 40.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: super-linear penalty on leftover space (dead space grows in cost).
    let mut score = 0.6 * post + 0.012 * post * post;

    // Reward tight fits: fraction of bin consumed, smoothly amplified.
    let fill = fit / cap;
    score -= 18.0 * fill * fill;

    // Perfect/near-perfect fit bonus (smooth, non-piecewise).
    score -= 8.0 * (-(post * post) / 50.0).exp();

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 3.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Stream-progress modulation: as the stream matures, penalize leftovers harder
    // (fewer future chances to reclaim dead space).
    score += 10.0 * progress * (post / cap) * (post / cap);

    // Crowd-awareness: many open bins -> prefer consolidating into existing ones.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // New-bin candidate (bin_residual == bin_capacity): make it costly unless
    // the item is large enough that no open bin could plausibly do better.
    if bin_residual == bin_capacity {
        score += 22.0 - 10.0 * fill;
        // Late in the stream, opening bins is cheaper than fragmenting.
        score -= 8.0 * progress;
    }

    // Mild pull toward bins with residual close to what we consume (best-fit flavor).
    let dev = (bin_residual as f64 - fit - cap * 0.5) / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into quarters.
    let quarter = bin_capacity as f64 / 4.0;
    let post = post_residual as f64;

    // Reward tight fits (post_residual in lowest quarter).
    if post <= quarter {
        score -= 12.0 + (quarter - post) / quarter * 10.0;
    } else if post <= 2.0 * quarter {
        score -= 4.0;
    } else if post > 3.0 * quarter {
        // Large dead space penalty, scaled by how much exceeds the top quarter.
        score += (post - 3.0 * quarter) * 0.35;
    }

    // Modulo arithmetic on post_residual: residues divisible by common item
    // granularities (10s) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 5 == 0 {
            score -= 2.0;
        }
        // Residual exactly matching a plausible next-item class (10..80 step 10)
        let class = (pr / 10).min(8) * 10;
        if class >= 10 && next_item_size as i64 - class as i64 == 0 {
            score -= 8.0;
        }
    } else {
        // Perfect fill is ideal.
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + (pr as f64 - next_item_size as f64) * 0.15;
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty, worse if post_residual is small-ish.
        score += (next_item_size as f64 - pr as f64).min(30.0) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current open bins are all crowded
    // or this is a large item with nowhere good to go.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.6;
        let base = 20.0 + post_residual as f64 * 0.1 + open_bins_count as f64 * 0.5;
        score += if crowded { 6.0 } else { base };
        // Late in stream, prefer consolidation into open bins.
        if total_items > 0 && step_index as f64 / total_items as f64 > 0.7 {
            score += 8.0;
        }
    }

    // Mild preference for fuller bins overall (small residual before placement).
    score += (bin_residual as f64 - item_size as f64) * 0.02;
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for even the
    // smallest plausible item (or the known next item) are wasted forever.
    let min_useful = next_item_size.min(10).max(1) as f64;
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 60.0 + 0.5 * (min_useful - post_residual as f64);
    }

    // Reward near-perfect packing strongly (non-linear tight-fit bonus).
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 12 {
        score -= 8.0;
    }

    // Reward using a bin whose residual was already small (consolidation).
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - residual_ratio) * (1.0 - residual_ratio);

    // Last-chance bin: strongly prefer filling the only fitting bin
    // to avoid opening a new bin under pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // favor placing into existing bins over opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins fit poorly
    // (post_residual large) or when the item pairs perfectly with the next item.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.2;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Late in the stream, opening fresh bins is cheap.
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress;
    }

    // Lookahead: if the next item exactly fills the post-residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 6.0;
    }

    // Mild tie-break toward bins already below mean residual (tighter bins).
    score += 0.15 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect match with the next item (2-step lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial credit: next item fits here, reward closeness of the fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot use this leftover: penalize proportionally.
        let waste = next_item_size as f64 - post_residual as f64;
        score += waste * 0.4;
    }

    // Reward tight fits relative to current residual (small post_residual is good).
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Compare against mean residual: leaving more than average waste is penalized.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large (little residual waste)
    // or no real bin offers a decent fit.
    if bin_residual == bin_capacity {
        let waste_penalty = post_residual as f64 * 0.8;
        score += 15.0 + waste_penalty;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: opening a new bin is required
        }
    }

    // Early in the stream, be slightly more willing to open fresh bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference (small post_residual), slightly super-linear.
    score += (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Lookahead: reward if the next item fits into the post-residual (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.06 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize proportionally.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 4.0 * waste * waste;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when existing bins can fit the item.
    if bin_residual == bin_capacity && bin_capacity >= item_size {
        let has_alternatives = fitting_bins_count > 0;
        if has_alternatives {
            score += 10.0 + 0.5 * open_bins_count as f64;
        } else {
            score -= 2.0;
        }
    }

    // Time-horizon coupling: early in the stream, be more willing to open new bins
    // (long horizon to fill them); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 4.0 * (1.0 - progress);
    } else {
        score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    if open_bins_count > 0 {
        let density = mean_residual / bin_capacity as f64;
        score += density * (open_bins_count as f64).ln().max(1.0) * 1.5;
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 5.0; // near-perfect fit leaves almost unusable sliver: good.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 1.7 * progress * norm_pr + 0.9 * progress * progress);

    // Dead-space penalty: residuals too small to hold typical items
    let dead = if norm_pr > 0.0 && norm_pr < 0.12 { (0.12 - norm_pr) * 90.0 } else { 0.0 };

    // Lookahead coupling: reward residual that can hold the next item, penalize near-misses
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            -(0.55 * (1.0 - (pr - nxt) / cap))
        } else {
            0.35 * (nxt - pr) / cap
        }
    } else { 0.0 };

    // Last-chance bonus: strongly favor the only bin that fits
    let last_chance = if fitting_bins_count == 1 { -14.0 } else { 0.0 };

    // Mild pressure to consolidate when many bins are open
    let consolidation = -0.04 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Slight preference for tight fits relative to mean residual
    let mean_coupling = 0.25 * (norm_pr - mean_residual / cap);

    let mut score = poly * 10.0 + dead + lookahead + last_chance + consolidation + mean_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "nice"
    // (small or exactly matching likely future item sizes via modulo classes).
    let cap = bin_capacity as f64;

    // Strongly prefer tight fits.
    score -= 12.0 * (1.0 - (post_residual as f64) / cap);

    // Dead-space penalty: residuals in awkward mid-range (e.g. 20..50) that
    // few items can use are penalized super-linearly.
    if post_residual > 0 && post_residual < 50 {
        score += 8.0 * ((50 - post_residual) as f64 / 50.0).powi(3);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic class: post_residual divisible by common item granularities
    // (10, 20, 25) is more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // this is a chain placement — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large gaps.
            score += 2.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or there are no open bins. Scale penalty with stream progression
    // (late in stream, consolidating matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            score -= 12.0; // big item into fresh bin is fine
        }
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (use bins that are already fuller than average).
    score -= 3.0 * (mean_residual - bin_residual as f64) / cap;

    // Many open bins: encourage filling existing ones to limit bin count.
    score += 0.5 * (open_bins_count as f64).ln() * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 60.0;
    }
    // Unusable small gaps: too small to fit anything meaningful later.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling with lookahead: favor leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when waste is similar.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current bins are hopelessly fragmented.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild progress term: later in stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 - mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain (gap 0) gets strong reward; decays quadratically
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).powi(6);
    } else if next_item_size > 0 {
        // Next item cannot follow: this bin's remaining space is likely dead
        score += 15.0;
    }

    // Penalize residual far above mean residual (creating outlier dead space)
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Tight fit reward: small post_residual is good, but not when it blocks next item
    if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Late in the stream, prefer closing bins (fewer open bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.3;

    // Mild preference for filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            score -= 8.0; // next item can follow in this bin
        }
    } else {
        // Last item: pure tight packing matters most.
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            post_residual < next_item_size && post_residual > 0
        } else {
            false
        };
        let mut new_bin_score = 30.0
            + 0.15 * open_bins_count as f64
            + 0.25 * mean_residual.max(0.0);
        if poor_fit {
            new_bin_score -= 45.0; // better to open a bin than fragment
        }
        // Early in the stream, opening bins is cheaper (more items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 10.0 * progress;
        score = score.max(new_bin_score);
    }

    // Slight preference for bins whose residual is near the global mean (balanced load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual (tight fit), non-linearly coupled with progress.
    let mut score = pr + 60.0 * pr_norm * pr_norm * (1.0 + progress);

    // Smooth interaction: tight fits matter more as the stream progresses.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 40.0 * (0.5 + progress);

    // Penalize dead space in the unusable zone relative to mean residual.
    if pr > 0.0 && pr < mean_residual {
        score += (mean_residual - pr) * 0.5;
    }

    // Lookahead coupling: reward bins whose post residual fits the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - slack * slack) * (1.0 - progress * 0.5);
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Mild penalty for hoarding many open bins late in the stream.
    score += open_bins_count as f64 * 0.05 * progress;

    // New-bin candidate: make it moderately attractive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" the leftover is.
    // Class 0: tiny dead space (<=10) -> excellent, strong reward.
    // Class 1: fits next item exactly -> jackpot.
    // Class 2: mid-range residual, moderately useful.
    // Class 3: large residual, item was small -> wasteful placement.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 45.0;
    } else if pr <= 20 {
        score -= 20.0;
    } else if pr <= 35 {
        score -= 5.0;
    } else {
        // large leftover: penalize proportional to wasted fraction
        score += (pr as f64 / cap) * 30.0;
    }

    // Lookahead coupling: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // perfect chaining
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64 / cap) * 12.0;
        }
    }

    // Harmonic (integer-division) threshold classes on item size.
    // Big items (>= half capacity) should go into tight bins; small items are flexible.
    let item_class = item_size / 20; // 0..4 harmonic class
    match item_class {
        0 => score += 8.0,              // tiny item anywhere is fine, less discriminating
        1 => score += 2.0,
        2 => score -= 0.0,
        3 => score -= 10.0,             // large items: prefer tight fits
        _ => score -= 18.0,             // huge items: strongly prefer tight fits
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit into
    // existing bins would leave bad residuals. Give the new bin a moderate
    // baseline penalty so it is chosen only for genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if stream is early, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // if next item is huge, fresh bin preserves flexibility
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Density pressure: when mean residual across open bins is high, prefer
    // filling existing bins rather than spreading.
    score -= (mean_residual / cap) * 6.0;

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are more reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 7.0;
    }

    // Tightness coupling: reward when item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Slight preference to close bins when many are open.
    if post_residual <= 5 && open_bins_count > 4 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized (non-linearly).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits strongly (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins fit, to keep discrimination sharp.
        score += (fitting_bins_count as f64) * 0.5;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else (large post_residual penalty in existing bins).
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: post_residual = capacity - item_size.
        // Give a moderate discount so it wins only over bad fits.
        score -= 10.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Existing bin: if next item could use the post_residual, reward it.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0;
        } else if next_item_size > 0 {
            // Post residual unusable by next item: penalize.
            score += 4.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in the direction of smaller residual (consolidate space).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for filling the bin exactly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward residuals that match next item size.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = 300.0 * (1.0 - diff / (bin_capacity as f64));
        if diff == 0 {
            score -= 400.0;
        } else if diff <= 10.0 {
            score -= 150.0;
        }
        score -= match_bonus * 0.5;
    }

    // Penalize large dead space relative to bin capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 80.0 * dead_frac * dead_frac;

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual deviates favorably (tighter bins for tight fits).
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 40.0; // this bin is tighter than average: good for big items
        } else if rel > 1.5 {
            score += 30.0; // much looser than average: save it
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer opening a new bin only if current bin would be badly wasted.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted when the item is large or fit is poor elsewhere.
        score = 60.0 + item_size as f64 * 0.3;
        if item_size >= 70 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - dead_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0 + 0.5 * item_size as f64;
    }

    // Lookahead: penalize leaving a residual that can't host the next item,
    // reward residuals that can (keeps chains of placements viable).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 15.0 + 0.3 * (next_item_size as f64);
        }
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or this is a big item that would create bad dead space elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fill = bin_capacity as f64 - mean_residual;
        let open_util = if open_bins_count > 0 { avg_open_fill / bin_capacity as f64 } else { 0.0 };
        // Prefer new bin when existing bins are well-filled or fit is poor.
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        score = 60.0 + 120.0 * (1.0 - open_util) + 40.0 * fit_quality - 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can always host the next item
        }
    }

    // Mild preference for filling already-open bins as stream progresses.
    if bin_residual < bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = pr_norm * pr_norm * (1.0 - progress) * 40.0
                 + pr_norm * progress * 25.0
                 + (1.0 - pr_norm) * (1.0 - pr_norm) * progress * 15.0;
    score += coupling * cap;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - pr_norm).powf(3.0) * 12.0 * (0.5 + progress);

    // Penalize dead space relative to next item: residual unusable by lookahead
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (pr - ni).max(0.0);
        let unusable = (ni - pr).max(0.0);
        score += waste * 0.3 * (1.0 - progress)
               + unusable * 0.5
               + (pr_norm * ni / cap) * 20.0;
    } else {
        // Last item: strongly reward filling bins
        score -= (1.0 - pr_norm) * 30.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 15.0 + 10.0 * progress;
    }

    // New empty bin: penalize mildly unless current bin fit would be terrible
    score += is_new_bin * (18.0 - 25.0 * (1.0 - pr_norm).min(1.0) * (1.0 - pr_norm));

    // Prefer bins with below-mean residual (keeps big residual bins available)
    score += (pr - mean_residual) * 0.15;

    // Mild penalty for spreading across many bins early
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits strongly (small post_residual is good).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= bin_capacity / 10 {
        score -= 40.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 20.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 5.0;
    } else {
        // Large leftover: penalize dead space super-linearly.
        score += (frac * frac) * 30.0;
    }

    // Harmonic classes via integer division of post_residual:
    // leftover classes that pair with common item sizes (10..80) are reusable.
    let class = post_residual / 10;
    match class {
        0 | 1 | 2 => score -= 12.0, // leftover 0-29: fills with small items
        3 | 4 | 5 => score -= 6.0,  // leftover 30-59: medium items
        6 | 7 => score -= 2.0,      // leftover 60-79: only large items
        _ => {}                     // 80-99: nearly unusable
    }

    // Lookahead coupling: if next item fits in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else {
            // Next item cannot follow here; slight penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): mild penalty so we prefer reusing open
    // bins unless their residuals are truly bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But if no open bin fits well (this is checked implicitly), the
        // lookahead bonus above can still make a fresh bin attractive when
        // the next item is large.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Progress-aware mean-residual coupling: late in the stream, consolidation
    // matters more; penalize bins far from the mean residual (fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * (0.05 + 0.10 * progress);

    // Slight preference for fuller bins among many open bins.
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals of 1..=9 are almost unusable
    // (items are >= 1 but small leftovers rarely match future demand).
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64; // tiny gaps are worst
    } else if post_residual >= 10 && post_residual <= 20 {
        // moderate dead space: mild penalty scaled by how far from capacity
        score += 0.5 * (20 - post_residual) as f64;
    } else if post_residual == 0 {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Reward bins whose residual is close to item_size (snug fit).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 8.0 * snug;

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; with few,
    // opening a new bin (empty candidate) is relatively cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += 2.0 * pressure * (mean_residual / bin_capacity as f64);

    // New-bin candidate: base cost plus pressure; accept it only when open bins
    // would create large dead space (handled above via penalties).
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio).powf(6.0);

    // Aggressive 2-step lookahead: if the next item exactly fills the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: partial reward, scaled by how snugly.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 * snug.powf(3.0);
        } else {
            // Next item won't fit in leftover: penalize dead space.
            score += 15.0;
        }
    }

    // Penalize bins whose residual deviates badly from the mean residual (outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Slight preference to fill older/more crowded bins when many bins are open.
    score -= 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mild pressure against opening new bins mid-stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Penalize large wasted residual quadratically.
    score += 0.002 * (post_residual as f64).powi(2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_ratio * waste_ratio; // penalize large dead space quadratically
    }

    // Last chance: strongly prefer using the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item cannot use the remaining space: mild penalty proportional to leftover.
            score += 0.15 * post_residual as f64;
        }
    }

    // Time horizon: early in the stream, be more conservative (favor filling existing bins);
    // late in the stream, perfect closures matter more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;

    // Global state coupling: if open bins have lots of residual on average, penalize
    // adding more residual (encourage using bins with less space left).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Discourage opening new bins when many bins are open and this bin fits reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from number of open bins.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // If the item is small and many bins exist, opening new bins is wasteful.
        if item_size < 50 {
            score += 15.0;
        }
    } else {
        // Slight preference for existing bins as open count grows.
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.1 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear penalty for mid-range dead space
    let mut score = pr * (1.0 + 0.6 * norm_pr * (1.0 - norm_pr) * 4.0);

    // Smooth coupling of residual with stream progress: later in stream,
    // value tight fits more (penalize large residuals more)
    let tightness = (pr / (item_size.max(1) as f64)).ln().abs();
    score += 8.0 * progress * tightness;

    // Reward filling bins nearly exactly (post_residual near 0) with smooth term
    score -= 15.0 * (-pr / 12.0).exp();

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New bin candidate: penalize mildly early, more when many bins already fit item
    if bin_residual == bin_capacity {
        let fit_pressure = fitting_bins_count as f64 / (open_bins_count.max(1) as f64);
        score = cap + 20.0 * fit_pressure + 10.0 * progress;
    }

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap).abs() * (1.0 - progress);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins)
    score += 0.3 * (mean_residual - pr) * (0.5 + progress);

    // Slight preference for fewer open bins when closing bins well
    score -= (post_residual == 0) as i32 as f64 * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" residue classes (multiples of 10, or >= 10) are better.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit, ideal
    } else if pr < 10 {
        score += 25.0; // dead space below min item size
    } else {
        // reward leftovers that are multiples of 10 (harmonic alignment)
        if pr % 10 == 0 { score -= 8.0; }
        // integer-division threshold: leftover >= 20 is reusable
        score -= (pr / 20) as f64 * 5.0;
    }

    // Tightness reward: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate penalty: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 60.0 - pressure * 40.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 12.0;
            // harmonic pair: both multiples of 10
            if next_item_size % 10 == 0 && pr % 10 == 0 { score -= 6.0; }
        } else {
            // next item cannot use leftover: mild penalty proportional to waste
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Prefer filling bins when many bins are open (consolidation)
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: placing into a bin below mean residual
    // (smaller leftover than average) is desirable
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // Penalize if post residual is just barely too small for next item (wasted gap).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: make it a moderate fallback, better than bad fits, worse than good fits.
    if bin_residual == bin_capacity {
        score = 35.0 - 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
