pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill: reward bins that end up well-utilized.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill * fill;

    // Perfect or near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward placing item here if the next item fits the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Lookahead: penalize if next item almost fits (near miss creates bad sequencing).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins below mean residual (keep some bins large for big items).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.15 * dev; // negative dev lowers score slightly (favor fuller bins)
    } else {
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be more liberal opening new bins;
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * fill;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * open_bins_count as f64 * 0.1;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin.
        score += 30.0;
        // Opening is more attractive early and for large items with few fitting bins.
        score -= 25.0 * (1.0 - progress) * large_item;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is tolerable; late in the stream, residual dead space is penalized super-linearly.
    let progress_waste = pr * (0.5 + 1.5 * progress * progress);
    score += 0.35 * progress_waste;

    // Smooth convex shaping of residual: quadratic term punishes mid-range leftovers,
    // normalized by capacity so it stays scale-free.
    let x = pr / cap;
    score += 8.0 * x * x * (1.0 - x) * cap * 0.1;

    // Lookahead coupling: if the next item fits smoothly into the post-residual, reward;
    // if post_residual is awkwardly just below next item, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= 4.0 * snug * snug;
        } else {
            let gap = (nxt - pr) / cap;
            score += 3.0 * gap;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate: opening a bin is penalized, more so when open bins exist
    // and mean residual is large; penalty decays smoothly with progress.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual / cap;
        score += 10.0 + 12.0 * mean_r * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    // Mild preference for tighter bins overall relative to fleet mean residual.
    score += 0.5 * (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0), tiny residues (1..5),
    // and residues matching common item sizes (10..80 classes) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 5 {
        score -= 25.0; // near-perfect, dead space is negligible
    } else if pr >= 10 && pr <= 80 {
        // residue is itself a plausible future item size -> reusable
        let class_bonus = match pr % 10 {
            0 => 18.0,
            _ => 9.0,
        };
        score -= class_bonus;
    } else {
        // large awkward residue (81..99) is mostly dead space
        score += 15.0;
    }

    // Fractional capacity coupling: residual relative to capacity quarters
    let frac = pr as f64 / bin_capacity as f64;
    score += 20.0 * (frac - 0.5).abs(); // prefer residuals near half capacity? no: penalize extremes
    score -= 12.0 * (1.0 - frac); // reward leaving little residue overall

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 5 {
                score -= 30.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            score += 8.0; // next item cannot use this bin's residue
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 70.0; // base cost of a fresh bin
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else {
            let progress = step_index as f64 / total_items.max(1) as f64;
            let crowded = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
            score -= 30.0 * progress + crowded * 2.0;
        }
    }

    // Mild tie-break toward bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Small deterministic jitter-free harmonic nudge on integer division class
    score += (pr / 7) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(bin_capacity)) {
        // gap unusable by the next item -> strong penalty
        score += 40.0 + 0.5 * post_residual as f64;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }
    // Tight fit reward: leaving a gap exactly equal to next item is excellent
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Reward when the gap can still host the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }
    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist (early stream).
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline plus pressure term
        score += 10.0 + 2.0 * open_bins_count as f64;
        // opening a new bin is attractive if mean residual across open bins is tiny
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // placing into an existing bin reduces open-bin pressure slightly
        score -= 1.0 * open_bins_count as f64;
    }
    // Late-stream consolidation: prefer filling existing bins tighter as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits but not perfectly: mild reward proportional to closeness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.5 * next_item_size as f64;
    }
    // Next item won't fit: penalize dead space creation.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + 0.3 * post_residual as f64;
    }

    // Reward tight fits relative to capacity (small post_residual is good, but zero-waste is best).
    if post_residual == 0 {
        score -= 500.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * tightness * tightness;
    }

    // Compare against mean residual: bins already much emptier than average should absorb items.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow new bin when next item is large and current fit would leave big dead space.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.6;

    // Penalize wasted space relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.2;
        } else {
            score += 8.0;
        }
        // If post_residual too small for anything useful, penalize dead space
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    }

    // New-bin candidate handling: only prefer opening a new bin when current bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if mean_residual > 0.0 { 1.0 - (item_size as f64 / mean_residual).min(1.0) } else { 0.5 };
        // Cost of a fresh bin decreases if open bins can't fit well and stream is early
        score = 70.0 + 40.0 * (1.0 - fragmentation) + 30.0 * progress;
        if fitting_bins_count == 1 {
            score += 60.0; // strongly discourage abandoning the only fitting bin
        }
    }

    // Mild penalty for spreading across too many bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear waste penalty: dead space grows super-linearly in post_residual
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += 0.8 * norm_pr * norm_pr * cap;

    // Tight-fit reward: subtract for small post_residual (smooth quadratic coupling)
    score -= 0.6 * (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0;

    // Stream progress coupling: early on, prefer filling bins loosely (keep flexibility);
    // later, prefer tight packing. Smooth interaction term.
    score += (1.0 - progress) * 0.5 * pr * 0.1;
    score -= progress * 0.5 * pr * 0.1;

    // Lookahead: penalize leaving residual that exactly matches nothing useful;
    // reward residual that can fit next item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= fit_next * 6.0 * (1.0 - diff / cap);
        score += 0.3 * (diff / cap) * cap * 0.1;
    }

    // Last chance bin: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins whose residual deviates far above mean (keeps balance)
    score += 0.2 * ((pr - mean_residual) / cap).abs() * cap * 0.1;

    // Mild penalty for having many open bins relative to progress
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it slightly unattractive unless residuals are all tight
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // opening fresh bin is good if next item is large
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
