    let pr = post_residual;
    if pr > 0 {
        let mut harmony: f64 = 0.0;
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 50 == 0 { harmony += 3.0; }
        score -= harmony;
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Dead-space penalty: very small but nonzero leftovers are wasted capacity.
    if pr > 0 && pr < 10 {
        score += 25.0 - 2.5 * pr as f64;
    }

    // Lookahead coupling: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after next placement drives a second-order term
            let pr2 = pr - next_item_size;
            score -= 8.0 + 0.15 * pr2 as f64;
            if pr2 % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 0.10 * ((next_item_size - pr) as f64).min(40.0);
        }
    } else {
        // Last item: only absolute waste matters.
        score += 0.5 * pr as f64;
    }

    // Tightness term: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual; make it
    // attractive only when no good fit exists (many open bins, poor harmony).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score = cap * (0.9 + 0.1 * progress) + 5.0 * crowd;
        if fitting_bins_count == 0 { score -= 20.0; }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin likely useful for a chain of large items
        }
    }

    // Mild tie-break toward consolidating into fewer bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small to ever be useful (below min item size 1..100, treat < 10 as dead)
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Non-linear penalty on small-but-not-dead residuals that few items can use
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual <= 30 {
        score += (30.0 - post_residual as f64) * (2.0 + progress * 3.0);
    }

    // Reward tight fits (low post_residual) proportionally to fill ratio
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 40.0;

    // Open-bin pressure: discourage spreading across many bins when this creates waste
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to item size (best-fit coupling)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Lookahead: if next item fits into post_residual, reward this placement strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward if it fits snugly
        if post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use the leftover: mild penalty scaled by wasted gap
        score += (post_residual as f64) * 0.4;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if no open bin fits well, allow it
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, opening new bins is cheaper than fragmentation
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Mean residual coupling: if this bin's residual deviates strongly from mean, slight penalty
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // bin can host the next item too: reward closeness of match
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize dead space relative to next item
            score += 0.5 * gap;
        }
    }

    // Reward tight fits relative to mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.8 * (mean_residual - pr);
    } else {
        score += 0.4 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 40.0 + 10.0 * (1.0 - tightness);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Slight preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer tight fits (small post_residual).
    let mut score = post;

    // Strongly reward near-perfect fits (post_residual <= 5).
    if post <= 5.0 {
        score -= 40.0 + (5.0 - post) * 4.0;
    } else if post <= 15.0 {
        score -= 15.0;
    }

    // Penalize dead space scaled by how unusable it is for typical items.
    let dead = post / cap;
    if post > 0.0 && post < 10.0 {
        score += 12.0; // tiny unusable sliver
    }
    score += dead * dead * 20.0;

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() <= 1.0 {
            score -= 35.0;
        } else if nxt <= post {
            score -= 8.0 * (1.0 - post / cap);
        } else {
            // Next item won't fit here; penalize leaving large gaps.
            score += 6.0 * (post / cap);
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }
    // Many alternatives: mild penalty for wasting this bin's flexibility.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state coupling.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 0 {
        let mr = mean_residual / cap;
        // Prefer bins whose residual is close to the mean (balanced packing) early on;
        // later, prioritize tight fits regardless of balance.
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score += dev * 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: encourage consolidation.
        if open_bins_count > 8 && mr > 0.4 {
            score -= 6.0 * mr;
        }
    }

    // New-bin candidate logic: naturally low post score, but penalize opening
    // new bins when decent fits exist, unless the item is large relative to residual.
    if is_new_bin {
        let open_pressure = (open_bins_count as f64 / 20.0).min(1.0);
        let mut penalty = 18.0 + 25.0 * open_pressure;
        if fitting_bins_count > 0 && item_size as f64 / cap < 0.5 {
            penalty += 15.0;
        }
        // Late in the stream, avoid spawning bins with small leftovers.
        if next_item_size > 0 && post < next_item_size as f64 {
            penalty += 10.0;
        }
        score += penalty;
    }

    // Small time-horizon modulation: tighten criteria as stream progresses.
    score *= 1.0 + 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on: mildly tolerate larger residuals; late: penalize wasted space more.
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += t * (pr * pr) / cap;

    // Reward tight fits: small post_residual gets a smooth bonus.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (cap * 0.35);

    // Perfect-fill attraction (smooth gaussian-like bump near zero residual).
    let x = pr / cap;
    score -= (cap * 0.8) * (-x * x / 0.005).exp();

    // Penalize creating dead space that next item can't use.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let unusable = (ni - pr).max(0.0) as f64;
        score += 0.9 * unusable;
        // Reward leaving space exactly usable by next item.
        let gap = (pr - ni).abs();
        score -= (cap * 0.5) * (-gap * gap / 50.0).exp();
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap * 1.5;
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // unless residual pressure is high.
    if bin_residual == bin_capacity {
        score += cap * 0.6 + open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidating: extra penalty.
        score += t * cap * 0.4;
    }

    // Mild coupling with mean residual: prefer bins deviating below mean
    // (keeps large residuals available for large items).
    score += 0.3 * (pr - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small to hold typical items.
        if post_residual < 10 {
            score += 50.0;
        } else if post_residual < 20 {
            score += 20.0;
        }

        // Harmonic class: leftover divisible into nice chunks is reusable.
        // Residuals in {0, 10, 20, 25, 50} mod classes are "harmonic".
        let r = post_residual;
        let harmonic = (r % 50 == 0) || (r % 25 == 0) || (r % 10 == 0) || (r % 20 == 0);
        if harmonic {
            score -= 15.0;
        }

        // Integer-division threshold classes on post_residual.
        let class = r / 10; // coarse class 0..10
        score += (class as f64) * 2.0; // prefer tighter classes overall (best-fit flavor)

        // Lookahead coupling: if next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 300.0;
            } else if next_item_size <= post_residual {
                // next item fits: reward proportionally, better if snug.
                let slack = (post_residual - next_item_size) as f64;
                score -= 60.0 * (1.0 - slack / cap);
            } else {
                // next item cannot use this leftover: penalize large leftovers mildly.
                score += 10.0 + frac * 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // a new bin when no open bin scores better.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * (open_bins_count as f64).sqrt();
    } else {
        // Slight preference for bins already below mean residual (consolidation).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild stream-position modulation: later in stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,9] are nearly unusable
    // (items are >= 1, but small gaps rarely match future demand).
    let pr = post_residual as f64;
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0 + (10.0 - pr) * 5.0; // smaller dead space = worse (wasted capacity)
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit, strongly reward closing the bin
    }

    // Reward tight fits generally (low post_residual relative to capacity).
    score -= (1.0 - pr / bin_capacity as f64) * 10.0;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement chains nicely; if next item is slightly too big,
    // the residual becomes dead space -> penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 12.0; // blocks next item in this bin
        } else if post_residual > 0 && (n - pr).abs() <= 3.0 {
            score -= 8.0; // near-chain fit
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current fit is poor and the item is large.
    if bin_residual == bin_capacity {
        let poor_fit = pr > 30.0; // placing in empty bin leaves big residual anyway
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if poor_fit && big_item {
            score -= 15.0;
        } else {
            score += 10.0 + mean_residual * 0.1; // discourage wasting open capacity
        }
    }

    // Slight preference for bins whose residual is close to item size
    // (best-fit flavor beyond raw post_residual).
    score -= ((bin_residual as f64 - item_size as f64).abs()) * (-0.05);
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
            // perfect chaining: post residual exactly equals next item
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // penalize creating residual too small for the next item (dead space)
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins already below average residual
    // (they are "tight" bins; consolidate filling there).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; relaxed when lookahead is promising
        score += 35.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        if item_size >= 60 {
            score -= 10.0; // large items fine in fresh bins
        }
    }

    // Slight preference to fill older/more crowded bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Penalize leaving small, hard-to-use dead space (< 10 units is nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here: mild penalty proportional to waste.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Reward post residuals that remain usable for a range of future items.
        if post_residual >= 10 {
            score -= 2.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    } else {
        // Last item: prefer filling bins as completely as possible.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // When many bins are open, consolidate into fewer bins; when few are open,
    // spreading load is less costly.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * crowding;

    // Mean residual coupling: prefer bins whose residual is below mean (filling
    // the emptier-trending bins first keeps the open-bin set tidy).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.10 * residual_gap;

    // Time horizon: early in the stream, keep flexibility (avoid near-full bins);
    // late in the stream, prioritize closing bins out completely.
    if progress < 0.3 {
        score += 3.0 * tightness;
    } else if progress > 0.7 {
        score -= 3.0 * (1.0 - tightness);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well, or when the item perfectly splits capacity.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * item_size as f64;
        if item_size == bin_capacity {
            score = -100.0; // perfect full fit in a fresh bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room to also take the lookahead item
        }
        // Late in the stream, opening new bins is more acceptable since leftover
        // capacity is less likely to be reused.
        score -= 10.0 * progress;
        // If many open bins can already fit the item, discourage a new bin.
        score += 6.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (quadratic penalty on wasted space)
    let mut score = post * post / cap;

    // Non-linear coupling of wasted space with stream progress:
    // late in the stream, dead space matters more.
    score += 12.0 * norm_post * norm_post * (progress * (1.0 - progress) * 4.0);

    // Lookahead: reward residual that can still host the next item (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0);
        let usable = (post - fits_next) / cap;
        score -= 6.0 * usable * (1.0 - (nxt / cap));
        // penalize leaving residual just below next item (near-miss dead space)
        let gap = (nxt - post).max(0.0) / cap;
        score += 10.0 * gap * (1.0 - gap);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 8.0 * (item / cap);
    }

    // Prefer bins with residual below mean (consolidate small leftovers)
    score += 0.5 * (post - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post).max(0.0);

    // Mild penalty for spreading across too many open bins when bin is nearly full
    if post == 0 {
        score -= 5.0; // perfect fit reward
    }

    // New-bin candidate: make empty bin moderately attractive only when item is large
    if bin_residual == bin_capacity {
        score = cap - item * 0.9 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity into 10 classes of size 10.
    // Class 0 (perfect fit) is maximally rewarded; mid classes (unusable slivers) penalized.
    let class = (post_residual % bin_capacity) / 10;
    match class {
        0 => score -= 40.0,                       // perfect or exact multiple fit
        1 => score += 25.0,                       // 1..10 dead space: worst sliver
        2 => score += 10.0,
        3 => score -= 2.0,                        // 30..39: fits typical mid items
        4 => score -= 6.0,
        5 => score -= 8.0,                        // ~half bin: very reusable
        6 => score -= 5.0,
        7 => score -= 1.0,
        8 => score += 6.0,
        _ => score += 0.0,
    }

    // Integer-division threshold: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead-friendly: reward proportionally to how snugly the next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 15.0 - snug * 0.3;
        } else {
            // Next item won't fit here: penalize, worse if this bin was its only hope.
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are congested or stream is early
    // and mean residual is large (bad fragmentation management so far).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = fitting_bins_count as f64;
        score = 30.0 + congestion * 12.0 - mean_residual * 0.1 - (1.0 - progress) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can always host the lookahead: slight discount.
            score -= 5.0;
        }
    }

    // Mild global pressure: when many bins are open, tighten packing (favor fuller bins).
    score -= open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead-space threshold: gaps too small for the smallest plausible item.
        let dead_threshold = 10.0f64;
        if (post_residual as f64) <= dead_threshold {
            score += 120.0 * (dead_threshold - post_residual as f64 + 1.0);
        }
        // Nonlinear penalty on medium-small gaps (hard to fill later).
        let gap = post_residual as f64;
        score += 40.0 * (1.0 - (gap / 50.0).min(1.0)) * (gap / 50.0);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward leaving room for the next item.
        score -= 0.5 * (post_residual - next_item_size) as f64;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    // (large post_residual elsewhere) or when many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by open-bin pressure.
        let pressure = open_bins_count as f64;
        score += 80.0 + 5.0 * pressure;
        // If the next item is large and current mean residual is small, new bin is attractive.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 60.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild preference for tighter bins overall (below mean residual is good).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powf(8.0) * 30.0;

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        score -= 20.0;
        score -= (next_post as f64 / bin_capacity as f64).powf(6.0) * 15.0;
    } else if next_item_size > 0 {
        // Next item won't fit after this placement: penalize wasted residual.
        score += (post_residual as f64 - mean_residual).abs() * 0.3;
        score += post_residual as f64 * 0.1;
    }

    // Relative-to-mean coupling: prefer bins with residual close to or below mean.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless it's genuinely better to open fresh.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If no open bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && item_size + 20 > bin_capacity) {
            score -= 45.0;
        }
    }

    // Late-stream tightening: minimize waste as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: strongly reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize creating dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * (item_size as f64);
    }

    // New-bin candidate: penalize opening a new bin when good fits exist,
    // but allow it when the item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0;
        if fitting_bins_count > 0 {
            // extra penalty if some open bin could actually fit it
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            // new bin can also host the next item: mild bonus
            score -= 10.0;
        }
    }

    // Lookahead: reward leaving residual that exactly fits the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            score -= 15.0 / (1.0 + gap);
        } else {
            score += 5.0 / (1.0 + gap);
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0));
    score -= 1.5 * pressure * (item_size as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (keeps the fleet homogeneous) — mild effect.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: as the stream progresses, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Penalize very large residuals being consumed by tiny items late in stream.
    if item_size < 20 && bin_residual > 60 && progress > 0.5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: reward tight fits via non-linear decay of post residual
    let mut score = (norm_post * norm_post) * cap * 1.3 + post * 0.2;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is penalized more aggressively
    let coupling = norm_post * norm_post * (progress * progress) * 40.0
                 + norm_post * (1.0 - progress) * (-8.0);
    score += coupling;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving a residual that barely fails/awkwardly fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            // next item can't use this residual: mild penalty scaled by closeness
            score += 6.0 * (1.0 - ((post - nxt).abs() / cap)) * (0.5 + 0.5 * progress);
        } else {
            // next item fits: reward proportionally to how well residual is used
            let use_ratio = nxt / post.max(1.0);
            score -= 10.0 * use_ratio * use_ratio;
        }
    }

    // Mean-residual coupling: prefer bins deviating from mean residual (balance-aware)
    let dev = (post - mean_residual).abs();
    score += 0.05 * dev * dev / cap;

    // Mild penalty for spreading across too many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 3.0 * progress) * 0.5;

    // New-bin candidate: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score = post * 0.2 + 30.0 - 18.0 * progress;
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (size 1..100 unknown, use harmonic classes of 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class match: post_residual exactly divisible into capacity fractions
    let cap = bin_capacity as u32;
    for frac in [2u32, 3, 4, 5, 10] {
        if post_residual == cap / frac {
            score -= 15.0;
        }
    }

    // Reward if post_residual can exactly hold next item (lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead
        score += 25.0;
    }

    // Last fitting bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when current bin would leave awkward residual
    if bin_residual == bin_capacity {
        // Base mild penalty so open bins with good fits win
        score += 5.0;
        // But if item fits badly everywhere (item large relative to residual), encourage new bin
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation)
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference to act early in stream (keep flexibility later)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive when other bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Only prefer a new bin if all existing fits would create dead space.
            score += 150.0;
        } else {
            score += 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 40.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item can use this bin's post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that is too small for the upcoming item.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Slight preference for bins with below-average residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit leaving no dead space.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly match the next item,
    // or that can still host it comfortably.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // chainable: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            // next item still fits; mild reward proportional to how snugly
            let slack = (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 20.0 * (1.0 - slack);
        } else {
            // dead space relative to lookahead: penalize unusable remainder
            let waste = (post_residual as f64 - nxt).max(0.0);
            score += 0.5 * waste;
        }
    }

    // Penalize small unusable residuals (dead space) more than linear.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (good fits), discourage outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Slight preference for filling older/more-filled bins early vs late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0
            || (next_item_size > 0 && post_residual < next_item_size as u32 && post_residual > 0);
        if poor_fit {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual.
    score += (post_residual as f64).powi(2) * 0.02;

    // Penalize leaving residual that is unusable for the next item but could fit nothing typical.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }
    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).ln().max(0.0);
        score -= 4.0 + 6.0 * progress - 2.0 * pressure;
        // If the item fits perfectly in a fresh bin, encourage opening it.
        if item_size == bin_capacity {
            score -= 20.0;
        }
    } else {
        // Mild preference for bins with below-average residual (keeps large gaps available).
        if (bin_residual as f64) > mean_residual {
            score += 1.5;
        } else {
            score -= 1.0;
        }
    }

    // Early stream: be conservative, prefer filling existing bins well.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (1.0 - progress * progress);
    score += poly * 20.0;
    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * progress * 15.0;
    // Penalize dead space that next item can't use
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + progress * 10.0;
    } else if next_item_size > 0 {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score += slack * slack * 6.0;
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }
    // Mild penalty when many bins are open relative to mean residual
    let mr = mean_residual / cap;
    score += (open_bins_count as f64).ln() * (mr - norm_pr).abs() * 4.0;
    // New-bin candidate: penalize unless item is large
    if bin_residual == bin_capacity {
        score += 30.0 - item_size as f64 * 0.25;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "useful"
    // residue classes (divisible by common item sizes) are more valuable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit is always great
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 25 == 0 || pr % 20 == 0 {
        -6.0
    } else {
        2.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: small unusable leftovers are bad unless bin is nearly full.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 3.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many bins open already
        score += 40.0 - (open_bins_count as f64).sqrt() * 2.0;
        // if item is large relative to capacity, opening fresh is more acceptable
        score -= (item_size as f64 / cap) * 10.0;
        // late in stream, prefer consolidation less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Prefer tighter fits generally: reward small post_residual relative to capacity.
    score -= (1.0 - pr as f64 / cap) * 4.0;

    // Prefer bins below mean residual (consolidate emptier bins? no: fill emptier bins less)
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are unusable (too small for
    // any plausible future item, min size 1..100 unknown -> treat tiny gaps
    // below a "dead zone" threshold as highly penalized).
    let dead_threshold = 12.0; // gaps <= 12 are nearly unusable
    if post_residual as f64 <= dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0 + 15.0;
    }
    // Perfect fit: zero waste is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: fraction of residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: penalize spreading across many open bins so the
    // heuristic prefers closing bins out.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    // (mean residual low) or this bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        let mut new_bin_score = 30.0 + open_bins_count as f64 * 2.0;
        if mean_gap < dead_threshold {
            new_bin_score -= 10.0; // existing bins would be dead anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 15.0; // new bin can host the next item too
        }
        score = score.min(new_bin_score) + new_bin_score - score.max(new_bin_score);
        score = new_bin_score;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item cannot use the leftover
    }

    // Mild stream-progression term: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact match for the next item is very desirable.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0);
            // Bonus if the next item leaves a tight residual too (chained packing).
            if post_residual - next_item_size < 10 {
                score -= 15.0;
            }
        } else {
            // Post-residual cannot host the next item: penalize dead space.
            score += 10.0 + (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small unusable slivers are bad unless next item fits (already rewarded).
        score += 5.0;
    }

    // Compare residual to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item is large relative to residual, opening fresh may still win.
        if next_item_size > 0 && next_item_size > bin_residual / 2 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for reusing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 12.0 + (leftover as f64).min(20.0) * 0.3;
    }
    // Penalize if next item would NOT fit here but would fit the current residual
    // (i.e., we "waste" the gap that could have hosted the next item).
    if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins are quite full or many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = avg_fill * (open_bins_count as f64).sqrt();
        score += 30.0 - pressure * 18.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // new bin preserves room for larger follow-ups
        }
    }

    // Mild preference for filling bins that are already below-average residual
    // (keeps a few "flexible" bins emptier).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score += 2.0;
        } else {
            score -= 2.0;
        }
    }

    // Early stream: slightly discourage hoarding many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling: dead space penalized more as stream progresses
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= 12.0 * (1.0 - (pr / bin_capacity as f64).powi(2));

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: penalize if next item can't use this bin's post residual
    if next_item_size > 0 && next_item_size as f64 > pr {
        score += 6.0 * (0.5 + progress);
    } else if next_item_size > 0 {
        score -= 4.0;
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mean-residual divergence: prefer bins near the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: perfect fits are golden.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Modulo-harmonic classes on post_residual: residuals that are multiples
    // of common item sizes (or their complements) are reusable slots.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 30.0; // round residual, easy to fill later
    } else if pr % 5 == 0 {
        score -= 12.0;
    } else {
        score += 8.0; // awkward odd residual
    }

    // Dead-zone penalty: residuals that are too small for the minimum item
    // (1..=100 interface, but keep a soft threshold) are wasted space.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Lookahead: reward residuals that can exactly fit the next item,
    // penalize residuals that barely fail it.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 150.0;
        } else if pr >= next_item_size {
            score -= 20.0;
        } else if next_item_size > 0 && pr > 0 {
            score += 15.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer tighter bins relative to the fleet mean residual.
    score -= 0.5 * (mean_residual - bin_residual as f64).max(-cap) / cap * 50.0;

    // Slight preference for consolidating into fewer bins as stream matures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity as u32 {
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: penalize it mildly unless it offers a harmonic
        // full-capacity slot that open bins can't (it starts at cap anyway,
        // so rely on the bonuses above to make good open bins win).
        score += 25.0 + 15.0 * progress;
    }

    // Tie-break: favor bins with larger current residual usage.
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max: u32 = 10;
    if post_residual > 0 && post_residual <= dead_zone_max {
        score += (dead_zone_max - post_residual + 1) as f64 * 25.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Penalize creating gaps that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // gap remains usable for the next item
    }

    // Open-bin pressure: discourage proliferation of bins, but relax late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.5 - 1.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual;
        if mean_gap < item_size as f64 * 0.5 {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: squared dead-space penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Penalize leaving slivers the next item cannot use.
            score += (post_residual as f64) * 0.5;
        }
        // If next item fits exactly, big bonus.
        if next_item_size <= post_residual && (post_residual - next_item_size) < 5 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score = (bin_capacity as f64) + 20.0;
        // Early in stream, opening bins is cheaper (builds inventory).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // If many open bins, discourage adding more.
        score += (open_bins_count as f64) * 1.5;
        // If current item is large relative to capacity, a new bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // If next item is huge, reserving a fresh bin is valuable.
        if next_item_size >= bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    } else {
        // Prefer bins with residual below mean (consolidate toward fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild preference for bins whose residual is close to item_size (best-fit coupling).
    let gap = if bin_residual >= item_size { (bin_residual - item_size) as f64 } else { 0.0 };
    score += gap * 0.3;

    // Slight time-decay of lookahead influence late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr) + 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (1.0 - pr / ns) * (0.5 + progress);
        } else {
            score -= 4.0 * (pr / (pr + ns)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Nudge toward bins near the mean residual (balance)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: prefer it only when residual is full and fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions via integer division
    let item_class = item_size / 10;          // coarse decile class
    let post_class = post_residual / 10;      // decile class of leftover space

    // Reward placements whose post-residual forms a "harmonic" complement:
    // post_residual that is exactly a multiple of common item sizes (10..40)
    // is likely to be filled later. Reward (subtract) for usable leftovers.
    let usable = post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0);
    if usable {
        score -= 6.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize tiny dead space that no item can use (items >= 1, but small
        // leftovers below the smallest likely item class are wasted).
        if post_residual < 10 {
            score += 12.0 + (10 - post_residual) as f64;
        }
        // Harmonic coupling: post_residual divisible by next item's class
        // means the lookahead item can slot in perfectly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let diff = post_residual - next_item_size;
            if diff == 0 {
                score -= 15.0; // lookahead perfect fit
            } else if diff < 10 {
                score -= 4.0;
            } else if diff % 10 == 0 {
                score -= 6.0;
            }
        }
        // If lookahead cannot fit here, this bin's leftover is final-ish;
        // penalize large stranded residuals in harmonic classes.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Reward using bins with low residual (best-fit flavor) scaled by class
    score += post_class as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin gives a decent fit (post_residual would be large / dead).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream when
        // many bins are open and mean residual is high (fragmentation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_cost = 30.0;
        // If the item is large, a fresh bin is natural (harmonic: item > cap/2)
        if item_size * 2 > bin_capacity {
            new_cost -= 12.0;
        }
        // If the lookahead item is large too, fresh bin pairs them well
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            new_cost -= 8.0;
        }
        // Late stream with fragmented open bins: cheaper to open fresh
        new_cost -= progress * 6.0 + (open_bins_count as f64).min(10.0) * 0.3;
        score += new_cost;
    }

    // Mild preference for fuller bins relative to fleet state
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post residual that cannot fit even the smallest plausible item but is not zero.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just below the next item (blocking lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        // Favor tighter existing bins (smaller residual before placement).
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Early stream: be slightly more open to new bins; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual exactly or snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.8; // perfect chain fit gets big bonus
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize dead space relative to next item size
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Prefer bins with residual below mean (tighter bins) when fit is good.
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.25;
    } else {
        score += (residual_f - mean_residual) * 0.10;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize very small dead space (< 10) which is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if open_pressure > 25.0 {
            score += 60.0; // keep using open bins when they have room
        } else {
            score += 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference to fill bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify via square.
    score += (post_residual as f64) * 0.1;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are nearly unusable
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            score += 4.0; // next item won't fit here; bin likely closed after
        }
    } else {
        // Last item: just minimize post_residual, slight bonus for using bin.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 3 {
        score += 1.5; // many options; be pickier, mild penalty
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor fits. Penalize opening a new bin, more so early in stream
    // and when open bins are still roomy on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 10.0 * (1.0 - progress);
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 15.0;
        // If current item is huge, a fresh bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Prefer fuller bins relative to the fleet: a bin whose residual is far
    // below the mean is already well-packed; using it keeps mean spread tight.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let ratio = residual_f / mean_residual;
        score += (ratio - 1.0) * 2.0;
    }

    // Slight preference for bins with residual close to item_size (perfect packing).
    let diff = (residual_f - item_size as f64).abs();
    score += diff * 0.05;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit preferred, with non-linear (quadratic + quartic) coupling
    let mut score = pr + 0.9 * (pr / cap).powi(2) * cap + 0.6 * (pr / cap).powi(4) * cap;

    // Stream-progress coupling: later in stream, value tight fits more strongly
    score *= 1.0 + 0.8 * progress * (pr / cap);

    // Reward using a bin whose residual closely matches the item (good coupling)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * (1.0 - (fit_ratio - 1.0).powi(2)).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving a residual that fits next item poorly but wastes space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // residual can host next item: reward leaving exactly-useful space
            let waste = pr - nxt;
            score -= 4.0 * (1.0 - waste / cap);
            score += 0.5 * (waste / cap).powi(2) * cap;
        } else {
            // dead space relative to next item: penalize smoothly
            score += 3.0 * ((nxt - pr) / cap) * pr / cap * cap * 0.1;
        }
    }

    // New-bin candidate: penalize opening a bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let avg_fit = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        let desperation = (avg_fit - item_size as f64 / cap).max(0.0);
        score = cap + 40.0 - 60.0 * desperation.min(1.0) * (0.5 + progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals that are likely reusable
    // (multiples of 10, small remainders) are worth keeping, odd dead space penalized.
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => 500.0,
        x if x % 10 == 0 => 40.0 + x as f64 * 0.3,
        x if x % 5 == 0 => 15.0,
        x if x < 10 => -30.0, // dead space below smallest item
        _ => 0.0,
    };
    score -= class_bonus;

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 60.0 - slack as f64 * 0.4;
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Capacity fraction logic: penalize leaving tiny unusable fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 {
        score += 50.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Slight preference for tighter-than-average bins
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // New-bin candidate: make empty bin unattractive unless all fits are terrible
    if bin_residual == bin_capacity {
        score += 250.0;
        // allow new bin early in stream or when item is huge relative to residual pattern
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > bin_capacity / 2 {
            score -= 100.0;
        }
        if progress < 0.05 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual in [1..=15] is likely waste)
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (1.0 - (post_residual as f64) / 15.0);
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 25.0 - (gap as f64).min(25.0);
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 20.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Prefer bins with residual below mean (tighter packing)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.3;
        } else {
            score += (-diff) * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild quadratic penalty
    // on wasted space to amplify differences among poor fits.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // ---- Aggressive 2-step lookahead ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: next item can be chained into this bin.
            // Reward proportionally to how snugly the next item fits.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 60.0 + 20.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else if post_residual > 0 {
            // Dead space: too small for the lookahead item.
            // Penalize proportionally to the gap (unusable fragment).
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 + 0.8 * gap.min(40.0);
        }
    } else {
        // Last item: just prefer minimal leftover.
        score -= 5.0;
    }

    // ---- Relative-to-mean coupling ----
    // Bins with residual already below mean are "well used"; placing here and
    // leaving a small post_residual is good. If post_residual diverges far above
    // the mean residual, this bin was loose — discourage.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - pr).min(30.0);
    }

    // ---- Last-chance bonus ----
    // If this is the only bin that fits the item, using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when:
        //  - no open bin fits well (many fitting bins => keep using them), or
        //  - the item is large and current open bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = mean_residual / bin_capacity as f64; // low => bins nearly full
        let penalty = 90.0
            + 25.0 * (1.0 - crowd)          // plenty of room left in open bins => don't open
            + 30.0 * (1.0 - progress)        // early in stream, prefer consolidating
            + 15.0 * (fitting_bins_count as f64).min(4.0) / 4.0;
        score += penalty;

        // If lookahead item would exactly fill a fresh bin with this item, soften a bit.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Slight preference to spread across bins when many are open and nearly full:
    // keeps mean residual low and options open.
    if open_bins_count > 3 && mean_residual < 20.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest plausible item is worthless.
    if post_residual < 10 {
        score -= 25.0; // nearly perfect fit
    } else if post_residual < 20 {
        score -= 10.0;
    } else if post_residual < 35 {
        score -= 3.0;
    }

    // Penalize large waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count == 2 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 18.0; // perfect chain for next item
        } else if slack < 25.0 {
            score -= 6.0;
        } else {
            score += slack * 0.05; // mild penalty for leaving a big gap
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly discourage creating unusable space.
        score += (post_residual as f64) * 0.08;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit (i.e., this call is for the empty bin itself).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or
        // when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        if mean_residual > (item_size as f64 * 1.5 + 15.0) {
            new_bin_cost += 25.0; // open bins have plenty of room; don't open new
        }
        if open_bins_count == 0 {
            new_bin_cost = 0.0; // no alternative
        }
        score += new_bin_cost;
    }

    // Global pressure: many open bins with small mean residual -> consolidate,
    // favor filling existing bins more aggressively.
    if open_bins_count > 2 {
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= crowding * 8.0;
    }

    // Early stream: be a bit greedy about tight fits; late stream: keep
    // flexibility for unknown arrivals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: tight fits preferred (small post residual).
    let mut score = pr;

    // Non-linear penalty for residual that is too small to be useful later,
    // smoothly coupled with stream progress (later in stream, dead space hurts more).
    let dead = 1.0 - (norm_pr * 3.0).min(1.0);
    score += 8.0 * dead * dead * (0.5 + progress);

    // Reward bins whose residual approaches zero smoothly (perfect fill).
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 5.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bonus: only fitting bin; avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Mild penalty when bin residual deviates from mean residual (balance diversity).
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: empty bin has full residual; push its score up so it is
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are preferred.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50, 100].iter() {
            if pr % m == 0 { harmony += 6.0; }
        }
        if pr % 5 == 0 { harmony += 2.0; }
        score -= harmony;
    }

    // Dead-space penalty: tiny residuals that few items can use.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover; slight penalty
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, scaled by how well
    // existing bins would do (mean_residual high => existing bins are roomy).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // big-item streams: fresh bin useful
        }
    }

    // Prefer filling fuller bins early in the stream (first-fit flavor).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * (20.0 + 30.0 * progress);

    // Mild tie-break toward bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Leftover too small for the lookahead item = likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }
    // Reward fitting the next item too (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Opening a new bin should be costly when many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        // Mild pressure to prefer fuller bins (smaller residual) among open bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Penalize bins far from the mean residual (outliers keep fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        score -= 60.0 + (next_post as f64) * 0.3;
        if next_post == 0 {
            score -= 400.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize wasted space
        score += (next_item_size as f64) * 0.2;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 80.0 - (item_size as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // fresh bin supports the lookahead pair
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins among many fitting candidates that leave less waste
    score += (fitting_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: subtract proportional to fill fraction of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Penalize large dead space nonlinearly: residuals that are too small to
    // hold typical items (<= ~10) are wasted; residuals just above common
    // item sizes are also poor targets.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny unusable sliver
    } else if pr >= 10.0 && pr <= 30.0 {
        score += 8.0 * (1.0 - pr / 30.0); // awkward medium dead space
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n == pr {
            score -= 35.0;
        } else if n <= pr {
            // partial reward scaled by how well next item uses leftover
            score -= 15.0 * (n / pr);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 5.0 * ((n - pr) / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be more conservative (favor compacting
    // existing bins); late in the stream, allow opening new bins more freely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure terms.
        let mut nb = 20.0 + 10.0 * (1.0 - progress);
        // More open bins => discourage proliferation unless mean residual is low.
        nb += open_bins_count as f64 * 1.5;
        nb -= (mean_residual / bin_capacity as f64) * 15.0;
        // If nothing else fits well, new bin becomes attractive when mean
        // residual is small relative to item.
        if item_size as f64 > mean_residual {
            nb -= 12.0;
        }
        score = nb + score * 0.1; // keep small dependence on raw residual
    } else {
        // Prefer bins whose residual deviates from the mean residual in a
        // "consolidating" direction (place into below-average-residual bins
        // to keep some bins large for future items).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 10.0 * dev;
        // Congestion: many open bins => push toward filling existing ones.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals become more valuable (harder to fill later).
    let norm_post = post / cap;
    score += (norm_post * norm_post) * (1.0 + 3.0 * progress) * 20.0;

    // Reward tight fits (small post_residual relative to item size) more strongly over time.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (0.5 + 2.0 * progress) * 10.0;

    // Penalize residuals that are too small to be useful (dead space), quadratic in progress.
    if post < item_size as f64 {
        score += (1.0 - post / (item_size as f64)) * (5.0 + 15.0 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large or the stream is early and mean residual is small.
    if bin_residual == bin_capacity {
        let rel_item = item_size as f64 / cap;
        let new_bin_bonus = rel_item * rel_item * 30.0 + (1.0 - progress) * 15.0 - (mean_residual / cap) * 20.0;
        score += 10.0 - new_bin_bonus;
    } else {
        // Prefer bins whose residual is above average (they still hold future items).
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post) / cap * 10.0;
    }

    // Mild congestion penalty: many open bins push toward consolidation.
    score += (open_bins_count as f64).ln() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 40.0 * tightness * tightness;

    // Harmonic class of post_residual: residual mod 10 buckets.
    let rmod = (post_residual % 10) as f64;
    score += 0.6 * rmod;

    // Penalize dead space that cannot fit the next item; reward if next item fits exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap_f);
            // Perfect chain: post_residual == next_item_size
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            score += 6.0 + 0.15 * (next_item_size as f64);
        }
    }

    // Integer-division threshold classes on post_residual.
    let div = post_residual / 25; // 0..4 class
    score += match div {
        0 => -6.0,          // nearly full bin, great
        1 => 0.0,
        2 => 2.0,
        3 => 5.0,
        _ => 3.0,           // nearly empty bin
    };

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: slightly discourage opening new bins unless residual is large
    // (wasteful) relative to item size.
    if bin_residual == bin_capacity {
        let frac = (item_size as f64) / cap_f;
        score += 10.0 - 12.0 * frac;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 4.0; // open bin could serve next item too
        }
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64) / cap_f;

    // Prefer bins already below mean residual (consolidate fullness).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 7.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose residual was large but now tight (good relative fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Dead space relative to capacity.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Open-bin pressure: encourage filling existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive if current bin leaves a bad gap
    // or no open bin fits well; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual || open_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Lookahead: favor leaving room for the next item if it fits the gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Two-step lookahead coupling: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if post_residual > next_item_size {
            // next item fits but leaves more waste; mild reward scaled by leftover
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 - chain_waste.min(30.0);
        } else {
            // next item cannot follow into this bin: penalize if dead space is small
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && gap < 10.0 {
                score += (10.0 - gap) * 2.0; // unusable sliver
            }
        }
    }

    // Compare against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early stream: be conservative, keep large residuals around
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Penalize leaving very small unusable residuals generally
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when all open bins are poor fits
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            // neutral-ish baseline; competing bins with tight fits will beat it
            score = bin_capacity as f64 * 0.8;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but avoid exact-zero
    // dead-space traps when the next item could use a small gap.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        // Fragment penalty: residuals below the minimum item size are dead space.
        score += 8.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Post-residual can't host the next item: mild penalty scaled by waste.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 6.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild pressure to consolidate into fewer bins as the stream grows.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * progress;

    // Slight bias against opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger residuals (keep flexibility); late, punish dead space harder
    let dead_space_penalty = 30.0 * progress * x * x + 20.0 * (1.0 - progress) * x * (1.0 - x);
    score += dead_space_penalty;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Reward bins below mean residual (compact bins), smooth coupling with progress
    let mr_norm = mean_residual / cap;
    score -= 8.0 * (mr_norm - x) * (1.0 + progress);

    // Lookahead: if next item fits exactly into post residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 15.0 * fit_quality * fit_quality * (0.5 + progress);
        } else {
            // next item won't fit here; mildly penalize leaving large residual
            score += 5.0 * x * x;
        }
    }

    // Slight preference for fewer open bins early (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * x;

    // New-bin candidate: make empty bin attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - x); // placeholder; x==1 for empty bin so effectively +10
        // penalize opening new bin when a decent fit exists elsewhere
        if pr < item_size as f64 * 0.5 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod 10 buckets. Small post residuals
    // (near 0) are great; residuals that are "dead" (1..=9 mod 10 with no
    // small item likely to fit) are penalized via a dead-space curve.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 20.0; // small leftover, likely fillable
    } else {
        // penalize mid-range dead space more than large usable space
        let cls = (pr % 10) as f64;
        let dec = (pr / 10) as f64;
        score += cls * 0.8 - dec * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - pr) as f64;
            score += 8.0 * (miss / 100.0).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // and current bins are fragmented (high mean residual relative to item).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 30.0 - 40.0 * fragmentation;
        if item_size > 60 {
            score -= 15.0; // big items fine in fresh bins
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // room for lookahead in fresh bin
        }
    }

    // Tight fit reward: filling a bin to >= 90% is excellent.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill >= 0.9 {
        score -= 18.0 * (fill - 0.9);
    }

    // Mild stream-phase modulation: early on, prefer consolidation;
    // late, prefer tight fits (already covered) and discourage bin sprawl.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for any plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual)
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post_residual blocks the next item
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Progress-based pressure: later in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, more when many bins are open
        score += 15.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler target
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)) * (post_residual as f64 / bin_capacity as f64);
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0; // perfect 2-step match
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Penalize unusable dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item matches a fresh bin well and current fits are wasteful, allow it.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() < 5
            && post_residual as f64 > mean_residual + 20.0 {
            score -= 25.0;
        }
    }

    // Early stream: consolidate into few bins.
    if open_bins_count > 1 && (step_index as f64) / (total_items.max(1) as f64) < 0.3 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any item (min size 1) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect closure is excellent
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual likely wasted relative to lookahead item.
        score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins mildly; relax penalty as bins fill up / stream progresses.
        score += 45.0 - 35.0 * pressure - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild preference to spread load when many open bins have large residuals.
    if bin_residual as f64 > mean_residual + 20.0 && open_bins_count > 1 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap; // fill fraction after placement
    let mut score = pr;

    // Smooth non-linear reward for tight fits (quartic fill coupling)
    score -= 40.0 * fill.powi(4);

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate slack; late in stream punish dead space quadratically
    let t = progress;
    score += 30.0 * (pr / cap).powi(2) * (0.5 + 0.5 * t);

    // Penalize wasted space that could hold the lookahead item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr / (next_item_size as f64 + pr));
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Mild pressure to close out stream with fewer open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // Prefer bins whose residual deviates favorably from the mean
    score -= 5.0 * ((mean_residual - pr) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins with residual divisible into
    // small common denominators are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                bonus += 8.0;
            }
        }
        score -= bonus;
    } else {
        // Perfect fit: strongly rewarded.
        score -= 100.0;
    }

    // Dead space penalty: residuals that few plausible item sizes can use.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.1;
        } else {
            // Post residual cannot host the next item: penalize proportional waste.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are heavily loaded
    // and the current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) < 15.0;
        if poor_fit && mean_residual < 20.0 {
            score -= 20.0 * (0.3 + progress);
        } else {
            score += 25.0;
        }
    }

    // Mild preference to fill already-open bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "unusable" if it cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead gap: severe penalty
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // small risky gap
    }

    // Reward tight fits (small post_residual) beyond the linear baseline.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 20.0; // chain fit closes the bin nicely
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0; // next item won't fit here and gap is dead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: add pressure so it only wins when fits are terrible.
        score += 10.0 + pressure;
    } else {
        score -= pressure * 0.1;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers creating fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly fits the next item (2-step lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward when next item fits in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    }
    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer tight fits: small post_residual relative to item size.
    score -= 8.0 * (item_size as f64) / (bin_capacity as f64);

    // Compare against mean residual: filling below-mean-residual bins is good.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Encourage consolidation when many bins are open.
    score -= 0.5 * (open_bins_count as f64) * (item_size as f64) / (bin_capacity as f64);

    // New-bin candidate: prefer it only when the item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 70 {
            score -= 15.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Late-stream tie-breaking: slightly prefer tighter residual as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by relative fill.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Penalize dead space that no future item (min size 1..~) can use effectively.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny slivers are near-useless
    } else if post_residual >= 10 && post_residual < 25 {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item won't fit here; slight penalty for blocking
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Crowding: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Mean residual coupling: if this bin is far below mean residual (i.e. tighter),
    // it's a good target; penalize bins far above mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate handling: empty bin gets a mild exploration bonus early,
    // but is discouraged late in the stream when consolidation matters more.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress - 3.0 * (next_item_size as f64 / 100.0);
    }

    // Late stream: be extra greedy about residual.
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste-aware residual
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, larger residuals are fine (bins stay flexible); late, we
    // punish leftover space quadratically since future chances are fewer.
    let prn = pr / cap; // normalized post residual in [0,1]
    let w_early = 1.0 - progress;
    let w_late = progress;
    let poly = prn * prn * (1.0 - prn); // peaks mid-range residual
    score += 30.0 * w_late * prn * prn;
    score -= 12.0 * w_early * poly;

    // Reward tight fits (small post residual) smoothly.
    score -= 20.0 * (-prn * 6.0).exp();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * w_late;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (ni / cap);
        } else {
            score += 5.0 * ((ni - pr) / cap) * ((ni - pr) / cap);
        }
    }

    // Slight pull toward bins near the mean residual (keeps balance smooth).
    score += 0.05 * (pr - mean_residual).abs() / cap;

    // Mild penalty for proliferating open bins when residuals are large.
    score += 0.01 * (open_bins_count as f64) * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight-fit reward: quadratic in fill ratio.
    let fill = item_size as f64 / cap;
    score -= 40.0 * fill * fill;

    // Dead-space penalty: small post_residual that cannot hold typical
    // future items (harmonic classes of residual modulo capacity quarters).
    let pr = post_residual;
    let usable = if pr >= 80 { 3 } else if pr >= 50 { 2 } else if pr >= 20 { 1 } else { 0 };
    score -= 12.0 * usable as f64;

    // Harmonic class penalty: residuals in awkward bands (1..=9) are dead space.
    if pr >= 1 && pr <= 9 {
        score += 30.0;
    }
    // Modulo-class coupling: residual congruent to small classes are harder to fill.
    if pr % 10 != 0 && pr < 20 {
        score += 8.0;
    }

    // Last-chance bonus: only bin that fits -> strong preference.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0;
        } else if next_item_size <= pr {
            score -= 15.0;
        } else {
            // next item won't fit here; mild penalty for wasting capacity
            score += 5.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large / many bins open (spread load).
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let mean_gap = mean_residual - (item_size as f64);
        // If mean residual across open bins is small, new bin is fine.
        score = 25.0 + 0.5 * mean_gap.max(0.0) + open_f * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score += 20.0; // next item won't fit after this placement anyway
        }
        if fitting_bins_count == 1 {
            score += 100.0; // never prefer new bin when it's the only fit
        }
    }

    // Late-stream consolidation: as stream progresses, favor filling open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        // Fraction of capacity wasted after placement.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        // Dead space threshold: gaps below ~10% of capacity are nearly unusable
        // for typical items (sizes 1..100 unknown distribution, but small gaps
        // rarely match). Apply a superlinear penalty there.
        let dead_threshold = bin_capacity as f64 * 0.10;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
        // Mild superlinear waste term for medium gaps.
        score += waste_frac * waste_frac * 20.0;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to the bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and this is an existing bin; the new-bin candidate (residual == capacity)
    // gets penalized for spreading items across too many bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // but relax pressure as the stream progresses (early consolidation
        // matters most).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) * (1.6 - progress);
        score += pressure.max(0.0) * 4.0;
        // Extra penalty if other bins can also fit the item.
        if fitting_bins_count >= 1 {
            score += 8.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it before opening a new bin.
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves another gap: mild reward scaled by fit tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
            score -= tight * 12.0;
        } else {
            // Next item won't fit in the gap: penalize if the gap is small dead space.
            if (post_residual as f64) < bin_capacity as f64 * 0.10 {
                score += 10.0;
            }
        }
    }

    // Prefer bins whose residual is below the mean residual (consolidating
    // nearly-full bins), keeping large-residual bins flexible for big items.
    if bin_residual == bin_capacity {
        // new bin: neutral w.r.t. mean residual
    } else {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff.min(50.0) * 0.5;
        } else {
            score += (-diff).min(50.0) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills remainder
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item does NOT fit in this bin's residual: penalize wasted pairing potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(80.0) * 1.5;
        }
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let base_penalty = 150.0;
        // large items justify a fresh bin more than small ones
        let size_relief = (item_size as f64 / bin_capacity as f64) * 140.0;
        score += base_penalty - size_relief;
        // late in the stream, prefer closing out existing bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 60.0;
        }
    }

    // Slight preference for filling bins with larger residual when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.35 * fill * fill);

    // Smooth coupling of residual quality with stream progress:
    // late in the stream, tight fits matter more (dead space penalized harder)
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * pr_norm * pr_norm * 40.0;

    // Reward near-perfect fits smoothly
    let tightness = 1.0 - (pr_norm - 0.05).abs() * 4.0;
    if tightness > 0.0 {
        score -= tightness * tightness * 12.0;
    }

    // Last-chance bonus (smooth, not hard switch)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 0.5 * late);
    }

    // Lookahead: bonus if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let chain = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * chain;
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Penalize bins far below mean residual (fragmenting outliers), smooth coupling
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference to spread load across bins early (keep residuals balanced)
    score += 0.02 * (open_bins_count as f64) * fill;

    // New-bin candidate: moderate default so poor fits in open bins win
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste is nonlinear; small residuals
    // (dead space) are penalized super-linearly, larger usable residuals less so.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,
        1..=5 => -6.0,
        6..=10 => 2.0,
        11..=20 => 6.0,
        21..=35 => 10.0,
        36..=50 => 13.0,
        _ => 16.0,
    };
    score += class;

    // Modulo / divisibility structure: residuals that are multiples of common
    // item sizes are more likely reusable.
    let reusable = ((pr % 10 == 0) as f64) * 4.0
        + ((pr % 20 == 0) as f64) * 3.0
        + ((pr % 5 == 0 && pr > 0) as f64) * 1.5;
    score -= reusable;

    // Lookahead: strongly reward exact fit of the next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 8.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual: small penalty if residual tiny
            score += (pr as f64 / cap) * 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current item is large or
    // all open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual.saturating_sub(item_size)) >= 0;
        let pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            (mean_residual / cap).clamp(0.0, 1.0)
        };
        // Prefer new bin when open bins are fragmented (high mean residual
        // relative to item size) or late in the stream.
        score = 45.0
            + 25.0 * (1.0 - pressure)
            + 15.0 * progress
            - (if tight_fit_exists { 0.0 } else { 20.0 });
        // Large items pack cleanly into fresh bins.
        if item_size >= 50 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Mild global pressure: many open bins -> favor filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Slight tie-break noise-free determinism: prefer bins with residual
    // closest to item size (best fit flavor) via fractional term.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    let min_item = 1.0f64;
    if post_residual > 0 {
        if (post_residual as f64) < min_item {
            score += 500.0; // impossible gap -> worst dead space
        }
        // Non-linear penalty for gaps too small for typical items
        if post_residual < 20 {
            score += (20 - post_residual) as f64 * 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 200.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, encourage filling
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(3.0);
    score += pressure * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 250.0;
    }
    // If next item fits in post_residual, mild reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }
    // If next item does NOT fit in post_residual, penalize wasting space
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins with residual below mean (fill fuller bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // New-bin candidate handling: neutral-ish, only chosen if fits are bad
    if bin_residual == bin_capacity {
        score += 60.0 + pressure * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is disproportionately bad).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall.
            let short = (next_item_size - post_residual) as f64;
            score += 60.0 * (short / 100.0).min(1.0);
        }
    }

    // Compare post residual against mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 250.0; // default penalty for opening a new bin
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair > bin_capacity {
                // Item + next item cannot share a bin anyway; a fresh bin is fine.
                score -= 200.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for filling fuller bins.
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to hold a typical future item,
    // but only when it cannot pair with the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good pairing potential: reward residual that exactly or closely fits next item.
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        } else if post_residual > 0 && post_residual < 10 {
            // Tiny unusable sliver: hard penalty.
            score += 30.0;
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is attractive early or when open bins are crowded,
    // but penalize opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
        score += 12.0 - 8.0 * progress - crowd.min(6.0);
        // If the next item is large, a fresh bin keeps flexibility.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Mild preference for reusing bins with residuals near the mean (keeps balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Fragmentation guard: penalize leaving residuals in the awkward 11..=19 band
    // (too small for most items, too big to ignore).
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    // Reward closing out bins nearly exactly as stream ends.
    if step_index + 2 >= total_items && post_residual < 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter packing (small post_residual) is rewarded more.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space quadratically, scaled by progress.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead * (0.3 + progress);

    // Interaction: post_residual vs mean residual deviation, smoothed.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Last-chance bin bonus (smoothly weighted by progress).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for opening new bins when many bins already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it decomposes modulo common item sizes
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that are "harmonically friendly": divisible into plausible future items
    // A post_residual that is an exact multiple of a common size class (e.g. 10,20,25,50) is reusable.
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit, best possible
    } else if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0 {
        18.0
    } else if pr % 5 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize dead space in awkward ranges (residual too small for any item 1..100 except tiny)
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr >= 10 && pr <= 15 {
        score += 8.0;
    }

    // Tightness: fraction of bin used by this placement
    let fill = (bin_capacity - pr) as f64 / cap;
    score -= 12.0 * fill * fill;

    // Lookahead coupling: does post_residual still fit next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            // prefer leaving exactly-fitting or harmonically divisible slack
            score -= 10.0 * (1.0 - slack / cap);
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize proportionally
            score += 14.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current residuals are large or item is huge
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / cap;
        // open a new bin if open bins are mostly full (low mean residual) or item is big
        let open_bias = if item_size >= 50 { 6.0 } else { 0.0 };
        score += 45.0 + 20.0 * pressure + 10.0 * progress - open_bias;
        if pr == 0 {
            score -= 5.0; // exact fill of a fresh bin (item == capacity) is great
        }
    } else {
        // mild preference for bins whose residual is below mean (consolidate fuller bins)
        let resid_frac = bin_residual as f64 / cap;
        score += 6.0 * (resid_frac - mean_residual / cap).abs().min(1.0);
    }

    // Integer-division threshold on post_residual: bins with residual in [0,9] are near-dead
    if pr / 10 == 0 && pr > 0 {
        score += 15.0;
    }

    // Late-stream consolidation: fewer open bins preferred as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing can fit into are heavily penalized.
    // Treat gaps below the typical small-item threshold (10) as pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual) more aggressively than plain best-fit.
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else {
        score -= 18.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);
    }

    // Penalize leaving a gap that exactly fails to fit the next item (near-dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64).powi(2);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty-bin call has a large residual and the mean residual is small).
    if bin_residual == bin_capacity {
        let openness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 * (1.0 - openness); // attractive when open bins are nearly full
        score -= 5.0 * openness;          // discourage hoarding new bins when space exists
    }

    // Mild alignment with mean residual: prefer bins close to the average fill state
    // to keep a balanced pool of medium gaps for future medium items.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to wasted potential
        score += 15.0 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Penalize small unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins tighter than average (best-fit style refinement)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in stream: mildly favor consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening new bins unless nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Mild penalty when many bins compete (encourage diversity of residuals).
        score += 0.6 * (fitting_bins_count as f64).min(8.0);
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize wasting a large residual.
        let waste = post_residual as f64;
        if waste > next_item_size as f64 + 20.0 {
            score += 0.25 * (waste - next_item_size as f64);
        }
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 40.0;
        // Cheaper to open new bin late in the stream or when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        score -= 0.4 * (open_bins_count as f64).min(20.0);
        // If mean residual is large, prefer existing bins.
        score += 0.15 * mean_residual;
        // If the only alternative is a single fitting bin, make new bin expensive.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    } else {
        // Existing bin: slight preference for bins with residual near item size
        // (best-fit style), scaled by mean residual for context.
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += 0.05 * diff;
        score -= 0.05 * mean_residual;
    }

    // Early stream: encourage keeping residuals balanced / larger for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = pr / cap;

    // Base: penalize wasted space, but the penalty grows super-linearly
    // for small residuals (dead space) as the stream progresses.
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - fit_frac) * (1.0 - fit_frac));

    // Smooth non-linear coupling: reward tight fits more strongly later in stream.
    score -= 12.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * (1.0 + progress);

    // Penalize bins whose residual deviates from the mean residual (imbalance),
    // with a smooth quadratic interaction scaled by progress.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            // next item won't fit: mild penalty for blocking, smooth in gap size
            let gap = (nxt - pr) / cap;
            score += 4.0 * gap * (1.0 - gap) * (0.5 + progress);
        }
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // current bins would leave very small residuals; smooth logistic gate.
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-8.0 * (fit_frac - 0.5)).exp());
        score = pr + 8.0 + 15.0 * gate * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create classes.
    let class = post_residual % 10;
    // Penalize dead space in "awkward" classes (residues that few items can fill).
    let awkward = match class {
        0 => -6.0, // perfectly full-ish bin, great
        1 | 2 | 3 => 8.0, // tiny slivers, likely dead space
        4 | 5 | 6 => 2.0,
        _ => 0.0,
    };
    score += awkward;

    // Integer-division threshold: residual in [0,10) is nearly perfect.
    if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit anywhere else either, keep slack.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here anyway; mild bonus for tight packing now
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for small items early in the stream (save big bins),
        // penalize when stream is nearly done or few bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 30.0 * tightness - 20.0 * progress - 2.0 * open_bins_count as f64;
        if next_item_size > item_size {
            score -= 10.0; // keep big bins free for bigger next item
        }
    }

    // Mean-residual coupling: if this bin is much tighter than average, favor it.
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small for the smallest
    // plausible item are "unusable". Penalize them harshly.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(10) {
        score += 40.0;
    }
    // Penalize small-but-nonzero dead space in a non-linear way.
    if post_residual > 0 && post_residual <= 15 {
        score += (16 - post_residual as i32 as f64) * 3.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 35.0;
        } else {
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow here: mild penalty proportional to waste.
        score += 5.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open,
    // but allow opening a new bin when few exist or current fits are bad.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.05;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when
    // existing residuals are poor (large mean residual spread / low fit).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 30.0 + pressure * 0.1;
        // If the item fits well nowhere else (few fitting bins) and mean
        // residual is small relative to item, a new bin is attractive.
        if fitting_bins_count <= 1 {
            new_bin_cost -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // Sequencing large items together: new bin keeps large items paired.
            new_bin_cost -= 8.0;
        }
        score = score.min(new_bin_cost + post_residual as f64);
    }

    // Mean-residual coupling: bins far below the mean residual are more
    // "spent" and should absorb items to consolidate waste.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
