        score -= 60.0 / (1.0 + diff as f64);
        // Penalize residual that is small but cannot fit the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when good open bins exist
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 30.0;
        }
        // open new bin more readily early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (waste-avoidance)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for high fill ratio
    score -= item_size as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; penalize wasting a good bin
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (explore)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later
        score += 15.0 * (1.0 - progress);
        // But if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
        score -= 8.0;
    } else if open_bins_count > 2 {
        score += 4.0;
    }

    // Prefer bins whose residual is close to mean (keep residuals homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_ratio = 1.0 - pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic) growth
    let mut score = pr + 0.35 * pr * pr / cap;

    // Smooth interaction: tight fits are rewarded more as stream progresses
    let tightness = fill_ratio * fill_ratio;
    score -= 6.0 * tightness * (0.5 + progress);

    // Penalize dead space that no typical item could use
    let small = if pr < 10.0 { 0.0 } else { pr };
    score += 0.05 * small * (1.0 - fill_ratio);

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when open bins are loose
    if bin_residual == bin_capacity {
        score += 3.0 + 0.25 * open_bins_count as f64 + 0.02 * mean_residual;
    }

    // Lookahead: reward bins whose post-residual still fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 4.0 * (1.0 - (pr - nxt).abs() / cap);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small divisors) are more valuable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit is always king
    } else if pr % 10 == 0 {
        -25.0 // leftover aligned to decimal grid is reusable
    } else if pr % 5 == 0 {
        -12.0
    } else if pr < 10 {
        30.0 // dead space: tiny unusable fragment
    } else {
        0.0
    };
    score += class_bonus;

    // Penalize dead space non-linearly: small leftovers are wasteful.
    if pr > 0 && pr < 15 {
        score += (15 - pr) as f64 * 2.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 20.0 + (pr - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty since bin becomes less useful
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to typical residuals or all open bins are tight.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { item_size as f64 / mean_residual } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin, discounted when open bins are congested.
        score = 70.0 + 30.0 * (1.0 - progress) - 25.0 * (pressure - 1.0).clamp(0.0, 2.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory
        }
    }

    // Mild preference for filling already-open bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Small tie-breaker: prefer bins with residual closest to item size (tight fit).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that the lookahead item can exactly use.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if leftover cannot fit the next item but bin stays open (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last chance: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins below mean residual (relatively emptier) slightly less.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when item is large relative to residual
    // or the current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        let tight_alternative = fitting_bins_count > 0 && (post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size));
        if tight_alternative {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Late in stream, be more conservative: keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: no dead space at all.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward tight chains: post_residual just above next_item_size is ideal.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * slack;
            // Exact chain fit is excellent.
            if post_residual == next_item_size {
                score -= 200.0;
            }
            // Reward combined packing: item + next item nearly fills the bin.
            let combined = (item_size + next_item_size) as f64;
            let fill_after = 1.0 - (bin_capacity as f64 - combined) / bin_capacity as f64;
            score -= 40.0 * fill_after;
        } else {
            // Next item won't fit here; penalize leaving awkward small residue.
            score += 25.0;
        }
    } else {
        // Last item: maximize fill.
        score -= 50.0;
    }

    // Penalize residues that are too small to ever be useful (dead space) —
    // nothing in [1,100] range likely fits except tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    // when the fit is good, to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New empty bin candidate: only attractive when no good fit exists
    // (i.e., item barely fits anywhere or many bins are open with poor residuals).
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64) / bin_capacity as f64;
        // Opening a new bin is cheap for large items, expensive for small ones.
        score -= 20.0 * tight_fit;
        // If several bins fit the item, discourage opening a new one.
        score += 12.0 * (fitting_bins_count as f64);
        // Early in the stream, opening bins is fine; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize large dead space: post_residual that can't fit typical items is wasted.
    if post_residual < 10 {
        score -= 15.0; // near-perfect closure
    } else if post_residual > 50 {
        score += 10.0; // leaving huge holes is bad
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when no
    // open bin fits well. Make the empty bin moderately attractive by default.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or when
        // open bins are congested (high mean residual usage).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = mean_residual / bin_capacity as f64;
        score += 25.0 - 15.0 * congestion - 10.0 * progress;
        // If lookahead item is small, a fresh bin pairs well (big + small).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Lookahead synergy: reward bins whose post_residual can host next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 4.0; // dead space for the known next item
        }
    }

    // Mild preference for bins below mean residual (keep a spread of capacities).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early stream: be slightly conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer bins with small post-residual (tight fit), scaled non-linearly.
    let mut score = post * (1.0 + 0.5 * fit_ratio * (1.0 - progress));

    // Penalize unusable dead space: small post_residual that cannot fit typical items.
    let dead = (1.0 - (post / cap).sqrt()).powi(2);
    score += 12.0 * dead * (0.5 + 0.5 * progress);

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    score += 8.0 * norm_post * norm_post * (1.0 - norm_post) * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // Mild preference to fill existing bins over opening new ones, stronger early.
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: make empty bins attractive only for large items or when
    // open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        let worth = fit_ratio * 0.5 + avg_fill * 0.5 + 0.3 * progress;
        score += (1.0 - worth.clamp(0.0, 1.0)) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zones" (1..=9, or unusable slivers) should be penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0 - (pr as f64); // tiny slivers are near-wasted space
    }

    // Reward residuals that are harmonic with the capacity (nice fractions).
    let cap = bin_capacity as f64;
    for k in 1..4u32 {
        let frac = cap * (k as f64) / 4.0;
        if (pr as f64 - frac).abs() < 0.5 {
            score -= 8.0;
        }
    }
    // Modulo-10 harmony: residuals divisible by 10 pair well with 10..80 items.
    if pr % 10 == 0 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // next item fits but leaves a new residual: evaluate its class
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 12.0;
            } else if pr2 < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot use this bin's residual: mild penalty
            score += 6.0;
            // unless residual is already tiny (irrelevant)
            if pr < 10 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 5 {
            score += 15.0; // near-perfect fill is fine, but don't over-reward
        }
    }

    // New-bin candidate handling: opening a bin should only win when no open
    // bin offers a decent fit. Make the empty bin attractive only if its
    // post-residual is harmonically clean and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // penalize new bin more as stream progresses and bins are usable
        score += 15.0 + 20.0 * progress + fragmentation * 0.1;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size >= bin_capacity - 5 {
            score -= 10.0; // next item nearly fills a fresh bin
        }
    }

    // Tight-fit reward: filling a bin almost exactly is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Slight preference for using fuller bins (smaller bin_residual).
    score += (bin_residual as f64) * 0.05;

    // Mean-residual coupling: prefer bins below mean residual (fuller than avg).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    // Integer-division threshold on post_residual classes
    let cls = pr / 20; // 0..5 harmonic class
    score += [0.0, -2.0, 0.0, 1.0, 2.0, 3.0][cls.min(5) as usize];

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A gap is "dead" if no plausible item (>= 1) can use it well; especially
    // penalize gaps smaller than a typical small item threshold.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Reward tight fits relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: when many bins are open, prefer consolidating into
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 + progress);

    // New-bin candidate: penalize slightly so it is only chosen when open bins
    // would create bad dead space or fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    }
    // If next item would NOT fit here but could fit elsewhere, mild penalty
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += (post_residual as f64 - next_item_size as f64).abs() * 0.1;
    }

    // Prefer bins whose residual is close to mean (balance residual distribution)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but penalize leftover after that placement too.
            score -= 100.0 - ((post_residual - next_item_size) as f64) * 2.0;
        } else {
            // Next item cannot use the remaining space: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize small unusable residuals (< 10, minimum item size) as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins with less residual (tighter bins)
    // but only mildly, so lookahead dominates.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid wasting it on
    // a large item that leaves big dead space; reward using it when tight fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 10 {
            score -= 150.0; // good use of last chance
        } else {
            score += 50.0; // discourage sloppy use of only fitting bin
        }
    }

    // New-bin candidate: neutral-ish baseline, only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Early in stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 80.0;
        // If next item is small, a fresh bin is more attractive (keeps flexibility).
        if next_item_size > 0 && next_item_size < 30 {
            score -= 60.0;
        }
    }

    // Mild penalty for too many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post residual to punish wasted space harder.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + slack * 0.1;
    }
    // If next item would NOT fit in post residual but fits a fresh bin, penalize slightly
    // when post residual is small dead space.
    else if next_item_size > post_residual && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins are open (fragmentation)
        // and early in the stream; mildly encouraged late when mean residual is low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 25.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        score += new_bin_penalty.max(5.0);
    } else {
        // Reusing an existing bin: reward when its residual is close to mean residual
        // (keep bins balanced) — subtract a small bonus.
        let balance = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();
        score -= 10.0 * (1.0 - balance.min(1.0));
    }

    // Exact fill bonus: perfectly closing a bin is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress:
    // tight fits (small post_residual) are rewarded increasingly as the stream advances.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + progress) * cap;
    score += 0.6 * coupling;

    // Reward tight fits via smooth decay of dead space
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 8.0 * tightness * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild penalty spread over many candidates to encourage consolidation
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if the next item fits the post residual, this is a great placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    } else if next_item_size > post_residual && post_residual > 0 {
        // penalize leaving dead space that the next item cannot use
        score += 5.0 * (next_item_size - post_residual) as f64 / cap;
    }

    // Penalize bins whose residual deviates from the mean residual (harmony term)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * (0.5 + progress);

    // Mild preference for filling already-open bins over opening new ones,
    // weakening late in the stream so fresh bins stay competitive.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // Smooth penalty for very small unusable residuals
    if post_residual > 0 && post_residual < item_size {
        score += 4.0 * (1.0 - pr / (item_size as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space non-linearly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Harmonic class of post_residual: residual mod 10 classes
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,                 // perfect decade residual: highly reusable
        1 | 9 => score -= 4.0,              // near-decade: decent
        5 => score -= 6.0,                  // half-decade: pairs with medium items
        2 | 3 | 4 | 6 | 7 | 8 => score += 5.0, // awkward classes: dead-space risk
        _ => {}
    }

    // Integer division thresholds on post_residual: small remnants are nearly dead
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }
    if post_residual <= 20 && post_residual >= 10 {
        score -= 8.0; // still usable for small items (sizes >= 1 allowed)
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or near-exact lookahead match is a jackpot
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 40.0;
            } else if slack < 10 {
                score -= 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize more if post_residual becomes dead
            if post_residual < next_item_size.min(80) {
                score += (post_residual as f64) * 0.3;
            }
        }
    } else {
        // last item: just minimize waste
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty unless residuals
    // across open bins are already tight (little room to maneuver)
    if bin_residual == bin_capacity {
        let tight = mean_residual < 15.0;
        if tight {
            score -= 10.0; // open bins nearly full: fresh bin is fine
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Mild pressure against bin proliferation as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual anchoring: prefer bins near the mean (keeps spread balanced)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are pure waste -> heavy penalty.
    let min_item = 1.0f64;
    let unusable = (post_residual as f64) < min_item;
    if unusable {
        score += 1000.0; // perfect fill is ideal, but ensure ordering below
    }

    // Reward tight fits: the smaller post_residual relative to bin capacity,
    // the better the utilization.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Penalize "awkward" gaps: post_residual that is nonzero but too small
    // for typical future items (dead space zone).
    if post_residual > 0 && post_residual < 25 {
        score += 40.0 + (25 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit
    // is loose; encourage consolidation.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement is very desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a good fit (post_residual small).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; scales with how many bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 10.0 * progress;
        // If current item leaves a good working residual in a fresh bin,
        // slightly reduce the cost.
        if item_size >= 50 {
            score -= 10.0;
        }
        // If open bins are nearly full on average, opening a new bin is fine.
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item leaves minimal waste.
    let perfect_fit = (post_residual == 0) as i32;
    score -= 50.0 * perfect_fit as f64;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Tight coupling: the closer post_residual is to next_item_size, the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.25 * slack;
        } else {
            // Dead space penalty if next item cannot fit in the leftover space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Compare post_residual relative to mean residual: penalize creating outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to capacity (large items pack better in fresh bins).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * frac;
    }

    // Late in the stream, consolidate: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * open_bins_count as f64;

    // Mild penalty for very small post_residual that isn't zero (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that is too small to be useful later (hard-to-fill slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: strongly reward bins where the next item also fits after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item nearly fills the remaining space.
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * chain_tightness;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that the known next item cannot use.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit into any open bin is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / bin_capacity as f64;
        // Base penalty for opening a new bin.
        score += 20.0;
        // But reward opening a new bin when mean residual is high (existing bins full)
        // or when no open bin fits well.
        score -= 25.0 * crowding;
        if fit_ratio < 0.5 && !is_new_bin {
            score -= 0.0; // unreachable guard, kept for clarity
        }
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            // Large items: fresh bin gives best long-term packing.
            score -= 10.0;
        }
    }

    // Mild preference for using bins with residual close to mean (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more conservative (prefer new bins
    // for structure); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Slight penalty per open bin to discourage bin proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post-residual with smooth non-linear shaping (quadratic waste penalty)
    let mut score = post * (1.0 + 0.004 * post);

    // Smooth coupling with stream progress: later in stream, waste matters more
    score *= 1.0 + 0.8 * progress * progress;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 12.0 * (1.0 - post / cap) * (0.5 + progress);

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly, but relax late in the stream or when
    // this bin would leave a large unusable remainder for the next item.
    if bin_residual == bin_capacity {
        score += 6.0 - 5.0 * progress;
    }

    // Lookahead: penalize if post-residual can't fit next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 3.0 + 4.0 * (nxt - post) / cap;
        } else {
            score -= 2.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 45.0 * tightness;

    // Harmonic class of post_residual: dead space in low residue classes is unusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 25.0; // small dead space, still usable for tiny items
    } else {
        // modulo classes: penalize awkward remainders
        let m = pr % 20;
        score += match m {
            0 => -15.0,
            1..=5 => 0.0,
            6..=12 => 6.0,
            _ => 12.0,
        } as f64;
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly-ish: reward
            let slack = pr - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / (pr as f64).max(1.0));
        } else {
            // next item won't fit: penalize proportionally to how far off
            score += 10.0 + 0.15 * (next_item_size - pr) as f64;
        }
    } else {
        // last item: just close bins tightly
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    // or are congested (many open bins, high mean residual).
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 55.0 - 40.0 * congestion - 8.0 * pressure;
        // never open a new bin for a tiny item
        score += 0.5 * item_size as f64;
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    } else {
        // Prefer fuller bins among open ones (best-fit bias beyond raw residual).
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 12.0 * fill;
        // mild penalty when many bins compete equally (keep diversity low)
        if fitting_bins_count > 4 {
            score += 4.0;
        }
    }

    // Late-stream consolidation: as stream progresses, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized
    // so we prefer bins that either fill exactly or leave a usable gap.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Reward perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage opening new bins when good alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Allow new bin only if no existing bin fits well (tight fit check).
        if fill_ratio > 0.5 && fitting_bins_count > 0 {
            score += 50.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it before opening a new one.
        score -= 45.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Dead space for the known next item: penalize.
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Mild preference for bins below mean residual (consolidate fuller bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight late-stream conservatism: prefer reusing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 45.0; // perfect 2-step match
        } else if post_residual as u32 > next_item_size {
            score -= 12.0 * (nxt / (post_residual as f64 + 1.0)); // next item fits
        } else {
            score += 8.0 + (nxt - post_residual as f64) * 0.3; // dead space relative to next item
        }
    } else {
        // last item: pure tightest fit
        score += 0.0;
    }

    // Penalize large unusable gaps (dead space below minimum plausible item size)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare against mean residual: placing into a tighter-than-average bin
    // keeps loose bins available for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: penalize opening a bin when other bins fit,
    // unless the item is large relative to residual (poor fits elsewhere).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + 5.0 * (open_bins_count as f64).sqrt();
        // allow new bin for large items that would leave big gaps elsewhere
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Slight preference to fill bins earlier in the stream (bin consolidation)
    score += 0.5 * (step_index as f64 / (total_items as f64).max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize residual that is likely dead space (too small for typical future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect two-item packing: current + next exactly fills the bin.
        if item_size as f64 + next_item_size as f64 == bin_residual as f64 {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless
    // current bins fit poorly or mean residual is too small for the item.
    if bin_residual == bin_capacity {
        let mean_fits = mean_residual >= item_size as f64;
        let any_fits = fitting_bins_count > 0;
        if any_fits && mean_fits {
            score += 35.0; // discourage opening when decent options exist
        } else {
            score -= 15.0; // encourage fresh bin when nothing fits well
        }
        // Early in the stream, opening bins is cheaper (more future to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate: prefer bins below mean residual (emptier bins
    // absorb items, keeping many tight bins for small future items).
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    }

    // Many open bins: favor filling existing ones over spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let fit = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 + t * t);
    score -= 30.0 * poly;

    // Penalize dead space that shrinks as stream progresses
    score += (1.0 - t) * 8.0 * (x * x);

    // Reward tight fits, more strongly later in the stream
    score -= (1.0 + t) * 20.0 * fit * (1.0 - x);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Lookahead: reward if next item fits the resulting residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - nx / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins vs mean residual
    score += 0.3 * ((open_bins_count as f64).ln() * (mean_residual / cap - x).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals in "usable" classes.
    // Class A: post_residual divisible by 10 (clean slots) -> strong reward.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 5 -> mild reward.
    else if post_residual % 5 == 0 {
        score -= 2.5;
    }
    // Small unusable dead space (post_residual < 10) -> penalize unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division threshold: residual "quanta" of size 10.
    let quanta = post_residual / 10;
    score -= quanta as f64 * 1.5;

    // Perfect fit is best.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: strong reward, scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.05 * slack;
            // Harmonic bonus: next item exactly fills a class boundary.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here: penalize more if we waste a lot.
            score += 2.0;
            if post_residual < 10 {
                score += 4.0; // bin becomes dead anyway
            }
        }
    } else {
        // Last item: prefer exact fill.
        if post_residual == 0 { score -= 10.0; }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: make it attractive only when item is large relative to
    // mean residual or open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 20.0 + item_size as f64 * 0.15 - congestion * 2.0 - progress * 3.0;
        // Harmonic: large items starting fresh bins is good.
        if item_size % 10 == 0 { score -= 2.0; }
        if item_size >= 50 { score -= 3.0; }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals that are too small to be useful later
    // (items are >= 1, but tiny gaps are hard to fill). Penalize gaps
    // that are small but nonzero more than large leftover space.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // unusable-dead-space penalty: strongest for small gaps
        let dead = ((bin_capacity as f64) * 0.25).min(pr);
        score += 3.0 * dead * (1.0 - pr / (bin_capacity as f64 + 1.0));
        // perfect fit reward
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Tight fit reward: fraction of bin filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= ni && (pr - ni) <= 5.0 {
            score -= 8.0;
        } else if pr < ni && pr > 0 {
            // gap too small for the next known item: extra dead-space penalty
            score += 4.0 * (1.0 - pr / (ni + 1.0));
        }
    }

    // Open-bin pressure: discourage spreading into many bins when mean
    // residual is already large; encourage using existing slack.
    if bin_residual != bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 10.0);
        score += pressure;
        // reward bins with residual near mean (balanced packing)
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * diff;
    } else {
        // New-bin candidate: penalize slightly so we only open when existing
        // fits are bad; scale with number of open bins.
        score += 6.0 + 0.5 * open_bins_count as f64;
        // but if no open bin fits well, opening is fine (handled by comparison)
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Stream progression: early on, be a bit more willing to open bins
    // (long horizon amortizes); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // matches the next item size (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect fit for the next item: strongly favor this bin.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits afterwards: mild reward proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit in the leftover: penalize dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    } else {
        // Last item: just prefer minimal post_residual (handled by base score).
        score += 0.0;
    }

    // Compare post_residual against mean residual of open bins.
    // Leaving more than average is wasteful; leaving less than average
    // concentrates waste compactly (good for future larger items).
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = C - item.
    // Prefer opening a new bin only when the best existing fit would leave
    // a lot of fragmented residual, or when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // New bin: neutral-ish baseline; make it attractive when many bins
        // are open and mean residual is low (existing bins nearly full).
        let openness = open_bins_count as f64;
        score -= 5.0 + 0.1 * openness * (1.0 - progress);
        // If next item is large and would not fit a fragmented leftover,
        // a fresh bin is safer.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Tiny tie-breaker toward tighter fills as the stream progresses.
    score += 0.05 * (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual non-linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item exactly fits the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item can't use leftover space; mild penalty for large leftovers.
            score += 4.0 * (post_residual as f64 / cap);
        }
    }

    // Prefer bins with below-mean residual (consolidate emptier space usage).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 10.0 * (open_bins_count as f64).ln() + 8.0 * progress;
    }

    // Time horizon: later in the stream, prefer tighter packing more aggressively.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * horizon * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: penalize leftover space, quadratically (dead space is costly).
    let mut score = post + 40.0 * post_norm * post_norm;

    // Smooth non-linear coupling of leftover with stream progress:
    // later in the stream, leftover space matters more (fewer chances to fill it).
    score += 60.0 * post_norm * post_norm * (progress * progress);

    // Reward tight fits (small post_residual) increasingly as stream advances.
    score -= 30.0 * (1.0 - post_norm) * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fill = nx / post.max(1.0);
            score -= 15.0 * fill * fill;
        } else {
            // Next item won't fit: leftover likely dead space; penalize smoothly.
            score += 12.0 * (1.0 - post / nx.max(1.0)).abs();
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (consolidate fullness) with smooth interaction.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 20.0 * dev * dev - 10.0 * dev * (1.0 - progress);

    // New-bin candidate handling: only attractive early or when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score += 18.0 * pressure * (1.0 - progress);
        score -= 10.0 * progress * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference to keep open bin count from exploding.
    score += 0.05 * open_bins_count as f64 * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: low residuals are "dead space"
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual in (0, 10] -> nearly dead space, strong penalty
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Class B: (10, 20]
    if post_residual > 10 && post_residual <= 20 {
        score += 10.0;
    }
    // Class C: (20, 35] moderately usable
    if post_residual > 20 && post_residual <= 35 {
        score += 3.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }
    // Quarter-class exact fits (residual divisible into harmonic fractions)
    if bin_capacity % 4 == 0 {
        let q = bin_capacity / 4;
        if post_residual % q == 0 && post_residual > 0 {
            score -= 2.0 * (post_residual as f64 / q as f64);
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, more if tight
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 0.1 * slack.min(30.0);
            // harmonic pair: next item exactly fills remainder
            if next_item_size == post_residual {
                score -= 20.0;
            }
            // modulo harmony: both sizes in same residue class mod 10
            if item_size % 10 == next_item_size % 10 {
                score -= 2.0;
            }
        } else {
            // next item won't fit here: mild penalty, worse if residual tiny
            score += 4.0;
            if post_residual < next_item_size / 2 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (post_residual already does this)
        score += 0.5 * (fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // as stream progresses / when current item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.75 + 20.0 * progress;
        // opening a new bin is attractive if item is huge and nothing fits well
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 5.0; // next item needs a fresh bin anyway, still fine
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - pr).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Gap is "dead" if too small for the smallest plausible item (<=10)
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0 * (20.0 - pr) / 10.0;
        }
        // Nonlinear coupling: dead space hurts more when bin is nearly full
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score += 0.5 * pr * pr / bin_capacity as f64 * (0.5 + fill_ratio);
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Prefer bins whose residual closely matches the item (tight packing)
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tight;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit and gap is small, penalize
    if next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; with few, allow
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: mildly penalized so it's chosen only over very poor fits
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: dead space if next item cannot fit post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // penalize unusable sliver relative to how big the waste is
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        } else {
            // reward chains where next item also fits
            let chain = (post_residual - next_item_size) as f64;
            score -= chain * 0.3;
        }
    }

    // Compare against mean residual: bins with residual near mean are more flexible
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * post_residual as f64;
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild preference for tighter bins overall
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Lookahead: if next item fits in post_residual, this is a great pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving awkward leftovers.
        score += 3.0 * (post_residual as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a bin unless residual is wasteful.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 10.0 - 10.0 * waste;
        // More open bins => prefer consolidating into existing bins.
        score += 0.4 * open_bins_count as f64;
    }

    // Global state: penalize bins deviating from mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: later in stream, prefer tighter packing (be pickier).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr_n = pr / cap;
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic waste penalty on post-residual, sharpened late in stream
    let mut score = pr_n * pr_n * (1.0 + 3.0 * progress * progress) * cap;

    // Reward tight fits (small post_residual) with smooth exponential coupling
    score -= (1.0 - pr_n).powf(4.0) * 20.0;

    // Coupling: post-residual usefulness vs lookahead item (smooth, non-linear)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = (nx - pr_n).abs();
        score -= 8.0 * (-usable * usable * 10.0).exp() * (1.0 - progress);
    }

    // Last-chance bonus: only one bin fits -> strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - fit_ratio);
    }

    // Penalize bins far below mean residual (fragmentation), smooth cubic
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * dev.abs().sqrt().max(0.0);

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * pr_n * 2.0;

    // Smooth new-bin preference: favor fresh bin early or when fit is poor
    let fresh = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += fresh * (-10.0 * fit_ratio * (1.0 + 2.0 * progress)) - fresh * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes modulo 10 are near-perfect fills; reward them.
    let pr = post_residual;
    let harmonic = (pr % 10) as f64;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0 - harmonic; // tiny dead space, very desirable
    } else {
        score += harmonic * 0.8; // penalize awkward residue classes
    }

    // Integer-division thresholds on post_residual: leftover buckets.
    if pr >= 50 {
        score += 8.0; // half-empty bin kept is wasteful unless new-bin case
    } else if pr >= 30 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr && (pr - next_item_size) <= 10 {
            score -= 15.0;
        } else if next_item_size > pr {
            // next item won't fit here; slight penalty for stranding space
            score += 2.0 + ((pr % 20) as f64) * 0.3;
        }
    }

    // Last-chance bin: only bin that fits the item — strong reward to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize it when good open options exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0
            - 15.0 * (mean_residual / bin_capacity as f64).min(1.0)
            - 10.0 * progress;
        if post_residual > 20 {
            score += 5.0; // would waste a fresh bin on a big item gap
        }
    }

    // Slight preference for tighter bins overall (close to mean residual).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Capacity-fraction bonus: item consuming a harmonic fraction of capacity.
    let frac = (item_size as f64) / (bin_capacity as f64);
    if (frac * 4.0).fract() < 1e-9 {
        score -= 4.0; // quarter-capacity classes pack harmonically
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small
    // to be usable by typical future items (unusable gap zone).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space of 1..9 is nearly worthless
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // small gap, partially usable
    }

    // Reward exact / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // creates a gap the next item cannot use
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill;

    // Open-bin pressure: discourage scattering across many open bins,
    // but never so strong that it forces bad fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (open_bins_count as f64) * (0.5 + 0.5 * (1.0 - progress));

    // Prefer bins whose residual is close to the item (good fit relative to average).
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs() * 0.1;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the
    // item is large or all open fits would leave heavy dead space.
    if bin_residual == bin_capacity {
        let dead_if_placed_open = fitting_bins_count > 0;
        let large_item = item_size > 60;
        if !dead_if_placed_open && !large_item {
            score += 55.0; // prefer existing bins for small/medium items
        } else {
            score -= 10.0; // large item or no alternative: opening fresh is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // Lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let match_err = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.8 * match_err;
        // Perfect lookahead match: strong bonus
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // If next item fits in post_residual, mild reward scaled by tightness
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Dead space penalty: next item cannot use this leftover
            score += 15.0;
        }
    }

    // Penalize bins far above mean residual (fragmented bins)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Reward using bins that are already quite full (avoid wasting open capacity)
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill;

    // Last-chance bin: strongly prefer it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current item is large relative to
    // capacity and no good fit exists; make empty bin mildly unattractive by default
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize large dead space, especially small dead spaces that are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // Perfect pair bonus: item + next item exactly fills this bin.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so late in the stream
    // or when other bins have plenty of room.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * progress + 0.3 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
    } else {
        // Favor bins whose residual is close to the global mean residual (balance load).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Mild preference for filling already-open bins when many are open.
    if bin_residual != bin_capacity {
        score -= 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let fit_ratio = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };

    let mut score = pr;

    // Non-linear waste penalty: dead space that is too small to fit typical items
    let dead = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 40.0 * dead * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 15.0 * (0.3 + 0.7 * progress);

    // Smooth coupling with mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: penalize leaving residual that neither fits next item nor is tiny
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = ((pr - nx).abs()) / cap;
        score += 8.0 * gap * gap;
        score -= 12.0 * fits_next * (nx / cap);
    }

    // Mild penalty for spreading across too many bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress) * item_norm;

    // New-bin candidate: opening a bin is penalized unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (1.0 - pr_norm) * fit_ratio * (0.5 + progress);
        // note: for the new-bin call itself pr_norm == 1, so this reduces to a fixed penalty
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into modulo buckets.
    let class = post_residual / 10;
    let rem = post_residual % 10;
    // Reward clean classes (residuals that are "harmonic" multiples of 10 are reusable),
    // penalize awkward leftovers in (0,10) which are near-dead space.
    if rem == 0 {
        score -= 6.0 + class as f64;
    } else {
        score += (10 - rem) as f64 * 0.8; // smaller leftover fraction -> worse
    }

    // Compatibility with the lookahead item (k=2): reward residuals that can host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + next_item_size as f64 * 0.15;
        } else {
            score += 4.0; // dead space for the next item
        }
        // Perfect pairing: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // (few fitting bins) or mean residual is small.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let crowding = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let pressure = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        score += 30.0 - 25.0 * crowding - 20.0 * pressure;
    } else {
        // Prefer fuller bins: tie-break toward minimal waste relative to capacity.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize tiny gaps much harder than large ones (non-linear)
        score += 30.0 * (1.0 - dead / bin_capacity as f64) * (1.0 - dead / bin_capacity as f64);
        // Hardest penalty for the smallest unusable slivers (< 10)
        if post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use this gap -> it is dead space for the future
            score += 8.0;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins
        score += 20.0 + 3.0 * open_bins_count as f64;
        // If other bins can fit the item, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Exception: if the item would leave a poor fit everywhere, new bin ok
        if post_residual >= item_size {
            score -= 5.0;
        }
    } else {
        // Mild reward for using existing bins, scaled by congestion
        score -= 2.0 + open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: bins far below mean residual are less valuable to fill;
    // prefer bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness * tightness;

    // Slight preference to fill older/more crowded bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a 2-step lookahead match: post_residual fits next item exactly.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect: item + next item fill the bin exactly.
            score -= 60.0;
        } else if diff > 0 {
            // Next item fits with leftover; reward proportional to closeness.
            let closeness = 1.0 - (diff as f64 / bin_capacity as f64);
            score -= 40.0 * closeness * closeness;
            // Penalize large unusable leftovers (dead space below min item size).
            if diff < 10 {
                score += 8.0;
            }
        } else {
            // Next item won't fit here; mild penalty for tight-but-not-matching fit.
            score += 3.0;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = if bin_residual > 0 {
        (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64
    } else {
        1.0
    };
    score -= 10.0 * tightness;

    // Penalize bins whose residual is far below the mean (fragmented bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (post_residual small) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = 12.0 * (open_bins_count as f64).ln();
        let best_fit_bonus = if post_residual as f64 <= mean_residual * 0.5 { 15.0 } else { 0.0 };
        score += 20.0 + open_penalty - 5.0 * progress - best_fit_bonus;
    }

    // Mild pressure to consolidate as the stream progresses.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting capacity planning.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 60.0;
        // If many bins are open with slack, discourage new bin.
        if open_bins_count > 0 {
            score += 10.0 * (mean_residual / bin_capacity as f64);
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins with below-average residual (more filled bins) to consolidate.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Mild pressure when many bins open: encourage filling existing ones.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: penalize leftover space, super-linearly (dead space is quadratic waste).
    let mut score = post * (1.0 + 0.015 * post / cap);

    // Reward high fill ratio smoothly.
    let fill = fit / cap;
    score -= 30.0 * fill * fill;

    // Smooth coupling: as the stream progresses, prefer tighter packing more strongly.
    let tightness = 1.0 - post / cap;
    score -= 25.0 * progress * tightness * tightness;

    // Penalize post-residual that could still fit the next item awkwardly:
    // if post_residual nearly equals next_item_size, reward (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 12.0 * (-gap / 10.0) * (-gap / 10.0); // smooth match bonus
        // Penalize leaving just-barely-too-small leftovers (worst dead space).
        let too_small = (post < nxt) as f64 * (1.0 - (nxt - post) / cap).max(0.0);
        score += 15.0 * too_small * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish base; penalize slightly less when open bins are crowded
    // or the fit into existing bins is poor (high post_residual relative to mean residual).
    score += is_new_bin * (8.0 + 0.05 * open_bins_count as f64 - 10.0 * progress);

    // Mild penalty for proliferating bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Nudge toward bins whose residual is near the current mean (balanced packing).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals divisible by common sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score += 60.0; // unusable dead space
    } else {
        // modulo classes: residuals divisible by 25/20/50 are reusable
        if pr % 25 == 0 { score -= 18.0; }
        if pr % 20 == 0 { score -= 12.0; }
        if pr % 50 == 0 { score -= 15.0; }
        if pr % 10 == 0 { score -= 6.0; }
        // odd residuals are awkward
        if pr % 2 == 1 { score += 5.0; }
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + (next_item_size as f64 / 10.0);
            // exact match class
            if pr % next_item_size == 0 { score -= 10.0; }
        } else {
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        score += 40.0 + 60.0 * (1.0 - tight) + 20.0 * (1.0 - progress);
    }

    // Prefer bins with less residual among equally good fits
    score += (bin_residual as f64) * 0.05;

    // Mild preference to fill bins when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is nearly unusable
    // (items >= 10), so penalize it heavily on top of the base.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    } else if post_residual > 9 && post_residual <= 19 {
        // Small gap: only usable by tiny items; mildly penalize.
        score += 10.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 9 {
            score -= 35.0;
        } else {
            score -= (slack as f64).min(30.0) * 0.3;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item.
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // already-fragmented bins; prefer consolidating into tight fits.
    let pressure = open_bins_count as f64;
    score += pressure * 0.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Mean-residual coupling: penalize bins whose residual deviates upward
    // from the mean (they are loose bins wasting space).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.4;

    // New-bin candidate: opening a fresh bin should only win when no open
    // bin offers a decent fit. Make the empty bin moderately unattractive.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 0.3;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Penalize residuals that are too small to ever be useful (dead space).
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }

        // Penalize opening a new bin when existing bins fit reasonably well.
        if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual >= next_item_size {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for filling early bins as the stream progresses.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item.
    if next_item_size > 0 && !is_new_bin {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Leftover too small for the next item: penalize proportionally to waste.
            score += 3.0 + 0.05 * post_residual as f64;
        }
        // If next item is large, prefer keeping big residuals intact.
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate logic: open a new bin only when existing bins are fragmented
    // (high mean residual relative to what this placement would leave) or late in stream
    // with many open bins.
    if is_new_bin {
        // Base reluctance to open new bins.
        score += 6.0;
        // If open bins are fragmented (mean residual high), a fresh bin is attractive.
        score -= (mean_residual - 25.0).max(0.0) * 0.6;
        // More open bins -> mild extra reluctance (consolidation preference).
        score += 0.3 * open_bins_count as f64;
        // Late in the stream, avoid spawning bins for marginal gains.
        score += 4.0 * t;
        // A new bin's leftover equals capacity - item; if item is large, this is a good deal.
        if item_size >= 70 {
            score -= 10.0;
        }
    } else {
        // Mild penalty for leaving large unusable chunks in existing bins.
        if post_residual > 30 {
            score += 0.08 * (post_residual - 30) as f64;
        }
    }

    // Global waste pressure scaled by stream progress.
    score += 4.0 * t * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear base: reward small post_residual (tight fit) with saturating polynomial
    let x = pr / cap;
    let base = x * x * (3.0 - 2.0 * x); // smoothstep: low when post_residual small

    // Stream-progress coupling: late in stream, punish wasted space more strongly
    let progress_coupling = base * (1.0 + 2.0 * progress * progress);

    // Dead-space penalty: residuals too small for likely future items
    let dead = if next_item_size > 0 && (post_residual as u32) < next_item_size {
        (next_item_size as f64 - pr) / cap
    } else {
        0.0
    };

    // Last-chance bonus: only bin that fits -> strong reward
    let last_chance = if fitting_bins_count == 1 { -3.0 } else { 0.0 };

    // Mild preference for keeping many bins consolidated
    let consolidation = 0.01 * open_bins_count as f64 * base;

    // New-bin candidate: neutral-ish score so poor fits in open bins lose to it
    let new_bin = if bin_residual == bin_capacity {
        1.5 + 0.5 * progress
    } else {
        0.0
    };

    base * 4.0 + progress_coupling * 2.0 + dead * 3.0 + last_chance + consolidation + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 and mod 25
    let pr = post_residual;
    let r10 = (pr % 10) as f64;
    let r25 = (pr % 25) as f64;

    // Penalize awkward residues (dead space unlikely to be filled by common item sizes)
    if r10 > 0.0 && r10 < 5.0 {
        score += (5.0 - r10) * 2.0;
    }
    if r25 > 0.0 && r25 < 10.0 {
        score += (10.0 - r25) * 1.5;
    }

    // Reward exact-fit-like placements
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 12.0;
    }

    // Harmonic fraction of the bin used
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 15.0;

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainability reward, stronger for tight chains
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - slack * 0.2;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) * (mean_residual / cap);
        score = 25.0 - crowding * 3.0;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild stream-phase adaptation: early on, be conservative about tight fits
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 3.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that no realistic future item (min size 1..=10) can use is waste.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Non-linear penalty on medium dead space that only tiny items could fill.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.35 + 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (using a bin with residual well below mean tightens the packing).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 1.5 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space the next item cannot use.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early on and
    // when other bins fit the item well.
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * progress + (fitting_bins_count as f64) * 2.0;
        if post_residual as f64 > 60.0 {
            score -= 5.0; // large leftover is reusable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize small post_residual less by normalizing against item size.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 0.5 * fit_ratio * (bin_residual as f64 - post_residual as f64);

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Slack after chaining the next item: smaller slack is better.
            let chain_slack = post - next;
            score -= 1.5 * (1.0 - chain_slack / bin_capacity as f64);
            // Exact chain fit bonus.
            if chain_slack == 0.0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot follow here; penalize proportionally to the gap.
            score += 0.75 * ((next - post) / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" and precious;
    // placing here when it's a near-perfect fit is extra valuable.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev / bin_capacity as f64;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // New-bin candidate: discourage opening a new bin unless current placement would be wasteful.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win; relax it when many bins are open
        // (consolidation pressure) or when the fit here would leave a large dead gap.
        let mut new_bin_penalty = 6.0;
        if next_item_size > 0 {
            let post = post_residual as f64;
            if next_item_size as f64 <= post {
                new_bin_penalty -= 1.0; // fresh bin chains nicely with next item
            }
        }
        if open_bins_count > 3 {
            new_bin_penalty -= 0.5 * (open_bins_count as f64 - 3.0).min(3.0);
        }
        score += new_bin_penalty;
    }

    // Slight late-stream tightening: prefer compact packing as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), with superlinear penalty on waste
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Very small dead space reward
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item won't fit here; penalize leaving awkward gap slightly
            score += (post_residual as f64) * 0.15;
        }
        // reward leaving gap close to next item size (near-perfect chain)
        let gap_diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= (1.0 - gap_diff / bin_capacity as f64) * 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many open bins: discourage spreading into large-residual bins when alternatives exist
    if fitting_bins_count > 1 {
        // prefer bins with residual close to item size among many candidates
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.3;
    }

    // Global state: if mean residual is high, prefer consuming from large-residual bins
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Time horizon: early in stream, be more liberal opening bins (low penalty); later, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        // opening a new bin costs more as many bins are open
        score += 30.0 + open_pressure * 2.0;
        // but if the item is large and current bins would leave big waste, allow it
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 0.6 * t * t + 0.4 * t * t * t;
    score *= poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 12.0 * (0.5 + t);

    // Penalize large dead space non-linearly
    score += norm_pr * norm_pr * 10.0 * (1.0 - t);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to prefer tighter alternatives
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead coupling: reward bins whose post_residual fits next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // Prefer bins with below-mean residual (tighter bins) smoothly
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 * (0.3 + 0.7 * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues divisible into
    // coarse buckets; small "dead" residues are the worst outcomes.
    let dead = (post_residual as f64 / (bin_capacity as f64 / 10.0)).floor() * 12.0;
    score += dead;

    // Perfect fit: post_residual exactly zero -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Integer-division threshold classes on post_residual.
    match post_residual / 10 {
        0 => score -= 10.0,          // tiny leftover, nearly perfect
        1 => score += 0.0,
        2 => score -= 3.0,           // 20-29 residual is a useful slot
        3 => score += 2.0,
        4 => score -= 5.0,           // 40-49 pairs with many item sizes
        5 => score += 1.0,
        6 => score -= 2.0,
        7 => score += 4.0,
        8 => score -= 1.0,
        9 => score += 6.0,
        _ => {}
    }

    // Lookahead: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic bonus scaled by how well next item fills the gap.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * fill_ratio;
        } else {
            // Gap unusable by next item: mild penalty, worse if gap is large.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when current fit is bad
    // (large dead space) or very few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = if post_residual > 40 { 1.0 } else { 0.0 };
        score += 45.0
            - 25.0 * bad_fit
            - 20.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);
        // Penalize opening a new bin when the next item is small enough
        // to be placed into a fresh bin together later anyway.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Tightness coupling: bins whose residual is close to item size are
    // "harmonic matches" - reward modulo-style closeness.
    let diff = bin_residual - item_size;
    if diff <= 10 {
        score -= (11 - diff as i32) as f64 * 1.5;
    }

    // Mean residual pressure: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are worse than moderate ones.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // small dead space (< min item size) is pure waste -> heavy penalty
        score += (10.0 - pr) * 4.0;
    }
    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Prefer bins whose residual was already small (tight packing)
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 6.0;

    // Pressure from number of open bins: discourage opening new bins
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 4.0;
    } else {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
    }

    // Late in stream, prefer closing bins tightly (avoid many near-empty bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.3;

    // Mild preference toward bins with below-mean residual (fill emptier ones less)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
