pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Penalize dead space that no realistic future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.6 + 15.0 * (1.0 - progress);
        if post_residual as f64 > mean_residual + 5.0 || fitting_bins_count == 0 {
            score -= 25.0; // no good existing option -> open new bin
        }
        if fitting_bins_count <= 1 {
            score += 60.0; // never open when it's the last chance
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 {
        let consolidation = ((post_residual as f64) - mean_residual).abs();
        score += 0.5 * consolidation;
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Mild time-horizon damping: early stream, be pickier about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Base: post-residual with non-linear penalty on awkward leftover sizes
    let mut score = pr as f64;
    score += 18.0 * (fit * (1.0 - fit)).powi(2) * cap; // penalize mid-range leftovers (hard to fill)

    // Stream-progress coupling: early on tolerate slack, late prefer tight fits
    let tightness = 1.0 - fit;
    score -= 12.0 * tightness * (progress * progress);
    score += 8.0 * fit * (1.0 - progress);

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 10.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowd control: many open bins -> prefer filling existing ones
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * fit;

    // Mean residual interaction: penalize deviating far from fleet average
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" class (divisible into common small item sizes) are favored.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit, best possible outcome
    } else if pr <= 10 {
        -12.0 // small dead space, nearly perfect
    } else if pr % 10 == 0 {
        -6.0 // leftover matches the classic size grid
    } else if pr % 5 == 0 {
        -3.0
    } else if pr >= 40 {
        -2.0 // large leftover still very reusable
    } else {
        4.0 // awkward mid-sized dead space
    };
    score += harmonic_bonus;

    // Tightness reward: relative fill of the bin by this item.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill;

    // Penalize leaving residual that neither fits the next item well nor
    // is tiny: wasted capacity.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as f64) >= nx {
            // next item could chain into this bin: reward modest leftovers
            score -= 3.0 * (1.0 - nx / cap);
        } else {
            // leftover too small for lookahead item: penalize proportionally
            score += 5.0 * (1.0 - (pr as f64) / nx.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty keeps open bins preferred unless they score badly.
        score += 18.0;
        // If many bins are open with large mean residual, reusing is cheap.
        score += 0.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is less costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * progress;
        // If the item is huge, a fresh bin gives a clean layout.
        if item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual (consolidating space).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: residuals below the minimum item size are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 / (1.0 + tightness);

    // Reward perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: bonus if the next item fits exactly into the resulting residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            score += 10.0; // next item won't fit here; mild penalty
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but encourage using existing bins when many are open.
    let pressure = open_bins_count as f64 / 10.0;
    score -= pressure * (bin_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // penalize wasting space in bins with large residuals.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    // New-bin candidate handling: opening a new bin is expensive early (few open bins),
    // but acceptable late or when this bin would leave large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 - 30.0 * progress + open_bins_count as f64 * 2.0;
        // If the item would leave a tiny unusable gap in any bin, opening new is less bad.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    }
    // Next item fits into post_residual: mild reward proportional to tightness.
    if next_item_size > 0 && next_item_size < post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit in the leftover: penalize small dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 40.0 * (1.0 - dead / bin_capacity as f64) * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is already below average (tighter bins first).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Early in the stream, keep bins consolidated; late, avoid tiny leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize very small unusable leftovers (dead space) generally.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward near-perfect packing
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize leaving residuals that no typical item can use (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here anyway; slight penalty for wasted pairing
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when few open bins can fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { fitting_bins_count as f64 };
        // Penalize opening a new bin when alternatives exist
        score += 30.0 / pressure;
        // But allow new bin when mean residual across open bins is very low (all full)
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        // Late in stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Encourage spreading load when many bins open with high mean residual
    if !is_new_bin && mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += rel * 6.0;
    }

    // Mild preference for filling emptier bins early
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr - 0.5 * progress * progress);

    let mut score = poly * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (cap - pr) / cap * (10.0 + 20.0 * progress);

    // Penalize bins that are the only fitting bin (last chance) slightly less
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Penalize creating dead space below typical item sizes
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (1.0 + progress);
    }

    // New-bin candidate: mild penalty so it's chosen only when open fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress + 0.5 * mean_residual * 0.1;
    }

    // Slight penalty for too many open bins relative to mean residual usage
    score += (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "unreachable" residue classes (small slivers that few item sizes can fill).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual below the minimum useful item size is pure loss.
    if post_residual > 0 {
        let sliver = if post_residual < 10 { 3.0 } else { 0.0 };
        score += sliver;
    }

    // Perfect fit reward: harmonic class 0 mod (capacity/4) residuals are highly reusable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 1000.0; // exact fill, ideal
    } else if post_residual % quarter == 0 {
        score -= 60.0;   // quarter-aligned residual: many sizes fit exactly
    } else if post_residual % (bin_capacity / 10) == 0 {
        score -= 25.0;   // decile-aligned residual
    } else if post_residual > half {
        score -= 15.0;   // large residual is generally good
    }

    // Penalize residuals in awkward classes: pr in (0,20) exclusive is hard to fill.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - pr / 20.0);
    }

    // Lookahead coupling: if the next item fits the post_residual exactly or
    // into a harmonic class, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let chain = post_residual - next_item_size;
            score -= 30.0;
            if chain % quarter == 0 {
                score -= 40.0;
            }
            if chain < 10 {
                score += 25.0; // chaining creates a tiny sliver
            }
        } else {
            // next item cannot follow here; slightly penalize wasting tight space
            if post_residual < 25 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // leaves a harmonically clean residual (e.g. item is a divisor-aligned size)
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        if post_residual % 10 == 0 {
            score -= 45.0; // clean residual class, opening a new bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 1000.0; // forced open
        }
    }

    // Mild pressure to consolidate bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.5 * progress * (open_bins_count as f64).ln().max(0.0);

    // Small tie-breaker toward bins tighter than average.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    // or would create dead space; otherwise keep it slightly worse than good fits.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer bins with tighter residuals (waste-minimizing tie-break).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight stream-progression pressure to consolidate early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 80.0 - slack * 0.5; // tighter chaining gets bigger bonus
        if post_residual == next_item_size {
            score -= 400.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item, scaled by dead-space size.
        let dead = post_residual.min(next_item_size - 1) as f64;
        score += dead * 0.8;
    }

    // Penalize residuals too small for any future item (min size 1..100 unknown, assume >=10 typical).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer bins with below-average residual (tighter bins first), leaving roomier bins flexible.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make it moderately attractive only when no good fit exists
    // (i.e., all fits would leave large dead space) and the stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let best_possible = if next_item_size > 0 { 0.0 } else { 0.0 };
        let _ = best_possible;
        // Base penalty so open bins with decent fits win; reduce penalty late in stream.
        score = 60.0 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 30.0; // fresh bin can chain the next item too
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    }

    // Mild bonus for filling many-item bins when bin count is high.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powf(3.0);

    // Perfect / near-perfect fills are gold.
    if post_residual == 0 { score -= 100.0; }
    else if post_residual < 10 { score -= 50.0; }

    // Lookahead: penalize leaving a residual that cannot host the next item
    // (dead space), unless the next item would fit even better here than there.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to lookahead, scaled by how big the orphan is.
            score += 0.8 * next_item_size as f64 * (1.0 - progress * 0.3);
        } else {
            // Bonus if this bin can also host the next item (chain packing).
            score -= 12.0 + 0.1 * next_item_size as f64;
            // Extra reward if the chained pair nearly fills the bin.
            let chain = item_size as f64 + next_item_size as f64;
            if chain >= bin_capacity as f64 { score -= 40.0; }
            else { score -= 20.0 * (chain / bin_capacity as f64).powf(2.0); }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 15.0 * fill;
    }

    // Many open bins with high mean residual => prefer consolidating into
    // bins with below-average residual (drier bins), fight fragmentation.
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
        // When many bins are open, tighten the penalty on wasteful placements.
        score += 0.05 * open_bins_count as f64 * post_residual as f64 / bin_capacity as f64;
    }

    // New-bin candidate: default mild penalty so we only open when existing
    // fits are genuinely poor; relax late in the stream or when existing
    // placements would strand large residuals.
    if is_new_bin {
        score += 18.0 - 10.0 * progress;
        if fitting_bins_count > 0 {
            // Only attractive if the best existing fit would leave big dead space.
            score += 0.6 * mean_residual.min(bin_capacity as f64);
        }
        // Opening a bin is cheaper when few bins are open (spread risk).
        if open_bins_count <= 2 { score -= 10.0; }
    }

    // Mild time-horizon modulation: early on, be slightly greedy for tight
    // fits; late, favor keeping flexibility (larger residuals).
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_gain = norm_pr * (1.0 + 2.0 * t * (1.0 - t) * 4.0);
    score -= progress_gain * cap * 0.35;

    // Penalize unusable dead space (residual too small for typical future items)
    let dead = (1.0 - norm_pr).powi(3);
    score += dead * cap * 0.5 * (0.5 + 0.5 * t);

    // Reward tight fits: low post_residual relative to item
    score -= (norm_item - norm_pr).abs() * cap * 0.2;

    // Lookahead coupling: reward residual that can fit the next item
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fits_next * norm_next * cap * 0.4;
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= cap * 0.3 * (1.0 - t * 0.5);
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 10.0 * t;

    // Pull toward mean residual: prefer bins with residual near the average
    score += ((mean_residual - pr) / cap).abs() * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let post_frac = post_residual as f64 / cap;
    score -= 60.0 * (1.0 - post_frac).powi(4);

    // Dead-space penalty for tiny unusable leftovers (harmonic classes).
    let cls = post_residual % 10;
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 25.0;
    }
    if cls == 0 && post_residual > 0 {
        score -= 5.0; // round leftovers stay reusable
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only good if the item
    // is large (fills a lot of a fresh bin) or nothing fits anywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / cap;
        // Penalize opening a bin; reward if item is big.
        score += 90.0;
        score -= 70.0 * fill_frac;
        // Encourage opening when current bins are very full on average.
        score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);
        // Slight encouragement late in the stream to consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    } else {
        // Prefer using existing bins, especially emptier ones.
        score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Lookahead: keep room for the next item if it fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Perfect pair: post residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 8.0; // blocks the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how poor current fits are.
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        let mut new_bin_score = 55.0 + open_bins_count as f64 * 2.0;
        // If existing bins would leave large dead space, opening a fresh bin is better.
        new_bin_score -= mean_gap * 0.8;
        // Lookahead: if next item matches the post-residual of this bin, avoid new bin.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 20.0;
            new_bin_score += 15.0;
        }
        // If next item would fit the new bin's full capacity nicely, mild bonus.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score);
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // (packing into below-average-residual bins keeps large gaps available).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item fits leaving small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to wasted lookahead.
        let gap = (next_item_size - post_residual) as f64;
        score += 15.0 * (gap / bin_capacity as f64).min(1.0);
    }

    // Prefer bins whose residual deviates below the mean (tighter bins get used first).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Penalize tiny unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless current bin is empty-ish
    // or the fit is very tight (post_residual small) — then it's a fine choice.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (post_residual as f64 / bin_capacity as f64);
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0; // empty bin still allows a perfect lookahead chain
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later (items >= 1).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 2.0 * (1.0 - dead / bin_capacity as f64).powi(3);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 4.0 * next_fit;
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            score += 1.5;
        }
    }

    // Prefer filling bins with large mean residual (consolidate slack).
    score -= 0.05 * mean_residual;

    // Mild pressure toward fewer open bins early; later, allow more bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.3 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 10.0 } else {
            // compare against worst-case waste of using an open bin
            (post_residual as f64) * 0.4
        };
        score = 100.0 - 20.0 * size_frac - desperation;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 30.0; // next item needs a fresh bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear reward for tight fits (small post_residual) with smooth saturation.
    let tightness = 1.0 - pr / cap;
    score -= 25.0 * tightness * tightness * tightness;

    // Penalize residuals that cannot plausibly host future items (dead space),
    // smoothly coupled with stream progress.
    let dead = ((pr - 10.0).max(0.0) / cap).powi(2);
    score += 12.0 * dead * (1.0 + progress);

    // Exact fill bonus, smoothed.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin when existing bins fit well,
    // with penalty decaying as open-bin residuals grow (fragmentation escape).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 + 15.0 * (1.0 - frag) + 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the resulting residual, reward it smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let fit_quality = 1.0 - slack / cap;
        score -= 15.0 * fit_quality * fit_quality;
    }

    // Mild pressure to consolidate bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear squashing
    let tightness = post_residual as f64 / cap_f;
    score += 12.0 * tightness * tightness;

    // Harmonic class of post_residual: residuals divisible by common item
    // granularity are more reusable. Modulo classes on 10-unit grid.
    let pr = post_residual;
    if pr > 0 {
        let mod10 = pr % 10;
        // Residuals aligned to the 10-grid are "usable" dead space
        score += (mod10 as f64) * 0.8;
        // Harmonic bonus: residual divisible by many small sizes
        let mut harmony = 0.0f64;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 { harmony += 1.0; }
        }
        score -= harmony * 2.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 6.0;
        if next_item_size == pr { score -= 8.0; }
        // partial match via integer division
        if pr / next_item_size.max(1) >= 2 { score -= 2.0; }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this residual: penalize large leftover
        score += 0.05 * (pr as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): should only win when no good fit exists
    if bin_residual == bin_capacity {
        // default: opening a new bin is costly
        score = cap_f + 20.0;
        // but if current bin would leave a very awkward residual, allow opening
        let awkward = (post_residual > 0 && post_residual < 10)
            || (next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size / 2);
        if awkward && fitting_bins_count >= 1 {
            score = cap_f - 8.0;
        }
        // early in stream, opening bins is cheaper
        if step_index < total_items / 10 {
            score -= 10.0;
        }
        // many open bins with slack: discourage another
        if open_bins_count as f64 > mean_residual / 5.0 {
            score += 10.0;
        }
    }

    // Mean-residual steering: prefer bins whose residual is below average
    // (pack full bins first, keep slack concentrated)
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Slight preference for filling bins that are already quite full
    let fill = 1.0 - (bin_residual as f64) / cap_f;
    score -= 4.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item are pure waste — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }
    // Moderately small gaps are also risky for future items.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many open bins,
    // pushing consolidation when many bins are active.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive when nothing fits well —
    // an empty bin has full residual but should lose unless the best
    // existing fit is poor.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * open_bins_count as f64;
        // If the next item is large, a fresh bin is less harmful.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Lookahead: if the residual left behind can host the next item,
    // this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Conversely, leaving a residual that just barely misses the next
    // item wastes the gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Late in the stream, prefer closing bins cleanly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
