pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 12.0 * (fill_ratio - 0.85);
    } else if fill_ratio < 0.4 {
        score += 6.0 * (0.4 - fill_ratio); // penalize wasteful placements
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 8.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Dead-space penalty: residual left behind that is too small for typical items.
    if post_residual > 0 && post_residual < 20 {
        score += 4.0 * (20 - post_residual) as f64 / 20.0;
    }

    // Lookahead coupling: reward if the leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // If next item fits exactly in the leftover, strong reward
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: prefer minimal leftover overall
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        score += 18.0;
        // If many bins are open with slack, discourage new bins.
        score += 0.4 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If mean residual across open bins is large, opening new is wasteful.
        score += 0.15 * mean_residual;
        // Exception: a big item that barely fits nowhere well justifies a fresh bin.
        if item_size > bin_capacity * 3 / 4 {
            score -= 14.0;
        }
    } else {
        // Slight preference for bins with residual close to the item (best-fit bias).
        score += 0.05 * (bin_residual as f64 - item_size as f64);
        // Prefer bins below the mean residual (tighter bins first) mildly.
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
        // Spread load: with many open bins, slightly favor filling tighter ones.
        score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Small time-horizon modulation: early stream, be more exploratory (favor new bins less penalized).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: penalize leftover dead space, with non-linear (quadratic) growth.
    let mut score = pr + (pr / cap) * (pr / cap) * 20.0;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - pr / (it + 1.0).max(cap);
    score -= tightness * 8.0;

    // Smooth stream-progress coupling: later in the stream, prefer filling
    // existing bins aggressively (avoid fragmentation at the tail).
    let late = progress * progress;
    score += late * (pr / cap) * 15.0;
    score -= late * tightness * 5.0;

    // Lookahead synergy: if the next item fits into the post residual, reward.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let nxt = next_item_size as f64;
        let fill_after = (pr - nxt) / cap;
        score -= 6.0 * (1.0 - fill_after);
    } else if next_item_size > 0 {
        // Post residual unusable by next item: mild penalty scaled by dead space.
        score += 3.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer the tightest, discourage wasting slack.
        score += (fitting_bins_count as f64).ln() * (pr / cap) * 4.0;
    }

    // New empty bin candidate: it is only attractive when no open bin gives a
    // decent fit (i.e., when post_residual here is small because item is huge),
    // or when open bins are nearly exhausted of slack.
    if bin_residual == bin_capacity {
        let slack_pressure = (mean_residual / cap).tanh();
        // Opening a bin costs ~one bin of slack; discount by how starved we are.
        score += 55.0 * (1.0 - slack_pressure);
        // Big items justify a fresh bin more than small ones.
        score -= (it / cap) * 12.0;
        // Early in the stream, opening bins is cheaper (room to consolidate later).
        score -= (1.0 - progress) * 10.0;
    } else {
        // Penalize bins whose residual deviates from the mean (keeps bin pool balanced).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += dev * dev * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how well it decomposes into
    // typical small-item denominations (capacity fractions).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: waste is proportional to unusable space, but small residuals
    // (harmonic classes 0..=10) are nearly perfect fits.
    if post_residual <= 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 25 {
        score -= 8.0;
    } else if post_residual <= 50 {
        score += 4.0;
    } else {
        score += 12.0;
    }

    // Modulo-10 class: residuals that are multiples of 10 pair naturally
    // with integer item sizes in [1,100].
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0;
    } else if class >= 5 {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post <= 10 {
                score -= 18.0;
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.15;
            }
        } else {
            // Next item won't fit here; penalize wasting a large residual on
            // a bin that will be closed anyway.
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open
    // bin offers a tight fit. Empty-bin call has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Reward keeping tight fits in existing bins: new bin should lose
        // unless the item leaves a very awkward residual elsewhere.
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // Few open bins -> new bin less costly.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Prefer bins with residual close to the item (tight fit) relative to
    // the mean residual across open bins.
    if mean_residual > 0.0 {
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= tightness * 5.0;
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Integer-division threshold: penalize residuals that can only host
    // items in an awkward mid-range (post_residual / 2 in 26..=40 zone).
    let half = post_residual / 2;
    if half > 25 && half < 41 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        // Small gaps that only fit tiny items are semi-dead space.
        score += 8.0 + (20 - post_residual) as f64 * 0.5;
    }

    // Reward tight fits (wasted fraction small) super-linearly.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_frac).powi(3) * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap < 10 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't fit here anyway; slight penalty if this bin is the
        // last chance for the current item (avoid forcing a new bin later).
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus per-open-bin pressure.
        score += 15.0 + open_bins_count as f64 * 4.0;
        // A new bin is acceptable if the item fits poorly everywhere
        // (large item leaving small dead space is fine in a fresh bin).
        if item_size >= 50 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); late in the stream, squeeze into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 12.0;
    } else {
        // Mild reward for using existing bins proportional to open-bin count.
        score -= open_bins_count as f64 * 0.3;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; prefer consuming fragmented bins first.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.4;
    } else {
        score += (-dev) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if post_residual >= next_item_size {
            // next item can also fit here: strong reward, tighter match is better
            score -= 200.0 - gap * 1.5;
        } else {
            // next item won't fit: penalize wasted residual relative to gap
            score += gap * 0.3;
        }
    }

    // Prefer bins with residual below mean (tight bins) to keep loose bins available
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // allow opening a new bin early in the stream when few bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
    }

    // Mild penalty for fragmenting large residual bins with small items
    if (post_residual as f64) > mean_residual * 1.5 && item_size < 30 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post_residual relative to capacity.
    let tightness = (post_residual as f64) / cap;
    score += 12.0 * tightness * tightness;

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item; penalize if next item fits
    // better in a fresh residual than what we leave behind.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item can chain into this bin: reward proportional to chain tightness
            let chain_fit = (post_residual as f64 - nxt) / cap;
            score -= 8.0 * (1.0 - chain_fit);
        } else {
            // we strand the next item: penalize proportionally to leftover waste
            score += 3.0 * (post_residual as f64 / cap);
        }
    }

    // Prefer bins below mean residual (consolidating emptier space) mildly,
    // but avoid dumping into very full bins when alternatives exist.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 2.0 * dev;
    }

    // New-bin candidate: neutral-ish score so it's chosen only when open-bin fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.55
            + 10.0 * tightness
            - (open_bins_count as f64) * 0.15;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: opening a bin is fine
        }
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 2.0;
        }
    }

    // Slight time drift: as stream progresses, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: waste after placement, normalized
    let mut score = post / cap;

    // Tight-fit reward: quadratic coupling of fill ratio
    let fill = item / cap;
    score -= 2.5 * fill * fill;

    // Smooth non-linear penalty for mid-range dead space (post_residual near 20-40 is least reusable)
    let dead = (post / cap - 0.3) * (post / cap - 0.3);
    score += 1.2 * dead * (1.0 - progress);

    // Stream progress coupling: later in stream, waste matters more
    score += 0.8 * progress * (post / cap);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 1.5 * snug * snug;
        } else {
            score += 0.6 * (nxt - post) / cap;
        }
    }

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Prefer bins below mean residual (keep large residuals available)
    score += 0.4 * (residual - mean_residual) / cap;

    // New-bin candidate: penalize opening new bins, more so early and when alternatives exist
    if bin_residual == bin_capacity {
        let alt = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 1.0 + 0.5 * (1.0 - progress) + 0.3 * alt.ln().max(0.0);
        // But allow new bin if item is huge and would leave very tight fit elsewhere
        if item > 0.8 * cap {
            score -= 0.8;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space below half capacity is very bad
    if post_residual > 0 {
        let half = bin_capacity / 2;
        if post_residual < half {
            // small unusable gap -> penalize quadratically
            score += (half - post_residual) as f64 * 0.5;
        }
    }

    // Reward when the next item can exactly fill the post residual (chain fit)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it uses the gap
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize tight fits that strand the bin
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score is its full residual; add opening cost
        score += 50.0 + 10.0 * (open_bins_count as f64).sqrt();
    } else {
        // mild preference for tighter existing bins (best-fit core)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Late in stream: consolidation pressure — avoid leaving many open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps hard (dead space below min item size 1..100 => treat <20 as dead)
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    score += open_bins_count as f64 * 2.0;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // Lookahead: if next item almost fits (gap < 10), penalize slightly
    if next_item_size > post_residual && next_item_size > 0 && (next_item_size - post_residual) < 10 {
        score += 8.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when current fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
    }

    // Slight preference for tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits, but measure how tightly
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
        } else {
            // dead space: next item can't use the leftover
            score += 8.0 + 0.2 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual: avoid leaving bins far below average
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when a reasonably tight fit exists
    if bin_residual == bin_capacity && bin_capacity >= item_size {
        let tightness = (bin_capacity - item_size) as f64;
        score += 15.0 + 0.3 * tightness;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 10.0; // new bin would leave unusable space for next item too
        }
    }

    // Late in stream: push toward closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // Small penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - tightness * tightness);

    // Exact / near-exact fits get a big bonus.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 90.0;
    }

    // Lookahead coupling: prefer bins whose leftover pairs with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 50.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // leftover too small for the next item -> dead space penalty
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize creating unusable dead space relative to the minimum item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: opening a new bin is generally costly, but
    // attractive when current fits are poor (large post_residual everywhere).
    if bin_residual == bin_capacity {
        let new_bin_cost = 80.0 + 10.0 * open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Slightly cheaper to open bins early (more stream left to amortize).
        score = new_bin_cost * (1.0 + 0.5 * progress) + post_residual as f64;
        // If mean residual of open bins is small (all bins nearly full), a new
        // bin is reasonable.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 40.0;
    } else {
        // Mild penalty scaled by how many bins are open: prefer filling existing
        // bins when there are many.
        score += 0.3 * open_bins_count as f64;
    }

    // Prefer bins whose residual is far from the mean residual (diversity of
    // leftover sizes keeps future pairing options open).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress
    let t = progress;
    score += (x * x) * (100.0 + 60.0 * t);
    score -= (x * x * x) * (40.0 * t);
    score += (1.0 - t) * (x * (cap - pr as f64)) * 0.3;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0 * (1.0 - t);
    }

    // Penalize small post residual that next item cannot use
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * (0.5 + 0.5 * t);
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 * (1.0 - x);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0 * (1.0 - t);
    }

    // New-bin candidate handling: prefer opening new bin only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * (1.2 + 0.4 * t) + mean_residual * 0.2;
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 2.0 * tightness;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded,
    // small awkward residuals penalized via integer-division thresholds.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        // dead space too small for any item (min size 1..100, but small is bad)
        score += 8.0;
    } else if post_residual <= 20 {
        score += 4.0;
    }

    // Modulo-arithmetic class: residuals that are multiples of common size
    // bands (10s) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving large unusable residue
            score += 0.05 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's post_residual would be very wasteful or no tight option exists.
    if bin_residual == bin_capacity {
        // neutral baseline: score = capacity - item_size (its natural post_residual)
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // slight lookahead bonus for fresh bin
            score -= 2.0;
        }
        // discourage proliferation when many bins already open
        score += 0.5 * open_bins_count as f64;
    }

    // Progress-aware nudging: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * tightness;

    // Distance from mean residual: prefer bins whose residual is below mean
    // (fill the emptier-relative bins first to keep many small residuals? No —
    // prefer filling bins close to full, i.e. residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a gap too small for the next item (dead space guaranteed).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading into many bins.
    score += 2.5 * open_bins_count as f64;

    // Prefer bins with low residual relative to mean (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline, only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}
